SET default_tablespace = '';

SET default_table_access_method = heap;

--
-- Name: workspace_analysis_publication_proof; Type: TABLE; Schema: agent; Owner: -
--

CREATE TABLE agent.workspace_analysis_publication_proof (
    id uuid NOT NULL,
    workspace_id uuid NOT NULL,
    analysis_run_id uuid NOT NULL,
    answer_id uuid NOT NULL,
    workflow_run_id uuid NOT NULL,
    finalization_node_run_id uuid NOT NULL,
    finalization_node_attempt_id uuid NOT NULL,
    candidate_id uuid NOT NULL,
    candidate_hash text NOT NULL,
    git_receipt_id uuid,
    git_receipt_hash text,
    validation_receipt_id uuid NOT NULL,
    validation_receipt_hash text NOT NULL,
    review_model_result_id uuid NOT NULL,
    review_document_hash text NOT NULL,
    published_document bytea NOT NULL,
    published_result_hash text NOT NULL,
    published_bytes bigint NOT NULL,
    created_at timestamp with time zone NOT NULL,
    CONSTRAINT workspace_analysis_publication_git_pair CHECK (((git_receipt_id IS NULL) = (git_receipt_hash IS NULL))),
    CONSTRAINT workspace_analysis_publication_pr_validation_receipt_hash_check CHECK ((validation_receipt_hash ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT workspace_analysis_publication_proo_published_result_hash_check CHECK ((published_result_hash ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT workspace_analysis_publication_proof_candidate_hash_check CHECK ((candidate_hash ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT workspace_analysis_publication_proof_git_receipt_hash_check CHECK ((git_receipt_hash ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT workspace_analysis_publication_proof_integrity CHECK (((published_bytes = octet_length(published_document)) AND ((published_bytes >= 1) AND (published_bytes <= 262144)) AND (published_result_hash = encode(sha256(published_document), 'hex'::text)))),
    CONSTRAINT workspace_analysis_publication_proof_review_document_hash_check CHECK ((review_document_hash ~ '^[0-9a-f]{64}$'::text))
);


--
-- Name: validate_workspace_analysis_v2_publication_proof(agent.workspace_analysis_publication_proof); Type: FUNCTION; Schema: agent; Owner: -
--

CREATE FUNCTION agent.validate_workspace_analysis_v2_publication_proof(proof agent.workspace_analysis_publication_proof) RETURNS void
    LANGUAGE plpgsql
    AS $$
DECLARE
    analysis agent.workspace_analysis_run%ROWTYPE;
    runtime workflow.run%ROWTYPE; node workflow.node_run%ROWTYPE; attempt workflow.node_attempt%ROWTYPE;
    candidate agent.workspace_analysis_candidate%ROWTYPE;
    git_receipt workflow.tool_result_receipt%ROWTYPE; citation_receipt workflow.tool_result_receipt%ROWTYPE;
    review agent.workspace_analysis_model_result%ROWTYPE;
    latest_git_id uuid; latest_git_hash text;
    candidate_json jsonb; binding_json jsonb; published_json jsonb; expected_git jsonb:='null'::jsonb;
    expected_citations jsonb; expected_proposal jsonb; expected_document jsonb; git_json jsonb;
BEGIN
    SELECT * INTO runtime FROM workflow.run WHERE id=proof.workflow_run_id AND workspace_id=proof.workspace_id FOR UPDATE;
    SELECT * INTO node FROM workflow.node_run WHERE id=proof.finalization_node_run_id AND run_id=proof.workflow_run_id FOR UPDATE;
    SELECT * INTO attempt FROM workflow.node_attempt WHERE id=proof.finalization_node_attempt_id AND node_run_id=node.id FOR UPDATE;
    SELECT * INTO analysis FROM agent.workspace_analysis_run WHERE id=proof.analysis_run_id AND workspace_id=proof.workspace_id AND answer_id=proof.answer_id AND workflow_run_id=proof.workflow_run_id FOR UPDATE;
    SELECT * INTO candidate FROM agent.workspace_analysis_candidate WHERE id=proof.candidate_id AND analysis_run_id=analysis.id FOR SHARE;
    SELECT * INTO citation_receipt FROM workflow.tool_result_receipt WHERE id=proof.validation_receipt_id AND workspace_id=proof.workspace_id FOR SHARE;
    SELECT * INTO review FROM agent.workspace_analysis_model_result WHERE id=proof.review_model_result_id AND analysis_run_id=analysis.id FOR SHARE;
    SELECT result_id,result_hash INTO latest_git_id,latest_git_hash FROM agent.workspace_analysis_operation
        WHERE analysis_run_id=analysis.id AND node_key='decide_next' AND operation_kind='GIT_STATUS' AND status='SUCCEEDED' ORDER BY ordinal DESC LIMIT 1;
    IF proof.git_receipt_id IS NOT NULL THEN SELECT * INTO git_receipt FROM workflow.tool_result_receipt WHERE id=proof.git_receipt_id AND workspace_id=proof.workspace_id FOR SHARE; END IF;
    IF analysis.id IS NULL OR analysis.definition_version<>2 OR analysis.status<>'running' OR analysis.termination_reason IS NOT NULL
       OR runtime.id IS NULL OR runtime.status<>'running' OR runtime.cancel_requested_at IS NOT NULL
       OR node.id IS NULL OR node.node_key<>'review_publish' OR node.node_type<>'agent.workspace-analysis.v2.review_publish' OR node.status<>'running'
       OR attempt.id IS NULL OR attempt.status<>'running' OR node.attempt IS DISTINCT FROM attempt.attempt_no
       OR node.lease_owner IS NULL OR node.lease_owner='' OR node.lease_owner IS DISTINCT FROM btrim(node.lease_owner)
       OR node.lease_owner IS DISTINCT FROM attempt.lease_owner OR node.lease_until IS NULL OR node.lease_until IS DISTINCT FROM attempt.lease_until
       OR attempt.lease_until<=clock_timestamp() OR proof.created_at>clock_timestamp() OR proof.created_at<analysis.updated_at
       OR analysis.deadline_at<proof.created_at OR analysis.deadline_at<=clock_timestamp()
       OR candidate.id IS NULL OR candidate.answer_id<>proof.answer_id OR candidate.document_hash<>proof.candidate_hash OR candidate.schema_version<>2
       OR citation_receipt.id IS NULL OR citation_receipt.workflow_run_id<>proof.workflow_run_id OR citation_receipt.output_hash<>proof.validation_receipt_hash
       OR citation_receipt.tool_name<>'ValidateCitation' OR citation_receipt.tool_version<>4
       OR review.id IS NULL OR review.operation_kind<>'FAITHFULNESS_REVIEW' OR review.document_hash<>proof.review_document_hash
       OR review.subject_candidate_id IS DISTINCT FROM candidate.id OR review.subject_candidate_hash IS DISTINCT FROM candidate.document_hash
       OR NOT EXISTS (SELECT 1 FROM agent.workspace_analysis_operation WHERE id=review.operation_id AND analysis_run_id=analysis.id
            AND node_run_id=node.id AND result_id=review.id AND result_hash=review.document_hash AND status='SUCCEEDED')
       OR proof.git_receipt_id IS DISTINCT FROM latest_git_id OR proof.git_receipt_hash IS DISTINCT FROM latest_git_hash
       OR (proof.git_receipt_id IS NOT NULL AND (git_receipt.id IS NULL OR git_receipt.output_hash<>proof.git_receipt_hash
            OR git_receipt.tool_name<>'ReadGitStatus' OR git_receipt.tool_version<>3 OR git_receipt.workflow_run_id<>proof.workflow_run_id))
       OR proof.created_at<candidate.created_at OR proof.created_at<citation_receipt.created_at OR proof.created_at<review.created_at
       OR (git_receipt.id IS NOT NULL AND proof.created_at<git_receipt.created_at)
       OR EXISTS (SELECT 1 FROM agent.workspace_analysis_operation WHERE analysis_run_id=analysis.id AND updated_at>proof.created_at) THEN
        RAISE EXCEPTION 'dynamic workspace analysis publication fence or authority binding is invalid' USING ERRCODE='55000';
    END IF;
    PERFORM agent.verify_workspace_analysis_v2_success_facts(analysis,citation_receipt.id,review.model_run_id);
    candidate_json:=convert_from(candidate.document,'UTF8')::jsonb;
    binding_json:=convert_from(citation_receipt.server_binding_document,'UTF8')::jsonb;
    -- Alias references may describe the same immutable source. They retain their
    -- private Search/Read authority and map to one public Citation in first-use order.
    IF EXISTS (SELECT 1 FROM jsonb_array_elements(binding_json->'results') item GROUP BY item->>'citation_id'
            HAVING count(DISTINCT jsonb_build_array(item->'index_version_id',item->'chunk_id',item->'source_version_id',item->'source_span_id'))<>1)
       OR EXISTS (SELECT 1 FROM jsonb_array_elements(binding_json->'results') item
            GROUP BY item->'index_version_id',item->'chunk_id',item->'source_version_id',item->'source_span_id'
            HAVING count(DISTINCT item->>'citation_id')<>1) THEN
        RAISE EXCEPTION 'dynamic citation aliases disagree on public identity' USING ERRCODE='55000';
    END IF;
    SELECT jsonb_agg(citation ORDER BY first_ordinal) INTO expected_citations FROM (
        SELECT jsonb_build_object('id',item->>'citation_id','workspace_id',proof.workspace_id::text,
            'index_version_id',item->>'index_version_id','chunk_id',item->>'chunk_id',
            'source_version_id',item->>'source_version_id','source_span_id',item->>'source_span_id') citation, min(ordinal) first_ordinal
        FROM jsonb_array_elements(binding_json->'results') WITH ORDINALITY entry(item,ordinal)
        GROUP BY 1
    ) projected;
    IF candidate_json#>'{payload,proposal_suggestion}'='null'::jsonb THEN expected_proposal:='null'::jsonb;
    ELSE
        SELECT jsonb_build_object('summary',candidate_json#>>'{payload,proposal_suggestion,summary}',
            'citation_ids',jsonb_agg(citation_id ORDER BY first_ordinal),'href','/proposals')
        INTO expected_proposal FROM (
            SELECT item->'citation_id' citation_id,min(proposal.ordinal) first_ordinal
            FROM jsonb_array_elements(candidate_json#>'{payload,proposal_suggestion,citation_refs}') WITH ORDINALITY proposal(ref,ordinal)
            JOIN jsonb_array_elements(binding_json->'results') item ON item->'evidence_ref'=proposal.ref
            GROUP BY 1
        ) projected;
    END IF;
    IF git_receipt.id IS NOT NULL THEN
        git_json:=convert_from(git_receipt.output_document,'UTF8')::jsonb;
        expected_git:=jsonb_build_object('branch',git_json->>'branch','head',git_json->>'head','clean',git_json->'clean',
            'staged_count',git_json->'staged_count','unstaged_count',git_json->'unstaged_count',
            'untracked_count',git_json->'untracked_count','conflict_count',git_json->'conflict_count');
    END IF;
    expected_document:=jsonb_build_object('result_type','workspace_analysis','schema_id','conversation.workspace_analysis_answer',
        'schema_version','v2','model_run_ref',candidate.synthesis_model_run_id::text,
        'payload',jsonb_build_object('answer_markdown',candidate_json#>>'{payload,answer_markdown}',
            'citations',expected_citations,'git_status',expected_git,'proposal_suggestion',expected_proposal,'termination_reason','COMPLETED',
            'budget',jsonb_build_object('model_calls',analysis.settled_model_calls,'tool_calls',analysis.settled_tool_calls,
                'input_tokens',analysis.settled_input_tokens,'output_tokens',analysis.settled_output_tokens,'estimated_cost_microunits',analysis.settled_cost_microunits)));
    published_json:=convert_from(proof.published_document,'UTF8')::jsonb;
    IF published_json IS DISTINCT FROM expected_document THEN
        RAISE EXCEPTION 'dynamic workspace analysis publication is not the authoritative projection' USING ERRCODE='55000';
    END IF;
END;
$$;


--
-- Name: verify_answer_feedback_binding(); Type: FUNCTION; Schema: agent; Owner: -
--

CREATE FUNCTION agent.verify_answer_feedback_binding() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    answer_row agent.answer%ROWTYPE;
BEGIN
    SELECT *
      INTO answer_row
      FROM agent.answer
     WHERE id = NEW.answer_id
       AND workspace_id = NEW.workspace_id
     FOR SHARE;

    IF answer_row.id IS NULL THEN
        RETURN NEW;
    END IF;

    IF answer_row.publication_status NOT IN ('completed', 'refused') THEN
        RAISE EXCEPTION 'feedback requires a published answer or refusal' USING ERRCODE = '23514';
    END IF;

    IF NEW.feedback_type IN ('irrelevant_citation', 'broken_citation') THEN
        IF NEW.citation_id IS NULL THEN
            RAISE EXCEPTION 'citation feedback requires a citation id' USING ERRCODE = '23514';
        END IF;
        IF answer_row.result_type <> 'rag_answer'
           OR answer_row.result IS NULL
           OR NOT EXISTS (
                SELECT 1
                  FROM jsonb_array_elements(COALESCE(answer_row.result->'payload'->'citations', '[]'::jsonb)) AS citation(value)
                 WHERE citation.value->>'id' = NEW.citation_id
           ) THEN
            RAISE EXCEPTION 'citation feedback must bind to an existing answer citation' USING ERRCODE = '23514';
        END IF;
    ELSIF NEW.citation_id IS NOT NULL THEN
        RAISE EXCEPTION 'non-citation feedback cannot bind a citation id' USING ERRCODE = '23514';
    END IF;

    RETURN NEW;
END;
$$;


--
-- Name: verify_workspace_analysis_budget_totals(uuid); Type: FUNCTION; Schema: agent; Owner: -
--

CREATE FUNCTION agent.verify_workspace_analysis_budget_totals(target_run_id uuid) RETURNS void
    LANGUAGE plpgsql
    AS $$
DECLARE
    run_row agent.workspace_analysis_run%ROWTYPE;
    active_model_calls bigint;
    active_tool_calls bigint;
    active_source_reads bigint;
    active_input_tokens bigint;
    active_output_tokens bigint;
    active_cost bigint;
    used_model_calls bigint;
    used_tool_calls bigint;
    used_source_reads bigint;
    used_input_tokens bigint;
    used_output_tokens bigint;
    used_cost bigint;
BEGIN
    SELECT * INTO run_row
      FROM agent.workspace_analysis_run
     WHERE id=target_run_id;
    IF run_row.id IS NULL THEN
        RETURN;
    END IF;

    SELECT
        COALESCE(sum(reserved_model_calls) FILTER (WHERE status='RESERVED'),0),
        COALESCE(sum(reserved_tool_calls) FILTER (WHERE status='RESERVED'),0),
        COALESCE(sum(reserved_source_reads) FILTER (WHERE status='RESERVED'),0),
        COALESCE(sum(reserved_input_tokens) FILTER (WHERE status='RESERVED'),0),
        COALESCE(sum(reserved_output_tokens) FILTER (WHERE status='RESERVED'),0),
        COALESCE(sum(reserved_cost_microunits) FILTER (WHERE status='RESERVED'),0),
        COALESCE(sum(settled_model_calls) FILTER (WHERE status<>'RESERVED'),0),
        COALESCE(sum(settled_tool_calls) FILTER (WHERE status<>'RESERVED'),0),
        COALESCE(sum(settled_source_reads) FILTER (WHERE status<>'RESERVED'),0),
        COALESCE(sum(settled_input_tokens) FILTER (WHERE status<>'RESERVED'),0),
        COALESCE(sum(settled_output_tokens) FILTER (WHERE status<>'RESERVED'),0),
        COALESCE(sum(settled_cost_microunits) FILTER (WHERE status<>'RESERVED'),0)
      INTO active_model_calls,active_tool_calls,active_source_reads,
           active_input_tokens,active_output_tokens,active_cost,
           used_model_calls,used_tool_calls,used_source_reads,
           used_input_tokens,used_output_tokens,used_cost
      FROM agent.workspace_analysis_budget_reservation
     WHERE analysis_run_id=target_run_id;

    IF run_row.reserved_model_calls<>active_model_calls
       OR run_row.reserved_tool_calls<>active_tool_calls
       OR run_row.reserved_source_reads<>active_source_reads
       OR run_row.reserved_input_tokens<>active_input_tokens
       OR run_row.reserved_output_tokens<>active_output_tokens
       OR run_row.settled_model_calls<>used_model_calls
       OR run_row.settled_tool_calls<>used_tool_calls
       OR run_row.settled_source_reads<>used_source_reads
       OR run_row.settled_input_tokens<>used_input_tokens
       OR run_row.settled_output_tokens<>used_output_tokens
       OR (run_row.max_cost_microunits IS NOT NULL AND (
            run_row.reserved_cost_microunits<>active_cost
            OR run_row.settled_cost_microunits<>used_cost
       )) THEN
        RAISE EXCEPTION 'workspace analysis budget totals drifted' USING ERRCODE='55000';
    END IF;
END;
$$;


--
-- Name: verify_workspace_analysis_model_call_closure(uuid); Type: FUNCTION; Schema: agent; Owner: -
--

CREATE FUNCTION agent.verify_workspace_analysis_model_call_closure(target_call_id uuid) RETURNS void
    LANGUAGE plpgsql
    AS $$
DECLARE
    analysis_run_id_value uuid;
    operation_id_value uuid;
    call_status_value text;
    operation_status_value text;
    operation_error_code_value text;
    reservation_status_value text;
BEGIN
    SELECT analysis.id,operation.id,model_call.status,operation.status,operation.error_code,reservation.status
      INTO analysis_run_id_value,operation_id_value,call_status_value,operation_status_value,
           operation_error_code_value,reservation_status_value
      FROM agent.model_call AS model_call
      JOIN agent.model_run AS model_run ON model_run.id=model_call.model_run_id
      JOIN agent.workspace_analysis_run AS analysis
        ON analysis.workspace_id=model_run.workspace_id
       AND analysis.workflow_run_id=model_run.workflow_run_id
      LEFT JOIN agent.workspace_analysis_operation AS operation
        ON operation.analysis_run_id=analysis.id
       AND operation.model_call_id=model_call.id
      LEFT JOIN agent.workspace_analysis_budget_reservation AS reservation
        ON reservation.operation_id=operation.id
     WHERE model_call.id=target_call_id;
    IF analysis_run_id_value IS NULL THEN
        RETURN;
    END IF;
    IF operation_id_value IS NULL THEN
        RAISE EXCEPTION 'workspace analysis model call has no logical operation' USING ERRCODE='55000';
    END IF;
    PERFORM agent.verify_workspace_analysis_operation_closure(operation_id_value);
    IF NOT (
        (call_status_value='STARTED' AND operation_status_value='STARTED' AND reservation_status_value='RESERVED')
        OR (
            call_status_value='SUCCEEDED'
            AND (
                (operation_status_value='SUCCEEDED' AND reservation_status_value='SETTLED')
                OR (
                    operation_status_value='FAILED'
                    AND operation_error_code_value='WORKSPACE_ANALYSIS_MODEL_REFUSED'
                    AND reservation_status_value='SETTLED'
                )
            )
        )
        OR (call_status_value='FAILED' AND operation_status_value='FAILED' AND reservation_status_value='SETTLED')
        OR (call_status_value='UNKNOWN' AND operation_status_value='UNKNOWN' AND reservation_status_value='UNKNOWN_CHARGED')
    ) THEN
        RAISE EXCEPTION 'workspace analysis model call transaction closure is invalid' USING ERRCODE='55000';
    END IF;
END;
$$;


--
-- Name: verify_workspace_analysis_operation_closure(uuid); Type: FUNCTION; Schema: agent; Owner: -
--

CREATE FUNCTION agent.verify_workspace_analysis_operation_closure(target_operation_id uuid) RETURNS void
    LANGUAGE plpgsql
    AS $$
DECLARE
    operation_row agent.workspace_analysis_operation%ROWTYPE;
    reservation_row agent.workspace_analysis_budget_reservation%ROWTYPE;
BEGIN
    SELECT * INTO operation_row
      FROM agent.workspace_analysis_operation
     WHERE id=target_operation_id;
    IF operation_row.id IS NULL THEN
        RETURN;
    END IF;
    SELECT * INTO reservation_row
      FROM agent.workspace_analysis_budget_reservation
     WHERE operation_id=target_operation_id;

    IF EXISTS (SELECT 1 FROM agent.workspace_analysis_run WHERE id=operation_row.analysis_run_id AND definition_version=2) THEN
        IF NOT EXISTS (SELECT 1 FROM agent.workspace_analysis_journal WHERE operation_id=operation_row.id
            AND analysis_run_id=operation_row.analysis_run_id AND workspace_id=operation_row.workspace_id)
           OR NOT agent.workspace_analysis_v2_operation_predecessor(operation_row.id) THEN
            RAISE EXCEPTION 'dynamic operation requires its exact journal predecessor' USING ERRCODE='55000';
        END IF;
        IF operation_row.operation_kind='DECISION' AND operation_row.status<>'PENDING'
           AND NOT agent.workspace_analysis_v2_decision_call_bound(operation_row.model_call_id) THEN
            RAISE EXCEPTION 'dynamic decision operation has an incomplete call closure' USING ERRCODE='55000';
        END IF;
    END IF;
    IF operation_row.status='PENDING' THEN
        IF reservation_row.id IS NOT NULL THEN
            RAISE EXCEPTION 'pending workspace analysis operation has a reservation' USING ERRCODE='55000';
        END IF;
        RETURN;
    END IF;
    IF reservation_row.id IS NULL
       OR reservation_row.analysis_run_id<>operation_row.analysis_run_id
       OR reservation_row.workspace_id<>operation_row.workspace_id
       OR reservation_row.call_kind<>operation_row.call_kind
       OR reservation_row.model_call_id IS DISTINCT FROM operation_row.model_call_id
       OR reservation_row.tool_call_id IS DISTINCT FROM operation_row.tool_call_id
       OR (operation_row.status='STARTED' AND reservation_row.status<>'RESERVED')
       OR (operation_row.status IN ('SUCCEEDED','FAILED') AND reservation_row.status<>'SETTLED')
       OR (operation_row.status='UNKNOWN' AND reservation_row.status<>'UNKNOWN_CHARGED') THEN
        RAISE EXCEPTION 'workspace analysis operation reservation closure is invalid' USING ERRCODE='55000';
    END IF;
END;
$$;


--
-- Name: verify_workspace_analysis_publication_closure(uuid); Type: FUNCTION; Schema: agent; Owner: -
--

CREATE FUNCTION agent.verify_workspace_analysis_publication_closure(answer_id_value uuid) RETURNS void
    LANGUAGE plpgsql
    AS $$
DECLARE
    question_mode_value text;
    answer_status_value text;
    answer_result_type_value text;
    answer_result_value jsonb;
    answer_result_hash_value text;
    answer_model_run_id_value uuid;
    analysis_status_value text;
    analysis_reason_value text;
    analysis_validation_receipt_id uuid;
    analysis_review_model_run_id uuid;
    expected_answer_status text;
    proof_row agent.workspace_analysis_publication_proof%ROWTYPE;
    termination_proof_row agent.workspace_analysis_termination_proof%ROWTYPE;
    proof_review_model_run_id uuid;
BEGIN
    SELECT question.mode,answer.publication_status,answer.result_type,answer.result,answer.result_hash,answer.model_run_id
      INTO question_mode_value,answer_status_value,answer_result_type_value,answer_result_value,answer_result_hash_value,answer_model_run_id_value
      FROM agent.answer AS answer
      JOIN agent.question AS question
        ON question.id=answer.question_id
       AND question.workspace_id=answer.workspace_id
       AND question.conversation_id=answer.conversation_id
     WHERE answer.id=answer_id_value;
    IF answer_status_value IS NULL OR question_mode_value<>'workspace_analysis' THEN
        RETURN;
    END IF;

    SELECT status,termination_reason,validation_receipt_id,review_model_run_id
      INTO analysis_status_value,analysis_reason_value,analysis_validation_receipt_id,analysis_review_model_run_id
      FROM agent.workspace_analysis_run
     WHERE answer_id=answer_id_value;
    IF analysis_status_value IS NULL THEN
        RAISE EXCEPTION 'workspace analysis answer has no durable analysis run' USING ERRCODE='55000';
    END IF;
    expected_answer_status := CASE analysis_status_value
        WHEN 'queued' THEN 'pending'
        WHEN 'running' THEN 'pending'
        WHEN 'succeeded' THEN 'completed'
        WHEN 'refused' THEN 'refused'
        WHEN 'clarification_required' THEN 'clarification_required'
        WHEN 'failed' THEN 'failed'
        WHEN 'cancelled' THEN 'cancelled'
        ELSE NULL
    END;
    IF answer_status_value IS DISTINCT FROM expected_answer_status THEN
        RAISE EXCEPTION 'workspace analysis run and answer terminal states are not closed' USING ERRCODE='55000';
    END IF;
    SELECT * INTO proof_row
      FROM agent.workspace_analysis_publication_proof
     WHERE answer_id=answer_id_value;
    SELECT * INTO termination_proof_row
      FROM agent.workspace_analysis_termination_proof
     WHERE answer_id=answer_id_value;
    IF analysis_status_value='succeeded' THEN
        SELECT model_run_id INTO proof_review_model_run_id
          FROM agent.workspace_analysis_model_result
         WHERE id=proof_row.review_model_result_id;
        IF proof_row.id IS NULL
           OR answer_result_type_value<>'workspace_analysis'
           OR answer_result_hash_value IS DISTINCT FROM proof_row.published_result_hash
           OR answer_result_value IS DISTINCT FROM convert_from(proof_row.published_document,'UTF8')::jsonb
           OR analysis_validation_receipt_id IS DISTINCT FROM proof_row.validation_receipt_id
           OR analysis_review_model_run_id IS DISTINCT FROM proof_review_model_run_id
           OR termination_proof_row.id IS NOT NULL THEN
            RAISE EXCEPTION 'workspace analysis completed publication proof is not closed' USING ERRCODE='55000';
        END IF;
    ELSIF proof_row.id IS NOT NULL THEN
        RAISE EXCEPTION 'non-success workspace analysis cannot retain a success publication proof' USING ERRCODE='55000';
    ELSIF analysis_status_value IN ('refused','clarification_required','failed','cancelled') THEN
        IF termination_proof_row.id IS NULL
           OR termination_proof_row.reason IS DISTINCT FROM analysis_reason_value
           OR answer_result_hash_value IS DISTINCT FROM termination_proof_row.published_result_hash
           OR answer_result_value IS DISTINCT FROM convert_from(termination_proof_row.published_document,'UTF8')::jsonb
           OR answer_model_run_id_value IS DISTINCT FROM termination_proof_row.published_model_run_id THEN
            RAISE EXCEPTION 'workspace analysis termination proof is not closed' USING ERRCODE='55000';
        END IF;
    ELSIF termination_proof_row.id IS NOT NULL THEN
        RAISE EXCEPTION 'active workspace analysis cannot retain a termination proof' USING ERRCODE='55000';
    END IF;
END;
$$;


--
-- Name: verify_workspace_analysis_tool_call_closure(uuid); Type: FUNCTION; Schema: agent; Owner: -
--

CREATE FUNCTION agent.verify_workspace_analysis_tool_call_closure(target_call_id uuid) RETURNS void
    LANGUAGE plpgsql
    AS $$
DECLARE
    analysis_run_id_value uuid;
    operation_id_value uuid;
    call_status_value text;
    workflow_run_id_value uuid;
    operation_status_value text;
    operation_error_code_value text;
    reservation_status_value text;
BEGIN
    SELECT analysis.id,operation.id,tool_call.status,tool_call.workflow_run_id,
           operation.status,operation.error_code,reservation.status
      INTO analysis_run_id_value,operation_id_value,call_status_value,workflow_run_id_value,
           operation_status_value,operation_error_code_value,reservation_status_value
      FROM workflow.tool_call AS tool_call
      JOIN agent.workspace_analysis_run AS analysis
        ON analysis.workspace_id=tool_call.workspace_id
       AND analysis.workflow_run_id=tool_call.workflow_run_id
      LEFT JOIN agent.workspace_analysis_operation AS operation
        ON operation.analysis_run_id=analysis.id
       AND operation.tool_call_id=tool_call.id
      LEFT JOIN agent.workspace_analysis_budget_reservation AS reservation
        ON reservation.operation_id=operation.id
     WHERE tool_call.id=target_call_id;
    IF analysis_run_id_value IS NULL OR call_status_value='REFUSED' THEN
        RETURN;
    END IF;
    IF operation_id_value IS NULL THEN
        RAISE EXCEPTION 'workspace analysis tool call has no logical operation' USING ERRCODE='55000';
    END IF;
    IF call_status_value='STARTED' AND EXISTS (
        SELECT 1
          FROM workflow.tool_call
         WHERE workflow_run_id=workflow_run_id_value
           AND status='STARTED'
           AND id<>target_call_id
    ) THEN
        RAISE EXCEPTION 'workspace analysis tool calls must remain serial' USING ERRCODE='55000';
    END IF;
    PERFORM agent.verify_workspace_analysis_operation_closure(operation_id_value);
    IF NOT (
        (call_status_value='STARTED' AND operation_status_value='STARTED' AND reservation_status_value='RESERVED')
        OR (
            call_status_value='SUCCEEDED'
            AND reservation_status_value='SETTLED'
            AND (
                operation_status_value='SUCCEEDED'
                AND EXISTS (
                    SELECT 1 FROM workflow.tool_result_receipt
                     WHERE tool_call_id=target_call_id
                )
                AND NOT EXISTS (
                    SELECT 1 FROM workflow.tool_result_receipt_failure
                     WHERE tool_call_id=target_call_id
                )
                OR (
                    operation_status_value='FAILED'
                    AND operation_error_code_value='WORKSPACE_ANALYSIS_RECEIPT_INVALID'
                    AND EXISTS (
                        SELECT 1 FROM workflow.tool_result_receipt_failure
                         WHERE tool_call_id=target_call_id
                    )
                    AND NOT EXISTS (
                        SELECT 1 FROM workflow.tool_result_receipt
                         WHERE tool_call_id=target_call_id
                    )
                )
            )
        )
        OR (call_status_value='FAILED' AND operation_status_value='FAILED' AND reservation_status_value='SETTLED')
        OR (call_status_value='UNKNOWN' AND operation_status_value='UNKNOWN' AND reservation_status_value='UNKNOWN_CHARGED')
    ) THEN
        RAISE EXCEPTION 'workspace analysis tool call transaction closure is invalid' USING ERRCODE='55000';
    END IF;
END;
$$;


--
-- Name: verify_workspace_analysis_v2_model_run(uuid); Type: FUNCTION; Schema: agent; Owner: -
--

CREATE FUNCTION agent.verify_workspace_analysis_v2_model_run(target_model_run_id uuid) RETURNS void
    LANGUAGE plpgsql
    AS $$
DECLARE
    model agent.model_run%ROWTYPE;
    last_call agent.model_call%ROWTYPE;
    call_count integer;
    maximum_call integer;
    last_action text;
BEGIN
    SELECT * INTO model FROM agent.model_run WHERE id=target_model_run_id;
    IF model.id IS NULL OR model.output_schema_id<>'agent.workspace-analysis-decision' THEN RETURN; END IF;
    SELECT count(*),max(call_no) INTO call_count,maximum_call FROM agent.model_call WHERE model_run_id=model.id;
    IF call_count NOT BETWEEN 1 AND 12 OR call_count IS DISTINCT FROM maximum_call
       OR EXISTS (SELECT 1 FROM agent.model_call WHERE model_run_id=model.id AND NOT agent.workspace_analysis_v2_decision_call_bound(id)) THEN
        RAISE EXCEPTION 'dynamic model run requires a complete nonempty decision call prefix' USING ERRCODE='55000';
    END IF;
    SELECT * INTO last_call FROM agent.model_call WHERE model_run_id=model.id AND call_no=maximum_call;
    SELECT convert_from(document,'UTF8')::jsonb->>'action' INTO last_action FROM agent.workspace_analysis_decision WHERE model_call_id=last_call.id;
    IF EXISTS (SELECT 1 FROM agent.model_call WHERE model_run_id=model.id AND call_no<maximum_call AND status<>'SUCCEEDED')
       OR (model.status='RUNNING' AND (last_call.status NOT IN ('STARTED','SUCCEEDED') OR last_action='finish'))
       OR (model.status='SUCCEEDED' AND (last_call.status<>'SUCCEEDED' OR model.final_result_type IS DISTINCT FROM 'workspace_analysis_decision'))
       OR (model.status='FAILED' AND (last_call.status<>'FAILED' OR model.error_code IS DISTINCT FROM last_call.error_code))
       OR (model.status='UNKNOWN' AND (last_call.status<>'UNKNOWN' OR model.error_code IS DISTINCT FROM last_call.error_code))
       OR model.status NOT IN ('RUNNING','SUCCEEDED','FAILED','UNKNOWN')
       OR (model.status<>'RUNNING' AND (model.completed_at IS NULL OR model.completed_at<last_call.completed_at)) THEN
        RAISE EXCEPTION 'dynamic model run terminal result disagrees with its calls' USING ERRCODE='55000';
    END IF;
    IF model.status='SUCCEEDED' AND last_action IS DISTINCT FROM 'finish'
       AND NOT EXISTS (SELECT 1 FROM workflow.node_attempt WHERE id=model.node_attempt_id AND status IN ('lease_lost','retry_scheduled','failed','cancelled','manual_recovery'))
       AND NOT EXISTS (SELECT 1 FROM agent.workspace_analysis_run analysis
           JOIN agent.workspace_analysis_termination_proof proof ON proof.analysis_run_id=analysis.id
           WHERE analysis.workflow_run_id=model.workflow_run_id AND analysis.workspace_id=model.workspace_id) THEN
        RAISE EXCEPTION 'dynamic model checkpoint requires replacement or a proven analysis termination' USING ERRCODE='55000';
    END IF;
END;
$$;


--
-- Name: workspace_analysis_run; Type: TABLE; Schema: agent; Owner: -
--

CREATE TABLE agent.workspace_analysis_run (
    id uuid NOT NULL,
    workspace_id uuid NOT NULL,
    conversation_id uuid NOT NULL,
    question_id uuid NOT NULL,
    answer_id uuid NOT NULL,
    workflow_run_id uuid NOT NULL,
    definition_key text NOT NULL,
    definition_version bigint NOT NULL,
    definition_hash text NOT NULL,
    tool_catalog_hash text NOT NULL,
    policy_version integer NOT NULL,
    config_revision bigint NOT NULL,
    deadline_at timestamp with time zone NOT NULL,
    plan_model_timeout_ms bigint NOT NULL,
    synthesis_model_timeout_ms bigint NOT NULL,
    review_model_timeout_ms bigint NOT NULL,
    git_tool_timeout_ms bigint NOT NULL,
    search_tool_timeout_ms bigint NOT NULL,
    source_read_tool_timeout_ms bigint NOT NULL,
    validate_citation_tool_timeout_ms bigint NOT NULL,
    durable_completion_margin_ms bigint NOT NULL,
    max_nodes integer NOT NULL,
    max_model_calls integer NOT NULL,
    max_tool_calls integer NOT NULL,
    max_source_reads integer NOT NULL,
    max_tool_concurrency integer NOT NULL,
    max_input_tokens bigint NOT NULL,
    max_output_tokens bigint NOT NULL,
    max_cost_microunits bigint,
    reserved_model_calls integer DEFAULT 0 NOT NULL,
    reserved_tool_calls integer DEFAULT 0 NOT NULL,
    reserved_source_reads integer DEFAULT 0 NOT NULL,
    reserved_input_tokens bigint DEFAULT 0 NOT NULL,
    reserved_output_tokens bigint DEFAULT 0 NOT NULL,
    reserved_cost_microunits bigint,
    settled_model_calls integer DEFAULT 0 NOT NULL,
    settled_tool_calls integer DEFAULT 0 NOT NULL,
    settled_source_reads integer DEFAULT 0 NOT NULL,
    settled_input_tokens bigint DEFAULT 0 NOT NULL,
    settled_output_tokens bigint DEFAULT 0 NOT NULL,
    settled_cost_microunits bigint,
    status text NOT NULL,
    termination_reason text,
    validation_receipt_id uuid,
    review_model_run_id uuid,
    version bigint DEFAULT 1 NOT NULL,
    created_at timestamp with time zone NOT NULL,
    updated_at timestamp with time zone NOT NULL,
    completed_at timestamp with time zone,
    CONSTRAINT workspace_analysis_run_budget_bounds CHECK ((((reserved_model_calls + settled_model_calls) <= max_model_calls) AND ((reserved_tool_calls + settled_tool_calls) <= max_tool_calls) AND ((reserved_source_reads + settled_source_reads) <= max_source_reads) AND ((reserved_input_tokens + settled_input_tokens) <= max_input_tokens) AND ((reserved_output_tokens + settled_output_tokens) <= max_output_tokens) AND (reserved_cost_microunits IS NULL) AND (settled_cost_microunits IS NULL))),
    CONSTRAINT workspace_analysis_run_config_revision_check CHECK ((config_revision >= 0)),
    CONSTRAINT workspace_analysis_run_contract CHECK (((definition_key = 'workspace-analysis'::text) AND (max_tool_concurrency = 1) AND (max_cost_microunits IS NULL) AND (((definition_version = 1) AND (policy_version = 1) AND (max_nodes = 6) AND (max_model_calls = 3) AND (max_tool_calls = 6) AND (max_source_reads = 3) AND (max_input_tokens = 196608) AND ((max_output_tokens >= 1281) AND (max_output_tokens <= 5376))) OR ((definition_version = 2) AND (policy_version = 2) AND (max_nodes = 4) AND (max_model_calls = 14) AND (max_tool_calls = 13) AND (max_source_reads = 8) AND (max_input_tokens = 917504) AND ((max_output_tokens >= 7169) AND (max_output_tokens <= 11264)))))),
    CONSTRAINT workspace_analysis_run_definition_hash_check CHECK ((definition_hash ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT workspace_analysis_run_durable_completion_margin_ms_check CHECK ((durable_completion_margin_ms = 5000)),
    CONSTRAINT workspace_analysis_run_git_tool_timeout_ms_check CHECK (((git_tool_timeout_ms >= 1) AND (git_tool_timeout_ms <= 3600000))),
    CONSTRAINT workspace_analysis_run_lifecycle CHECK (((updated_at >= created_at) AND (deadline_at > created_at) AND (deadline_at <= (created_at + '01:00:00'::interval)) AND (deadline_at = (created_at + ((
CASE definition_version
    WHEN 1 THEN ((((((((((((git_tool_timeout_ms + 5000) + plan_model_timeout_ms) + search_tool_timeout_ms) + 15000) + (3 * source_read_tool_timeout_ms)) + 10000) + synthesis_model_timeout_ms) + 15000) + validate_citation_tool_timeout_ms) + 10000) + review_model_timeout_ms) + 15000)
    WHEN 2 THEN ((((((((12 * ((plan_model_timeout_ms + GREATEST(git_tool_timeout_ms, search_tool_timeout_ms, source_read_tool_timeout_ms, validate_citation_tool_timeout_ms)) + 5000)) + 15000) + synthesis_model_timeout_ms) + 15000) + validate_citation_tool_timeout_ms) + 10000) + review_model_timeout_ms) + 15000)
    ELSE NULL::bigint
END)::double precision * '00:00:00.001'::interval))) AND (((status = ANY (ARRAY['queued'::text, 'running'::text])) AND (termination_reason IS NULL) AND (completed_at IS NULL)) OR ((status = 'succeeded'::text) AND (termination_reason = 'COMPLETED'::text) AND (validation_receipt_id IS NOT NULL) AND (review_model_run_id IS NOT NULL) AND (completed_at IS NOT NULL) AND (completed_at = updated_at) AND (completed_at <= deadline_at)) OR ((status = ANY (ARRAY['refused'::text, 'clarification_required'::text, 'failed'::text, 'cancelled'::text])) AND (termination_reason IS NOT NULL) AND (completed_at IS NOT NULL) AND (completed_at = updated_at))))),
    CONSTRAINT workspace_analysis_run_plan_model_timeout_ms_check CHECK (((plan_model_timeout_ms >= 1) AND (plan_model_timeout_ms <= 3600000))),
    CONSTRAINT workspace_analysis_run_reason_check CHECK ((((status = ANY (ARRAY['queued'::text, 'running'::text])) AND (termination_reason IS NULL)) OR ((status = 'succeeded'::text) AND (termination_reason = 'COMPLETED'::text)) OR ((status = 'refused'::text) AND (termination_reason = ANY (ARRAY['WORKSPACE_ANALYSIS_EVIDENCE_INSUFFICIENT'::text, 'WORKSPACE_ANALYSIS_CITATION_INVALID'::text, 'WORKSPACE_ANALYSIS_FAITHFULNESS_REJECTED'::text, 'WORKSPACE_ANALYSIS_MODEL_REFUSED'::text]))) OR ((status = 'clarification_required'::text) AND (termination_reason = 'WORKSPACE_ANALYSIS_CLARIFICATION_REQUIRED'::text)) OR ((status = 'failed'::text) AND (termination_reason = ANY (ARRAY['WORKSPACE_ANALYSIS_BUDGET_EXHAUSTED'::text, 'WORKSPACE_ANALYSIS_RECEIPT_INVALID'::text, 'WORKSPACE_ANALYSIS_RESULT_UNKNOWN'::text, 'WORKSPACE_ANALYSIS_DEADLINE_EXCEEDED'::text, 'WORKSPACE_ANALYSIS_MODEL_FAILED'::text, 'WORKSPACE_ANALYSIS_TOOL_FAILED'::text, 'WORKSPACE_ANALYSIS_RUNTIME_FAILED'::text]))) OR ((status = 'cancelled'::text) AND (termination_reason = 'WORKSPACE_ANALYSIS_CANCELLED'::text)))),
    CONSTRAINT workspace_analysis_run_reserved_input_tokens_check CHECK ((reserved_input_tokens >= 0)),
    CONSTRAINT workspace_analysis_run_reserved_model_calls_check CHECK ((reserved_model_calls >= 0)),
    CONSTRAINT workspace_analysis_run_reserved_output_tokens_check CHECK ((reserved_output_tokens >= 0)),
    CONSTRAINT workspace_analysis_run_reserved_source_reads_check CHECK ((reserved_source_reads >= 0)),
    CONSTRAINT workspace_analysis_run_reserved_tool_calls_check CHECK ((reserved_tool_calls >= 0)),
    CONSTRAINT workspace_analysis_run_review_model_timeout_ms_check CHECK (((review_model_timeout_ms >= 1) AND (review_model_timeout_ms <= 3600000))),
    CONSTRAINT workspace_analysis_run_search_tool_timeout_ms_check CHECK (((search_tool_timeout_ms >= 1) AND (search_tool_timeout_ms <= 3600000))),
    CONSTRAINT workspace_analysis_run_settled_input_tokens_check CHECK ((settled_input_tokens >= 0)),
    CONSTRAINT workspace_analysis_run_settled_model_calls_check CHECK ((settled_model_calls >= 0)),
    CONSTRAINT workspace_analysis_run_settled_output_tokens_check CHECK ((settled_output_tokens >= 0)),
    CONSTRAINT workspace_analysis_run_settled_source_reads_check CHECK ((settled_source_reads >= 0)),
    CONSTRAINT workspace_analysis_run_settled_tool_calls_check CHECK ((settled_tool_calls >= 0)),
    CONSTRAINT workspace_analysis_run_source_read_tool_timeout_ms_check CHECK (((source_read_tool_timeout_ms >= 1) AND (source_read_tool_timeout_ms <= 3600000))),
    CONSTRAINT workspace_analysis_run_status_check CHECK ((status = ANY (ARRAY['queued'::text, 'running'::text, 'succeeded'::text, 'refused'::text, 'clarification_required'::text, 'failed'::text, 'cancelled'::text]))),
    CONSTRAINT workspace_analysis_run_synthesis_model_timeout_ms_check CHECK (((synthesis_model_timeout_ms >= 1) AND (synthesis_model_timeout_ms <= 3600000))),
    CONSTRAINT workspace_analysis_run_tool_catalog_hash_check CHECK ((tool_catalog_hash ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT workspace_analysis_run_validate_citation_tool_timeout_ms_check CHECK (((validate_citation_tool_timeout_ms >= 1) AND (validate_citation_tool_timeout_ms <= 3600000))),
    CONSTRAINT workspace_analysis_run_version_check CHECK ((version > 0))
);


--
-- Name: verify_workspace_analysis_v2_success_facts(agent.workspace_analysis_run, uuid, uuid); Type: FUNCTION; Schema: agent; Owner: -
--

CREATE FUNCTION agent.verify_workspace_analysis_v2_success_facts(analysis agent.workspace_analysis_run, validation_id uuid, review_id uuid) RETURNS void
    LANGUAGE plpgsql
    AS $$
DECLARE
    candidate agent.workspace_analysis_candidate%ROWTYPE;
    review agent.workspace_analysis_model_result%ROWTYPE;
    decision_count bigint; model_count bigint; tool_count bigint; read_count bigint;
BEGIN
    SELECT * INTO candidate FROM agent.workspace_analysis_candidate WHERE analysis_run_id=analysis.id AND answer_id=analysis.answer_id AND schema_version=2;
    SELECT result.* INTO review FROM agent.workspace_analysis_operation operation
      JOIN agent.workspace_analysis_model_result result ON result.id=operation.result_id AND result.operation_id=operation.id
        AND result.document_hash=operation.result_hash AND result.model_call_id=operation.model_call_id
      WHERE operation.analysis_run_id=analysis.id AND operation.node_key='review_publish' AND operation.operation_kind='FAITHFULNESS_REVIEW'
        AND operation.ordinal=1 AND operation.status='SUCCEEDED' AND result.model_run_id=review_id;
    SELECT count(*) FILTER (WHERE operation_kind='DECISION'),count(*) FILTER (WHERE call_kind='MODEL'),
        count(*) FILTER (WHERE call_kind='TOOL'),count(*) FILTER (WHERE operation_kind='SOURCE_READ')
      INTO decision_count,model_count,tool_count,read_count FROM agent.workspace_analysis_operation WHERE analysis_run_id=analysis.id;
    IF analysis.definition_version<>2 OR analysis.policy_version<>2 OR candidate.id IS NULL OR review.id IS NULL
       OR candidate.workspace_id<>analysis.workspace_id OR review.workspace_id<>analysis.workspace_id
       OR candidate.schema_version<>2 OR convert_from(candidate.document,'UTF8')::jsonb->>'schema_version' IS DISTINCT FROM '2'
       OR review.subject_candidate_id IS DISTINCT FROM candidate.id OR review.subject_candidate_hash IS DISTINCT FROM candidate.document_hash
       OR review.model_run_id=candidate.synthesis_model_run_id OR convert_from(review.document,'UTF8')::jsonb#>'{payload,passed}' IS DISTINCT FROM 'true'::jsonb
       OR NOT agent.workspace_analysis_v2_decisions_complete(analysis.id)
       OR NOT agent.workspace_analysis_v2_final_validation_bound(analysis.id)
       OR NOT agent.workspace_analysis_v2_validation_all_valid(analysis.id)
       OR NOT EXISTS (SELECT 1 FROM agent.workspace_analysis_operation WHERE analysis_run_id=analysis.id
            AND node_key='validate_citations' AND operation_kind='CITATION_VALIDATION' AND ordinal=1 AND status='SUCCEEDED' AND result_id=validation_id)
       OR NOT EXISTS (SELECT 1 FROM agent.workspace_analysis_operation WHERE id=candidate.synthesis_operation_id AND analysis_run_id=analysis.id
            AND node_key='synthesize_answer' AND operation_kind='ANSWER_SYNTHESIS' AND ordinal=1 AND status='SUCCEEDED'
            AND result_id=candidate.id AND result_hash=candidate.document_hash)
       OR NOT EXISTS (SELECT 1 FROM agent.model_run WHERE id=candidate.synthesis_model_run_id AND workspace_id=analysis.workspace_id
            AND workflow_run_id=analysis.workflow_run_id AND status='SUCCEEDED' AND final_result_type='workspace_analysis_answer')
       OR NOT EXISTS (SELECT 1 FROM agent.model_run WHERE id=review_id AND workspace_id=analysis.workspace_id
            AND workflow_run_id=analysis.workflow_run_id AND status='SUCCEEDED' AND final_result_type='faithfulness_review')
       OR EXISTS (SELECT 1 FROM agent.workspace_analysis_operation WHERE analysis_run_id=analysis.id AND (status<>'SUCCEEDED' OR NOT agent.workspace_analysis_v2_operation_predecessor(id)))
       OR EXISTS (SELECT 1 FROM agent.workspace_analysis_budget_reservation WHERE analysis_run_id=analysis.id AND status<>'SETTLED')
       OR EXISTS (SELECT 1 FROM agent.model_run WHERE workspace_id=analysis.workspace_id AND workflow_run_id=analysis.workflow_run_id AND status<>'SUCCEEDED')
       OR EXISTS (SELECT 1 FROM agent.model_call call JOIN agent.model_run model ON model.id=call.model_run_id
            WHERE model.workspace_id=analysis.workspace_id AND model.workflow_run_id=analysis.workflow_run_id AND call.status<>'SUCCEEDED')
       OR EXISTS (SELECT 1 FROM workflow.tool_call WHERE workspace_id=analysis.workspace_id AND workflow_run_id=analysis.workflow_run_id AND status<>'SUCCEEDED')
       OR model_count<>decision_count+2 OR model_count<>tool_count+2 OR decision_count NOT BETWEEN 3 AND 12
       OR read_count NOT BETWEEN 1 AND 8 OR tool_count NOT BETWEEN 3 AND 13
       OR (SELECT count(*) FROM agent.workspace_analysis_operation WHERE analysis_run_id=analysis.id AND node_key='synthesize_answer')<>1
       OR (SELECT count(*) FROM agent.workspace_analysis_operation WHERE analysis_run_id=analysis.id AND node_key='validate_citations')<>1
       OR (SELECT count(*) FROM agent.workspace_analysis_operation WHERE analysis_run_id=analysis.id AND node_key='review_publish')<>1
       OR model_count<>(SELECT count(*) FROM agent.model_call call JOIN agent.model_run model ON model.id=call.model_run_id WHERE model.workspace_id=analysis.workspace_id AND model.workflow_run_id=analysis.workflow_run_id)
       OR tool_count<>(SELECT count(*) FROM workflow.tool_call WHERE workspace_id=analysis.workspace_id AND workflow_run_id=analysis.workflow_run_id)
       OR analysis.settled_model_calls<>model_count OR analysis.settled_tool_calls<>tool_count OR analysis.settled_source_reads<>read_count
       OR analysis.reserved_model_calls<>0 OR analysis.reserved_tool_calls<>0 OR analysis.reserved_source_reads<>0
       OR analysis.reserved_input_tokens<>0 OR analysis.reserved_output_tokens<>0 OR COALESCE(analysis.reserved_cost_microunits,0)<>0 THEN
        RAISE EXCEPTION 'dynamic workspace analysis success facts are incomplete' USING ERRCODE='55000';
    END IF;
END;
$$;


--
-- Name: workspace_analysis_deadline_next_slot(uuid); Type: FUNCTION; Schema: agent; Owner: -
--

CREATE FUNCTION agent.workspace_analysis_deadline_next_slot(target_run_id uuid) RETURNS TABLE(node_key text, operation_kind text, ordinal integer)
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'agent', 'workflow'
    AS $$
DECLARE
    total_count bigint;
    git_count bigint;
    plan_count bigint;
    search_count bigint;
    source_count bigint;
    synthesis_count bigint;
    validation_count bigint;
    review_count bigint;
    plan_json jsonb;
    selected_refs jsonb;
    selected_count integer;
    last_operation agent.workspace_analysis_operation%ROWTYPE;
    last_decision jsonb;
BEGIN
    IF EXISTS (
        SELECT 1
          FROM agent.workspace_analysis_operation
         WHERE analysis_run_id=target_run_id
           AND status<>'SUCCEEDED'
    ) THEN
        RETURN;
    END IF;

    IF EXISTS (SELECT 1 FROM agent.workspace_analysis_run WHERE id=target_run_id AND definition_version=2) THEN
        IF EXISTS (SELECT 1 FROM agent.workspace_analysis_operation operation WHERE operation.analysis_run_id=target_run_id
            AND NOT agent.workspace_analysis_v2_operation_predecessor(operation.id)) THEN RETURN; END IF;
        SELECT operation.* INTO last_operation FROM agent.workspace_analysis_journal journal
          JOIN agent.workspace_analysis_operation operation ON operation.id=journal.operation_id
          WHERE journal.analysis_run_id=target_run_id ORDER BY journal.sequence DESC LIMIT 1;
        IF last_operation.id IS NULL THEN RETURN QUERY SELECT 'decide_next'::text,'DECISION'::text,1; RETURN; END IF;
        IF last_operation.node_key='decide_next' AND last_operation.operation_kind='DECISION' THEN
            SELECT convert_from(document,'UTF8')::jsonb INTO last_decision FROM agent.workspace_analysis_decision WHERE operation_id=last_operation.id;
            IF last_decision->>'action'='finish' THEN
                IF agent.workspace_analysis_v2_has_readable_evidence(target_run_id) THEN RETURN QUERY SELECT 'synthesize_answer'::text,'ANSWER_SYNTHESIS'::text,1; END IF;
            ELSIF agent.workspace_analysis_v2_decision_action_kind(last_decision->>'action') IS NOT NULL THEN
                RETURN QUERY SELECT 'decide_next'::text,agent.workspace_analysis_v2_decision_action_kind(last_decision->>'action'),last_operation.ordinal;
            END IF;
        ELSIF last_operation.node_key='decide_next' AND last_operation.call_kind='TOOL' THEN
            RETURN QUERY SELECT 'decide_next'::text,'DECISION'::text,last_operation.ordinal+1;
        ELSIF last_operation.node_key='synthesize_answer' AND last_operation.operation_kind='ANSWER_SYNTHESIS' THEN
            RETURN QUERY SELECT 'validate_citations'::text,'CITATION_VALIDATION'::text,1;
        ELSIF last_operation.node_key='validate_citations' AND last_operation.operation_kind='CITATION_VALIDATION'
            AND agent.workspace_analysis_v2_validation_all_valid(target_run_id) THEN
            RETURN QUERY SELECT 'review_publish'::text,'FAITHFULNESS_REVIEW'::text,1;
        END IF;
        RETURN;
    END IF;

    SELECT count(*),
           count(*) FILTER (WHERE operation.operation_kind='GIT_STATUS'),
           count(*) FILTER (WHERE operation.operation_kind='RETRIEVAL_PLAN'),
           count(*) FILTER (WHERE operation.operation_kind='KNOWLEDGE_SEARCH'),
           count(*) FILTER (WHERE operation.operation_kind='SOURCE_READ'),
           count(*) FILTER (WHERE operation.operation_kind='ANSWER_SYNTHESIS'),
           count(*) FILTER (WHERE operation.operation_kind='CITATION_VALIDATION'),
           count(*) FILTER (WHERE operation.operation_kind='FAITHFULNESS_REVIEW')
      INTO total_count,git_count,plan_count,search_count,source_count,
           synthesis_count,validation_count,review_count
      FROM agent.workspace_analysis_operation AS operation
     WHERE operation.analysis_run_id=target_run_id;

    IF total_count=0 THEN
        RETURN QUERY SELECT 'inspect_workspace'::text,'GIT_STATUS'::text,1;
        RETURN;
    END IF;
    IF git_count<>1 THEN
        RETURN;
    END IF;

    IF plan_count=0 THEN
        IF total_count=1 THEN
            RETURN QUERY SELECT 'retrieve_evidence'::text,'RETRIEVAL_PLAN'::text,1;
        END IF;
        RETURN;
    ELSIF plan_count<>1 THEN
        RETURN;
    END IF;

    SELECT convert_from(result.document,'UTF8')::jsonb
      INTO plan_json
      FROM agent.workspace_analysis_operation AS plan
      JOIN agent.workspace_analysis_model_result AS result
        ON result.id=plan.result_id
       AND result.operation_id=plan.id
       AND result.analysis_run_id=plan.analysis_run_id
     WHERE plan.analysis_run_id=target_run_id
       AND plan.operation_kind='RETRIEVAL_PLAN'
       AND plan.status='SUCCEEDED';
    IF plan_json#>'{payload,requires_clarification}' IS NOT DISTINCT FROM 'true'::jsonb THEN
        RETURN;
    ELSIF plan_json#>'{payload,requires_clarification}' IS DISTINCT FROM 'false'::jsonb THEN
        RETURN;
    END IF;

    IF search_count=0 THEN
        IF total_count=2 THEN
            RETURN QUERY SELECT 'retrieve_evidence'::text,'KNOWLEDGE_SEARCH'::text,1;
        END IF;
        RETURN;
    ELSIF search_count<>1 THEN
        RETURN;
    END IF;

    selected_refs := agent.workspace_analysis_selected_refs(target_run_id);
    IF selected_refs IS NULL THEN
        RETURN;
    END IF;
    selected_count := jsonb_array_length(selected_refs);
    IF selected_count=0 THEN
        RETURN;
    END IF;
    IF source_count<selected_count THEN
        IF total_count=3+source_count
           AND agent.workspace_analysis_source_prefix_matches(
                target_run_id,selected_refs,source_count::integer
           ) THEN
            RETURN QUERY
                SELECT 'read_evidence'::text,'SOURCE_READ'::text,(source_count+1)::integer;
        END IF;
        RETURN;
    ELSIF source_count<>selected_count
       OR NOT agent.workspace_analysis_source_prefix_matches(
            target_run_id,selected_refs,selected_count
       ) THEN
        RETURN;
    END IF;

    IF synthesis_count=0 THEN
        IF total_count=3+source_count THEN
            RETURN QUERY SELECT 'synthesize_answer'::text,'ANSWER_SYNTHESIS'::text,1;
        END IF;
        RETURN;
    ELSIF synthesis_count<>1
       OR NOT EXISTS (
            SELECT 1
              FROM agent.workspace_analysis_operation AS synthesis
              JOIN agent.workspace_analysis_candidate AS candidate
                ON candidate.id=synthesis.result_id
               AND candidate.synthesis_operation_id=synthesis.id
               AND candidate.analysis_run_id=synthesis.analysis_run_id
             WHERE synthesis.analysis_run_id=target_run_id
               AND synthesis.operation_kind='ANSWER_SYNTHESIS'
               AND synthesis.status='SUCCEEDED'
               AND synthesis.result_hash=candidate.document_hash
       ) THEN
        RETURN;
    END IF;

    IF validation_count=0 THEN
        IF total_count=4+source_count THEN
            RETURN QUERY SELECT 'validate_citations'::text,'CITATION_VALIDATION'::text,1;
        END IF;
        RETURN;
    ELSIF validation_count<>1
       OR NOT agent.workspace_analysis_validation_all_valid(target_run_id) THEN
        RETURN;
    END IF;

    IF review_count=0 AND total_count=5+source_count THEN
        RETURN QUERY SELECT 'review_publish'::text,'FAITHFULNESS_REVIEW'::text,1;
    END IF;
    RETURN;
END;
$$;


--
-- Name: workspace_analysis_selected_refs(uuid); Type: FUNCTION; Schema: agent; Owner: -
--

CREATE FUNCTION agent.workspace_analysis_selected_refs(target_run_id uuid) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'agent', 'workflow'
    AS $$
DECLARE
    output_json jsonb;
    binding_json jsonb;
    selected_refs jsonb;
    expected_refs jsonb;
BEGIN
    SELECT convert_from(receipt.output_document,'UTF8')::jsonb,
           convert_from(receipt.server_binding_document,'UTF8')::jsonb
      INTO output_json,binding_json
      FROM agent.workspace_analysis_operation AS operation
      JOIN workflow.tool_result_receipt AS receipt
        ON receipt.id=operation.result_id
       AND receipt.tool_call_id=operation.tool_call_id
     WHERE operation.analysis_run_id=target_run_id
       AND operation.operation_kind='KNOWLEDGE_SEARCH'
       AND operation.status='SUCCEEDED'
       AND receipt.tool_name='SearchKnowledge'
       AND receipt.tool_version=2;
    IF NOT FOUND
       OR jsonb_typeof(output_json->'items') IS DISTINCT FROM 'array'
       OR jsonb_typeof(binding_json->'items') IS DISTINCT FROM 'array'
       OR jsonb_typeof(binding_json->'selected_refs') IS DISTINCT FROM 'array' THEN
        RETURN NULL;
    END IF;

    selected_refs := binding_json->'selected_refs';
    IF jsonb_array_length(binding_json->'items') NOT BETWEEN 1 AND 5
       OR jsonb_array_length(output_json->'items')<>jsonb_array_length(binding_json->'items')
       OR jsonb_array_length(selected_refs)<>LEAST(3,jsonb_array_length(binding_json->'items'))
       OR EXISTS (
            SELECT 1
              FROM jsonb_array_elements(binding_json->'items') AS entry(item)
             WHERE jsonb_typeof(item->'evidence_ref') IS DISTINCT FROM 'string'
       )
       OR EXISTS (
            SELECT 1
              FROM jsonb_array_elements(selected_refs) AS entry(value)
             WHERE jsonb_typeof(value) IS DISTINCT FROM 'string'
       )
       OR EXISTS (
            SELECT 1
              FROM jsonb_array_elements(output_json->'items') WITH ORDINALITY AS output_entry(item,ordinal)
              JOIN jsonb_array_elements(binding_json->'items') WITH ORDINALITY AS binding_entry(item,ordinal)
                USING (ordinal)
             WHERE output_entry.item->>'evidence_ref' IS DISTINCT FROM binding_entry.item->>'evidence_ref'
       ) THEN
        RETURN NULL;
    END IF;
    SELECT COALESCE(jsonb_agg(item->'evidence_ref' ORDER BY ordinal),'[]'::jsonb)
      INTO expected_refs
      FROM jsonb_array_elements(binding_json->'items') WITH ORDINALITY AS entry(item,ordinal)
     WHERE ordinal<=3;
    IF selected_refs IS DISTINCT FROM expected_refs THEN
        RETURN NULL;
    END IF;
    RETURN selected_refs;
END;
$$;


--
-- Name: workspace_analysis_source_prefix_matches(uuid, jsonb, integer); Type: FUNCTION; Schema: agent; Owner: -
--

CREATE FUNCTION agent.workspace_analysis_source_prefix_matches(target_run_id uuid, selected_refs jsonb, prefix_length integer) RETURNS boolean
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'agent', 'workflow'
    AS $$
DECLARE
    canonical_refs jsonb;
    search_receipt_id uuid;
    search_receipt_hash text;
    search_binding_json jsonb;
    source_ordinal integer;
    expected_ref text;
    search_identity jsonb;
    match_count integer;
    succeeded_count integer;
BEGIN
    canonical_refs := agent.workspace_analysis_selected_refs(target_run_id);
    IF canonical_refs IS NULL
       OR canonical_refs IS DISTINCT FROM selected_refs
       OR prefix_length<0
       OR prefix_length>jsonb_array_length(canonical_refs) THEN
        RETURN false;
    END IF;
    SELECT receipt.id,receipt.output_hash,
           convert_from(receipt.server_binding_document,'UTF8')::jsonb
      INTO search_receipt_id,search_receipt_hash,search_binding_json
      FROM agent.workspace_analysis_operation AS operation
      JOIN workflow.tool_result_receipt AS receipt
        ON receipt.id=operation.result_id
       AND receipt.tool_call_id=operation.tool_call_id
     WHERE operation.analysis_run_id=target_run_id
       AND operation.operation_kind='KNOWLEDGE_SEARCH'
       AND operation.status='SUCCEEDED';
    IF NOT FOUND THEN
        RETURN false;
    END IF;

    SELECT count(*) INTO succeeded_count
      FROM agent.workspace_analysis_operation
     WHERE analysis_run_id=target_run_id
       AND operation_kind='SOURCE_READ'
       AND status='SUCCEEDED';
    IF succeeded_count<>prefix_length THEN
        RETURN false;
    END IF;

    FOR source_ordinal IN
        SELECT generate_series(1,prefix_length)
    LOOP
        expected_ref := canonical_refs->>(source_ordinal-1);
        search_identity := search_binding_json->'items'->(source_ordinal-1);
        SELECT count(*) INTO match_count
          FROM agent.workspace_analysis_operation AS operation
          JOIN workflow.tool_result_receipt AS receipt
            ON receipt.id=operation.result_id
           AND receipt.tool_call_id=operation.tool_call_id
         WHERE operation.analysis_run_id=target_run_id
           AND operation.operation_kind='SOURCE_READ'
           AND operation.ordinal=source_ordinal
           AND operation.status='SUCCEEDED'
           AND receipt.tool_name='ReadSource'
           AND receipt.tool_version=3
           AND convert_from(receipt.output_document,'UTF8')::jsonb->>'evidence_ref'=expected_ref
           AND convert_from(receipt.server_binding_document,'UTF8')::jsonb->>'evidence_ref'=expected_ref
           AND convert_from(receipt.server_binding_document,'UTF8')::jsonb->>'search_receipt_id'=search_receipt_id::text
           AND convert_from(receipt.server_binding_document,'UTF8')::jsonb->>'search_receipt_hash'=search_receipt_hash
           AND (
                convert_from(receipt.server_binding_document,'UTF8')::jsonb
                - 'search_receipt_id' - 'search_receipt_hash'
           )=search_identity;
        IF expected_ref IS NULL OR search_identity IS NULL OR match_count<>1 THEN
            RETURN false;
        END IF;
    END LOOP;
    RETURN true;
END;
$$;


--
-- Name: workspace_analysis_operation; Type: TABLE; Schema: agent; Owner: -
--

CREATE TABLE agent.workspace_analysis_operation (
    id uuid NOT NULL,
    workspace_id uuid NOT NULL,
    analysis_run_id uuid NOT NULL,
    workflow_run_id uuid NOT NULL,
    node_run_id uuid NOT NULL,
    node_key text NOT NULL,
    operation_kind text NOT NULL,
    ordinal integer NOT NULL,
    call_kind text NOT NULL,
    request_hash text NOT NULL,
    status text NOT NULL,
    first_node_attempt_id uuid,
    latest_node_attempt_id uuid,
    model_call_id uuid,
    tool_call_id uuid,
    result_kind text,
    result_id uuid,
    result_hash text,
    error_code text,
    version bigint DEFAULT 1 NOT NULL,
    created_at timestamp with time zone NOT NULL,
    updated_at timestamp with time zone NOT NULL,
    started_at timestamp with time zone,
    completed_at timestamp with time zone,
    CONSTRAINT workspace_analysis_operation_call_kind_check CHECK ((call_kind = ANY (ARRAY['MODEL'::text, 'TOOL'::text]))),
    CONSTRAINT workspace_analysis_operation_call_pair CHECK ((((call_kind = 'MODEL'::text) AND (tool_call_id IS NULL)) OR ((call_kind = 'TOOL'::text) AND (model_call_id IS NULL)))),
    CONSTRAINT workspace_analysis_operation_error_code_check CHECK (((error_code IS NULL) OR (error_code ~ '^[A-Z][A-Z0-9_]{0,127}$'::text))),
    CONSTRAINT workspace_analysis_operation_lifecycle CHECK (((updated_at >= created_at) AND ((started_at IS NULL) OR ((started_at >= created_at) AND (started_at <= updated_at))) AND ((completed_at IS NULL) OR ((started_at IS NOT NULL) AND (completed_at >= started_at) AND (completed_at <= updated_at))) AND (((status = 'PENDING'::text) AND (first_node_attempt_id IS NULL) AND (latest_node_attempt_id IS NULL) AND (model_call_id IS NULL) AND (tool_call_id IS NULL) AND (started_at IS NULL) AND (completed_at IS NULL) AND (result_kind IS NULL) AND (result_id IS NULL) AND (result_hash IS NULL) AND (error_code IS NULL)) OR ((status = 'STARTED'::text) AND (first_node_attempt_id IS NOT NULL) AND (latest_node_attempt_id IS NOT NULL) AND (((call_kind = 'MODEL'::text) AND (model_call_id IS NOT NULL)) OR ((call_kind = 'TOOL'::text) AND (tool_call_id IS NOT NULL))) AND (started_at IS NOT NULL) AND (completed_at IS NULL) AND (result_kind IS NULL) AND (result_id IS NULL) AND (result_hash IS NULL) AND (error_code IS NULL)) OR ((status = 'SUCCEEDED'::text) AND (first_node_attempt_id IS NOT NULL) AND (latest_node_attempt_id IS NOT NULL) AND (((call_kind = 'MODEL'::text) AND (model_call_id IS NOT NULL)) OR ((call_kind = 'TOOL'::text) AND (tool_call_id IS NOT NULL))) AND (started_at IS NOT NULL) AND (completed_at IS NOT NULL) AND (result_kind IS NOT NULL) AND (result_id IS NOT NULL) AND (result_hash IS NOT NULL) AND (error_code IS NULL)) OR ((status = ANY (ARRAY['FAILED'::text, 'UNKNOWN'::text])) AND (first_node_attempt_id IS NOT NULL) AND (latest_node_attempt_id IS NOT NULL) AND (((call_kind = 'MODEL'::text) AND (model_call_id IS NOT NULL)) OR ((call_kind = 'TOOL'::text) AND (tool_call_id IS NOT NULL))) AND (started_at IS NOT NULL) AND (completed_at IS NOT NULL) AND (result_kind IS NULL) AND (result_id IS NULL) AND (result_hash IS NULL) AND (error_code IS NOT NULL))))),
    CONSTRAINT workspace_analysis_operation_ordinal_check CHECK (((ordinal >= 1) AND (ordinal <= 13))),
    CONSTRAINT workspace_analysis_operation_request_hash_check CHECK ((request_hash ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT workspace_analysis_operation_result_hash_check CHECK (((result_hash IS NULL) OR (result_hash ~ '^[0-9a-f]{64}$'::text))),
    CONSTRAINT workspace_analysis_operation_result_kind CHECK (((result_kind IS NULL) OR ((call_kind = 'TOOL'::text) AND (result_kind = 'TOOL_RESULT_RECEIPT'::text)) OR ((operation_kind = ANY (ARRAY['RETRIEVAL_PLAN'::text, 'FAITHFULNESS_REVIEW'::text])) AND (result_kind = 'MODEL_RESULT_RECEIPT'::text)) OR ((operation_kind = 'ANSWER_SYNTHESIS'::text) AND (result_kind = 'SYNTHESIS_CANDIDATE'::text)) OR ((operation_kind = 'DECISION'::text) AND (result_kind = 'DECISION_RECEIPT'::text)))),
    CONSTRAINT workspace_analysis_operation_result_kind_check CHECK (((result_kind IS NULL) OR (result_kind = ANY (ARRAY['MODEL_RESULT_RECEIPT'::text, 'TOOL_RESULT_RECEIPT'::text, 'SYNTHESIS_CANDIDATE'::text, 'DECISION_RECEIPT'::text])))),
    CONSTRAINT workspace_analysis_operation_slot CHECK ((((node_key = 'inspect_workspace'::text) AND (operation_kind = 'GIT_STATUS'::text) AND (ordinal = 1) AND (call_kind = 'TOOL'::text)) OR ((node_key = 'retrieve_evidence'::text) AND (operation_kind = 'RETRIEVAL_PLAN'::text) AND (ordinal = 1) AND (call_kind = 'MODEL'::text)) OR ((node_key = 'retrieve_evidence'::text) AND (operation_kind = 'KNOWLEDGE_SEARCH'::text) AND (ordinal = 1) AND (call_kind = 'TOOL'::text)) OR ((node_key = 'read_evidence'::text) AND (operation_kind = 'SOURCE_READ'::text) AND ((ordinal >= 1) AND (ordinal <= 3)) AND (call_kind = 'TOOL'::text)) OR ((node_key = 'synthesize_answer'::text) AND (operation_kind = 'ANSWER_SYNTHESIS'::text) AND (ordinal = 1) AND (call_kind = 'MODEL'::text)) OR ((node_key = 'validate_citations'::text) AND (operation_kind = 'CITATION_VALIDATION'::text) AND (ordinal = 1) AND (call_kind = 'TOOL'::text)) OR ((node_key = 'review_publish'::text) AND (operation_kind = 'FAITHFULNESS_REVIEW'::text) AND (ordinal = 1) AND (call_kind = 'MODEL'::text)) OR ((node_key = 'decide_next'::text) AND (operation_kind = 'DECISION'::text) AND ((ordinal >= 1) AND (ordinal <= 13)) AND (call_kind = 'MODEL'::text)) OR ((node_key = 'decide_next'::text) AND (operation_kind = ANY (ARRAY['GIT_STATUS'::text, 'KNOWLEDGE_SEARCH'::text, 'SOURCE_READ'::text, 'CITATION_VALIDATION'::text])) AND ((ordinal >= 1) AND (ordinal <= 12)) AND (call_kind = 'TOOL'::text)))),
    CONSTRAINT workspace_analysis_operation_status_check CHECK ((status = ANY (ARRAY['PENDING'::text, 'STARTED'::text, 'SUCCEEDED'::text, 'FAILED'::text, 'UNKNOWN'::text]))),
    CONSTRAINT workspace_analysis_operation_version_check CHECK ((version > 0))
);


--
-- Name: workspace_analysis_v2_budget_denied(agent.workspace_analysis_run, agent.workspace_analysis_operation, integer, integer, integer, bigint, bigint); Type: FUNCTION; Schema: agent; Owner: -
--

CREATE FUNCTION agent.workspace_analysis_v2_budget_denied(analysis agent.workspace_analysis_run, operation agent.workspace_analysis_operation, requested_models integer, requested_tools integer, requested_reads integer, requested_input bigint, requested_output bigint) RETURNS boolean
    LANGUAGE plpgsql
    AS $$
DECLARE
    expected_models integer:=0; expected_tools integer:=0; expected_reads integer:=0;
    expected_input bigint:=0; expected_output bigint:=0;
    retained_models integer:=0; retained_tools integer:=0; retained_input bigint:=0; retained_output bigint:=0;
BEGIN
    IF analysis.definition_version<>2 OR operation.status<>'PENDING' OR operation.analysis_run_id<>analysis.id THEN RETURN false; END IF;
    CASE operation.operation_kind
        WHEN 'DECISION' THEN
            expected_models:=1; expected_input:=65536; expected_output:=512;
            retained_models:=2; retained_input:=131072; retained_output:=analysis.max_output_tokens-6144;
        WHEN 'ANSWER_SYNTHESIS' THEN expected_models:=1; expected_input:=65536; expected_output:=analysis.max_output_tokens-7168;
        WHEN 'FAITHFULNESS_REVIEW' THEN expected_models:=1; expected_input:=65536; expected_output:=1024;
        WHEN 'SOURCE_READ' THEN expected_tools:=1; expected_reads:=1;
        WHEN 'GIT_STATUS','KNOWLEDGE_SEARCH','CITATION_VALIDATION' THEN expected_tools:=1;
        ELSE RETURN false;
    END CASE;
    IF requested_models IS DISTINCT FROM expected_models OR requested_tools IS DISTINCT FROM expected_tools
       OR requested_reads IS DISTINCT FROM expected_reads OR requested_input IS DISTINCT FROM expected_input
       OR requested_output IS DISTINCT FROM expected_output THEN RETURN false; END IF;
    IF operation.node_key='decide_next' AND operation.call_kind='TOOL' THEN retained_tools:=1; END IF;
    RETURN (operation.operation_kind='DECISION' AND operation.ordinal>12)
        OR (operation.operation_kind='KNOWLEDGE_SEARCH' AND (SELECT count(*) FROM agent.workspace_analysis_evidence WHERE analysis_run_id=analysis.id)>=32)
        OR requested_models+retained_models>analysis.max_model_calls-analysis.reserved_model_calls-analysis.settled_model_calls
        OR requested_tools+retained_tools>analysis.max_tool_calls-analysis.reserved_tool_calls-analysis.settled_tool_calls
        OR requested_reads>analysis.max_source_reads-analysis.reserved_source_reads-analysis.settled_source_reads
        OR requested_input+retained_input>analysis.max_input_tokens-analysis.reserved_input_tokens-analysis.settled_input_tokens
        OR requested_output+retained_output>analysis.max_output_tokens-analysis.reserved_output_tokens-analysis.settled_output_tokens;
END;
$$;


--
-- Name: workspace_analysis_v2_decision_action_kind(text); Type: FUNCTION; Schema: agent; Owner: -
--

CREATE FUNCTION agent.workspace_analysis_v2_decision_action_kind(action_value text) RETURNS text
    LANGUAGE sql IMMUTABLE STRICT
    AS $$
    SELECT CASE action_value WHEN 'git_status' THEN 'GIT_STATUS' WHEN 'knowledge_search' THEN 'KNOWLEDGE_SEARCH'
        WHEN 'source_read' THEN 'SOURCE_READ' WHEN 'citation_validation' THEN 'CITATION_VALIDATION' END
$$;


--
-- Name: workspace_analysis_v2_decision_call_bound(uuid); Type: FUNCTION; Schema: agent; Owner: -
--

CREATE FUNCTION agent.workspace_analysis_v2_decision_call_bound(target_call_id uuid) RETURNS boolean
    LANGUAGE sql STABLE
    AS $$
    SELECT COALESCE((SELECT
        operation.node_key='decide_next' AND operation.operation_kind='DECISION' AND operation.ordinal BETWEEN 1 AND 12
        AND operation.call_kind='MODEL' AND operation.request_hash=call_row.request_hash AND operation.first_node_attempt_id=model.node_attempt_id
        AND operation.workspace_id=model.workspace_id AND operation.workflow_run_id=model.workflow_run_id AND operation.node_run_id=model.node_run_id
        AND call_row.phase='AGENT' AND call_row.output_schema_id='agent.workspace-analysis-decision' AND call_row.output_schema_version='1'
        AND call_row.max_output_tokens=512 AND reservation.model_call_id=call_row.id
        AND reservation.reserved_model_calls=1 AND reservation.reserved_input_tokens=65536 AND reservation.reserved_output_tokens=512
        AND ((call_row.status='STARTED' AND model.status='RUNNING' AND operation.status='STARTED' AND reservation.status='RESERVED' AND decision.id IS NULL)
          OR (call_row.status='SUCCEEDED' AND operation.status='SUCCEEDED' AND reservation.status='SETTLED'
              AND reservation.settled_input_tokens=call_row.input_tokens AND reservation.settled_output_tokens=call_row.output_tokens
              AND decision.id=operation.result_id AND operation.result_kind='DECISION_RECEIPT' AND operation.result_hash=decision.document_hash
              AND decision.model_run_id=model.id AND decision.model_call_id=call_row.id AND decision.node_attempt_id=model.node_attempt_id
              AND decision.workspace_id=model.workspace_id AND decision.analysis_run_id=operation.analysis_run_id AND decision.ordinal=operation.ordinal
              AND decision.document_hash=call_row.response_hash AND decision.document_bytes=call_row.response_bytes AND decision.created_at=call_row.completed_at)
          OR (call_row.status='FAILED' AND operation.status='FAILED' AND reservation.status='SETTLED' AND decision.id IS NULL
              AND operation.error_code=call_row.error_code AND reservation.settled_input_tokens=call_row.input_tokens AND reservation.settled_output_tokens=call_row.output_tokens)
          OR (call_row.status='UNKNOWN' AND operation.status='UNKNOWN' AND reservation.status='UNKNOWN_CHARGED' AND decision.id IS NULL
              AND operation.error_code=call_row.error_code AND reservation.settled_input_tokens=reservation.reserved_input_tokens
              AND reservation.settled_output_tokens=reservation.reserved_output_tokens))
      FROM agent.model_call call_row
      JOIN agent.model_run model ON model.id=call_row.model_run_id
      JOIN agent.workspace_analysis_operation operation ON operation.model_call_id=call_row.id
      JOIN agent.workspace_analysis_run analysis ON analysis.id=operation.analysis_run_id AND analysis.definition_version=2
      JOIN agent.workspace_analysis_journal journal ON journal.operation_id=operation.id AND journal.analysis_run_id=analysis.id
      JOIN agent.workspace_analysis_budget_reservation reservation ON reservation.operation_id=operation.id AND reservation.analysis_run_id=analysis.id
      LEFT JOIN agent.workspace_analysis_decision decision ON decision.operation_id=operation.id
      WHERE call_row.id=target_call_id),false)
$$;


--
-- Name: workspace_analysis_v2_decisions_complete(uuid); Type: FUNCTION; Schema: agent; Owner: -
--

CREATE FUNCTION agent.workspace_analysis_v2_decisions_complete(target_run_id uuid) RETURNS boolean
    LANGUAGE plpgsql
    AS $$
DECLARE total_decisions integer; total_tools integer;
BEGIN
    IF NOT EXISTS (SELECT 1 FROM agent.workspace_analysis_run WHERE id=target_run_id AND definition_version=2) THEN RETURN false; END IF;
    SELECT count(*) FILTER (WHERE operation_kind='DECISION'),count(*) FILTER (WHERE call_kind='TOOL') INTO total_decisions,total_tools
      FROM agent.workspace_analysis_operation WHERE analysis_run_id=target_run_id AND node_key='decide_next';
    IF total_decisions NOT BETWEEN 1 AND 12 OR total_decisions<>total_tools+1
       OR (SELECT count(*) FROM agent.workspace_analysis_decision WHERE analysis_run_id=target_run_id AND convert_from(document,'UTF8')::jsonb->>'action'='finish')<>1
       OR EXISTS (SELECT 1 FROM agent.workspace_analysis_operation WHERE analysis_run_id=target_run_id AND node_key='decide_next'
           AND (status<>'SUCCEEDED' OR NOT agent.workspace_analysis_v2_operation_predecessor(id)))
       OR EXISTS (SELECT 1 FROM agent.model_run model JOIN agent.workspace_analysis_run analysis
            ON analysis.workflow_run_id=model.workflow_run_id AND analysis.workspace_id=model.workspace_id
            WHERE analysis.id=target_run_id AND model.output_schema_id='agent.workspace-analysis-decision'
                AND (model.status<>'SUCCEEDED' OR model.final_result_type IS DISTINCT FROM 'workspace_analysis_decision')) THEN RETURN false; END IF;
    RETURN NOT EXISTS (SELECT 1 FROM agent.workspace_analysis_operation operation WHERE analysis_run_id=target_run_id AND operation_kind='DECISION'
        AND NOT agent.workspace_analysis_v2_decision_call_bound(operation.model_call_id));
END;
$$;


--
-- Name: workspace_analysis_v2_final_validation_bound(uuid); Type: FUNCTION; Schema: agent; Owner: -
--

CREATE FUNCTION agent.workspace_analysis_v2_final_validation_bound(target_run_id uuid) RETURNS boolean
    LANGUAGE plpgsql
    AS $$
DECLARE
    candidate agent.workspace_analysis_candidate%ROWTYPE;
    receipt workflow.tool_result_receipt%ROWTYPE;
    refs jsonb; output_json jsonb; binding_json jsonb;
BEGIN
    SELECT * INTO candidate FROM agent.workspace_analysis_candidate WHERE analysis_run_id=target_run_id AND schema_version=2;
    SELECT result.* INTO receipt FROM agent.workspace_analysis_operation operation
      JOIN workflow.tool_result_receipt result ON result.id=operation.result_id AND result.tool_call_id=operation.tool_call_id AND result.output_hash=operation.result_hash
      WHERE operation.analysis_run_id=target_run_id AND operation.node_key='validate_citations' AND operation.operation_kind='CITATION_VALIDATION'
        AND operation.ordinal=1 AND operation.status='SUCCEEDED' AND result.workspace_id=operation.workspace_id AND result.workflow_run_id=operation.workflow_run_id
        AND result.tool_name='ValidateCitation' AND result.tool_version=4;
    IF candidate.id IS NULL OR receipt.id IS NULL OR NOT EXISTS (SELECT 1 FROM agent.workspace_analysis_operation
        WHERE id=candidate.synthesis_operation_id AND status='SUCCEEDED' AND result_id=candidate.id AND result_hash=candidate.document_hash) THEN RETURN false; END IF;
    refs:=convert_from(candidate.document,'UTF8')::jsonb#>'{payload,citation_refs}';
    output_json:=convert_from(receipt.output_document,'UTF8')::jsonb;
    binding_json:=convert_from(receipt.server_binding_document,'UTF8')::jsonb;
    IF NOT agent.workspace_analysis_v2_refs_valid(refs,8)
       OR jsonb_typeof(output_json->'results') IS DISTINCT FROM 'array' OR jsonb_typeof(binding_json->'results') IS DISTINCT FROM 'array'
       OR binding_json->>'candidate_id' IS DISTINCT FROM candidate.id::text OR binding_json->>'candidate_hash' IS DISTINCT FROM candidate.document_hash THEN RETURN false; END IF;
    IF jsonb_array_length(output_json->'results')<>jsonb_array_length(refs) OR jsonb_array_length(binding_json->'results')<>jsonb_array_length(refs)
       OR refs IS DISTINCT FROM (SELECT jsonb_agg(item->'evidence_ref' ORDER BY ordinal) FROM jsonb_array_elements(output_json->'results') WITH ORDINALITY rows(item,ordinal))
       OR refs IS DISTINCT FROM (SELECT jsonb_agg(item->'evidence_ref' ORDER BY ordinal) FROM jsonb_array_elements(binding_json->'results') WITH ORDINALITY rows(item,ordinal))
       OR EXISTS (SELECT 1 FROM jsonb_array_elements_text(refs) ref WHERE NOT agent.workspace_analysis_v2_ref_read(target_run_id,ref))
       OR EXISTS (SELECT 1 FROM jsonb_array_elements(binding_json->'results') item WHERE NOT EXISTS (
            SELECT 1 FROM agent.workspace_analysis_operation operation JOIN workflow.tool_result_receipt source ON source.id=operation.result_id AND source.tool_call_id=operation.tool_call_id
            WHERE operation.analysis_run_id=target_run_id AND operation.node_key='decide_next' AND operation.operation_kind='SOURCE_READ' AND operation.status='SUCCEEDED'
              AND source.id::text=item->>'read_receipt_id' AND source.output_hash=item->>'read_receipt_hash' AND source.output_hash=operation.result_hash
              AND source.workspace_id=receipt.workspace_id AND source.workflow_run_id=receipt.workflow_run_id AND source.tool_name='ReadSource' AND source.tool_version=4
              AND convert_from(source.server_binding_document,'UTF8')::jsonb=item-ARRAY['read_receipt_id','read_receipt_hash']
              AND convert_from(source.output_document,'UTF8')::jsonb->'truncated'='false'::jsonb
       )) THEN RETURN false; END IF;
    RETURN true;
END;
$$;


--
-- Name: workspace_analysis_v2_has_readable_evidence(uuid); Type: FUNCTION; Schema: agent; Owner: -
--

CREATE FUNCTION agent.workspace_analysis_v2_has_readable_evidence(target_run_id uuid) RETURNS boolean
    LANGUAGE sql STABLE
    AS $$
    SELECT EXISTS (
        SELECT 1 FROM agent.workspace_analysis_operation operation
        JOIN workflow.tool_result_receipt receipt ON receipt.id=operation.result_id AND receipt.tool_call_id=operation.tool_call_id
          AND receipt.output_hash=operation.result_hash AND receipt.workspace_id=operation.workspace_id AND receipt.workflow_run_id=operation.workflow_run_id
        WHERE operation.analysis_run_id=target_run_id AND operation.node_key='decide_next'
          AND operation.operation_kind='SOURCE_READ' AND operation.status='SUCCEEDED'
          AND receipt.tool_name='ReadSource' AND receipt.tool_version=4
          AND convert_from(receipt.output_document,'UTF8')::jsonb->'truncated'='false'::jsonb
          AND agent.workspace_analysis_v2_ref_read(target_run_id,convert_from(receipt.output_document,'UTF8')::jsonb->>'evidence_ref')
    )
$$;


--
-- Name: workspace_analysis_v2_operation_predecessor(uuid); Type: FUNCTION; Schema: agent; Owner: -
--

CREATE FUNCTION agent.workspace_analysis_v2_operation_predecessor(target_operation_id uuid) RETURNS boolean
    LANGUAGE plpgsql
    AS $$
DECLARE
    op agent.workspace_analysis_operation%ROWTYPE;
    previous agent.workspace_analysis_operation%ROWTYPE;
    decision agent.workspace_analysis_decision%ROWTYPE;
    seq bigint;
    action_value text;
BEGIN
    SELECT * INTO op FROM agent.workspace_analysis_operation WHERE id=target_operation_id;
    IF op.id IS NULL OR NOT EXISTS (SELECT 1 FROM agent.workspace_analysis_run WHERE id=op.analysis_run_id AND definition_version=2) THEN RETURN false; END IF;
    SELECT sequence INTO seq FROM agent.workspace_analysis_journal WHERE operation_id=op.id;
    IF seq IS NULL THEN SELECT COALESCE(max(sequence),0)+1 INTO seq FROM agent.workspace_analysis_journal WHERE analysis_run_id=op.analysis_run_id; END IF;
    IF seq=1 THEN RETURN op.node_key='decide_next' AND op.operation_kind='DECISION' AND op.ordinal=1; END IF;
    SELECT operation.* INTO previous FROM agent.workspace_analysis_journal journal
        JOIN agent.workspace_analysis_operation operation ON operation.id=journal.operation_id
        WHERE journal.analysis_run_id=op.analysis_run_id AND journal.sequence=seq-1;
    IF previous.id IS NULL OR previous.status<>'SUCCEEDED' THEN RETURN false; END IF;
    IF op.node_key='decide_next' AND op.operation_kind='DECISION' THEN
        RETURN previous.node_key='decide_next' AND previous.call_kind='TOOL' AND op.ordinal=previous.ordinal+1;
    ELSIF op.node_key='decide_next' AND op.call_kind='TOOL' THEN
        SELECT * INTO decision FROM agent.workspace_analysis_decision WHERE operation_id=previous.id;
        action_value:=convert_from(decision.document,'UTF8')::jsonb->>'action';
        RETURN previous.node_key='decide_next' AND previous.operation_kind='DECISION' AND previous.ordinal=op.ordinal
            AND decision.id IS NOT NULL AND agent.workspace_analysis_v2_decision_action_kind(action_value)=op.operation_kind;
    ELSIF op.node_key='synthesize_answer' AND op.operation_kind='ANSWER_SYNTHESIS' THEN
        SELECT * INTO decision FROM agent.workspace_analysis_decision WHERE operation_id=previous.id;
        RETURN previous.node_key='decide_next' AND previous.operation_kind='DECISION' AND decision.id IS NOT NULL
            AND convert_from(decision.document,'UTF8')::jsonb->>'action'='finish'
            AND EXISTS (SELECT 1 FROM agent.workspace_analysis_operation WHERE analysis_run_id=op.analysis_run_id
                AND node_key='decide_next' AND operation_kind='SOURCE_READ' AND status='SUCCEEDED');
    ELSIF op.node_key='validate_citations' AND op.operation_kind='CITATION_VALIDATION' THEN
        RETURN previous.node_key='synthesize_answer' AND previous.operation_kind='ANSWER_SYNTHESIS'
            AND EXISTS (SELECT 1 FROM agent.workspace_analysis_candidate WHERE synthesis_operation_id=previous.id AND schema_version=2);
    ELSIF op.node_key='review_publish' AND op.operation_kind='FAITHFULNESS_REVIEW' THEN
        RETURN previous.node_key='validate_citations' AND previous.operation_kind='CITATION_VALIDATION'
            AND agent.workspace_analysis_validation_all_valid(op.analysis_run_id);
    END IF;
    RETURN false;
END;
$$;


--
-- Name: workspace_analysis_v2_ref_read(uuid, text); Type: FUNCTION; Schema: agent; Owner: -
--

CREATE FUNCTION agent.workspace_analysis_v2_ref_read(target_run_id uuid, reference_value text) RETURNS boolean
    LANGUAGE sql STABLE
    AS $$
    SELECT EXISTS (
        SELECT 1 FROM agent.workspace_analysis_evidence evidence
        JOIN agent.workspace_analysis_run analysis ON analysis.id=evidence.analysis_run_id AND analysis.definition_version=2
        JOIN agent.workspace_analysis_operation operation ON operation.analysis_run_id=analysis.id AND operation.workspace_id=analysis.workspace_id
            AND operation.node_key='decide_next' AND operation.operation_kind='SOURCE_READ' AND operation.status='SUCCEEDED'
        JOIN workflow.tool_result_receipt receipt ON receipt.id=operation.result_id AND receipt.tool_call_id=operation.tool_call_id
            AND receipt.workspace_id=analysis.workspace_id AND receipt.workflow_run_id=analysis.workflow_run_id
            AND receipt.tool_name='ReadSource' AND receipt.tool_version=4 AND receipt.output_hash=operation.result_hash
        WHERE evidence.analysis_run_id=target_run_id AND 'E'||evidence.reference_no::text=reference_value
          AND convert_from(receipt.server_binding_document,'UTF8')::jsonb=jsonb_build_object(
            'search_receipt_id',evidence.search_receipt_id::text,'search_receipt_hash',evidence.search_receipt_hash,
            'search_evidence_ref',evidence.local_evidence_ref,'evidence_ref',reference_value,'citation_id',evidence.citation_id,
            'index_version_id',evidence.index_version_id::text,'chunk_id',evidence.chunk_id::text,
            'source_version_id',evidence.source_version_id::text,'source_span_id',evidence.source_span_id::text,'content_hash',evidence.content_hash)
          AND convert_from(receipt.output_document,'UTF8')::jsonb->>'evidence_ref'=reference_value
    )
$$;


--
-- Name: workspace_analysis_v2_refs_valid(jsonb, integer); Type: FUNCTION; Schema: agent; Owner: -
--

CREATE FUNCTION agent.workspace_analysis_v2_refs_valid(refs jsonb, maximum_count integer) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    AS $_$
    SELECT COALESCE(jsonb_typeof(refs)='array' AND jsonb_array_length(refs) BETWEEN 1 AND maximum_count
        AND NOT EXISTS (SELECT 1 FROM jsonb_array_elements(refs) item
                        WHERE jsonb_typeof(item)<>'string' OR item#>>'{}' !~ '^E([1-9]|[12][0-9]|3[0-2])$')
        AND (SELECT count(DISTINCT item#>>'{}') FROM jsonb_array_elements(refs) item)=jsonb_array_length(refs),false)
$_$;


--
-- Name: workspace_analysis_v2_uncalled_pending(uuid); Type: FUNCTION; Schema: agent; Owner: -
--

CREATE FUNCTION agent.workspace_analysis_v2_uncalled_pending(target_operation_id uuid) RETURNS boolean
    LANGUAGE sql STABLE
    AS $$
    SELECT EXISTS (
        SELECT 1 FROM agent.workspace_analysis_operation operation
        JOIN agent.workspace_analysis_run analysis ON analysis.id=operation.analysis_run_id AND analysis.definition_version=2
        JOIN agent.workspace_analysis_journal journal ON journal.operation_id=operation.id
        WHERE operation.id=target_operation_id AND operation.status='PENDING'
          AND operation.model_call_id IS NULL AND operation.tool_call_id IS NULL
          AND operation.first_node_attempt_id IS NULL AND operation.latest_node_attempt_id IS NULL
          AND NOT EXISTS (SELECT 1 FROM agent.workspace_analysis_budget_reservation WHERE operation_id=operation.id)
          AND journal.sequence=(SELECT max(last.sequence) FROM agent.workspace_analysis_journal last WHERE last.analysis_run_id=operation.analysis_run_id)
          AND NOT EXISTS (SELECT 1 FROM agent.workspace_analysis_operation prior
              WHERE prior.analysis_run_id=operation.analysis_run_id AND prior.id<>operation.id AND prior.status<>'SUCCEEDED')
    )
$$;


--
-- Name: workspace_analysis_v2_validation_all_valid(uuid); Type: FUNCTION; Schema: agent; Owner: -
--

CREATE FUNCTION agent.workspace_analysis_v2_validation_all_valid(target_run_id uuid) RETURNS boolean
    LANGUAGE plpgsql
    AS $$
DECLARE
    candidate agent.workspace_analysis_candidate%ROWTYPE;
    receipt workflow.tool_result_receipt%ROWTYPE;
    refs jsonb; output_json jsonb; binding_json jsonb;
BEGIN
    SELECT * INTO candidate FROM agent.workspace_analysis_candidate WHERE analysis_run_id=target_run_id AND schema_version=2;
    SELECT result.* INTO receipt FROM agent.workspace_analysis_operation operation
      JOIN workflow.tool_result_receipt result ON result.id=operation.result_id AND result.tool_call_id=operation.tool_call_id AND result.output_hash=operation.result_hash
      WHERE operation.analysis_run_id=target_run_id AND operation.node_key='validate_citations' AND operation.operation_kind='CITATION_VALIDATION'
        AND operation.ordinal=1 AND operation.status='SUCCEEDED' AND result.workspace_id=operation.workspace_id AND result.workflow_run_id=operation.workflow_run_id
        AND result.tool_name='ValidateCitation' AND result.tool_version=4;
    IF candidate.id IS NULL OR receipt.id IS NULL OR NOT EXISTS (SELECT 1 FROM agent.workspace_analysis_operation
        WHERE id=candidate.synthesis_operation_id AND status='SUCCEEDED' AND result_id=candidate.id AND result_hash=candidate.document_hash) THEN RETURN false; END IF;
    refs:=convert_from(candidate.document,'UTF8')::jsonb#>'{payload,citation_refs}';
    output_json:=convert_from(receipt.output_document,'UTF8')::jsonb;
    binding_json:=convert_from(receipt.server_binding_document,'UTF8')::jsonb;
    IF NOT agent.workspace_analysis_v2_refs_valid(refs,8)
       OR jsonb_typeof(output_json->'results') IS DISTINCT FROM 'array' OR jsonb_typeof(binding_json->'results') IS DISTINCT FROM 'array'
       OR binding_json->>'candidate_id' IS DISTINCT FROM candidate.id::text OR binding_json->>'candidate_hash' IS DISTINCT FROM candidate.document_hash THEN RETURN false; END IF;
    IF jsonb_array_length(output_json->'results')<>jsonb_array_length(refs) OR jsonb_array_length(binding_json->'results')<>jsonb_array_length(refs)
       OR refs IS DISTINCT FROM (SELECT jsonb_agg(item->'evidence_ref' ORDER BY ordinal) FROM jsonb_array_elements(output_json->'results') WITH ORDINALITY rows(item,ordinal))
       OR refs IS DISTINCT FROM (SELECT jsonb_agg(item->'evidence_ref' ORDER BY ordinal) FROM jsonb_array_elements(binding_json->'results') WITH ORDINALITY rows(item,ordinal))
       OR EXISTS (SELECT 1 FROM jsonb_array_elements(output_json->'results') item WHERE item->'valid' IS DISTINCT FROM 'true'::jsonb OR item->>'reason_code' IS DISTINCT FROM 'OK')
       OR EXISTS (SELECT 1 FROM jsonb_array_elements_text(refs) ref WHERE NOT agent.workspace_analysis_v2_ref_read(target_run_id,ref))
       OR EXISTS (SELECT 1 FROM jsonb_array_elements(binding_json->'results') item WHERE NOT EXISTS (
            SELECT 1 FROM agent.workspace_analysis_operation operation JOIN workflow.tool_result_receipt source ON source.id=operation.result_id AND source.tool_call_id=operation.tool_call_id
            WHERE operation.analysis_run_id=target_run_id AND operation.node_key='decide_next' AND operation.operation_kind='SOURCE_READ' AND operation.status='SUCCEEDED'
              AND source.id::text=item->>'read_receipt_id' AND source.output_hash=item->>'read_receipt_hash' AND source.output_hash=operation.result_hash
              AND source.workspace_id=receipt.workspace_id AND source.workflow_run_id=receipt.workflow_run_id AND source.tool_name='ReadSource' AND source.tool_version=4
              AND convert_from(source.server_binding_document,'UTF8')::jsonb=item-ARRAY['read_receipt_id','read_receipt_hash']
       )) THEN RETURN false; END IF;
    RETURN true;
END;
$$;


--
-- Name: workspace_analysis_validation_all_valid(uuid); Type: FUNCTION; Schema: agent; Owner: -
--

CREATE FUNCTION agent.workspace_analysis_validation_all_valid(target_run_id uuid) RETURNS boolean
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'agent', 'workflow'
    AS $$
DECLARE
    candidate_row agent.workspace_analysis_candidate%ROWTYPE;
    validation_receipt workflow.tool_result_receipt%ROWTYPE;
    candidate_json jsonb;
    output_json jsonb;
    binding_json jsonb;
    search_binding_json jsonb;
    candidate_refs jsonb;
    selected_refs jsonb;
BEGIN
    IF EXISTS (SELECT 1 FROM agent.workspace_analysis_run WHERE id=target_run_id AND definition_version=2) THEN
        RETURN agent.workspace_analysis_v2_validation_all_valid(target_run_id);
    END IF;
    SELECT * INTO candidate_row
      FROM agent.workspace_analysis_candidate
     WHERE analysis_run_id=target_run_id;
    SELECT receipt.* INTO validation_receipt
      FROM agent.workspace_analysis_operation AS operation
      JOIN workflow.tool_result_receipt AS receipt
        ON receipt.id=operation.result_id
       AND receipt.tool_call_id=operation.tool_call_id
     WHERE operation.analysis_run_id=target_run_id
       AND operation.operation_kind='CITATION_VALIDATION'
       AND operation.status='SUCCEEDED'
       AND receipt.tool_name='ValidateCitation'
       AND receipt.tool_version=3;
    SELECT convert_from(receipt.server_binding_document,'UTF8')::jsonb
      INTO search_binding_json
      FROM agent.workspace_analysis_operation AS operation
      JOIN workflow.tool_result_receipt AS receipt
        ON receipt.id=operation.result_id
       AND receipt.tool_call_id=operation.tool_call_id
     WHERE operation.analysis_run_id=target_run_id
       AND operation.operation_kind='KNOWLEDGE_SEARCH'
       AND operation.status='SUCCEEDED';
    IF candidate_row.id IS NULL OR validation_receipt.id IS NULL OR search_binding_json IS NULL
       OR NOT EXISTS (
            SELECT 1 FROM agent.workspace_analysis_operation
             WHERE id=candidate_row.synthesis_operation_id
               AND analysis_run_id=target_run_id
               AND operation_kind='ANSWER_SYNTHESIS'
               AND status='SUCCEEDED'
               AND result_id=candidate_row.id
               AND result_hash=candidate_row.document_hash
       ) THEN
        RETURN false;
    END IF;

    selected_refs := agent.workspace_analysis_selected_refs(target_run_id);
    IF selected_refs IS NULL
       OR NOT agent.workspace_analysis_source_prefix_matches(
            target_run_id,selected_refs,jsonb_array_length(selected_refs)
       ) THEN
        RETURN false;
    END IF;
    candidate_json := convert_from(candidate_row.document,'UTF8')::jsonb;
    output_json := convert_from(validation_receipt.output_document,'UTF8')::jsonb;
    binding_json := convert_from(validation_receipt.server_binding_document,'UTF8')::jsonb;
    candidate_refs := candidate_json#>'{payload,citation_refs}';
    IF jsonb_typeof(candidate_refs) IS DISTINCT FROM 'array'
       OR jsonb_typeof(output_json->'results') IS DISTINCT FROM 'array'
       OR jsonb_typeof(binding_json->'results') IS DISTINCT FROM 'array'
       OR binding_json->>'candidate_id' IS DISTINCT FROM candidate_row.id::text
       OR binding_json->>'candidate_hash' IS DISTINCT FROM candidate_row.document_hash THEN
        RETURN false;
    END IF;
    IF jsonb_array_length(candidate_refs)<1
       OR jsonb_array_length(candidate_refs)>jsonb_array_length(selected_refs)
       OR jsonb_array_length(output_json->'results')<>jsonb_array_length(candidate_refs)
       OR jsonb_array_length(binding_json->'results')<>jsonb_array_length(candidate_refs)
       OR candidate_refs IS DISTINCT FROM (
            SELECT COALESCE(jsonb_agg(item->'evidence_ref' ORDER BY ordinal),'[]'::jsonb)
              FROM jsonb_array_elements(output_json->'results') WITH ORDINALITY AS entry(item,ordinal)
       )
       OR candidate_refs IS DISTINCT FROM (
            SELECT COALESCE(jsonb_agg(item->'evidence_ref' ORDER BY ordinal),'[]'::jsonb)
              FROM jsonb_array_elements(binding_json->'results') WITH ORDINALITY AS entry(item,ordinal)
       )
       OR EXISTS (
            SELECT 1
              FROM jsonb_array_elements(candidate_refs) AS candidate_ref(value)
             WHERE NOT (selected_refs @> jsonb_build_array(value))
       )
       OR EXISTS (
            SELECT 1
              FROM jsonb_array_elements(output_json->'results') AS entry(item)
             WHERE item->'valid' IS DISTINCT FROM 'true'::jsonb
                OR item->>'reason_code' IS DISTINCT FROM 'OK'
       )
       OR EXISTS (
            SELECT 1
              FROM jsonb_array_elements(binding_json->'results') AS validation_entry(item)
             WHERE NOT EXISTS (
                SELECT 1
                  FROM jsonb_array_elements(search_binding_json->'items') AS search_entry(item)
                 WHERE search_entry.item=validation_entry.item
             )
       ) THEN
        RETURN false;
    END IF;
    RETURN true;
END;
$$;


--
-- Name: guard_document_publication_path(); Type: FUNCTION; Schema: authoring; Owner: -
--

CREATE FUNCTION authoring.guard_document_publication_path() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    exact_publication_fact boolean;
BEGIN
    IF NEW.canonical_path IS DISTINCT FROM OLD.canonical_path
       AND (OLD.lifecycle_status='PUBLISHED' OR NEW.lifecycle_status='PUBLISHED'
           OR OLD.current_published_revision_id IS NOT NULL
           OR NEW.current_published_revision_id IS NOT NULL
           OR EXISTS (
               SELECT 1 FROM authoring.document_publication_reservation reservation
               WHERE reservation.workspace_id=OLD.workspace_id
                 AND reservation.document_id=OLD.id AND reservation.status='PENDING'
           )
           OR EXISTS (
               SELECT 1 FROM authoring.document_publication_binding binding
               WHERE binding.workspace_id=OLD.workspace_id
                 AND binding.document_id=OLD.id
                 AND binding.status IN ('PENDING','RECOVERY_REQUIRED')
           )
           OR EXISTS (
               SELECT 1 FROM authoring.document_restore_publication restore
               WHERE restore.workspace_id=OLD.workspace_id AND restore.document_id=OLD.id
           )
       ) THEN
       RAISE EXCEPTION 'document path cannot change during publication' USING ERRCODE='23514';
    END IF;
    IF NEW.lifecycle_status='PUBLISHED'
       AND (OLD.lifecycle_status IS DISTINCT FROM NEW.lifecycle_status
            OR OLD.current_published_revision_id IS DISTINCT FROM NEW.current_published_revision_id) THEN
        SELECT EXISTS (
            SELECT 1
              FROM core.article_revision revision
              JOIN authoring.document_publication_binding binding
                ON binding.workspace_id=revision.workspace_id
               AND binding.document_id=revision.document_id
               AND binding.article_revision_id=revision.id
              JOIN change_control.proposal_commit commit_mapping
                ON commit_mapping.proposal_id=binding.proposal_id
               AND commit_mapping.revision_id=binding.proposal_revision_id
             WHERE revision.id=NEW.current_published_revision_id
               AND revision.workspace_id=NEW.workspace_id
               AND revision.document_id=NEW.id
               AND revision.status='PUBLISHED'
               AND revision.git_commit IS NOT NULL
               AND binding.target_path=NEW.canonical_path
               AND binding.content_hash=revision.content_hash
               AND binding.status IN ('PENDING','RECOVERY_REQUIRED')
               AND commit_mapping.workspace_id=binding.workspace_id
               AND commit_mapping.target_path=binding.target_path
               AND commit_mapping.target_mode=binding.target_mode
               AND commit_mapping.result_hash=binding.content_hash
               AND commit_mapping.git_commit=revision.git_commit
        ) INTO exact_publication_fact;
        IF NOT exact_publication_fact THEN
            SELECT EXISTS (
                SELECT 1
                  FROM core.article_revision revision
                  JOIN authoring.document_restore_publication restore
                    ON restore.article_revision_id=revision.id
                   AND restore.workspace_id=revision.workspace_id
                   AND restore.document_id=revision.document_id
                 WHERE revision.id=NEW.current_published_revision_id
                   AND revision.workspace_id=NEW.workspace_id
                   AND revision.document_id=NEW.id
                   AND revision.status='PUBLISHED'
                   AND revision.git_commit=restore.git_commit
                   AND revision.content_hash=restore.target_content_hash
                   AND restore.target_path=NEW.canonical_path
            ) INTO exact_publication_fact;
        END IF;
        IF NOT exact_publication_fact THEN
            RAISE EXCEPTION 'document publication requires an exact published revision and proposal commit' USING ERRCODE='23514';
        END IF;
    END IF;
    RETURN NEW;
END;
$$;


--
-- Name: publication_is_exact_current(uuid, uuid, uuid); Type: FUNCTION; Schema: authoring; Owner: -
--

CREATE FUNCTION authoring.publication_is_exact_current(checked_workspace_id uuid, checked_document_id uuid, checked_revision_id uuid) RETURNS boolean
    LANGUAGE sql STABLE
    AS $$
    SELECT EXISTS (
        SELECT 1
          FROM core.document document
          JOIN core.article_revision article
            ON article.id=checked_revision_id
           AND article.workspace_id=checked_workspace_id
           AND article.document_id=checked_document_id
          JOIN authoring.document_publication_binding binding
            ON binding.workspace_id=article.workspace_id
           AND binding.document_id=article.document_id
           AND binding.article_revision_id=article.id
          JOIN authoring.document_publication_reservation reservation
            ON reservation.id=binding.reservation_id
          JOIN change_control.proposal proposal
            ON proposal.id=binding.proposal_id
          JOIN change_control.proposal_revision proposal_revision
            ON proposal_revision.id=binding.proposal_revision_id
           AND proposal_revision.proposal_id=proposal.id
          JOIN change_control.proposal_commit commit_mapping
            ON commit_mapping.workspace_id=binding.workspace_id
           AND commit_mapping.proposal_id=binding.proposal_id
           AND commit_mapping.revision_id=binding.proposal_revision_id
         WHERE document.id=checked_document_id
           AND document.workspace_id=checked_workspace_id
           AND document.lifecycle_status='PUBLISHED'
           AND document.current_published_revision_id=article.id
           AND document.canonical_path=binding.target_path
           AND article.status='PUBLISHED'
           AND article.git_commit IS NOT NULL
           AND article.git_commit=binding.git_commit
           AND article.content_hash=binding.content_hash
           AND binding.status='PUBLISHED'
           AND binding.error_code=''
           AND binding.published_at IS NOT NULL
           AND reservation.status='CLOSED'
           AND reservation.workspace_id=binding.workspace_id
           AND reservation.document_id=binding.document_id
           AND reservation.article_revision_id=binding.article_revision_id
           AND reservation.target_path=binding.target_path
           AND reservation.content_hash=binding.content_hash
           AND reservation.target_mode=binding.target_mode
           AND reservation.absence_token=binding.absence_token
           AND proposal.workspace_id=binding.workspace_id
           AND proposal.proposal_type='file_patch'
           AND proposal.idempotency_key=reservation.proposal_idempotency_key
           AND proposal.status IN ('verifying','completed')
           AND proposal_revision.target_path=binding.target_path
           AND proposal_revision.target_mode=binding.target_mode
           AND proposal_revision.base_hash=reservation.base_version
           AND proposal_revision.content=article.content
           AND encode(sha256(convert_to(proposal_revision.content,'UTF8')),'hex')=binding.content_hash
           AND commit_mapping.target_path=binding.target_path
           AND commit_mapping.target_mode=binding.target_mode
           AND commit_mapping.result_hash=binding.content_hash
           AND commit_mapping.git_commit=binding.git_commit
    );
$$;


--
-- Name: reject_immutable_mutation(); Type: FUNCTION; Schema: authoring; Owner: -
--

CREATE FUNCTION authoring.reject_immutable_mutation() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    RAISE EXCEPTION 'authoring immutable fact cannot be mutated' USING ERRCODE='55000';
END;
$$;


--
-- Name: restore_publication_is_exact_current(uuid, uuid, uuid); Type: FUNCTION; Schema: authoring; Owner: -
--

CREATE FUNCTION authoring.restore_publication_is_exact_current(checked_workspace_id uuid, checked_document_id uuid, checked_revision_id uuid) RETURNS boolean
    LANGUAGE sql STABLE
    AS $$
    SELECT EXISTS (
        SELECT 1
          FROM core.document document
          JOIN core.article_revision revision
            ON revision.id=checked_revision_id
           AND revision.workspace_id=checked_workspace_id
           AND revision.document_id=checked_document_id
          JOIN authoring.document_restore_publication restore
            ON restore.article_revision_id=revision.id
           AND restore.workspace_id=revision.workspace_id
           AND restore.document_id=revision.document_id
          JOIN change_control.proposal proposal
            ON proposal.id=restore.proposal_id
           AND proposal.workspace_id=restore.workspace_id
          JOIN change_control.proposal_commit commit_mapping
            ON commit_mapping.id=restore.proposal_commit_id
           AND commit_mapping.writeback_execution_id=restore.writeback_execution_id
         WHERE document.id=checked_document_id
           AND document.workspace_id=checked_workspace_id
           AND document.lifecycle_status='PUBLISHED'
           AND document.current_published_revision_id=revision.id
           AND document.canonical_path=restore.target_path
           AND document.version=restore.expected_document_version+1
           AND revision.status='PUBLISHED'
           AND revision.content_hash=restore.target_content_hash
           AND revision.git_commit=restore.git_commit
           AND proposal.proposal_type='restore_document'
           AND proposal.status IN ('verifying','completed')
           AND commit_mapping.proposal_id=restore.proposal_id
           AND commit_mapping.revision_id=restore.proposal_revision_id
           AND commit_mapping.workspace_id=restore.workspace_id
           AND commit_mapping.target_path=restore.target_path
           AND commit_mapping.target_mode='REPLACE'
           AND commit_mapping.result_hash=restore.target_content_hash
           AND commit_mapping.git_commit=restore.git_commit
    );
$$;


--
-- Name: validate_article_revision_mutation(); Type: FUNCTION; Schema: authoring; Owner: -
--

CREATE FUNCTION authoring.validate_article_revision_mutation() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    exact_publication_fact boolean;
BEGIN
    IF TG_OP='INSERT' THEN
        IF NEW.status='PUBLISHED' AND NEW.git_commit IS NOT NULL THEN
            SELECT EXISTS (
                SELECT 1 FROM authoring.document_restore_publication restore
                 WHERE restore.article_revision_id=NEW.id
                   AND restore.workspace_id=NEW.workspace_id
                   AND restore.document_id=NEW.document_id
                   AND restore.target_content_hash=NEW.content_hash
                   AND restore.git_commit=NEW.git_commit
            ) INTO exact_publication_fact;
            IF NOT exact_publication_fact THEN
                RAISE EXCEPTION 'published restore revision requires an exact restore publication' USING ERRCODE='23514';
            END IF;
            RETURN NEW;
        END IF;
        IF NEW.status='PUBLISHED' OR NEW.git_commit IS NOT NULL THEN
            RAISE EXCEPTION 'article revision must be inserted before publication' USING ERRCODE='23514';
        END IF;
        RETURN NEW;
    END IF;
    IF TG_OP='DELETE'
       OR NEW.id<>OLD.id OR NEW.workspace_id<>OLD.workspace_id
       OR NEW.document_id<>OLD.document_id
       OR NEW.source_version_id IS DISTINCT FROM OLD.source_version_id
       OR NEW.parent_revision_id IS DISTINCT FROM OLD.parent_revision_id
       OR NEW.revision_no<>OLD.revision_no OR NEW.content<>OLD.content
       OR NEW.content_hash<>OLD.content_hash
       OR NEW.optimization_mode<>OLD.optimization_mode
       OR NEW.created_by_type<>OLD.created_by_type OR NEW.created_at<>OLD.created_at THEN
        RAISE EXCEPTION 'article revision immutable field violation' USING ERRCODE='55000';
    END IF;

    IF OLD.status IN ('DRAFT','REVIEW','APPROVED') AND NEW.status='PUBLISHED'
       AND OLD.git_commit IS NULL AND NEW.git_commit IS NOT NULL THEN
        SELECT EXISTS (
            SELECT 1
              FROM authoring.document_publication_binding binding
              JOIN change_control.proposal_commit commit_mapping
                ON commit_mapping.proposal_id=binding.proposal_id
               AND commit_mapping.revision_id=binding.proposal_revision_id
             WHERE binding.workspace_id=NEW.workspace_id
               AND binding.document_id=NEW.document_id
               AND binding.article_revision_id=NEW.id
               AND binding.content_hash=NEW.content_hash
               AND binding.status IN ('PENDING','RECOVERY_REQUIRED')
               AND commit_mapping.workspace_id=binding.workspace_id
               AND commit_mapping.target_path=binding.target_path
               AND commit_mapping.target_mode=binding.target_mode
               AND commit_mapping.result_hash=binding.content_hash
               AND commit_mapping.git_commit=NEW.git_commit
        ) INTO exact_publication_fact;
        IF NOT exact_publication_fact THEN
            RAISE EXCEPTION 'article revision publish requires an exact proposal commit' USING ERRCODE='23514';
        END IF;
        RETURN NEW;
    END IF;

    IF OLD.status='PUBLISHED' AND NEW.status='SUPERSEDED'
       AND NEW.git_commit IS NOT DISTINCT FROM OLD.git_commit THEN
        SELECT EXISTS (
            SELECT 1
              FROM authoring.document_publication_binding binding
              JOIN authoring.document_publication_reservation reservation
                ON reservation.id=binding.reservation_id
              JOIN change_control.proposal_commit commit_mapping
                ON commit_mapping.proposal_id=binding.proposal_id
               AND commit_mapping.revision_id=binding.proposal_revision_id
             WHERE binding.workspace_id=OLD.workspace_id
               AND binding.document_id=OLD.document_id
               AND binding.article_revision_id<>OLD.id
               AND binding.target_mode='REPLACE'
               AND binding.status IN ('PENDING','RECOVERY_REQUIRED')
               AND reservation.status='CLOSED'
               AND reservation.base_version=OLD.content_hash
               AND commit_mapping.workspace_id=binding.workspace_id
               AND commit_mapping.target_path=binding.target_path
               AND commit_mapping.target_mode='REPLACE'
               AND commit_mapping.result_hash=binding.content_hash
        ) INTO exact_publication_fact;
        IF NOT exact_publication_fact THEN
            SELECT EXISTS (
                SELECT 1 FROM authoring.document_restore_publication restore
                 WHERE restore.workspace_id=OLD.workspace_id
                   AND restore.document_id=OLD.document_id
                   AND restore.article_revision_id<>OLD.id
                   AND restore.current_content_hash=OLD.content_hash
            ) INTO exact_publication_fact;
        END IF;
        IF NOT exact_publication_fact THEN
            RAISE EXCEPTION 'article revision supersede requires an exact replacement commit' USING ERRCODE='23514';
        END IF;
        RETURN NEW;
    END IF;

    IF NEW.git_commit IS DISTINCT FROM OLD.git_commit
       OR NOT (
           NEW.status=OLD.status
           OR (OLD.status='DRAFT' AND NEW.status IN ('REVIEW','APPROVED','ARCHIVED'))
           OR (OLD.status='REVIEW' AND NEW.status IN ('DRAFT','APPROVED','ARCHIVED'))
           OR (OLD.status='APPROVED' AND NEW.status IN ('DRAFT','REVIEW','ARCHIVED'))
           OR (OLD.status='SUPERSEDED' AND NEW.status='ARCHIVED')
       ) THEN
        RAISE EXCEPTION 'article revision publication state transition is invalid' USING ERRCODE='23514';
    END IF;
    RETURN NEW;
END;
$$;


--
-- Name: validate_document_restore_publication(); Type: FUNCTION; Schema: authoring; Owner: -
--

CREATE FUNCTION authoring.validate_document_restore_publication() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    exact_restore_fact boolean;
BEGIN
    IF TG_OP<>'INSERT' THEN
        RAISE EXCEPTION 'document restore publication is append-only' USING ERRCODE='55000';
    END IF;
    SELECT EXISTS (
        SELECT 1
          FROM change_control.proposal proposal
          JOIN change_control.proposal_revision revision
            ON revision.proposal_id=proposal.id
           AND revision.id=NEW.proposal_revision_id
          JOIN change_control.proposal_commit commit_mapping
            ON commit_mapping.id=NEW.proposal_commit_id
           AND commit_mapping.writeback_execution_id=NEW.writeback_execution_id
           AND commit_mapping.proposal_id=proposal.id
           AND commit_mapping.revision_id=revision.id
         WHERE proposal.id=NEW.proposal_id
           AND proposal.workspace_id=NEW.workspace_id
           AND proposal.proposal_type='restore_document'
           AND proposal.status IN ('verifying','completed')
           AND revision.restore_workspace_id=NEW.workspace_id
           AND revision.restore_document_id=NEW.document_id
           AND revision.restore_expected_document_version=NEW.expected_document_version
           AND revision.target_path=NEW.target_path
           AND revision.target_mode='REPLACE'
           AND revision.base_hash=NEW.current_content_hash
           AND revision.restore_current_content_hash=NEW.current_content_hash
           AND revision.restore_target_content_hash=NEW.target_content_hash
           AND revision.schema_version='document-restore/v1'
           AND encode(sha256(convert_to(revision.content,'UTF8')),'hex')=NEW.target_content_hash
           AND commit_mapping.workspace_id=NEW.workspace_id
           AND commit_mapping.target_path=NEW.target_path
           AND commit_mapping.target_mode='REPLACE'
           AND commit_mapping.result_hash=NEW.target_content_hash
           AND commit_mapping.git_commit=NEW.git_commit
    ) INTO exact_restore_fact;
    IF NOT exact_restore_fact THEN
        RAISE EXCEPTION 'document restore publication requires an exact proposal commit'
            USING ERRCODE='23514';
    END IF;
    RETURN NEW;
END;
$$;


--
-- Name: validate_generated_document_insert(); Type: FUNCTION; Schema: authoring; Owner: -
--

CREATE FUNCTION authoring.validate_generated_document_insert() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    PERFORM 1 FROM core.document
     WHERE id=NEW.document_id AND workspace_id=NEW.workspace_id
       AND lifecycle_status='DRAFT' AND current_published_revision_id IS NULL
       AND version=1 AND created_at=NEW.created_at AND updated_at=NEW.created_at
     FOR UPDATE;
    IF NOT FOUND OR EXISTS (
        SELECT 1 FROM core.article_revision WHERE document_id=NEW.document_id
    ) OR EXISTS (
        SELECT 1 FROM authoring.working_draft WHERE document_id=NEW.document_id
    ) THEN
        RAISE EXCEPTION 'generated origin requires a new unbound document' USING ERRCODE='23514';
    END IF;
    RETURN NEW;
END;
$$;


--
-- Name: validate_generated_retirement_insert(); Type: FUNCTION; Schema: authoring; Owner: -
--

CREATE FUNCTION authoring.validate_generated_retirement_insert() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    binding_record authoring.document_publication_binding%ROWTYPE;
    proposal_record change_control.proposal%ROWTYPE;
    document_version bigint;
    latest_revision uuid;
BEGIN
    SELECT * INTO binding_record FROM authoring.document_publication_binding
     WHERE id=NEW.publication_id AND workspace_id=NEW.workspace_id FOR SHARE;
    SELECT * INTO proposal_record FROM change_control.proposal
     WHERE id=binding_record.proposal_id AND workspace_id=NEW.workspace_id FOR SHARE;
    SELECT version INTO document_version FROM core.document
     WHERE id=NEW.document_id AND workspace_id=NEW.workspace_id FOR SHARE;
    SELECT id INTO latest_revision FROM core.article_revision
     WHERE document_id=NEW.document_id AND workspace_id=NEW.workspace_id
     ORDER BY revision_no DESC LIMIT 1;
    IF binding_record.id IS NULL OR proposal_record.id IS NULL
       OR binding_record.document_id<>NEW.document_id OR binding_record.article_revision_id<>NEW.article_revision_id
       OR latest_revision IS DISTINCT FROM NEW.article_revision_id
       OR document_version IS DISTINCT FROM NEW.expected_document_version
       OR binding_record.status<>'CLOSED' OR binding_record.error_code<>'AUTHORING_PUBLICATION_PROPOSAL_NEEDS_REVISION'
       OR binding_record.git_commit IS NOT NULL OR binding_record.published_at IS NOT NULL
       OR proposal_record.proposal_type<>'file_patch' OR proposal_record.status<>'needs_revision'
       OR proposal_record.current_revision_id IS DISTINCT FROM binding_record.proposal_revision_id
       OR proposal_record.version<>NEW.expected_proposal_version+1 OR proposal_record.workflow_run_id IS NOT NULL
       OR NEW.created_at<binding_record.updated_at OR NEW.created_at<proposal_record.updated_at
       OR EXISTS (SELECT 1 FROM change_control.approval WHERE proposal_id=proposal_record.id)
       OR EXISTS (SELECT 1 FROM change_control.proposal_revision_dispatch WHERE proposal_id=proposal_record.id)
       OR EXISTS (SELECT 1 FROM change_control.tool_authorization WHERE proposal_id=proposal_record.id)
       OR EXISTS (SELECT 1 FROM change_control.writeback_execution WHERE proposal_id=proposal_record.id)
       OR EXISTS (SELECT 1 FROM change_control.proposal_commit WHERE proposal_id=proposal_record.id) THEN
        RAISE EXCEPTION 'generated publication retirement lacks an exact unapproved terminal binding' USING ERRCODE='23514';
    END IF;
    RETURN NEW;
END;
$$;


--
-- Name: validate_generated_revision_insert(); Type: FUNCTION; Schema: authoring; Owner: -
--

CREATE FUNCTION authoring.validate_generated_revision_insert() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    document_record core.document%ROWTYPE;
    revision_record core.article_revision%ROWTYPE;
    parent_no integer;
BEGIN
    SELECT * INTO document_record FROM core.document
     WHERE id=NEW.document_id AND workspace_id=NEW.workspace_id FOR UPDATE;
    SELECT * INTO revision_record FROM core.article_revision
     WHERE id=NEW.article_revision_id AND workspace_id=NEW.workspace_id AND document_id=NEW.document_id FOR SHARE;
    IF document_record.id IS NULL OR revision_record.id IS NULL
       OR document_record.version<>NEW.document_version
       OR document_record.title<>NEW.title OR document_record.canonical_path<>NEW.target_path
       OR document_record.created_at<>NEW.document_created_at OR document_record.updated_at<>NEW.created_at
       OR document_record.lifecycle_status<>NEW.document_lifecycle
       OR document_record.current_published_revision_id IS DISTINCT FROM NEW.published_revision_id
       OR revision_record.created_by_type<>'AGENT' OR revision_record.source_version_id IS NOT NULL
       OR revision_record.status<>'DRAFT' OR revision_record.git_commit IS NOT NULL
       OR revision_record.optimization_mode<>'NONE'
       OR revision_record.content_hash<>NEW.content_hash
       OR encode(sha256(convert_to(revision_record.content,'UTF8')),'hex')<>NEW.content_hash
       OR octet_length(revision_record.content)>10485760 OR position(chr(13) in revision_record.content)>0
       OR revision_record.parent_revision_id IS DISTINCT FROM NEW.parent_revision_id
       OR revision_record.revision_no<>NEW.revision_no OR revision_record.created_at<>NEW.created_at
       OR EXISTS (
           SELECT 1 FROM core.article_revision
            WHERE document_id=NEW.document_id AND revision_no>NEW.revision_no
       ) OR EXISTS (
           SELECT 1 FROM authoring.document_publication_reservation
            WHERE workspace_id=NEW.workspace_id AND document_id=NEW.document_id AND status='PENDING'
       ) OR EXISTS (
           SELECT 1 FROM authoring.document_publication_binding
            WHERE workspace_id=NEW.workspace_id AND document_id=NEW.document_id AND status IN ('PENDING','RECOVERY_REQUIRED')
       ) THEN
        RAISE EXCEPTION 'generated revision does not match its document and agent provenance' USING ERRCODE='23514';
    END IF;
    IF NEW.parent_revision_id IS NOT NULL THEN
        SELECT revision_no INTO parent_no FROM authoring.generated_article_revision
         WHERE article_revision_id=NEW.parent_revision_id AND workspace_id=NEW.workspace_id
           AND document_id=NEW.document_id AND origin_kind=NEW.origin_kind AND origin_id=NEW.origin_id;
        IF parent_no IS NULL OR parent_no<>NEW.revision_no-1 THEN
            RAISE EXCEPTION 'generated revision parent does not match its origin' USING ERRCODE='23514';
        END IF;
    END IF;
    RETURN NEW;
END;
$$;


--
-- Name: validate_publication_binding_write(); Type: FUNCTION; Schema: authoring; Owner: -
--

CREATE FUNCTION authoring.validate_publication_binding_write() RETURNS trigger
    LANGUAGE plpgsql
    AS $_$
DECLARE
    proposal_workspace uuid;
    proposal_type_value text;
    proposal_idempotency_key text;
    proposal_status text;
    revision_proposal uuid;
    revision_target text;
    revision_target_mode text;
    revision_base_hash text;
    revision_content text;
    article_content text;
    article_content_hash text;
    article_status text;
    article_git_commit text;
    document_lifecycle text;
    document_published_revision uuid;
    exact_commit boolean;
    reservation authoring.document_publication_reservation%ROWTYPE;
BEGIN
    IF TG_OP='INSERT' THEN
        IF NEW.version<>1 OR NEW.status<>'PENDING' THEN
            RAISE EXCEPTION 'publication binding must start pending at version one' USING ERRCODE='23514';
        END IF;
        SELECT p.workspace_id,p.proposal_type,p.idempotency_key,p.status,
               r.proposal_id,r.target_path,r.target_mode,r.base_hash,r.content
          INTO proposal_workspace,proposal_type_value,proposal_idempotency_key,proposal_status,
               revision_proposal,revision_target,
               revision_target_mode,revision_base_hash,revision_content
          FROM change_control.proposal p
          JOIN change_control.proposal_revision r
            ON r.proposal_id=p.id
         WHERE p.id=NEW.proposal_id AND r.id=NEW.proposal_revision_id
         FOR SHARE OF p,r;
        SELECT content,content_hash
          INTO article_content,article_content_hash
          FROM core.article_revision
         WHERE id=NEW.article_revision_id
           AND workspace_id=NEW.workspace_id
           AND document_id=NEW.document_id
         FOR SHARE;
        SELECT * INTO reservation
          FROM authoring.document_publication_reservation WHERE id=NEW.reservation_id
          FOR UPDATE;
        IF proposal_workspace IS DISTINCT FROM NEW.workspace_id
           OR proposal_type_value IS DISTINCT FROM 'file_patch'
           OR proposal_idempotency_key IS DISTINCT FROM reservation.proposal_idempotency_key
           OR revision_proposal IS DISTINCT FROM NEW.proposal_id
           OR revision_target IS DISTINCT FROM NEW.target_path
           OR revision_target_mode IS DISTINCT FROM NEW.target_mode
           OR revision_base_hash IS DISTINCT FROM reservation.base_version
           OR revision_content IS DISTINCT FROM article_content
           OR article_content_hash IS DISTINCT FROM NEW.content_hash
           OR encode(sha256(convert_to(revision_content,'UTF8')),'hex') IS DISTINCT FROM NEW.content_hash
           OR reservation.id IS NULL OR reservation.status<>'PENDING'
           OR reservation.workspace_id<>NEW.workspace_id
           OR reservation.document_id<>NEW.document_id
           OR reservation.article_revision_id<>NEW.article_revision_id
           OR reservation.target_path<>NEW.target_path
           OR reservation.content_hash<>NEW.content_hash
           OR reservation.target_mode<>NEW.target_mode
           OR reservation.absence_token<>NEW.absence_token
           OR (NEW.target_mode='CREATE_ONLY'
               AND (reservation.absence_token='' OR reservation.base_version<>reservation.absence_token))
           OR (NEW.target_mode='REPLACE'
               AND (reservation.absence_token<>'' OR reservation.base_version !~ '^[0-9a-f]{64}$')) THEN
            RAISE EXCEPTION 'publication proposal binding is invalid' USING ERRCODE='23514';
        END IF;
        RETURN NEW;
    END IF;
    IF TG_OP='DELETE'
       OR NEW.id<>OLD.id OR NEW.workspace_id<>OLD.workspace_id
       OR NEW.reservation_id<>OLD.reservation_id
       OR NEW.document_id<>OLD.document_id
       OR NEW.article_revision_id<>OLD.article_revision_id
       OR NEW.proposal_id<>OLD.proposal_id
       OR NEW.proposal_revision_id<>OLD.proposal_revision_id
       OR NEW.target_path<>OLD.target_path OR NEW.content_hash<>OLD.content_hash
       OR NEW.target_mode<>OLD.target_mode OR NEW.absence_token<>OLD.absence_token
       OR NEW.created_at<>OLD.created_at OR NEW.version<>OLD.version+1
       OR NEW.updated_at<OLD.updated_at
       OR (OLD.status='PENDING' AND NEW.status NOT IN ('PUBLISHED','RECOVERY_REQUIRED','CLOSED'))
       OR (OLD.status='RECOVERY_REQUIRED' AND NEW.status NOT IN ('PUBLISHED','CLOSED'))
       OR OLD.status IN ('PUBLISHED','CLOSED') THEN
       RAISE EXCEPTION 'publication binding immutable field or transition violation' USING ERRCODE='23514';
    END IF;

    SELECT * INTO reservation
      FROM authoring.document_publication_reservation
     WHERE id=NEW.reservation_id
     FOR SHARE;
    SELECT p.workspace_id,p.proposal_type,p.idempotency_key,
           r.proposal_id,r.target_path,r.target_mode,r.base_hash,r.content
      INTO proposal_workspace,proposal_type_value,proposal_idempotency_key,
           revision_proposal,revision_target,revision_target_mode,revision_base_hash,revision_content
      FROM change_control.proposal p
      JOIN change_control.proposal_revision r
        ON r.proposal_id=p.id
     WHERE p.id=NEW.proposal_id AND r.id=NEW.proposal_revision_id
     FOR SHARE OF p,r;
    SELECT content,content_hash
      INTO article_content,article_content_hash
      FROM core.article_revision
     WHERE id=NEW.article_revision_id
       AND workspace_id=NEW.workspace_id
       AND document_id=NEW.document_id
     FOR SHARE;
    IF proposal_workspace IS DISTINCT FROM NEW.workspace_id
       OR proposal_type_value IS DISTINCT FROM 'file_patch'
       OR proposal_idempotency_key IS DISTINCT FROM reservation.proposal_idempotency_key
       OR revision_proposal IS DISTINCT FROM NEW.proposal_id
       OR revision_target IS DISTINCT FROM NEW.target_path
       OR revision_target_mode IS DISTINCT FROM NEW.target_mode
       OR revision_base_hash IS DISTINCT FROM reservation.base_version
       OR revision_content IS DISTINCT FROM article_content
       OR article_content_hash IS DISTINCT FROM NEW.content_hash
       OR encode(sha256(convert_to(revision_content,'UTF8')),'hex') IS DISTINCT FROM NEW.content_hash THEN
        RAISE EXCEPTION 'publication proposal binding identity changed' USING ERRCODE='23514';
    END IF;
    SELECT status INTO proposal_status
      FROM change_control.proposal
     WHERE id=NEW.proposal_id
       AND workspace_id=NEW.workspace_id
     FOR SHARE;
    SELECT status,git_commit
      INTO article_status,article_git_commit
      FROM core.article_revision
     WHERE id=NEW.article_revision_id
       AND workspace_id=NEW.workspace_id
       AND document_id=NEW.document_id
     FOR SHARE;
    SELECT lifecycle_status,current_published_revision_id
      INTO document_lifecycle,document_published_revision
      FROM core.document
     WHERE id=NEW.document_id
       AND workspace_id=NEW.workspace_id
     FOR SHARE;

    IF reservation.id IS NULL OR reservation.status<>'CLOSED' THEN
        RAISE EXCEPTION 'publication binding transition requires a closed reservation' USING ERRCODE='23514';
    END IF;

    IF NEW.status='PUBLISHED' THEN
        SELECT EXISTS (
            SELECT 1
              FROM change_control.proposal_commit commit_mapping
             WHERE commit_mapping.workspace_id=NEW.workspace_id
               AND commit_mapping.proposal_id=NEW.proposal_id
               AND commit_mapping.revision_id=NEW.proposal_revision_id
               AND commit_mapping.target_path=NEW.target_path
               AND commit_mapping.target_mode=NEW.target_mode
               AND commit_mapping.result_hash=NEW.content_hash
               AND commit_mapping.git_commit=NEW.git_commit
        ) INTO exact_commit;
        IF proposal_status NOT IN ('verifying','completed')
           OR article_status IS DISTINCT FROM 'PUBLISHED'
           OR article_git_commit IS DISTINCT FROM NEW.git_commit
           OR document_lifecycle IS DISTINCT FROM 'PUBLISHED'
           OR document_published_revision IS DISTINCT FROM NEW.article_revision_id
           OR NOT exact_commit THEN
            RAISE EXCEPTION 'published binding requires exact published proposal, revision, document, and commit facts'
                USING ERRCODE='23514';
        END IF;
    ELSIF NEW.status='CLOSED' THEN
        IF NOT (
            (proposal_status='rejected' AND NEW.error_code='AUTHORING_PUBLICATION_PROPOSAL_REJECTED')
            OR (proposal_status='needs_revision' AND NEW.error_code='AUTHORING_PUBLICATION_PROPOSAL_NEEDS_REVISION')
            OR (proposal_status='cancelled' AND NEW.error_code='AUTHORING_PUBLICATION_PROPOSAL_CANCELLED')
        ) THEN
            RAISE EXCEPTION 'closed publication binding must match the terminal proposal outcome'
                USING ERRCODE='23514';
        END IF;
    ELSIF NEW.status='RECOVERY_REQUIRED' THEN
        IF NEW.error_code NOT IN (
               'AUTHORING_PUBLICATION_COMMIT_MISMATCH',
               'AUTHORING_PUBLICATION_STATE_MISMATCH'
           )
           OR proposal_status IS NULL
           OR proposal_status IN ('rejected','needs_revision','cancelled') THEN
            RAISE EXCEPTION 'publication recovery binding has no controlled nonterminal recovery reason'
                USING ERRCODE='23514';
        END IF;
    ELSE
        RAISE EXCEPTION 'publication binding target status is invalid' USING ERRCODE='23514';
    END IF;
    RETURN NEW;
END;
$_$;


--
-- Name: validate_publication_reservation_write(); Type: FUNCTION; Schema: authoring; Owner: -
--

CREATE FUNCTION authoring.validate_publication_reservation_write() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF TG_OP='INSERT' THEN
        IF NEW.status<>'PENDING'
           OR NEW.error_code<>'' OR NEW.closed_at IS NOT NULL OR NEW.abandoned_at IS NOT NULL
           OR EXISTS (
               SELECT 1 FROM authoring.document_publication_binding binding
               WHERE binding.workspace_id=NEW.workspace_id
                 AND binding.document_id=NEW.document_id
                 AND binding.status IN ('PENDING','RECOVERY_REQUIRED')
           ) THEN
            RAISE EXCEPTION 'publication reservation conflicts with a nonterminal publication'
                USING ERRCODE='23505', CONSTRAINT='uq_authoring_publication_nonterminal_document';
        END IF;
        RETURN NEW;
    END IF;
    IF TG_OP='DELETE'
       OR NEW.id<>OLD.id OR NEW.workspace_id<>OLD.workspace_id
       OR NEW.document_id<>OLD.document_id OR NEW.article_revision_id<>OLD.article_revision_id
       OR NEW.idempotency_key<>OLD.idempotency_key OR NEW.request_hash<>OLD.request_hash
       OR NEW.proposal_idempotency_key<>OLD.proposal_idempotency_key
       OR NEW.target_path<>OLD.target_path OR NEW.content_hash<>OLD.content_hash
       OR NEW.target_mode<>OLD.target_mode OR NEW.base_version<>OLD.base_version
       OR NEW.absence_token<>OLD.absence_token
       OR NEW.created_at<>OLD.created_at OR NEW.updated_at<OLD.updated_at
       OR OLD.status<>'PENDING' THEN
        RAISE EXCEPTION 'publication reservation immutable field or transition violation' USING ERRCODE='23514';
    END IF;

    IF NEW.status='CLOSED' AND NEW.error_code='' AND NEW.abandoned_at IS NULL
       AND EXISTS (
           SELECT 1
             FROM authoring.document_publication_binding binding
            WHERE binding.reservation_id=OLD.id
              AND binding.workspace_id=OLD.workspace_id
              AND binding.document_id=OLD.document_id
              AND binding.article_revision_id=OLD.article_revision_id
              AND binding.target_path=OLD.target_path
              AND binding.content_hash=OLD.content_hash
              AND binding.target_mode=OLD.target_mode
              AND binding.absence_token=OLD.absence_token
              AND binding.status='PENDING'
       ) THEN
        RETURN NEW;
    END IF;

    IF NEW.status='ABANDONED' AND NEW.closed_at IS NULL
       AND NEW.error_code='WRITEBACK_TARGET_PARENT_NOT_FOUND'
       AND NOT EXISTS (
           SELECT 1 FROM authoring.document_publication_binding binding
            WHERE binding.workspace_id=OLD.workspace_id AND binding.reservation_id=OLD.id
       ) THEN
        RETURN NEW;
    END IF;

    RAISE EXCEPTION 'publication reservation transition requires its exact terminal proof'
        USING ERRCODE='23514';
END;
$$;


--
-- Name: validate_working_draft_write(); Type: FUNCTION; Schema: authoring; Owner: -
--

CREATE FUNCTION authoring.validate_working_draft_write() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF TG_OP='INSERT' THEN
        IF NEW.version<>1 THEN
            RAISE EXCEPTION 'working draft must start at version one' USING ERRCODE='23514';
        END IF;
        RETURN NEW;
    END IF;
    IF TG_OP='DELETE'
       OR NEW.id<>OLD.id OR NEW.workspace_id<>OLD.workspace_id
       OR NEW.created_at<>OLD.created_at
       OR (OLD.document_id IS NOT NULL AND NEW.document_id IS DISTINCT FROM OLD.document_id)
       OR NEW.version<>OLD.version+1 OR NEW.updated_at<OLD.updated_at THEN
        RAISE EXCEPTION 'working draft identity or version violation' USING ERRCODE='23514';
    END IF;
    RETURN NEW;
END;
$$;


--
-- Name: verify_generated_revision_closure(); Type: FUNCTION; Schema: authoring; Owner: -
--

CREATE FUNCTION authoring.verify_generated_revision_closure() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF TG_TABLE_NAME='generated_document' THEN
        IF NOT EXISTS (
            SELECT 1 FROM authoring.generated_article_revision
             WHERE document_id=NEW.document_id AND workspace_id=NEW.workspace_id
               AND origin_kind=NEW.origin_kind AND origin_id=NEW.origin_id AND revision_no=1
        ) THEN
            RAISE EXCEPTION 'generated document requires its initial revision' USING ERRCODE='23514';
        END IF;
    ELSIF NEW.created_by_type='AGENT' AND EXISTS (
        SELECT 1 FROM authoring.generated_document
         WHERE document_id=NEW.document_id AND workspace_id=NEW.workspace_id
    ) AND NOT EXISTS (
        SELECT 1 FROM authoring.generated_article_revision
         WHERE article_revision_id=NEW.id AND workspace_id=NEW.workspace_id
           AND document_id=NEW.document_id AND content_hash=NEW.content_hash
           AND parent_revision_id IS NOT DISTINCT FROM NEW.parent_revision_id
           AND revision_no=NEW.revision_no AND created_at=NEW.created_at
    ) THEN
        RAISE EXCEPTION 'generated agent revision requires its origin receipt' USING ERRCODE='23514';
    END IF;
    RETURN NULL;
END;
$$;


--
-- Name: verify_publication_terminal_state(); Type: FUNCTION; Schema: authoring; Owner: -
--

CREATE FUNCTION authoring.verify_publication_terminal_state() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    has_authoring_binding boolean;
    exact_terminal_state boolean;
BEGIN
    IF TG_TABLE_SCHEMA='authoring'
       AND TG_TABLE_NAME='document_publication_binding' THEN
        IF NEW.status<>'PUBLISHED'
           OR (TG_OP='UPDATE' AND OLD.status='PUBLISHED') THEN
            RETURN NEW;
        END IF;
        exact_terminal_state := authoring.publication_is_exact_current(
            NEW.workspace_id,NEW.document_id,NEW.article_revision_id);
    ELSIF TG_TABLE_SCHEMA='core' AND TG_TABLE_NAME='article_revision' THEN
        IF TG_OP<>'UPDATE' OR NEW.status IS NOT DISTINCT FROM OLD.status THEN
            RETURN NEW;
        END IF;
        IF NEW.status='PUBLISHED' THEN
            exact_terminal_state := authoring.publication_is_exact_current(
                NEW.workspace_id,NEW.document_id,NEW.id)
                OR authoring.restore_publication_is_exact_current(
                    NEW.workspace_id,NEW.document_id,NEW.id);
        ELSIF OLD.status='PUBLISHED' AND NEW.status='SUPERSEDED' THEN
            SELECT EXISTS (
                SELECT 1
                  FROM core.document document
                  JOIN authoring.document_publication_binding replacement
                    ON replacement.workspace_id=document.workspace_id
                   AND replacement.document_id=document.id
                   AND replacement.article_revision_id=document.current_published_revision_id
                  JOIN authoring.document_publication_reservation replacement_reservation
                    ON replacement_reservation.id=replacement.reservation_id
                 WHERE document.id=NEW.document_id
                   AND document.workspace_id=NEW.workspace_id
                   AND document.lifecycle_status='PUBLISHED'
                   AND document.current_published_revision_id<>NEW.id
                   AND replacement.target_mode='REPLACE'
                   AND replacement.status='PUBLISHED'
                   AND replacement_reservation.status='CLOSED'
                   AND replacement_reservation.base_version=NEW.content_hash
                   AND authoring.publication_is_exact_current(
                       replacement.workspace_id,replacement.document_id,
                       replacement.article_revision_id)
            ) OR EXISTS (
                SELECT 1
                  FROM core.document document
                  JOIN authoring.document_restore_publication restore
                    ON restore.workspace_id=document.workspace_id
                   AND restore.document_id=document.id
                   AND restore.article_revision_id=document.current_published_revision_id
                 WHERE document.id=NEW.document_id
                   AND document.workspace_id=NEW.workspace_id
                   AND document.lifecycle_status='PUBLISHED'
                   AND document.current_published_revision_id<>NEW.id
                   AND restore.current_content_hash=NEW.content_hash
                   AND authoring.restore_publication_is_exact_current(
                       restore.workspace_id,restore.document_id,restore.article_revision_id)
            ) INTO exact_terminal_state;
        ELSE
            RETURN NEW;
        END IF;
    ELSE
        IF NEW.lifecycle_status<>'PUBLISHED'
           OR NEW.current_published_revision_id IS NULL THEN
            RETURN NEW;
        END IF;
        SELECT EXISTS (
            SELECT 1 FROM authoring.document_publication_binding binding
             WHERE binding.workspace_id=NEW.workspace_id
               AND binding.document_id=NEW.id
               AND binding.article_revision_id=NEW.current_published_revision_id
        ) INTO has_authoring_binding;
        IF NOT has_authoring_binding
           AND OLD.lifecycle_status IS NOT DISTINCT FROM NEW.lifecycle_status
           AND OLD.current_published_revision_id IS NOT DISTINCT FROM NEW.current_published_revision_id THEN
            RETURN NEW;
        END IF;
        exact_terminal_state := authoring.publication_is_exact_current(
            NEW.workspace_id,NEW.id,NEW.current_published_revision_id)
            OR authoring.restore_publication_is_exact_current(
                NEW.workspace_id,NEW.id,NEW.current_published_revision_id);
    END IF;

    IF exact_terminal_state IS NOT TRUE THEN
        RAISE EXCEPTION 'authoring publication terminal state is not closed'
            USING ERRCODE='23514';
    END IF;
    RETURN NEW;
END;
$$;


--
-- Name: guard_proposal_identity(); Type: FUNCTION; Schema: change_control; Owner: -
--

CREATE FUNCTION change_control.guard_proposal_identity() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF NEW.id <> OLD.id OR NEW.workspace_id <> OLD.workspace_id OR NEW.created_at <> OLD.created_at THEN
        RAISE EXCEPTION 'proposal identity is immutable' USING ERRCODE='55000';
    END IF;
    RETURN NEW;
END;
$$;


--
-- Name: guard_proposal_workflow_run_binding(); Type: FUNCTION; Schema: change_control; Owner: -
--

CREATE FUNCTION change_control.guard_proposal_workflow_run_binding() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    run_workspace_id uuid;
BEGIN
    IF NEW.proposal_type='downstream_update' AND NEW.workflow_run_id IS NOT NULL THEN
        RAISE EXCEPTION 'downstream update proposal cannot bind a workflow run'
            USING ERRCODE='23514';
    END IF;
    IF TG_OP='INSERT' THEN
        IF NEW.workflow_run_id IS NOT NULL THEN
            RAISE EXCEPTION 'proposal workflow run must be bound after proposal creation'
                USING ERRCODE='55000';
        END IF;
        RETURN NEW;
    END IF;
    IF OLD.workflow_run_id IS NOT NULL
       AND NEW.workflow_run_id IS DISTINCT FROM OLD.workflow_run_id THEN
        RAISE EXCEPTION 'proposal workflow run binding is immutable' USING ERRCODE='55000';
    END IF;
    IF OLD.workflow_run_id IS NULL AND NEW.workflow_run_id IS NOT NULL THEN
        IF NEW.status<>'approved' OR OLD.status NOT IN ('ready_for_review','approved') THEN
            RAISE EXCEPTION 'only an approved proposal can bind a workflow run' USING ERRCODE='23514';
        END IF;
        SELECT workspace_id INTO run_workspace_id FROM workflow.run WHERE id=NEW.workflow_run_id;
        IF FOUND AND run_workspace_id<>NEW.workspace_id THEN
            RAISE EXCEPTION 'proposal and workflow run must belong to the same workspace'
                USING ERRCODE='23514';
        END IF;
    END IF;
    RETURN NEW;
END;
$$;


--
-- Name: guard_writeback_reindex_mutation(); Type: FUNCTION; Schema: change_control; Owner: -
--

CREATE FUNCTION change_control.guard_writeback_reindex_mutation() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF TG_OP = 'DELETE' THEN
        IF OLD.event_type = 'retrieval.revision.reindex_requested' THEN
            RAISE EXCEPTION 'writeback reindex event is append-preserving' USING ERRCODE = '55000';
        END IF;
        RETURN OLD;
    END IF;
    IF OLD.event_type <> 'retrieval.revision.reindex_requested'
       AND NEW.event_type = 'retrieval.revision.reindex_requested' THEN
        RAISE EXCEPTION 'writeback reindex event must be inserted through its validated boundary' USING ERRCODE = '55000';
    END IF;
    IF OLD.event_type = 'retrieval.revision.reindex_requested' AND (
        NEW.id <> OLD.id OR NEW.workspace_id <> OLD.workspace_id OR NEW.run_id IS DISTINCT FROM OLD.run_id
        OR NEW.event_type <> OLD.event_type OR NEW.idempotency_key <> OLD.idempotency_key
        OR NEW.payload <> OLD.payload OR NEW.occurred_at <> OLD.occurred_at
        OR (OLD.published_at IS NOT NULL AND NEW.published_at IS DISTINCT FROM OLD.published_at)
    ) THEN
        RAISE EXCEPTION 'writeback reindex event identity is immutable' USING ERRCODE = '55000';
    END IF;
    RETURN NEW;
END;
$$;


--
-- Name: reject_downstream_update_execution(); Type: FUNCTION; Schema: change_control; Owner: -
--

CREATE FUNCTION change_control.reject_downstream_update_execution() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF EXISTS (
        SELECT 1 FROM change_control.proposal
        WHERE id=NEW.proposal_id AND proposal_type='downstream_update'
    ) THEN
        RAISE EXCEPTION 'downstream update apply is unavailable' USING ERRCODE='23514';
    END IF;
    RETURN NEW;
END;
$$;


--
-- Name: reject_immutable_mutation(); Type: FUNCTION; Schema: change_control; Owner: -
--

CREATE FUNCTION change_control.reject_immutable_mutation() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    RAISE EXCEPTION '% is immutable', TG_TABLE_NAME USING ERRCODE='55000';
END;
$$;


--
-- Name: reject_revision_append_only_mutation(); Type: FUNCTION; Schema: change_control; Owner: -
--

CREATE FUNCTION change_control.reject_revision_append_only_mutation() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    RAISE EXCEPTION '% is append-only', TG_TABLE_NAME USING ERRCODE='55000';
END $$;


--
-- Name: reject_tool_authorization_delete(); Type: FUNCTION; Schema: change_control; Owner: -
--

CREATE FUNCTION change_control.reject_tool_authorization_delete() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    RAISE EXCEPTION 'tool authorization is immutable' USING ERRCODE = '55000';
END;
$$;


--
-- Name: reject_writeback_execution_delete(); Type: FUNCTION; Schema: change_control; Owner: -
--

CREATE FUNCTION change_control.reject_writeback_execution_delete() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    RAISE EXCEPTION 'writeback execution is append-preserving' USING ERRCODE = '55000';
END;
$$;


--
-- Name: validate_authorization_current_revision(); Type: FUNCTION; Schema: change_control; Owner: -
--

CREATE FUNCTION change_control.validate_authorization_current_revision() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    current_revision uuid;
    dispatch_run uuid;
    dispatch_approval uuid;
BEGIN
    IF NEW.status NOT IN ('issued','consumed') THEN
        RETURN NEW;
    END IF;
    SELECT p.current_revision_id,d.workflow_run_id,d.approval_id
      INTO current_revision,dispatch_run,dispatch_approval
      FROM change_control.proposal p
      LEFT JOIN change_control.proposal_revision_dispatch d
        ON d.proposal_id=p.id AND d.revision_id=NEW.revision_id
     WHERE p.id=NEW.proposal_id
     FOR UPDATE OF p;
    IF current_revision IS NULL OR current_revision<>NEW.revision_id
       OR dispatch_run IS NULL OR dispatch_run<>NEW.workflow_run_id
       OR dispatch_approval IS NULL OR dispatch_approval<>NEW.approval_id THEN
        RAISE EXCEPTION 'tool authorization is not bound to the current revision dispatch' USING ERRCODE='23514';
    END IF;
    RETURN NEW;
END;
$$;


--
-- Name: validate_create_only_revision_binding(); Type: FUNCTION; Schema: change_control; Owner: -
--

CREATE FUNCTION change_control.validate_create_only_revision_binding() RETURNS trigger
    LANGUAGE plpgsql
    AS $_$
DECLARE
    proposal_type_value text;
    workspace_value uuid;
BEGIN
    SELECT proposal_type,workspace_id INTO proposal_type_value,workspace_value
      FROM change_control.proposal WHERE id=NEW.proposal_id FOR SHARE;
    IF proposal_type_value IS NULL THEN
        RAISE EXCEPTION 'proposal revision proposal is missing' USING ERRCODE='23514';
    END IF;
    IF proposal_type_value <> 'file_patch' AND NEW.target_mode <> 'REPLACE' THEN
        RAISE EXCEPTION 'only file patch revisions can use create only target mode' USING ERRCODE='23514';
    END IF;
    IF proposal_type_value = 'file_patch' AND NEW.target_mode = 'CREATE_ONLY'
       AND NEW.base_hash !~ '^workspace-target-absent/v1:[0-9a-f]{64}$' THEN
        RAISE EXCEPTION 'create only revision requires a versioned absence token' USING ERRCODE='23514';
    END IF;
    RETURN NEW;
END;
$_$;


--
-- Name: validate_proposal_revision_dispatch(); Type: FUNCTION; Schema: change_control; Owner: -
--

CREATE FUNCTION change_control.validate_proposal_revision_dispatch() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE approval_proposal uuid; approval_revision uuid; approval_decision text; approval_hash text;
        revision_hash text; proposal_workspace uuid; proposal_current_revision uuid; run_workspace uuid;
BEGIN
    SELECT proposal_id,revision_id,decision,change_hash INTO approval_proposal,approval_revision,approval_decision,approval_hash
      FROM change_control.approval WHERE id=NEW.approval_id;
    SELECT change_hash INTO revision_hash FROM change_control.proposal_revision
      WHERE proposal_id=NEW.proposal_id AND id=NEW.revision_id;
    SELECT workspace_id,current_revision_id INTO proposal_workspace,proposal_current_revision
      FROM change_control.proposal WHERE id=NEW.proposal_id FOR UPDATE;
    SELECT workspace_id INTO run_workspace FROM workflow.run WHERE id=NEW.workflow_run_id;
    IF approval_proposal IS NULL OR approval_revision IS NULL OR revision_hash IS NULL
       OR proposal_workspace IS NULL OR proposal_current_revision IS NULL OR run_workspace IS NULL
       OR approval_proposal<>NEW.proposal_id OR approval_revision<>NEW.revision_id
       OR approval_decision<>'approved' OR approval_hash<>revision_hash
       OR proposal_workspace<>NEW.workspace_id OR proposal_current_revision<>NEW.revision_id
       OR run_workspace<>NEW.workspace_id THEN
        RAISE EXCEPTION 'proposal revision dispatch binding mismatch' USING ERRCODE='23514';
    END IF;
    RETURN NEW;
END $$;


--
-- Name: validate_proposal_revision_payload(); Type: FUNCTION; Schema: change_control; Owner: -
--

CREATE FUNCTION change_control.validate_proposal_revision_payload() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    proposal_type_value text;
    proposal_workspace_id uuid;
    proposal_risk_level text;
    downstream_fields_present boolean;
BEGIN
    SELECT proposal_type,workspace_id,risk_level
      INTO proposal_type_value,proposal_workspace_id,proposal_risk_level
      FROM change_control.proposal
     WHERE id=NEW.proposal_id
     FOR SHARE;

    IF proposal_type_value IS NULL THEN
        RETURN NEW;
    END IF;

    downstream_fields_present := NEW.downstream_workspace_id IS NOT NULL
        OR NEW.downstream_report_id IS NOT NULL
        OR NEW.downstream_analysis_version IS NOT NULL
        OR NEW.downstream_report_fingerprint IS NOT NULL
        OR NEW.downstream_source_event_id IS NOT NULL
        OR NEW.downstream_source_event_version IS NOT NULL
        OR NEW.downstream_target_type IS NOT NULL
        OR NEW.downstream_target_id IS NOT NULL
        OR NEW.downstream_base_version IS NOT NULL
        OR NEW.downstream_action IS NOT NULL
        OR NEW.downstream_owner_binding IS NOT NULL
        OR NEW.downstream_reason IS NOT NULL;

    IF proposal_type_value='file_patch' THEN
        IF NEW.target_path IS NULL
           OR NEW.base_hash IS NULL
           OR NEW.content IS NULL
           OR NEW.evidence_summary IS NULL
           OR NEW.target_refs IS NOT NULL
           OR NEW.base_versions IS NOT NULL
           OR NEW.change_set IS NOT NULL
           OR NEW.evidence_refs IS NOT NULL
           OR NEW.artifact_id IS NOT NULL
           OR NEW.artifact_revision_id IS NOT NULL
           OR NEW.artifact_revision_no IS NOT NULL
           OR NEW.artifact_version IS NOT NULL
           OR NEW.artifact_content_hash IS NOT NULL
           OR NEW.artifact_source_coverage IS NOT NULL
           OR downstream_fields_present
           OR NEW.schema_version IS NOT NULL THEN
            RAISE EXCEPTION 'file patch proposal revision requires file fields only'
                USING ERRCODE='23514';
        END IF;
        RETURN NEW;
    END IF;

    IF proposal_type_value='knowledge_change' THEN
        IF NEW.target_path IS NOT NULL
           OR NEW.base_hash IS NOT NULL
           OR NEW.content IS NOT NULL
           OR NEW.evidence_summary IS NOT NULL
           OR NEW.target_refs IS NULL
           OR NEW.base_versions IS NULL
           OR NEW.change_set IS NULL
           OR NEW.evidence_refs IS NULL
           OR NEW.artifact_id IS NOT NULL
           OR NEW.artifact_revision_id IS NOT NULL
           OR NEW.artifact_revision_no IS NOT NULL
           OR NEW.artifact_version IS NOT NULL
           OR NEW.artifact_content_hash IS NOT NULL
           OR NEW.artifact_source_coverage IS NOT NULL
           OR downstream_fields_present
           OR NEW.schema_version IS DISTINCT FROM 'knowledge-relation-change/v1' THEN
            RAISE EXCEPTION 'knowledge change proposal revision requires typed fields only'
                USING ERRCODE='23514';
        END IF;
        RETURN NEW;
    END IF;

    IF proposal_type_value='publish_artifact' THEN
        IF NEW.target_path IS NOT NULL
           OR NEW.base_hash IS NOT NULL
           OR NEW.content IS NOT NULL
           OR NEW.evidence_summary IS NOT NULL
           OR NEW.target_refs IS NOT NULL
           OR NEW.base_versions IS NOT NULL
           OR NEW.change_set IS NOT NULL
           OR NEW.evidence_refs IS NOT NULL
           OR NEW.artifact_id IS NULL
           OR NEW.artifact_revision_id IS NULL
           OR NEW.artifact_revision_no IS NULL
           OR NEW.artifact_version IS NULL
           OR NEW.artifact_content_hash IS NULL
           OR NEW.artifact_source_coverage IS NULL
           OR downstream_fields_present
           OR NEW.schema_version IS DISTINCT FROM 'artifact-publication/v1' THEN
            RAISE EXCEPTION 'publish artifact proposal revision requires frozen artifact fields only'
                USING ERRCODE='23514';
        END IF;
        RETURN NEW;
    END IF;

    IF proposal_type_value <> 'downstream_update'
       OR NEW.target_path IS NOT NULL
       OR NEW.base_hash IS NOT NULL
       OR NEW.content IS NOT NULL
       OR NEW.evidence_summary IS NOT NULL
       OR NEW.target_refs IS NOT NULL
       OR NEW.base_versions IS NOT NULL
       OR NEW.change_set IS NOT NULL
       OR NEW.evidence_refs IS NOT NULL
       OR NEW.artifact_id IS NOT NULL
       OR NEW.artifact_revision_id IS NOT NULL
       OR NEW.artifact_revision_no IS NOT NULL
       OR NEW.artifact_version IS NOT NULL
       OR NEW.artifact_content_hash IS NOT NULL
       OR NEW.artifact_source_coverage IS NOT NULL
       OR NEW.downstream_workspace_id IS NULL
       OR NEW.downstream_report_id IS NULL
       OR NEW.downstream_analysis_version IS DISTINCT FROM 'impact-analysis/v2'
       OR NEW.downstream_report_fingerprint IS NULL
       OR NEW.downstream_source_event_id IS NULL
       OR NEW.downstream_source_event_version IS NULL
       OR NEW.downstream_target_type IS NULL
       OR NEW.downstream_target_type NOT IN ('ARTIFACT','REVIEW_CARD')
       OR NEW.downstream_target_id IS NULL
       OR NEW.downstream_base_version IS NULL
       OR NEW.downstream_action IS NULL
       OR NEW.downstream_action NOT IN ('REGENERATE_ARTIFACT','REVALIDATE_REVIEW_CARD')
       OR NEW.downstream_owner_binding IS NULL
       OR NEW.downstream_reason IS NULL
       OR NEW.schema_version IS DISTINCT FROM 'impact-downstream-update/v1'
       OR proposal_workspace_id IS DISTINCT FROM NEW.downstream_workspace_id
       OR proposal_risk_level IS DISTINCT FROM 'HIGH'
       OR (NEW.downstream_target_type='ARTIFACT' AND NEW.downstream_action IS DISTINCT FROM 'REGENERATE_ARTIFACT')
       OR (NEW.downstream_target_type='REVIEW_CARD' AND NEW.downstream_action IS DISTINCT FROM 'REVALIDATE_REVIEW_CARD')
       OR NOT COALESCE(ops.valid_impact_owner_binding(
           NEW.downstream_target_type,NEW.downstream_target_id,
           NEW.downstream_base_version,NEW.downstream_owner_binding
       ),false) THEN
        RAISE EXCEPTION 'downstream update proposal revision requires frozen owner fields only'
            USING ERRCODE='23514';
    END IF;

    PERFORM report.id
        FROM ops.impact_report AS report
        WHERE report.id=NEW.downstream_report_id
          AND report.workspace_id=NEW.downstream_workspace_id
          AND report.source_event_id=NEW.downstream_source_event_id
          AND report.source_event_version=NEW.downstream_source_event_version
          AND report.analysis_version=NEW.downstream_analysis_version
          AND report.fingerprint=NEW.downstream_report_fingerprint
          AND report.schema_version='impact-report/v2'
          AND report.status='READY'
          AND NOT EXISTS (
              SELECT 1
              FROM ops.impact_report AS successor
              WHERE successor.workspace_id=report.workspace_id
                AND successor.supersedes_report_id=report.id
          )
          AND (
              SELECT count(*)
              FROM jsonb_array_elements(report.objects) AS candidate(value)
              WHERE candidate.value->>'type'=NEW.downstream_target_type
                AND candidate.value->>'id'=NEW.downstream_target_id::text
          )=1
          AND EXISTS (
              SELECT 1
              FROM jsonb_array_elements(report.objects) AS candidate(value)
              WHERE jsonb_typeof(candidate.value)='object'
                AND candidate.value->>'type'=NEW.downstream_target_type
                AND candidate.value->>'id'=NEW.downstream_target_id::text
                AND candidate.value->>'workspace_id'=NEW.downstream_workspace_id::text
                AND candidate.value->'version'=to_jsonb(NEW.downstream_base_version)
                AND candidate.value->>'action'=NEW.downstream_action
                AND candidate.value->'reason'=to_jsonb(NEW.downstream_reason)
                AND candidate.value->'requires_proposal'='true'::jsonb
                AND (
                    (
                        NEW.downstream_target_type='ARTIFACT'
                        AND candidate.value - ARRAY[
                            'type','id','workspace_id','version','action','reason',
                            'requires_proposal','artifact_binding'
                        ]='{}'::jsonb
                        AND candidate.value->'artifact_binding'=NEW.downstream_owner_binding->'artifact'
                    )
                    OR (
                        NEW.downstream_target_type='REVIEW_CARD'
                        AND candidate.value - ARRAY[
                            'type','id','workspace_id','version','action','reason',
                            'requires_proposal','review_card_binding'
                        ]='{}'::jsonb
                        AND candidate.value->'review_card_binding'=NEW.downstream_owner_binding->'review_card'
                    )
                )
          )
        FOR SHARE OF report;
    IF NOT FOUND THEN
        RAISE EXCEPTION 'downstream update report binding is not current and ready'
            USING ERRCODE='23514';
    END IF;

    IF NEW.downstream_target_type='ARTIFACT' THEN
        PERFORM artifact.id
        FROM learning.artifact AS artifact
        JOIN learning.artifact_revision AS revision
          ON revision.id=artifact.current_revision_id
         AND revision.workspace_id=artifact.workspace_id
         AND revision.artifact_id=artifact.id
         AND revision.domain_schema_version='artifact-revision/v1'
        WHERE artifact.workspace_id=NEW.downstream_workspace_id
          AND artifact.id=NEW.downstream_target_id
          AND artifact.domain_schema_version='artifact/v1'
          AND artifact.version=NEW.downstream_base_version
          AND artifact.current_revision_id::text=NEW.downstream_owner_binding->'artifact'->>'revision_id'
          AND revision.revision_no=(NEW.downstream_owner_binding->'artifact'->>'revision_no')::bigint
          AND revision.content_hash=NEW.downstream_owner_binding->'artifact'->>'content_hash'
        FOR SHARE OF artifact,revision;
    ELSE
        PERFORM card.id
        FROM learning.review_card AS card
        WHERE card.workspace_id=NEW.downstream_workspace_id
          AND card.id=NEW.downstream_target_id
          AND card.version=NEW.downstream_base_version
          AND card.status=NEW.downstream_owner_binding->'review_card'->>'status'
          AND card.fingerprint=NEW.downstream_owner_binding->'review_card'->>'fingerprint'
          AND card.claim_id::text=NEW.downstream_owner_binding->'review_card'->>'claim_id'
          AND learning.review_card_evidence_binding_fingerprint(card.evidence)=
              NEW.downstream_owner_binding->'review_card'->>'evidence_binding_fingerprint'
        FOR SHARE OF card;
    END IF;
    IF NOT FOUND THEN
        RAISE EXCEPTION 'downstream update owner binding is stale'
            USING ERRCODE='23514';
    END IF;
    RETURN NEW;
END;
$$;


--
-- Name: validate_proposal_revision_transition(); Type: FUNCTION; Schema: change_control; Owner: -
--

CREATE FUNCTION change_control.validate_proposal_revision_transition() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE source_revision change_control.proposal_revision%ROWTYPE; current_revision change_control.proposal_revision%ROWTYPE;
BEGIN
    IF TG_OP='INSERT' THEN
        RETURN NEW;
    END IF;
    IF NEW.current_revision_id IS NOT DISTINCT FROM OLD.current_revision_id THEN
        RETURN NEW;
    END IF;
    SELECT * INTO source_revision FROM change_control.proposal_revision WHERE proposal_id=NEW.id AND id=OLD.current_revision_id;
    SELECT * INTO current_revision FROM change_control.proposal_revision WHERE proposal_id=NEW.id AND id=NEW.current_revision_id;
    IF OLD.status NOT IN ('ready_for_review','needs_revision') OR NEW.status<>'ready_for_review'
       OR NEW.version<>OLD.version+1 OR source_revision.id IS NULL OR current_revision.id IS NULL
       OR current_revision.revision_no<>source_revision.revision_no+1
       OR current_revision.target_path<>source_revision.target_path OR current_revision.target_mode<>'REPLACE' THEN
        RAISE EXCEPTION 'proposal current revision transition is not allowed' USING ERRCODE='23514';
    END IF;
    RETURN NEW;
END $$;


--
-- Name: validate_proposal_transition(); Type: FUNCTION; Schema: change_control; Owner: -
--

CREATE FUNCTION change_control.validate_proposal_transition() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    workflow_binding_added boolean;
    pointer_changed boolean;
    source_no integer;
    result_no integer;
    source_path text;
    result_path text;
    source_mode text;
    result_mode text;
BEGIN
    IF TG_OP='INSERT' THEN
        IF NEW.version<>1 THEN
            RAISE EXCEPTION 'proposal must start at version one' USING ERRCODE='23514';
        END IF;
        IF NEW.proposal_type='publish_artifact' AND NEW.workflow_run_id IS NOT NULL THEN
            RAISE EXCEPTION 'publish artifact proposal cannot bind a writeback workflow' USING ERRCODE='23514';
        END IF;
        IF NEW.proposal_type='downstream_update'
           AND (NEW.workflow_run_id IS NOT NULL OR NEW.status<>'ready_for_review' OR NEW.risk_level<>'HIGH') THEN
            RAISE EXCEPTION 'downstream update proposal must start approval-only' USING ERRCODE='23514';
        END IF;
        RETURN NEW;
    END IF;

    IF NEW.id<>OLD.id
       OR NEW.workspace_id<>OLD.workspace_id
       OR NEW.idempotency_key<>OLD.idempotency_key
       OR NEW.request_hash<>OLD.request_hash
       OR NEW.proposal_type<>OLD.proposal_type
       OR NEW.risk_level<>OLD.risk_level
       OR NEW.created_at<>OLD.created_at
       OR NEW.updated_at<OLD.updated_at
       OR NEW.version<>OLD.version+1 THEN
        RAISE EXCEPTION 'proposal immutable field or version violation' USING ERRCODE='23514';
    END IF;

    pointer_changed := NEW.current_revision_id IS DISTINCT FROM OLD.current_revision_id;
    IF pointer_changed THEN
        IF NEW.workflow_run_id IS DISTINCT FROM OLD.workflow_run_id
           OR NEW.proposal_type<>'file_patch'
           OR OLD.status NOT IN ('ready_for_review','needs_revision')
           OR NEW.status<>'ready_for_review'
           OR OLD.current_revision_id IS NULL OR NEW.current_revision_id IS NULL THEN
            RAISE EXCEPTION 'proposal revision pointer transition is not allowed' USING ERRCODE='23514';
        END IF;
        SELECT revision_no,target_path,target_mode
          INTO source_no,source_path,source_mode
          FROM change_control.proposal_revision
         WHERE proposal_id=NEW.id AND id=OLD.current_revision_id;
        SELECT revision_no,target_path,target_mode
          INTO result_no,result_path,result_mode
          FROM change_control.proposal_revision
         WHERE proposal_id=NEW.id AND id=NEW.current_revision_id;
        IF source_no IS NULL OR result_no<>source_no+1
           OR source_path<>result_path OR source_mode<>'REPLACE' OR result_mode<>'REPLACE' THEN
            RAISE EXCEPTION 'proposal revision pointer binding is invalid' USING ERRCODE='23514';
        END IF;
        RETURN NEW;
    END IF;

    IF NEW.proposal_type='publish_artifact' AND NEW.workflow_run_id IS NOT NULL THEN
        RAISE EXCEPTION 'publish artifact proposal cannot bind a writeback workflow' USING ERRCODE='23514';
    END IF;
    IF NEW.proposal_type='downstream_update' THEN
        IF NEW.workflow_run_id IS NOT NULL
           OR NOT (OLD.status='ready_for_review' AND NEW.status IN ('approved','rejected')) THEN
            RAISE EXCEPTION 'downstream update apply is unavailable' USING ERRCODE='23514';
        END IF;
        RETURN NEW;
    END IF;

    workflow_binding_added := OLD.workflow_run_id IS NULL AND NEW.workflow_run_id IS NOT NULL;
    IF workflow_binding_added
       AND NEW.status='approved'
       AND OLD.status IN ('ready_for_review','approved') THEN
        RETURN NEW;
    END IF;

    IF NOT (
        (OLD.status='ready_for_review' AND NEW.status IN ('approved','rejected','needs_revision'))
        OR (OLD.status='approved' AND NEW.status IN ('applying','needs_revision'))
        OR (OLD.status='applying' AND NEW.status IN ('applied','apply_failed','needs_revision'))
        OR (OLD.status='applied' AND NEW.status='verifying')
        OR (OLD.status='verifying' AND NEW.status IN ('completed','verify_failed','rolled_back'))
        OR (OLD.status='verify_failed' AND NEW.status IN ('verifying','rolled_back'))
        OR (OLD.status='apply_failed' AND NEW.status IN ('applying','rolled_back'))
        OR (OLD.status='needs_revision' AND NEW.status IN ('draft','cancelled'))
    ) THEN
        RAISE EXCEPTION 'proposal status transition is not allowed' USING ERRCODE='23514';
    END IF;
    RETURN NEW;
END;
$$;


--
-- Name: validate_restore_document_revision_payload(); Type: FUNCTION; Schema: change_control; Owner: -
--

CREATE FUNCTION change_control.validate_restore_document_revision_payload() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    proposal_type_value text;
    proposal_workspace_id uuid;
    proposal_risk_level text;
BEGIN
    SELECT proposal_type,workspace_id,risk_level
      INTO proposal_type_value,proposal_workspace_id,proposal_risk_level
      FROM change_control.proposal
     WHERE id=NEW.proposal_id
     FOR SHARE;

    IF proposal_type_value IS DISTINCT FROM 'restore_document'
       OR proposal_workspace_id IS DISTINCT FROM NEW.restore_workspace_id
       OR proposal_risk_level IS DISTINCT FROM 'HIGH'
       OR NEW.target_path IS NULL
       OR NEW.target_mode IS DISTINCT FROM 'REPLACE'
       OR NEW.base_hash IS NULL
       OR NEW.content IS NULL
       OR NEW.evidence_summary IS NULL
       OR NEW.target_refs IS NOT NULL
       OR NEW.base_versions IS NOT NULL
       OR NEW.change_set IS NOT NULL
       OR NEW.evidence_refs IS NOT NULL
       OR NEW.artifact_id IS NOT NULL
       OR NEW.artifact_revision_id IS NOT NULL
       OR NEW.artifact_revision_no IS NOT NULL
       OR NEW.artifact_version IS NOT NULL
       OR NEW.artifact_content_hash IS NOT NULL
       OR NEW.artifact_source_coverage IS NOT NULL
       OR NEW.downstream_workspace_id IS NOT NULL
       OR NEW.downstream_report_id IS NOT NULL
       OR NEW.downstream_analysis_version IS NOT NULL
       OR NEW.downstream_report_fingerprint IS NOT NULL
       OR NEW.downstream_source_event_id IS NOT NULL
       OR NEW.downstream_source_event_version IS NOT NULL
       OR NEW.downstream_target_type IS NOT NULL
       OR NEW.downstream_target_id IS NOT NULL
       OR NEW.downstream_base_version IS NOT NULL
       OR NEW.downstream_action IS NOT NULL
       OR NEW.downstream_owner_binding IS NOT NULL
       OR NEW.downstream_reason IS NOT NULL
       OR NEW.restore_workspace_id IS NULL
       OR NEW.restore_document_id IS NULL
       OR NEW.restore_target_commit IS NULL
       OR NEW.restore_expected_head IS NULL
       OR NEW.restore_expected_document_version IS NULL
       OR NEW.restore_preview_hash IS NULL
       OR NEW.restore_current_content_hash IS NULL
       OR NEW.restore_target_content_hash IS NULL
       OR NEW.schema_version IS DISTINCT FROM 'document-restore/v1'
       OR NEW.base_hash IS DISTINCT FROM NEW.restore_current_content_hash
       OR encode(sha256(convert_to(NEW.content,'UTF8')),'hex')
          IS DISTINCT FROM NEW.restore_target_content_hash THEN
        RAISE EXCEPTION 'restore document revision requires frozen restore and file fields only'
            USING ERRCODE='23514';
    END IF;

    PERFORM document.id
      FROM core.document AS document
     WHERE document.id=NEW.restore_document_id
       AND document.workspace_id=NEW.restore_workspace_id
       AND document.canonical_path=NEW.target_path
       AND document.version=NEW.restore_expected_document_version
       AND document.lifecycle_status='PUBLISHED'
       AND document.current_published_revision_id IS NOT NULL
     FOR SHARE OF document;
    IF NOT FOUND THEN
        RAISE EXCEPTION 'restore document binding is stale' USING ERRCODE='23514';
    END IF;
    RETURN NEW;
END;
$$;


--
-- Name: validate_revision_append_closure(); Type: FUNCTION; Schema: change_control; Owner: -
--

CREATE FUNCTION change_control.validate_revision_append_closure() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    source_change_hash text;
    result_base_hash text;
    snapshot_base_hash text;
    lineage_source uuid;
    lineage_source_hash text;
    lineage_algorithm text;
    lineage_algorithm_version text;
    lineage_fingerprint text;
    receipt_workspace uuid;
    receipt_source uuid;
    receipt_source_hash text;
    receipt_expected_version bigint;
    receipt_expected_hash text;
    receipt_preview_hash text;
    receipt_algorithm text;
    receipt_algorithm_version text;
    receipt_result_version bigint;
BEGIN
    IF NEW.current_revision_id IS NOT DISTINCT FROM OLD.current_revision_id THEN
        RETURN NEW;
    END IF;
    SELECT change_hash INTO source_change_hash
      FROM change_control.proposal_revision
     WHERE proposal_id=NEW.id AND id=OLD.current_revision_id;
    SELECT base_hash INTO result_base_hash
      FROM change_control.proposal_revision
     WHERE proposal_id=NEW.id AND id=NEW.current_revision_id;
    SELECT base_hash INTO snapshot_base_hash
      FROM change_control.proposal_revision_base_snapshot
     WHERE proposal_id=NEW.id AND revision_id=NEW.current_revision_id;
    SELECT source_revision_id,source_change_hash,merge_algorithm,merge_algorithm_version,merge_fingerprint
      INTO lineage_source,lineage_source_hash,lineage_algorithm,lineage_algorithm_version,lineage_fingerprint
      FROM change_control.proposal_revision_lineage
     WHERE proposal_id=NEW.id AND revision_id=NEW.current_revision_id;
    SELECT workspace_id,source_revision_id,source_change_hash,expected_proposal_version,
           expected_current_hash,preview_hash,merge_algorithm,merge_algorithm_version,result_proposal_version
      INTO receipt_workspace,receipt_source,receipt_source_hash,receipt_expected_version,
           receipt_expected_hash,receipt_preview_hash,receipt_algorithm,receipt_algorithm_version,receipt_result_version
      FROM change_control.proposal_revision_command
     WHERE proposal_id=NEW.id AND result_revision_id=NEW.current_revision_id;
    IF source_change_hash IS NULL OR result_base_hash IS NULL OR snapshot_base_hash IS NULL
       OR lineage_source IS NULL OR receipt_workspace IS NULL
       OR snapshot_base_hash<>result_base_hash
       OR lineage_source<>OLD.current_revision_id OR lineage_source_hash<>source_change_hash
       OR receipt_workspace<>NEW.workspace_id OR receipt_source<>OLD.current_revision_id
       OR receipt_source_hash<>source_change_hash OR receipt_expected_version<>OLD.version
       OR receipt_expected_hash<>result_base_hash OR receipt_preview_hash<>lineage_fingerprint
       OR receipt_algorithm<>lineage_algorithm OR receipt_algorithm_version<>lineage_algorithm_version
       OR receipt_result_version<>NEW.version THEN
        RAISE EXCEPTION 'proposal revision append closure is incomplete' USING ERRCODE='23514';
    END IF;
    RETURN NEW;
END $$;


--
-- Name: validate_revision_base_snapshot(); Type: FUNCTION; Schema: change_control; Owner: -
--

CREATE FUNCTION change_control.validate_revision_base_snapshot() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    revision_row change_control.proposal_revision%ROWTYPE;
    proposal_type_value text;
BEGIN
    SELECT revision.* INTO revision_row
      FROM change_control.proposal_revision AS revision
     WHERE revision.id=NEW.revision_id
       AND revision.proposal_id=NEW.proposal_id;
    SELECT proposal.proposal_type INTO proposal_type_value
      FROM change_control.proposal AS proposal
     WHERE proposal.id=NEW.proposal_id;
    IF revision_row.id IS NULL
       OR proposal_type_value<>'file_patch'
       OR revision_row.target_mode<>'REPLACE'
       OR revision_row.base_hash<>NEW.base_hash
       OR encode(sha256(convert_to(NEW.content,'UTF8')),'hex')<>NEW.base_hash THEN
        RAISE EXCEPTION 'proposal revision base snapshot binding mismatch' USING ERRCODE='23514';
    END IF;
    RETURN NEW;
END $$;


--
-- Name: validate_revision_command_receipt(); Type: FUNCTION; Schema: change_control; Owner: -
--

CREATE FUNCTION change_control.validate_revision_command_receipt() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    proposal_workspace uuid;
    source_no integer;
    source_hash text;
    result_no integer;
    result_base_hash text;
    lineage_source uuid;
    lineage_fingerprint text;
BEGIN
    SELECT workspace_id INTO proposal_workspace
      FROM change_control.proposal WHERE id=NEW.proposal_id;
    SELECT revision_no,change_hash INTO source_no,source_hash
      FROM change_control.proposal_revision
     WHERE proposal_id=NEW.proposal_id AND id=NEW.source_revision_id;
    SELECT revision_no,base_hash INTO result_no,result_base_hash
      FROM change_control.proposal_revision
     WHERE proposal_id=NEW.proposal_id AND id=NEW.result_revision_id;
    SELECT source_revision_id,merge_fingerprint INTO lineage_source,lineage_fingerprint
      FROM change_control.proposal_revision_lineage
     WHERE proposal_id=NEW.proposal_id AND revision_id=NEW.result_revision_id;
    IF proposal_workspace IS NULL OR proposal_workspace<>NEW.workspace_id
       OR source_no IS NULL OR source_hash<>NEW.source_change_hash
       OR result_no IS NULL OR result_no<>source_no+1 OR result_no<>NEW.result_revision_no
       OR result_base_hash<>NEW.expected_current_hash
       OR lineage_source IS NULL OR lineage_fingerprint IS NULL
       OR lineage_source<>NEW.source_revision_id OR lineage_fingerprint<>NEW.preview_hash THEN
        RAISE EXCEPTION 'proposal revision command receipt binding mismatch' USING ERRCODE='23514';
    END IF;
    RETURN NEW;
END $$;


--
-- Name: validate_revision_lineage(); Type: FUNCTION; Schema: change_control; Owner: -
--

CREATE FUNCTION change_control.validate_revision_lineage() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE source_no integer; result_no integer; source_hash text;
BEGIN
    SELECT revision_no,change_hash INTO source_no,source_hash FROM change_control.proposal_revision
     WHERE proposal_id=NEW.proposal_id AND id=NEW.source_revision_id;
    SELECT revision_no INTO result_no FROM change_control.proposal_revision
     WHERE proposal_id=NEW.proposal_id AND id=NEW.revision_id;
    IF source_no IS NULL OR result_no<>source_no+1 OR source_hash<>NEW.source_change_hash THEN
        RAISE EXCEPTION 'proposal revision lineage binding mismatch' USING ERRCODE='23514';
    END IF;
    RETURN NEW;
END $$;


--
-- Name: validate_tool_authorization_transition(); Type: FUNCTION; Schema: change_control; Owner: -
--

CREATE FUNCTION change_control.validate_tool_authorization_transition() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF NEW.id<>OLD.id OR NEW.workspace_id<>OLD.workspace_id OR NEW.workflow_run_id<>OLD.workflow_run_id
       OR NEW.node_run_id<>OLD.node_run_id OR NEW.proposal_id<>OLD.proposal_id OR NEW.revision_id<>OLD.revision_id
       OR NEW.approval_id<>OLD.approval_id OR NEW.tool_name<>OLD.tool_name OR NEW.capability<>OLD.capability
       OR NEW.scope<>OLD.scope OR NEW.approved_change_hash<>OLD.approved_change_hash OR NEW.target_mode<>OLD.target_mode
       OR NEW.target_version<>OLD.target_version OR NEW.token_hash<>OLD.token_hash OR NEW.idempotency_key<>OLD.idempotency_key
       OR NEW.issued_at<>OLD.issued_at OR NEW.expires_at<>OLD.expires_at OR NEW.version<>OLD.version+1
       OR OLD.status<>'issued' OR NEW.status NOT IN ('consumed','revoked','expired') THEN
        RAISE EXCEPTION 'tool authorization immutable field or transition violation' USING ERRCODE='23514';
    END IF;
    RETURN NEW;
END;
$$;


--
-- Name: validate_typed_proposal_approval(); Type: FUNCTION; Schema: change_control; Owner: -
--

CREATE FUNCTION change_control.validate_typed_proposal_approval() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    proposal_type_value text;
BEGIN
    SELECT proposal_type
      INTO proposal_type_value
      FROM change_control.proposal
     WHERE id=NEW.proposal_id
     FOR SHARE;

    IF proposal_type_value IN ('knowledge_change','publish_artifact','downstream_update')
       AND NEW.approved_git_head IS NOT NULL THEN
        RAISE EXCEPTION 'typed proposal approval cannot carry a git baseline'
            USING ERRCODE='23514';
    END IF;
    RETURN NEW;
END;
$$;


--
-- Name: validate_writeback_current_revision(); Type: FUNCTION; Schema: change_control; Owner: -
--

CREATE FUNCTION change_control.validate_writeback_current_revision() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    current_revision uuid;
    dispatch_run uuid;
    dispatch_approval uuid;
BEGIN
    SELECT p.current_revision_id,d.workflow_run_id,d.approval_id
      INTO current_revision,dispatch_run,dispatch_approval
      FROM change_control.proposal p
      LEFT JOIN change_control.proposal_revision_dispatch d
        ON d.proposal_id=p.id AND d.revision_id=NEW.revision_id
     WHERE p.id=NEW.proposal_id
     FOR UPDATE OF p;
    IF current_revision IS NULL OR current_revision<>NEW.revision_id
       OR dispatch_run IS NULL OR dispatch_run<>NEW.workflow_run_id
       OR dispatch_approval IS NULL OR dispatch_approval<>NEW.approval_id THEN
        RAISE EXCEPTION 'writeback execution is not bound to the current revision dispatch' USING ERRCODE='23514';
    END IF;
    RETURN NEW;
END;
$$;


--
-- Name: validate_writeback_execution_transition(); Type: FUNCTION; Schema: change_control; Owner: -
--

CREATE FUNCTION change_control.validate_writeback_execution_transition() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF NEW.id<>OLD.id OR NEW.workspace_id<>OLD.workspace_id OR NEW.workflow_run_id<>OLD.workflow_run_id
       OR NEW.node_run_id<>OLD.node_run_id OR NEW.proposal_id<>OLD.proposal_id OR NEW.revision_id<>OLD.revision_id
       OR NEW.approval_id<>OLD.approval_id OR NEW.write_authorization_id<>OLD.write_authorization_id
       OR NEW.git_authorization_id<>OLD.git_authorization_id OR NEW.target_path<>OLD.target_path
       OR NEW.target_mode<>OLD.target_mode OR NEW.base_hash<>OLD.base_hash OR NEW.result_hash<>OLD.result_hash
       OR NEW.approved_change_hash<>OLD.approved_change_hash OR NEW.approved_git_head<>OLD.approved_git_head
       OR NEW.idempotency_key<>OLD.idempotency_key OR NEW.created_at<>OLD.created_at
       OR NEW.updated_at<OLD.updated_at OR NEW.version<>OLD.version+1 THEN
        RAISE EXCEPTION 'writeback immutable field or version violation' USING ERRCODE='23514';
    END IF;
    IF NOT (
        (OLD.status='verifying' AND NEW.status='verifying'
         AND OLD.cleanup_completed_at IS NULL AND NEW.cleanup_completed_at IS NOT NULL
         AND NEW.failure_code IS NOT DISTINCT FROM OLD.failure_code
         AND NEW.manual_recovery_required=OLD.manual_recovery_required
         AND NEW.temporary_ref IS NOT DISTINCT FROM OLD.temporary_ref
         AND NEW.backup_ref IS NOT DISTINCT FROM OLD.backup_ref
         AND NEW.file_byte_size IS NOT DISTINCT FROM OLD.file_byte_size
         AND NEW.file_mode IS NOT DISTINCT FROM OLD.file_mode
         AND NEW.file_lock_token IS NOT DISTINCT FROM OLD.file_lock_token
         AND NEW.file_result_lock_token IS NOT DISTINCT FROM OLD.file_result_lock_token
         AND NEW.file_backup_lock_token IS NOT DISTINCT FROM OLD.file_backup_lock_token
         AND NEW.base_blob_id IS NOT DISTINCT FROM OLD.base_blob_id
         AND NEW.result_blob_id IS NOT DISTINCT FROM OLD.result_blob_id
         AND NEW.base_mode IS NOT DISTINCT FROM OLD.base_mode
         AND NEW.git_commit IS NOT DISTINCT FROM OLD.git_commit
         AND NEW.parent_git_commit IS NOT DISTINCT FROM OLD.parent_git_commit
         AND NEW.diff_hash IS NOT DISTINCT FROM OLD.diff_hash
         AND NEW.completed_at IS NOT DISTINCT FROM OLD.completed_at)
        OR (OLD.status='prepared' AND (
            NEW.status IN ('file_prepared','needs_revision','apply_failed')
            OR (OLD.target_mode='REPLACE' AND NEW.status='file_applied' AND OLD.temporary_ref IS NOT NULL AND OLD.backup_ref IS NOT NULL)
        ))
        OR (OLD.status='file_prepared' AND NEW.status IN ('file_applied','needs_revision','apply_failed','manual_recovery_required'))
        OR (OLD.status='file_applied' AND (
            NEW.status IN ('git_prepared','compensating_file','manual_recovery_required')
            OR (OLD.target_mode='REPLACE' AND NEW.status='git_committed' AND OLD.file_lock_token IS NULL)
        ))
        OR (OLD.status='git_prepared' AND NEW.status IN ('git_committed','compensating_file','manual_recovery_required'))
        OR (OLD.status='compensating_file' AND NEW.status IN ('compensated','manual_recovery_required'))
        OR (OLD.status='git_committed' AND NEW.status IN ('verifying','publish_recovery_required'))
        OR (OLD.status='publish_recovery_required' AND NEW.status IN ('verifying','manual_recovery_required'))
        OR (OLD.status='verifying' AND NEW.status IN ('completed','verify_failed','rolled_back'))
        OR (OLD.status='verify_failed' AND NEW.status IN ('verifying','rolled_back'))
    ) THEN
        RAISE EXCEPTION 'writeback status transition is not allowed' USING ERRCODE='23514';
    END IF;
    IF OLD.git_commit IS NOT NULL AND (NEW.git_commit IS DISTINCT FROM OLD.git_commit OR NEW.parent_git_commit IS DISTINCT FROM OLD.parent_git_commit OR NEW.diff_hash IS DISTINCT FROM OLD.diff_hash) THEN
        RAISE EXCEPTION 'writeback git result is immutable' USING ERRCODE='23514';
    END IF;
    IF OLD.result_blob_id IS NOT NULL AND (NEW.base_blob_id IS DISTINCT FROM OLD.base_blob_id OR NEW.result_blob_id IS DISTINCT FROM OLD.result_blob_id OR NEW.base_mode IS DISTINCT FROM OLD.base_mode OR NEW.diff_hash IS DISTINCT FROM OLD.diff_hash) THEN
        RAISE EXCEPTION 'writeback git intent is immutable' USING ERRCODE='23514';
    END IF;
    IF OLD.file_lock_token IS NOT NULL AND (NEW.temporary_ref IS DISTINCT FROM OLD.temporary_ref OR NEW.backup_ref IS DISTINCT FROM OLD.backup_ref OR NEW.file_byte_size IS DISTINCT FROM OLD.file_byte_size OR NEW.file_mode IS DISTINCT FROM OLD.file_mode OR NEW.file_lock_token IS DISTINCT FROM OLD.file_lock_token OR NEW.file_result_lock_token IS DISTINCT FROM OLD.file_result_lock_token OR NEW.file_backup_lock_token IS DISTINCT FROM OLD.file_backup_lock_token) THEN
        RAISE EXCEPTION 'writeback file lock binding is immutable' USING ERRCODE='23514';
    END IF;
    IF OLD.cleanup_completed_at IS NOT NULL AND NEW.cleanup_completed_at IS DISTINCT FROM OLD.cleanup_completed_at THEN
        RAISE EXCEPTION 'writeback cleanup marker is immutable' USING ERRCODE='23514';
    END IF;
    IF OLD.manual_recovery_required AND NOT NEW.manual_recovery_required THEN
        RAISE EXCEPTION 'writeback manual recovery flag is immutable' USING ERRCODE='23514';
    END IF;
    IF OLD.completed_at IS NOT NULL AND NEW.completed_at IS DISTINCT FROM OLD.completed_at THEN
        RAISE EXCEPTION 'writeback completion time is immutable' USING ERRCODE='23514';
    END IF;
    IF NEW.status='file_prepared' AND (
        NEW.temporary_ref IS NULL OR NEW.file_byte_size IS NULL OR NEW.file_mode IS NULL OR NEW.file_lock_token IS NULL OR NEW.file_result_lock_token IS NULL
        OR (NEW.target_mode='REPLACE' AND (NEW.backup_ref IS NULL OR NEW.file_backup_lock_token IS NULL))
        OR (NEW.target_mode='CREATE_ONLY' AND (NEW.backup_ref IS NOT NULL OR NEW.file_backup_lock_token IS NOT NULL))
    ) THEN
        RAISE EXCEPTION 'file_prepared requires durable file intent' USING ERRCODE='23514';
    END IF;
    IF NEW.status='git_prepared' AND (
        NEW.result_blob_id IS NULL OR NEW.base_mode IS NULL OR NEW.diff_hash IS NULL
        OR (NEW.target_mode='REPLACE' AND NEW.base_blob_id IS NULL)
        OR (NEW.target_mode='CREATE_ONLY' AND NEW.base_blob_id IS NOT NULL)
    ) THEN
        RAISE EXCEPTION 'git_prepared requires durable git intent' USING ERRCODE='23514';
    END IF;
    RETURN NEW;
END;
$$;


--
-- Name: validate_writeback_reindex_insert(); Type: FUNCTION; Schema: change_control; Owner: -
--

CREATE FUNCTION change_control.validate_writeback_reindex_insert() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    execution change_control.writeback_execution%ROWTYPE;
    payload_key_count integer;
BEGIN
    IF NEW.event_type <> 'retrieval.revision.reindex_requested' THEN
        RETURN NEW;
    END IF;
    SELECT count(*) INTO payload_key_count FROM jsonb_object_keys(NEW.payload);
    IF NEW.run_id IS NULL OR payload_key_count <> 11
       OR NOT (NEW.payload ?& ARRAY[
            'schema_version','workspace_id','workflow_run_id','node_run_id','proposal_id','revision_id',
            'approval_id','writeback_execution_id','target_path','result_hash','git_commit'
       ])
       OR NEW.payload->'schema_version' <> '1'::jsonb THEN
        RAISE EXCEPTION 'writeback reindex payload schema mismatch' USING ERRCODE = '23514';
    END IF;

    SELECT * INTO execution
      FROM change_control.writeback_execution
     WHERE id::text = NEW.payload->>'writeback_execution_id'
     FOR UPDATE;
    IF execution.id IS NULL OR execution.status NOT IN ('git_committed','publish_recovery_required','verifying')
       OR NEW.workspace_id::text <> NEW.payload->>'workspace_id'
       OR NEW.run_id::text <> NEW.payload->>'workflow_run_id'
       OR execution.workspace_id <> NEW.workspace_id OR execution.workflow_run_id <> NEW.run_id
       OR execution.node_run_id::text <> NEW.payload->>'node_run_id'
       OR execution.proposal_id::text <> NEW.payload->>'proposal_id'
       OR execution.revision_id::text <> NEW.payload->>'revision_id'
       OR execution.approval_id::text <> NEW.payload->>'approval_id'
       OR execution.target_path <> NEW.payload->>'target_path'
       OR execution.result_hash <> NEW.payload->>'result_hash'
       OR execution.git_commit <> NEW.payload->>'git_commit'
       OR NEW.idempotency_key <> 'reindex:' || execution.workspace_id::text || ':' || execution.proposal_id::text || ':' || execution.revision_id::text || ':' || execution.git_commit THEN
        RAISE EXCEPTION 'writeback reindex event binding mismatch' USING ERRCODE = '23514';
    END IF;
    RETURN NEW;
END;
$$;


--
-- Name: verify_proposal_commit_binding(); Type: FUNCTION; Schema: change_control; Owner: -
--

CREATE FUNCTION change_control.verify_proposal_commit_binding() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    execution change_control.writeback_execution%ROWTYPE;
    proposal_status text;
    revision_proposal uuid;
    revision_target text;
    revision_target_mode text;
    revision_change_hash text;
    approval_proposal uuid;
    approval_revision uuid;
    approval_change_hash text;
    approval_decision text;
    approval_git_head text;
BEGIN
    SELECT * INTO execution FROM change_control.writeback_execution WHERE id=NEW.writeback_execution_id FOR UPDATE;
    SELECT p.status,r.proposal_id,r.target_path,r.target_mode,r.change_hash,a.proposal_id,a.revision_id,a.change_hash,a.decision,a.approved_git_head
      INTO proposal_status,revision_proposal,revision_target,revision_target_mode,revision_change_hash,
           approval_proposal,approval_revision,approval_change_hash,approval_decision,approval_git_head
      FROM change_control.proposal p
      JOIN change_control.proposal_revision r ON r.id=execution.revision_id
      JOIN change_control.approval a ON a.id=execution.approval_id
     WHERE p.id=execution.proposal_id
     FOR UPDATE OF p,r,a;
    IF execution.id IS NULL OR execution.status NOT IN ('git_committed','publish_recovery_required','verifying')
       OR NEW.workspace_id<>execution.workspace_id OR NEW.proposal_id<>execution.proposal_id
       OR NEW.revision_id<>execution.revision_id OR NEW.approval_id<>execution.approval_id
       OR NEW.git_commit<>execution.git_commit OR NEW.parent_git_commit<>execution.parent_git_commit
       OR NEW.target_path<>execution.target_path OR NEW.target_mode<>execution.target_mode
       OR NEW.diff_hash<>execution.diff_hash OR NEW.result_hash<>execution.result_hash
       OR proposal_status NOT IN ('applied','verifying') OR revision_proposal<>execution.proposal_id
       OR revision_target<>execution.target_path OR revision_target_mode<>execution.target_mode
       OR revision_change_hash<>execution.approved_change_hash
       OR approval_proposal<>execution.proposal_id OR approval_revision<>execution.revision_id
       OR approval_change_hash<>execution.approved_change_hash OR approval_decision<>'approved'
       OR approval_git_head IS NULL OR approval_git_head<>execution.approved_git_head THEN
        RAISE EXCEPTION 'proposal commit binding mismatch' USING ERRCODE='23514';
    END IF;
    RETURN NEW;
END;
$$;


--
-- Name: verify_tool_authorization_binding(); Type: FUNCTION; Schema: change_control; Owner: -
--

CREATE FUNCTION change_control.verify_tool_authorization_binding() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    proposal_workspace uuid;
    proposal_status text;
    proposal_target_path text;
    proposal_target_mode text;
    revision_proposal uuid;
    revision_base_hash text;
    revision_change_hash text;
    approval_proposal uuid;
    approval_revision uuid;
    approval_change_hash text;
    approval_decision text;
    run_workspace uuid;
    node_run_id uuid;
    expected_scope text;
BEGIN
    IF TG_OP='INSERT' AND (NEW.status<>'issued' OR NEW.version<>1 OR NEW.consumed_at IS NOT NULL OR NEW.revoked_at IS NOT NULL) THEN
        RAISE EXCEPTION 'tool authorization must be inserted as issued version one' USING ERRCODE='23514';
    END IF;
    IF (NEW.capability='WRITE_KNOWLEDGE' AND NEW.tool_name<>'ApplyApprovedPatch')
       OR (NEW.capability='GIT_WRITE' AND NEW.tool_name<>'CreateGitCommit') THEN
        RAISE EXCEPTION 'tool authorization capability/tool mismatch' USING ERRCODE='23514';
    END IF;
    SELECT p.workspace_id,p.status,r.target_path,r.target_mode,r.proposal_id,r.base_hash,r.change_hash,
           a.proposal_id,a.revision_id,a.change_hash,a.decision
      INTO proposal_workspace,proposal_status,proposal_target_path,proposal_target_mode,revision_proposal,revision_base_hash,revision_change_hash,
           approval_proposal,approval_revision,approval_change_hash,approval_decision
      FROM change_control.proposal p
      JOIN change_control.proposal_revision r ON r.id=NEW.revision_id
      JOIN change_control.approval a ON a.id=NEW.approval_id
     WHERE p.id=NEW.proposal_id
     FOR UPDATE OF p,r,a;
    expected_scope := CASE proposal_target_mode
        WHEN 'CREATE_ONLY' THEN 'target:create-only:' || proposal_target_path
        ELSE 'target:' || proposal_target_path
    END;
    IF proposal_workspace IS NULL OR proposal_workspace<>NEW.workspace_id OR proposal_status<>'approved'
       OR NEW.target_mode<>proposal_target_mode
       OR NEW.scope<>expected_scope
       OR revision_proposal<>NEW.proposal_id OR approval_proposal<>NEW.proposal_id OR approval_revision<>NEW.revision_id
       OR approval_decision<>'approved' OR revision_change_hash<>NEW.approved_change_hash
       OR approval_change_hash<>NEW.approved_change_hash OR revision_base_hash<>NEW.target_version THEN
        RAISE EXCEPTION 'tool authorization approval binding mismatch' USING ERRCODE='23514';
    END IF;
    SELECT r.workspace_id,n.id INTO run_workspace,node_run_id
      FROM workflow.run r JOIN workflow.node_run n ON n.run_id=r.id
     WHERE r.id=NEW.workflow_run_id AND n.id=NEW.node_run_id
       AND r.status IN ('pending','running','waiting_for_human')
       AND n.status IN ('pending','running','waiting_for_human')
     FOR UPDATE OF r,n;
    IF run_workspace IS NULL OR run_workspace<>NEW.workspace_id OR node_run_id IS NULL THEN
        RAISE EXCEPTION 'tool authorization workflow binding mismatch' USING ERRCODE='23514';
    END IF;
    RETURN NEW;
END;
$$;


--
-- Name: verify_writeback_execution_binding(); Type: FUNCTION; Schema: change_control; Owner: -
--

CREATE FUNCTION change_control.verify_writeback_execution_binding() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    proposal_workspace uuid;
    proposal_status text;
    revision_proposal uuid;
    revision_target text;
    revision_target_mode text;
    revision_base_hash text;
    revision_change_hash text;
    approval_proposal uuid;
    approval_revision uuid;
    approval_change_hash text;
    approval_decision text;
    approval_git_head text;
    run_workspace uuid;
    bound_node uuid;
    expected_scope text;
    write_authorization change_control.tool_authorization%ROWTYPE;
    git_authorization change_control.tool_authorization%ROWTYPE;
    existing_execution change_control.writeback_execution%ROWTYPE;
BEGIN
    IF NEW.status<>'prepared' OR NEW.version<>1
       OR NEW.git_commit IS NOT NULL OR NEW.parent_git_commit IS NOT NULL OR NEW.diff_hash IS NOT NULL
       OR NEW.failure_code IS NOT NULL OR NEW.manual_recovery_required OR NEW.completed_at IS NOT NULL THEN
        RAISE EXCEPTION 'writeback execution must be inserted as prepared version one' USING ERRCODE='23514';
    END IF;
    IF NEW.write_authorization_id=NEW.git_authorization_id THEN
        RAISE EXCEPTION 'writeback requires two distinct authorizations' USING ERRCODE='23514';
    END IF;
    PERFORM id FROM change_control.tool_authorization
     WHERE id IN (NEW.write_authorization_id,NEW.git_authorization_id)
     ORDER BY id FOR UPDATE;

    SELECT p.workspace_id,p.status,r.proposal_id,r.target_path,r.target_mode,r.base_hash,r.change_hash,
           a.proposal_id,a.revision_id,a.change_hash,a.decision,a.approved_git_head
      INTO proposal_workspace,proposal_status,revision_proposal,revision_target,revision_target_mode,revision_base_hash,revision_change_hash,
           approval_proposal,approval_revision,approval_change_hash,approval_decision,approval_git_head
      FROM change_control.proposal p
      JOIN change_control.proposal_revision r ON r.id=NEW.revision_id
      JOIN change_control.approval a ON a.id=NEW.approval_id
     WHERE p.id=NEW.proposal_id
     FOR UPDATE OF p,r,a;
    IF proposal_status<>'approved' THEN
        SELECT * INTO existing_execution FROM change_control.writeback_execution
         WHERE (workspace_id=NEW.workspace_id AND idempotency_key=NEW.idempotency_key)
            OR (proposal_id=NEW.proposal_id AND revision_id=NEW.revision_id)
         ORDER BY id LIMIT 1 FOR UPDATE;
        IF existing_execution.id IS NOT NULL
           AND existing_execution.workspace_id=NEW.workspace_id
           AND existing_execution.workflow_run_id=NEW.workflow_run_id
           AND existing_execution.node_run_id=NEW.node_run_id
           AND existing_execution.proposal_id=NEW.proposal_id
           AND existing_execution.revision_id=NEW.revision_id
           AND existing_execution.approval_id=NEW.approval_id
           AND existing_execution.write_authorization_id=NEW.write_authorization_id
           AND existing_execution.git_authorization_id=NEW.git_authorization_id
           AND existing_execution.target_path=NEW.target_path
           AND existing_execution.target_mode=NEW.target_mode
           AND existing_execution.base_hash=NEW.base_hash
           AND existing_execution.result_hash=NEW.result_hash
           AND existing_execution.approved_change_hash=NEW.approved_change_hash
           AND existing_execution.approved_git_head=NEW.approved_git_head
           AND existing_execution.idempotency_key=NEW.idempotency_key THEN
            RETURN NEW;
        END IF;
        RAISE EXCEPTION 'writeback proposal is no longer approved' USING ERRCODE='23514';
    END IF;
    IF proposal_workspace IS NULL OR proposal_workspace<>NEW.workspace_id OR proposal_status<>'approved'
       OR revision_proposal<>NEW.proposal_id OR revision_target<>NEW.target_path OR revision_target_mode<>NEW.target_mode
       OR revision_base_hash<>NEW.base_hash OR revision_change_hash<>NEW.approved_change_hash
       OR approval_proposal<>NEW.proposal_id OR approval_revision<>NEW.revision_id
       OR approval_change_hash<>NEW.approved_change_hash OR approval_decision<>'approved'
       OR approval_git_head IS NULL OR approval_git_head<>NEW.approved_git_head THEN
        RAISE EXCEPTION 'writeback proposal approval binding mismatch' USING ERRCODE='23514';
    END IF;
    SELECT r.workspace_id,n.id INTO run_workspace,bound_node
      FROM workflow.run r JOIN workflow.node_run n ON n.run_id=r.id
     WHERE r.id=NEW.workflow_run_id AND n.id=NEW.node_run_id
       AND r.status IN ('pending','running','waiting_for_human')
       AND n.status IN ('pending','running','waiting_for_human')
     FOR UPDATE OF r,n;
    IF run_workspace IS NULL OR run_workspace<>NEW.workspace_id OR bound_node IS NULL THEN
        RAISE EXCEPTION 'writeback workflow binding mismatch' USING ERRCODE='23514';
    END IF;
    SELECT * INTO write_authorization FROM change_control.tool_authorization WHERE id=NEW.write_authorization_id FOR UPDATE;
    SELECT * INTO git_authorization FROM change_control.tool_authorization WHERE id=NEW.git_authorization_id FOR UPDATE;
    expected_scope := CASE NEW.target_mode WHEN 'CREATE_ONLY' THEN 'target:create-only:' || NEW.target_path ELSE 'target:' || NEW.target_path END;
    IF write_authorization.id IS NULL OR git_authorization.id IS NULL
       OR write_authorization.workspace_id<>NEW.workspace_id OR git_authorization.workspace_id<>NEW.workspace_id
       OR write_authorization.workflow_run_id<>NEW.workflow_run_id OR git_authorization.workflow_run_id<>NEW.workflow_run_id
       OR write_authorization.node_run_id<>NEW.node_run_id OR git_authorization.node_run_id<>NEW.node_run_id
       OR write_authorization.proposal_id<>NEW.proposal_id OR git_authorization.proposal_id<>NEW.proposal_id
       OR write_authorization.revision_id<>NEW.revision_id OR git_authorization.revision_id<>NEW.revision_id
       OR write_authorization.approval_id<>NEW.approval_id OR git_authorization.approval_id<>NEW.approval_id
       OR write_authorization.tool_name<>'ApplyApprovedPatch' OR write_authorization.capability<>'WRITE_KNOWLEDGE'
       OR git_authorization.tool_name<>'CreateGitCommit' OR git_authorization.capability<>'GIT_WRITE'
       OR write_authorization.target_mode<>NEW.target_mode OR git_authorization.target_mode<>NEW.target_mode
       OR write_authorization.scope<>expected_scope OR git_authorization.scope<>expected_scope
       OR write_authorization.approved_change_hash<>NEW.approved_change_hash OR git_authorization.approved_change_hash<>NEW.approved_change_hash
       OR write_authorization.target_version<>NEW.base_hash OR git_authorization.target_version<>NEW.base_hash
       OR NOT (write_authorization.status='consumed' OR (write_authorization.status='issued' AND CURRENT_TIMESTAMP<write_authorization.expires_at))
       OR NOT (git_authorization.status='consumed' OR (git_authorization.status='issued' AND CURRENT_TIMESTAMP<git_authorization.expires_at)) THEN
        RAISE EXCEPTION 'writeback authorization binding mismatch' USING ERRCODE='23514';
    END IF;
    RETURN NEW;
END;
$$;


--
-- Name: bind_source_version_workspace(); Type: FUNCTION; Schema: core; Owner: -
--

CREATE FUNCTION core.bind_source_version_workspace() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    source_workspace_id uuid;
BEGIN
    SELECT workspace_id
      INTO source_workspace_id
      FROM core.source
     WHERE id = NEW.source_id;

    IF source_workspace_id IS NULL THEN
        RAISE EXCEPTION 'source version source workspace is missing' USING ERRCODE = '23514';
    END IF;
    IF NEW.workspace_id IS NULL THEN
        NEW.workspace_id := source_workspace_id;
    ELSIF NEW.workspace_id <> source_workspace_id THEN
        RAISE EXCEPTION 'source version workspace does not match source' USING ERRCODE = '23514';
    END IF;
    RETURN NEW;
END;
$$;


--
-- Name: bump_workspace_read_model_revision(); Type: FUNCTION; Schema: core; Owner: -
--

CREATE FUNCTION core.bump_workspace_read_model_revision() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    owner_workspace_id uuid;
    workspace_ids uuid[];
    knowledge_delta bigint := 0;
    conflict_delta bigint := 0;
    health_delta bigint := 0;
BEGIN
    IF TG_TABLE_SCHEMA = 'core' AND TG_TABLE_NAME = 'source_version' THEN
        SELECT workspace_id
          INTO owner_workspace_id
          FROM core.source
         WHERE id = CASE WHEN TG_OP = 'DELETE' THEN OLD.source_id ELSE NEW.source_id END;
    ELSIF TG_OP = 'UPDATE' AND OLD.workspace_id IS DISTINCT FROM NEW.workspace_id THEN
        workspace_ids := ARRAY[OLD.workspace_id, NEW.workspace_id];
    ELSE
        workspace_ids := ARRAY[CASE WHEN TG_OP = 'DELETE' THEN OLD.workspace_id ELSE NEW.workspace_id END];
    END IF;

    IF owner_workspace_id IS NOT NULL THEN
        workspace_ids := ARRAY[owner_workspace_id];
    END IF;

    IF workspace_ids IS NULL OR array_length(workspace_ids, 1) IS NULL THEN
        RAISE EXCEPTION 'read model revision workspace is missing'
            USING ERRCODE = '23514';
    END IF;

    SELECT array_agg(candidate.workspace_id ORDER BY candidate.workspace_id)
      INTO workspace_ids
      FROM (
          SELECT DISTINCT unnest(workspace_ids) AS workspace_id
      ) AS candidate;

    CASE TG_ARGV[0]
        WHEN 'knowledge' THEN knowledge_delta := 1;
        WHEN 'conflict' THEN conflict_delta := 1;
        WHEN 'health' THEN health_delta := 1;
        ELSE RAISE EXCEPTION 'read model revision kind is invalid' USING ERRCODE = '23514';
    END CASE;

    FOREACH owner_workspace_id IN ARRAY workspace_ids LOOP
        IF owner_workspace_id IS NULL THEN
            RAISE EXCEPTION 'read model revision workspace is missing' USING ERRCODE = '23514';
        END IF;
        INSERT INTO core.workspace_read_model_revision(
            workspace_id,knowledge_revision,conflict_revision,health_revision,updated_at
        ) VALUES (
            owner_workspace_id,knowledge_delta,conflict_delta,health_delta,CURRENT_TIMESTAMP
        )
        ON CONFLICT (workspace_id) DO UPDATE
        SET knowledge_revision = core.workspace_read_model_revision.knowledge_revision + EXCLUDED.knowledge_revision,
            conflict_revision = core.workspace_read_model_revision.conflict_revision + EXCLUDED.conflict_revision,
            health_revision = core.workspace_read_model_revision.health_revision + EXCLUDED.health_revision,
            updated_at = GREATEST(core.workspace_read_model_revision.updated_at, EXCLUDED.updated_at);
    END LOOP;

    IF TG_OP = 'DELETE' THEN
        RETURN OLD;
    END IF;
    RETURN NEW;
END;
$$;


--
-- Name: enforce_workspace_registry(); Type: FUNCTION; Schema: core; Owner: -
--

CREATE FUNCTION core.enforce_workspace_registry() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF TG_OP IN ('DELETE','TRUNCATE') THEN
        RAISE EXCEPTION 'workspace registry identities must be soft removed' USING ERRCODE='55000';
    END IF;
    IF TG_OP='INSERT' THEN
        RETURN NEW;
    END IF;
    IF ROW(NEW.root_path,NEW.git_repository_path,NEW.root_fingerprint,NEW.binding_version)
       IS DISTINCT FROM ROW(OLD.root_path,OLD.git_repository_path,OLD.root_fingerprint,OLD.binding_version) THEN
        IF ROW(NEW.id,NEW.name,NEW.root_path,NEW.git_repository_path,
               NEW.git_branch,NEW.git_head,NEW.git_dirty,NEW.git_checked_at,
               NEW.status,NEW.last_opened_at,NEW.removed_at,NEW.created_at)
           IS DISTINCT FROM
           ROW(OLD.id,OLD.name,OLD.root_path,OLD.git_repository_path,
               OLD.git_branch,OLD.git_head,OLD.git_dirty,OLD.git_checked_at,
               OLD.status,OLD.last_opened_at,OLD.removed_at,OLD.created_at)
           OR OLD.status<>'inactive'
           OR OLD.availability<>'migration_required'
           OR OLD.availability_reason<>'WORKSPACE_ROOT_IDENTITY_CHANGED'
           OR OLD.removed_at IS NOT NULL
           OR NEW.root_path<>OLD.root_path
           OR NEW.git_repository_path<>OLD.git_repository_path
           OR NEW.root_fingerprint=OLD.root_fingerprint
           OR NEW.binding_version<>OLD.binding_version+1
           OR NEW.availability<>'available'
           OR NEW.availability_reason IS NOT NULL
           OR NEW.availability_checked_at IS NULL
           OR NEW.availability_checked_at<OLD.availability_checked_at
           OR NEW.version<>OLD.version+1
           OR NEW.updated_at<OLD.updated_at
           OR NOT EXISTS (
                SELECT 1
                FROM ops.workspace_root_binding_history AS history
                WHERE history.workspace_id=OLD.id
                  AND history.canonical_root=OLD.root_path
                  AND history.old_root_fingerprint=OLD.root_fingerprint
                  AND history.new_root_fingerprint=NEW.root_fingerprint
                  AND history.old_binding_version=OLD.binding_version
                  AND history.new_binding_version=NEW.binding_version
                  AND history.old_workspace_version=OLD.version
                  AND history.new_workspace_version=NEW.version
                  AND history.reason='WORKSPACE_ROOT_IDENTITY_CHANGED'
                  AND history.transaction_id=pg_current_xact_id()
           ) THEN
            RAISE EXCEPTION 'workspace root binding is immutable' USING ERRCODE='55000';
        END IF;
        RETURN NEW;
    END IF;
    IF NEW.version<>OLD.version+1 OR NEW.updated_at<OLD.updated_at THEN
        RAISE EXCEPTION 'workspace registry version is invalid' USING ERRCODE='40001';
    END IF;
    IF OLD.removed_at IS NOT NULL AND NEW.removed_at IS NULL
       AND NEW.availability<>'available' THEN
        RAISE EXCEPTION 'removed workspace can only be restored after availability verification' USING ERRCODE='55000';
    END IF;
    RETURN NEW;
END
$$;


--
-- Name: knowledge_reject_immutable_mutation(); Type: FUNCTION; Schema: core; Owner: -
--

CREATE FUNCTION core.knowledge_reject_immutable_mutation() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    RAISE EXCEPTION 'knowledge record is immutable' USING ERRCODE = '55000';
END;
$$;


--
-- Name: knowledge_validate_claim_write(); Type: FUNCTION; Schema: core; Owner: -
--

CREATE FUNCTION core.knowledge_validate_claim_write() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF TG_OP = 'INSERT' THEN
        IF NEW.status <> 'SUGGESTED' OR NEW.version <> 1 THEN
            RAISE EXCEPTION 'knowledge claim has an invalid initial state' USING ERRCODE = '23514';
        END IF;
        RETURN NEW;
    END IF;

    IF NEW.id <> OLD.id
       OR NEW.workspace_id <> OLD.workspace_id
       OR NEW.statement <> OLD.statement
       OR NEW.normalized_statement <> OLD.normalized_statement
       OR NEW.applicability <> OLD.applicability
       OR NEW.applicability_schema_version <> OLD.applicability_schema_version
       OR NEW.applicability_hash <> OLD.applicability_hash
       OR NEW.fingerprint <> OLD.fingerprint
       OR NEW.created_at <> OLD.created_at
       OR NEW.version <> OLD.version + 1
       OR NEW.updated_at < OLD.updated_at THEN
        RAISE EXCEPTION 'knowledge claim immutable binding or version changed' USING ERRCODE = '23514';
    END IF;
    IF OLD.status IN ('SUPERSEDED', 'DEPRECATED', 'INVALID') THEN
        RAISE EXCEPTION 'terminal knowledge claim is immutable' USING ERRCODE = '55000';
    END IF;
    IF NEW.status <> OLD.status AND NOT (
        (OLD.status = 'SUGGESTED' AND NEW.status IN ('CONFIRMED', 'INVALID'))
        OR (OLD.status = 'CONFIRMED' AND NEW.status IN ('DISPUTED', 'SUPERSEDED', 'DEPRECATED', 'INVALID'))
        OR (OLD.status = 'DISPUTED' AND NEW.status IN ('CONFIRMED', 'SUPERSEDED', 'DEPRECATED', 'INVALID'))
    ) THEN
        RAISE EXCEPTION 'knowledge claim transition is invalid' USING ERRCODE = '23514';
    END IF;
    IF OLD.status = 'DISPUTED' AND NEW.status = 'CONFIRMED' AND EXISTS (
        SELECT 1
          FROM core.conflict_member member
          JOIN core.conflict conflict
            ON conflict.id = member.conflict_id
           AND conflict.workspace_id = member.workspace_id
         WHERE member.workspace_id = NEW.workspace_id
           AND member.claim_id = NEW.id
           AND conflict.status NOT IN ('RESOLVED', 'ACCEPTED_DIVERGENCE')
    ) THEN
        RAISE EXCEPTION 'knowledge claim remains in an unresolved conflict' USING ERRCODE = '23514';
    END IF;
    RETURN NEW;
END;
$$;


--
-- Name: knowledge_validate_command_receipt_insert(); Type: FUNCTION; Schema: core; Owner: -
--

CREATE FUNCTION core.knowledge_validate_command_receipt_insert() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    current_version bigint;
BEGIN
    IF NEW.aggregate_type = 'TOPIC' THEN
        SELECT version INTO current_version FROM core.topic
         WHERE id = NEW.aggregate_id AND workspace_id = NEW.workspace_id FOR KEY SHARE;
    ELSIF NEW.aggregate_type = 'CLAIM' THEN
        SELECT version INTO current_version FROM core.claim
         WHERE id = NEW.aggregate_id AND workspace_id = NEW.workspace_id FOR KEY SHARE;
    ELSIF NEW.aggregate_type = 'RELATION' THEN
        SELECT version INTO current_version FROM core.relation
         WHERE id = NEW.aggregate_id AND workspace_id = NEW.workspace_id FOR KEY SHARE;
    ELSIF NEW.aggregate_type = 'CONFLICT' THEN
        SELECT version INTO current_version FROM core.conflict
         WHERE id = NEW.aggregate_id AND workspace_id = NEW.workspace_id FOR KEY SHARE;
    END IF;
    IF current_version IS NULL OR current_version <> NEW.aggregate_version THEN
        RAISE EXCEPTION 'knowledge command receipt aggregate binding is invalid' USING ERRCODE = '23514';
    END IF;
    RETURN NEW;
END;
$$;


--
-- Name: knowledge_validate_conflict_member_insert(); Type: FUNCTION; Schema: core; Owner: -
--

CREATE FUNCTION core.knowledge_validate_conflict_member_insert() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    claim_status text;
    claim_applicability jsonb;
    claim_schema_version text;
    claim_applicability_hash text;
BEGIN
    SELECT status, applicability, applicability_schema_version, applicability_hash
      INTO claim_status, claim_applicability, claim_schema_version, claim_applicability_hash
      FROM core.claim
     WHERE id = NEW.claim_id
       AND workspace_id = NEW.workspace_id
     FOR SHARE;
    IF claim_status IS NULL OR claim_status NOT IN ('CONFIRMED', 'DISPUTED') THEN
        RAISE EXCEPTION 'knowledge conflict member claim is not disputable' USING ERRCODE = '23514';
    END IF;
    IF NEW.applicability <> claim_applicability
       OR NEW.applicability_schema_version <> claim_schema_version
       OR NEW.applicability_hash <> claim_applicability_hash THEN
        RAISE EXCEPTION 'knowledge conflict member applicability snapshot is invalid' USING ERRCODE = '23514';
    END IF;
    RETURN NEW;
END;
$$;


--
-- Name: knowledge_validate_conflict_write(); Type: FUNCTION; Schema: core; Owner: -
--

CREATE FUNCTION core.knowledge_validate_conflict_write() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF TG_OP = 'INSERT' THEN
        IF NEW.status <> 'OPEN' OR NEW.version <> 1 THEN
            RAISE EXCEPTION 'knowledge conflict must start open at version one' USING ERRCODE = '23514';
        END IF;
        RETURN NEW;
    END IF;

    IF NEW.id <> OLD.id
       OR NEW.workspace_id <> OLD.workspace_id
       OR NEW.topic_id IS DISTINCT FROM OLD.topic_id
       OR NEW.applicability_assessment <> OLD.applicability_assessment
       OR NEW.applicability_hash IS DISTINCT FROM OLD.applicability_hash
       OR NEW.overlap_reason IS DISTINCT FROM OLD.overlap_reason
       OR NEW.fingerprint <> OLD.fingerprint
       OR NEW.created_at <> OLD.created_at
       OR NEW.version <> OLD.version + 1
       OR NEW.updated_at < OLD.updated_at
       OR (OLD.resolution_reference IS NOT NULL
           AND NEW.resolution_reference IS DISTINCT FROM OLD.resolution_reference) THEN
        RAISE EXCEPTION 'knowledge conflict immutable binding or version changed' USING ERRCODE = '23514';
    END IF;
    IF OLD.status IN ('RESOLVED', 'ACCEPTED_DIVERGENCE') THEN
        RAISE EXCEPTION 'terminal knowledge conflict is immutable' USING ERRCODE = '55000';
    END IF;
    IF NEW.status <> OLD.status AND NOT (
        (OLD.status = 'OPEN' AND NEW.status IN ('INVESTIGATING', 'DEFERRED'))
        OR (OLD.status = 'INVESTIGATING' AND NEW.status IN ('RESOLUTION_PROPOSED', 'DEFERRED'))
        OR (OLD.status = 'DEFERRED' AND NEW.status = 'INVESTIGATING')
        OR (
            OLD.status = 'RESOLUTION_PROPOSED'
            AND NEW.status IN ('RESOLVED', 'ACCEPTED_DIVERGENCE', 'INVESTIGATING')
        )
    ) THEN
        RAISE EXCEPTION 'knowledge conflict transition is invalid' USING ERRCODE = '23514';
    END IF;
    RETURN NEW;
END;
$$;


--
-- Name: knowledge_validate_provenance_binding(uuid, uuid, uuid); Type: FUNCTION; Schema: core; Owner: -
--

CREATE FUNCTION core.knowledge_validate_provenance_binding(expected_workspace_id uuid, expected_source_version_id uuid, expected_source_span_id uuid) RETURNS boolean
    LANGUAGE sql STABLE
    AS $$
    SELECT EXISTS (
        SELECT 1
          FROM core.source_version source_version
          JOIN core.source source
            ON source.id = source_version.source_id
           AND source.workspace_id = expected_workspace_id
          JOIN core.content_artifact artifact
            ON artifact.id = source_version.content_artifact_id
           AND artifact.workspace_id = expected_workspace_id
           AND artifact.content_hash = source_version.content_hash
           AND artifact.byte_size = source_version.byte_size
          JOIN ingestion.source_version_projection source_projection
            ON source_projection.source_version_id = source_version.id
           AND source_projection.workspace_id = expected_workspace_id
          JOIN ingestion.parse_projection parse_projection
            ON parse_projection.id = source_projection.parse_projection_id
           AND parse_projection.workspace_id = expected_workspace_id
           AND parse_projection.content_artifact_id = artifact.id
          JOIN ingestion.source_span source_span
            ON source_span.id = expected_source_span_id
           AND source_span.workspace_id = expected_workspace_id
           AND source_span.content_artifact_id = artifact.id
           AND source_span.parse_projection_id = parse_projection.id
           AND source_span.parser_version = parse_projection.parser_version
           AND source_span.schema_version = parse_projection.schema_version
         WHERE source_version.id = expected_source_version_id
    );
$$;


--
-- Name: knowledge_validate_provenance_insert(); Type: FUNCTION; Schema: core; Owner: -
--

CREATE FUNCTION core.knowledge_validate_provenance_insert() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF NOT core.knowledge_validate_provenance_binding(
        NEW.workspace_id, NEW.source_version_id, NEW.source_span_id
    ) THEN
        RAISE EXCEPTION 'knowledge provenance binding is invalid' USING ERRCODE = '23514';
    END IF;
    RETURN NEW;
END;
$$;


--
-- Name: knowledge_validate_relation_endpoint(uuid, text, uuid); Type: FUNCTION; Schema: core; Owner: -
--

CREATE FUNCTION core.knowledge_validate_relation_endpoint(expected_workspace_id uuid, endpoint_type text, endpoint_id uuid) RETURNS void
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF endpoint_type = 'TOPIC' THEN
        PERFORM id FROM core.topic
         WHERE id = endpoint_id
           AND workspace_id = expected_workspace_id
           AND status = 'ACTIVE'
         FOR SHARE;
    ELSIF endpoint_type = 'CLAIM' THEN
        PERFORM id FROM core.claim
         WHERE id = endpoint_id
           AND workspace_id = expected_workspace_id
           AND status IN ('SUGGESTED', 'CONFIRMED', 'DISPUTED')
         FOR SHARE;
    ELSE
        RAISE EXCEPTION 'knowledge relation node type is invalid' USING ERRCODE = '23514';
    END IF;
    IF NOT FOUND THEN
        RAISE EXCEPTION 'knowledge relation endpoint is missing or inactive' USING ERRCODE = '23514';
    END IF;
END;
$$;


--
-- Name: knowledge_validate_relation_endpoint_identity(uuid, text, uuid); Type: FUNCTION; Schema: core; Owner: -
--

CREATE FUNCTION core.knowledge_validate_relation_endpoint_identity(expected_workspace_id uuid, endpoint_type text, endpoint_id uuid) RETURNS void
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF endpoint_type = 'TOPIC' THEN
        PERFORM id FROM core.topic
         WHERE id = endpoint_id
           AND workspace_id = expected_workspace_id
         FOR KEY SHARE;
    ELSIF endpoint_type = 'CLAIM' THEN
        PERFORM id FROM core.claim
         WHERE id = endpoint_id
           AND workspace_id = expected_workspace_id
         FOR KEY SHARE;
    ELSE
        RAISE EXCEPTION 'knowledge relation node type is invalid' USING ERRCODE = '23514';
    END IF;
    IF NOT FOUND THEN
        RAISE EXCEPTION 'knowledge relation endpoint identity is missing' USING ERRCODE = '23514';
    END IF;
END;
$$;


--
-- Name: knowledge_validate_relation_write(); Type: FUNCTION; Schema: core; Owner: -
--

CREATE FUNCTION core.knowledge_validate_relation_write() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    compatible boolean;
BEGIN
    IF TG_OP = 'UPDATE' THEN
        IF NEW.id <> OLD.id
           OR NEW.workspace_id <> OLD.workspace_id
           OR NEW.source_node_type <> OLD.source_node_type
           OR NEW.source_node_id <> OLD.source_node_id
           OR NEW.target_node_type <> OLD.target_node_type
           OR NEW.target_node_id <> OLD.target_node_id
           OR NEW.relation_type <> OLD.relation_type
           OR NEW.fingerprint <> OLD.fingerprint
           OR NEW.valid_from IS DISTINCT FROM OLD.valid_from
           OR NEW.created_at <> OLD.created_at
           OR NEW.version <> OLD.version + 1
           OR NEW.updated_at < OLD.updated_at
           OR (OLD.valid_to IS NOT NULL AND NEW.valid_to IS DISTINCT FROM OLD.valid_to)
           OR (
                (NEW.confirmation_method IS DISTINCT FROM OLD.confirmation_method
                 OR NEW.confirmation_ref IS DISTINCT FROM OLD.confirmation_ref)
                AND NOT (
                    OLD.status = 'STALE'
                    AND NEW.status = 'CONFIRMED'
                    AND NEW.confirmation_method IS NOT NULL
                    AND NEW.confirmation_ref IS NOT NULL
                )
                AND NOT (
                    OLD.status = 'STALE'
                    AND NEW.status = 'REJECTED'
                    AND NEW.confirmation_method IS NULL
                    AND NEW.confirmation_ref IS NULL
                )
                AND NOT (
                    OLD.status = 'REJECTED'
                    AND NEW.status = 'SUGGESTED'
                    AND NEW.confirmation_method IS NULL
                    AND NEW.confirmation_ref IS NULL
                )
                AND NOT (
                    OLD.confirmation_method IS NULL
                    AND OLD.confirmation_ref IS NULL
                    AND NEW.status = 'CONFIRMED'
                    AND NEW.confirmation_method IS NOT NULL
                    AND NEW.confirmation_ref IS NOT NULL
                )
           ) THEN
            RAISE EXCEPTION 'knowledge relation immutable binding or version changed' USING ERRCODE = '23514';
        END IF;
        IF OLD.status = 'DEPRECATED' THEN
            RAISE EXCEPTION 'deprecated knowledge relation is immutable' USING ERRCODE = '55000';
        END IF;
        IF NEW.status <> OLD.status AND NOT (
            (OLD.status = 'SUGGESTED' AND NEW.status IN ('CONFIRMED', 'REJECTED'))
            OR (OLD.status = 'CONFIRMED' AND NEW.status IN ('STALE', 'DEPRECATED'))
            OR (OLD.status = 'STALE' AND NEW.status IN ('CONFIRMED', 'REJECTED', 'DEPRECATED'))
            OR (OLD.status = 'REJECTED' AND NEW.status = 'SUGGESTED')
        ) THEN
            RAISE EXCEPTION 'knowledge relation transition is invalid' USING ERRCODE = '23514';
        END IF;
        IF OLD.status = 'REJECTED' AND NEW.status = 'SUGGESTED' THEN
            IF NEW.evidence_fingerprint IS NULL
               OR NEW.evidence_fingerprint IS NOT DISTINCT FROM OLD.evidence_fingerprint THEN
                RAISE EXCEPTION 'knowledge relation resuggestion requires new evidence' USING ERRCODE = '23514';
            END IF;
        ELSIF NEW.evidence_fingerprint IS DISTINCT FROM OLD.evidence_fingerprint
              AND NEW.status NOT IN ('SUGGESTED', 'CONFIRMED') THEN
            RAISE EXCEPTION 'knowledge relation evidence fingerprint changed outside resuggestion' USING ERRCODE = '23514';
        END IF;
    ELSIF NEW.status <> 'SUGGESTED' OR NEW.version <> 1 THEN
        RAISE EXCEPTION 'knowledge relation has an invalid initial state' USING ERRCODE = '23514';
    END IF;

    IF TG_OP = 'INSERT' OR NEW.status IN ('SUGGESTED', 'CONFIRMED') THEN
        PERFORM core.knowledge_validate_relation_endpoint(
            NEW.workspace_id, NEW.source_node_type, NEW.source_node_id
        );
        PERFORM core.knowledge_validate_relation_endpoint(
            NEW.workspace_id, NEW.target_node_type, NEW.target_node_id
        );
    ELSE
        PERFORM core.knowledge_validate_relation_endpoint_identity(
            NEW.workspace_id, NEW.source_node_type, NEW.source_node_id
        );
        PERFORM core.knowledge_validate_relation_endpoint_identity(
            NEW.workspace_id, NEW.target_node_type, NEW.target_node_id
        );
    END IF;

    compatible := CASE NEW.relation_type
        WHEN 'CITES' THEN NEW.source_node_type = 'CLAIM' AND NEW.target_node_type = 'CLAIM'
        WHEN 'DERIVED_FROM' THEN NEW.source_node_type = 'CLAIM' AND NEW.target_node_type = 'CLAIM'
        WHEN 'BELONGS_TO' THEN NEW.source_node_type = 'CLAIM' AND NEW.target_node_type = 'TOPIC'
        WHEN 'SUPPORTS' THEN NEW.source_node_type = 'CLAIM' AND NEW.target_node_type = 'CLAIM'
        WHEN 'CONFLICTS_WITH' THEN NEW.source_node_type = 'CLAIM' AND NEW.target_node_type = 'CLAIM'
        WHEN 'COMPLEMENTS' THEN NEW.source_node_type = NEW.target_node_type
        WHEN 'DUPLICATES' THEN NEW.source_node_type = NEW.target_node_type
        WHEN 'PREREQUISITE_OF' THEN NEW.source_node_type = NEW.target_node_type
        WHEN 'VERSION_OF' THEN NEW.source_node_type = NEW.target_node_type
        WHEN 'IMPACTS' THEN true
        ELSE false
    END;
    IF NOT compatible THEN
        RAISE EXCEPTION 'knowledge relation endpoint combination is invalid' USING ERRCODE = '23514';
    END IF;
    RETURN NEW;
END;
$$;


--
-- Name: knowledge_validate_topic_alias_insert(); Type: FUNCTION; Schema: core; Owner: -
--

CREATE FUNCTION core.knowledge_validate_topic_alias_insert() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    owner_status text;
BEGIN
    PERFORM id FROM core.workspace WHERE id = NEW.workspace_id FOR KEY SHARE;
    IF NOT FOUND THEN
        RAISE EXCEPTION 'knowledge topic alias workspace does not exist' USING ERRCODE = '23514';
    END IF;
    PERFORM pg_advisory_xact_lock(
        hashtextextended(NEW.workspace_id::text || E'\\x1f' || NEW.normalized_alias, 0)
    );
    SELECT status INTO owner_status
      FROM core.topic
     WHERE id = NEW.topic_id
       AND workspace_id = NEW.workspace_id
     FOR SHARE;
    IF owner_status IS DISTINCT FROM 'ACTIVE' THEN
        RAISE EXCEPTION 'knowledge topic alias owner is not active' USING ERRCODE = '23514';
    END IF;
    IF EXISTS (
        SELECT 1 FROM core.topic
         WHERE workspace_id = NEW.workspace_id
           AND normalized_name = NEW.normalized_alias
    ) THEN
        RAISE EXCEPTION 'knowledge topic alias collides with a topic name' USING ERRCODE = '23514';
    END IF;
    RETURN NEW;
END;
$$;


--
-- Name: knowledge_validate_topic_write(); Type: FUNCTION; Schema: core; Owner: -
--

CREATE FUNCTION core.knowledge_validate_topic_write() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    merged_target_status text;
BEGIN
    PERFORM id FROM core.workspace WHERE id = NEW.workspace_id FOR KEY SHARE;
    IF NOT FOUND THEN
        RAISE EXCEPTION 'knowledge topic workspace does not exist' USING ERRCODE = '23514';
    END IF;

    IF TG_OP = 'INSERT' THEN
        IF NEW.status <> 'ACTIVE' OR NEW.version <> 1 THEN
            RAISE EXCEPTION 'knowledge topic must start active at version one' USING ERRCODE = '23514';
        END IF;
        PERFORM pg_advisory_xact_lock(
            hashtextextended(NEW.workspace_id::text || E'\\x1f' || NEW.normalized_name, 0)
        );
        IF EXISTS (
            SELECT 1 FROM core.topic_alias
             WHERE workspace_id = NEW.workspace_id
               AND normalized_alias = NEW.normalized_name
        ) THEN
            RAISE EXCEPTION 'knowledge topic name collides with an alias' USING ERRCODE = '23514';
        END IF;
        RETURN NEW;
    END IF;

    IF NEW.id <> OLD.id
       OR NEW.workspace_id <> OLD.workspace_id
       OR NEW.name <> OLD.name
       OR NEW.normalized_name <> OLD.normalized_name
       OR NEW.created_at <> OLD.created_at
       OR NEW.version <> OLD.version + 1
       OR NEW.updated_at < OLD.updated_at THEN
        RAISE EXCEPTION 'knowledge topic immutable binding or version changed' USING ERRCODE = '23514';
    END IF;
    IF OLD.status IN ('MERGED', 'DEPRECATED') THEN
        RAISE EXCEPTION 'historical knowledge topic is immutable' USING ERRCODE = '55000';
    END IF;
    IF NEW.status <> OLD.status AND NOT (
        OLD.status = 'ACTIVE' AND NEW.status IN ('MERGED', 'DEPRECATED')
    ) THEN
        RAISE EXCEPTION 'knowledge topic transition is invalid' USING ERRCODE = '23514';
    END IF;
    IF NEW.status = 'MERGED' THEN
        SELECT status INTO merged_target_status
          FROM core.topic
         WHERE id = NEW.merged_into_topic_id
           AND workspace_id = NEW.workspace_id
         FOR SHARE;
        IF merged_target_status IS DISTINCT FROM 'ACTIVE' THEN
            RAISE EXCEPTION 'knowledge topic merge target is invalid' USING ERRCODE = '23514';
        END IF;
    END IF;
    RETURN NEW;
END;
$$;


--
-- Name: knowledge_verify_claim_confirmation(); Type: FUNCTION; Schema: core; Owner: -
--

CREATE FUNCTION core.knowledge_verify_claim_confirmation() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    owner_id uuid;
    owner_workspace_id uuid;
    owner_status text;
BEGIN
    IF TG_TABLE_NAME = 'claim' THEN
        owner_id := NEW.id;
        owner_workspace_id := NEW.workspace_id;
        owner_status := NEW.status;
    ELSE
        owner_id := NEW.claim_id;
        owner_workspace_id := NEW.workspace_id;
        SELECT status INTO owner_status
          FROM core.claim
         WHERE id = owner_id AND workspace_id = owner_workspace_id;
    END IF;

    IF owner_status = 'CONFIRMED' AND NOT EXISTS (
        SELECT 1 FROM core.claim_source
         WHERE claim_id = owner_id
           AND workspace_id = owner_workspace_id
           AND support_type = 'SUPPORTS'
    ) THEN
        RAISE EXCEPTION 'confirmed knowledge claim requires supporting provenance' USING ERRCODE = '55000';
    END IF;
    RETURN NEW;
END;
$$;


--
-- Name: knowledge_verify_claim_conflict_integrity(); Type: FUNCTION; Schema: core; Owner: -
--

CREATE FUNCTION core.knowledge_verify_claim_conflict_integrity() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF NEW.status <> 'DISPUTED' AND EXISTS (
        SELECT 1
          FROM core.conflict_member member
          JOIN core.conflict conflict
            ON conflict.id = member.conflict_id
           AND conflict.workspace_id = member.workspace_id
         WHERE member.claim_id = NEW.id
           AND member.workspace_id = NEW.workspace_id
           AND conflict.status NOT IN ('RESOLVED', 'ACCEPTED_DIVERGENCE')
    ) THEN
        RAISE EXCEPTION 'unresolved knowledge conflict requires disputed claims'
            USING ERRCODE = '55000';
    END IF;
    RETURN NEW;
END;
$$;


--
-- Name: knowledge_verify_claim_relation_integrity(); Type: FUNCTION; Schema: core; Owner: -
--

CREATE FUNCTION core.knowledge_verify_claim_relation_integrity() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF NEW.status NOT IN ('SUGGESTED', 'CONFIRMED', 'DISPUTED') AND EXISTS (
        SELECT 1
          FROM core.relation relation
         WHERE relation.workspace_id = NEW.workspace_id
           AND relation.status IN ('SUGGESTED', 'CONFIRMED')
           AND (
                (relation.source_node_type = 'CLAIM' AND relation.source_node_id = NEW.id)
                OR (relation.target_node_type = 'CLAIM' AND relation.target_node_id = NEW.id)
           )
    ) THEN
        RAISE EXCEPTION 'historical knowledge claim cannot retain an active relation'
            USING ERRCODE = '55000';
    END IF;
    RETURN NEW;
END;
$$;


--
-- Name: knowledge_verify_conflict_integrity(); Type: FUNCTION; Schema: core; Owner: -
--

CREATE FUNCTION core.knowledge_verify_conflict_integrity() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    owner_id uuid;
    owner_workspace_id uuid;
    owner_status text;
    owner_assessment text;
    owner_applicability_hash text;
    owner_resolution text;
    member_count bigint;
    distinct_hash_count bigint;
    exact_hash text;
BEGIN
    IF TG_TABLE_NAME = 'conflict' THEN
        owner_id := NEW.id;
        owner_workspace_id := NEW.workspace_id;
        owner_status := NEW.status;
        owner_assessment := NEW.applicability_assessment;
        owner_applicability_hash := NEW.applicability_hash;
        owner_resolution := NEW.resolution;
    ELSE
        owner_id := NEW.conflict_id;
        owner_workspace_id := NEW.workspace_id;
        SELECT status, applicability_assessment, applicability_hash, resolution
          INTO owner_status, owner_assessment, owner_applicability_hash, owner_resolution
          FROM core.conflict
         WHERE id = owner_id AND workspace_id = owner_workspace_id;
    END IF;

    SELECT count(*), count(DISTINCT applicability_hash), min(applicability_hash)
      INTO member_count, distinct_hash_count, exact_hash
      FROM core.conflict_member
     WHERE conflict_id = owner_id
       AND workspace_id = owner_workspace_id;

    IF member_count < 2 THEN
        RAISE EXCEPTION 'knowledge conflict requires at least two claims' USING ERRCODE = '55000';
    END IF;
    IF EXISTS (
        SELECT 1
          FROM core.conflict_member member
          JOIN core.claim claim
            ON claim.id = member.claim_id
           AND claim.workspace_id = member.workspace_id
         WHERE member.conflict_id = owner_id
           AND member.workspace_id = owner_workspace_id
           AND (
                member.applicability <> claim.applicability
                OR member.applicability_schema_version <> claim.applicability_schema_version
                OR member.applicability_hash <> claim.applicability_hash
           )
    ) THEN
        RAISE EXCEPTION 'knowledge conflict member snapshot drifted' USING ERRCODE = '55000';
    END IF;
    IF owner_assessment = 'EXACT' AND (
        distinct_hash_count <> 1 OR owner_applicability_hash IS DISTINCT FROM exact_hash
    ) THEN
        RAISE EXCEPTION 'knowledge exact conflict applicability is inconsistent' USING ERRCODE = '55000';
    END IF;
    IF owner_assessment = 'REVIEWED_OVERLAP' AND distinct_hash_count < 2 THEN
        RAISE EXCEPTION 'knowledge reviewed overlap requires different applicability hashes' USING ERRCODE = '55000';
    END IF;
    IF owner_status NOT IN ('RESOLVED', 'ACCEPTED_DIVERGENCE') AND EXISTS (
        SELECT 1
          FROM core.conflict_member member
          JOIN core.claim claim
            ON claim.id = member.claim_id
           AND claim.workspace_id = member.workspace_id
         WHERE member.conflict_id = owner_id
           AND member.workspace_id = owner_workspace_id
           AND claim.status <> 'DISPUTED'
    ) THEN
        RAISE EXCEPTION 'unresolved knowledge conflict requires disputed claims' USING ERRCODE = '55000';
    END IF;
    IF owner_status = 'ACCEPTED_DIVERGENCE' AND (
        distinct_hash_count < 2 OR owner_resolution IS NULL
    ) THEN
        RAISE EXCEPTION 'accepted divergence requires distinct applicability and resolution' USING ERRCODE = '55000';
    END IF;
    RETURN NEW;
END;
$$;


--
-- Name: knowledge_verify_relation_confirmation(); Type: FUNCTION; Schema: core; Owner: -
--

CREATE FUNCTION core.knowledge_verify_relation_confirmation() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    owner_id uuid;
    owner_workspace_id uuid;
    owner_status text;
    owner_confirmation_method text;
    owner_confirmation_ref text;
BEGIN
    IF TG_TABLE_NAME = 'relation' THEN
        owner_id := NEW.id;
        owner_workspace_id := NEW.workspace_id;
        owner_status := NEW.status;
        owner_confirmation_method := NEW.confirmation_method;
        owner_confirmation_ref := NEW.confirmation_ref;
    ELSE
        owner_id := NEW.relation_id;
        owner_workspace_id := NEW.workspace_id;
        SELECT status, confirmation_method, confirmation_ref
          INTO owner_status, owner_confirmation_method, owner_confirmation_ref
          FROM core.relation
         WHERE id = owner_id AND workspace_id = owner_workspace_id;
    END IF;

    IF owner_status = 'CONFIRMED' AND (
        owner_confirmation_method IS NULL
        OR owner_confirmation_ref IS NULL
        OR NOT EXISTS (
            SELECT 1 FROM core.relation_evidence
             WHERE relation_id = owner_id
               AND workspace_id = owner_workspace_id
               AND confirmation_method = owner_confirmation_method
               AND confirmed_by = owner_confirmation_ref
        )
    ) THEN
        RAISE EXCEPTION 'confirmed knowledge relation requires confirmed evidence' USING ERRCODE = '55000';
    END IF;
    RETURN NEW;
END;
$$;


--
-- Name: knowledge_verify_topic_relation_integrity(); Type: FUNCTION; Schema: core; Owner: -
--

CREATE FUNCTION core.knowledge_verify_topic_relation_integrity() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF NEW.status <> 'ACTIVE' AND EXISTS (
        SELECT 1
          FROM core.relation relation
         WHERE relation.workspace_id = NEW.workspace_id
           AND relation.status IN ('SUGGESTED', 'CONFIRMED')
           AND (
                (relation.source_node_type = 'TOPIC' AND relation.source_node_id = NEW.id)
                OR (relation.target_node_type = 'TOPIC' AND relation.target_node_id = NEW.id)
           )
    ) THEN
        RAISE EXCEPTION 'historical knowledge topic cannot retain an active relation'
            USING ERRCODE = '55000';
    END IF;
    RETURN NEW;
END;
$$;


--
-- Name: reject_content_artifact_mutation(); Type: FUNCTION; Schema: core; Owner: -
--

CREATE FUNCTION core.reject_content_artifact_mutation() RETURNS trigger
