--
-- Name: reject_source_version_mutation(); Type: FUNCTION; Schema: core; Owner: -
--

CREATE FUNCTION core.reject_source_version_mutation() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF TG_OP = 'UPDATE'
       AND OLD.content_artifact_id IS NULL
       AND NEW.content_artifact_id IS NOT NULL
       AND (to_jsonb(NEW) - 'content_artifact_id') = (to_jsonb(OLD) - 'content_artifact_id') THEN
        RETURN NEW;
    END IF;
    RAISE EXCEPTION 'source_version is immutable' USING ERRCODE = '55000';
END;
$$;


--
-- Name: validate_capture_write(); Type: FUNCTION; Schema: core; Owner: -
--

CREATE FUNCTION core.validate_capture_write() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF TG_OP='INSERT' THEN
        IF NEW.version<>1 THEN
            RAISE EXCEPTION 'capture must start at version one' USING ERRCODE='23514';
        END IF;
        RETURN NEW;
    END IF;
    IF TG_OP='DELETE'
       OR NEW.id<>OLD.id OR NEW.workspace_id<>OLD.workspace_id OR NEW.kind<>OLD.kind
       OR NEW.original_location<>OLD.original_location
       OR NEW.original_url IS DISTINCT FROM OLD.original_url
       OR NEW.original_input_hash IS DISTINCT FROM OLD.original_input_hash
       OR NEW.source_id<>OLD.source_id OR NEW.captured_at<>OLD.captured_at
       OR NEW.version<>OLD.version+1 OR NEW.updated_at<OLD.updated_at THEN
        RAISE EXCEPTION 'capture immutable field or version violation' USING ERRCODE='23514';
    END IF;
    RETURN NEW;
END;
$$;


--
-- Name: validate_workspace_git_capture_checkpoint_update(); Type: FUNCTION; Schema: core; Owner: -
--

CREATE FUNCTION core.validate_workspace_git_capture_checkpoint_update() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF NEW.workspace_id<>OLD.workspace_id OR NEW.created_at<>OLD.created_at OR NEW.version<>OLD.version+1 THEN
        RAISE EXCEPTION 'Git capture checkpoint immutable binding or version changed' USING ERRCODE='55000';
    END IF;
    IF OLD.inflight_run_id IS NULL THEN
        IF NEW.completed_head_oid<>OLD.completed_head_oid OR NEW.inflight_run_id IS NULL
           OR NEW.last_run_id IS DISTINCT FROM OLD.last_run_id
           OR NEW.last_before_oid IS DISTINCT FROM OLD.last_before_oid
           OR NEW.last_after_oid IS DISTINCT FROM OLD.last_after_oid
           OR NEW.last_request_hash IS DISTINCT FROM OLD.last_request_hash THEN
            RAISE EXCEPTION 'Git capture checkpoint begin transition is invalid' USING ERRCODE='55000';
        END IF;
    ELSE
        IF NEW.inflight_run_id IS NOT NULL OR NEW.completed_head_oid<>OLD.inflight_after_oid
           OR NEW.last_run_id<>OLD.inflight_run_id OR NEW.last_before_oid<>OLD.inflight_before_oid
           OR NEW.last_after_oid<>OLD.inflight_after_oid OR NEW.last_request_hash<>OLD.inflight_request_hash THEN
            RAISE EXCEPTION 'Git capture checkpoint completion transition is invalid' USING ERRCODE='55000';
        END IF;
    END IF;
    RETURN NEW;
END;
$$;


--
-- Name: verify_source_version_artifact_workspace(); Type: FUNCTION; Schema: core; Owner: -
--

CREATE FUNCTION core.verify_source_version_artifact_workspace() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    source_workspace uuid;
    artifact_workspace uuid;
BEGIN
    SELECT workspace_id INTO source_workspace FROM core.source WHERE id = NEW.source_id;
    SELECT workspace_id INTO artifact_workspace FROM core.content_artifact WHERE id = NEW.content_artifact_id;
    IF source_workspace IS NULL OR artifact_workspace IS NULL OR source_workspace <> artifact_workspace THEN
        RAISE EXCEPTION 'source version artifact workspace mismatch' USING ERRCODE = '23514';
    END IF;
    IF NOT EXISTS (
        SELECT 1
        FROM core.content_artifact
        WHERE id = NEW.content_artifact_id
          AND content_hash = NEW.content_hash
          AND byte_size = NEW.byte_size
    ) THEN
        RAISE EXCEPTION 'source version artifact content metadata mismatch' USING ERRCODE = '23514';
    END IF;
    RETURN NEW;
END;
$$;


