--
-- Name: validate_attempt_transition(); Type: FUNCTION; Schema: ingestion; Owner: -
--

CREATE FUNCTION ingestion.validate_attempt_transition() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF NEW.id <> OLD.id
       OR NEW.workspace_id <> OLD.workspace_id
       OR NEW.source_version_id <> OLD.source_version_id
       OR NEW.workflow_run_id IS DISTINCT FROM OLD.workflow_run_id
       OR NEW.parser_id <> OLD.parser_id
       OR NEW.parser_version <> OLD.parser_version
       OR NEW.parser_config_hash <> OLD.parser_config_hash
       OR NEW.chunk_strategy_version <> OLD.chunk_strategy_version
       OR NEW.schema_version <> OLD.schema_version
       OR NEW.idempotency_key <> OLD.idempotency_key
       OR NEW.attempt_number <> OLD.attempt_number
       OR NEW.started_at <> OLD.started_at
       OR (OLD.parse_projection_id IS NOT NULL AND NEW.parse_projection_id IS DISTINCT FROM OLD.parse_projection_id)
       OR NEW.version <> OLD.version + 1 THEN
        RAISE EXCEPTION 'attempt immutable fields or version changed' USING ERRCODE = '23514';
    END IF;
    IF OLD.status IN ('chunked','parse_failed','cancelled') OR (OLD.status = 'validating' AND OLD.security_status = 'quarantined') THEN
        RAISE EXCEPTION 'terminal attempt cannot transition' USING ERRCODE = '23514';
    END IF;
    IF NOT (
        (OLD.status = 'validating' AND OLD.security_status = 'pending' AND NEW.status = 'validating' AND NEW.security_status = 'quarantined')
        OR
        (OLD.status = 'validating' AND NEW.status IN ('parsing','parse_failed','cancelled'))
        OR (OLD.status = 'parsing' AND NEW.status IN ('parsed','parse_failed','cancelled'))
        OR (OLD.status = 'parsed' AND NEW.status IN ('chunking','parse_failed','cancelled'))
        OR (OLD.status = 'chunking' AND NEW.status IN ('chunked','parse_failed','cancelled'))
    ) THEN
        RAISE EXCEPTION 'invalid attempt state transition' USING ERRCODE = '23514';
    END IF;
    RETURN NEW;
END;
$$;


--
-- Name: verify_workspace_ownership(); Type: FUNCTION; Schema: ingestion; Owner: -
--

CREATE FUNCTION ingestion.verify_workspace_ownership() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    actual_workspace uuid;
    artifact_id uuid;
    artifact_size bigint;
    projection_parser_version text;
    projection_schema_version text;
    projection_parser_id text;
    projection_config_hash text;
    span_parser_version text;
    span_schema_version text;
BEGIN
    IF TG_TABLE_NAME = 'parse_projection' THEN
        SELECT workspace_id INTO actual_workspace FROM core.content_artifact WHERE id = NEW.content_artifact_id;
    ELSIF TG_TABLE_NAME = 'attempt' THEN
        SELECT s.workspace_id, sv.content_artifact_id
          INTO actual_workspace, artifact_id
          FROM core.source_version sv JOIN core.source s ON s.id = sv.source_id
         WHERE sv.id = NEW.source_version_id;
        IF NEW.workflow_run_id IS NOT NULL AND NOT EXISTS (
            SELECT 1 FROM workflow.run WHERE id = NEW.workflow_run_id AND workspace_id = NEW.workspace_id
        ) THEN
            RAISE EXCEPTION 'attempt workflow workspace mismatch' USING ERRCODE = '23514';
        END IF;
        IF NEW.parse_projection_id IS NOT NULL AND NOT EXISTS (
            SELECT 1 FROM ingestion.parse_projection
             WHERE id = NEW.parse_projection_id
               AND workspace_id = NEW.workspace_id
               AND content_artifact_id = artifact_id
        ) THEN
            RAISE EXCEPTION 'attempt projection source mismatch' USING ERRCODE = '23514';
        END IF;
        IF NEW.parse_projection_id IS NOT NULL THEN
            SELECT parser_id, parser_version, parser_config_hash, schema_version
              INTO projection_parser_id, projection_parser_version, projection_config_hash, projection_schema_version
              FROM ingestion.parse_projection WHERE id = NEW.parse_projection_id;
            IF NEW.parser_id <> projection_parser_id OR NEW.parser_version <> projection_parser_version
               OR NEW.parser_config_hash <> projection_config_hash OR NEW.schema_version <> projection_schema_version THEN
                RAISE EXCEPTION 'attempt parser contract mismatch' USING ERRCODE = '23514';
            END IF;
        END IF;
    ELSIF TG_TABLE_NAME = 'source_version_projection' THEN
        SELECT s.workspace_id, sv.content_artifact_id
          INTO actual_workspace, artifact_id
          FROM core.source_version sv JOIN core.source s ON s.id = sv.source_id
         WHERE sv.id = NEW.source_version_id;
        IF NOT EXISTS (
            SELECT 1 FROM ingestion.parse_projection
             WHERE id = NEW.parse_projection_id
               AND workspace_id = NEW.workspace_id
               AND content_artifact_id = artifact_id
        ) THEN
            RAISE EXCEPTION 'source version projection mismatch' USING ERRCODE = '23514';
        END IF;
    ELSIF TG_TABLE_NAME = 'source_span' THEN
        SELECT workspace_id, content_artifact_id, parser_version, schema_version
          INTO actual_workspace, artifact_id, projection_parser_version, projection_schema_version
          FROM ingestion.parse_projection WHERE id = NEW.parse_projection_id;
        IF artifact_id <> NEW.content_artifact_id THEN
            RAISE EXCEPTION 'span artifact projection mismatch' USING ERRCODE = '23514';
        END IF;
        SELECT byte_size INTO artifact_size FROM core.content_artifact WHERE id = NEW.content_artifact_id;
        IF artifact_size IS NULL OR NEW.end_byte > artifact_size THEN
            RAISE EXCEPTION 'span exceeds content artifact' USING ERRCODE = '23514';
        END IF;
        IF NEW.parser_version <> projection_parser_version OR NEW.schema_version <> projection_schema_version THEN
            RAISE EXCEPTION 'span parser/schema version mismatch' USING ERRCODE = '23514';
        END IF;
    ELSIF TG_TABLE_NAME = 'canonical_chunk' THEN
        SELECT workspace_id, parser_version, schema_version
          INTO actual_workspace, projection_parser_version, projection_schema_version
          FROM ingestion.parse_projection WHERE id = NEW.parse_projection_id;
        IF NOT EXISTS (
            SELECT 1 FROM ingestion.source_span
             WHERE id = NEW.source_span_id
               AND workspace_id = NEW.workspace_id
               AND parse_projection_id = NEW.parse_projection_id
        ) THEN
            RAISE EXCEPTION 'chunk span projection mismatch' USING ERRCODE = '23514';
        END IF;
        SELECT parser_version, schema_version INTO span_parser_version, span_schema_version
          FROM ingestion.source_span WHERE id = NEW.source_span_id;
        IF NEW.parser_version <> projection_parser_version OR NEW.schema_version <> projection_schema_version
           OR NEW.parser_version <> span_parser_version OR NEW.schema_version <> span_schema_version THEN
            RAISE EXCEPTION 'chunk parser/schema version mismatch' USING ERRCODE = '23514';
        END IF;
    END IF;
    IF actual_workspace IS NULL OR actual_workspace <> NEW.workspace_id THEN
        RAISE EXCEPTION 'ingestion workspace mismatch' USING ERRCODE = '23514';
    END IF;
    RETURN NEW;
END;
$$;


--
-- Name: assert_interview_artifact_binding(); Type: FUNCTION; Schema: learning; Owner: -
--

CREATE FUNCTION learning.assert_interview_artifact_binding() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
 expected_type text; actual_type text; artifact_schema_version text; revision_schema_version text;
 current_revision_id uuid; current_artifact_version bigint; interview_id uuid; sections jsonb;
 preparation learning.note_interview_preparation;
BEGIN
 expected_type:=CASE TG_TABLE_NAME WHEN 'interview_report' THEN 'INTERVIEW_DOC' WHEN 'learning_path' THEN 'LEARNING_PATH' ELSE NULL END;
 SELECT artifact.artifact_type,artifact.domain_schema_version,artifact.current_revision_id,artifact.version,revision.domain_schema_version,revision.sections
  INTO actual_type,artifact_schema_version,current_revision_id,current_artifact_version,revision_schema_version,sections
  FROM learning.artifact artifact JOIN learning.artifact_revision revision
   ON revision.id=NEW.artifact_revision_id AND revision.workspace_id=NEW.workspace_id AND revision.artifact_id=NEW.artifact_id
  WHERE artifact.id=NEW.artifact_id AND artifact.workspace_id=NEW.workspace_id;
 IF actual_type IS DISTINCT FROM expected_type OR artifact_schema_version IS DISTINCT FROM 'artifact/v1'
  OR current_revision_id IS DISTINCT FROM NEW.artifact_revision_id OR current_artifact_version IS DISTINCT FROM NEW.artifact_version THEN
  RAISE EXCEPTION 'learning path artifact binding is invalid' USING ERRCODE='23514';
 END IF;
 IF TG_TABLE_NAME='interview_report' THEN
  interview_id:=NEW.session_id;
 ELSIF TG_TABLE_NAME='learning_path' AND NEW.origin_type='INTERVIEW' THEN
  interview_id:=NEW.interview_session_id;
 END IF;
 SELECT * INTO preparation FROM learning.note_interview_preparation
  WHERE workspace_id=NEW.workspace_id AND session_id=interview_id AND status='READY';
 IF preparation.id IS NULL THEN
  IF revision_schema_version IS DISTINCT FROM 'artifact-revision/v1' THEN
   RAISE EXCEPTION 'Claim and Review artifacts require their original revision schema' USING ERRCODE='23514';
  END IF;
 ELSE
  IF revision_schema_version IS DISTINCT FROM 'artifact-revision/v2'
   OR (SELECT count(*) FROM learning.artifact_revision_document_source source WHERE source.workspace_id=NEW.workspace_id AND source.revision_id=NEW.artifact_revision_id AND source.artifact_id=NEW.artifact_id)<>1
   OR NOT EXISTS (SELECT 1 FROM learning.artifact_revision_document_source source
    WHERE source.workspace_id=NEW.workspace_id AND source.revision_id=NEW.artifact_revision_id AND source.artifact_id=NEW.artifact_id
     AND source.document_id=preparation.document_id AND source.article_revision_id=preparation.article_revision_id
     AND source.revision_no=(preparation.snapshot->>'article_revision_no')::bigint AND source.content_hash=preparation.snapshot->>'content_hash')
   OR EXISTS (SELECT 1 FROM jsonb_array_elements(sections) section WHERE COALESCE(section->'Citations','null'::jsonb) NOT IN ('[]'::jsonb,'null'::jsonb)) THEN
   RAISE EXCEPTION 'note interview artifact differs from its frozen document source' USING ERRCODE='23514';
  END IF;
 END IF;
 RETURN NEW;
END $$;


--
-- Name: assert_interview_path_step_evidence(); Type: FUNCTION; Schema: learning; Owner: -
--

CREATE FUNCTION learning.assert_interview_path_step_evidence() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF NOT EXISTS (
        SELECT 1
          FROM core.claim AS claim
          JOIN core.claim_source AS source
            ON source.workspace_id = claim.workspace_id
           AND source.claim_id = claim.id
         WHERE claim.workspace_id = NEW.workspace_id
           AND claim.id = NEW.claim_id
           AND claim.status = 'CONFIRMED'
           AND source.source_version_id = NEW.source_version_id
           AND source.source_span_id = NEW.source_span_id
           AND source.evidence_hash = NEW.evidence_hash
           AND source.support_type = 'SUPPORTS'
    ) THEN
        RAISE EXCEPTION 'learning path step evidence is not a confirmed claim support'
            USING ERRCODE = '23514';
    END IF;
    RETURN NEW;
END;
$$;


--
-- Name: assert_interview_question_evidence(); Type: FUNCTION; Schema: learning; Owner: -
--

CREATE FUNCTION learning.assert_interview_question_evidence() RETURNS trigger
    LANGUAGE plpgsql
    AS $_$
DECLARE
    parent_claim_id uuid;
    parent_evidence jsonb;
BEGIN
    IF jsonb_typeof(NEW.evidence) IS DISTINCT FROM 'array'
       OR jsonb_array_length(NEW.evidence) = 0
       OR jsonb_array_length(NEW.evidence) > 64 THEN
        RAISE EXCEPTION 'interview question evidence must be a non-empty bounded array'
            USING ERRCODE = '23514';
    END IF;

    IF NEW.follow_up_no > 0 THEN
        SELECT question.claim_id, question.evidence
          INTO parent_claim_id, parent_evidence
          FROM learning.interview_question AS question
         WHERE question.id = NEW.parent_question_id
           AND question.workspace_id = NEW.workspace_id
           AND question.session_id = NEW.session_id;
        IF NOT FOUND
           OR parent_claim_id IS DISTINCT FROM NEW.claim_id
           OR parent_evidence IS DISTINCT FROM NEW.evidence THEN
            RAISE EXCEPTION 'interview follow-up must retain parent evidence'
                USING ERRCODE = '23514';
        END IF;
    END IF;

    IF EXISTS (
        SELECT 1
          FROM jsonb_array_elements(NEW.evidence) AS evidence(item)
         WHERE jsonb_typeof(evidence.item) IS DISTINCT FROM 'object'
            OR CASE
                WHEN jsonb_typeof(evidence.item) = 'object' THEN
                    (SELECT count(*) FROM jsonb_object_keys(evidence.item)) <> 8
                ELSE true
               END
            OR NOT evidence.item ?& ARRAY[
                'schema_version', 'claim_id', 'index_version_id', 'chunk_id',
                'source_version_id', 'source_span_id', 'evidence_hash', 'support_type'
            ]
            OR jsonb_typeof(evidence.item -> 'schema_version') IS DISTINCT FROM 'string'
            OR jsonb_typeof(evidence.item -> 'claim_id') IS DISTINCT FROM 'string'
            OR jsonb_typeof(evidence.item -> 'index_version_id') IS DISTINCT FROM 'string'
            OR jsonb_typeof(evidence.item -> 'chunk_id') IS DISTINCT FROM 'string'
            OR jsonb_typeof(evidence.item -> 'source_version_id') IS DISTINCT FROM 'string'
            OR jsonb_typeof(evidence.item -> 'source_span_id') IS DISTINCT FROM 'string'
            OR jsonb_typeof(evidence.item -> 'evidence_hash') IS DISTINCT FROM 'string'
            OR jsonb_typeof(evidence.item -> 'support_type') IS DISTINCT FROM 'string'
            OR evidence.item ->> 'schema_version' IS DISTINCT FROM 'interview-evidence/v2'
            OR learning.try_interview_evidence_uuid(evidence.item ->> 'claim_id') IS DISTINCT FROM NEW.claim_id
            OR learning.try_interview_evidence_uuid(evidence.item ->> 'index_version_id') IS NULL
            OR learning.try_interview_evidence_uuid(evidence.item ->> 'chunk_id') IS NULL
            OR learning.try_interview_evidence_uuid(evidence.item ->> 'source_version_id') IS NULL
            OR learning.try_interview_evidence_uuid(evidence.item ->> 'source_span_id') IS NULL
            OR evidence.item ->> 'evidence_hash' !~ '^[0-9a-f]{64}$'
            OR evidence.item ->> 'support_type' IS DISTINCT FROM 'SUPPORTS'
            OR NOT EXISTS (
                SELECT 1
                  FROM core.claim_source AS claim_source
                  JOIN retrieval.index_version AS index_version
                    ON index_version.id = learning.try_interview_evidence_uuid(evidence.item ->> 'index_version_id')
                   AND index_version.workspace_id = claim_source.workspace_id
                  JOIN retrieval.index_manifest_source AS manifest_source
                    ON manifest_source.index_version_id = index_version.id
                   AND manifest_source.workspace_id = index_version.workspace_id
                   AND manifest_source.source_version_id = claim_source.source_version_id
                   AND manifest_source.selection_status = 'included'
                  JOIN ingestion.canonical_chunk AS chunk
                    ON chunk.id = learning.try_interview_evidence_uuid(evidence.item ->> 'chunk_id')
                   AND chunk.workspace_id = claim_source.workspace_id
                   AND chunk.parse_projection_id = manifest_source.parse_projection_id
                   AND chunk.source_span_id = claim_source.source_span_id
                  JOIN retrieval.index_manifest_chunk AS manifest_chunk
                    ON manifest_chunk.index_version_id = index_version.id
                   AND manifest_chunk.workspace_id = index_version.workspace_id
                   AND manifest_chunk.chunk_id = chunk.id
                   AND manifest_chunk.content_hash = chunk.content_hash
                 WHERE claim_source.workspace_id = NEW.workspace_id
                   AND claim_source.claim_id = NEW.claim_id
                   AND claim_source.source_version_id = learning.try_interview_evidence_uuid(evidence.item ->> 'source_version_id')
                   AND claim_source.source_span_id = learning.try_interview_evidence_uuid(evidence.item ->> 'source_span_id')
                   AND claim_source.evidence_hash = evidence.item ->> 'evidence_hash'
                   AND claim_source.support_type = 'SUPPORTS'
                   AND core.knowledge_validate_provenance_binding(
                       NEW.workspace_id,
                       claim_source.source_version_id,
                       claim_source.source_span_id
                   )
                   AND (
                       NEW.follow_up_no > 0
                       OR (
                           index_version.status = 'active'
                           AND EXISTS (
                               SELECT 1
                                 FROM core.claim AS claim
                                WHERE claim.id = NEW.claim_id
                                  AND claim.workspace_id = NEW.workspace_id
                                  AND claim.status = 'CONFIRMED'
                           )
                           AND EXISTS (
                               SELECT 1
                                 FROM core.source_version AS source_version
                                WHERE source_version.id = claim_source.source_version_id
                                  AND source_version.workspace_id = NEW.workspace_id
                                  AND source_version.security_status <> 'quarantined'
                           )
                           AND COALESCE((
                               SELECT attempt.security_status
                                 FROM ingestion.attempt AS attempt
                                WHERE attempt.workspace_id = NEW.workspace_id
                                  AND attempt.source_version_id = claim_source.source_version_id
                                ORDER BY attempt.started_at DESC, attempt.id DESC
                                LIMIT 1
                           ), 'passed') <> 'quarantined'
                           AND NOT EXISTS (
                               SELECT 1
                                 FROM core.conflict_member AS conflict_member
                                 JOIN core.conflict AS conflict
                                   ON conflict.id = conflict_member.conflict_id
                                  AND conflict.workspace_id = conflict_member.workspace_id
                                WHERE conflict_member.workspace_id = NEW.workspace_id
                                  AND conflict_member.claim_id = NEW.claim_id
                                  AND conflict.severity IN ('CRITICAL', 'HIGH')
                                  AND conflict.status NOT IN ('RESOLVED', 'ACCEPTED_DIVERGENCE')
                           )
                       )
                   )
            )
    ) THEN
        RAISE EXCEPTION 'interview question evidence binding is invalid'
            USING ERRCODE = '23514';
    END IF;
    RETURN NEW;
END
$_$;


--
-- Name: assert_interview_session_shell(); Type: FUNCTION; Schema: learning; Owner: -
--

CREATE FUNCTION learning.assert_interview_session_shell() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    shell_type text;
    shell_config jsonb;
BEGIN
    SELECT session_type, config
      INTO shell_type, shell_config
      FROM learning.review_session
     WHERE id = NEW.session_id
       AND workspace_id = NEW.workspace_id;

    IF shell_type IS DISTINCT FROM 'INTERVIEW'
       OR shell_config ->> 'schema_version' IS DISTINCT FROM 'interview/v1' THEN
        RAISE EXCEPTION 'interview session must bind an interview review shell'
            USING ERRCODE = '23514';
    END IF;
    RETURN NEW;
END;
$$;


--
-- Name: assert_review_card_schedule(); Type: FUNCTION; Schema: learning; Owner: -
--

CREATE FUNCTION learning.assert_review_card_schedule() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF NEW.status = 'APPROVED' AND NOT EXISTS (
        SELECT 1 FROM learning.review_schedule
        WHERE workspace_id = NEW.workspace_id AND card_id = NEW.id
    ) THEN
        RAISE EXCEPTION 'approved review card requires one schedule' USING ERRCODE = '23514';
    END IF;
    IF NEW.status <> 'APPROVED' AND EXISTS (
        SELECT 1 FROM learning.review_schedule
        WHERE workspace_id = NEW.workspace_id AND card_id = NEW.id
    ) THEN
        RAISE EXCEPTION 'inactive review card cannot retain a schedule' USING ERRCODE = '23514';
    END IF;
    RETURN NULL;
END
$$;


--
-- Name: assert_review_schedule_card_status(); Type: FUNCTION; Schema: learning; Owner: -
--

CREATE FUNCTION learning.assert_review_schedule_card_status() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    target_workspace uuid;
    target_card uuid;
    card_status text;
BEGIN
    IF TG_OP = 'DELETE' THEN
        target_workspace := OLD.workspace_id;
        target_card := OLD.card_id;
    ELSE
        target_workspace := NEW.workspace_id;
        target_card := NEW.card_id;
    END IF;
    SELECT status INTO card_status
    FROM learning.review_card
    WHERE workspace_id = target_workspace AND id = target_card;

    IF card_status = 'APPROVED' AND NOT EXISTS (
        SELECT 1 FROM learning.review_schedule
        WHERE workspace_id = target_workspace AND card_id = target_card
    ) THEN
        RAISE EXCEPTION 'approved review card requires one schedule' USING ERRCODE = '23514';
    END IF;
    IF card_status IS NOT NULL AND card_status <> 'APPROVED' AND EXISTS (
        SELECT 1 FROM learning.review_schedule
        WHERE workspace_id = target_workspace AND card_id = target_card
    ) THEN
        RAISE EXCEPTION 'inactive review card cannot retain a schedule' USING ERRCODE = '23514';
    END IF;
    RETURN NULL;
END
$$;


--
-- Name: enforce_interview_question_history(); Type: FUNCTION; Schema: learning; Owner: -
--

CREATE FUNCTION learning.enforce_interview_question_history() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF TG_OP = 'DELETE' THEN
        RAISE EXCEPTION 'interview question is retained history' USING ERRCODE = '55000';
    END IF;

    IF ROW(
        NEW.id,
        NEW.workspace_id,
        NEW.session_id,
        NEW.question_no,
        NEW.follow_up_no,
        NEW.parent_question_id,
        NEW.claim_id,
        NEW.topic_id,
        NEW.prompt,
        NEW.answer_points,
        NEW.evidence,
        NEW.fingerprint,
        NEW.created_at
    ) IS DISTINCT FROM ROW(
        OLD.id,
        OLD.workspace_id,
        OLD.session_id,
        OLD.question_no,
        OLD.follow_up_no,
        OLD.parent_question_id,
        OLD.claim_id,
        OLD.topic_id,
        OLD.prompt,
        OLD.answer_points,
        OLD.evidence,
        OLD.fingerprint,
        OLD.created_at
    ) THEN
        RAISE EXCEPTION 'interview question facts are immutable' USING ERRCODE = '55000';
    END IF;

    IF OLD.status <> 'PENDING' OR OLD.answered_at IS NOT NULL THEN
        RAISE EXCEPTION 'terminal interview question is immutable' USING ERRCODE = '55000';
    END IF;

    IF NEW.status = 'ANSWERED'
       AND NEW.answered_at IS NOT NULL
       AND NEW.answered_at >= OLD.created_at THEN
        RETURN NEW;
    END IF;
    IF NEW.status = 'SKIPPED' AND NEW.answered_at IS NULL THEN
        RETURN NEW;
    END IF;

    RAISE EXCEPTION 'interview question transition is invalid' USING ERRCODE = '55000';
END;
$$;


--
-- Name: enforce_learning_path_history(); Type: FUNCTION; Schema: learning; Owner: -
--

CREATE FUNCTION learning.enforce_learning_path_history() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF TG_OP = 'DELETE' THEN
        RAISE EXCEPTION 'learning path is retained history' USING ERRCODE = '55000';
    END IF;

    IF ROW(
        NEW.id, NEW.workspace_id, NEW.interview_session_id,
        NEW.interview_report_id, NEW.review_answer_id, NEW.origin_type,
        NEW.source_policy_version, NEW.artifact_id, NEW.artifact_revision_id,
        NEW.artifact_version, NEW.created_at
    ) IS DISTINCT FROM ROW(
        OLD.id, OLD.workspace_id, OLD.interview_session_id,
        OLD.interview_report_id, OLD.review_answer_id, OLD.origin_type,
        OLD.source_policy_version, OLD.artifact_id, OLD.artifact_revision_id,
        OLD.artifact_version, OLD.created_at
    ) THEN
        RAISE EXCEPTION 'learning path facts are immutable' USING ERRCODE = '55000';
    END IF;

    IF NEW.version <> OLD.version + 1
       OR NEW.updated_at < OLD.updated_at THEN
        RAISE EXCEPTION 'learning path version progression is invalid' USING ERRCODE = '23514';
    END IF;

    -- A step transition also advances the aggregate version while the path
    -- remains ACTIVE. The established command contract also permits an
    -- explicit same-status, new-version receipt. Keep those legal optimistic-
    -- lock progressions, but do not permit a terminal path to be reopened or
    -- a paused path to complete without first being resumed.
    IF NEW.status = OLD.status
       OR (OLD.status = 'ACTIVE' AND NEW.status IN ('PAUSED', 'COMPLETED'))
       OR (OLD.status = 'PAUSED' AND NEW.status = 'ACTIVE') THEN
        RETURN NEW;
    END IF;

    RAISE EXCEPTION 'learning path status transition is invalid' USING ERRCODE = '23514';
END;
$$;


--
-- Name: enforce_learning_path_step_history(); Type: FUNCTION; Schema: learning; Owner: -
--

CREATE FUNCTION learning.enforce_learning_path_step_history() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF TG_OP = 'DELETE' THEN
        RAISE EXCEPTION 'learning path step is retained history' USING ERRCODE = '55000';
    END IF;

    IF ROW(
        NEW.id, NEW.workspace_id, NEW.path_id, NEW.step_no, NEW.claim_id,
        NEW.topic_id, NEW.source_version_id, NEW.source_span_id,
        NEW.evidence_hash, NEW.title, NEW.rationale, NEW.created_at
    ) IS DISTINCT FROM ROW(
        OLD.id, OLD.workspace_id, OLD.path_id, OLD.step_no, OLD.claim_id,
        OLD.topic_id, OLD.source_version_id, OLD.source_span_id,
        OLD.evidence_hash, OLD.title, OLD.rationale, OLD.created_at
    ) THEN
        RAISE EXCEPTION 'learning path step facts are immutable' USING ERRCODE = '55000';
    END IF;

    IF NEW.version <> OLD.version + 1
       OR NEW.updated_at < OLD.updated_at THEN
        RAISE EXCEPTION 'learning path step version progression is invalid' USING ERRCODE = '23514';
    END IF;

    IF NEW.status = OLD.status
       OR (OLD.status = 'PENDING' AND NEW.status IN ('IN_PROGRESS', 'COMPLETED', 'SKIPPED'))
       OR (OLD.status = 'IN_PROGRESS' AND NEW.status IN ('COMPLETED', 'SKIPPED')) THEN
        RETURN NEW;
    END IF;

    RAISE EXCEPTION 'learning path step status transition is invalid' USING ERRCODE = '23514';
END;
$$;


--
-- Name: enforce_memory_lifecycle(); Type: FUNCTION; Schema: learning; Owner: -
--

CREATE FUNCTION learning.enforce_memory_lifecycle() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF TG_OP = 'INSERT' THEN
        IF NEW.status <> 'CANDIDATE' THEN
            RAISE EXCEPTION 'memory must be created as a candidate' USING ERRCODE = '23514';
        END IF;
        IF NEW.confirmed_at IS NOT NULL OR NEW.confirmed_by_principal_kind IS NOT NULL OR NEW.confirmed_by_principal_id IS NOT NULL THEN
            RAISE EXCEPTION 'candidate memory cannot be confirmed on insert' USING ERRCODE = '23514';
        END IF;
        IF NEW.version <> 1 THEN
            RAISE EXCEPTION 'new memory must start at version one' USING ERRCODE = '23514';
        END IF;
        RETURN NEW;
    END IF;

    IF OLD.status = 'DELETED' THEN
        RAISE EXCEPTION 'deleted memory is a tombstone' USING ERRCODE = '55000';
    END IF;
    IF NEW.id <> OLD.id OR NEW.workspace_id <> OLD.workspace_id
       OR NEW.owner_principal_kind <> OLD.owner_principal_kind OR NEW.owner_principal_id <> OLD.owner_principal_id
       OR NEW.memory_type <> OLD.memory_type
       OR NEW.source_type <> OLD.source_type OR NEW.source_ref <> OLD.source_ref THEN
        RAISE EXCEPTION 'memory identity, owner, type, and source provenance are immutable' USING ERRCODE = '23514';
    END IF;
    IF NEW.version <> OLD.version + 1 OR NEW.updated_at < OLD.updated_at THEN
        RAISE EXCEPTION 'memory update must advance version and timestamp' USING ERRCODE = '23514';
    END IF;

    IF OLD.status <> 'CANDIDATE'
       AND (NEW.confirmed_at, NEW.confirmed_by_principal_kind, NEW.confirmed_by_principal_id)
           IS DISTINCT FROM (OLD.confirmed_at, OLD.confirmed_by_principal_kind, OLD.confirmed_by_principal_id) THEN
        RAISE EXCEPTION 'memory confirmation is immutable after confirmation' USING ERRCODE = '23514';
    END IF;

    IF NEW.status = OLD.status THEN
        IF OLD.status = 'CANDIDATE'
           AND (NEW.confirmed_at, NEW.confirmed_by_principal_kind, NEW.confirmed_by_principal_id)
               IS DISTINCT FROM (OLD.confirmed_at, OLD.confirmed_by_principal_kind, OLD.confirmed_by_principal_id) THEN
            RAISE EXCEPTION 'candidate confirmation requires active transition' USING ERRCODE = '23514';
        END IF;
        RETURN NEW;
    END IF;

    CASE OLD.status
        WHEN 'CANDIDATE' THEN
            IF NEW.status = 'ACTIVE'
               AND NEW.confirmed_at IS NOT NULL
               AND NEW.confirmed_by_principal_kind = 'USER'
               AND NEW.confirmed_by_principal_id IS NOT NULL THEN
                RETURN NEW;
            END IF;
            IF NEW.status IN ('EXPIRED', 'DELETED')
               AND NEW.confirmed_at IS NULL
               AND NEW.confirmed_by_principal_kind IS NULL
               AND NEW.confirmed_by_principal_id IS NULL THEN
                RETURN NEW;
            END IF;
        WHEN 'ACTIVE' THEN
            IF NEW.status IN ('PAUSED', 'EXPIRED', 'DELETED') THEN
                RETURN NEW;
            END IF;
        WHEN 'PAUSED' THEN
            IF NEW.status IN ('ACTIVE', 'EXPIRED', 'DELETED') THEN
                RETURN NEW;
            END IF;
        WHEN 'EXPIRED' THEN
            IF NEW.status = 'DELETED' THEN
                RETURN NEW;
            END IF;
    END CASE;

    RAISE EXCEPTION 'illegal memory lifecycle transition from % to %', OLD.status, NEW.status USING ERRCODE = '23514';
END;
$$;


--
-- Name: guard_artifact_citation_selector_backfill(); Type: FUNCTION; Schema: learning; Owner: -
--

CREATE FUNCTION learning.guard_artifact_citation_selector_backfill() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF TG_OP = 'DELETE' OR OLD.status = 'COMPLETED' THEN
        RAISE EXCEPTION 'artifact citation selector backfill marker is irreversible'
            USING ERRCODE = '55000';
    END IF;
    IF NEW.workspace_id <> OLD.workspace_id
       OR NEW.contract_version <> OLD.contract_version
       OR NEW.high_water_created_at IS DISTINCT FROM OLD.high_water_created_at
       OR NEW.high_water_revision_id IS DISTINCT FROM OLD.high_water_revision_id
       OR NEW.expected_revision_count <> OLD.expected_revision_count
       OR NEW.expected_selector_count < OLD.expected_selector_count
       OR NEW.processed_revision_count < OLD.processed_revision_count
       OR NEW.processed_selector_count < OLD.processed_selector_count
       OR NEW.validated_revision_count < OLD.validated_revision_count
       OR NEW.validated_selector_count < OLD.validated_selector_count
       OR NEW.version <> OLD.version + 1
       OR NEW.updated_at < OLD.updated_at
       OR NOT (
           (OLD.status='PENDING' AND NEW.status IN ('RUNNING','FAILED'))
           OR (OLD.status='RUNNING' AND NEW.status IN ('RUNNING','FAILED','COMPLETED'))
           OR (OLD.status='FAILED' AND NEW.status='RUNNING')
       ) THEN
        RAISE EXCEPTION 'artifact citation selector backfill transition is invalid'
            USING ERRCODE = '55000';
    END IF;
    RETURN NEW;
END;
$$;


--
-- Name: guard_artifact_external_transition_reservation_mutation(); Type: FUNCTION; Schema: learning; Owner: -
--

CREATE FUNCTION learning.guard_artifact_external_transition_reservation_mutation() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF TG_OP = 'UPDATE' THEN
        RAISE EXCEPTION 'artifact external transition reservation is immutable' USING ERRCODE = '55000';
    END IF;
    IF TG_OP = 'DELETE' AND NOT EXISTS (
        SELECT 1
          FROM learning.artifact_command c
          JOIN learning.artifact a ON a.id = OLD.artifact_id AND a.workspace_id = OLD.workspace_id
         WHERE c.workspace_id = OLD.workspace_id
           AND c.idempotency_key = OLD.idempotency_key
           AND c.request_hash = OLD.request_hash
           AND c.command_type = OLD.command_type
           AND c.artifact_id = OLD.artifact_id
           AND c.artifact_version = OLD.expected_version + 1
           AND a.version = OLD.expected_version + 1
           AND (
                (OLD.command_type = 'EXPORT_MARKDOWN' AND a.status = 'EXPORTED' AND EXISTS (
                    SELECT 1 FROM learning.artifact_export e
                     WHERE e.workspace_id = OLD.workspace_id AND e.artifact_id = OLD.artifact_id
                       AND e.revision_id = OLD.current_revision_id AND e.artifact_version = OLD.expected_version + 1
                )) OR
                (OLD.command_type = 'PUBLISH' AND a.status = 'PUBLISH_PROPOSED' AND EXISTS (
                    SELECT 1 FROM learning.artifact_publication p
                     WHERE p.workspace_id = OLD.workspace_id AND p.artifact_id = OLD.artifact_id
                       AND p.revision_id = OLD.current_revision_id AND p.artifact_version = OLD.expected_version + 1
                ))
           )
    ) THEN
        RAISE EXCEPTION 'artifact external transition reservation cannot be deleted before its terminal receipt and side fact' USING ERRCODE = '55000';
    END IF;
    RETURN OLD;
END;
$$;


--
-- Name: guard_artifact_section_generation_mutation(); Type: FUNCTION; Schema: learning; Owner: -
--

CREATE FUNCTION learning.guard_artifact_section_generation_mutation() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    actual_revision_no integer;
BEGIN
    IF TG_OP = 'DELETE' THEN
        RAISE EXCEPTION 'artifact section generation is append-only'
            USING ERRCODE = '55000';
    END IF;

    IF TG_OP = 'INSERT' THEN
        IF NEW.status <> 'PENDING' OR NEW.version <> 1 THEN
            RAISE EXCEPTION 'artifact section generation must start pending at version one'
                USING ERRCODE = '23514';
        END IF;
        SELECT revision_no
          INTO actual_revision_no
          FROM learning.artifact_revision
         WHERE id = NEW.source_revision_id
           AND workspace_id = NEW.workspace_id
           AND artifact_id = NEW.artifact_id;
        IF actual_revision_no IS NULL OR actual_revision_no <> NEW.source_revision_no THEN
            RAISE EXCEPTION 'artifact section generation source revision binding is invalid'
                USING ERRCODE = '23514';
        END IF;
        RETURN NEW;
    END IF;

    IF OLD.status <> 'PENDING'
       OR OLD.version <> 1
       OR NEW.status NOT IN ('COMPLETED', 'FAILED', 'CANCELLED', 'RECOVERY_REQUIRED')
       OR NEW.id IS DISTINCT FROM OLD.id
       OR NEW.workspace_id IS DISTINCT FROM OLD.workspace_id
       OR NEW.artifact_id IS DISTINCT FROM OLD.artifact_id
       OR NEW.source_revision_id IS DISTINCT FROM OLD.source_revision_id
       OR NEW.source_revision_no IS DISTINCT FROM OLD.source_revision_no
       OR NEW.source_artifact_version IS DISTINCT FROM OLD.source_artifact_version
       OR NEW.section_key IS DISTINCT FROM OLD.section_key
       OR NEW.idempotency_key IS DISTINCT FROM OLD.idempotency_key
       OR NEW.request_hash IS DISTINCT FROM OLD.request_hash
       OR NEW.workflow_run_id IS DISTINCT FROM OLD.workflow_run_id
       OR NEW.node_run_id IS DISTINCT FROM OLD.node_run_id
       OR NEW.created_at IS DISTINCT FROM OLD.created_at
       OR NEW.version <> 2
       OR NEW.updated_at < OLD.updated_at THEN
        RAISE EXCEPTION 'artifact section generation transition is invalid'
            USING ERRCODE = '55000';
    END IF;
    RETURN NEW;
END;
$$;


--
-- Name: guard_interview_artifact_visibility_hold(); Type: FUNCTION; Schema: learning; Owner: -
--

CREATE FUNCTION learning.guard_interview_artifact_visibility_hold() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    reservation_status text;
    reservation_digest text;
    held_artifact_type text;
    plan_binding_exists boolean;
BEGIN
    -- Existing Interview writers still submit owner_id.  Project that legacy
    -- identity into the structured FK column before the row-level shape check;
    -- a caller that supplies both must supply the same identifier.
    IF NEW.owner_type = 'INTERVIEW_COMPLETE' THEN
        IF NEW.interview_session_id IS NULL THEN
            NEW.interview_session_id := NEW.owner_id;
        ELSIF NEW.interview_session_id IS DISTINCT FROM NEW.owner_id THEN
            RAISE EXCEPTION 'interview artifact hold owner identifiers disagree'
                USING ERRCODE = '23514';
        END IF;
    ELSIF NEW.owner_type = 'LEARNING_PATH_CREATE' THEN
        IF NEW.review_answer_id IS NULL THEN
            NEW.review_answer_id := NEW.owner_id;
        ELSIF NEW.review_answer_id IS DISTINCT FROM NEW.owner_id THEN
            RAISE EXCEPTION 'review path hold owner identifiers disagree'
                USING ERRCODE = '23514';
        END IF;
    END IF;

    IF NEW.disposition <> 'ACTIVE' THEN
        RETURN NEW;
    END IF;

    IF NEW.owner_type = 'INTERVIEW_COMPLETE' THEN
        PERFORM 1
          FROM learning.interview_session AS session
         WHERE session.workspace_id = NEW.workspace_id
           AND session.session_id = NEW.interview_session_id
         FOR UPDATE;

        IF NOT FOUND THEN
            RAISE EXCEPTION 'active interview artifact hold must bind an existing interview session'
                USING ERRCODE = '23514';
        END IF;

        SELECT reservation.status,
               reservation.artifact_digest,
               artifact.artifact_type,
               EXISTS (
                   SELECT 1
                     FROM learning.artifact_command AS command
                    WHERE command.workspace_id = NEW.workspace_id
                      AND command.artifact_id = NEW.artifact_id
                      AND command.command_type = 'PLAN'
                      AND command.idempotency_key =
                          'iv1:' || NEW.interview_session_id::text || ':' || artifact.artifact_type || ':' ||
                          reservation.artifact_digest || ':p'
               )
          INTO reservation_status, reservation_digest, held_artifact_type, plan_binding_exists
          FROM learning.interview_completion_reservation AS reservation
          JOIN learning.artifact AS artifact
            ON artifact.workspace_id = NEW.workspace_id
           AND artifact.id = NEW.artifact_id
         WHERE reservation.workspace_id = NEW.workspace_id
           AND reservation.session_id = NEW.interview_session_id
         FOR UPDATE OF reservation;

        IF NOT FOUND
           OR reservation_status IS DISTINCT FROM 'PENDING'
           OR reservation_digest IS NULL
           OR (NEW.attempt_digest IS NOT NULL AND NEW.attempt_digest IS DISTINCT FROM reservation_digest)
           OR plan_binding_exists IS DISTINCT FROM true
           OR NOT (
               (NEW.owner_role = 'REPORT' AND held_artifact_type = 'INTERVIEW_DOC')
               OR (NEW.owner_role = 'PATH' AND held_artifact_type = 'LEARNING_PATH')
           ) THEN
            RAISE EXCEPTION 'active interview artifact hold must bind the pending completion digest'
                USING ERRCODE = '23514';
        END IF;

        NEW.attempt_digest := reservation_digest;
        RETURN NEW;
    END IF;

    IF NEW.owner_type = 'LEARNING_PATH_CREATE' THEN
        PERFORM 1
          FROM learning.review_answer AS answer
         WHERE answer.workspace_id = NEW.workspace_id
           AND answer.id = NEW.review_answer_id
         FOR UPDATE;

        IF NOT FOUND THEN
            RAISE EXCEPTION 'active review path hold must bind an existing review answer'
                USING ERRCODE = '23514';
        END IF;

        SELECT reservation.status,
               reservation.artifact_digest,
               artifact.artifact_type,
               EXISTS (
                   SELECT 1
                     FROM learning.artifact_command AS command
                    WHERE command.workspace_id = NEW.workspace_id
                      AND command.artifact_id = NEW.artifact_id
                      AND command.command_type = 'PLAN'
                      AND command.idempotency_key =
                          'lp1:review:' || NEW.review_answer_id::text || ':LEARNING_PATH:' ||
                          reservation.artifact_digest || ':p'
               )
          INTO reservation_status, reservation_digest, held_artifact_type, plan_binding_exists
          FROM learning.learning_path_creation_reservation AS reservation
          JOIN learning.artifact AS artifact
            ON artifact.workspace_id = NEW.workspace_id
           AND artifact.id = NEW.artifact_id
         WHERE reservation.workspace_id = NEW.workspace_id
           AND reservation.review_answer_id = NEW.review_answer_id
         FOR UPDATE OF reservation;

        IF NOT FOUND
           OR reservation_status IS DISTINCT FROM 'PENDING'
           OR reservation_digest IS NULL
           OR (NEW.attempt_digest IS NOT NULL AND NEW.attempt_digest IS DISTINCT FROM reservation_digest)
           OR held_artifact_type IS DISTINCT FROM 'LEARNING_PATH'
           OR NEW.owner_role IS DISTINCT FROM 'PATH'
           OR plan_binding_exists IS DISTINCT FROM true THEN
            RAISE EXCEPTION 'active review path hold must bind the pending creation digest'
                USING ERRCODE = '23514';
        END IF;

        NEW.attempt_digest := reservation_digest;
        RETURN NEW;
    END IF;

    RAISE EXCEPTION 'active artifact hold owner type is unsupported'
        USING ERRCODE = '23514';
END;
$$;


--
-- Name: guard_interview_session_shell_binding(); Type: FUNCTION; Schema: learning; Owner: -
--

CREATE FUNCTION learning.guard_interview_session_shell_binding() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    shell_type text;
    shell_deck_id uuid;
    shell_config jsonb;
BEGIN
    SELECT session_type, deck_id, config
      INTO shell_type, shell_deck_id, shell_config
      FROM learning.review_session
     WHERE id = NEW.session_id
       AND workspace_id = NEW.workspace_id
     FOR UPDATE;

    IF NOT FOUND
       OR shell_type IS DISTINCT FROM 'INTERVIEW'
       OR shell_deck_id IS NOT NULL
       OR shell_config ->> 'schema_version' IS DISTINCT FROM 'interview/v1' THEN
        RAISE EXCEPTION 'interview session must bind a deckless interview shell'
            USING ERRCODE = '23514';
    END IF;
    RETURN NEW;
END
$$;


--
-- Name: guard_memory_audit_aggregate(); Type: FUNCTION; Schema: learning; Owner: -
--

CREATE FUNCTION learning.guard_memory_audit_aggregate() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    aggregate_owner_kind text;
    aggregate_owner_id uuid;
    aggregate_status text;
    aggregate_version bigint;
BEGIN
    SELECT owner_principal_kind, owner_principal_id, status, version
      INTO aggregate_owner_kind, aggregate_owner_id, aggregate_status, aggregate_version
      FROM learning.memory
     WHERE id = NEW.memory_id
       AND workspace_id = NEW.workspace_id
     FOR KEY SHARE;

    IF NOT FOUND
       OR NEW.owner_principal_kind IS DISTINCT FROM aggregate_owner_kind
       OR NEW.owner_principal_id IS DISTINCT FROM aggregate_owner_id
       OR NEW.memory_version IS DISTINCT FROM aggregate_version
       OR NEW.to_status IS DISTINCT FROM aggregate_status THEN
        RAISE EXCEPTION 'memory audit does not match the aggregate version'
            USING ERRCODE = '23514';
    END IF;

    IF NEW.action = 'CANDIDATE_CREATED'
       AND NEW.memory_version = 1
       AND NEW.from_status IS NULL
       AND NEW.to_status = 'CANDIDATE' THEN
        RETURN NEW;
    ELSIF NEW.action = 'CONFIRMED'
       AND NEW.from_status = 'CANDIDATE'
       AND NEW.to_status = 'ACTIVE' THEN
        RETURN NEW;
    ELSIF NEW.action = 'UPDATED'
       AND NEW.from_status = NEW.to_status
       AND NEW.to_status IN ('CANDIDATE', 'ACTIVE', 'PAUSED') THEN
        RETURN NEW;
    ELSIF NEW.action = 'PAUSED'
       AND NEW.from_status = 'ACTIVE'
       AND NEW.to_status = 'PAUSED' THEN
        RETURN NEW;
    ELSIF NEW.action = 'RESUMED'
       AND NEW.from_status = 'PAUSED'
       AND NEW.to_status = 'ACTIVE' THEN
        RETURN NEW;
    ELSIF NEW.action = 'EXPIRED'
       AND NEW.from_status IN ('CANDIDATE', 'ACTIVE', 'PAUSED')
       AND NEW.to_status = 'EXPIRED' THEN
        RETURN NEW;
    ELSIF NEW.action = 'DELETED'
       AND NEW.from_status IN ('CANDIDATE', 'ACTIVE', 'PAUSED', 'EXPIRED')
       AND NEW.to_status = 'DELETED' THEN
        RETURN NEW;
    END IF;

    RAISE EXCEPTION 'memory audit action does not match its lifecycle transition'
        USING ERRCODE = '23514';
END
$$;


--
-- Name: guard_memory_interview_provenance(); Type: FUNCTION; Schema: learning; Owner: -
--

CREATE FUNCTION learning.guard_memory_interview_provenance() RETURNS trigger
    LANGUAGE plpgsql
    AS $_$
DECLARE
    parsed_session_id uuid;
    parsed_path_id uuid;
    parsed_step_id uuid;
    step_title text;
    step_rationale text;
BEGIN
    IF TG_OP = 'UPDATE' THEN
        IF ROW(
            NEW.interview_session_id,
            NEW.interview_path_id,
            NEW.interview_step_id
        ) IS DISTINCT FROM ROW(
            OLD.interview_session_id,
            OLD.interview_path_id,
            OLD.interview_step_id
        ) THEN
            RAISE EXCEPTION 'memory interview provenance is immutable'
                USING ERRCODE = '23514';
        END IF;

        IF NEW.source_type = 'INTERVIEW'
           AND NEW.source_ref IS DISTINCT FROM format(
               'interview:%s:learning-path:%s:step:%s',
               NEW.interview_session_id,
               NEW.interview_path_id,
               NEW.interview_step_id
           ) THEN
            RAISE EXCEPTION 'memory interview source_ref is not canonical'
                USING ERRCODE = '23514';
        END IF;
        RETURN NEW;
    END IF;

    IF NEW.source_type <> 'INTERVIEW' THEN
        IF NEW.interview_session_id IS NOT NULL
           OR NEW.interview_path_id IS NOT NULL
           OR NEW.interview_step_id IS NOT NULL THEN
            RAISE EXCEPTION 'non-interview memory cannot carry interview provenance'
                USING ERRCODE = '23514';
        END IF;
        RETURN NEW;
    END IF;

    IF NEW.source_ref !~ '^interview:[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}:learning-path:[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}:step:[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$' THEN
        RAISE EXCEPTION 'memory interview source_ref is not canonical'
            USING ERRCODE = '23514';
    END IF;

    parsed_session_id := split_part(NEW.source_ref, ':', 2)::uuid;
    parsed_path_id := split_part(NEW.source_ref, ':', 4)::uuid;
    parsed_step_id := split_part(NEW.source_ref, ':', 6)::uuid;

    IF (NEW.interview_session_id IS NOT NULL AND NEW.interview_session_id IS DISTINCT FROM parsed_session_id)
       OR (NEW.interview_path_id IS NOT NULL AND NEW.interview_path_id IS DISTINCT FROM parsed_path_id)
       OR (NEW.interview_step_id IS NOT NULL AND NEW.interview_step_id IS DISTINCT FROM parsed_step_id) THEN
        RAISE EXCEPTION 'memory interview columns disagree with source_ref'
            USING ERRCODE = '23514';
    END IF;

    SELECT step.title, step.rationale
      INTO step_title, step_rationale
      FROM learning.learning_path AS path
      JOIN learning.learning_path_step AS step
        ON step.id = parsed_step_id
       AND step.workspace_id = path.workspace_id
       AND step.path_id = path.id
     WHERE path.id = parsed_path_id
       AND path.workspace_id = NEW.workspace_id
       AND path.origin_type = 'INTERVIEW'
       AND path.interview_session_id = parsed_session_id
     FOR KEY SHARE OF path, step;

    IF NOT FOUND
       OR NEW.owner_principal_kind IS DISTINCT FROM 'USER'
       OR NEW.owner_principal_id IS DISTINCT FROM '00000000-0000-5000-8000-000000000001'::uuid
       OR NEW.memory_type IS DISTINCT FROM 'GOAL'
       OR NEW.task_scope_id IS DISTINCT FROM parsed_session_id
       OR NEW.expires_at IS NOT NULL
       OR NEW.content IS DISTINCT FROM jsonb_build_object(
           'goal', step_title,
           'rationale', step_rationale
       ) THEN
        RAISE EXCEPTION 'interview memory candidate does not match its path step'
            USING ERRCODE = '23514';
    END IF;

    NEW.interview_session_id := parsed_session_id;
    NEW.interview_path_id := parsed_path_id;
    NEW.interview_step_id := parsed_step_id;
    RETURN NEW;
END;
$_$;


--
-- Name: guard_note_interview_preparation(); Type: FUNCTION; Schema: learning; Owner: -
--

CREATE FUNCTION learning.guard_note_interview_preparation() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE expected jsonb; run_status text;
BEGIN
 IF TG_OP='DELETE' THEN RAISE EXCEPTION 'note interview preparation is retained history' USING ERRCODE='55000'; END IF;
 IF TG_OP='INSERT' THEN
  IF NEW.status<>'QUEUED' OR NEW.version<>1 THEN RAISE EXCEPTION 'note interview preparation must start queued' USING ERRCODE='23514'; END IF;
  SELECT jsonb_build_object('workspace_id',r.workspace_id,'note_id',r.note_id,'revision_id',r.id,'revision_no',r.revision_no,
   'document_id',r.document_id,'article_revision_id',r.article_revision_id,'article_revision_no',r.article_revision_no,
   'content_hash',r.content_hash,'projection_hash',r.projection_hash,'title',r.title,'renderer_version',r.renderer_version,'items',r.items)
   INTO expected FROM organizing.synthesis_revision r WHERE r.id=NEW.revision_id AND r.workspace_id=NEW.workspace_id;
  IF expected IS NULL OR NEW.snapshot IS DISTINCT FROM expected THEN RAISE EXCEPTION 'note interview snapshot differs from immutable revision' USING ERRCODE='23514'; END IF;
  IF NEW.retry_of IS NULL THEN
   IF NOT EXISTS (
    SELECT 1 FROM core.document d JOIN core.article_revision ar ON ar.id=d.current_published_revision_id AND ar.workspace_id=d.workspace_id AND ar.document_id=d.id
    JOIN authoring.generated_article_revision gr ON gr.article_revision_id=ar.id AND gr.workspace_id=ar.workspace_id AND gr.document_id=ar.document_id AND gr.content_hash=ar.content_hash
    JOIN authoring.document_publication_binding b ON b.article_revision_id=ar.id AND b.workspace_id=ar.workspace_id AND b.document_id=d.id AND b.status='PUBLISHED'
    JOIN change_control.proposal_commit pc ON pc.proposal_id=b.proposal_id AND pc.revision_id=b.proposal_revision_id AND pc.workspace_id=b.workspace_id
      AND pc.target_path=b.target_path AND pc.target_mode=b.target_mode AND pc.result_hash=b.content_hash AND pc.git_commit=b.git_commit
    WHERE d.id=NEW.document_id AND d.workspace_id=NEW.workspace_id AND ar.id=NEW.article_revision_id AND ar.status='PUBLISHED' AND ar.created_by_type='AGENT'
     AND ar.content_hash=NEW.snapshot->>'content_hash' AND ar.content_hash=b.content_hash AND ar.git_commit=b.git_commit AND d.canonical_path=b.target_path AND d.lifecycle_status='PUBLISHED'
   ) THEN RAISE EXCEPTION 'note interview requires an actually published generated revision' USING ERRCODE='23514'; END IF;
  ELSIF NOT EXISTS (SELECT 1 FROM learning.note_interview_preparation p WHERE p.id=NEW.retry_of AND p.workspace_id=NEW.workspace_id
   AND p.status IN ('FAILED','CAPABILITY_UNAVAILABLE') AND p.failure_retryable AND p.snapshot=NEW.snapshot AND p.options=NEW.options) THEN
   RAISE EXCEPTION 'note interview retry changed original material or is not allowed' USING ERRCODE='23514';
  END IF;
  IF NOT (NEW.options ?& ARRAY['role','difficulty','duration_minutes','question_count','max_follow_ups']) OR (SELECT count(*) FROM jsonb_object_keys(NEW.options))<>5
   OR jsonb_typeof(NEW.options->'role')<>'string' OR btrim(NEW.options->>'role')='' OR octet_length(NEW.options->>'role')>256
   OR NEW.options->>'difficulty' NOT IN ('FOUNDATION','INTERMEDIATE','ADVANCED')
   OR (NEW.options->>'duration_minutes')::integer NOT BETWEEN 1 AND 240 OR (NEW.options->>'question_count')::integer NOT BETWEEN 1 AND 20
   OR (NEW.options->>'max_follow_ups')::integer NOT BETWEEN 0 AND 20 THEN RAISE EXCEPTION 'note interview options are invalid' USING ERRCODE='23514'; END IF;
 ELSE
  IF OLD.status NOT IN ('QUEUED','GENERATING') OR NEW.version<>OLD.version+1 OR NEW.updated_at<OLD.updated_at
   OR ROW(NEW.id,NEW.workspace_id,NEW.note_id,NEW.revision_id,NEW.document_id,NEW.article_revision_id,NEW.projection_hash,NEW.snapshot,NEW.options,NEW.workflow_run_id,NEW.node_run_id,NEW.idempotency_key,NEW.request_hash,NEW.retry_of,NEW.created_at)
    IS DISTINCT FROM ROW(OLD.id,OLD.workspace_id,OLD.note_id,OLD.revision_id,OLD.document_id,OLD.article_revision_id,OLD.projection_hash,OLD.snapshot,OLD.options,OLD.workflow_run_id,OLD.node_run_id,OLD.idempotency_key,OLD.request_hash,OLD.retry_of,OLD.created_at)
   OR (OLD.node_attempt_id IS NOT NULL AND ROW(NEW.node_attempt_id,NEW.model_settings_revision) IS DISTINCT FROM ROW(OLD.node_attempt_id,OLD.model_settings_revision))
   OR (OLD.model_run_id IS NOT NULL AND NEW.model_run_id IS DISTINCT FROM OLD.model_run_id)
   OR (OLD.status='GENERATING' AND NEW.status='QUEUED') OR (OLD.status='QUEUED' AND NEW.status NOT IN ('GENERATING','FAILED','CAPABILITY_UNAVAILABLE','RECOVERY_REQUIRED')) THEN
   RAISE EXCEPTION 'note interview preparation transition or frozen binding is invalid' USING ERRCODE='55000';
  END IF;
 END IF;
 IF NEW.model_run_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM agent.model_run m WHERE m.id=NEW.model_run_id AND m.workspace_id=NEW.workspace_id
  AND m.workflow_run_id=NEW.workflow_run_id AND m.node_run_id=NEW.node_run_id AND m.node_attempt_id=NEW.node_attempt_id
  AND m.model_settings_revision IS NOT DISTINCT FROM NEW.model_settings_revision AND m.output_schema_id='agent.synthesis-note-interview-plan'
  AND m.output_schema_version='1' AND m.prompt_template_id='interview.synthesis-note-plan' AND m.prompt_template_version='1'
  AND m.reduced_schema_id=m.output_schema_id AND m.reduced_schema_version=m.output_schema_version AND m.retrieval_index_version_id IS NULL) THEN
  RAISE EXCEPTION 'note interview model binding is invalid' USING ERRCODE='23514';
 END IF;
 IF NEW.status='READY' AND NOT EXISTS (SELECT 1 FROM agent.model_run m JOIN LATERAL (SELECT response_hash,response_bytes,status FROM agent.model_call c WHERE c.model_run_id=m.id ORDER BY call_no DESC LIMIT 1) last_call ON true
  WHERE m.id=NEW.model_run_id AND m.status='SUCCEEDED' AND m.final_result_type='synthesis_note_interview_plan' AND last_call.status='SUCCEEDED'
  AND last_call.response_hash=encode(sha256(NEW.model_output),'hex') AND last_call.response_bytes=octet_length(NEW.model_output)) THEN
  RAISE EXCEPTION 'ready note interview has no accepted model response proof' USING ERRCODE='23514';
 END IF;
 RETURN NEW;
END $$;


--
-- Name: guard_note_interview_question(); Type: FUNCTION; Schema: learning; Owner: -
--

CREATE FUNCTION learning.guard_note_interview_question() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE p learning.note_interview_preparation; item jsonb; item_no integer; plan jsonb; points jsonb; expected_plan jsonb; ref jsonb; parent learning.interview_question;
BEGIN
 IF TG_OP='UPDATE' AND ROW(NEW.source_kind,NEW.note_source,NEW.follow_up_plan) IS DISTINCT FROM ROW(OLD.source_kind,OLD.note_source,OLD.follow_up_plan) THEN
  RAISE EXCEPTION 'interview question source and model plan are immutable' USING ERRCODE='55000';
 END IF;
 IF NEW.source_kind<>'NOTE_REVISION' THEN
  IF EXISTS (SELECT 1 FROM learning.review_session s WHERE s.id=NEW.session_id AND s.workspace_id=NEW.workspace_id AND s.config->'scope' ? 'note_revision') THEN RAISE EXCEPTION 'note interview cannot contain Claim questions' USING ERRCODE='23514'; END IF;
  RETURN NEW;
 END IF;
 SELECT * INTO p FROM learning.note_interview_preparation WHERE session_id=NEW.session_id AND workspace_id=NEW.workspace_id AND status='READY';
 IF p.id IS NULL THEN RAISE EXCEPTION 'note question has no ready preparation' USING ERRCODE='23514'; END IF;
 ref:=p.snapshot-'items'-'renderer_version';
 IF NOT EXISTS(SELECT 1 FROM learning.review_session s WHERE s.id=NEW.session_id AND s.workspace_id=NEW.workspace_id AND s.config->'scope'=jsonb_build_object('note_revision',ref)
  AND s.config-'scope'-'schema_version'=p.options) THEN RAISE EXCEPTION 'note question scope differs from preparation' USING ERRCODE='23514'; END IF;
 SELECT value,ordinality::integer INTO item,item_no FROM jsonb_array_elements(p.snapshot->'items') WITH ORDINALITY WHERE value->>'id'=NEW.note_source->>'item_id';
 IF item IS NULL OR NEW.note_source IS DISTINCT FROM jsonb_build_object('revision',ref,'item_id',item->'id','item_kind',item->'kind','sources',learning.note_interview_item_sources(item)) THEN
  RAISE EXCEPTION 'note question source differs from frozen material' USING ERRCODE='23514'; END IF;
 points:=learning.note_interview_item_points(item);
 plan:=convert_from(p.model_output,'UTF8')::jsonb->'questions'->(NEW.question_no-1);
 SELECT COALESCE(jsonb_agg(jsonb_build_object('condition',f->'condition','prompt',f->'prompt','answer_points',points) ORDER BY n),'[]'::jsonb) INTO expected_plan
  FROM jsonb_array_elements(plan->'follow_ups') WITH ORDINALITY q(f,n);
 IF plan IS NULL OR plan->>'item_label' IS DISTINCT FROM 'I'||lpad(item_no::text,3,'0') OR NEW.answer_points IS DISTINCT FROM points OR NEW.follow_up_plan IS DISTINCT FROM expected_plan THEN
  RAISE EXCEPTION 'note question differs from accepted model plan' USING ERRCODE='23514'; END IF;
 IF NEW.follow_up_no=0 THEN
  IF NEW.prompt IS DISTINCT FROM plan->>'prompt' THEN RAISE EXCEPTION 'note question prompt differs from model response' USING ERRCODE='23514'; END IF;
 ELSE
  SELECT * INTO parent FROM learning.interview_question WHERE id=NEW.parent_question_id AND workspace_id=NEW.workspace_id AND session_id=NEW.session_id;
  IF parent.id IS NULL OR parent.source_kind<>'NOTE_REVISION' OR parent.note_source IS DISTINCT FROM NEW.note_source OR parent.question_no<>NEW.question_no OR parent.follow_up_no+1<>NEW.follow_up_no
   OR NEW.prompt IS DISTINCT FROM (plan->'follow_ups'->(NEW.follow_up_no-1)->>'prompt') THEN RAISE EXCEPTION 'note follow-up does not extend its frozen question chain' USING ERRCODE='23514'; END IF;
 END IF;
 RETURN NEW;
END $$;


--
-- Name: guard_note_interview_report(); Type: FUNCTION; Schema: learning; Owner: -
--

CREATE FUNCTION learning.guard_note_interview_report() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE expected jsonb; finding jsonb; group_key text;
BEGIN
 SELECT jsonb_agg(note_source ORDER BY first_question) INTO expected FROM (
  SELECT note_source,min(question_no) first_question FROM learning.interview_question
  WHERE workspace_id=NEW.workspace_id AND session_id=NEW.session_id AND source_kind='NOTE_REVISION' AND follow_up_no=0 GROUP BY note_source
 ) source_items;
 IF expected IS NULL THEN
  IF NEW.report ? 'note_sources' THEN RAISE EXCEPTION 'Claim report cannot carry note sources' USING ERRCODE='23514'; END IF;
  RETURN NEW;
 END IF;
 IF NEW.report->'note_sources' IS DISTINCT FROM expected OR NEW.report->'evidence' IS DISTINCT FROM '[]'::jsonb THEN
  RAISE EXCEPTION 'note report sources differ from its frozen questions' USING ERRCODE='23514'; END IF;
 FOREACH group_key IN ARRAY ARRAY['strengths','gaps','expression'] LOOP
  FOR finding IN SELECT value FROM jsonb_array_elements(CASE WHEN jsonb_typeof(NEW.report->group_key)='array' THEN NEW.report->group_key ELSE '[]'::jsonb END) LOOP
   IF finding->>'source_kind' IS DISTINCT FROM 'NOTE_REVISION' OR finding->>'claim_id' IS DISTINCT FROM '' OR finding->'evidence' IS DISTINCT FROM '[]'::jsonb
    OR NOT EXISTS(SELECT 1 FROM jsonb_array_elements(expected) source WHERE source=finding->'note_source') THEN
    RAISE EXCEPTION 'note report finding changed its original source' USING ERRCODE='23514'; END IF;
  END LOOP;
 END LOOP;
 RETURN NEW;
END $$;


--
-- Name: guard_note_interview_step(); Type: FUNCTION; Schema: learning; Owner: -
--

CREATE FUNCTION learning.guard_note_interview_step() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
 IF TG_OP='UPDATE' AND ROW(NEW.source_kind,NEW.note_source) IS DISTINCT FROM ROW(OLD.source_kind,OLD.note_source) THEN RAISE EXCEPTION 'learning step source is immutable' USING ERRCODE='55000'; END IF;
 IF NEW.source_kind='NOTE_REVISION' AND NOT EXISTS (SELECT 1 FROM learning.learning_path p JOIN learning.interview_question q ON q.workspace_id=p.workspace_id AND q.session_id=p.interview_session_id
  WHERE p.id=NEW.path_id AND p.workspace_id=NEW.workspace_id AND p.origin_type='INTERVIEW' AND q.source_kind='NOTE_REVISION' AND q.note_source=NEW.note_source) THEN
  RAISE EXCEPTION 'note learning step has no exact interview source' USING ERRCODE='23514'; END IF;
 RETURN NEW;
END $$;


--
-- Name: guard_note_interview_turn(); Type: FUNCTION; Schema: learning; Owner: -
--

CREATE FUNCTION learning.guard_note_interview_turn() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE q learning.interview_question;
BEGIN
 SELECT * INTO q FROM learning.interview_question WHERE id=NEW.question_id AND session_id=NEW.session_id AND workspace_id=NEW.workspace_id;
 IF q.source_kind='NOTE_REVISION' THEN
  IF NEW.score->'note_source' IS DISTINCT FROM q.note_source OR NEW.score->'evidence' IS DISTINCT FROM '[]'::jsonb THEN RAISE EXCEPTION 'note turn source differs from question' USING ERRCODE='23514'; END IF;
 ELSIF NEW.score ? 'note_source' THEN RAISE EXCEPTION 'Claim turn cannot carry a note source' USING ERRCODE='23514'; END IF;
 RETURN NEW;
END $$;


--
-- Name: guard_review_answer_session_binding(); Type: FUNCTION; Schema: learning; Owner: -
--

CREATE FUNCTION learning.guard_review_answer_session_binding() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    shell_type text;
    shell_deck_id uuid;
BEGIN
    SELECT session_type, deck_id
      INTO shell_type, shell_deck_id
      FROM learning.review_session
     WHERE id = NEW.session_id
       AND workspace_id = NEW.workspace_id
     FOR UPDATE;

    IF NOT FOUND
       OR shell_type IS DISTINCT FROM 'REVIEW'
       OR shell_deck_id IS NULL
       OR NEW.card_id IS NULL
       OR NOT EXISTS (
           SELECT 1
             FROM learning.review_card AS card
            WHERE card.id = NEW.card_id
              AND card.workspace_id = NEW.workspace_id
              AND card.deck_id = shell_deck_id
       ) THEN
        RAISE EXCEPTION 'review answer must bind a card in a deck-bound review session'
            USING ERRCODE = '23514';
    END IF;
    RETURN NEW;
END
$$;


--
-- Name: guard_review_session_learning_binding(); Type: FUNCTION; Schema: learning; Owner: -
--

CREATE FUNCTION learning.guard_review_session_learning_binding() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF EXISTS (
        SELECT 1
          FROM learning.interview_session AS interview
         WHERE interview.session_id = OLD.id
           AND interview.workspace_id = OLD.workspace_id
    ) AND (
        NEW.session_type IS DISTINCT FROM 'INTERVIEW'
        OR NEW.deck_id IS NOT NULL
        OR NEW.config IS DISTINCT FROM OLD.config
        OR NEW.started_at IS DISTINCT FROM OLD.started_at
    ) THEN
        RAISE EXCEPTION 'interview review shell binding is immutable'
            USING ERRCODE = '23514';
    END IF;

    IF EXISTS (
        SELECT 1
          FROM learning.review_answer AS answer
         WHERE answer.session_id = OLD.id
           AND answer.workspace_id = OLD.workspace_id
    ) AND (
        NEW.session_type IS DISTINCT FROM 'REVIEW'
        OR NEW.deck_id IS NULL
    ) THEN
        RAISE EXCEPTION 'answered review session must remain deck-bound review'
            USING ERRCODE = '23514';
    END IF;
    RETURN NEW;
END
$$;


--
-- Name: initialize_artifact_citation_selector_backfill(); Type: FUNCTION; Schema: learning; Owner: -
--

CREATE FUNCTION learning.initialize_artifact_citation_selector_backfill() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    INSERT INTO learning.artifact_citation_selector_backfill(
        workspace_id,expected_revision_count,processed_revision_count,
        expected_selector_count,processed_selector_count,
        validated_revision_count,validated_selector_count,
        status,version,created_at,updated_at,completed_at
    ) VALUES(
        NEW.id,0,0,0,0,0,0,'COMPLETED',1,
        CURRENT_TIMESTAMP,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP
    )
    ON CONFLICT (workspace_id) DO NOTHING;
    RETURN NEW;
END;
$$;


--
-- Name: invalidate_review_cards_for_claim_lifecycle(); Type: FUNCTION; Schema: learning; Owner: -
--

CREATE FUNCTION learning.invalidate_review_cards_for_claim_lifecycle() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    PERFORM 1 FROM core.workspace WHERE id = NEW.workspace_id FOR UPDATE;

    IF NEW.status <> 'CONFIRMED'
       AND NEW.status IS DISTINCT FROM OLD.status THEN
        UPDATE learning.review_card
        SET status = 'INVALIDATED',
            invalidation_reason = 'CLAIM_' || NEW.status,
            invalidated_at = NEW.updated_at,
            version = version + 1,
            updated_at = NEW.updated_at
        WHERE workspace_id = NEW.workspace_id
          AND claim_id = NEW.id
          AND status = 'APPROVED';
    END IF;
    RETURN NEW;
END
$$;


--
-- Name: invalidate_review_cards_for_high_conflict(); Type: FUNCTION; Schema: learning; Owner: -
--

CREATE FUNCTION learning.invalidate_review_cards_for_high_conflict() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    PERFORM 1 FROM core.workspace WHERE id = NEW.workspace_id FOR UPDATE;

    IF NEW.severity IN ('CRITICAL', 'HIGH')
       AND NEW.status NOT IN ('RESOLVED', 'ACCEPTED_DIVERGENCE') THEN
        UPDATE learning.review_card AS card
        SET status = 'INVALIDATED',
            invalidation_reason = 'HIGH_SEVERITY_CONFLICT:' || NEW.id::text,
            invalidated_at = NEW.updated_at,
            version = card.version + 1,
            updated_at = NEW.updated_at
        WHERE card.workspace_id = NEW.workspace_id
          AND card.status = 'APPROVED'
          AND EXISTS (
              SELECT 1
              FROM core.conflict_member member
              WHERE member.workspace_id = NEW.workspace_id
                AND member.conflict_id = NEW.id
                AND member.claim_id = card.claim_id
          );
    END IF;
    RETURN NEW;
END
$$;


--
-- Name: invalidate_review_cards_for_high_conflict_member(); Type: FUNCTION; Schema: learning; Owner: -
--

CREATE FUNCTION learning.invalidate_review_cards_for_high_conflict_member() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    conflict_status text;
    conflict_severity text;
    occurred_at timestamptz;
BEGIN
    PERFORM 1 FROM core.workspace WHERE id = NEW.workspace_id FOR UPDATE;

    SELECT status,severity,updated_at
      INTO conflict_status,conflict_severity,occurred_at
      FROM core.conflict
     WHERE workspace_id = NEW.workspace_id
       AND id = NEW.conflict_id;

    IF conflict_severity IN ('CRITICAL', 'HIGH')
       AND conflict_status NOT IN ('RESOLVED', 'ACCEPTED_DIVERGENCE') THEN
        UPDATE learning.review_card
        SET status = 'INVALIDATED',
            invalidation_reason = 'HIGH_SEVERITY_CONFLICT:' || NEW.conflict_id::text,
            invalidated_at = occurred_at,
            version = version + 1,
            updated_at = occurred_at
        WHERE workspace_id = NEW.workspace_id
          AND claim_id = NEW.claim_id
          AND status = 'APPROVED';
    END IF;
    RETURN NEW;
END
$$;


--
-- Name: invalidate_review_cards_for_quarantined_source(); Type: FUNCTION; Schema: learning; Owner: -
--

CREATE FUNCTION learning.invalidate_review_cards_for_quarantined_source() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    occurred_at timestamptz;
BEGIN
    PERFORM 1 FROM core.workspace WHERE id = NEW.workspace_id FOR UPDATE;

    IF NEW.security_status = 'quarantined'
       AND (TG_OP = 'INSERT' OR NEW.security_status IS DISTINCT FROM OLD.security_status) THEN
        occurred_at := COALESCE(NEW.completed_at, CURRENT_TIMESTAMP);
        UPDATE learning.review_card AS card
        SET status = 'INVALIDATED',
            invalidation_reason = 'SOURCE_QUARANTINED:' || NEW.source_version_id::text,
            invalidated_at = occurred_at,
            version = card.version + 1,
            updated_at = occurred_at
        WHERE card.workspace_id = NEW.workspace_id
          AND card.status = 'APPROVED'
          AND EXISTS (
              SELECT 1
              FROM jsonb_array_elements(card.evidence) AS evidence(item)
              WHERE evidence.item->>'source_version_id' = NEW.source_version_id::text
          );
    END IF;
    RETURN NEW;
END
$$;


--
-- Name: mark_document_profiles_stale_on_index_activation(); Type: FUNCTION; Schema: learning; Owner: -
--

CREATE FUNCTION learning.mark_document_profiles_stale_on_index_activation() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    candidate record;
    stale_at timestamptz := clock_timestamp();
BEGIN
    FOR candidate IN
        SELECT profile.id,profile.workspace_id,profile.capture_id,profile.source_version_id
          FROM learning.document_knowledge_profile AS profile
          JOIN retrieval.index_manifest_source AS manifest_source
            ON manifest_source.index_version_id=NEW.target_index_version_id
           AND manifest_source.workspace_id=NEW.workspace_id
           AND manifest_source.source_version_id=profile.source_version_id
           AND manifest_source.selection_status='included'
          LEFT JOIN learning.document_knowledge_profile_revision AS revision
            ON revision.id=profile.current_revision_id
           AND revision.profile_id=profile.id
           AND revision.workspace_id=profile.workspace_id
           AND revision.source_version_id=profile.source_version_id
         WHERE profile.workspace_id=NEW.workspace_id
           AND (
                profile.status='RUNNING'
                OR (profile.status='READY' AND revision.parse_projection_id<>manifest_source.parse_projection_id)
           )
         ORDER BY profile.workspace_id,profile.capture_id,profile.source_version_id,profile.id
    LOOP
        PERFORM id
          FROM core.capture
         WHERE id=candidate.capture_id AND workspace_id=candidate.workspace_id
         FOR UPDATE;
        PERFORM pg_advisory_xact_lock(hashtextextended(
            candidate.workspace_id::text || chr(31) || candidate.source_version_id::text,0
        ));
        PERFORM id
          FROM learning.document_knowledge_profile
         WHERE id=candidate.id AND workspace_id=candidate.workspace_id
         FOR UPDATE;
    END LOOP;

    WITH candidates AS (
        SELECT profile.id,profile.workspace_id,profile.capture_id
          FROM learning.document_knowledge_profile AS profile
          JOIN learning.document_knowledge_profile_revision AS revision
            ON revision.id=profile.current_revision_id
           AND revision.profile_id=profile.id
           AND revision.workspace_id=profile.workspace_id
           AND revision.source_version_id=profile.source_version_id
          JOIN retrieval.index_manifest_source AS manifest_source
            ON manifest_source.index_version_id=NEW.target_index_version_id
           AND manifest_source.workspace_id=NEW.workspace_id
           AND manifest_source.source_version_id=profile.source_version_id
           AND manifest_source.selection_status='included'
         WHERE profile.workspace_id=NEW.workspace_id
           AND profile.status='READY'
           AND revision.parse_projection_id<>manifest_source.parse_projection_id
    ), stale_profiles AS (
        UPDATE learning.document_knowledge_profile AS profile
           SET status='STALE',error_code='',retryable=false,
               version=profile.version+1,updated_at=GREATEST(profile.updated_at,stale_at)
          FROM candidates
         WHERE profile.id=candidates.id AND profile.workspace_id=candidates.workspace_id
        RETURNING profile.workspace_id,profile.capture_id,profile.source_version_id
    )
    UPDATE core.capture AS capture
       SET profile_status='STALE',version=capture.version+1,
           updated_at=GREATEST(capture.updated_at,stale_at)
      FROM stale_profiles
     WHERE capture.workspace_id=stale_profiles.workspace_id
       AND capture.id=stale_profiles.capture_id
       AND capture.latest_source_version_id=stale_profiles.source_version_id
       AND capture.profile_status='READY';
    RETURN NEW;
END;
$$;


--
-- Name: mark_document_profiles_stale_on_model_settings_activation(); Type: FUNCTION; Schema: learning; Owner: -
--

CREATE FUNCTION learning.mark_document_profiles_stale_on_model_settings_activation() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    candidate record;
    stale_at timestamptz := clock_timestamp();
BEGIN
    -- Capture completion locks Capture before reading Profile. Keep the trigger
    -- on the same order, and use the per-Source fence shared with Profile completion.
    FOR candidate IN
        SELECT profile.id,profile.workspace_id,profile.capture_id,profile.source_version_id
          FROM learning.document_knowledge_profile AS profile
          JOIN learning.document_knowledge_profile_revision AS revision
            ON revision.id=profile.current_revision_id
           AND revision.profile_id=profile.id
           AND revision.workspace_id=profile.workspace_id
           AND revision.source_version_id=profile.source_version_id
          JOIN core.capture AS capture
            ON capture.id=profile.capture_id
           AND capture.workspace_id=profile.workspace_id
           AND capture.latest_source_version_id=profile.source_version_id
         WHERE profile.status='READY'
           AND revision.model_settings_revision IS DISTINCT FROM NEW.active_revision
         ORDER BY profile.workspace_id,profile.capture_id,profile.source_version_id,profile.id
    LOOP
        PERFORM id
          FROM core.capture
         WHERE id=candidate.capture_id AND workspace_id=candidate.workspace_id
         FOR UPDATE;
        PERFORM pg_advisory_xact_lock(hashtextextended(
            candidate.workspace_id::text || chr(31) || candidate.source_version_id::text,0
        ));
        PERFORM id
          FROM learning.document_knowledge_profile
         WHERE id=candidate.id AND workspace_id=candidate.workspace_id
         FOR UPDATE;
    END LOOP;

    WITH candidates AS (
        SELECT profile.id,profile.workspace_id,profile.capture_id
          FROM learning.document_knowledge_profile AS profile
          JOIN learning.document_knowledge_profile_revision AS revision
            ON revision.id=profile.current_revision_id
           AND revision.profile_id=profile.id
           AND revision.workspace_id=profile.workspace_id
           AND revision.source_version_id=profile.source_version_id
          JOIN core.capture AS capture
            ON capture.id=profile.capture_id
           AND capture.workspace_id=profile.workspace_id
           AND capture.latest_source_version_id=profile.source_version_id
         WHERE profile.status='READY'
           AND revision.model_settings_revision IS DISTINCT FROM NEW.active_revision
    ), stale_profiles AS (
        UPDATE learning.document_knowledge_profile AS profile
           SET status='STALE',error_code='',retryable=false,
               version=profile.version+1,updated_at=GREATEST(profile.updated_at,stale_at)
          FROM candidates
         WHERE profile.id=candidates.id AND profile.workspace_id=candidates.workspace_id
        RETURNING profile.workspace_id,profile.capture_id
    )
    UPDATE core.capture AS capture
       SET profile_status='STALE',version=capture.version+1,
           updated_at=GREATEST(capture.updated_at,stale_at)
     FROM stale_profiles
     WHERE capture.workspace_id=stale_profiles.workspace_id
       AND capture.id=stale_profiles.capture_id
       AND capture.profile_status='READY';
    RETURN NEW;
END;
$$;


--
-- Name: note_interview_item_points(jsonb); Type: FUNCTION; Schema: learning; Owner: -
--

CREATE FUNCTION learning.note_interview_item_points(item jsonb) RETURNS jsonb
    LANGUAGE sql IMMUTABLE
    AS $$
 WITH statements AS (
  SELECT 1::bigint n,item->'fact' statement WHERE item->>'kind'='FACT'
  UNION ALL SELECT n,statement FROM jsonb_array_elements(CASE WHEN item->>'kind'='CONFLICT' THEN item->'conflict'->'alternatives' ELSE '[]'::jsonb END) WITH ORDINALITY a(statement,n)
  UNION ALL SELECT 1,item->'gap'->'resolution' WHERE item->>'kind'='GAP' AND item->'gap'->'resolution'<>'null'::jsonb
 ), points AS (
  SELECT n*2 n,statement->>'text' value FROM statements
  UNION ALL SELECT n*2+1,statement->>'applicability' FROM statements WHERE statement->>'applicability'<>''
  UNION ALL SELECT 1,'Insufficient evidence; 不足以判断，需要补充资料。' WHERE item->>'kind'='GAP' AND item->'gap'->'resolution'='null'::jsonb
 ), unique_points AS (SELECT value,min(n) n FROM points GROUP BY value)
 SELECT jsonb_agg(value ORDER BY n) FROM unique_points
$$;


--
-- Name: note_interview_item_sources(jsonb); Type: FUNCTION; Schema: learning; Owner: -
--

CREATE FUNCTION learning.note_interview_item_sources(item jsonb) RETURNS jsonb
    LANGUAGE sql IMMUTABLE
    AS $$
 SELECT CASE item->>'kind'
  WHEN 'FACT' THEN item->'fact'->'sources'
  WHEN 'CONFLICT' THEN COALESCE((SELECT jsonb_agg(source ORDER BY alternative_no,source_no) FROM jsonb_array_elements(item->'conflict'->'alternatives') WITH ORDINALITY a(alternative,alternative_no)
    CROSS JOIN LATERAL jsonb_array_elements(alternative->'sources') WITH ORDINALITY s(source,source_no)),'[]'::jsonb)
  WHEN 'GAP' THEN COALESCE(item->'gap'->'sources','[]'::jsonb)||COALESCE(item->'gap'->'resolution'->'sources','[]'::jsonb)
 END
$$;


--
-- Name: project_artifact_revision_citation_selectors(); Type: FUNCTION; Schema: learning; Owner: -
--

CREATE FUNCTION learning.project_artifact_revision_citation_selectors() RETURNS trigger
    LANGUAGE plpgsql
    AS $_$
BEGIN
    IF NEW.domain_schema_version NOT IN ('artifact-revision/v1','artifact-revision/v2') THEN
        RETURN NEW;
    END IF;

    IF jsonb_typeof(NEW.sections) IS DISTINCT FROM 'array'
       OR EXISTS (
           SELECT 1
           FROM jsonb_array_elements(NEW.sections) AS section(value)
           WHERE jsonb_typeof(section.value) IS DISTINCT FROM 'object'
              OR jsonb_typeof(section.value->'Citations') IS DISTINCT FROM 'array'
       ) THEN
        RAISE EXCEPTION 'artifact revision citation sections are invalid'
            USING ERRCODE='23514';
    END IF;

    IF EXISTS (
        SELECT 1
        FROM jsonb_array_elements(NEW.sections) AS section(value)
        CROSS JOIN LATERAL jsonb_array_elements(section.value->'Citations') AS citation(value)
        WHERE jsonb_typeof(citation.value) IS DISTINCT FROM 'object'
           OR jsonb_typeof(citation.value->'SourceVersionID') IS DISTINCT FROM 'string'
           OR citation.value->>'SourceVersionID' !~ '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
           OR jsonb_typeof(citation.value->'SourceSpanID') IS DISTINCT FROM 'string'
           OR citation.value->>'SourceSpanID' !~ '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
           OR citation.value->>'SourceVersionID'=citation.value->>'SourceSpanID'
           OR citation.value->'Verified' IS DISTINCT FROM 'true'::jsonb
    ) THEN
        RAISE EXCEPTION 'artifact revision citation binding is invalid'
            USING ERRCODE='23514';
    END IF;

    INSERT INTO learning.artifact_revision_citation_selector(
        workspace_id,artifact_id,revision_id,source_version_id,source_span_id
    )
    SELECT DISTINCT NEW.workspace_id,NEW.artifact_id,NEW.id,
           (citation.value->>'SourceVersionID')::uuid,
           (citation.value->>'SourceSpanID')::uuid
    FROM jsonb_array_elements(NEW.sections) AS section(value)
    CROSS JOIN LATERAL jsonb_array_elements(section.value->'Citations') AS citation(value);
    RETURN NEW;
END;
$_$;


--
-- Name: project_artifact_revision_document_sources(); Type: FUNCTION; Schema: learning; Owner: -
--

CREATE FUNCTION learning.project_artifact_revision_document_sources() RETURNS trigger
    LANGUAGE plpgsql
    AS $_$
DECLARE
    document_source_count bigint;
BEGIN
    IF NEW.domain_schema_version IS DISTINCT FROM 'artifact-revision/v2' THEN
        RETURN NEW;
    END IF;

    IF jsonb_typeof(NEW.sections) IS DISTINCT FROM 'array'
       OR EXISTS (
           SELECT 1
           FROM jsonb_array_elements(NEW.sections) AS section(value)
           WHERE jsonb_typeof(section.value) IS DISTINCT FROM 'object'
              OR (
                  section.value ? 'DocumentSources'
                  AND jsonb_typeof(section.value->'DocumentSources') IS DISTINCT FROM 'array'
              )
              OR CASE
                  WHEN jsonb_typeof(section.value->'DocumentSources') = 'array'
                  THEN jsonb_array_length(section.value->'DocumentSources') > 64
                  ELSE false
              END
       ) THEN
        RAISE EXCEPTION 'artifact revision document source sections are invalid'
            USING ERRCODE='23514';
    END IF;

    IF EXISTS (
        SELECT 1
        FROM jsonb_array_elements(NEW.sections) AS section(value)
        CROSS JOIN LATERAL jsonb_array_elements(
            COALESCE(section.value->'DocumentSources','[]'::jsonb)
        ) AS document_source(value)
        WHERE jsonb_typeof(document_source.value) IS DISTINCT FROM 'object'
           OR NOT (document_source.value ?& ARRAY[
               'DocumentID','ArticleRevisionID','RevisionNo','VerifiedContentHash','Verified'
           ])
           OR document_source.value - ARRAY[
               'DocumentID','ArticleRevisionID','RevisionNo','VerifiedContentHash','Verified'
           ] <> '{}'::jsonb
           OR jsonb_typeof(document_source.value->'DocumentID') IS DISTINCT FROM 'string'
           OR document_source.value->>'DocumentID' !~
                '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
           OR jsonb_typeof(document_source.value->'ArticleRevisionID') IS DISTINCT FROM 'string'
           OR document_source.value->>'ArticleRevisionID' !~
                '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
           OR document_source.value->>'DocumentID'=document_source.value->>'ArticleRevisionID'
           OR jsonb_typeof(document_source.value->'RevisionNo') IS DISTINCT FROM 'number'
           OR document_source.value->>'RevisionNo' !~ '^[1-9][0-9]{0,9}$'
           OR CASE
               WHEN document_source.value->>'RevisionNo' ~ '^[1-9][0-9]{0,9}$'
               THEN (document_source.value->>'RevisionNo')::bigint > 2147483647
               ELSE false
           END
           OR jsonb_typeof(document_source.value->'VerifiedContentHash') IS DISTINCT FROM 'string'
           OR document_source.value->>'VerifiedContentHash' !~ '^[0-9a-f]{64}$'
           OR document_source.value->'Verified' IS DISTINCT FROM 'true'::jsonb
    ) THEN
        RAISE EXCEPTION 'artifact revision document source is invalid'
            USING ERRCODE='23514';
    END IF;

    SELECT count(*) INTO document_source_count
    FROM jsonb_array_elements(NEW.sections) AS section(value)
    CROSS JOIN LATERAL jsonb_array_elements(
        COALESCE(section.value->'DocumentSources','[]'::jsonb)
    ) AS document_source(value);
    IF document_source_count = 0 THEN
        RAISE EXCEPTION 'artifact revision v2 requires at least one document source'
            USING ERRCODE='23514';
    END IF;

    IF EXISTS (
        SELECT 1
        FROM jsonb_array_elements(NEW.sections) WITH ORDINALITY AS section(value,section_ordinality)
        CROSS JOIN LATERAL jsonb_array_elements(
            COALESCE(section.value->'DocumentSources','[]'::jsonb)
        ) AS document_source(value)
        GROUP BY section.section_ordinality,
                 document_source.value->>'DocumentID',
                 document_source.value->>'ArticleRevisionID',
                 document_source.value->>'VerifiedContentHash'
        HAVING count(*) > 1
    ) THEN
        RAISE EXCEPTION 'artifact revision section document source is duplicated'
            USING ERRCODE='23514';
    END IF;

    IF EXISTS (
        SELECT 1
        FROM jsonb_array_elements(NEW.sections) AS section(value)
        CROSS JOIN LATERAL jsonb_array_elements(
            COALESCE(section.value->'DocumentSources','[]'::jsonb)
        ) AS document_source(value)
        LEFT JOIN core.document AS document
          ON document.id=(document_source.value->>'DocumentID')::uuid
         AND document.workspace_id=NEW.workspace_id
         AND document.lifecycle_status<>'DELETED'
        LEFT JOIN core.article_revision AS article_revision
          ON article_revision.id=(document_source.value->>'ArticleRevisionID')::uuid
         AND article_revision.workspace_id=NEW.workspace_id
         AND article_revision.document_id=(document_source.value->>'DocumentID')::uuid
         AND article_revision.revision_no=(document_source.value->>'RevisionNo')::integer
         AND article_revision.content_hash=document_source.value->>'VerifiedContentHash'
        WHERE document.id IS NULL OR article_revision.id IS NULL
    ) THEN
        RAISE EXCEPTION 'artifact revision document source is not an exact verified article revision'
            USING ERRCODE='23514';
    END IF;

    INSERT INTO learning.artifact_revision_document_source(
        workspace_id,artifact_id,revision_id,document_id,article_revision_id,revision_no,content_hash
    )
    SELECT DISTINCT NEW.workspace_id,NEW.artifact_id,NEW.id,
           (document_source.value->>'DocumentID')::uuid,
           (document_source.value->>'ArticleRevisionID')::uuid,
           (document_source.value->>'RevisionNo')::integer,
           document_source.value->>'VerifiedContentHash'
    FROM jsonb_array_elements(NEW.sections) AS section(value)
    CROSS JOIN LATERAL jsonb_array_elements(
        COALESCE(section.value->'DocumentSources','[]'::jsonb)
    ) AS document_source(value);
    RETURN NEW;
END;
$_$;


--
-- Name: project_review_card_invalidation_health(); Type: FUNCTION; Schema: learning; Owner: -
--

CREATE FUNCTION learning.project_review_card_invalidation_health() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF TG_OP = 'INSERT' THEN
        IF NEW.status = 'INVALIDATED' THEN
            PERFORM learning.sync_review_invalidation_health(
                NEW.workspace_id,NEW.claim_id,COALESCE(NEW.invalidated_at,NEW.updated_at)
            );
        END IF;
        RETURN NEW;
    END IF;

    IF OLD.status = 'INVALIDATED' AND OLD.claim_id IS DISTINCT FROM NEW.claim_id THEN
        PERFORM learning.sync_review_invalidation_health(
            OLD.workspace_id,OLD.claim_id,COALESCE(NEW.updated_at,CURRENT_TIMESTAMP)
        );
    END IF;
    IF NEW.status = 'INVALIDATED' OR OLD.status = 'INVALIDATED' THEN
        PERFORM learning.sync_review_invalidation_health(
            NEW.workspace_id,NEW.claim_id,COALESCE(NEW.invalidated_at,NEW.updated_at,CURRENT_TIMESTAMP)
        );
    END IF;
    RETURN NEW;
END
$$;


--
-- Name: project_review_card_invalidation_health_insert_statement(); Type: FUNCTION; Schema: learning; Owner: -
--

CREATE FUNCTION learning.project_review_card_invalidation_health_insert_statement() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    affected_workspace_ids uuid[];
    affected_claim_ids uuid[];
    affected_occurred_ats timestamptz[];
BEGIN
    SELECT array_agg(affected.workspace_id ORDER BY affected.workspace_id,affected.claim_id),
           array_agg(affected.claim_id ORDER BY affected.workspace_id,affected.claim_id),
           array_agg(affected.occurred_at ORDER BY affected.workspace_id,affected.claim_id)
      INTO affected_workspace_ids,affected_claim_ids,affected_occurred_ats
    FROM (
        SELECT card.workspace_id,
               card.claim_id,
               max(COALESCE(card.invalidated_at,card.updated_at,CURRENT_TIMESTAMP)) AS occurred_at
        FROM new_review_cards AS card
        WHERE card.status = 'INVALIDATED'
          AND card.claim_id IS NOT NULL
        GROUP BY card.workspace_id,card.claim_id
    ) AS affected;
    PERFORM learning.sync_review_invalidation_health_batch(
        affected_workspace_ids,affected_claim_ids,affected_occurred_ats
    );
    RETURN NULL;
END
$$;


--
-- Name: project_review_card_invalidation_health_update_statement(); Type: FUNCTION; Schema: learning; Owner: -
--

CREATE FUNCTION learning.project_review_card_invalidation_health_update_statement() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    affected_workspace_ids uuid[];
    affected_claim_ids uuid[];
    affected_occurred_ats timestamptz[];
BEGIN
    SELECT array_agg(affected.workspace_id ORDER BY affected.workspace_id,affected.claim_id),
           array_agg(affected.claim_id ORDER BY affected.workspace_id,affected.claim_id),
           array_agg(affected.occurred_at ORDER BY affected.workspace_id,affected.claim_id)
      INTO affected_workspace_ids,affected_claim_ids,affected_occurred_ats
    FROM (
        SELECT changed.workspace_id,
               changed.claim_id,
               max(changed.occurred_at) AS occurred_at
        FROM (
            SELECT old_card.workspace_id,
                   old_card.claim_id,
                   COALESCE(new_card.updated_at,CURRENT_TIMESTAMP) AS occurred_at
            FROM old_review_cards AS old_card
            JOIN new_review_cards AS new_card ON new_card.id = old_card.id
            WHERE old_card.status = 'INVALIDATED'
              AND old_card.claim_id IS NOT NULL

            UNION ALL

            SELECT new_card.workspace_id,
                   new_card.claim_id,
                   COALESCE(new_card.invalidated_at,new_card.updated_at,CURRENT_TIMESTAMP) AS occurred_at
            FROM old_review_cards AS old_card
            JOIN new_review_cards AS new_card ON new_card.id = old_card.id
            WHERE (new_card.status = 'INVALIDATED' OR old_card.status = 'INVALIDATED')
              AND new_card.claim_id IS NOT NULL
        ) AS changed
        GROUP BY changed.workspace_id,changed.claim_id
    ) AS affected;
    PERFORM learning.sync_review_invalidation_health_batch(
        affected_workspace_ids,affected_claim_ids,affected_occurred_ats
    );
    RETURN NULL;
END
$$;


