    IF normalized_value IS NULL
       OR normalized_value !~ '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
        RETURN NULL;
    END IF;
    RETURN normalized_value::uuid;
END
$_$;


--
-- Name: validate_document_profile_evidence(); Type: FUNCTION; Schema: learning; Owner: -
--

CREATE FUNCTION learning.validate_document_profile_evidence() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    revision_projection_id uuid;
BEGIN
    SELECT parse_projection_id INTO revision_projection_id
      FROM learning.document_knowledge_profile_revision
     WHERE id=NEW.revision_id AND workspace_id=NEW.workspace_id
       AND source_version_id=NEW.source_version_id;
    IF revision_projection_id IS NULL OR NOT EXISTS (
        SELECT 1 FROM ingestion.source_span
         WHERE id=NEW.source_span_id AND workspace_id=NEW.workspace_id
           AND parse_projection_id=revision_projection_id
    ) THEN
        RAISE EXCEPTION 'document profile evidence is outside the frozen projection'
            USING ERRCODE='23514';
    END IF;
    RETURN NEW;
END;
$$;


--
-- Name: validate_document_profile_write(); Type: FUNCTION; Schema: learning; Owner: -
--

CREATE FUNCTION learning.validate_document_profile_write() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF TG_OP='INSERT' THEN
        IF NEW.version<>1 THEN
            RAISE EXCEPTION 'document profile must start at version one' USING ERRCODE='23514';
        END IF;
        RETURN NEW;
    END IF;
    IF TG_OP='DELETE'
       OR NEW.id<>OLD.id OR NEW.workspace_id<>OLD.workspace_id
       OR NEW.capture_id<>OLD.capture_id OR NEW.source_version_id<>OLD.source_version_id
       OR NEW.created_at<>OLD.created_at OR NEW.version<>OLD.version+1
       OR NEW.updated_at<OLD.updated_at THEN
        RAISE EXCEPTION 'document profile immutable field or version violation' USING ERRCODE='23514';
    END IF;
    RETURN NEW;
END;
$$;


--
-- Name: validate_smart_collection_command_insert(); Type: FUNCTION; Schema: learning; Owner: -
--

CREATE FUNCTION learning.validate_smart_collection_command_insert() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    current_version bigint;
BEGIN
    SELECT version INTO current_version
      FROM learning.smart_collection
     WHERE id = NEW.collection_id
       AND workspace_id = NEW.workspace_id
     FOR KEY SHARE;
    IF current_version IS NULL OR current_version <> NEW.collection_version THEN
        RAISE EXCEPTION 'smart collection command aggregate binding is invalid' USING ERRCODE = '23514';
    END IF;
    RETURN NEW;
END;
$$;


--
-- Name: validate_smart_collection_write(); Type: FUNCTION; Schema: learning; Owner: -
--

CREATE FUNCTION learning.validate_smart_collection_write() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF TG_OP = 'INSERT' THEN
        IF NEW.version <> 1 OR NEW.status <> 'ACTIVE' THEN
            RAISE EXCEPTION 'smart collection must start active at version one' USING ERRCODE = '23514';
        END IF;
        RETURN NEW;
    END IF;
    IF NEW.id <> OLD.id
       OR NEW.workspace_id <> OLD.workspace_id
       OR NEW.created_at <> OLD.created_at
       OR NEW.updated_at < OLD.updated_at
       OR NEW.version <> OLD.version + 1 THEN
        RAISE EXCEPTION 'smart collection immutable binding or version changed' USING ERRCODE = '23514';
    END IF;
    IF OLD.status = 'ARCHIVED' THEN
        RAISE EXCEPTION 'archived smart collection is immutable' USING ERRCODE = '55000';
    END IF;
    IF NEW.status NOT IN (OLD.status, 'ARCHIVED') THEN
        RAISE EXCEPTION 'smart collection transition is invalid' USING ERRCODE = '23514';
    END IF;
    IF NEW.query_definition IS DISTINCT FROM OLD.query_definition
       OR NEW.query_hash IS DISTINCT FROM OLD.query_hash
       OR NEW.query_schema_version IS DISTINCT FROM OLD.query_schema_version THEN
        IF NEW.query_version <> OLD.query_version + 1 THEN
            RAISE EXCEPTION 'query change must increment query version' USING ERRCODE = '23514';
        END IF;
    ELSIF NEW.query_version <> OLD.query_version THEN
        RAISE EXCEPTION 'query version cannot change without query change' USING ERRCODE = '23514';
    END IF;
    RETURN NEW;
END;
$$;


--
-- Name: verify_artifact_citation_selector(); Type: FUNCTION; Schema: learning; Owner: -
--

CREATE FUNCTION learning.verify_artifact_citation_selector() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    source_workspace_id uuid;
    span_workspace_id uuid;
    source_projection_id uuid;
    span_projection_id uuid;
BEGIN
    SELECT source.workspace_id
      INTO source_workspace_id
      FROM core.source_version AS version
      JOIN core.source AS source ON source.id=version.source_id
     WHERE version.id=NEW.source_version_id;

    SELECT span.workspace_id,span.parse_projection_id
      INTO span_workspace_id,span_projection_id
      FROM ingestion.source_span AS span
     WHERE span.id=NEW.source_span_id;

    SELECT projection.parse_projection_id
      INTO source_projection_id
      FROM ingestion.source_version_projection AS projection
     WHERE projection.source_version_id=NEW.source_version_id
       AND projection.parse_projection_id=span_projection_id;

    IF source_workspace_id IS NULL
       OR source_workspace_id <> NEW.workspace_id
       OR span_workspace_id IS NULL
       OR span_workspace_id <> NEW.workspace_id
       OR source_projection_id IS NULL THEN
        RAISE EXCEPTION 'artifact citation selector source binding mismatch'
            USING ERRCODE = '23514';
    END IF;
    RETURN NEW;
END;
$$;


--
-- Name: enforce_export_job_update(); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.enforce_export_job_update() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF NEW.version<>OLD.version+1 THEN
        RAISE EXCEPTION 'export job version must advance by one' USING ERRCODE='55000';
    END IF;
    IF ROW(
        NEW.id,NEW.workspace_id,NEW.scope_kind,NEW.kind,NEW.schema_version,NEW.query_definition,NEW.fields,
        NEW.idempotency_key,NEW.request_hash,NEW.request_ttl_seconds,NEW.expires_at,NEW.created_at,
        NEW.collection_id,NEW.collection_version,NEW.query_hash,NEW.attachment_root_contract_version,
        NEW.redaction_policy,NEW.include_sensitive,NEW.permission_scope,NEW.requested_by
    ) IS DISTINCT FROM ROW(
        OLD.id,OLD.workspace_id,OLD.scope_kind,OLD.kind,OLD.schema_version,OLD.query_definition,OLD.fields,
        OLD.idempotency_key,OLD.request_hash,OLD.request_ttl_seconds,OLD.expires_at,OLD.created_at,
        OLD.collection_id,OLD.collection_version,OLD.query_hash,OLD.attachment_root_contract_version,
        OLD.redaction_policy,OLD.include_sensitive,OLD.permission_scope,OLD.requested_by
    ) THEN
        RAISE EXCEPTION 'export request binding is immutable' USING ERRCODE='55000';
    END IF;
    IF OLD.prepared_at IS NOT NULL AND ROW(
        NEW.read_model_revision,NEW.exact_count,NEW.manifest_sha256,NEW.entry_count,NEW.total_uncompressed_bytes,
        NEW.prepared_at,NEW.prepared_staging_path,NEW.file_path,NEW.file_hash,NEW.file_size
    ) IS DISTINCT FROM ROW(
        OLD.read_model_revision,OLD.exact_count,OLD.manifest_sha256,OLD.entry_count,OLD.total_uncompressed_bytes,
        OLD.prepared_at,OLD.prepared_staging_path,OLD.file_path,OLD.file_hash,OLD.file_size
    ) THEN
        RAISE EXCEPTION 'export prepared result binding is immutable' USING ERRCODE='55000';
    END IF;
    IF NOT (
        (OLD.status=NEW.status AND OLD.status IN ('RUNNING','SUCCEEDED','EXPIRED'))
        OR (OLD.status='PENDING' AND NEW.status IN ('RUNNING','EXPIRED'))
        OR (OLD.status='RUNNING' AND NEW.status IN ('PENDING','SUCCEEDED','FAILED','EXPIRED'))
        OR (OLD.status='SUCCEEDED' AND NEW.status='EXPIRED')
        OR (OLD.status='FAILED' AND NEW.status='EXPIRED')
    ) THEN
        RAISE EXCEPTION 'export job status transition is invalid' USING ERRCODE='55000';
    END IF;
    IF NEW.attempt_count<OLD.attempt_count OR NEW.attempt_count>OLD.attempt_count+1
       OR NEW.download_count<OLD.download_count OR NEW.download_count>OLD.download_count+1
       OR NEW.cleanup_attempt_count<OLD.cleanup_attempt_count OR NEW.cleanup_attempt_count>OLD.cleanup_attempt_count+1 THEN
        RAISE EXCEPTION 'export counter transition is invalid' USING ERRCODE='55000';
    END IF;
    IF NEW.updated_at<OLD.updated_at THEN
        RAISE EXCEPTION 'export updated_at cannot move backwards' USING ERRCODE='55000';
    END IF;
    RETURN NEW;
END
$$;


--
-- Name: enforce_managed_ollama_hold(); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.enforce_managed_ollama_hold() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF TG_OP='UPDATE' THEN
        IF ROW(NEW.hold_id,NEW.owner_kind,NEW.owner_id,NEW.owner_epoch,NEW.role,NEW.instance_id,
               NEW.revision,NEW.rollout_id,NEW.operation_id,NEW.requirement_hash,NEW.models,NEW.created_at)
           IS DISTINCT FROM
           ROW(OLD.hold_id,OLD.owner_kind,OLD.owner_id,OLD.owner_epoch,OLD.role,OLD.instance_id,
               OLD.revision,OLD.rollout_id,OLD.operation_id,OLD.requirement_hash,OLD.models,OLD.created_at)
           OR NEW.updated_at<OLD.updated_at THEN
            RAISE EXCEPTION 'managed Ollama hold identity is immutable' USING ERRCODE='55000';
        END IF;
        IF OLD.released_at IS NULL AND NEW.released_at IS NULL THEN
            IF NEW.version<>OLD.version+1 OR NEW.lease_expires_at<OLD.lease_expires_at THEN
                RAISE EXCEPTION 'managed Ollama hold renewal is invalid' USING ERRCODE='55000';
            END IF;
        ELSIF OLD.released_at IS NULL AND NEW.released_at IS NOT NULL THEN
            IF NEW.version<>OLD.version+1 THEN
                RAISE EXCEPTION 'managed Ollama hold release version is invalid' USING ERRCODE='55000';
            END IF;
        ELSIF ROW(NEW.version,NEW.released_at) IS DISTINCT FROM ROW(OLD.version,OLD.released_at) THEN
            RAISE EXCEPTION 'managed Ollama released hold is immutable' USING ERRCODE='55000';
        END IF;
    END IF;
    RETURN NEW;
END
$$;


--
-- Name: enforce_managed_ollama_operation(); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.enforce_managed_ollama_operation() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF TG_OP IN ('DELETE','TRUNCATE') THEN
        RAISE EXCEPTION 'managed Ollama operations cannot be deleted' USING ERRCODE='55000';
    END IF;
    IF TG_OP='UPDATE' THEN
        IF NEW.operation_id<>OLD.operation_id OR NEW.kind<>OLD.kind OR NEW.idempotency_key<>OLD.idempotency_key
           OR NEW.request_hash<>OLD.request_hash OR NEW.requirement_hash<>OLD.requirement_hash
           OR NEW.version<>OLD.version+1 OR NEW.created_at<>OLD.created_at OR NEW.updated_at<OLD.updated_at THEN
            RAISE EXCEPTION 'managed Ollama operation identity/version is immutable' USING ERRCODE='55000';
        END IF;
        IF OLD.terminal_at IS NOT NULL AND ROW(NEW.phase,NEW.terminal_at,NEW.error_code,NEW.error_retryable)
             IS DISTINCT FROM ROW(OLD.phase,OLD.terminal_at,OLD.error_code,OLD.error_retryable) THEN
            RAISE EXCEPTION 'managed Ollama terminal operation is immutable' USING ERRCODE='55000';
        END IF;
        IF NOT (NEW.phase=OLD.phase OR
            (OLD.phase='queued' AND NEW.phase IN ('starting','failed')) OR
            (OLD.phase='starting' AND NEW.phase IN ('checking','pulling','failed')) OR
            (OLD.phase='checking' AND NEW.phase IN ('pulling','verifying','failed')) OR
            (OLD.phase='pulling' AND NEW.phase IN ('pulling','verifying','failed')) OR
            (OLD.phase='verifying' AND NEW.phase IN ('ready','failed')) OR
            (OLD.kind='active_recovery' AND OLD.phase='verifying' AND NEW.phase='succeeded') OR
            (OLD.phase='ready' AND NEW.phase IN ('probing','succeeded','failed')) OR
            (OLD.phase='probing' AND NEW.phase IN ('ready','succeeded','failed')) OR
            (OLD.phase NOT IN ('succeeded','failed','superseded') AND NEW.phase='superseded')) THEN
            RAISE EXCEPTION 'managed Ollama operation phase transition is invalid' USING ERRCODE='55000';
        END IF;
        IF OLD.kind='test' AND OLD.phase='ready' AND NEW.phase='succeeded' THEN
            RAISE EXCEPTION 'managed Ollama test production probe must be claimed' USING ERRCODE='55000';
        END IF;
        IF OLD.kind='test' AND OLD.phase='ready' AND NEW.phase='failed'
           AND NEW.error_code<>'LOCAL_MODEL_RUNTIME_PREPARATION_TIMEOUT' THEN
            RAISE EXCEPTION 'managed Ollama test production probe must be claimed' USING ERRCODE='55000';
        END IF;
        IF OLD.phase='ready' AND NEW.phase='probing'
           AND (NEW.claim_owner_id IS NULL OR NEW.claim_owner_epoch IS NULL OR NEW.claim_expires_at IS NULL) THEN
            RAISE EXCEPTION 'managed Ollama production probe must be claimed' USING ERRCODE='55000';
        END IF;
        IF OLD.phase='ready' AND NEW.phase='probing'
           AND NOT EXISTS (
               SELECT 1 FROM ops.managed_ollama_holds
               WHERE owner_kind='test' AND operation_id=OLD.operation_id
                 AND released_at IS NULL AND owner_id<>NEW.claim_owner_id
           ) THEN
            RAISE EXCEPTION 'managed Ollama production probe owner conflicts with its hold' USING ERRCODE='55000';
        END IF;
        IF OLD.phase='probing' AND NEW.phase='probing'
           AND ROW(NEW.claim_owner_id,NEW.claim_owner_epoch) IS DISTINCT FROM ROW(OLD.claim_owner_id,OLD.claim_owner_epoch)
           AND OLD.claim_expires_at>clock_timestamp() THEN
            RAISE EXCEPTION 'managed Ollama production probe owner is fresh' USING ERRCODE='55000';
        END IF;
        IF OLD.phase='probing' AND NEW.phase IN ('ready','succeeded','failed')
           AND (OLD.claim_owner_id IS NULL OR OLD.claim_owner_epoch IS NULL OR OLD.claim_expires_at IS NULL) THEN
            RAISE EXCEPTION 'managed Ollama production probe completion is unowned' USING ERRCODE='55000';
        END IF;
    END IF;
    RETURN NEW;
END
$$;


--
-- Name: enforce_managed_ollama_runtime(); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.enforce_managed_ollama_runtime() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF TG_OP='UPDATE' THEN
        IF NEW.singleton<>OLD.singleton OR NEW.mode<>OLD.mode
           OR NEW.owner_epoch<OLD.owner_epoch OR NEW.requirement_version<OLD.requirement_version
           OR NEW.child_epoch<OLD.child_epoch OR NEW.version<>OLD.version+1
           OR NEW.updated_at<OLD.updated_at THEN
            RAISE EXCEPTION 'managed Ollama runtime fence/version is invalid' USING ERRCODE='55000';
        END IF;
        IF NEW.owner_id IS DISTINCT FROM OLD.owner_id AND NEW.owner_epoch<>OLD.owner_epoch+1 THEN
            RAISE EXCEPTION 'managed Ollama runtime takeover must advance owner epoch' USING ERRCODE='55000';
        END IF;
        IF NEW.owner_id IS NOT DISTINCT FROM OLD.owner_id AND NEW.owner_epoch<>OLD.owner_epoch
           AND NOT (OLD.owner_id IS NULL AND NEW.owner_id IS NOT NULL AND NEW.owner_epoch=1) THEN
            RAISE EXCEPTION 'managed Ollama runtime owner epoch changed unexpectedly' USING ERRCODE='55000';
        END IF;
        IF NOT (NEW.observed_phase=OLD.observed_phase OR
            (OLD.observed_phase='stopped' AND NEW.observed_phase IN ('starting','failed')) OR
            (OLD.observed_phase='starting' AND NEW.observed_phase IN ('pulling','checking','ready','failed','stopping')) OR
            (OLD.observed_phase='pulling' AND NEW.observed_phase IN ('pulling','checking','ready','failed','stopping')) OR
            (OLD.observed_phase='checking' AND NEW.observed_phase IN ('pulling','ready','failed','stopping')) OR
            (OLD.observed_phase='ready' AND NEW.observed_phase IN ('starting','pulling','checking','stopping','failed')) OR
            (OLD.observed_phase='stopping' AND NEW.observed_phase IN ('stopped','starting','failed')) OR
            (OLD.observed_phase='failed' AND NEW.observed_phase IN ('stopped','starting','pulling','checking','ready','stopping'))) THEN
            RAISE EXCEPTION 'managed Ollama runtime phase transition is invalid' USING ERRCODE='55000';
        END IF;
        IF NEW.observed_phase='ready' AND (NEW.ready_requirement_hash='' OR NEW.ready_requirement_hash<>NEW.requirement_hash) THEN
            RAISE EXCEPTION 'managed Ollama ready phase must bind the current requirement' USING ERRCODE='55000';
        END IF;
        IF NEW.observed_phase IN ('stopped','starting','stopping') AND NEW.ready_requirement_hash<>'' THEN
            RAISE EXCEPTION 'managed Ollama non-ready phase retained ready binding' USING ERRCODE='55000';
        END IF;
    END IF;
    RETURN NEW;
END
$$;


--
-- Name: enforce_model_settings_participant(); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.enforce_model_settings_participant() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    state_rollout_id uuid;
    state_target_revision bigint;
    state_phase text;
    runtime_instance_id uuid;
    runtime_applied_revision bigint;
    participant_now timestamptz;
BEGIN
    IF TG_OP IN ('DELETE','TRUNCATE') THEN
        RAISE EXCEPTION 'model settings participant history cannot be deleted' USING ERRCODE='55000';
    END IF;
    IF NOT ops.model_settings_revision_exists(NEW.target_revision) THEN
        RAISE EXCEPTION 'model settings participant references an unknown revision' USING ERRCODE='23503';
    END IF;
    IF TG_OP='UPDATE' AND (NEW.rollout_id<>OLD.rollout_id OR NEW.role<>OLD.role
       OR NEW.target_revision<>OLD.target_revision OR NEW.heartbeat_at<OLD.heartbeat_at
       OR NEW.version<>OLD.version+1) THEN
        RAISE EXCEPTION 'model settings participant binding or version is invalid' USING ERRCODE='55000';
    END IF;
    SELECT rollout_id,target_revision,phase
      INTO state_rollout_id,state_target_revision,state_phase
      FROM ops.model_settings_state WHERE singleton=true;
    IF NEW.phase NOT IN ('failed','aborted','retired') THEN
        IF state_rollout_id IS DISTINCT FROM NEW.rollout_id
           OR state_target_revision IS DISTINCT FROM NEW.target_revision THEN
            RAISE EXCEPTION 'model settings participant does not match the live activation' USING ERRCODE='23514';
        END IF;
        SELECT instance_id,applied_revision INTO runtime_instance_id,runtime_applied_revision
          FROM ops.model_settings_runtime WHERE role=NEW.role;
        IF runtime_instance_id IS DISTINCT FROM NEW.instance_id THEN
            RAISE EXCEPTION 'model settings participant does not match the serving owner' USING ERRCODE='23514';
        END IF;
        IF NEW.phase='activated' AND runtime_applied_revision IS DISTINCT FROM NEW.target_revision THEN
            RAISE EXCEPTION 'activated model settings participant does not match serving revision' USING ERRCODE='23514';
        END IF;
    END IF;
    IF TG_OP='INSERT' THEN
        IF NOT ((state_phase IN ('preparing','arming') AND NEW.phase='preparing')
            OR (state_phase='activating' AND NEW.phase='activated')) THEN
            RAISE EXCEPTION 'model settings participant initial phase is invalid' USING ERRCODE='55000';
        END IF;
        RETURN NEW;
    END IF;
    IF NEW.instance_id<>OLD.instance_id THEN
        participant_now := clock_timestamp();
        IF NEW.heartbeat_at>participant_now THEN
            RAISE EXCEPTION 'model settings participant takeover heartbeat is invalid' USING ERRCODE='55000';
        END IF;
        IF NOT OLD.heartbeat_at < participant_now-interval '20 seconds' THEN
            RAISE EXCEPTION 'model settings participant owner is still fresh' USING ERRCODE='55000';
        END IF;
        IF NOT ((state_phase IN ('preparing','arming') AND NEW.phase='preparing')
            OR (state_phase='activating' AND NEW.phase='activated')) THEN
            RAISE EXCEPTION 'model settings participant takeover is invalid' USING ERRCODE='55000';
        END IF;
        RETURN NEW;
    END IF;
    IF NOT (
        NEW.phase=OLD.phase
        OR (OLD.phase='preparing' AND NEW.phase IN ('prepared','failed','aborted'))
        OR (OLD.phase='prepared' AND NEW.phase IN ('armed','failed','aborted'))
        OR (OLD.phase='armed' AND NEW.phase IN ('activated','failed','aborted'))
        OR (OLD.phase='activated' AND NEW.phase='retired')
    ) THEN
        RAISE EXCEPTION 'model settings participant transition is invalid' USING ERRCODE='55000';
    END IF;
    IF NEW.phase IN ('failed','aborted') AND state_phase NOT IN ('preparing','arming','failed') THEN
        RAISE EXCEPTION 'model settings participant cannot fail after commit' USING ERRCODE='55000';
    END IF;
    RETURN NEW;
END
$$;


--
-- Name: enforce_model_settings_runtime(); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.enforce_model_settings_runtime() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    activation_allowed boolean;
    state_active_revision bigint;
    state_previous_active_revision bigint;
    state_target_revision bigint;
    state_phase text;
    runtime_now timestamptz;
BEGIN
    IF TG_OP IN ('DELETE','TRUNCATE') THEN
        RAISE EXCEPTION 'model settings runtime ownership cannot be deleted' USING ERRCODE='55000';
    END IF;
    IF NOT ops.model_settings_revision_exists(NEW.applied_revision) THEN
        RAISE EXCEPTION 'model settings runtime references an unknown revision' USING ERRCODE='23503';
    END IF;
    IF TG_OP='INSERT' OR NEW.instance_id<>OLD.instance_id THEN
        runtime_now := clock_timestamp();
        IF NEW.phase NOT IN ('active','unavailable') OR NEW.rollout_id IS NOT NULL
           OR NEW.heartbeat_at>runtime_now OR NEW.applied_at>runtime_now THEN
            RAISE EXCEPTION 'model settings runtime serving registration is invalid' USING ERRCODE='55000';
        END IF;
        SELECT active_revision,previous_active_revision,target_revision,phase
          INTO state_active_revision,state_previous_active_revision,state_target_revision,state_phase
          FROM ops.model_settings_state WHERE singleton=true;
        IF NOT FOUND THEN
            RAISE EXCEPTION 'model settings singleton state is missing' USING ERRCODE='23503';
        END IF;
        IF state_phase IN ('idle','failed') THEN
            IF NEW.applied_revision<>state_active_revision THEN
                RAISE EXCEPTION 'model settings runtime revision is not active' USING ERRCODE='55000';
            END IF;
        ELSIF state_phase IN ('preparing','arming') THEN
            IF NEW.applied_revision<>state_active_revision
               OR state_previous_active_revision IS DISTINCT FROM state_active_revision THEN
                RAISE EXCEPTION 'model settings runtime revision is not the pre-commit active revision' USING ERRCODE='55000';
            END IF;
        ELSIF state_phase='activating' THEN
            IF NEW.applied_revision IS DISTINCT FROM state_target_revision THEN
                RAISE EXCEPTION 'model settings runtime revision is not the committed target' USING ERRCODE='55000';
            END IF;
        ELSE
            RAISE EXCEPTION 'model settings runtime registration phase is invalid' USING ERRCODE='55000';
        END IF;
        IF TG_OP='UPDATE' THEN
            IF NOT OLD.heartbeat_at < runtime_now-interval '20 seconds' THEN
                RAISE EXCEPTION 'model settings runtime owner is still fresh' USING ERRCODE='55000';
            END IF;
            IF NEW.applied_at<OLD.applied_at THEN
                RAISE EXCEPTION 'model settings runtime applied time cannot move backwards' USING ERRCODE='55000';
            END IF;
            -- A replacement may advance only as post-commit recovery from the
            -- persisted previous serving revision to the committed target.
            IF NEW.applied_revision<>OLD.applied_revision
               AND NOT (state_phase='activating'
                   AND OLD.applied_revision IS NOT DISTINCT FROM state_previous_active_revision
                   AND NEW.applied_revision IS NOT DISTINCT FROM state_target_revision) THEN
                RAISE EXCEPTION 'model settings runtime takeover cannot change revision' USING ERRCODE='55000';
            END IF;
        END IF;
        RETURN NEW;
    END IF;
    IF NEW.heartbeat_at<OLD.heartbeat_at THEN
        RAISE EXCEPTION 'model settings runtime heartbeat cannot move backwards' USING ERRCODE='55000';
    END IF;
    IF NEW.applied_revision<>OLD.applied_revision THEN
        SELECT EXISTS (
            SELECT 1
              FROM ops.model_settings_state AS state
              JOIN ops.model_settings_rollout_participant AS participant
                ON participant.rollout_id=state.rollout_id AND participant.role=NEW.role
             WHERE state.singleton=true AND state.phase='activating'
               AND state.target_revision=NEW.applied_revision
               AND participant.instance_id=NEW.instance_id
               AND participant.target_revision=NEW.applied_revision
               AND participant.phase='armed'
        ) INTO activation_allowed;
        IF NOT activation_allowed OR NEW.phase<>'active' OR NEW.rollout_id IS NOT NULL
           OR NEW.applied_at<OLD.applied_at THEN
            RAISE EXCEPTION 'model settings runtime activation binding is invalid' USING ERRCODE='55000';
        END IF;
        RETURN NEW;
    END IF;
    IF NEW.applied_at<>OLD.applied_at THEN
        RAISE EXCEPTION 'model settings runtime applied time is immutable without activation' USING ERRCODE='55000';
    END IF;
    IF OLD.phase='unavailable' AND NEW.phase='active'
       AND OLD.rollout_id IS NULL AND NEW.rollout_id IS NULL THEN
        SELECT EXISTS (
            SELECT 1 FROM ops.model_settings_state AS state
             WHERE state.singleton=true
               AND ((state.phase IN ('idle','failed') AND state.active_revision=NEW.applied_revision)
                    OR (state.phase IN ('preparing','arming')
                        AND state.active_revision=NEW.applied_revision
                        AND state.previous_active_revision=NEW.applied_revision)
                    OR (state.phase='activating' AND state.active_revision=NEW.applied_revision
                        AND state.target_revision=NEW.applied_revision))
        ) INTO activation_allowed;
        IF NOT activation_allowed THEN
            RAISE EXCEPTION 'model settings runtime availability restore is invalid' USING ERRCODE='55000';
        END IF;
        RETURN NEW;
    END IF;
    IF NOT (NEW.phase=OLD.phase AND NEW.rollout_id IS NOT DISTINCT FROM OLD.rollout_id)
       AND NOT (NEW.phase='unavailable' AND NEW.rollout_id IS NULL) THEN
        RAISE EXCEPTION 'model settings runtime phase transition is invalid' USING ERRCODE='55000';
    END IF;
    RETURN NEW;
END
$$;


--
-- Name: enforce_model_settings_state(); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.enforce_model_settings_state() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    activation_now timestamptz;
    ready_role text;
    ready_roles integer := 0;
BEGIN
    IF TG_OP IN ('DELETE','TRUNCATE') THEN
        RAISE EXCEPTION 'model settings singleton state cannot be deleted' USING ERRCODE='55000';
    END IF;
    IF NOT ops.model_settings_revision_exists(NEW.desired_revision)
       OR NOT ops.model_settings_revision_exists(NEW.active_revision)
       OR (NEW.target_revision IS NOT NULL AND NOT ops.model_settings_revision_exists(NEW.target_revision))
       OR (NEW.previous_active_revision IS NOT NULL AND NOT ops.model_settings_revision_exists(NEW.previous_active_revision)) THEN
        RAISE EXCEPTION 'model settings state references an unknown revision' USING ERRCODE='23503';
    END IF;
    IF TG_OP='INSERT' THEN
        RETURN NEW;
    END IF;
    IF NEW.version<>OLD.version+1 OR NEW.updated_at<OLD.updated_at THEN
        RAISE EXCEPTION 'model settings state version is invalid' USING ERRCODE='55000';
    END IF;
    IF NEW.desired_revision<>OLD.desired_revision AND NEW.desired_revision<=OLD.desired_revision THEN
        RAISE EXCEPTION 'model settings desired revision cannot move backwards' USING ERRCODE='55000';
    END IF;
    IF OLD.phase IN ('preparing','arming','activating')
       AND NEW.desired_revision<>OLD.desired_revision THEN
        RAISE EXCEPTION 'model settings desired revision is fixed during activation' USING ERRCODE='55000';
    END IF;
    IF OLD.active_revision<>NEW.active_revision
       AND NOT (OLD.phase='arming' AND NEW.phase='activating'
           AND NEW.active_revision=OLD.target_revision) THEN
        RAISE EXCEPTION 'model settings active revision transition is invalid' USING ERRCODE='55000';
    END IF;
    IF OLD.phase IN ('preparing','arming') AND NEW.phase='failed'
       AND EXISTS (
            SELECT 1 FROM ops.model_settings_rollout_participant
            WHERE rollout_id=OLD.rollout_id AND phase IN ('preparing','prepared','armed')
       ) THEN
        RAISE EXCEPTION 'model settings participants must be aborted before activation failure' USING ERRCODE='55000';
    END IF;
    IF NOT (
        (OLD.phase=NEW.phase AND OLD.phase IN ('idle','failed'))
        OR (OLD.phase IN ('idle','failed') AND NEW.phase='preparing'
            AND NEW.target_revision=NEW.desired_revision
            AND NEW.previous_active_revision=OLD.active_revision
            AND NEW.active_revision=OLD.active_revision)
        OR (OLD.phase=NEW.phase AND OLD.phase IN ('preparing','arming','activating')
            AND NEW.rollout_id=OLD.rollout_id AND NEW.target_revision=OLD.target_revision
            AND NEW.previous_active_revision=OLD.previous_active_revision
            AND NEW.active_revision=OLD.active_revision)
        OR (OLD.phase='preparing' AND NEW.phase='arming'
            AND NEW.active_revision=OLD.previous_active_revision)
        OR (OLD.phase IN ('preparing','arming') AND NEW.phase='failed'
            AND NEW.rollout_id=OLD.rollout_id AND NEW.target_revision=OLD.target_revision
            AND NEW.previous_active_revision=OLD.previous_active_revision
            AND NEW.active_revision=OLD.previous_active_revision)
        OR (OLD.phase='arming' AND NEW.phase='activating'
            AND NEW.rollout_id=OLD.rollout_id AND NEW.target_revision=OLD.target_revision
            AND NEW.previous_active_revision=OLD.previous_active_revision
            AND NEW.active_revision=OLD.target_revision)
        OR (OLD.phase='activating' AND NEW.phase='idle'
            AND NEW.active_revision=OLD.target_revision)
    ) THEN
        RAISE EXCEPTION 'model settings activation transition is invalid' USING ERRCODE='55000';
    END IF;
    IF OLD.phase='failed' AND NEW.phase='failed'
       AND ROW(NEW.rollout_id,NEW.target_revision,NEW.previous_active_revision,NEW.last_error_code)
           IS DISTINCT FROM ROW(OLD.rollout_id,OLD.target_revision,OLD.previous_active_revision,OLD.last_error_code) THEN
        RAISE EXCEPTION 'failed model settings activation binding is immutable' USING ERRCODE='55000';
    END IF;
    IF OLD.phase IN ('preparing','arming','activating')
       AND NEW.phase IN ('preparing','arming','activating')
       AND ROW(NEW.rollout_id,NEW.target_revision,NEW.previous_active_revision)
           IS DISTINCT FROM ROW(OLD.rollout_id,OLD.target_revision,OLD.previous_active_revision) THEN
        RAISE EXCEPTION 'model settings activation binding is immutable' USING ERRCODE='55000';
    END IF;
    IF OLD.phase='arming' AND NEW.phase='activating' THEN
        -- Lock in the same order as CommitActivation: singleton state, serving
        -- runtimes by role, then the matching participant rows by role.
        activation_now := clock_timestamp();
        FOR ready_role IN
            SELECT runtime.role
              FROM ops.model_settings_runtime AS runtime
              JOIN ops.model_settings_rollout_participant AS participant
                ON participant.rollout_id=NEW.rollout_id AND participant.role=runtime.role
             WHERE runtime.role IN ('api','worker')
               AND runtime.instance_id=participant.instance_id
               AND runtime.rollout_id IS NULL AND runtime.phase='active'
               AND runtime.applied_revision=NEW.previous_active_revision
               AND participant.target_revision=NEW.target_revision AND participant.phase='armed'
               AND runtime.heartbeat_at BETWEEN activation_now-interval '20 seconds' AND activation_now
               AND participant.heartbeat_at BETWEEN activation_now-interval '20 seconds' AND activation_now
             ORDER BY runtime.role
             FOR SHARE OF runtime, participant
        LOOP
            ready_roles := ready_roles+1;
        END LOOP;
        IF ready_roles<>2 THEN
            RAISE EXCEPTION 'both model settings activation roles must be fresh and armed' USING ERRCODE='55000';
        END IF;
    END IF;
    RETURN NEW;
END
$$;


--
-- Name: enforce_runtime_mutation_gate(); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.enforce_runtime_mutation_gate() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF TG_OP IN ('DELETE','TRUNCATE') THEN
        RAISE EXCEPTION 'runtime mutation gate cannot be deleted' USING ERRCODE='55000';
    END IF;
    IF TG_OP='INSERT' THEN
        RETURN NEW;
    END IF;
    IF NEW.version<>OLD.version+1 OR NEW.updated_at<OLD.updated_at THEN
        RAISE EXCEPTION 'runtime mutation gate version is invalid' USING ERRCODE='40001';
    END IF;
    IF OLD.owner_id IS NOT NULL AND NEW.owner_id IS NOT NULL
       AND NEW.owner_id IS DISTINCT FROM OLD.owner_id
       AND OLD.lease_expires_at>NEW.updated_at THEN
        RAISE EXCEPTION 'runtime mutation gate is held' USING ERRCODE='55P03';
    END IF;
    RETURN NEW;
END
$$;


--
-- Name: enforce_workspace_control_state(); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.enforce_workspace_control_state() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF TG_OP IN ('DELETE','TRUNCATE') THEN
        RAISE EXCEPTION 'workspace control singleton cannot be deleted' USING ERRCODE='55000';
    END IF;
    IF TG_OP='INSERT' THEN
        RETURN NEW;
    END IF;
    IF NEW.state_version<>OLD.state_version+1 OR NEW.updated_at<OLD.updated_at THEN
        RAISE EXCEPTION 'workspace control state version is invalid' USING ERRCODE='40001';
    END IF;
    IF NEW.grant_generation<OLD.grant_generation THEN
        RAISE EXCEPTION 'workspace grant generation cannot move backwards' USING ERRCODE='55000';
    END IF;
    RETURN NEW;
END
$$;


--
-- Name: enforce_workspace_root_binding_history(); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.enforce_workspace_root_binding_history() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF TG_OP IN ('UPDATE','DELETE','TRUNCATE') THEN
        RAISE EXCEPTION 'workspace root binding history is append-only' USING ERRCODE='55000';
    END IF;
    IF NEW.transaction_id<>pg_current_xact_id() THEN
        RAISE EXCEPTION 'workspace root binding history must be created in the binding transaction'
            USING ERRCODE='55000';
    END IF;
    PERFORM pg_advisory_xact_lock(hashtextextended(NEW.workspace_id::text,0));
    PERFORM pg_advisory_xact_lock(hashtextextended(LEAST(NEW.old_root_fingerprint,NEW.new_root_fingerprint),0));
    PERFORM pg_advisory_xact_lock(hashtextextended(GREATEST(NEW.old_root_fingerprint,NEW.new_root_fingerprint),0));
    PERFORM 1 FROM ops.workspace_control_state WHERE singleton=true FOR UPDATE;
    IF EXISTS (
        SELECT 1
        FROM ops.workspace_control_state AS state
        WHERE state.singleton=true
          AND (state.active_workspace_id IS NOT NULL
            OR state.resume_workspace_id IS NOT NULL
            OR state.operation_id IS NOT NULL
            OR state.operation_phase IS NOT NULL
            OR state.target_workspace_id IS NOT NULL
            OR state.previous_active_workspace_id IS NOT NULL
            OR state.controller_lease_owner_id IS NOT NULL
            OR state.controller_lease_expires_at IS NOT NULL)
    ) THEN
        RAISE EXCEPTION 'workspace root binding cannot change while control state retains a binding'
            USING ERRCODE='55P03';
    END IF;
    PERFORM 1 FROM ops.runtime_mutation_gate WHERE singleton=true FOR UPDATE;
    IF EXISTS (
        SELECT 1 FROM ops.runtime_mutation_gate
        WHERE singleton=true AND owner_id IS NOT NULL
    ) THEN
        RAISE EXCEPTION 'workspace root binding cannot change while the runtime mutation gate is held'
            USING ERRCODE='55P03';
    END IF;
    PERFORM 1 FROM core.workspace WHERE id=NEW.workspace_id FOR UPDATE;
    IF EXISTS (
        SELECT 1 FROM core.workspace_git_capture_checkpoint
        WHERE workspace_id=NEW.workspace_id
    ) THEN
        RAISE EXCEPTION 'workspace Git capture lineage requires explicit rebaseline'
            USING ERRCODE='55000';
    END IF;
    IF NOT EXISTS (
        SELECT 1
        FROM core.workspace AS workspace
        WHERE workspace.id=NEW.workspace_id
          AND workspace.root_path=NEW.canonical_root
          AND workspace.git_repository_path=NEW.canonical_root
          AND workspace.root_fingerprint=NEW.old_root_fingerprint
          AND workspace.binding_version=NEW.old_binding_version
          AND workspace.version=NEW.old_workspace_version
          AND workspace.status='inactive'
          AND workspace.availability='migration_required'
          AND workspace.availability_reason='WORKSPACE_ROOT_IDENTITY_CHANGED'
          AND workspace.removed_at IS NULL
    ) THEN
        RAISE EXCEPTION 'workspace root binding history does not match the migration-required identity'
            USING ERRCODE='55000';
    END IF;
    PERFORM 1 FROM ops.workspace_runtime
        WHERE workspace_id=NEW.workspace_id ORDER BY role FOR UPDATE;
    IF EXISTS (
        SELECT 1 FROM ops.workspace_runtime
        WHERE workspace_id=NEW.workspace_id AND phase<>'unavailable'
    ) THEN
        RAISE EXCEPTION 'workspace root binding cannot change while a runtime remains available'
            USING ERRCODE='55P03';
    END IF;
    RETURN NEW;
END
$$;


--
-- Name: enforce_workspace_root_binding_history_commit(); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.enforce_workspace_root_binding_history_commit() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF NOT EXISTS (
        SELECT 1
        FROM core.workspace AS workspace
        WHERE workspace.id=NEW.workspace_id
          AND workspace.root_path=NEW.canonical_root
          AND workspace.git_repository_path=NEW.canonical_root
          AND workspace.root_fingerprint=NEW.new_root_fingerprint
          AND workspace.binding_version=NEW.new_binding_version
          AND workspace.version=NEW.new_workspace_version
          AND workspace.status='inactive'
          AND workspace.availability='available'
          AND workspace.availability_reason IS NULL
          AND workspace.removed_at IS NULL
    ) THEN
        RAISE EXCEPTION 'workspace root binding history was not consumed by its registry transition'
            USING ERRCODE='55000';
    END IF;
    IF NOT EXISTS (
        SELECT 1
        FROM ops.audit_event AS audit
        WHERE audit.id=NEW.id
          AND audit.workspace_id=NEW.workspace_id
          AND audit.actor_type='SYSTEM'
          AND audit.actor_ref=NEW.controller_instance_id::text
          AND audit.action='workspace.root.rebound'
          AND audit.resource_type='workspace_root_binding'
          AND audit.resource_ref='workspace_root_binding:'||NEW.id::text
          AND audit.idempotency_key='workspace.root.rebind:'||NEW.id::text
          AND audit.correlation=jsonb_build_object('workspace_binding_history_id',NEW.id::text)
          AND audit.payload @> jsonb_build_object(
            'old_root_fingerprint',NEW.old_root_fingerprint,
            'new_root_fingerprint',NEW.new_root_fingerprint,
            'old_binding_version',NEW.old_binding_version,
            'new_binding_version',NEW.new_binding_version,
            'old_workspace_version',NEW.old_workspace_version,
            'new_workspace_version',NEW.new_workspace_version,
            'reason',NEW.reason,
            'audit_outcome','SUCCEEDED',
            'audit_schema_version','audit-event/v1'
          )
          AND audit.occurred_at=NEW.created_at
          AND audit.transaction_id=NEW.transaction_id
    ) THEN
        RAISE EXCEPTION 'workspace root binding history has no exact Audit event'
            USING ERRCODE='55000';
    END IF;
    RETURN NULL;
END
$$;


--
-- Name: enforce_workspace_runtime(); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.enforce_workspace_runtime() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF TG_OP IN ('DELETE','TRUNCATE') THEN
        RAISE EXCEPTION 'workspace runtime ownership cannot be deleted' USING ERRCODE='55000';
    END IF;
    IF NOT EXISTS (
        SELECT 1 FROM core.workspace AS workspace
        WHERE workspace.id=NEW.workspace_id
          AND workspace.root_fingerprint=NEW.root_fingerprint
          AND workspace.binding_version=NEW.binding_version
    ) THEN
        RAISE EXCEPTION 'workspace runtime binding does not match registry identity' USING ERRCODE='23514';
    END IF;
    IF TG_OP='INSERT' THEN
        IF NEW.version<>1 THEN
            RAISE EXCEPTION 'workspace runtime initial version is invalid' USING ERRCODE='55000';
        END IF;
        RETURN NEW;
    END IF;
    IF NEW.version<>OLD.version+1 OR NEW.heartbeat_at<OLD.heartbeat_at THEN
        RAISE EXCEPTION 'workspace runtime version is invalid' USING ERRCODE='40001';
    END IF;
    IF NEW.instance_id<>OLD.instance_id THEN
        RETURN NEW;
    END IF;
    IF ROW(NEW.workspace_id,NEW.grant_generation,NEW.root_fingerprint,
           NEW.binding_version,NEW.started_at)
       IS DISTINCT FROM ROW(OLD.workspace_id,OLD.grant_generation,OLD.root_fingerprint,
           OLD.binding_version,OLD.started_at) THEN
        RAISE EXCEPTION 'workspace runtime binding is immutable for an instance' USING ERRCODE='55000';
    END IF;
    IF NOT (
        (NEW.phase=OLD.phase AND NEW.operation_id IS NOT DISTINCT FROM OLD.operation_id)
        OR (OLD.phase='active' AND NEW.phase='quiescing' AND NEW.operation_id IS NOT NULL)
        OR (OLD.phase='quiescing' AND NEW.phase='quiesced' AND NEW.operation_id=OLD.operation_id)
        OR (OLD.phase IN ('quiescing','quiesced') AND NEW.phase='active' AND NEW.operation_id IS NULL)
        OR (OLD.phase='prepared' AND NEW.phase='verifying' AND NEW.operation_id=OLD.operation_id)
        OR (OLD.phase IN ('prepared','verifying') AND NEW.phase='active' AND NEW.operation_id IS NULL)
        OR (NEW.phase='unavailable' AND NEW.operation_id IS NULL)
    ) THEN
        RAISE EXCEPTION 'workspace runtime phase transition is invalid' USING ERRCODE='55000';
    END IF;
    RETURN NEW;
END
$$;


--
-- Name: enforce_workspace_switch(); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.enforce_workspace_switch() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF TG_OP IN ('DELETE','TRUNCATE') THEN
        RAISE EXCEPTION 'workspace switch history is append-preserving' USING ERRCODE='55000';
    END IF;
    IF TG_OP='INSERT' THEN
        IF NEW.version<>1 OR NEW.result IS NOT NULL THEN
            RAISE EXCEPTION 'workspace switch initial state is invalid' USING ERRCODE='55000';
        END IF;
        RETURN NEW;
    END IF;
    IF OLD.result IS NOT NULL THEN
        RAISE EXCEPTION 'terminal workspace switch is immutable' USING ERRCODE='55000';
    END IF;
    IF NEW.version<>OLD.version+1 OR NEW.updated_at<OLD.updated_at
       OR NEW.heartbeat_at<OLD.heartbeat_at THEN
        RAISE EXCEPTION 'workspace switch version is invalid' USING ERRCODE='40001';
    END IF;
    IF ROW(NEW.controller_instance_id,NEW.idempotency_key,NEW.request_hash,
           NEW.previous_workspace_id,NEW.target_workspace_id,NEW.target_root_fingerprint,
           NEW.target_binding_version,NEW.grant_generation,NEW.recovery_generation,
           NEW.expected_state_version,NEW.deadline_at,NEW.created_at)
       IS DISTINCT FROM
       ROW(OLD.controller_instance_id,OLD.idempotency_key,OLD.request_hash,
           OLD.previous_workspace_id,OLD.target_workspace_id,OLD.target_root_fingerprint,
           OLD.target_binding_version,OLD.grant_generation,OLD.recovery_generation,
           OLD.expected_state_version,OLD.deadline_at,OLD.created_at) THEN
        RAISE EXCEPTION 'workspace switch binding is immutable' USING ERRCODE='55000';
    END IF;
    IF NEW.result IS NULL
       AND NEW.lease_owner_id IS DISTINCT FROM OLD.lease_owner_id
       AND OLD.lease_expires_at>NEW.updated_at THEN
        RAISE EXCEPTION 'workspace switch lease is held' USING ERRCODE='55P03';
    END IF;
    IF NOT (
        NEW.phase=OLD.phase
        OR (OLD.phase='validating' AND NEW.phase='quiescing')
        OR (OLD.phase='quiescing' AND NEW.phase='revoking')
        OR (OLD.phase='revoking' AND NEW.phase='applying_grant')
        OR (OLD.phase='applying_grant' AND NEW.phase='preparing')
        OR (OLD.phase='preparing' AND NEW.phase='verifying')
        OR (OLD.phase='verifying' AND NEW.phase='committing')
        OR (OLD.phase='committing' AND NEW.phase='activating')
        OR (OLD.phase IN ('revoking','applying_grant','preparing','verifying','committing','activating')
            AND NEW.phase='rolling_back')
        OR (OLD.phase='rolling_back' AND NEW.phase='recovering')
    ) THEN
        RAISE EXCEPTION 'workspace switch phase transition is invalid' USING ERRCODE='55000';
    END IF;
    IF NEW.result IS NOT NULL AND NOT (
        (NEW.result='succeeded' AND NEW.phase='activating')
        OR (NEW.result='rejected' AND NEW.phase='validating')
        OR (NEW.result='cancelled' AND NEW.phase IN ('validating','quiescing'))
        OR (NEW.result IN ('rolled_back','failed') AND NEW.phase='recovering')
    ) THEN
        RAISE EXCEPTION 'workspace switch terminal transition is invalid' USING ERRCODE='55000';
    END IF;
    RETURN NEW;
END
$$;


--
-- Name: enqueue_health_affected_index_failure(); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.enqueue_health_affected_index_failure() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    event_key_value text;
    event_id_value uuid;
BEGIN
    event_key_value := 'health-affected-change:v1:index:' || NEW.id::text || ':' || NEW.version::text;
    event_id_value := md5(event_key_value)::uuid;
    INSERT INTO ops.health_affected_change_outbox (
        id, workspace_id, schema_version, event_version, event_type, event_key,
        source_kind, source_key, source_hash, aggregate_type, aggregate_id,
        aggregate_sub_id, aggregate_version, change_status, change_code,
        occurred_at, available_at, attempt_count, last_error_code,
        bound_scan_id, bound_workflow_run_id, published_at, poisoned_at,
        manual_recovery_required, version, created_at, updated_at
    ) VALUES (
        event_id_value, NEW.workspace_id, 1, 1, 'health.affected.index_failed', event_key_value,
        'INDEX_VERSION', NEW.id::text, NULL, 'INDEX_VERSION', NEW.id,
        NULL, NEW.version, NEW.status, NEW.failure_code,
        NEW.updated_at, NEW.updated_at, 0, NULL,
        NULL, NULL, NULL, NULL, false, 1, NEW.updated_at, NEW.updated_at
    ) ON CONFLICT (event_key) DO NOTHING;
    RETURN NEW;
END;
$$;


--
-- Name: enqueue_health_affected_knowledge_change(); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.enqueue_health_affected_knowledge_change() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    event_key_value text;
    event_id_value uuid;
BEGIN
    event_key_value := 'health-affected-change:v1:knowledge:' || NEW.workspace_id::text || ':' || NEW.idempotency_key;
    event_id_value := md5(event_key_value)::uuid;
    INSERT INTO ops.health_affected_change_outbox (
        id, workspace_id, schema_version, event_version, event_type, event_key,
        source_kind, source_key, source_hash, aggregate_type, aggregate_id,
        aggregate_sub_id, aggregate_version, change_status, change_code,
        occurred_at, available_at, attempt_count, last_error_code,
        bound_scan_id, bound_workflow_run_id, published_at, poisoned_at,
        manual_recovery_required, version, created_at, updated_at
    ) VALUES (
        event_id_value, NEW.workspace_id, 1, 1, 'health.affected.knowledge_changed', event_key_value,
        'KNOWLEDGE_COMMAND_RECEIPT', NEW.idempotency_key, NEW.request_hash, NEW.aggregate_type, NEW.aggregate_id,
        NULL, NEW.aggregate_version, NEW.command_type, NULL,
        NEW.created_at, NEW.created_at, 0, NULL,
        NULL, NULL, NULL, NULL, false, 1, NEW.created_at, NEW.created_at
    ) ON CONFLICT (event_key) DO NOTHING;
    RETURN NEW;
END;
$$;


