--
-- Name: knowledge_command_receipt; Type: TABLE; Schema: core; Owner: -
--

CREATE TABLE core.knowledge_command_receipt (
    workspace_id uuid NOT NULL,
    idempotency_key text NOT NULL,
    request_hash text NOT NULL,
    command_type text NOT NULL,
    aggregate_type text NOT NULL,
    aggregate_id uuid NOT NULL,
    aggregate_version bigint NOT NULL,
    created_at timestamp with time zone NOT NULL,
    CONSTRAINT knowledge_command_receipt_aggregate_type_check CHECK ((aggregate_type = ANY (ARRAY['TOPIC'::text, 'CLAIM'::text, 'RELATION'::text, 'CONFLICT'::text]))),
    CONSTRAINT knowledge_command_receipt_aggregate_version_check CHECK ((aggregate_version > 0)),
    CONSTRAINT knowledge_command_receipt_command_type_check CHECK ((command_type = ANY (ARRAY['topic.create'::text, 'claim.suggest'::text, 'claim.confirm'::text, 'claim.transition'::text, 'relation.suggest'::text, 'relation.confirm'::text, 'relation.transition'::text, 'conflict.open'::text, 'conflict.transition'::text]))),
    CONSTRAINT knowledge_command_receipt_idempotency_key_check CHECK (((btrim(idempotency_key) <> ''::text) AND (octet_length(idempotency_key) <= 128))),
    CONSTRAINT knowledge_command_receipt_request_hash_check CHECK ((request_hash ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT knowledge_command_receipt_type_binding CHECK ((((command_type = 'topic.create'::text) AND (aggregate_type = 'TOPIC'::text)) OR ((command_type = ANY (ARRAY['claim.suggest'::text, 'claim.confirm'::text, 'claim.transition'::text])) AND (aggregate_type = 'CLAIM'::text)) OR ((command_type = ANY (ARRAY['relation.suggest'::text, 'relation.confirm'::text, 'relation.transition'::text])) AND (aggregate_type = 'RELATION'::text)) OR ((command_type = ANY (ARRAY['conflict.open'::text, 'conflict.transition'::text])) AND (aggregate_type = 'CONFLICT'::text))))
);


--
-- Name: enqueue_knowledge_command_timeline(core.knowledge_command_receipt); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.enqueue_knowledge_command_timeline(receipt core.knowledge_command_receipt) RETURNS void
    LANGUAGE plpgsql
    AS $$
DECLARE
    projected_event_type text;
    projected_summary text;
    aggregate_status text;
    projected_correlation jsonb := '{}'::jsonb;
    relation_confirmation_ref text;
    related_proposal_id uuid;
    related_approval_id uuid;
BEGIN
    CASE receipt.command_type
        WHEN 'topic.create' THEN
            projected_event_type := 'VERSION_PUBLISHED';
            projected_summary := 'Topic version published';
        WHEN 'claim.confirm' THEN
            projected_event_type := 'VERSION_PUBLISHED';
            projected_summary := 'Claim version published';
        WHEN 'claim.transition' THEN
            SELECT status INTO aggregate_status
              FROM core.claim
             WHERE workspace_id = receipt.workspace_id AND id = receipt.aggregate_id;
            IF aggregate_status = 'CONFIRMED' THEN
                projected_event_type := 'VERSION_PUBLISHED';
            ELSIF aggregate_status IN ('SUPERSEDED', 'DEPRECATED', 'INVALID') THEN
                projected_event_type := 'VERSION_SUPERSEDED';
            ELSE
                projected_event_type := 'CORRECTIVE_EVENT';
            END IF;
            projected_summary := 'Claim status changed to ' || aggregate_status;
        WHEN 'relation.confirm' THEN
            projected_event_type := 'RELATION_CONFIRMED';
            projected_summary := 'Relation confirmed';
        WHEN 'relation.transition' THEN
            SELECT status INTO aggregate_status
              FROM core.relation
             WHERE workspace_id = receipt.workspace_id AND id = receipt.aggregate_id;
            IF aggregate_status = 'CONFIRMED' THEN
                projected_event_type := 'RELATION_CONFIRMED';
            ELSIF aggregate_status = 'DEPRECATED' THEN
                projected_event_type := 'RELATION_DEPRECATED';
            ELSE
                projected_event_type := 'CORRECTIVE_EVENT';
            END IF;
            projected_summary := 'Relation status changed to ' || aggregate_status;
        WHEN 'conflict.open' THEN
            projected_event_type := 'CONFLICT_OPENED';
            projected_summary := 'Conflict opened';
        WHEN 'conflict.transition' THEN
            SELECT status INTO aggregate_status
              FROM core.conflict
             WHERE workspace_id = receipt.workspace_id AND id = receipt.aggregate_id;
            IF aggregate_status IN ('RESOLVED', 'ACCEPTED_DIVERGENCE') THEN
                projected_event_type := 'CONFLICT_RESOLVED';
            ELSE
                projected_event_type := 'CONFLICT_TRANSITIONED';
            END IF;
            projected_summary := 'Conflict status changed to ' || aggregate_status;
        ELSE
            RETURN;
    END CASE;

    IF receipt.aggregate_type = 'RELATION' THEN
        SELECT relation.confirmation_ref
          INTO relation_confirmation_ref
          FROM core.relation relation
         WHERE relation.workspace_id = receipt.workspace_id
           AND relation.id = receipt.aggregate_id;
        IF relation_confirmation_ref IS NOT NULL THEN
            SELECT approval.proposal_id, approval.id
              INTO related_proposal_id, related_approval_id
              FROM change_control.approval approval
             WHERE approval.id::text = relation_confirmation_ref;
            IF related_approval_id IS NOT NULL THEN
                projected_correlation := jsonb_build_object(
                    'proposal_id', related_proposal_id::text,
                    'approval_id', related_approval_id::text
                );
            END IF;
        END IF;
    END IF;

    PERFORM ops.enqueue_timeline_projection(
        receipt.workspace_id,
        projected_event_type,
        receipt.aggregate_type,
        receipt.aggregate_id,
        'knowledge-command:' || receipt.command_type || ':' || receipt.aggregate_id::text || ':v' || receipt.aggregate_version::text,
        lower(receipt.aggregate_type) || ':' || receipt.aggregate_id::text,
        receipt.aggregate_version,
        projected_summary,
        projected_correlation,
        receipt.created_at
    );
END;
$$;


--
-- Name: enqueue_timeline_projection(uuid, text, text, uuid, text, text, bigint, text, jsonb, timestamp with time zone); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.enqueue_timeline_projection(projection_workspace_id uuid, projection_event_type text, projection_aggregate_type text, projection_aggregate_id uuid, projection_source_event_ref text, projection_source_ref text, projection_event_version bigint, projection_summary text, projection_correlation jsonb, projection_occurred_at timestamp with time zone) RETURNS void
    LANGUAGE plpgsql
    AS $$
DECLARE
    stable_event_id uuid;
    stable_event_created_at timestamptz;
    inserted_rows bigint;
BEGIN
    IF projection_event_version < 1 OR projection_event_version > 2147483647 THEN
        RAISE EXCEPTION 'timeline projection event version is outside integer range'
            USING ERRCODE = '23514';
    END IF;
    SELECT id, created_at INTO stable_event_id, stable_event_created_at
      FROM ops.knowledge_event
     WHERE workspace_id = projection_workspace_id
       AND source_event_ref = projection_source_event_ref;
    stable_event_id := COALESCE(stable_event_id, gen_random_uuid());
    stable_event_created_at := COALESCE(
        stable_event_created_at,
        GREATEST(projection_occurred_at, CURRENT_TIMESTAMP)
    );

    INSERT INTO ops.timeline_projection_outbox(
        event_id,workspace_id,event_type,aggregate_type,aggregate_id,source_event_ref,source_ref,
        event_version,summary,correlation,occurred_at,status,created_at,updated_at
    ) VALUES(
        stable_event_id,projection_workspace_id,projection_event_type,projection_aggregate_type,
        projection_aggregate_id,projection_source_event_ref,projection_source_ref,
        projection_event_version::integer,projection_summary,COALESCE(projection_correlation, '{}'::jsonb),
        projection_occurred_at,'PENDING',stable_event_created_at,
        GREATEST(stable_event_created_at,CURRENT_TIMESTAMP)
    )
    ON CONFLICT (workspace_id, source_event_ref) DO NOTHING;
    GET DIAGNOSTICS inserted_rows = ROW_COUNT;

    IF inserted_rows = 0 AND NOT EXISTS (
        SELECT 1
          FROM ops.timeline_projection_outbox queued
         WHERE queued.workspace_id = projection_workspace_id
           AND queued.source_event_ref = projection_source_event_ref
           AND queued.event_type = projection_event_type
           AND queued.aggregate_type = projection_aggregate_type
           AND queued.aggregate_id IS NOT DISTINCT FROM projection_aggregate_id
           AND queued.source_ref = projection_source_ref
           AND queued.event_version = projection_event_version
           AND queued.summary = projection_summary
           AND queued.correlation = COALESCE(projection_correlation, '{}'::jsonb)
           AND queued.occurred_at = projection_occurred_at
    ) THEN
        RAISE EXCEPTION 'timeline projection source is bound to different content'
            USING ERRCODE = '23514';
    END IF;
END;
$$;


--
-- Name: enqueue_timeline_projection_v2(uuid, text, text, uuid, text, text, bigint, text, jsonb, text, uuid, jsonb, timestamp with time zone); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.enqueue_timeline_projection_v2(projection_workspace_id uuid, projection_event_type text, projection_aggregate_type text, projection_aggregate_id uuid, projection_source_event_ref text, projection_source_ref text, projection_event_version bigint, projection_summary text, projection_correlation jsonb, projection_operator_type text, projection_operator_id uuid, projection_owner_binding jsonb, projection_occurred_at timestamp with time zone) RETURNS void
    LANGUAGE plpgsql
    AS $$
DECLARE
    stable_event_id uuid;
    stable_event_created_at timestamptz;
    inserted_rows bigint;
BEGIN
    IF projection_event_version < 1 OR projection_event_version > 2147483647 THEN
        RAISE EXCEPTION 'timeline projection event version is outside integer range'
            USING ERRCODE = '23514';
    END IF;
    IF projection_operator_type IS NULL
       OR projection_operator_type NOT IN ('USER','API_TOKEN','SYSTEM','UNKNOWN')
       OR (projection_operator_type IN ('SYSTEM','UNKNOWN') AND projection_operator_id IS NOT NULL)
       OR NOT ops.valid_timeline_owner_binding(
           projection_event_type,projection_aggregate_type,projection_aggregate_id,projection_owner_binding
       ) THEN
        RAISE EXCEPTION 'timeline v2 projection binding is invalid'
            USING ERRCODE = '23514';
    END IF;

    SELECT id,created_at
      INTO stable_event_id,stable_event_created_at
      FROM ops.knowledge_event
     WHERE workspace_id=projection_workspace_id
       AND source_event_ref=projection_source_event_ref;
    stable_event_id := COALESCE(stable_event_id,gen_random_uuid());
    stable_event_created_at := COALESCE(
        stable_event_created_at,GREATEST(projection_occurred_at,CURRENT_TIMESTAMP)
    );

    INSERT INTO ops.timeline_projection_outbox(
        event_id,workspace_id,event_type,aggregate_type,aggregate_id,source_event_ref,source_ref,
        event_version,schema_version,summary,correlation,operator_type,operator_id,owner_binding,
        occurred_at,status,created_at,updated_at
    ) VALUES(
        stable_event_id,projection_workspace_id,projection_event_type,projection_aggregate_type,
        projection_aggregate_id,projection_source_event_ref,projection_source_ref,
        projection_event_version::integer,'knowledge-event/v2',projection_summary,
        COALESCE(projection_correlation,'{}'::jsonb),projection_operator_type,
        projection_operator_id,projection_owner_binding,projection_occurred_at,'PENDING',
        stable_event_created_at,GREATEST(stable_event_created_at,CURRENT_TIMESTAMP)
    )
    ON CONFLICT (workspace_id,source_event_ref) DO NOTHING;
    GET DIAGNOSTICS inserted_rows = ROW_COUNT;

    IF inserted_rows = 0 AND NOT EXISTS (
        SELECT 1
          FROM ops.timeline_projection_outbox AS queued
         WHERE queued.workspace_id=projection_workspace_id
           AND queued.source_event_ref=projection_source_event_ref
           AND queued.event_type=projection_event_type
           AND queued.aggregate_type=projection_aggregate_type
           AND queued.aggregate_id IS NOT DISTINCT FROM projection_aggregate_id
           AND queued.source_ref=projection_source_ref
           AND queued.event_version=projection_event_version
           AND queued.schema_version='knowledge-event/v2'
           AND queued.summary=projection_summary
           AND queued.correlation=COALESCE(projection_correlation,'{}'::jsonb)
           AND queued.operator_type=projection_operator_type
           AND queued.operator_id IS NOT DISTINCT FROM projection_operator_id
           AND queued.owner_binding=projection_owner_binding
           AND queued.occurred_at=projection_occurred_at
    ) THEN
        RAISE EXCEPTION 'timeline projection source is bound to different content'
            USING ERRCODE = '23514';
    END IF;
END;
$$;


--
-- Name: guard_timeline_projection_outbox_mutation(); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.guard_timeline_projection_outbox_mutation() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF TG_OP = 'DELETE' THEN
        RAISE EXCEPTION 'Timeline projection outbox rows cannot be deleted'
            USING ERRCODE = '55000';
    END IF;
    IF OLD.status <> 'PENDING'
       OR NEW.status NOT IN ('PROJECTED', 'POISONED')
       OR NEW.version <> OLD.version + 1 THEN
        RAISE EXCEPTION 'invalid Timeline projection outbox state transition'
            USING ERRCODE = '55000';
    END IF;
    IF ROW(
        NEW.id, NEW.event_id, NEW.workspace_id, NEW.event_type,
        NEW.aggregate_type, NEW.aggregate_id, NEW.source_event_ref,
        NEW.source_ref, NEW.event_version, NEW.schema_version, NEW.summary,
        NEW.correlation, NEW.operator_type, NEW.operator_id, NEW.owner_binding,
        NEW.occurred_at, NEW.created_at
    ) IS DISTINCT FROM ROW(
        OLD.id, OLD.event_id, OLD.workspace_id, OLD.event_type,
        OLD.aggregate_type, OLD.aggregate_id, OLD.source_event_ref,
        OLD.source_ref, OLD.event_version, OLD.schema_version, OLD.summary,
        OLD.correlation, OLD.operator_type, OLD.operator_id, OLD.owner_binding,
        OLD.occurred_at, OLD.created_at
    ) THEN
        RAISE EXCEPTION 'Timeline projection outbox source binding is immutable'
            USING ERRCODE = '55000';
    END IF;
    RETURN NEW;
END;
$$;


--
-- Name: health_validate_object_binding(uuid, text, uuid); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.health_validate_object_binding(workspace_value uuid, type_value text, id_value uuid) RETURNS boolean
    LANGUAGE plpgsql
    AS $$
BEGIN
    CASE type_value
        WHEN 'TOPIC' THEN RETURN EXISTS (SELECT 1 FROM core.topic WHERE id=id_value AND workspace_id=workspace_value);
        WHEN 'CLAIM' THEN RETURN EXISTS (SELECT 1 FROM core.claim WHERE id=id_value AND workspace_id=workspace_value);
        WHEN 'RELATION' THEN RETURN EXISTS (SELECT 1 FROM core.relation WHERE id=id_value AND workspace_id=workspace_value);
        WHEN 'CONFLICT' THEN RETURN EXISTS (SELECT 1 FROM core.conflict WHERE id=id_value AND workspace_id=workspace_value);
        WHEN 'SOURCE_VERSION' THEN RETURN EXISTS (
            SELECT 1 FROM core.source_version sv JOIN core.source s ON s.id=sv.source_id
            WHERE sv.id=id_value AND s.workspace_id=workspace_value
        );
        WHEN 'INDEX_VERSION' THEN RETURN EXISTS (
            SELECT 1 FROM retrieval.index_version WHERE id=id_value AND workspace_id=workspace_value
        );
        ELSE RETURN false;
    END CASE;
END;
$$;


--
-- Name: managed_ollama_operations; Type: TABLE; Schema: ops; Owner: -
--

CREATE TABLE ops.managed_ollama_operations (
    operation_id uuid NOT NULL,
    kind text NOT NULL,
    idempotency_key text NOT NULL,
    request_hash text NOT NULL,
    target_revision bigint,
    rollout_id uuid,
    requirement_hash text NOT NULL,
    required_models jsonb DEFAULT '[]'::jsonb NOT NULL,
    phase text DEFAULT 'queued'::text NOT NULL,
    claim_owner_id uuid,
    claim_owner_epoch bigint,
    claim_expires_at timestamp with time zone,
    version bigint DEFAULT 1 NOT NULL,
    completed_models jsonb DEFAULT '[]'::jsonb NOT NULL,
    resolved_models jsonb DEFAULT '[]'::jsonb NOT NULL,
    completed_bytes bigint DEFAULT 0 NOT NULL,
    total_bytes bigint,
    progress_known boolean DEFAULT false NOT NULL,
    attempt_no integer DEFAULT 0 NOT NULL,
    last_progress_at timestamp with time zone,
    error_code text,
    error_retryable boolean DEFAULT false NOT NULL,
    created_at timestamp with time zone DEFAULT clock_timestamp() NOT NULL,
    updated_at timestamp with time zone DEFAULT clock_timestamp() NOT NULL,
    terminal_at timestamp with time zone,
    CONSTRAINT ops_managed_ollama_operation_claim_shape CHECK ((((claim_owner_id IS NULL) AND (claim_owner_epoch IS NULL) AND (claim_expires_at IS NULL)) OR ((claim_owner_id IS NOT NULL) AND (claim_owner_epoch > 0) AND (claim_expires_at IS NOT NULL)))),
    CONSTRAINT ops_managed_ollama_operation_error CHECK ((((error_code IS NULL) AND (error_retryable = false)) OR ((error_code IS NOT NULL) AND (error_code ~ '^[A-Z0-9_]{1,128}$'::text)))),
    CONSTRAINT ops_managed_ollama_operation_hash CHECK (((request_hash ~ '^[0-9a-f]{64}$'::text) AND (requirement_hash ~ '^[0-9a-f]{64}$'::text))),
    CONSTRAINT ops_managed_ollama_operation_idempotency CHECK (((idempotency_key = btrim(idempotency_key)) AND ((octet_length(idempotency_key) >= 1) AND (octet_length(idempotency_key) <= 256)) AND (idempotency_key !~ '[[:cntrl:]]'::text))),
    CONSTRAINT ops_managed_ollama_operation_kind CHECK ((kind = ANY (ARRAY['activation'::text, 'active_recovery'::text, 'test'::text]))),
    CONSTRAINT ops_managed_ollama_operation_models CHECK (((jsonb_typeof(completed_models) = 'array'::text) AND (NOT jsonb_path_exists(completed_models, '$[*]?(@.type() != "string")'::jsonpath)) AND (NOT jsonb_path_exists(completed_models, '$[*]?(@ == "" || @.size() > 128)'::jsonpath)))),
    CONSTRAINT ops_managed_ollama_operation_phase CHECK ((phase = ANY (ARRAY['queued'::text, 'starting'::text, 'checking'::text, 'pulling'::text, 'verifying'::text, 'ready'::text, 'probing'::text, 'succeeded'::text, 'failed'::text, 'superseded'::text]))),
    CONSTRAINT ops_managed_ollama_operation_probe_shape CHECK (((phase <> 'probing'::text) OR ((kind = 'test'::text) AND (claim_owner_id IS NOT NULL) AND (claim_owner_epoch > 0) AND (claim_expires_at IS NOT NULL)))),
    CONSTRAINT ops_managed_ollama_operation_progress CHECK (((completed_bytes >= 0) AND ((total_bytes IS NULL) OR (total_bytes >= completed_bytes)))),
    CONSTRAINT ops_managed_ollama_operation_required_models CHECK (((jsonb_typeof(required_models) = 'array'::text) AND (jsonb_array_length(required_models) > 0) AND (NOT jsonb_path_exists(required_models, '$[*]?(@.type() != "string")'::jsonpath)) AND (NOT jsonb_path_exists(required_models, '$[*]?(@ == "" || @.size() > 128)'::jsonpath)))),
    CONSTRAINT ops_managed_ollama_operation_resolved_models CHECK (((jsonb_typeof(resolved_models) = 'array'::text) AND (NOT jsonb_path_exists(resolved_models, '$[*]?((@."model".type() != "string" || @."digest".type() != "string") || @."bytes".type() != "number")'::jsonpath)))),
    CONSTRAINT ops_managed_ollama_operation_terminal CHECK (((phase = ANY (ARRAY['succeeded'::text, 'failed'::text, 'superseded'::text])) = (terminal_at IS NOT NULL))),
    CONSTRAINT ops_managed_ollama_operation_unclaimed_shape CHECK (((phase <> ALL (ARRAY['ready'::text, 'succeeded'::text, 'failed'::text, 'superseded'::text])) OR (claim_owner_id IS NULL))),
    CONSTRAINT ops_managed_ollama_operation_version CHECK (((version > 0) AND (attempt_no >= 0)))
);


--
-- Name: managed_ollama_begin_pull_attempt(uuid, uuid, bigint, bigint, interval); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.managed_ollama_begin_pull_attempt(p_operation_id uuid, p_owner_id uuid, p_owner_epoch bigint, p_expected_version bigint, p_lease_duration interval) RETURNS SETOF ops.managed_ollama_operations
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'ops'
    AS $$
DECLARE
    result ops.managed_ollama_operations;
BEGIN
    UPDATE ops.managed_ollama_operations
    SET attempt_no=CASE WHEN attempt_no>=3 THEN attempt_no ELSE attempt_no+1 END,
        phase=CASE WHEN attempt_no>=3 THEN 'failed' ELSE phase END,
        error_code=CASE WHEN attempt_no>=3 THEN 'LOCAL_MODEL_RUNTIME_PULL_ATTEMPTS_EXHAUSTED' ELSE NULL END,
        error_retryable=false,
        terminal_at=CASE WHEN attempt_no>=3 THEN clock_timestamp() ELSE NULL END,
        claim_owner_id=CASE WHEN attempt_no>=3 THEN NULL ELSE claim_owner_id END,
        claim_owner_epoch=CASE WHEN attempt_no>=3 THEN NULL ELSE claim_owner_epoch END,
        claim_expires_at=CASE WHEN attempt_no>=3 THEN NULL ELSE clock_timestamp()+p_lease_duration END,
        version=version+1, updated_at=clock_timestamp()
    WHERE operation_id=p_operation_id AND claim_owner_id=p_owner_id AND claim_owner_epoch=p_owner_epoch
      AND version=p_expected_version AND terminal_at IS NULL
      AND phase IN ('starting','checking','pulling')
      AND (kind<>'active_recovery' OR EXISTS (
          SELECT 1 FROM ops.model_settings_state state
          WHERE state.singleton=true AND state.active_revision=ops.managed_ollama_operations.target_revision
      ))
      AND created_at+interval '6 hours'>clock_timestamp()
      AND claim_expires_at>clock_timestamp()
      AND p_lease_duration>interval '0' AND p_lease_duration<=interval '1 hour'
      AND EXISTS (
          SELECT 1 FROM ops.managed_ollama_runtime runtime
          WHERE runtime.singleton=true AND runtime.owner_id=p_owner_id
            AND runtime.owner_epoch=p_owner_epoch AND runtime.lease_expires_at>clock_timestamp()
      )
    RETURNING * INTO result;
    IF NOT FOUND THEN
        RETURN;
    END IF;
    IF result.phase='failed' THEN
        UPDATE ops.managed_ollama_holds
        SET released_at=clock_timestamp(), version=version+1, updated_at=clock_timestamp()
        WHERE operation_id=result.operation_id AND released_at IS NULL;
        IF NOT FOUND THEN
            RAISE EXCEPTION 'managed Ollama exhausted operation hold is missing' USING ERRCODE='55000';
        END IF;
    END IF;
    RETURN NEXT result;
END
$$;


--
-- Name: managed_ollama_runtime; Type: TABLE; Schema: ops; Owner: -
--

CREATE TABLE ops.managed_ollama_runtime (
    singleton boolean DEFAULT true NOT NULL,
    mode text DEFAULT 'managed'::text NOT NULL,
    owner_id uuid,
    owner_epoch bigint DEFAULT 0 NOT NULL,
    heartbeat_at timestamp with time zone,
    lease_expires_at timestamp with time zone,
    requirement_version bigint DEFAULT 0 NOT NULL,
    requirement_hash text DEFAULT ''::text NOT NULL,
    required_models jsonb DEFAULT '[]'::jsonb NOT NULL,
    observed_phase text DEFAULT 'stopped'::text NOT NULL,
    ready_requirement_hash text DEFAULT ''::text NOT NULL,
    child_epoch bigint DEFAULT 0 NOT NULL,
    last_error_code text,
    last_error_retryable boolean DEFAULT false NOT NULL,
    version bigint DEFAULT 1 NOT NULL,
    updated_at timestamp with time zone DEFAULT clock_timestamp() NOT NULL,
    CONSTRAINT ops_managed_ollama_runtime_hash CHECK (((requirement_hash = ''::text) OR (requirement_hash ~ '^[0-9a-f]{64}$'::text))),
    CONSTRAINT ops_managed_ollama_runtime_hash_empty_shape CHECK ((((jsonb_array_length(required_models) = 0) AND (requirement_hash = ''::text)) OR ((jsonb_array_length(required_models) > 0) AND (requirement_hash <> ''::text)))),
    CONSTRAINT ops_managed_ollama_runtime_mode CHECK ((mode = ANY (ARRAY['managed'::text, 'external-static'::text]))),
    CONSTRAINT ops_managed_ollama_runtime_models CHECK (((jsonb_typeof(required_models) = 'array'::text) AND (NOT jsonb_path_exists(required_models, '$[*]?(@.type() != "string")'::jsonpath)) AND (NOT jsonb_path_exists(required_models, '$[*]?(@ == "" || @.size() > 128)'::jsonpath)))),
    CONSTRAINT ops_managed_ollama_runtime_owner_shape CHECK (((((owner_id IS NULL) AND (heartbeat_at IS NULL) AND (lease_expires_at IS NULL) AND (owner_epoch = 0)) OR ((owner_id IS NOT NULL) AND (heartbeat_at IS NOT NULL) AND (lease_expires_at IS NOT NULL) AND (owner_epoch > 0) AND (lease_expires_at >= heartbeat_at))) IS TRUE)),
    CONSTRAINT ops_managed_ollama_runtime_phase CHECK ((observed_phase = ANY (ARRAY['stopped'::text, 'starting'::text, 'pulling'::text, 'checking'::text, 'ready'::text, 'stopping'::text, 'failed'::text]))),
    CONSTRAINT ops_managed_ollama_runtime_phase_shape CHECK (((((observed_phase = ANY (ARRAY['stopped'::text, 'ready'::text])) AND (last_error_code IS NULL) AND (last_error_retryable = false)) OR ((observed_phase = ANY (ARRAY['starting'::text, 'pulling'::text, 'checking'::text, 'stopping'::text])) AND (last_error_code IS NULL) AND (last_error_retryable = false)) OR ((observed_phase = 'failed'::text) AND (last_error_code IS NOT NULL))) IS TRUE)),
    CONSTRAINT ops_managed_ollama_runtime_ready_hash CHECK (((ready_requirement_hash = ''::text) OR (ready_requirement_hash ~ '^[0-9a-f]{64}$'::text))),
    CONSTRAINT ops_managed_ollama_runtime_singleton CHECK (singleton),
    CONSTRAINT ops_managed_ollama_runtime_version CHECK (((version > 0) AND (requirement_version >= 0) AND (child_epoch >= 0)))
);


--
-- Name: managed_ollama_claim_manager(uuid, interval, interval); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.managed_ollama_claim_manager(p_owner_id uuid, p_lease_duration interval, p_stale_after interval) RETURNS SETOF ops.managed_ollama_runtime
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'ops'
    AS $$
BEGIN
    RETURN QUERY
    UPDATE ops.managed_ollama_runtime
    SET owner_id=p_owner_id,
        owner_epoch=CASE WHEN owner_id=p_owner_id THEN owner_epoch ELSE owner_epoch+1 END,
        heartbeat_at=clock_timestamp(), lease_expires_at=clock_timestamp()+p_lease_duration,
        version=version+1, updated_at=clock_timestamp()
    WHERE singleton=true
      AND p_lease_duration>interval '0' AND p_lease_duration<=interval '10 minutes'
      AND p_stale_after>=p_lease_duration AND p_stale_after<=interval '10 minutes'
      AND (owner_id IS NULL OR owner_id=p_owner_id
      OR lease_expires_at<=clock_timestamp()
      OR heartbeat_at<=clock_timestamp()-p_stale_after)
    RETURNING *;
END
$$;


--
-- Name: managed_ollama_claim_operation(uuid, text, text, text, bigint, uuid, text, jsonb, uuid, bigint, interval); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.managed_ollama_claim_operation(p_operation_id uuid, p_kind text, p_idempotency_key text, p_request_hash text, p_target_revision bigint, p_rollout_id uuid, p_requirement_hash text, p_required_models jsonb, p_owner_id uuid, p_owner_epoch bigint, p_lease_duration interval) RETURNS SETOF ops.managed_ollama_operations
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'ops'
    AS $$
BEGIN
    RETURN QUERY
    UPDATE ops.managed_ollama_operations
    SET claim_owner_id=p_owner_id, claim_owner_epoch=p_owner_epoch,
        claim_expires_at=clock_timestamp()+p_lease_duration, version=version+1,
        updated_at=clock_timestamp()
    WHERE operation_id=p_operation_id AND kind=p_kind AND idempotency_key=p_idempotency_key
      AND request_hash=p_request_hash AND requirement_hash=p_requirement_hash
      AND required_models=p_required_models
      AND target_revision IS NOT DISTINCT FROM p_target_revision
      AND rollout_id IS NOT DISTINCT FROM p_rollout_id
      AND p_lease_duration>interval '0' AND p_lease_duration<=interval '1 hour'
      AND created_at+interval '6 hours'>clock_timestamp()
      AND phase IN ('queued','starting','checking','pulling','verifying')
      AND (kind<>'active_recovery' OR EXISTS (
          SELECT 1 FROM ops.model_settings_state state
          WHERE state.singleton=true AND state.active_revision=ops.managed_ollama_operations.target_revision
      ))
      AND EXISTS (
          SELECT 1 FROM ops.managed_ollama_runtime runtime
          WHERE runtime.singleton=true AND runtime.owner_id=p_owner_id
            AND runtime.owner_epoch=p_owner_epoch AND runtime.lease_expires_at>clock_timestamp()
      )
      AND (claim_owner_id IS NULL
           OR (claim_owner_id=p_owner_id AND claim_owner_epoch=p_owner_epoch)
           OR claim_expires_at<=clock_timestamp())
    RETURNING *;
END
$$;


--
-- Name: managed_ollama_compare_runtime_phase(uuid, bigint, bigint, text, text, text, text, bigint, text, boolean, bigint); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.managed_ollama_compare_runtime_phase(p_owner_id uuid, p_owner_epoch bigint, p_expected_version bigint, p_expected_phase text, p_next_phase text, p_requirement_hash text, p_ready_requirement_hash text, p_child_epoch bigint, p_error_code text, p_error_retryable boolean, p_expected_settings_state_version bigint) RETURNS SETOF ops.managed_ollama_runtime
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'ops'
    AS $$
BEGIN
    RETURN QUERY
    UPDATE ops.managed_ollama_runtime
    SET observed_phase=p_next_phase, requirement_hash=p_requirement_hash,
        ready_requirement_hash=p_ready_requirement_hash, child_epoch=p_child_epoch,
        last_error_code=p_error_code, last_error_retryable=p_error_retryable,
        version=version+1, updated_at=clock_timestamp()
    WHERE singleton=true AND owner_id=p_owner_id AND owner_epoch=p_owner_epoch AND version=p_expected_version
      AND observed_phase=p_expected_phase AND lease_expires_at>clock_timestamp()
      AND (SELECT version FROM ops.model_settings_state WHERE singleton=true)=p_expected_settings_state_version
    RETURNING *;
END
$$;


--
-- Name: managed_ollama_complete_operation(uuid, uuid, bigint, bigint, text, text, boolean, jsonb, bigint, bigint); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.managed_ollama_complete_operation(p_operation_id uuid, p_owner_id uuid, p_owner_epoch bigint, p_expected_version bigint, p_phase text, p_error_code text, p_error_retryable boolean, p_completed_models jsonb, p_completed_bytes bigint, p_total_bytes bigint) RETURNS SETOF ops.managed_ollama_operations
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'ops'
    AS $$
DECLARE
    result ops.managed_ollama_operations;
BEGIN
    UPDATE ops.managed_ollama_operations
    SET phase=CASE WHEN created_at+interval '6 hours'<=clock_timestamp()
                   THEN 'failed'
                   WHEN kind='active_recovery' AND p_phase='ready' THEN 'succeeded'
                   ELSE p_phase END,
        error_code=CASE WHEN created_at+interval '6 hours'<=clock_timestamp()
                        THEN 'LOCAL_MODEL_RUNTIME_PREPARATION_TIMEOUT' ELSE p_error_code END,
        error_retryable=CASE WHEN created_at+interval '6 hours'<=clock_timestamp()
                             THEN false ELSE p_error_retryable END,
        completed_models=p_completed_models, completed_bytes=p_completed_bytes, total_bytes=p_total_bytes,
        terminal_at=CASE WHEN p_phase='ready' AND kind<>'active_recovery'
                              AND created_at+interval '6 hours'>clock_timestamp()
                         THEN NULL ELSE clock_timestamp() END,
        claim_owner_id=NULL, claim_owner_epoch=NULL, claim_expires_at=NULL,
        version=version+1, updated_at=clock_timestamp()
    WHERE operation_id=p_operation_id AND claim_owner_id=p_owner_id AND claim_owner_epoch=p_owner_epoch
      AND version=p_expected_version AND terminal_at IS NULL
      AND claim_expires_at>clock_timestamp()
      AND p_phase IN ('ready','failed')
      AND (kind<>'active_recovery' OR EXISTS (
          SELECT 1 FROM ops.model_settings_state state
          WHERE state.singleton=true AND state.active_revision=ops.managed_ollama_operations.target_revision
      ))
      AND EXISTS (
          SELECT 1 FROM ops.managed_ollama_runtime runtime
          WHERE runtime.singleton=true AND runtime.owner_id=p_owner_id
            AND runtime.owner_epoch=p_owner_epoch AND runtime.lease_expires_at>clock_timestamp()
      )
    RETURNING * INTO result;
    IF NOT FOUND THEN
        RETURN;
    END IF;
    IF result.phase IN ('failed','succeeded') THEN
        UPDATE ops.managed_ollama_holds
        SET released_at=clock_timestamp(), version=version+1, updated_at=clock_timestamp()
        WHERE operation_id=result.operation_id AND released_at IS NULL;
        IF NOT FOUND THEN
            RAISE EXCEPTION 'managed Ollama terminal operation hold is missing' USING ERRCODE='55000';
        END IF;
    END IF;
    RETURN NEXT result;
END
$$;


--
-- Name: managed_ollama_expire_operations(uuid, bigint); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.managed_ollama_expire_operations(p_owner_id uuid, p_owner_epoch bigint) RETURNS bigint
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'ops'
    AS $$
DECLARE
    expired_count bigint;
BEGIN
    WITH terminalized AS (
        UPDATE ops.managed_ollama_operations operation
        SET phase=CASE WHEN operation.created_at+interval '6 hours'<=clock_timestamp()
                       THEN 'failed' ELSE 'superseded' END,
            error_code=CASE WHEN operation.created_at+interval '6 hours'<=clock_timestamp()
                            THEN 'LOCAL_MODEL_RUNTIME_PREPARATION_TIMEOUT' ELSE NULL END,
            error_retryable=false, terminal_at=clock_timestamp(),
            claim_owner_id=NULL, claim_owner_epoch=NULL, claim_expires_at=NULL,
            version=operation.version+1, updated_at=clock_timestamp()
        WHERE operation.terminal_at IS NULL
          AND (
              operation.created_at+interval '6 hours'<=clock_timestamp()
              OR (operation.kind='active_recovery' AND NOT EXISTS (
                  SELECT 1 FROM ops.model_settings_state state
                  WHERE state.singleton=true AND state.active_revision=operation.target_revision
              ))
          )
          AND EXISTS (
              SELECT 1 FROM ops.managed_ollama_runtime runtime
              WHERE runtime.singleton=true AND runtime.owner_id=p_owner_id
                AND runtime.owner_epoch=p_owner_epoch AND runtime.lease_expires_at>clock_timestamp()
          )
        RETURNING operation.operation_id
    ), released AS (
        UPDATE ops.managed_ollama_holds hold
        SET released_at=clock_timestamp(), version=hold.version+1, updated_at=clock_timestamp()
        WHERE hold.released_at IS NULL
          AND hold.operation_id IN (SELECT operation_id FROM terminalized)
        RETURNING hold.operation_id
    )
    SELECT count(*) INTO expired_count FROM terminalized;
    RETURN expired_count;
END
$$;


--
-- Name: managed_ollama_heartbeat_manager(uuid, bigint, bigint, interval); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.managed_ollama_heartbeat_manager(p_owner_id uuid, p_owner_epoch bigint, p_expected_version bigint, p_lease_duration interval) RETURNS SETOF ops.managed_ollama_runtime
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'ops'
    AS $$
BEGIN
    RETURN QUERY
    UPDATE ops.managed_ollama_runtime
    SET heartbeat_at=clock_timestamp(), lease_expires_at=clock_timestamp()+p_lease_duration,
        version=version+1, updated_at=clock_timestamp()
    WHERE singleton=true AND owner_id=p_owner_id AND owner_epoch=p_owner_epoch AND version=p_expected_version
      AND p_lease_duration>interval '0' AND p_lease_duration<=interval '10 minutes'
      AND lease_expires_at>clock_timestamp()
    RETURNING *;
END
$$;


--
-- Name: managed_ollama_publish_demand(uuid, bigint, bigint, bigint, text, jsonb, bigint); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.managed_ollama_publish_demand(p_owner_id uuid, p_owner_epoch bigint, p_expected_version bigint, p_expected_requirement_version bigint, p_requirement_hash text, p_required_models jsonb, p_expected_settings_state_version bigint) RETURNS SETOF ops.managed_ollama_runtime
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'ops'
    AS $$
BEGIN
    RETURN QUERY
    UPDATE ops.managed_ollama_runtime
    SET requirement_version=requirement_version+1,
        requirement_hash=p_requirement_hash,
        required_models=p_required_models,
        observed_phase=CASE
            WHEN requirement_hash IS DISTINCT FROM p_requirement_hash
                 AND jsonb_array_length(p_required_models)=0
                 AND observed_phase IN ('ready','starting','pulling','checking','failed') THEN 'stopping'
            WHEN requirement_hash IS DISTINCT FROM p_requirement_hash
                 AND jsonb_array_length(p_required_models)>0
                 AND observed_phase='ready' THEN 'starting'
            ELSE observed_phase
        END,
        ready_requirement_hash=CASE WHEN requirement_hash IS DISTINCT FROM p_requirement_hash THEN '' ELSE ready_requirement_hash END,
        version=version+1, updated_at=clock_timestamp()
    WHERE singleton=true AND owner_id=p_owner_id AND owner_epoch=p_owner_epoch
      AND version=p_expected_version AND requirement_version=p_expected_requirement_version
      AND lease_expires_at>clock_timestamp()
      AND (SELECT version FROM ops.model_settings_state WHERE singleton=true)=p_expected_settings_state_version
    RETURNING *;
END
$$;


--
-- Name: managed_ollama_record_operation_progress(uuid, uuid, bigint, bigint, text, jsonb, jsonb, bigint, bigint, boolean, interval, text); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.managed_ollama_record_operation_progress(p_operation_id uuid, p_owner_id uuid, p_owner_epoch bigint, p_expected_version bigint, p_next_phase text, p_completed_models jsonb, p_resolved_models jsonb, p_completed_bytes bigint, p_total_bytes bigint, p_progress_known boolean, p_lease_duration interval, p_expected_phase text) RETURNS SETOF ops.managed_ollama_operations
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'ops'
    AS $$
BEGIN
    RETURN QUERY
    UPDATE ops.managed_ollama_operations
    SET phase=p_next_phase, completed_models=p_completed_models, resolved_models=p_resolved_models,
        completed_bytes=p_completed_bytes, total_bytes=p_total_bytes, progress_known=p_progress_known,
        last_progress_at=clock_timestamp(), claim_expires_at=clock_timestamp()+p_lease_duration,
        version=version+1, updated_at=clock_timestamp()
    WHERE operation_id=p_operation_id AND claim_owner_id=p_owner_id AND claim_owner_epoch=p_owner_epoch
      AND version=p_expected_version AND phase=p_expected_phase AND terminal_at IS NULL
      AND claim_expires_at>clock_timestamp()
      AND created_at+interval '6 hours'>clock_timestamp()
      AND (kind<>'active_recovery' OR EXISTS (
          SELECT 1 FROM ops.model_settings_state state
          WHERE state.singleton=true AND state.active_revision=ops.managed_ollama_operations.target_revision
      ))
      AND p_lease_duration>interval '0' AND p_lease_duration<=interval '1 hour'
      AND EXISTS (
          SELECT 1 FROM ops.managed_ollama_runtime runtime
          WHERE runtime.singleton=true AND runtime.owner_id=p_owner_id
            AND runtime.owner_epoch=p_owner_epoch AND runtime.lease_expires_at>clock_timestamp()
      )
    RETURNING *;
END
$$;


--
-- Name: managed_ollama_seed_active_recovery(uuid, bigint, bigint, interval); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.managed_ollama_seed_active_recovery(p_owner_id uuid, p_owner_epoch bigint, p_expected_settings_state_version bigint, p_lease_duration interval) RETURNS SETOF ops.managed_ollama_operations
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'ops'
    AS $$
DECLARE
    v_active_revision bigint;
    v_required_models jsonb;
    v_model_lines text;
    v_requirement_hash text;
    v_request_hash text;
    v_idempotency_key text;
    v_generation bigint;
    v_result ops.managed_ollama_operations;
BEGIN
    IF p_lease_duration<=interval '0' OR p_lease_duration>interval '1 hour' THEN
        RETURN;
    END IF;
    IF NOT EXISTS (
        SELECT 1 FROM ops.managed_ollama_runtime runtime
        WHERE runtime.singleton=true AND runtime.owner_id=p_owner_id
          AND runtime.owner_epoch=p_owner_epoch AND runtime.lease_expires_at>clock_timestamp()
    ) THEN
        RETURN;
    END IF;

    IF EXISTS (
        SELECT 1
        FROM ops.model_settings_state state
        JOIN ops.model_settings_revisions revision ON revision.revision=state.active_revision
        CROSS JOIN LATERAL (
            VALUES
                (CASE WHEN revision.chat_provider='ollama'
                            OR (revision.chat_provider='openai-compatible'
                                AND revision.chat_base_url='http://127.0.0.1:11434')
                      THEN revision.chat_model END),
                (CASE WHEN revision.embedding_provider='ollama' THEN revision.embedding_model END)
        ) local_model(model)
        WHERE state.singleton=true AND state.version=p_expected_settings_state_version
          AND local_model.model IS NOT NULL
          AND (local_model.model<>btrim(local_model.model)
               OR octet_length(local_model.model) NOT BETWEEN 1 AND 128
               OR local_model.model ~ '[[:cntrl:]]'
               OR local_model.model ~ U&'[\0080-\009F]')
    ) THEN
        RAISE EXCEPTION 'active managed Ollama recovery model is invalid' USING ERRCODE='55000';
    END IF;

    SELECT state.active_revision,
           jsonb_agg(local_model.model ORDER BY local_model.model),
           string_agg(local_model.model,E'\n' ORDER BY local_model.model)
    INTO v_active_revision,v_required_models,v_model_lines
    FROM ops.model_settings_state state
    JOIN ops.model_settings_revisions revision ON revision.revision=state.active_revision
    CROSS JOIN LATERAL (
        SELECT DISTINCT candidate.model
        FROM (VALUES
            (CASE WHEN revision.chat_provider='ollama'
                        OR (revision.chat_provider='openai-compatible'
                            AND revision.chat_base_url='http://127.0.0.1:11434')
                  THEN revision.chat_model END),
            (CASE WHEN revision.embedding_provider='ollama' THEN revision.embedding_model END)
        ) candidate(model)
        WHERE candidate.model IS NOT NULL
    ) local_model
    WHERE state.singleton=true AND state.version=p_expected_settings_state_version
    GROUP BY state.active_revision;
    IF v_active_revision IS NULL OR jsonb_array_length(v_required_models)=0 THEN
        RETURN;
    END IF;

    v_requirement_hash := encode(sha256(convert_to(
        'managed-ollama-requirement/v1'||E'\n'||v_model_lines,'UTF8')),'hex');
    v_request_hash := encode(sha256(convert_to(
        'managed-ollama-active-recovery/v1'||E'\n'||v_active_revision::text||E'\n'||v_requirement_hash,
        'UTF8')),'hex');
    SELECT count(*)
    INTO v_generation
    FROM ops.managed_ollama_operations operation
    WHERE operation.kind='active_recovery'
      AND operation.target_revision=v_active_revision
      AND operation.requirement_hash=v_requirement_hash
      AND operation.idempotency_key LIKE 'active-recovery:'||v_active_revision::text||':'||v_requirement_hash||':%';

    SELECT * INTO v_result
    FROM ops.managed_ollama_operations operation
    WHERE operation.kind='active_recovery'
      AND operation.target_revision=v_active_revision
      AND operation.requirement_hash=v_requirement_hash
    ORDER BY operation.created_at DESC,operation.operation_id DESC
    LIMIT 1;
    IF FOUND AND v_result.terminal_at IS NULL THEN
        v_idempotency_key := v_result.idempotency_key;
    ELSIF FOUND AND v_result.phase='failed' THEN
        RETURN NEXT v_result;
        RETURN;
    ELSE
        v_generation := v_generation+1;
        v_idempotency_key := 'active-recovery:'||v_active_revision::text||':'||v_requirement_hash||':'||v_generation::text;
        v_result := NULL;
    END IF;

    IF v_result.operation_id IS NULL THEN
        INSERT INTO ops.managed_ollama_operations(
            operation_id,kind,idempotency_key,request_hash,target_revision,
            requirement_hash,required_models
        ) VALUES(
            gen_random_uuid(),'active_recovery',v_idempotency_key,v_request_hash,v_active_revision,
            v_requirement_hash,v_required_models
        ) ON CONFLICT (kind,idempotency_key) DO NOTHING;
    END IF;

    SELECT * INTO v_result
    FROM ops.managed_ollama_operations operation
    WHERE operation.kind='active_recovery' AND operation.idempotency_key=v_idempotency_key;
    IF v_result.request_hash IS DISTINCT FROM v_request_hash
       OR v_result.target_revision IS DISTINCT FROM v_active_revision
       OR v_result.requirement_hash IS DISTINCT FROM v_requirement_hash
       OR v_result.required_models IS DISTINCT FROM v_required_models THEN
        RAISE EXCEPTION 'active managed Ollama recovery replay conflicts with current settings' USING ERRCODE='55000';
    END IF;

    IF v_result.terminal_at IS NULL THEN
        INSERT INTO ops.managed_ollama_holds(
            hold_id,owner_kind,owner_id,owner_epoch,revision,operation_id,
            requirement_hash,models,lease_expires_at
        ) VALUES(
            gen_random_uuid(),'preparation',v_result.operation_id,1,v_active_revision,v_result.operation_id,
            v_requirement_hash,v_required_models,clock_timestamp()+p_lease_duration
        ) ON CONFLICT (operation_id) WHERE operation_id IS NOT NULL DO NOTHING;
        IF NOT EXISTS (
            SELECT 1 FROM ops.managed_ollama_holds hold
            WHERE hold.operation_id=v_result.operation_id AND hold.owner_kind='preparation'
              AND hold.owner_id=v_result.operation_id AND hold.owner_epoch=1
              AND hold.revision=v_active_revision AND hold.requirement_hash=v_requirement_hash
              AND hold.models=v_required_models AND hold.released_at IS NULL
        ) THEN
            RAISE EXCEPTION 'active managed Ollama recovery hold conflicts with current settings' USING ERRCODE='55000';
        END IF;
    END IF;
    RETURN NEXT v_result;
END
$$;


--
-- Name: model_settings_revision_exists(bigint); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.model_settings_revision_exists(candidate bigint) RETURNS boolean
    LANGUAGE sql STABLE
    AS $$
    SELECT candidate=0 OR EXISTS (
        SELECT 1 FROM ops.model_settings_revisions AS revision WHERE revision.revision=candidate
    )
$$;


--
-- Name: project_approval_timeline_source(); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.project_approval_timeline_source() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    approval_workspace_id uuid;
    proposal_type_value text;
    projected_event_type text;
BEGIN
    SELECT workspace_id,proposal_type INTO approval_workspace_id,proposal_type_value
      FROM change_control.proposal
     WHERE id = NEW.proposal_id;
    IF proposal_type_value='restore_document' THEN
        RETURN NEW;
    END IF;
    projected_event_type := CASE WHEN NEW.decision = 'approved' THEN 'APPROVAL_GRANTED' ELSE 'APPROVAL_REJECTED' END;
    PERFORM ops.enqueue_timeline_projection(
        approval_workspace_id,projected_event_type,'APPROVAL',NEW.id,
        'approval:' || NEW.id::text || ':v1','approval:' || NEW.id::text,
        1,CASE WHEN NEW.decision = 'approved' THEN 'Approval granted' ELSE 'Approval rejected' END,
        jsonb_build_object('proposal_id',NEW.proposal_id::text,'approval_id',NEW.id::text),NEW.decided_at
    );
    RETURN NEW;
END;
$$;


--
-- Name: project_artifact_generated_timeline_source(); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.project_artifact_generated_timeline_source() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    revision_id uuid;
    revision_no integer;
    revision_content_hash text;
    revision_created_by_type text;
    binding jsonb;
BEGIN
    IF OLD.current_revision_id IS NOT DISTINCT FROM NEW.current_revision_id
       OR NEW.domain_schema_version <> 'artifact/v1' THEN
        RETURN NEW;
    END IF;

    SELECT candidate.id,candidate.revision_no,candidate.content_hash,candidate.created_by_type
      INTO revision_id,revision_no,revision_content_hash,revision_created_by_type
      FROM learning.artifact_revision
      AS candidate
     WHERE candidate.id=NEW.current_revision_id
       AND candidate.workspace_id=NEW.workspace_id
       AND candidate.artifact_id=NEW.id;

    IF revision_id IS NULL OR revision_created_by_type <> 'AGENT' THEN
        RETURN NEW;
    END IF;

    binding := jsonb_build_object('artifact',jsonb_build_object(
        'artifact_id',NEW.id,
        'artifact_version',NEW.version,
        'revision_id',revision_id,
        'revision_no',revision_no,
        'content_hash',revision_content_hash
    ));

    PERFORM ops.enqueue_timeline_projection_v2(
        NEW.workspace_id,'ARTIFACT_GENERATED','ARTIFACT',NEW.id,
        'artifact-generated:' || NEW.id::text || ':' || revision_id::text || ':v' || NEW.version::text,
        'artifact:' || NEW.id::text,NEW.version,
        'Artifact revision generated','{}'::jsonb,'SYSTEM',NULL,binding,NEW.updated_at
    );
    RETURN NEW;
END;
$$;


--
-- Name: project_health_issue_timeline_source(); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.project_health_issue_timeline_source() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    projected_event_type text;
    projected_source_kind text;
    projected_summary text;
    projected_occurred_at timestamptz;
BEGIN
    IF TG_OP = 'INSERT' THEN
        projected_event_type := 'HEALTH_ISSUE_DETECTED';
        projected_source_kind := 'detected';
        projected_summary := 'Health issue detected';
        projected_occurred_at := NEW.first_detected_at;
    ELSIF OLD.status IS DISTINCT FROM NEW.status AND NEW.status = 'RESOLVED' THEN
        projected_event_type := 'HEALTH_ISSUE_RESOLVED';
        projected_source_kind := 'resolved';
        projected_summary := 'Health issue resolved';
        projected_occurred_at := NEW.resolved_at;
    ELSIF OLD.status = 'RESOLVED' AND NEW.status = 'REOPENED' THEN
        projected_event_type := 'HEALTH_ISSUE_DETECTED';
        projected_source_kind := 'detected';
        projected_summary := 'Health issue detected';
        projected_occurred_at := NEW.last_detected_at;
    ELSE
        RETURN NEW;
    END IF;

    PERFORM ops.enqueue_timeline_projection(
        NEW.workspace_id,
        projected_event_type,
        'HEALTH_ISSUE',
        NEW.id,
        'health-issue.' || projected_source_kind || ':' || NEW.id::text || ':v' || NEW.version::text,
        'health_issue:' || NEW.id::text,
        NEW.version,
        projected_summary,
        '{}'::jsonb,
        projected_occurred_at
    );
    RETURN NEW;
END;
$$;


