--
-- Name: project_learning_server_event(); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.project_learning_server_event() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    row_data jsonb;
    action text;
    event_type text;
    resource_id text;
    resource_version bigint;
    occurred_at timestamptz;
BEGIN
    IF TG_OP = 'DELETE' THEN
        row_data := to_jsonb(OLD);
        action := 'deleted';
    ELSIF TG_OP = 'UPDATE' THEN
        row_data := to_jsonb(NEW);
        action := 'updated';
    ELSE
        row_data := to_jsonb(NEW);
        action := 'created';
    END IF;

    resource_id := row_data ->> TG_ARGV[2];
    IF resource_id IS NULL OR resource_id = '' THEN
        RAISE EXCEPTION 'learning SSE resource identity is missing'
            USING ERRCODE = '23514';
    END IF;

    IF TG_ARGV[3] <> '' THEN
        resource_version := NULLIF(row_data ->> TG_ARGV[3], '')::bigint;
    ELSE
        -- Immutable rows are version one. The only unversioned mutable rows
        -- (review sessions) have a single ACTIVE -> terminal transition.
        resource_version := CASE WHEN TG_OP = 'UPDATE' THEN 2 ELSE 1 END;
    END IF;
    IF resource_version IS NULL OR resource_version < 1 THEN
        RAISE EXCEPTION 'learning SSE resource version is invalid'
            USING ERRCODE = '23514';
    END IF;

    IF TG_OP = 'UPDATE' AND TG_NARGS > 5 THEN
        IF TG_ARGV[5] <> '' AND NULLIF(row_data ->> TG_ARGV[5], '') IS NOT NULL THEN
            occurred_at := (row_data ->> TG_ARGV[5])::timestamptz;
        ELSE
            occurred_at := CURRENT_TIMESTAMP;
        END IF;
    ELSIF TG_ARGV[4] <> '' AND NULLIF(row_data ->> TG_ARGV[4], '') IS NOT NULL THEN
        occurred_at := (row_data ->> TG_ARGV[4])::timestamptz;
    ELSE
        occurred_at := CURRENT_TIMESTAMP;
    END IF;
    event_type := TG_ARGV[0] || '.' || action;

    INSERT INTO ops.server_event(
        workspace_id,conversation_id,workflow_run_id,event_type,resource_ref,
        resource_version,payload_summary,schema_version,source_event_ref,
        occurred_at,expires_at
    ) VALUES (
        (row_data ->> 'workspace_id')::uuid,NULL,NULL,event_type,
        TG_ARGV[1] || ':' || resource_id,resource_version,'{}'::jsonb,1,
        event_type || ':' || resource_id || ':v' || resource_version::text || ':tx' || txid_current()::text,
        occurred_at,occurred_at + INTERVAL '24 hours'
    )
    ON CONFLICT (workspace_id,source_event_ref) DO NOTHING;

    IF TG_OP = 'DELETE' THEN
        RETURN OLD;
    END IF;
    RETURN NEW;
END
$$;


--
-- Name: project_proposal_commit_timeline_source(); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.project_proposal_commit_timeline_source() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    revision_version integer;
    proposal_type_value text;
    projected_correlation jsonb;
BEGIN
    SELECT proposal.proposal_type,revision.revision_no
      INTO proposal_type_value,revision_version
      FROM change_control.proposal AS proposal
      JOIN change_control.proposal_revision AS revision
        ON revision.id=NEW.revision_id AND revision.proposal_id=proposal.id
     WHERE proposal.id=NEW.proposal_id;
    IF proposal_type_value='restore_document' THEN
        RETURN NEW;
    END IF;
    projected_correlation := jsonb_build_object(
        'proposal_id',NEW.proposal_id::text,
        'approval_id',NEW.approval_id::text,
        'git_commit_ref',NEW.git_commit
    );
    PERFORM ops.enqueue_timeline_projection(
        NEW.workspace_id,'GIT_COMMITTED','GIT_COMMIT',NEW.id,
        'proposal-commit:' || NEW.id::text || ':v1','git_commit:' || NEW.git_commit,
        1,'Git commit created',projected_correlation,NEW.created_at
    );
    PERFORM ops.enqueue_timeline_projection(
        NEW.workspace_id,'VERSION_PUBLISHED','ARTICLE_REVISION',NEW.revision_id,
        'proposal-revision-published:' || NEW.id::text || ':v1','article_revision:' || NEW.revision_id::text,
        revision_version,'Proposal revision published',projected_correlation,NEW.created_at
    );
    RETURN NEW;
END;
$$;


