        'review-card-invalidated:' || NEW.id::text || ':v' || NEW.version::text,
        'review-card:' || NEW.id::text,NEW.version,
        'Review card invalidated','{}'::jsonb,'SYSTEM',NULL,binding,NEW.updated_at
    );
    RETURN NEW;
