--
-- Name: sync_model_settings_mutation_gate(); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.sync_model_settings_mutation_gate() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    changed_rows integer;
BEGIN
    IF NEW.phase IN ('preparing','arming','activating') THEN
        UPDATE ops.runtime_mutation_gate
        SET owner_kind='model_settings',owner_id=NEW.rollout_id,
            lease_expires_at=NEW.lease_expires_at,version=version+1,updated_at=NEW.updated_at
        WHERE singleton=true
          AND (owner_id IS NULL OR (owner_kind='model_settings' AND owner_id=NEW.rollout_id));
        GET DIAGNOSTICS changed_rows=ROW_COUNT;
        IF changed_rows<>1 THEN
            RAISE EXCEPTION 'runtime mutation gate is held by another operation' USING ERRCODE='55P03';
        END IF;
    ELSIF OLD.phase IN ('preparing','arming','activating') AND NEW.phase IN ('idle','failed') THEN
        UPDATE ops.runtime_mutation_gate
        SET owner_kind=NULL,owner_id=NULL,lease_expires_at=NULL,
            version=version+1,updated_at=NEW.updated_at
        WHERE singleton=true AND owner_kind='model_settings' AND owner_id=OLD.rollout_id;
        GET DIAGNOSTICS changed_rows=ROW_COUNT;
        IF changed_rows<>1 THEN
            RAISE EXCEPTION 'model settings mutation gate ownership is corrupt' USING ERRCODE='55000';
        END IF;
    END IF;
    RETURN NEW;
END
$$;


--
-- Name: valid_git_sync_changed_files(jsonb); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.valid_git_sync_changed_files(value jsonb) RETURNS boolean
    LANGUAGE plpgsql IMMUTABLE STRICT
    AS $$
DECLARE
    item jsonb;
    kind text;
    path_value text;
    old_path_value text;
BEGIN
    IF jsonb_typeof(value)<>'array' OR jsonb_array_length(value)>500
       OR octet_length(value::text)>1048576 THEN
        RETURN false;
    END IF;
    FOR item IN SELECT item_value FROM jsonb_array_elements(value) AS elements(item_value) LOOP
        IF jsonb_typeof(item)<>'object' OR item - ARRAY['path','old_path','kind']::text[] <> '{}'::jsonb
           OR jsonb_typeof(item->'path') IS DISTINCT FROM 'string'
           OR jsonb_typeof(item->'kind') IS DISTINCT FROM 'string' THEN
            RETURN false;
        END IF;
        kind := item->>'kind';
        path_value := item->>'path';
        IF kind NOT IN ('ADDED','MODIFIED','DELETED','RENAMED') OR NOT ops.valid_git_sync_path(path_value) THEN
            RETURN false;
        END IF;
        IF kind='RENAMED' THEN
            IF jsonb_typeof(item->'old_path') IS DISTINCT FROM 'string' THEN
                RETURN false;
            END IF;
            old_path_value := item->>'old_path';
            IF NOT ops.valid_git_sync_path(old_path_value) OR old_path_value=path_value THEN
                RETURN false;
            END IF;
        ELSIF item ? 'old_path' THEN
            RETURN false;
        END IF;
    END LOOP;
    RETURN true;
END;
$$;


--
-- Name: valid_git_sync_path(text); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.valid_git_sync_path(value text) RETURNS boolean
    LANGUAGE sql IMMUTABLE STRICT
    AS $_$
    SELECT octet_length(value) BETWEEN 1 AND 4096
       AND value=btrim(value)
       AND value !~ E'[\\x00-\\x1f\\x7f]'
       AND left(value,1)<>'/'
       AND right(value,1)<>'/'
       AND value<>'.'
       AND value !~ '(^|/)([.]|[.][.])(/|$)'
       AND value !~ '//';
$_$;


--
-- Name: valid_impact_owner_binding(text, uuid, bigint, jsonb); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.valid_impact_owner_binding(target_type text, target_id uuid, target_version bigint, owner_binding jsonb) RETURNS boolean
    LANGUAGE plpgsql IMMUTABLE
    AS $_$
DECLARE
    artifact_binding jsonb;
    review_binding jsonb;
BEGIN
    IF target_type='ARTIFACT' THEN
        artifact_binding := owner_binding->'artifact';
        RETURN COALESCE(target_id IS NOT NULL
           AND target_version > 0
           AND jsonb_typeof(owner_binding)='object'
           AND owner_binding - 'artifact'='{}'::jsonb
           AND jsonb_typeof(artifact_binding)='object'
           AND artifact_binding - ARRAY[
               'artifact_id','artifact_version','revision_id','revision_no','content_hash'
           ]='{}'::jsonb
           AND artifact_binding->>'artifact_id' ~ '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
           AND (artifact_binding->>'artifact_id')::uuid=target_id
           AND (artifact_binding->>'artifact_version')::bigint=target_version
           AND artifact_binding->>'revision_id' ~ '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
           AND (artifact_binding->>'revision_id')::uuid<>target_id
           AND (artifact_binding->>'revision_no')::bigint>0
           AND artifact_binding->>'content_hash' ~ '^[0-9a-f]{64}$', false);
    END IF;

    IF target_type='REVIEW_CARD' THEN
        review_binding := owner_binding->'review_card';
        RETURN COALESCE(target_id IS NOT NULL
           AND target_version > 0
           AND jsonb_typeof(owner_binding)='object'
           AND owner_binding - 'review_card'='{}'::jsonb
           AND jsonb_typeof(review_binding)='object'
           AND review_binding - ARRAY[
               'card_id','card_version','status','fingerprint','claim_id','evidence_binding_fingerprint'
           ]='{}'::jsonb
           AND review_binding->>'card_id' ~ '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
           AND (review_binding->>'card_id')::uuid=target_id
           AND (review_binding->>'card_version')::bigint=target_version
           AND review_binding->>'status' IN ('DRAFT','APPROVED','INVALIDATED','REJECTED')
           AND review_binding->>'fingerprint' ~ '^[0-9a-f]{64}$'
           AND review_binding->>'claim_id' ~ '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
           AND (review_binding->>'claim_id')::uuid<>target_id
           AND review_binding->>'evidence_binding_fingerprint' ~ '^[0-9a-f]{64}$', false);
    END IF;

    RETURN false;
EXCEPTION
    WHEN invalid_text_representation OR numeric_value_out_of_range THEN
        RETURN false;
END
$_$;


--
-- Name: valid_timeline_owner_binding(text, text, uuid, jsonb); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.valid_timeline_owner_binding(projected_event_type text, projected_aggregate_type text, projected_aggregate_id uuid, projected_owner_binding jsonb) RETURNS boolean
    LANGUAGE plpgsql IMMUTABLE
    AS $_$
DECLARE
    artifact_binding jsonb;
    review_binding jsonb;
BEGIN
    IF projected_event_type = 'ARTIFACT_GENERATED' THEN
        artifact_binding := projected_owner_binding->'artifact';
        RETURN COALESCE(projected_aggregate_type = 'ARTIFACT'
           AND projected_aggregate_id IS NOT NULL
           AND jsonb_typeof(projected_owner_binding) = 'object'
           AND projected_owner_binding - 'artifact' = '{}'::jsonb
           AND jsonb_typeof(artifact_binding) = 'object'
           AND artifact_binding - ARRAY[
               'artifact_id','artifact_version','revision_id','revision_no','content_hash'
           ] = '{}'::jsonb
           AND artifact_binding->>'artifact_id' ~ '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
           AND (artifact_binding->>'artifact_id')::uuid = projected_aggregate_id
           AND (artifact_binding->>'artifact_version')::bigint > 0
           AND artifact_binding->>'revision_id' ~ '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
           AND (artifact_binding->>'revision_id')::uuid <> projected_aggregate_id
           AND (artifact_binding->>'revision_no')::bigint > 0
           AND artifact_binding->>'content_hash' ~ '^[0-9a-f]{64}$', false);
    END IF;

    IF projected_event_type = 'REVIEW_CARD_INVALIDATED' THEN
        review_binding := projected_owner_binding->'review_card';
        RETURN COALESCE(projected_aggregate_type = 'REVIEW_CARD'
           AND projected_aggregate_id IS NOT NULL
           AND jsonb_typeof(projected_owner_binding) = 'object'
           AND projected_owner_binding - 'review_card' = '{}'::jsonb
           AND jsonb_typeof(review_binding) = 'object'
           AND review_binding - ARRAY[
               'card_id','card_version','status','fingerprint','claim_id','evidence_binding_fingerprint'
           ] = '{}'::jsonb
           AND review_binding->>'card_id' ~ '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
           AND (review_binding->>'card_id')::uuid = projected_aggregate_id
           AND (review_binding->>'card_version')::bigint > 0
           AND review_binding->>'status' = 'INVALIDATED'
           AND review_binding->>'fingerprint' ~ '^[0-9a-f]{64}$'
           AND review_binding->>'claim_id' ~ '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
           AND (review_binding->>'claim_id')::uuid <> projected_aggregate_id
           AND review_binding->>'evidence_binding_fingerprint' ~ '^[0-9a-f]{64}$', false);
    END IF;

    RETURN projected_owner_binding IS NULL;
EXCEPTION
    WHEN invalid_text_representation OR numeric_value_out_of_range THEN
        RETURN false;
END
$_$;


--
-- Name: validate_git_remote_config_projection(); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.validate_git_remote_config_projection() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF TG_OP='DELETE' THEN
        RAISE EXCEPTION 'Git remote current configuration cannot be deleted' USING ERRCODE='55000';
    END IF;
    IF TG_OP='INSERT' AND NEW.revision<>1 THEN
        RAISE EXCEPTION 'Git remote initial configuration revision is invalid' USING ERRCODE='55000';
    END IF;
    IF TG_OP='UPDATE' AND (
        NEW.workspace_id IS DISTINCT FROM OLD.workspace_id
        OR NEW.created_at IS DISTINCT FROM OLD.created_at
        OR NEW.revision<>OLD.revision+1
        OR NEW.updated_at<OLD.updated_at
    ) THEN
        RAISE EXCEPTION 'Git remote current configuration CAS is invalid' USING ERRCODE='55000';
    END IF;
    IF NOT EXISTS (
        SELECT 1 FROM ops.git_remote_config_revision AS revision
        WHERE revision.workspace_id=NEW.workspace_id AND revision.revision=NEW.revision
          AND revision.configured=NEW.configured
          AND revision.normalized_url IS NOT DISTINCT FROM NEW.normalized_url
          AND revision.branch IS NOT DISTINCT FROM NEW.branch
          AND revision.auto_sync=NEW.auto_sync
          AND revision.token_configured=NEW.token_configured
          AND revision.config_created_at=NEW.created_at
          AND revision.created_at=NEW.updated_at
    ) THEN
        RAISE EXCEPTION 'Git remote current configuration lacks an exact revision fact' USING ERRCODE='55000';
    END IF;
    RETURN NEW;
END;
$$;


--
-- Name: validate_git_remote_credential_binding(); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.validate_git_remote_credential_binding() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    target_workspace uuid;
    expects_credential boolean;
    has_credential boolean;
BEGIN
    target_workspace := COALESCE(NEW.workspace_id, OLD.workspace_id);
    SELECT token_configured INTO expects_credential
    FROM ops.git_remote_config
    WHERE workspace_id=target_workspace;
    IF NOT FOUND THEN
        RETURN NULL;
    END IF;
    SELECT EXISTS (
        SELECT 1
        FROM ops.git_remote_credential AS credential
        JOIN ops.git_remote_config AS config
          ON config.workspace_id=credential.workspace_id
         AND config.revision=credential.config_revision
        WHERE credential.workspace_id=target_workspace
    ) INTO has_credential;
    IF expects_credential IS DISTINCT FROM has_credential THEN
        RAISE EXCEPTION 'Git remote token projection and credential disagree' USING ERRCODE='55000';
    END IF;
    RETURN NULL;
END;
$$;


--
-- Name: validate_git_sync_attempt_update(); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.validate_git_sync_attempt_update() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF NEW.id<>OLD.id OR NEW.workspace_id<>OLD.workspace_id OR NEW.run_id<>OLD.run_id
       OR NEW.attempt_no<>OLD.attempt_no OR NEW.started_at<>OLD.started_at
       OR NEW.version<>OLD.version+1 OR OLD.status<>'RUNNING' THEN
        RAISE EXCEPTION 'Git sync attempt immutable binding or transition changed' USING ERRCODE='55000';
    END IF;
    RETURN NEW;
END;
$$;


--
-- Name: validate_git_sync_run_update(); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.validate_git_sync_run_update() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF NEW.id<>OLD.id OR NEW.workspace_id<>OLD.workspace_id OR NEW.config_revision<>OLD.config_revision
       OR NEW.remote_url<>OLD.remote_url OR NEW.branch<>OLD.branch OR NEW.trigger<>OLD.trigger
       OR NEW.retry_of_run_id IS DISTINCT FROM OLD.retry_of_run_id OR NEW.idempotency_key<>OLD.idempotency_key
       OR NEW.request_hash<>OLD.request_hash OR NEW.created_at<>OLD.created_at
       OR NEW.version<>OLD.version+1 THEN
        RAISE EXCEPTION 'Git sync run immutable binding or version changed' USING ERRCODE='55000';
    END IF;

    IF OLD.status IN ('PENDING','FETCHING','COMPARING','FAST_FORWARDING','PUSHING','VERIFYING') THEN
        IF NOT (
	            (OLD.status='PENDING' AND NEW.status IN ('FETCHING','FAILED','STALE'))
            OR (OLD.status='FETCHING' AND NEW.status IN ('COMPARING','FAILED','STALE','MANUAL_RECOVERY_REQUIRED'))
            OR (OLD.status='COMPARING' AND NEW.status IN ('FAST_FORWARDING','PUSHING','SUCCEEDED','CONFLICT','FAILED','STALE','MANUAL_RECOVERY_REQUIRED'))
            OR (OLD.status='FAST_FORWARDING' AND NEW.status IN ('VERIFYING','FAILED','CONFLICT','MANUAL_RECOVERY_REQUIRED'))
            OR (OLD.status='PUSHING' AND NEW.status IN ('VERIFYING','FAILED','CONFLICT','MANUAL_RECOVERY_REQUIRED'))
            OR (OLD.status='VERIFYING' AND NEW.status IN ('SUCCEEDED','FAILED','CONFLICT','MANUAL_RECOVERY_REQUIRED'))
        ) THEN
            RAISE EXCEPTION 'Git sync run transition is invalid' USING ERRCODE='55000';
        END IF;
    ELSIF OLD.status='SUCCEEDED' AND NEW.status='SUCCEEDED' THEN
        IF NEW.id IS DISTINCT FROM OLD.id OR NEW.expected_head_oid IS DISTINCT FROM OLD.expected_head_oid
           OR NEW.expected_remote_oid IS DISTINCT FROM OLD.expected_remote_oid
           OR NEW.verified_head_oid IS DISTINCT FROM OLD.verified_head_oid
           OR NEW.verified_remote_oid IS DISTINCT FROM OLD.verified_remote_oid
           OR NEW.changed_files IS DISTINCT FROM OLD.changed_files
           OR NEW.direction<>OLD.direction OR NEW.failure_class<>OLD.failure_class
           OR NEW.error_code<>OLD.error_code OR NEW.retryable<>OLD.retryable
           OR NEW.completed_at IS DISTINCT FROM OLD.completed_at
           OR NOT (
	               (OLD.index_status='PENDING' AND NEW.index_status IN ('RUNNING','FAILED'))
               OR (OLD.index_status='RUNNING' AND NEW.index_status IN ('SUCCEEDED','FAILED'))
               OR (OLD.index_status='FAILED' AND NEW.index_status='PENDING')
           ) THEN
            RAISE EXCEPTION 'Git sync index follow-up transition is invalid' USING ERRCODE='55000';
        END IF;
    ELSE
        RAISE EXCEPTION 'terminal Git sync result is immutable' USING ERRCODE='55000';
    END IF;
    RETURN NEW;
END;
$$;


--
-- Name: validate_health_affected_change_outbox_write(); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.validate_health_affected_change_outbox_write() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF TG_OP = 'DELETE' THEN
        RAISE EXCEPTION 'health affected-change is append-only' USING ERRCODE = '55000';
    END IF;
    IF TG_OP = 'INSERT' THEN
        IF NEW.attempt_count <> 0
           OR NEW.version <> 1
           OR NEW.last_error_code IS NOT NULL
           OR NEW.bound_scan_id IS NOT NULL
           OR NEW.bound_workflow_run_id IS NOT NULL
           OR NEW.published_at IS NOT NULL
           OR NEW.poisoned_at IS NOT NULL
           OR NEW.manual_recovery_required
           OR NEW.available_at <> NEW.occurred_at
           OR NEW.created_at <> NEW.occurred_at
           OR NEW.updated_at <> NEW.occurred_at THEN
            RAISE EXCEPTION 'health affected-change has an invalid initial lifecycle' USING ERRCODE = '23514';
        END IF;
        RETURN NEW;
    END IF;

    IF OLD.published_at IS NOT NULL OR OLD.manual_recovery_required THEN
        RAISE EXCEPTION 'terminal health affected-change is immutable' USING ERRCODE = '55000';
    END IF;
    IF NEW.id <> OLD.id
       OR NEW.workspace_id <> OLD.workspace_id
       OR NEW.schema_version <> OLD.schema_version
       OR NEW.event_version <> OLD.event_version
       OR NEW.event_type <> OLD.event_type
       OR NEW.event_key <> OLD.event_key
       OR NEW.source_kind <> OLD.source_kind
       OR NEW.source_key <> OLD.source_key
       OR NEW.source_hash IS DISTINCT FROM OLD.source_hash
       OR NEW.aggregate_type <> OLD.aggregate_type
       OR NEW.aggregate_id <> OLD.aggregate_id
       OR NEW.aggregate_sub_id IS DISTINCT FROM OLD.aggregate_sub_id
       OR NEW.aggregate_version <> OLD.aggregate_version
       OR NEW.change_status <> OLD.change_status
       OR NEW.change_code IS DISTINCT FROM OLD.change_code
       OR NEW.occurred_at <> OLD.occurred_at
       OR NEW.created_at <> OLD.created_at
       OR NEW.attempt_count <> OLD.attempt_count + 1
       OR NEW.version <> OLD.version + 1
       OR NEW.updated_at < OLD.updated_at
       OR NEW.available_at < OLD.available_at THEN
        RAISE EXCEPTION 'health affected-change immutable binding or version changed' USING ERRCODE = '23514';
    END IF;

    IF NEW.published_at IS NOT NULL THEN
        IF NEW.last_error_code IS NOT NULL
           OR NEW.available_at <> OLD.available_at
           OR NOT EXISTS (
                SELECT 1
                  FROM ops.health_scan scan
                 WHERE scan.id = NEW.bound_scan_id
                   AND scan.workspace_id = NEW.workspace_id
                   AND scan.workflow_run_id = NEW.bound_workflow_run_id
                   AND scan.scope_type = 'WORKSPACE'
                   AND scan.scope_ref = NEW.workspace_id
                   AND scan.idempotency_key = 'health-affected-change:' || NEW.id::text
           ) THEN
            RAISE EXCEPTION 'published health affected-change scan binding is invalid' USING ERRCODE = '55000';
        END IF;
    ELSIF NEW.manual_recovery_required THEN
        IF NEW.poisoned_at IS NULL OR NEW.last_error_code IS NULL OR NEW.available_at <> OLD.available_at THEN
            RAISE EXCEPTION 'poisoned health affected-change binding is invalid' USING ERRCODE = '23514';
        END IF;
    ELSIF NEW.last_error_code IS NULL OR NEW.available_at <= OLD.available_at THEN
        RAISE EXCEPTION 'pending health affected-change retry must persist backoff' USING ERRCODE = '23514';
    END IF;
    RETURN NEW;
END;
$$;


--
-- Name: validate_health_evidence_insert(); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.validate_health_evidence_insert() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF NOT ops.health_validate_object_binding(NEW.workspace_id, NEW.ref_type, NEW.ref_id) THEN
        RAISE EXCEPTION 'health evidence reference binding is invalid' USING ERRCODE = '23514';
    END IF;
    RETURN NEW;
END;
$$;


--
-- Name: validate_health_issue_history_insert(); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.validate_health_issue_history_insert() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    current_version bigint;
    issue_workspace uuid;
    proposal_workspace uuid;
    proposal_type_value text;
BEGIN
    IF TG_TABLE_NAME = 'health_issue_observation' THEN
        SELECT workspace_id, version INTO issue_workspace, current_version
          FROM ops.health_issue WHERE id=NEW.issue_id FOR SHARE;
        IF issue_workspace IS NULL OR issue_workspace <> NEW.workspace_id OR NEW.issue_version <> current_version THEN
            RAISE EXCEPTION 'health observation issue version or workspace mismatch' USING ERRCODE = '23514';
        END IF;
    ELSIF TG_TABLE_NAME = 'health_issue_decision' THEN
        SELECT workspace_id, version INTO issue_workspace, current_version
          FROM ops.health_issue WHERE id=NEW.issue_id FOR SHARE;
        IF issue_workspace IS NULL OR issue_workspace <> NEW.workspace_id OR NEW.issue_version <> current_version THEN
            RAISE EXCEPTION 'health decision issue version or workspace mismatch' USING ERRCODE = '23514';
        END IF;
        IF NEW.action = 'DEFER' AND NEW.defer_until <= CURRENT_TIMESTAMP THEN
            RAISE EXCEPTION 'health decision defer time must be in the future' USING ERRCODE = '23514';
        END IF;
        IF NEW.proposal_id IS NOT NULL THEN
            SELECT workspace_id, proposal_type INTO proposal_workspace, proposal_type_value
              FROM change_control.proposal WHERE id=NEW.proposal_id FOR SHARE;
            IF proposal_workspace IS NULL OR proposal_workspace <> NEW.workspace_id OR proposal_type_value <> 'knowledge_change' THEN
                RAISE EXCEPTION 'health decision proposal binding is invalid' USING ERRCODE = '23514';
            END IF;
        END IF;
    END IF;
    RETURN NEW;
END;
$$;


--
-- Name: validate_health_issue_write(); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.validate_health_issue_write() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    proposal_workspace uuid;
    proposal_type_value text;
BEGIN
    IF NOT ops.health_validate_object_binding(NEW.workspace_id, NEW.target_type, NEW.target_id) THEN
        RAISE EXCEPTION 'health issue target binding is invalid' USING ERRCODE = '23514';
    END IF;
    IF NEW.repair_proposal_id IS NOT NULL THEN
        SELECT workspace_id, proposal_type INTO proposal_workspace, proposal_type_value
          FROM change_control.proposal WHERE id=NEW.repair_proposal_id FOR SHARE;
        IF proposal_workspace IS NULL OR proposal_workspace <> NEW.workspace_id OR proposal_type_value <> 'knowledge_change' THEN
            RAISE EXCEPTION 'health issue proposal binding is invalid' USING ERRCODE = '23514';
        END IF;
    END IF;
    IF TG_OP = 'UPDATE'
       AND NEW.id = OLD.id
       AND NEW.workspace_id = OLD.workspace_id
       AND NEW.type = OLD.type
       AND NEW.target_type = OLD.target_type
       AND NEW.target_id = OLD.target_id
       AND NEW.detector_id = OLD.detector_id
       AND NEW.identity_hash = OLD.identity_hash
       AND NEW.fingerprint_schema_version = OLD.fingerprint_schema_version
       AND NEW.fingerprint = OLD.fingerprint
       AND NEW.detector_version = OLD.detector_version
       AND NEW.severity = OLD.severity
       AND NEW.evidence_summary = OLD.evidence_summary
       AND NEW.status = OLD.status
       AND NEW.status_reason IS NOT DISTINCT FROM OLD.status_reason
       AND NEW.deferred_until IS NOT DISTINCT FROM OLD.deferred_until
       AND NEW.repair_proposal_id IS NOT DISTINCT FROM OLD.repair_proposal_id
       AND NEW.repair_option_code IS NOT DISTINCT FROM OLD.repair_option_code
       AND NEW.repair_binding_fingerprint IS NOT DISTINCT FROM OLD.repair_binding_fingerprint
       AND NEW.repair_binding_object_versions IS NOT DISTINCT FROM OLD.repair_binding_object_versions
       AND NEW.repair_proposal_created_at IS NOT DISTINCT FROM OLD.repair_proposal_created_at
       AND NEW.version = OLD.version
       AND NEW.first_detected_at = OLD.first_detected_at
       AND NEW.last_detected_at = OLD.last_detected_at
       AND NEW.last_verified_at >= OLD.last_verified_at
       AND NEW.resolved_at IS NOT DISTINCT FROM OLD.resolved_at
       AND NEW.created_at = OLD.created_at
       AND NEW.updated_at = OLD.updated_at THEN
        RETURN NEW;
    END IF;
    IF TG_OP = 'INSERT' THEN
        IF NEW.version <> 1 OR NEW.status <> 'OPEN' THEN
            RAISE EXCEPTION 'health issue must start open at version one' USING ERRCODE = '23514';
        END IF;
        RETURN NEW;
    END IF;
    IF NEW.id <> OLD.id
       OR NEW.workspace_id <> OLD.workspace_id
       OR NEW.type <> OLD.type
       OR NEW.target_type <> OLD.target_type
       OR NEW.target_id <> OLD.target_id
       OR NEW.detector_id <> OLD.detector_id
       OR NEW.identity_hash <> OLD.identity_hash
       OR NEW.first_detected_at <> OLD.first_detected_at
       OR NEW.created_at <> OLD.created_at
       OR NEW.updated_at < OLD.updated_at
       OR NEW.last_detected_at < OLD.last_detected_at
       OR NEW.last_verified_at < OLD.last_verified_at
       OR NEW.version <> OLD.version + 1 THEN
        RAISE EXCEPTION 'health issue immutable binding, time, or version changed' USING ERRCODE = '23514';
    END IF;
    IF OLD.status = 'RESOLVED' AND NEW.status <> 'REOPENED' THEN
        RAISE EXCEPTION 'resolved health issue can only reopen' USING ERRCODE = '23514';
    END IF;
    IF NEW.status = 'DEFERRED'
       AND (
           OLD.status <> 'DEFERRED'
           OR NEW.deferred_until IS DISTINCT FROM OLD.deferred_until
       )
       AND NEW.deferred_until <= GREATEST(CURRENT_TIMESTAMP, NEW.updated_at) THEN
        RAISE EXCEPTION 'health issue defer time must be in the future' USING ERRCODE = '23514';
    END IF;
    IF NEW.fingerprint IS DISTINCT FROM OLD.fingerprint THEN
        IF NEW.status <> 'REOPENED'
           OR NEW.status_reason IS NOT NULL
           OR NEW.deferred_until IS NOT NULL
           OR NEW.repair_proposal_id IS NOT NULL
           OR NEW.repair_option_code IS NOT NULL
           OR NEW.repair_binding_fingerprint IS NOT NULL
           OR NEW.repair_binding_object_versions IS NOT NULL
           OR NEW.repair_proposal_created_at IS NOT NULL
           OR NEW.resolved_at IS NOT NULL THEN
            RAISE EXCEPTION 'changed health issue fingerprint must reopen without stale bindings' USING ERRCODE = '23514';
        END IF;
    ELSIF OLD.status <> NEW.status AND NOT (
        (OLD.status IN ('OPEN','ACKNOWLEDGED','DEFERRED','PROPOSAL_CREATED','REOPENED')
            AND NEW.status IN ('ACKNOWLEDGED','DEFERRED','PROPOSAL_CREATED','IGNORED','FALSE_POSITIVE','RESOLVED'))
        OR (OLD.status IN ('IGNORED','FALSE_POSITIVE') AND NEW.status = 'RESOLVED')
        OR (OLD.status = 'RESOLVED' AND NEW.status = 'REOPENED')
    ) THEN
        RAISE EXCEPTION 'health issue status transition is invalid' USING ERRCODE = '23514';
    END IF;
    RETURN NEW;
END;
$$;


--
-- Name: validate_health_scan_detector_write(); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.validate_health_scan_detector_write() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF TG_OP = 'INSERT' THEN
        IF NEW.status <> 'PENDING'
           OR NEW.processed_count <> 0
           OR NEW.created_count <> 0
           OR NEW.reopened_count <> 0
           OR NEW.resolved_count <> 0
           OR NEW.unchanged_count <> 0
           OR NEW.failed_count <> 0 THEN
            RAISE EXCEPTION 'health detector coverage must start pending' USING ERRCODE = '23514';
        END IF;
        RETURN NEW;
    END IF;
    IF NEW.scan_id <> OLD.scan_id
       OR NEW.workspace_id <> OLD.workspace_id
       OR NEW.detector_id <> OLD.detector_id
       OR NEW.detector_version <> OLD.detector_version
       OR NEW.processed_count < OLD.processed_count
       OR NEW.created_count < OLD.created_count
       OR NEW.reopened_count < OLD.reopened_count
       OR NEW.resolved_count < OLD.resolved_count
       OR NEW.unchanged_count < OLD.unchanged_count
       OR NEW.failed_count < OLD.failed_count THEN
        RAISE EXCEPTION 'health detector immutable binding or counters changed invalidly' USING ERRCODE = '23514';
    END IF;
    IF OLD.status <> NEW.status AND NOT (
        (OLD.status='PENDING' AND NEW.status IN ('RUNNING','FAILED','CANCELLED','UNAVAILABLE'))
        OR (OLD.status='RUNNING' AND NEW.status IN ('SUCCEEDED','PARTIAL','FAILED','CANCELLED'))
    ) THEN
        RAISE EXCEPTION 'health detector transition is invalid' USING ERRCODE = '23514';
    END IF;
    IF OLD.status IN ('PARTIAL','FAILED','CANCELLED','UNAVAILABLE') THEN
        RAISE EXCEPTION 'terminal health detector coverage is immutable' USING ERRCODE = '55000';
    END IF;
    IF OLD.status = 'SUCCEEDED' AND (
        NEW.status <> 'SUCCEEDED'
        OR NEW.checkpoint <> OLD.checkpoint
        OR NEW.failure_summary IS DISTINCT FROM OLD.failure_summary
        OR NEW.unavailable_reason IS DISTINCT FROM OLD.unavailable_reason
        OR NEW.processed_count <> OLD.processed_count
        OR NEW.created_count <> OLD.created_count
        OR NEW.reopened_count <> OLD.reopened_count
        OR NEW.unchanged_count <> OLD.unchanged_count
        OR NEW.failed_count <> OLD.failed_count
        OR NEW.started_at IS DISTINCT FROM OLD.started_at
        OR NEW.completed_at IS DISTINCT FROM OLD.completed_at
    ) THEN
        RAISE EXCEPTION 'succeeded health detector only accepts resolved count finalization' USING ERRCODE = '55000';
    END IF;
    IF OLD.status = 'SUCCEEDED' AND NEW.resolved_count <> OLD.resolved_count THEN
        PERFORM 1
          FROM ops.health_scan scan
         WHERE scan.id = NEW.scan_id
           AND scan.workspace_id = NEW.workspace_id
           AND scan.status = 'RUNNING'
         FOR SHARE;
        IF NOT FOUND THEN
            RAISE EXCEPTION 'succeeded health detector can only finalize resolved count while scan is running' USING ERRCODE = '55000';
        END IF;
    END IF;
    RETURN NEW;
END;
$$;


--
-- Name: validate_health_scan_scope(uuid, text, uuid, bigint, text); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.validate_health_scan_scope(workspace_value uuid, scope_type_value text, scope_ref_value uuid, scope_version_value bigint, scope_hash_value text) RETURNS boolean
    LANGUAGE plpgsql
    AS $$
BEGIN
    CASE scope_type_value
        WHEN 'WORKSPACE' THEN RETURN EXISTS (
            SELECT 1 FROM core.workspace
             WHERE id=workspace_value
               AND id=scope_ref_value
               AND version=scope_version_value
        );
        WHEN 'TOPIC' THEN RETURN EXISTS (
            SELECT 1 FROM core.topic
             WHERE id=scope_ref_value
               AND workspace_id=workspace_value
               AND version=scope_version_value
        );
        WHEN 'SMART_COLLECTION' THEN RETURN EXISTS (
            SELECT 1 FROM learning.smart_collection
             WHERE id=scope_ref_value
               AND workspace_id=workspace_value
               AND version=scope_version_value
               AND query_hash=scope_hash_value
               AND status='ACTIVE'
        );
        ELSE RETURN false;
    END CASE;
END;
$$;


--
-- Name: validate_health_scan_write(); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.validate_health_scan_write() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF TG_OP = 'INSERT' THEN
        IF NOT ops.validate_health_scan_scope(
            NEW.workspace_id,
            NEW.scope_type,
            NEW.scope_ref,
            NEW.scope_version,
            NEW.scope_hash
        ) THEN
            RAISE EXCEPTION 'health scan scope binding is invalid' USING ERRCODE = '23514';
        END IF;
        IF NEW.version <> 1 OR NEW.status NOT IN ('PENDING', 'RUNNING') THEN
            RAISE EXCEPTION 'health scan must start pending or running at version one' USING ERRCODE = '23514';
        END IF;
        RETURN NEW;
    END IF;
    IF NEW.id <> OLD.id
       OR NEW.workspace_id <> OLD.workspace_id
       OR NEW.scope_type <> OLD.scope_type
       OR NEW.scope_ref <> OLD.scope_ref
       OR NEW.scope_version <> OLD.scope_version
       OR NEW.scope_schema_version <> OLD.scope_schema_version
       OR NEW.scope_hash IS DISTINCT FROM OLD.scope_hash
       OR NEW.scope_read_model_revision IS DISTINCT FROM OLD.scope_read_model_revision
       OR NEW.scope_exact_count IS DISTINCT FROM OLD.scope_exact_count
       OR NEW.fingerprint <> OLD.fingerprint
       OR NEW.idempotency_key <> OLD.idempotency_key
       OR NEW.request_hash <> OLD.request_hash
       OR NEW.workflow_run_id <> OLD.workflow_run_id
       OR NEW.max_items <> OLD.max_items
       OR NEW.created_at <> OLD.created_at
       OR NEW.updated_at < OLD.updated_at
       OR NEW.version <> OLD.version + 1 THEN
        RAISE EXCEPTION 'health scan immutable binding or version changed' USING ERRCODE = '23514';
    END IF;
    IF NEW.processed_count < OLD.processed_count
       OR NEW.created_count < OLD.created_count
       OR NEW.reopened_count < OLD.reopened_count
       OR NEW.resolved_count < OLD.resolved_count
       OR NEW.unchanged_count < OLD.unchanged_count
       OR NEW.failed_count < OLD.failed_count THEN
        RAISE EXCEPTION 'health scan counters cannot decrease' USING ERRCODE = '23514';
    END IF;
    IF OLD.status <> NEW.status AND NOT (
        (OLD.status='PENDING' AND NEW.status IN ('RUNNING','FAILED','CANCELLED'))
        OR (OLD.status='RUNNING' AND NEW.status IN ('SUCCEEDED','PARTIAL','FAILED','CANCELLED'))
    ) THEN
        RAISE EXCEPTION 'health scan transition is invalid' USING ERRCODE = '23514';
    END IF;
    IF OLD.status IN ('SUCCEEDED','PARTIAL','FAILED','CANCELLED') THEN
        RAISE EXCEPTION 'terminal health scan is immutable' USING ERRCODE = '55000';
    END IF;
    RETURN NEW;
END;
$$;


--
-- Name: validate_health_schedule_write(); Type: FUNCTION; Schema: ops; Owner: -
--

CREATE FUNCTION ops.validate_health_schedule_write() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF TG_OP = 'INSERT' THEN
        IF NOT ops.validate_health_scan_scope(
            NEW.workspace_id,
            NEW.scope_type,
            NEW.scope_ref,
            NEW.scope_version,
            NEW.scope_hash
        ) THEN
            RAISE EXCEPTION 'health schedule scope binding is invalid' USING ERRCODE = '23514';
        END IF;
        IF NEW.version <> 1 THEN
            RAISE EXCEPTION 'health schedule must start at version one' USING ERRCODE = '23514';
        END IF;
        IF NEW.pending_due_at IS NOT NULL OR NEW.dispatch_lease_until IS NOT NULL THEN
            RAISE EXCEPTION 'health schedule cannot start with a pending delivery' USING ERRCODE = '23514';
        END IF;
        RETURN NEW;
    END IF;
    IF NEW.id <> OLD.id
       OR NEW.workspace_id <> OLD.workspace_id
       OR NEW.scope_type <> OLD.scope_type
       OR NEW.scope_ref <> OLD.scope_ref
       OR NEW.scope_version <> OLD.scope_version
       OR NEW.scope_schema_version <> OLD.scope_schema_version
       OR NEW.scope_hash IS DISTINCT FROM OLD.scope_hash
       OR NEW.created_at <> OLD.created_at
       OR NEW.updated_at < OLD.updated_at
       OR (OLD.last_run_at IS NOT NULL AND NEW.last_run_at IS NULL)
       OR (OLD.last_run_at IS NOT NULL AND NEW.last_run_at < OLD.last_run_at)
       OR NEW.version <> OLD.version + 1 THEN
        RAISE EXCEPTION 'health schedule immutable binding, time, or version changed' USING ERRCODE = '23514';
    END IF;

    IF OLD.pending_due_at IS NULL AND NEW.pending_due_at IS NOT NULL THEN
        IF OLD.next_run_at IS NULL
           OR NEW.pending_due_at IS DISTINCT FROM OLD.next_run_at
           OR NEW.next_run_at IS NULL
           OR NEW.next_run_at <= NEW.pending_due_at
           OR NEW.dispatch_lease_until <= NEW.updated_at
           OR NEW.last_run_at IS DISTINCT FROM OLD.last_run_at
           OR NEW.cadence IS DISTINCT FROM OLD.cadence
           OR NEW.cron_expression IS DISTINCT FROM OLD.cron_expression
           OR NEW.timezone IS DISTINCT FROM OLD.timezone
           OR NEW.max_items IS DISTINCT FROM OLD.max_items THEN
            RAISE EXCEPTION 'health schedule initial delivery claim is invalid' USING ERRCODE = '23514';
        END IF;
        RETURN NEW;
    END IF;

    IF OLD.pending_due_at IS NOT NULL AND NEW.pending_due_at IS NOT NULL THEN
        IF NEW.pending_due_at IS DISTINCT FROM OLD.pending_due_at
           OR NEW.next_run_at IS DISTINCT FROM OLD.next_run_at
           OR NEW.last_run_at IS DISTINCT FROM OLD.last_run_at
           OR NEW.dispatch_lease_until < NEW.updated_at
           OR NEW.cadence IS DISTINCT FROM OLD.cadence
           OR NEW.cron_expression IS DISTINCT FROM OLD.cron_expression
           OR NEW.timezone IS DISTINCT FROM OLD.timezone
           OR NEW.max_items IS DISTINCT FROM OLD.max_items THEN
            RAISE EXCEPTION 'health schedule pending delivery mutation is invalid' USING ERRCODE = '55000';
        END IF;
        RETURN NEW;
    END IF;

    IF OLD.pending_due_at IS NOT NULL AND NEW.pending_due_at IS NULL THEN
        IF NEW.dispatch_lease_until IS NOT NULL
           OR NEW.last_run_at IS DISTINCT FROM OLD.pending_due_at
           OR NEW.next_run_at IS DISTINCT FROM OLD.next_run_at
           OR NEW.cadence IS DISTINCT FROM OLD.cadence
           OR NEW.cron_expression IS DISTINCT FROM OLD.cron_expression
           OR NEW.timezone IS DISTINCT FROM OLD.timezone
           OR NEW.max_items IS DISTINCT FROM OLD.max_items THEN
            RAISE EXCEPTION 'health schedule delivery acknowledgement is invalid' USING ERRCODE = '55000';
        END IF;
        RETURN NEW;
    END IF;

    IF NEW.dispatch_lease_until IS NOT NULL THEN
        RAISE EXCEPTION 'health schedule lease requires a pending due' USING ERRCODE = '23514';
    END IF;
    RETURN NEW;
END;
$$;


--
-- Name: guard_synthesis_execution(); Type: FUNCTION; Schema: organizing; Owner: -
--

CREATE FUNCTION organizing.guard_synthesis_execution() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF TG_OP='INSERT' THEN
        IF NEW.version<>1 OR NEW.input_document IS NOT NULL OR NEW.apply_node_run_id IS NOT NULL THEN
            RAISE EXCEPTION 'synthesis execution must start without results' USING ERRCODE='23514';
        END IF;
        IF NOT EXISTS (SELECT 1 FROM workflow.run r JOIN workflow.definition d ON d.id=r.definition_id AND d.workspace_id=r.workspace_id
            WHERE r.id=NEW.workflow_run_id AND r.workspace_id=NEW.workspace_id AND d.key='organizing.synthesis-note' AND d.version=1
              AND r.input->>'processing_id'=NEW.processing_id::text AND (r.input->>'execution_no')::integer=NEW.execution_no
              AND (r.input->>'apply_recovery')::boolean=NEW.apply_recovery) THEN
            RAISE EXCEPTION 'synthesis execution workflow binding is invalid' USING ERRCODE='23514';
        END IF;
        RETURN NEW;
    END IF;
    IF TG_OP='DELETE' OR NEW.workflow_run_id<>OLD.workflow_run_id OR NEW.workspace_id<>OLD.workspace_id OR NEW.processing_id<>OLD.processing_id
       OR NEW.execution_no<>OLD.execution_no OR NEW.apply_recovery<>OLD.apply_recovery OR NEW.created_at<>OLD.created_at
       OR NEW.version<>OLD.version+1 OR NEW.updated_at<OLD.updated_at
       OR (OLD.input_document IS NOT NULL AND (NEW.input_document IS DISTINCT FROM OLD.input_document OR NEW.input_hash IS DISTINCT FROM OLD.input_hash))
       OR OLD.applied_result IS NOT NULL THEN
        RAISE EXCEPTION 'synthesis execution immutable result changed' USING ERRCODE='55000';
    END IF;
    IF NEW.applied_result IS NOT NULL AND NOT EXISTS (
        SELECT 1 FROM organizing.synthesis_apply_receipt receipt
        WHERE receipt.workspace_id=NEW.workspace_id AND receipt.processing_id=NEW.processing_id
          AND (NEW.apply_recovery OR receipt.workflow_run_id=NEW.workflow_run_id)
          AND receipt.result=NEW.applied_result
    ) THEN
        RAISE EXCEPTION 'synthesis execution result requires its immutable application receipt' USING ERRCODE='23514';
    END IF;
    RETURN NEW;
END;
$$;


--
-- Name: guard_synthesis_model_step(); Type: FUNCTION; Schema: organizing; Owner: -
--

CREATE FUNCTION organizing.guard_synthesis_model_step() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF TG_OP='INSERT' THEN
        IF NEW.status<>'RUNNING' OR NEW.version<>1 OR NEW.model_run_id IS NOT NULL THEN
            RAISE EXCEPTION 'synthesis model step must start unbound' USING ERRCODE='23514';
        END IF;
        IF NOT EXISTS (SELECT 1 FROM organizing.synthesis_execution e JOIN workflow.node_run n ON n.run_id=e.workflow_run_id
            WHERE e.workflow_run_id=NEW.workflow_run_id AND e.workspace_id=NEW.workspace_id AND e.processing_id=NEW.processing_id
              AND NOT e.apply_recovery AND e.input_hash=NEW.input_request_hash AND n.id=NEW.node_run_id
              AND ((NEW.stage='GENERATE' AND n.node_type='organizing.synthesis.generate') OR (NEW.stage='VALIDATE' AND n.node_type='organizing.synthesis.validate'))) THEN
            RAISE EXCEPTION 'synthesis model step input binding is invalid' USING ERRCODE='23514';
        END IF;
        RETURN NEW;
    END IF;
    IF TG_OP='DELETE' OR OLD.status<>'RUNNING' OR NEW.id<>OLD.id OR NEW.workspace_id<>OLD.workspace_id OR NEW.processing_id<>OLD.processing_id
       OR NEW.workflow_run_id<>OLD.workflow_run_id OR NEW.node_run_id<>OLD.node_run_id OR NEW.node_attempt_id<>OLD.node_attempt_id
       OR NEW.stage<>OLD.stage OR NEW.request_hash<>OLD.request_hash OR NEW.input_request_hash<>OLD.input_request_hash
       OR NEW.generation_output_hash IS DISTINCT FROM OLD.generation_output_hash OR NEW.model_settings_revision IS DISTINCT FROM OLD.model_settings_revision
       OR NEW.created_at<>OLD.created_at OR NEW.version<>OLD.version+1 OR NEW.updated_at<OLD.updated_at
       OR (OLD.model_run_id IS NOT NULL AND NEW.model_run_id IS DISTINCT FROM OLD.model_run_id)
       OR (NEW.status='RUNNING' AND (OLD.model_run_id IS NOT NULL OR NEW.model_run_id IS NULL)) THEN
        RAISE EXCEPTION 'synthesis model step transition is invalid' USING ERRCODE='55000';
    END IF;
    IF NEW.model_run_id IS NOT NULL AND NOT EXISTS (
        SELECT 1 FROM agent.model_run r WHERE r.id=NEW.model_run_id AND r.workspace_id=NEW.workspace_id
          AND r.workflow_run_id=NEW.workflow_run_id AND r.node_run_id=NEW.node_run_id AND r.node_attempt_id=NEW.node_attempt_id
          AND r.model_settings_revision IS NOT DISTINCT FROM NEW.model_settings_revision
          AND ((NEW.stage='GENERATE' AND r.output_schema_id='agent.synthesis-delta') OR (NEW.stage='VALIDATE' AND r.output_schema_id='agent.synthesis-semantic-review'))
          AND r.output_schema_version='v1'
          AND ((NEW.status='RUNNING' AND r.status='RUNNING')
            OR (NEW.status='FAILED' AND r.status='FAILED')
            OR (NEW.status='RECOVERY_REQUIRED' AND r.status='UNKNOWN')
            OR (NEW.status='READY' AND r.status='SUCCEEDED' AND ((NEW.stage='GENERATE' AND r.final_result_type='synthesis_delta') OR (NEW.stage='VALIDATE' AND r.final_result_type='synthesis_semantic_review'))))
    ) THEN
        RAISE EXCEPTION 'synthesis model step requires its exact ModelRun proof' USING ERRCODE='23514';
    END IF;
    RETURN NEW;
END;
$$;


--
-- Name: guard_synthesis_processing(); Type: FUNCTION; Schema: organizing; Owner: -
--

CREATE FUNCTION organizing.guard_synthesis_processing() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF TG_OP='INSERT' THEN
        IF NEW.version<>1 OR NEW.status NOT IN ('PENDING','SKIPPED') OR NEW.model_run_id IS NOT NULL THEN
            RAISE EXCEPTION 'synthesis processing must begin pending or skipped' USING ERRCODE='23514';
        END IF;
        IF NOT EXISTS (SELECT 1 FROM workflow.outbox_event e
            JOIN core.source_version v ON v.id=NEW.source_version_id AND v.source_id=NEW.source_id
            JOIN ingestion.parse_projection p ON p.id=NEW.parse_projection_id AND p.workspace_id=NEW.workspace_id
            WHERE e.id=NEW.source_event_id AND e.workspace_id=NEW.workspace_id AND e.event_type='ingestion.source.ready'
              AND e.payload->>'source_id'=NEW.source_id::text AND e.payload->>'source_version_id'=NEW.source_version_id::text
              AND e.payload->>'content_artifact_id'=NEW.content_artifact_id::text AND e.payload->>'parse_projection_id'=NEW.parse_projection_id::text
              AND e.payload->>'content_hash'=NEW.source_content_hash
              AND e.payload->>'ingestion_attempt_id'=NEW.ingestion_attempt_id::text AND e.occurred_at=NEW.source_occurred_at
              AND v.content_hash=NEW.source_content_hash AND v.content_artifact_id=NEW.content_artifact_id
              AND p.content_artifact_id=NEW.content_artifact_id) THEN
            RAISE EXCEPTION 'synthesis processing source event binding is invalid' USING ERRCODE='23514';
        END IF;
        RETURN NEW;
    END IF;
    IF TG_OP='DELETE' OR NEW.id<>OLD.id OR NEW.workspace_id<>OLD.workspace_id
       OR NEW.source_event_id<>OLD.source_event_id OR NEW.source_id<>OLD.source_id OR NEW.source_version_id<>OLD.source_version_id
       OR NEW.content_artifact_id<>OLD.content_artifact_id OR NEW.parse_projection_id<>OLD.parse_projection_id
       OR NEW.source_content_hash<>OLD.source_content_hash OR NEW.ingestion_attempt_id<>OLD.ingestion_attempt_id
       OR NEW.processor_version<>OLD.processor_version OR NEW.source_occurred_at<>OLD.source_occurred_at
       OR NEW.processing_key<>OLD.processing_key OR NEW.request_hash<>OLD.request_hash OR NEW.created_at<>OLD.created_at
       OR NEW.version<>OLD.version+1 OR NEW.updated_at<OLD.updated_at OR OLD.status IN ('SUCCEEDED','NO_CHANGE','SKIPPED','RECOVERY_REQUIRED') THEN
        RAISE EXCEPTION 'synthesis processing transition is invalid' USING ERRCODE='55000';
    END IF;
    IF OLD.status='FAILED' THEN
        IF NOT OLD.retryable OR NEW.status<>'PENDING' OR NEW.workflow_run_id=OLD.workflow_run_id OR NEW.model_run_id IS NOT NULL THEN
            RAISE EXCEPTION 'synthesis processing retry is invalid' USING ERRCODE='55000';
        END IF;
    ELSIF NEW.workflow_run_id IS DISTINCT FROM OLD.workflow_run_id THEN
        RAISE EXCEPTION 'synthesis processing active run is immutable' USING ERRCODE='55000';
    END IF;
    IF NEW.status IN ('SUCCEEDED','NO_CHANGE') AND NOT EXISTS (
        SELECT 1 FROM organizing.synthesis_execution e JOIN workflow.run r ON r.id=e.workflow_run_id AND r.workspace_id=e.workspace_id
        WHERE e.processing_id=NEW.id AND e.workspace_id=NEW.workspace_id AND e.workflow_run_id=NEW.workflow_run_id
          AND r.status='succeeded' AND e.applied_result IS NOT NULL
          AND e.applied_result->'revision_ids'=NEW.revision_ids
          AND (e.applied_result->>'changed')::boolean=(NEW.status='SUCCEEDED')
    ) THEN
        RAISE EXCEPTION 'synthesis processing success requires Workflow application proof' USING ERRCODE='23514';
    END IF;
    RETURN NEW;
END;
$$;


--
-- Name: reject_immutable_mutation(); Type: FUNCTION; Schema: organizing; Owner: -
--

CREATE FUNCTION organizing.reject_immutable_mutation() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    RAISE EXCEPTION 'organizing immutable fact cannot be mutated' USING ERRCODE='55000';
END;
$$;


--
-- Name: synthesis_item_sources(jsonb); Type: FUNCTION; Schema: organizing; Owner: -
--

CREATE FUNCTION organizing.synthesis_item_sources(items jsonb) RETURNS SETOF jsonb
    LANGUAGE sql IMMUTABLE STRICT
    AS $$
    SELECT DISTINCT refs.source
    FROM jsonb_array_elements(items) item
    CROSS JOIN LATERAL (
        SELECT value AS source FROM jsonb_array_elements(COALESCE(item->'fact'->'sources','[]'::jsonb))
        UNION ALL
        SELECT source.value FROM jsonb_array_elements(COALESCE(item->'conflict'->'alternatives','[]'::jsonb)) alternative
            CROSS JOIN LATERAL jsonb_array_elements(COALESCE(alternative->'sources','[]'::jsonb)) source
        UNION ALL
        SELECT value FROM jsonb_array_elements(COALESCE(item->'gap'->'sources','[]'::jsonb))
        UNION ALL
        SELECT value FROM jsonb_array_elements(COALESCE(item->'gap'->'resolution'->'sources','[]'::jsonb))
    ) refs;
$$;


--
-- Name: valid_evidence(jsonb); Type: FUNCTION; Schema: organizing; Owner: -
--

CREATE FUNCTION organizing.valid_evidence(value jsonb) RETURNS boolean
    LANGUAGE plpgsql IMMUTABLE
    AS $_$
DECLARE
    item jsonb;
    key_count integer;
    index_version text := NULL;
    item_key text;
    seen_keys text[] := ARRAY[]::text[];
    uuid_pattern constant text := '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$';
    hash_pattern constant text := '^[0-9a-f]{64}$';
BEGIN
    IF value IS NULL OR jsonb_typeof(value)<>'array' OR jsonb_array_length(value)>100 THEN
        RETURN false;
    END IF;
    FOR item IN SELECT element FROM jsonb_array_elements(value) AS elements(element)
    LOOP
        IF jsonb_typeof(item)<>'object' THEN
            RETURN false;
        END IF;
        SELECT count(*) INTO key_count FROM jsonb_object_keys(item);
        IF key_count<>6
           OR NOT (item ?& ARRAY[
                'index_version_id','chunk_id','source_version_id','source_span_id',
                'content_hash','excerpt_hash'
           ])
           OR jsonb_typeof(item->'index_version_id')<>'string'
           OR jsonb_typeof(item->'chunk_id')<>'string'
           OR jsonb_typeof(item->'source_version_id')<>'string'
           OR jsonb_typeof(item->'source_span_id')<>'string'
           OR jsonb_typeof(item->'content_hash')<>'string'
           OR jsonb_typeof(item->'excerpt_hash')<>'string'
           OR item->>'index_version_id' !~ uuid_pattern
           OR item->>'chunk_id' !~ uuid_pattern
           OR item->>'source_version_id' !~ uuid_pattern
           OR item->>'source_span_id' !~ uuid_pattern
           OR item->>'content_hash' !~ hash_pattern
           OR item->>'excerpt_hash' !~ hash_pattern THEN
            RETURN false;
        END IF;
        IF index_version IS NULL THEN
            index_version := item->>'index_version_id';
        ELSIF index_version<>item->>'index_version_id' THEN
            RETURN false;
        END IF;
        item_key := item::text;
        IF item_key=ANY(seen_keys) THEN
            RETURN false;
        END IF;
        seen_keys := array_append(seen_keys,item_key);
    END LOOP;
    RETURN true;
END;
$_$;


--
-- Name: valid_material_shape(text, uuid, uuid, uuid, uuid, uuid, uuid, uuid, bigint, text, text, text, jsonb, boolean); Type: FUNCTION; Schema: organizing; Owner: -
--

CREATE FUNCTION organizing.valid_material_shape(material_kind text, source_version_id uuid, document_id uuid, article_revision_id uuid, claim_id uuid, collection_id uuid, origin_collection_id uuid, profile_revision_id uuid, material_version bigint, content_hash text, query_hash text, read_model_revision text, evidence jsonb, allow_collection_origin boolean) RETURNS boolean
    LANGUAGE plpgsql IMMUTABLE
    AS $_$
DECLARE
    hash_pattern constant text := '^[0-9a-f]{64}$';
BEGIN
    IF NOT organizing.valid_evidence(evidence)
       OR (origin_collection_id IS NOT NULL AND NOT allow_collection_origin)
       OR (origin_collection_id IS NOT NULL AND material_kind='SMART_COLLECTION') THEN
        RETURN false;
    END IF;
    RETURN COALESCE(CASE material_kind
        WHEN 'SOURCE_VERSION' THEN
            source_version_id IS NOT NULL AND material_version=0
            AND content_hash ~ hash_pattern
            AND document_id IS NULL AND article_revision_id IS NULL
            AND claim_id IS NULL AND collection_id IS NULL
            AND query_hash IS NULL AND read_model_revision IS NULL
        WHEN 'DOCUMENT_REVISION' THEN
            document_id IS NOT NULL AND article_revision_id IS NOT NULL
            AND material_version>0 AND content_hash ~ hash_pattern
            AND source_version_id IS NULL AND claim_id IS NULL
            AND collection_id IS NULL AND profile_revision_id IS NULL
            AND query_hash IS NULL AND read_model_revision IS NULL
        WHEN 'CLAIM' THEN
            claim_id IS NOT NULL AND material_version>0
            AND content_hash ~ hash_pattern AND jsonb_array_length(evidence)>0
            AND source_version_id IS NULL AND document_id IS NULL
            AND article_revision_id IS NULL AND collection_id IS NULL
            AND profile_revision_id IS NULL AND query_hash IS NULL
            AND read_model_revision IS NULL
        WHEN 'SMART_COLLECTION' THEN
            collection_id IS NOT NULL AND material_version>0
            AND query_hash ~ hash_pattern AND read_model_revision ~ hash_pattern
            AND source_version_id IS NULL AND document_id IS NULL
            AND article_revision_id IS NULL AND claim_id IS NULL
            AND origin_collection_id IS NULL AND profile_revision_id IS NULL
            AND content_hash IS NULL AND jsonb_array_length(evidence)=0
        ELSE false
    END,false);
END;
$_$;


--
-- Name: valid_reason_codes(text[]); Type: FUNCTION; Schema: organizing; Owner: -
--

CREATE FUNCTION organizing.valid_reason_codes(value text[]) RETURNS boolean
    LANGUAGE plpgsql IMMUTABLE
    AS $$
DECLARE
    reason text;
    seen text[] := ARRAY[]::text[];
BEGIN
    IF value IS NULL OR cardinality(value)<1 OR cardinality(value)>8 THEN
        RETURN false;
    END IF;
    FOREACH reason IN ARRAY value
    LOOP
        IF reason IS NULL OR reason NOT IN (
            'HYBRID_MATCH','PROFILE_MATCH','ALIAS_MATCH','FORMAL_KNOWLEDGE',
            'COLLECTION_MEMBER','USER_ADDED'
        ) OR reason=ANY(seen) THEN
            RETURN false;
        END IF;
        seen := array_append(seen,reason);
    END LOOP;
    RETURN true;
END;
$$;


--
-- Name: validate_draft_current_version(); Type: FUNCTION; Schema: organizing; Owner: -
--

CREATE FUNCTION organizing.validate_draft_current_version() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF NOT EXISTS (
        SELECT 1 FROM organizing.draft_version AS version
         WHERE version.workspace_id=NEW.workspace_id AND version.draft_id=NEW.id
           AND version.version=NEW.version AND version.intent=NEW.intent
           AND version.status=NEW.status
           AND version.template_revision_id IS NOT DISTINCT FROM NEW.template_revision_id
           AND version.confirmed_snapshot_id IS NOT DISTINCT FROM NEW.confirmed_snapshot_id
           AND version.draft_created_at=NEW.created_at AND version.updated_at=NEW.updated_at
    ) THEN
        RAISE EXCEPTION 'organizing draft current version is inconsistent' USING ERRCODE='23514';
    END IF;
    RETURN NULL;
END;
$$;


--
-- Name: validate_draft_version_insert(); Type: FUNCTION; Schema: organizing; Owner: -
--

CREATE FUNCTION organizing.validate_draft_version_insert() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    current_version bigint;
    current_status text;
    current_created_at timestamptz;
    previous_updated_at timestamptz;
BEGIN
    SELECT version,status,created_at INTO current_version,current_status,current_created_at
      FROM organizing.draft
     WHERE id=NEW.draft_id AND workspace_id=NEW.workspace_id;
    IF NOT FOUND OR current_created_at<>NEW.draft_created_at THEN
        RAISE EXCEPTION 'organizing draft version owner is invalid' USING ERRCODE='23514';
    END IF;
    IF NEW.template_revision_id IS NOT NULL AND NOT EXISTS (
        SELECT 1
          FROM organizing.template_revision AS revision
          JOIN organizing.template AS template ON template.id=revision.template_id
         WHERE revision.id=NEW.template_revision_id
           AND (template.workspace_id=NEW.workspace_id OR template.workspace_id IS NULL)
    ) THEN
        RAISE EXCEPTION 'organizing draft template revision is not visible' USING ERRCODE='23514';
    END IF;
    IF NEW.version=1 THEN
        IF current_version<>1 OR NEW.status<>'EDITING' OR NEW.confirmed_snapshot_id IS NOT NULL THEN
            RAISE EXCEPTION 'organizing draft version one is invalid' USING ERRCODE='23514';
        END IF;
        RETURN NEW;
    END IF;
    SELECT updated_at INTO previous_updated_at
      FROM organizing.draft_version
     WHERE workspace_id=NEW.workspace_id AND draft_id=NEW.draft_id AND version=NEW.version-1
       AND status='EDITING';
    IF NOT FOUND OR current_version<>NEW.version-1 OR current_status<>'EDITING'
       OR NEW.updated_at<previous_updated_at THEN
        RAISE EXCEPTION 'organizing draft version sequence is invalid' USING ERRCODE='23514';
    END IF;
    IF NEW.status='CONFIRMED' AND NOT EXISTS (
        SELECT 1
          FROM organizing.workflow_input_snapshot AS snapshot
         WHERE snapshot.id=NEW.confirmed_snapshot_id
           AND snapshot.workspace_id=NEW.workspace_id
           AND snapshot.draft_id=NEW.draft_id
           AND snapshot.draft_version=NEW.version-1
           AND snapshot.template_revision_id=NEW.template_revision_id
    ) THEN
        RAISE EXCEPTION 'organizing confirmed draft snapshot is invalid' USING ERRCODE='23514';
    END IF;
    RETURN NEW;
END;
$$;


--
-- Name: validate_draft_write(); Type: FUNCTION; Schema: organizing; Owner: -
--

CREATE FUNCTION organizing.validate_draft_write() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF TG_OP='INSERT' THEN
        IF NEW.version<>1 OR NEW.status<>'EDITING' OR NEW.confirmed_snapshot_id IS NOT NULL THEN
            RAISE EXCEPTION 'organizing draft must start editable at version one' USING ERRCODE='23514';
        END IF;
        RETURN NEW;
    END IF;
    IF TG_OP='DELETE'
       OR NEW.id<>OLD.id OR NEW.workspace_id<>OLD.workspace_id
       OR NEW.created_at<>OLD.created_at OR NEW.version<>OLD.version+1
       OR NEW.updated_at<OLD.updated_at OR OLD.status<>'EDITING'
       OR NEW.status NOT IN ('EDITING','CONFIRMED') THEN
        RAISE EXCEPTION 'organizing draft transition is invalid' USING ERRCODE='55000';
    END IF;
    RETURN NEW;
END;
$$;


--
-- Name: validate_generation_write(); Type: FUNCTION; Schema: organizing; Owner: -
--

CREATE FUNCTION organizing.validate_generation_write() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF TG_OP='INSERT' THEN
        IF NEW.status<>'RUNNING' OR NEW.version<>1 OR NEW.model_run_id IS NOT NULL THEN
            RAISE EXCEPTION 'organizing generation must start unbound and running' USING ERRCODE='23514';
        END IF;
        IF NOT EXISTS (
            SELECT 1
              FROM organizing.run_binding
             WHERE workspace_id=NEW.workspace_id
               AND snapshot_id=NEW.snapshot_id
               AND workflow_run_id=NEW.workflow_run_id
        ) THEN
            RAISE EXCEPTION 'organizing generation run binding is invalid' USING ERRCODE='23514';
        END IF;
        RETURN NEW;
    END IF;
    IF TG_OP='DELETE' OR OLD.status<>'RUNNING'
       OR NEW.id<>OLD.id OR NEW.workspace_id<>OLD.workspace_id
       OR NEW.snapshot_id<>OLD.snapshot_id OR NEW.workflow_run_id<>OLD.workflow_run_id
       OR NEW.node_run_id<>OLD.node_run_id OR NEW.node_attempt_id<>OLD.node_attempt_id
       OR NEW.generation_kind<>OLD.generation_kind OR NEW.request_hash<>OLD.request_hash
       OR NEW.model_settings_revision IS DISTINCT FROM OLD.model_settings_revision
       OR NEW.created_at<>OLD.created_at OR NEW.version<>OLD.version+1
       OR NEW.updated_at<OLD.updated_at THEN
        RAISE EXCEPTION 'organizing generation transition is invalid' USING ERRCODE='55000';
    END IF;
    IF NEW.status='RUNNING' THEN
        IF OLD.model_run_id IS NOT NULL OR NEW.model_run_id IS NULL
           OR NEW.completed_at IS NOT NULL OR NEW.output_document IS NOT NULL
           OR NEW.output_hash IS NOT NULL OR NEW.error_code IS NOT NULL OR NEW.retryable THEN
            RAISE EXCEPTION 'organizing generation model binding is invalid' USING ERRCODE='55000';
        END IF;
    ELSIF NEW.status IN ('READY','FAILED','RECOVERY_REQUIRED') THEN
        IF OLD.model_run_id IS NULL OR NEW.model_run_id<>OLD.model_run_id OR NEW.completed_at IS NULL THEN
            RAISE EXCEPTION 'organizing generation terminal transition is invalid' USING ERRCODE='55000';
        END IF;
    ELSE
        RAISE EXCEPTION 'organizing generation status is invalid' USING ERRCODE='55000';
    END IF;
    RETURN NEW;
END;
$$;


--
-- Name: validate_run_binding_completion(); Type: FUNCTION; Schema: organizing; Owner: -
--

CREATE FUNCTION organizing.validate_run_binding_completion() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF NOT EXISTS (
        SELECT 1
          FROM organizing.workflow_start_outbox AS outbox
          JOIN organizing.workflow_input_snapshot AS snapshot
            ON snapshot.id=outbox.snapshot_id
           AND snapshot.workspace_id=outbox.workspace_id
          JOIN organizing.template_revision AS revision
            ON revision.id=snapshot.template_revision_id
         WHERE outbox.workspace_id=NEW.workspace_id
           AND outbox.snapshot_id=NEW.snapshot_id
           AND outbox.run_binding_id=NEW.id
           AND outbox.status='STARTED'
           AND outbox.template_revision_id=snapshot.template_revision_id
           AND outbox.template_kind=revision.kind
    ) THEN
        RAISE EXCEPTION 'organizing run binding has no completed start outbox' USING ERRCODE='23514';
    END IF;
    RETURN NULL;
END;
$$;


--
-- Name: validate_run_binding_insert(); Type: FUNCTION; Schema: organizing; Owner: -
--

CREATE FUNCTION organizing.validate_run_binding_insert() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF NOT EXISTS (
        SELECT 1
          FROM workflow.run AS run
          JOIN workflow.definition AS definition
            ON definition.id=run.definition_id
           AND definition.workspace_id=run.workspace_id
          JOIN organizing.workflow_input_snapshot AS snapshot
            ON snapshot.id=NEW.snapshot_id
           AND snapshot.workspace_id=NEW.workspace_id
          JOIN organizing.template_revision AS revision
            ON revision.id=snapshot.template_revision_id
         WHERE run.id=NEW.workflow_run_id
           AND run.workspace_id=NEW.workspace_id
           AND definition.key=NEW.definition_key
           AND definition.version=NEW.definition_version
           AND run.idempotency_key='snapshot:'||NEW.snapshot_id::text
           AND run.input=jsonb_build_object('snapshot_id',NEW.snapshot_id::text)
           AND NEW.definition_key=CASE revision.kind
                WHEN 'TOPIC_ARTICLE' THEN 'organizing.topic-article'
                WHEN 'MERGE_DOCUMENTS' THEN 'organizing.merge-documents'
                WHEN 'KNOWLEDGE_REPORT' THEN 'organizing.knowledge-report'
                WHEN 'INTERVIEW_REVIEW' THEN 'organizing.interview-review'
                ELSE NULL
           END
           AND NEW.definition_version=1
    ) THEN
        RAISE EXCEPTION 'organizing run binding definition is invalid' USING ERRCODE='23514';
    END IF;
    RETURN NEW;
END;
$$;


--
-- Name: validate_run_result_insert(); Type: FUNCTION; Schema: organizing; Owner: -
--

CREATE FUNCTION organizing.validate_run_result_insert() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF NOT EXISTS (
        SELECT 1
          FROM organizing.run_binding AS binding
          JOIN workflow.run AS run
            ON run.id=binding.workflow_run_id AND run.workspace_id=binding.workspace_id
          JOIN workflow.node_run AS node
            ON node.id=NEW.node_run_id AND node.run_id=run.id
          JOIN organizing.workflow_input_snapshot AS snapshot
            ON snapshot.id=binding.snapshot_id
           AND snapshot.workspace_id=binding.workspace_id
          JOIN organizing.template_revision AS revision
            ON revision.id=snapshot.template_revision_id
         WHERE binding.id=NEW.run_binding_id AND binding.workspace_id=NEW.workspace_id
           AND binding.snapshot_id=NEW.snapshot_id AND binding.workflow_run_id=NEW.workflow_run_id
           AND run.status='succeeded' AND node.status='succeeded'
           AND NEW.result_kind=CASE revision.kind
                WHEN 'MERGE_DOCUMENTS' THEN 'MERGE_PROPOSAL'
                WHEN 'TOPIC_ARTICLE' THEN 'ARTIFACT'
                WHEN 'KNOWLEDGE_REPORT' THEN 'ARTIFACT'
                WHEN 'INTERVIEW_REVIEW' THEN 'ARTIFACT'
                ELSE NULL
           END
           AND CASE NEW.result_kind
                WHEN 'ARTIFACT' THEN EXISTS (
                    SELECT 1
                      FROM learning.artifact AS artifact
                      JOIN learning.artifact_revision AS artifact_revision
                        ON artifact_revision.artifact_id=artifact.id
                       AND artifact_revision.workspace_id=artifact.workspace_id
                     WHERE artifact.id=NEW.result_ref
                       AND artifact.workspace_id=NEW.workspace_id
                       AND artifact_revision.content_hash=NEW.result_hash
                )
                WHEN 'MERGE_PROPOSAL' THEN EXISTS (
                    SELECT 1
                      FROM change_control.proposal AS proposal
                      JOIN change_control.proposal_revision AS proposal_revision
                        ON proposal_revision.proposal_id=proposal.id
                     WHERE proposal.id=NEW.result_ref
                       AND proposal.workspace_id=NEW.workspace_id
                       AND proposal.proposal_type='file_patch'
                       AND proposal_revision.change_hash=NEW.result_hash
                )
                ELSE false
           END
    ) THEN
        RAISE EXCEPTION 'organizing run result binding is invalid' USING ERRCODE='23514';
    END IF;
    RETURN NEW;
END;
$$;


--
-- Name: validate_snapshot_insert(); Type: FUNCTION; Schema: organizing; Owner: -
--

CREATE FUNCTION organizing.validate_snapshot_insert() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    PERFORM template.id
      FROM organizing.template AS template
      JOIN organizing.template_revision AS revision
        ON revision.id=NEW.template_revision_id
       AND revision.template_id=template.id
       AND revision.declaration_hash=NEW.template_hash
     WHERE template.id=NEW.template_id
       AND template.current_revision_id=revision.id
       AND (template.workspace_id=NEW.workspace_id OR template.workspace_id IS NULL)
       AND revision.workspace_id IS NOT DISTINCT FROM template.workspace_id
     FOR SHARE OF template;
    IF NOT FOUND THEN
        RAISE EXCEPTION 'organizing snapshot template binding is invalid' USING ERRCODE='23514';
    END IF;
    RETURN NEW;
END;
$$;


--
-- Name: validate_snapshot_material_origin(); Type: FUNCTION; Schema: organizing; Owner: -
--

CREATE FUNCTION organizing.validate_snapshot_material_origin() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF NEW.origin_collection_id IS NOT NULL AND NOT EXISTS (
        SELECT 1
          FROM organizing.workflow_input_material AS marker
         WHERE marker.workspace_id=NEW.workspace_id
           AND marker.snapshot_id=NEW.snapshot_id
           AND marker.kind='SMART_COLLECTION'
           AND marker.collection_id=NEW.origin_collection_id
           AND marker.origin_collection_id IS NULL
    ) THEN
        RAISE EXCEPTION 'organizing snapshot material collection origin is invalid' USING ERRCODE='23514';
    END IF;
    RETURN NULL;
END;
$$;


--
-- Name: validate_start_outbox_write(); Type: FUNCTION; Schema: organizing; Owner: -
--

CREATE FUNCTION organizing.validate_start_outbox_write() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF TG_OP='INSERT' THEN
        IF NEW.status<>'PENDING' OR NEW.version<>1 OR NEW.attempt_count<>0
           OR NEW.lease_owner IS NOT NULL OR NEW.lease_until IS NOT NULL
           OR NEW.last_error_code IS NOT NULL OR NOT EXISTS (
                SELECT 1
                  FROM organizing.workflow_input_snapshot AS snapshot
                  JOIN organizing.template_revision AS revision
                    ON revision.id=snapshot.template_revision_id
                 WHERE snapshot.id=NEW.snapshot_id
                   AND snapshot.workspace_id=NEW.workspace_id
                   AND snapshot.template_revision_id=NEW.template_revision_id
                   AND revision.kind=NEW.template_kind
           ) THEN
            RAISE EXCEPTION 'organizing start outbox insert is invalid' USING ERRCODE='23514';
        END IF;
        RETURN NEW;
    END IF;
    IF TG_OP='DELETE' OR OLD.status<>'PENDING'
       OR NEW.id<>OLD.id OR NEW.workspace_id<>OLD.workspace_id
       OR NEW.snapshot_id<>OLD.snapshot_id OR NEW.template_revision_id<>OLD.template_revision_id
       OR NEW.template_kind<>OLD.template_kind OR NEW.created_at<>OLD.created_at
       OR NEW.version<>OLD.version+1 OR NEW.updated_at<OLD.updated_at
       OR NEW.attempt_count<OLD.attempt_count OR NEW.attempt_count>OLD.attempt_count+1 THEN
        RAISE EXCEPTION 'organizing start outbox transition is invalid' USING ERRCODE='55000';
    END IF;
    IF NEW.status='PENDING' AND NEW.lease_owner IS NOT NULL THEN
        IF NEW.attempt_count<>OLD.attempt_count+1
           OR (OLD.lease_until IS NOT NULL AND OLD.lease_until>clock_timestamp()) THEN
            RAISE EXCEPTION 'organizing start outbox claim is invalid' USING ERRCODE='55000';
        END IF;
    ELSIF NEW.status='PENDING' AND NEW.lease_owner IS NULL THEN
        IF OLD.lease_owner IS NULL OR NEW.attempt_count<>OLD.attempt_count
           OR NEW.available_at<OLD.available_at OR NEW.last_error_code IS NULL THEN
            RAISE EXCEPTION 'organizing start outbox retry is invalid' USING ERRCODE='55000';
        END IF;
    ELSIF NEW.status='STARTED' THEN
        IF OLD.lease_owner IS NULL OR NEW.attempt_count<>OLD.attempt_count THEN
            RAISE EXCEPTION 'organizing start outbox completion is invalid' USING ERRCODE='55000';
        END IF;
    ELSIF NEW.status='POISONED' THEN
        IF NEW.attempt_count<>OLD.attempt_count
           OR (OLD.lease_owner IS NULL AND OLD.attempt_count<1000) THEN
            RAISE EXCEPTION 'organizing start outbox poison is invalid' USING ERRCODE='55000';
        END IF;
    ELSE
        RAISE EXCEPTION 'organizing start outbox state is invalid' USING ERRCODE='55000';
    END IF;
    RETURN NEW;
END;
$$;


--
-- Name: validate_synthesis_membership(); Type: FUNCTION; Schema: organizing; Owner: -
--

CREATE FUNCTION organizing.validate_synthesis_membership() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF TG_TABLE_NAME='synthesis_topic_key' THEN
        PERFORM 1 FROM organizing.synthesis_note
         WHERE id=NEW.note_id AND workspace_id=NEW.workspace_id
           AND (topic_key=NEW.topic_key OR NEW.topic_key=ANY(aliases));
    ELSE
        PERFORM 1 FROM organizing.synthesis_revision r
        CROSS JOIN LATERAL organizing.synthesis_item_sources(r.items) reference
         WHERE r.id=NEW.revision_id AND r.workspace_id=NEW.workspace_id AND r.note_id=NEW.note_id
           AND reference=jsonb_build_object('source',jsonb_build_object(
                'workspace_id',NEW.workspace_id,'source_id',NEW.source_id,'source_version_id',NEW.source_version_id,
                'content_artifact_id',NEW.content_artifact_id,'parse_projection_id',NEW.parse_projection_id,'content_hash',NEW.content_hash),
                'source_span_id',NEW.source_span_id,'excerpt_hash',NEW.excerpt_hash,'title',NEW.title);
    END IF;
    IF NOT FOUND THEN RAISE EXCEPTION 'synthesis child is outside its immutable projection' USING ERRCODE='23514'; END IF;
    RETURN NEW;
END;
$$;


--
-- Name: validate_synthesis_note_transition(); Type: FUNCTION; Schema: organizing; Owner: -
--

CREATE FUNCTION organizing.validate_synthesis_note_transition() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF TG_OP='DELETE' THEN RAISE EXCEPTION 'synthesis history cannot be deleted' USING ERRCODE='55000'; END IF;
    IF (NEW.id,NEW.workspace_id,NEW.document_id,NEW.topic_key,NEW.title,NEW.aliases,NEW.created_at)
       IS DISTINCT FROM (OLD.id,OLD.workspace_id,OLD.document_id,OLD.topic_key,OLD.title,OLD.aliases,OLD.created_at)
       OR NEW.version<>OLD.version+1 OR NEW.updated_at<OLD.updated_at THEN
        RAISE EXCEPTION 'synthesis identity or version changed' USING ERRCODE='23514';
    END IF;
    IF NEW.current_revision_id<>OLD.current_revision_id AND NOT EXISTS (
        SELECT 1 FROM organizing.synthesis_revision WHERE id=NEW.current_revision_id AND workspace_id=NEW.workspace_id
        AND note_id=NEW.id AND parent_revision_id=OLD.current_revision_id
    ) THEN RAISE EXCEPTION 'synthesis candidate does not extend current revision' USING ERRCODE='23514'; END IF;
    RETURN NEW;
END;
$$;


--
-- Name: validate_synthesis_revision(); Type: FUNCTION; Schema: organizing; Owner: -
--

CREATE FUNCTION organizing.validate_synthesis_revision() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE parent_record organizing.synthesis_revision%ROWTYPE;
BEGIN
    PERFORM 1 FROM organizing.synthesis_note
     WHERE id=NEW.note_id AND workspace_id=NEW.workspace_id AND document_id=NEW.document_id AND title=NEW.title FOR UPDATE;
    IF NOT FOUND THEN RAISE EXCEPTION 'synthesis note binding changed' USING ERRCODE='23514'; END IF;
    IF NEW.parent_revision_id IS NOT NULL THEN
        SELECT * INTO parent_record FROM organizing.synthesis_revision WHERE id=NEW.parent_revision_id;
        IF parent_record.revision_no<>NEW.revision_no-1 OR parent_record.article_revision_no<>NEW.article_revision_no-1
           OR parent_record.created_at>NEW.created_at THEN
            RAISE EXCEPTION 'synthesis revision parent changed' USING ERRCODE='23514';
        END IF;
    END IF;
    IF NEW.item_count<>jsonb_array_length(NEW.items)
       OR NEW.conflict_count<>(SELECT count(*) FROM jsonb_array_elements(NEW.items) item WHERE item->>'kind'='CONFLICT')
       OR NEW.gap_count<>(SELECT count(*) FROM jsonb_array_elements(NEW.items) item WHERE item->>'kind'='GAP')
       OR NEW.open_gap_count<>(SELECT count(*) FROM jsonb_array_elements(NEW.items) item WHERE item->>'kind'='GAP' AND item->'gap'->'resolution'='null'::jsonb) THEN
        RAISE EXCEPTION 'synthesis revision summary does not match its items' USING ERRCODE='23514';
    END IF;
    RETURN NEW;
END;
$$;


--
-- Name: validate_synthesis_source(); Type: FUNCTION; Schema: organizing; Owner: -
--

CREATE FUNCTION organizing.validate_synthesis_source() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF NOT EXISTS (
        SELECT 1 FROM core.source_version v
        JOIN core.content_artifact a ON a.id=v.content_artifact_id AND a.workspace_id=NEW.workspace_id AND a.content_hash=v.content_hash
        JOIN ingestion.parse_projection pp ON pp.id=NEW.parse_projection_id AND pp.workspace_id=NEW.workspace_id AND pp.content_artifact_id=a.id
        JOIN ingestion.source_span sp ON sp.id=NEW.source_span_id AND sp.workspace_id=NEW.workspace_id AND sp.content_artifact_id=a.id
         AND sp.parse_projection_id=pp.id AND sp.parser_version=pp.parser_version AND sp.schema_version=pp.schema_version
        WHERE v.id=NEW.source_version_id AND v.source_id=NEW.source_id AND v.workspace_id=NEW.workspace_id
          AND a.id=NEW.content_artifact_id AND v.content_hash=NEW.content_hash AND sp.excerpt_hash=NEW.excerpt_hash
    ) THEN RAISE EXCEPTION 'synthesis source tuple changed' USING ERRCODE='23514'; END IF;
    RETURN NEW;
END;
$$;


--
-- Name: validate_template_current_revision(); Type: FUNCTION; Schema: organizing; Owner: -
--

CREATE FUNCTION organizing.validate_template_current_revision() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF NOT EXISTS (
        SELECT 1 FROM organizing.template_revision AS revision
        WHERE revision.id=NEW.current_revision_id
          AND revision.template_id=NEW.id
          AND revision.workspace_id IS NOT DISTINCT FROM NEW.workspace_id
          AND revision.owner=NEW.owner AND revision.kind=NEW.kind
          AND revision.revision_no=NEW.version
    ) THEN
        RAISE EXCEPTION 'organizing template current revision is invalid' USING ERRCODE='23514';
    END IF;
    RETURN NULL;
END;
$$;


--
-- Name: validate_template_revision_insert(); Type: FUNCTION; Schema: organizing; Owner: -
--

CREATE FUNCTION organizing.validate_template_revision_insert() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    template_row organizing.template%ROWTYPE;
BEGIN
    SELECT * INTO template_row FROM organizing.template WHERE id=NEW.template_id;
    IF NOT FOUND OR template_row.owner<>NEW.owner OR template_row.kind<>NEW.kind
       OR template_row.workspace_id IS DISTINCT FROM NEW.workspace_id THEN
        RAISE EXCEPTION 'organizing template revision binding is invalid' USING ERRCODE='23514';
    END IF;
    RETURN NEW;
END;
$$;


--
-- Name: validate_template_write(); Type: FUNCTION; Schema: organizing; Owner: -
--

CREATE FUNCTION organizing.validate_template_write() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF TG_OP='INSERT' THEN
        IF NEW.version<>1 THEN
            RAISE EXCEPTION 'organizing template must start at version one' USING ERRCODE='23514';
        END IF;
        RETURN NEW;
    END IF;
    IF TG_OP='DELETE' OR OLD.owner='BUILT_IN'
       OR NEW.id<>OLD.id OR NEW.workspace_id IS DISTINCT FROM OLD.workspace_id
       OR NEW.owner<>OLD.owner OR NEW.kind<>OLD.kind OR NEW.created_at<>OLD.created_at
       OR NEW.current_revision_id=OLD.current_revision_id
       OR NEW.version<>OLD.version+1 OR NEW.updated_at<OLD.updated_at THEN
        RAISE EXCEPTION 'organizing template transition is invalid' USING ERRCODE='55000';
    END IF;
    RETURN NEW;
END;
$$;


--
-- Name: verify_synthesis_closure(); Type: FUNCTION; Schema: organizing; Owner: -
--

CREATE FUNCTION organizing.verify_synthesis_closure() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE expected_sources jsonb; actual_sources jsonb;
BEGIN
    IF TG_TABLE_NAME='synthesis_note' THEN
        IF (SELECT count(*) FROM organizing.synthesis_topic_key WHERE workspace_id=NEW.workspace_id AND note_id=NEW.id)
           <> cardinality(NEW.aliases)+1 OR EXISTS (
            SELECT 1 FROM organizing.synthesis_topic_key WHERE workspace_id=NEW.workspace_id AND note_id=NEW.id
             AND topic_key<>NEW.topic_key AND NOT topic_key=ANY(NEW.aliases)
        ) THEN RAISE EXCEPTION 'synthesis topic namespace is incomplete' USING ERRCODE='23514'; END IF;
    ELSE
        SELECT COALESCE(jsonb_agg(source ORDER BY source::text),'[]'::jsonb) INTO expected_sources
          FROM organizing.synthesis_item_sources(NEW.items) source;
        SELECT COALESCE(jsonb_agg(reference ORDER BY reference::text),'[]'::jsonb) INTO actual_sources FROM (
            SELECT jsonb_build_object('source',jsonb_build_object(
                'workspace_id',s.workspace_id,'source_id',s.source_id,'source_version_id',s.source_version_id,
                'content_artifact_id',s.content_artifact_id,'parse_projection_id',s.parse_projection_id,'content_hash',s.content_hash),
                'source_span_id',s.source_span_id,'excerpt_hash',s.excerpt_hash,'title',s.title) AS reference
            FROM organizing.synthesis_revision_source s WHERE s.revision_id=NEW.id AND s.workspace_id=NEW.workspace_id AND s.note_id=NEW.note_id
        ) source;
        IF actual_sources<>expected_sources OR jsonb_array_length(actual_sources)>256 OR NOT EXISTS (
            SELECT 1 FROM organizing.synthesis_apply_receipt receipt
             WHERE receipt.workspace_id=NEW.workspace_id AND receipt.workflow_run_id=NEW.workflow_run_id
               AND receipt.model_run_id=NEW.model_run_id AND receipt.source_event_id=NEW.source_event_id
               AND receipt.result->'revision_ids' @> jsonb_build_array(NEW.id::text)
        ) THEN RAISE EXCEPTION 'synthesis projection lacks its exact sources and receipt' USING ERRCODE='23514'; END IF;
    END IF;
    RETURN NULL;
END;
$$;


--
-- Name: verify_synthesis_receipt_publications(); Type: FUNCTION; Schema: organizing; Owner: -
--

CREATE FUNCTION organizing.verify_synthesis_receipt_publications() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE command jsonb; matched integer;
BEGIN
    IF (SELECT count(DISTINCT value) FROM jsonb_array_elements(NEW.result->'revision_ids'))
          <>jsonb_array_length(NEW.result->'revision_ids')
       OR (SELECT count(DISTINCT value->>'revision_id') FROM jsonb_array_elements(NEW.result->'publications'))
          <>jsonb_array_length(NEW.result->'publications') THEN
        RAISE EXCEPTION 'synthesis receipt repeats a revision publication' USING ERRCODE='23514';
    END IF;
    FOR command IN SELECT value FROM jsonb_array_elements(NEW.result->'publications') LOOP
        SELECT count(*) INTO matched FROM organizing.synthesis_revision r
        JOIN authoring.document_publication_reservation reservation
          ON reservation.workspace_id=r.workspace_id AND reservation.document_id=r.document_id
         AND reservation.article_revision_id=r.article_revision_id AND reservation.content_hash=r.content_hash
         AND reservation.idempotency_key=command->>'idempotency_key'
        WHERE r.workspace_id=NEW.workspace_id AND r.workflow_run_id=NEW.workflow_run_id
          AND r.model_run_id=NEW.model_run_id AND r.source_event_id=NEW.source_event_id
          AND r.id::text=command->>'revision_id' AND r.note_id::text=command->>'note_id'
          AND r.document_id::text=command->>'document_id' AND r.article_revision_id::text=command->>'article_revision_id'
          AND r.content_hash=command->>'content_hash'
          AND NEW.result->'revision_ids' @> jsonb_build_array(r.id::text);
        IF matched<>1 THEN RAISE EXCEPTION 'synthesis receipt publication binding changed' USING ERRCODE='23514'; END IF;
    END LOOP;
    RETURN NULL;
END;
$$;


--
-- Name: assert_reindex_completion(uuid); Type: FUNCTION; Schema: retrieval; Owner: -
--

CREATE FUNCTION retrieval.assert_reindex_completion(delivery_identity uuid) RETURNS void
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF NOT EXISTS (
        SELECT 1
          FROM retrieval.reindex_delivery delivery
          JOIN workflow.outbox_event event
            ON event.id = delivery.outbox_event_id AND event.workspace_id = delivery.workspace_id
          JOIN change_control.writeback_execution execution
            ON execution.id = delivery.writeback_execution_id AND execution.workspace_id = delivery.workspace_id
          JOIN change_control.proposal proposal ON proposal.id = execution.proposal_id
          JOIN change_control.proposal_commit commit_mapping
            ON commit_mapping.writeback_execution_id = execution.id
          JOIN workflow.run workflow_run ON workflow_run.id = execution.workflow_run_id
          JOIN workflow.node_run workflow_node
            ON workflow_node.id = execution.node_run_id AND workflow_node.run_id = workflow_run.id
          JOIN core.source_version source_version ON source_version.id = delivery.source_version_id
          JOIN core.source source ON source.id = source_version.source_id AND source.workspace_id = delivery.workspace_id
          JOIN retrieval.index_version index_version
            ON index_version.id = delivery.index_version_id AND index_version.workspace_id = delivery.workspace_id
          JOIN retrieval.index_manifest_source source_manifest
            ON source_manifest.index_version_id = index_version.id
           AND source_manifest.source_id = source.id
           AND source_manifest.source_version_id = source_version.id
           AND source_manifest.parse_projection_id = delivery.parse_projection_id
           AND source_manifest.selection_status = 'included'
          JOIN retrieval.index_activation activation
            ON activation.id = delivery.activation_id
           AND activation.workspace_id = delivery.workspace_id
           AND activation.target_index_version_id = index_version.id
          JOIN retrieval.reindex_delivery_attempt delivery_attempt
            ON delivery_attempt.id = delivery.current_attempt_id
           AND delivery_attempt.delivery_id = delivery.id
           AND delivery_attempt.attempt_no = delivery.attempt_no
           AND delivery_attempt.dispatch_no = delivery.dispatch_no
           AND delivery_attempt.status = 'succeeded'
          JOIN ingestion.attempt ingestion_attempt
            ON ingestion_attempt.id = delivery_attempt.ingestion_attempt_id
           AND ingestion_attempt.workspace_id = delivery.workspace_id
           AND ingestion_attempt.source_version_id = delivery.source_version_id
           AND ingestion_attempt.parse_projection_id = delivery.parse_projection_id
         WHERE delivery.id = delivery_identity
           AND delivery.status = 'succeeded'
           AND (
                (delivery.regression_code = 'SNAPSHOT_STRUCTURE_V1' AND index_version.embedding_version_id IS NULL)
                OR
                (delivery.regression_code = 'SNAPSHOT_STRUCTURE_V2' AND index_version.embedding_version_id IS NOT NULL)
           )
           AND delivery.regression_hash IS NOT NULL
           AND delivery.regression_passed_at IS NOT NULL
           AND event.event_type = 'retrieval.revision.reindex_requested'
           AND event.published_at IS NOT NULL
           AND event.payload->>'workspace_id' = delivery.workspace_id::text
           AND event.payload->>'workflow_run_id' = execution.workflow_run_id::text
           AND event.payload->>'node_run_id' = execution.node_run_id::text
           AND event.payload->>'proposal_id' = execution.proposal_id::text
           AND event.payload->>'revision_id' = execution.revision_id::text
           AND event.payload->>'approval_id' = execution.approval_id::text
           AND event.payload->>'writeback_execution_id' = execution.id::text
           AND event.payload->>'target_path' = execution.target_path
           AND event.payload->>'result_hash' = execution.result_hash
           AND event.payload->>'git_commit' = execution.git_commit
           AND commit_mapping.proposal_id = execution.proposal_id
           AND commit_mapping.revision_id = execution.revision_id
           AND commit_mapping.approval_id = execution.approval_id
           AND commit_mapping.git_commit = execution.git_commit
           AND commit_mapping.target_path = execution.target_path
           AND commit_mapping.result_hash = execution.result_hash
           AND source_version.content_hash = execution.result_hash
           AND ingestion_attempt.status = 'chunked'
           AND ingestion_attempt.security_status = 'passed'
           AND execution.status = 'completed'
           AND execution.completed_at IS NOT NULL
           AND execution.cleanup_completed_at IS NOT NULL
           AND proposal.status = 'completed'
           AND proposal.workflow_run_id = workflow_run.id
           AND workflow_run.status = 'succeeded'
           AND workflow_node.status = 'succeeded'
           AND index_version.status = 'active'
           AND index_version.source_manifest_hash IS NOT NULL
           AND index_version.expected_source_count IS NOT NULL
           AND activation.kind = 'activate'
           AND activation.target_version = index_version.version
           AND delivery.excluded_source_count = (
                SELECT count(*) FROM retrieval.index_manifest_source excluded
                 WHERE excluded.index_version_id = index_version.id
                   AND excluded.selection_status = 'excluded'
           )
    ) THEN
        RAISE EXCEPTION 'reindex completion invariant is not closed' USING ERRCODE = '55000';
    END IF;
END;
$$;


--
-- Name: enforce_embedding_model_settings_revision(); Type: FUNCTION; Schema: retrieval; Owner: -
--

CREATE FUNCTION retrieval.enforce_embedding_model_settings_revision() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF TG_OP = 'UPDATE'
       AND NEW.model_settings_revision IS DISTINCT FROM OLD.model_settings_revision THEN
        RAISE EXCEPTION 'retrieval embedding model settings revision is immutable'
            USING ERRCODE = '55000';
    END IF;
    IF NEW.model_settings_revision IS NOT NULL
       AND NOT ops.model_settings_revision_exists(NEW.model_settings_revision) THEN
        RAISE EXCEPTION 'retrieval embedding references an unknown model settings revision'
            USING ERRCODE = '23503';
    END IF;
    RETURN NEW;
END;
$$;


--
-- Name: enforce_index_model_settings_revision(); Type: FUNCTION; Schema: retrieval; Owner: -
--

CREATE FUNCTION retrieval.enforce_index_model_settings_revision() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    embedding_revision bigint;
BEGIN
    IF TG_OP = 'UPDATE'
       AND NEW.model_settings_revision IS DISTINCT FROM OLD.model_settings_revision THEN
        RAISE EXCEPTION 'retrieval index model settings revision is immutable'
            USING ERRCODE = '55000';
    END IF;

    IF NEW.embedding_version_id IS NULL THEN
        IF NEW.model_settings_revision IS NOT NULL THEN
            RAISE EXCEPTION 'retrieval FTS-only index cannot carry an embedding model settings revision'
                USING ERRCODE = '23514';
        END IF;
        RETURN NEW;
    END IF;

    SELECT model_settings_revision
      INTO embedding_revision
      FROM retrieval.embedding_version
     WHERE id = NEW.embedding_version_id;
    IF NOT FOUND THEN
        RAISE EXCEPTION 'retrieval index references an unknown embedding version'
            USING ERRCODE = '23503';
    END IF;
    IF NEW.model_settings_revision IS DISTINCT FROM embedding_revision THEN
        RAISE EXCEPTION 'retrieval index model settings revision differs from embedding version'
            USING ERRCODE = '23514';
    END IF;
    RETURN NEW;
END;
$$;


--
-- Name: reject_immutable_mutation(); Type: FUNCTION; Schema: retrieval; Owner: -
--

CREATE FUNCTION retrieval.reject_immutable_mutation() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    RAISE EXCEPTION 'retrieval record is immutable' USING ERRCODE = '55000';
END;
$$;


--
-- Name: validate_embedding_cache_statement(); Type: FUNCTION; Schema: retrieval; Owner: -
--

CREATE FUNCTION retrieval.validate_embedding_cache_statement() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF EXISTS (
        SELECT 1
          FROM new_embedding_cache cache
          LEFT JOIN retrieval.embedding_version embedding_version
            ON embedding_version.id = cache.embedding_version_id
         WHERE embedding_version.id IS NULL
            OR vector_dims(cache.embedding) <> embedding_version.dimensions
            OR NOT (
                vector_norm(cache.embedding) > 0
                AND vector_norm(cache.embedding) < 'Infinity'::double precision
            )
            OR (
                embedding_version.normalization = 'l2'
                AND abs(vector_norm(cache.embedding) - 1.0) > 0.00001
            )
    ) THEN
        RAISE EXCEPTION 'retrieval embedding cache vector violates embedding version' USING ERRCODE = '23514';
    END IF;
    RETURN NULL;
END;
$$;


--
-- Name: validate_index_activation_insert(); Type: FUNCTION; Schema: retrieval; Owner: -
--

CREATE FUNCTION retrieval.validate_index_activation_insert() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    existing_activation retrieval.index_activation%ROWTYPE;
    target_status text;
    target_current_version bigint;
    previous_status text;
    previous_current_version bigint;
BEGIN
    SELECT id, kind, workspace_id, target_index_version_id, previous_index_version_id,
           target_version, previous_version, idempotency_key, reason_code, created_at
      INTO existing_activation
      FROM retrieval.index_activation
     WHERE workspace_id = NEW.workspace_id
       AND idempotency_key = NEW.idempotency_key;
    IF FOUND THEN
        IF existing_activation.kind = NEW.kind
           AND existing_activation.target_index_version_id = NEW.target_index_version_id
           AND existing_activation.previous_index_version_id IS NOT DISTINCT FROM NEW.previous_index_version_id
           AND existing_activation.target_version = NEW.target_version
           AND existing_activation.previous_version IS NOT DISTINCT FROM NEW.previous_version
           AND existing_activation.reason_code = NEW.reason_code THEN
            RETURN NEW;
        END IF;
        RAISE EXCEPTION 'retrieval activation replay binding mismatch' USING ERRCODE = '23514';
    END IF;

    PERFORM id
      FROM retrieval.index_version
     WHERE id IN (NEW.target_index_version_id, NEW.previous_index_version_id)
     ORDER BY id
     FOR UPDATE;

    SELECT status, version INTO target_status, target_current_version
      FROM retrieval.index_version
     WHERE id = NEW.target_index_version_id
       AND workspace_id = NEW.workspace_id;
    IF target_status IS NULL
       OR target_status NOT IN ('ready', 'retiring')
       OR NEW.target_version <> target_current_version + 1 THEN
        RAISE EXCEPTION 'retrieval activation target binding mismatch' USING ERRCODE = '23514';
    END IF;

    IF NEW.previous_index_version_id IS NULL THEN
        IF NEW.kind <> 'activate' OR target_status <> 'ready' THEN
            RAISE EXCEPTION 'retrieval first activation target must be ready' USING ERRCODE = '23514';
        END IF;
        PERFORM id
          FROM retrieval.index_version
         WHERE workspace_id = NEW.workspace_id
           AND status = 'active'
         FOR UPDATE;
        IF FOUND THEN
            RAISE EXCEPTION 'retrieval first activation requires no current active index' USING ERRCODE = '23514';
        END IF;
        RETURN NEW;
    END IF;

    IF NEW.kind = 'activate' AND target_status <> 'ready' THEN
        RAISE EXCEPTION 'retrieval activation target must be ready' USING ERRCODE = '23514';
    END IF;
    IF NEW.kind = 'rollback' AND target_status <> 'retiring' THEN
        RAISE EXCEPTION 'retrieval rollback target must be retiring' USING ERRCODE = '23514';
    END IF;

    SELECT status, version INTO previous_status, previous_current_version
      FROM retrieval.index_version
     WHERE id = NEW.previous_index_version_id
       AND workspace_id = NEW.workspace_id;
    IF previous_status IS NULL
       OR previous_status <> 'active'
       OR NEW.previous_version <> previous_current_version + 1 THEN
        RAISE EXCEPTION 'retrieval activation previous index binding mismatch' USING ERRCODE = '23514';
    END IF;
    RETURN NEW;
END;
$$;


--
-- Name: validate_index_version_write(); Type: FUNCTION; Schema: retrieval; Owner: -
--

CREATE FUNCTION retrieval.validate_index_version_write() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    manifest_count bigint;
    projection_count bigint;
    source_count bigint;
BEGIN
    IF TG_OP = 'INSERT' THEN
        IF NEW.status <> 'building' OR NEW.version <> 1
           OR NEW.built_at IS NOT NULL OR NEW.activated_at IS NOT NULL
           OR NEW.retired_at IS NOT NULL OR NEW.archived_at IS NOT NULL
           OR NEW.failed_at IS NOT NULL OR NEW.failure_code IS NOT NULL THEN
            RAISE EXCEPTION 'retrieval index must be inserted as building version one' USING ERRCODE = '23514';
        END IF;
        RETURN NEW;
    END IF;

    IF NEW.id <> OLD.id OR NEW.workspace_id <> OLD.workspace_id
       OR NEW.embedding_version_id IS DISTINCT FROM OLD.embedding_version_id
       OR NEW.tokenizer_id <> OLD.tokenizer_id OR NEW.tokenizer_version <> OLD.tokenizer_version
       OR NEW.tokenizer_config_hash <> OLD.tokenizer_config_hash OR NEW.fusion_config <> OLD.fusion_config
       OR NEW.source_snapshot_ref <> OLD.source_snapshot_ref OR NEW.manifest_hash <> OLD.manifest_hash
       OR NEW.expected_chunk_count <> OLD.expected_chunk_count
       OR NEW.source_manifest_hash IS DISTINCT FROM OLD.source_manifest_hash
       OR NEW.expected_source_count IS DISTINCT FROM OLD.expected_source_count
       OR NEW.source_parser_id IS DISTINCT FROM OLD.source_parser_id
       OR NEW.source_parser_version IS DISTINCT FROM OLD.source_parser_version
       OR NEW.source_parser_config_hash IS DISTINCT FROM OLD.source_parser_config_hash
       OR NEW.source_chunk_strategy_version IS DISTINCT FROM OLD.source_chunk_strategy_version
       OR NEW.source_schema_version IS DISTINCT FROM OLD.source_schema_version
       OR NEW.idempotency_key <> OLD.idempotency_key OR NEW.created_at <> OLD.created_at
       OR NEW.updated_at < OLD.updated_at OR NEW.version <> OLD.version + 1 THEN
        RAISE EXCEPTION 'retrieval index immutable field or version violation' USING ERRCODE = '23514';
    END IF;
    IF OLD.status <> 'building' AND NEW.degraded_capabilities <> OLD.degraded_capabilities THEN
        RAISE EXCEPTION 'retrieval index degraded capabilities are immutable after build' USING ERRCODE = '23514';
    END IF;
    IF NOT (
        (OLD.status = 'building' AND NEW.status IN ('ready', 'failed'))
        OR (OLD.status = 'ready' AND NEW.status = 'active')
        OR (OLD.status = 'active' AND NEW.status = 'retiring')
        OR (OLD.status = 'retiring' AND NEW.status IN ('active', 'archived'))
    ) THEN
        RAISE EXCEPTION 'retrieval index status transition is invalid' USING ERRCODE = '23514';
    END IF;
    IF NEW.status = 'active' AND NOT EXISTS (
        SELECT 1 FROM retrieval.index_activation activation
         WHERE activation.workspace_id = NEW.workspace_id
           AND activation.target_index_version_id = NEW.id
           AND activation.target_version = NEW.version
    ) THEN
        RAISE EXCEPTION 'retrieval index may enter active only through activation' USING ERRCODE = '55000';
    END IF;

    IF NEW.status = 'ready' THEN
        SELECT count(*) INTO manifest_count FROM retrieval.index_manifest_chunk WHERE index_version_id = NEW.id;
        SELECT count(*) INTO projection_count FROM retrieval.chunk_projection WHERE index_version_id = NEW.id;
        IF manifest_count <> NEW.expected_chunk_count OR projection_count <> NEW.expected_chunk_count
           OR EXISTS (
                SELECT 1 FROM retrieval.index_manifest_chunk manifest
                LEFT JOIN retrieval.chunk_projection projection
                  ON projection.index_version_id = manifest.index_version_id AND projection.chunk_id = manifest.chunk_id
                WHERE manifest.index_version_id = NEW.id
                  AND (projection.chunk_id IS NULL OR projection.lexical_status <> 'ready')
           )
           OR (NEW.embedding_version_id IS NULL AND EXISTS (
                SELECT 1 FROM retrieval.chunk_projection WHERE index_version_id = NEW.id AND vector_status <> 'disabled'
           ))
           OR (NEW.embedding_version_id IS NOT NULL AND NEW.degraded_capabilities = '[]'::jsonb AND EXISTS (
                SELECT 1 FROM retrieval.chunk_projection WHERE index_version_id = NEW.id AND vector_status <> 'ready'
           ))
           OR (NEW.embedding_version_id IS NOT NULL AND NEW.degraded_capabilities = '["vector"]'::jsonb AND EXISTS (
                SELECT 1 FROM retrieval.chunk_projection
                 WHERE index_version_id = NEW.id AND vector_status NOT IN ('ready', 'skipped_oversized', 'failed')
           ))
           OR (NEW.embedding_version_id IS NOT NULL AND NEW.degraded_capabilities = '["vector"]'::jsonb AND NOT EXISTS (
                SELECT 1 FROM retrieval.chunk_projection WHERE index_version_id = NEW.id AND vector_status <> 'ready'
           )) THEN
            RAISE EXCEPTION 'retrieval index is not complete enough to become ready' USING ERRCODE = '23514';
        END IF;

        IF NEW.source_manifest_hash IS NOT NULL THEN
            SELECT count(*) INTO source_count FROM retrieval.index_manifest_source WHERE index_version_id = NEW.id;
            IF source_count <> NEW.expected_source_count
               OR EXISTS (
                    SELECT 1
                      FROM retrieval.index_manifest_source source_manifest
                     WHERE source_manifest.index_version_id = NEW.id
                       AND source_manifest.selection_status = 'included'
                       AND NOT EXISTS (
                            SELECT 1
                              FROM ingestion.parse_projection projection
                              JOIN ingestion.attempt attempt
                                ON attempt.parse_projection_id = projection.id
                               AND attempt.source_version_id = source_manifest.source_version_id
                               AND attempt.workspace_id = source_manifest.workspace_id
                               AND attempt.status = 'chunked'
                               AND attempt.security_status = 'passed'
                               AND attempt.parser_id = NEW.source_parser_id
                               AND attempt.parser_version = NEW.source_parser_version
                               AND attempt.parser_config_hash = NEW.source_parser_config_hash
                               AND attempt.chunk_strategy_version = NEW.source_chunk_strategy_version
                               AND attempt.schema_version = NEW.source_schema_version
                             WHERE projection.id = source_manifest.parse_projection_id
                               AND projection.workspace_id = source_manifest.workspace_id
                               AND projection.parser_id = NEW.source_parser_id
                               AND projection.parser_version = NEW.source_parser_version
                               AND projection.parser_config_hash = NEW.source_parser_config_hash
                               AND projection.schema_version = NEW.source_schema_version
                       )
               )
               OR EXISTS (
                    (SELECT chunk.id
                       FROM retrieval.index_manifest_source source_manifest
                       JOIN ingestion.canonical_chunk chunk
                         ON chunk.parse_projection_id = source_manifest.parse_projection_id
                       AND chunk.workspace_id = source_manifest.workspace_id
                        AND chunk.status = 'active'
                        AND chunk.parser_version = NEW.source_parser_version
                        AND chunk.chunk_strategy_version = NEW.source_chunk_strategy_version
                        AND chunk.schema_version = NEW.source_schema_version
                      JOIN ingestion.parse_projection projection
                        ON projection.id = source_manifest.parse_projection_id
                       AND projection.workspace_id = source_manifest.workspace_id
                       AND projection.parser_id = NEW.source_parser_id
                       AND projection.parser_version = NEW.source_parser_version
                       AND projection.parser_config_hash = NEW.source_parser_config_hash
                       AND projection.schema_version = NEW.source_schema_version
                      WHERE source_manifest.index_version_id = NEW.id
                        AND source_manifest.selection_status = 'included'
                     EXCEPT
                     SELECT chunk_id FROM retrieval.index_manifest_chunk WHERE index_version_id = NEW.id)
                    UNION ALL
                    (SELECT chunk_id FROM retrieval.index_manifest_chunk WHERE index_version_id = NEW.id
                     EXCEPT
                     SELECT chunk.id
                       FROM retrieval.index_manifest_source source_manifest
                       JOIN ingestion.canonical_chunk chunk
                         ON chunk.parse_projection_id = source_manifest.parse_projection_id
                       AND chunk.workspace_id = source_manifest.workspace_id
                        AND chunk.status = 'active'
                        AND chunk.parser_version = NEW.source_parser_version
                        AND chunk.chunk_strategy_version = NEW.source_chunk_strategy_version
                        AND chunk.schema_version = NEW.source_schema_version
                      JOIN ingestion.parse_projection projection
                        ON projection.id = source_manifest.parse_projection_id
                       AND projection.workspace_id = source_manifest.workspace_id
                       AND projection.parser_id = NEW.source_parser_id
                       AND projection.parser_version = NEW.source_parser_version
                       AND projection.parser_config_hash = NEW.source_parser_config_hash
                       AND projection.schema_version = NEW.source_schema_version
                      WHERE source_manifest.index_version_id = NEW.id
                        AND source_manifest.selection_status = 'included')
               ) THEN
                RAISE EXCEPTION 'retrieval source and chunk manifests are not a closed snapshot' USING ERRCODE = '23514';
            END IF;
        ELSIF EXISTS (SELECT 1 FROM retrieval.index_manifest_source WHERE index_version_id = NEW.id) THEN
            RAISE EXCEPTION 'legacy retrieval index cannot contain a source manifest' USING ERRCODE = '23514';
        END IF;
    END IF;
    RETURN NEW;
END;
$$;


--
-- Name: validate_manifest_chunk_insert(); Type: FUNCTION; Schema: retrieval; Owner: -
--

CREATE FUNCTION retrieval.validate_manifest_chunk_insert() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    existing_row retrieval.index_manifest_chunk%ROWTYPE;
    index_workspace_id uuid;
    index_status text;
    chunk_workspace_id uuid;
    chunk_content_hash text;
    chunk_sequence integer;
    chunk_parser_version text;
    chunk_strategy_version text;
    chunk_schema_version text;
BEGIN
    SELECT manifest.index_version_id, manifest.chunk_id, manifest.workspace_id,
           manifest.content_hash, manifest.sequence, manifest.parser_version,
           manifest.chunk_strategy_version, manifest.schema_version, manifest.created_at
      INTO existing_row
      FROM retrieval.index_manifest_chunk manifest
     WHERE manifest.index_version_id = NEW.index_version_id
       AND manifest.chunk_id = NEW.chunk_id;
    IF FOUND THEN
        IF existing_row.workspace_id = NEW.workspace_id
           AND existing_row.content_hash = NEW.content_hash
           AND existing_row.sequence = NEW.sequence
           AND existing_row.parser_version = NEW.parser_version
           AND existing_row.chunk_strategy_version = NEW.chunk_strategy_version
           AND existing_row.schema_version = NEW.schema_version THEN
            RETURN NEW;
        END IF;
        RAISE EXCEPTION 'retrieval manifest replay binding mismatch' USING ERRCODE = '23514';
    END IF;

    SELECT index_version.workspace_id, index_version.status
      INTO index_workspace_id, index_status
      FROM retrieval.index_version index_version
     WHERE index_version.id = NEW.index_version_id
     FOR UPDATE;
    SELECT chunk.workspace_id, chunk.content_hash, chunk.sequence, chunk.parser_version,
           chunk.chunk_strategy_version, chunk.schema_version
      INTO chunk_workspace_id, chunk_content_hash, chunk_sequence, chunk_parser_version,
           chunk_strategy_version, chunk_schema_version
      FROM ingestion.canonical_chunk chunk
     WHERE chunk.id = NEW.chunk_id;

    IF index_workspace_id IS NULL OR index_workspace_id <> NEW.workspace_id OR index_status <> 'building' THEN
        RAISE EXCEPTION 'retrieval manifest index binding mismatch' USING ERRCODE = '23514';
    END IF;
    IF chunk_workspace_id IS NULL OR chunk_workspace_id <> NEW.workspace_id
       OR chunk_content_hash <> NEW.content_hash
       OR chunk_sequence <> NEW.sequence
       OR chunk_parser_version <> NEW.parser_version
       OR chunk_strategy_version <> NEW.chunk_strategy_version
       OR chunk_schema_version <> NEW.schema_version THEN
        RAISE EXCEPTION 'retrieval manifest canonical chunk binding mismatch' USING ERRCODE = '23514';
    END IF;

    RETURN NEW;
END;
$$;


--
-- Name: validate_manifest_chunk_statement(); Type: FUNCTION; Schema: retrieval; Owner: -
--

CREATE FUNCTION retrieval.validate_manifest_chunk_statement() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF EXISTS (
        SELECT 1
          FROM new_manifest_rows rows
          JOIN retrieval.index_version index_version ON index_version.id = rows.index_version_id
         WHERE index_version.workspace_id <> rows.workspace_id
            OR index_version.status <> 'building'
    ) THEN
        RAISE EXCEPTION 'retrieval manifest index must be building and workspace-bound' USING ERRCODE = '23514';
    END IF;
    RETURN NULL;
END;
$$;


--
-- Name: validate_manifest_source_statement(); Type: FUNCTION; Schema: retrieval; Owner: -
--

CREATE FUNCTION retrieval.validate_manifest_source_statement() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF EXISTS (
        SELECT 1
          FROM new_source_rows rows
          JOIN retrieval.index_version index_version ON index_version.id = rows.index_version_id
         WHERE index_version.workspace_id <> rows.workspace_id
            OR index_version.status <> 'building'
    ) THEN
        RAISE EXCEPTION 'retrieval source manifest index must be building and workspace-bound' USING ERRCODE = '23514';
    END IF;
    RETURN NULL;
END;
$$;


--
-- Name: validate_projection_write(); Type: FUNCTION; Schema: retrieval; Owner: -
--

CREATE FUNCTION retrieval.validate_projection_write() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    existing_row retrieval.chunk_projection%ROWTYPE;
    index_workspace_id uuid;
    index_status text;
    index_embedding_version_id uuid;
    registered_dimensions integer;
    chunk_oversized boolean;
BEGIN
    IF TG_OP = 'INSERT' THEN
        SELECT index_version_id, chunk_id, workspace_id, embedding_version_id,
               search_vector, embedding, token_count, lexical_status, vector_status,
               failure_code, created_at, updated_at
          INTO existing_row
          FROM retrieval.chunk_projection
         WHERE index_version_id = NEW.index_version_id
           AND chunk_id = NEW.chunk_id;
        IF FOUND THEN
            IF existing_row.workspace_id = NEW.workspace_id
               AND existing_row.embedding_version_id IS NOT DISTINCT FROM NEW.embedding_version_id
               AND existing_row.search_vector IS NOT DISTINCT FROM NEW.search_vector
               AND existing_row.embedding IS NOT DISTINCT FROM NEW.embedding
               AND existing_row.token_count = NEW.token_count
               AND existing_row.lexical_status = NEW.lexical_status
               AND existing_row.vector_status = NEW.vector_status
               AND existing_row.failure_code IS NOT DISTINCT FROM NEW.failure_code THEN
                RETURN NEW;
            END IF;
            RAISE EXCEPTION 'retrieval projection replay binding mismatch' USING ERRCODE = '23514';
        END IF;
    END IF;

    SELECT workspace_id, status, embedding_version_id
      INTO index_workspace_id, index_status, index_embedding_version_id
      FROM retrieval.index_version
     WHERE id = NEW.index_version_id
     FOR UPDATE;
    IF index_workspace_id IS NULL OR index_workspace_id <> NEW.workspace_id OR index_status <> 'building' THEN
        RAISE EXCEPTION 'retrieval projection index binding mismatch' USING ERRCODE = '23514';
    END IF;
    IF NEW.embedding_version_id IS DISTINCT FROM index_embedding_version_id THEN
        RAISE EXCEPTION 'retrieval projection embedding version mismatch' USING ERRCODE = '23514';
    END IF;
    IF index_embedding_version_id IS NULL AND NEW.vector_status <> 'disabled' THEN
        RAISE EXCEPTION 'retrieval FTS-only projection must disable vector capability' USING ERRCODE = '23514';
    END IF;
    IF index_embedding_version_id IS NOT NULL AND NEW.vector_status = 'disabled' THEN
        RAISE EXCEPTION 'retrieval vector projection cannot be disabled' USING ERRCODE = '23514';
    END IF;

    IF NEW.vector_status = 'ready' THEN
        SELECT dimensions INTO registered_dimensions
          FROM retrieval.embedding_version
         WHERE id = NEW.embedding_version_id;
        IF registered_dimensions IS NULL
           OR vector_dims(NEW.embedding) <> registered_dimensions
           OR vector_norm(NEW.embedding) <= 0 THEN
            RAISE EXCEPTION 'retrieval projection vector is invalid' USING ERRCODE = '23514';
        END IF;
    END IF;

    IF NEW.vector_status = 'skipped_oversized' THEN
        SELECT atomic_oversized INTO chunk_oversized
          FROM ingestion.canonical_chunk
         WHERE id = NEW.chunk_id
           AND workspace_id = NEW.workspace_id;
        IF chunk_oversized IS DISTINCT FROM true THEN
            RAISE EXCEPTION 'retrieval projection may skip only an oversized canonical chunk' USING ERRCODE = '23514';
        END IF;
    END IF;

    IF TG_OP = 'UPDATE' THEN
        IF NEW.index_version_id <> OLD.index_version_id
           OR NEW.chunk_id <> OLD.chunk_id
           OR NEW.workspace_id <> OLD.workspace_id
           OR NEW.embedding_version_id IS DISTINCT FROM OLD.embedding_version_id
           OR NEW.token_count <> OLD.token_count
           OR NEW.created_at <> OLD.created_at
           OR NEW.updated_at < OLD.updated_at THEN
            RAISE EXCEPTION 'retrieval projection immutable binding changed' USING ERRCODE = '23514';
        END IF;
        IF NEW.lexical_status <> OLD.lexical_status
           AND NOT (OLD.lexical_status = 'pending' AND NEW.lexical_status IN ('ready', 'failed')) THEN
            RAISE EXCEPTION 'retrieval lexical projection transition is invalid' USING ERRCODE = '23514';
        END IF;
        IF NEW.vector_status <> OLD.vector_status
           AND NOT (OLD.vector_status = 'pending' AND NEW.vector_status IN ('ready', 'skipped_oversized', 'failed')) THEN
            RAISE EXCEPTION 'retrieval vector projection transition is invalid' USING ERRCODE = '23514';
        END IF;
        IF OLD.search_vector IS NOT NULL AND NEW.search_vector IS DISTINCT FROM OLD.search_vector THEN
            RAISE EXCEPTION 'retrieval lexical projection result is immutable' USING ERRCODE = '23514';
        END IF;
        IF OLD.embedding IS NOT NULL AND NEW.embedding IS DISTINCT FROM OLD.embedding THEN
            RAISE EXCEPTION 'retrieval vector projection result is immutable' USING ERRCODE = '23514';
        END IF;
        IF OLD.failure_code IS NOT NULL AND NEW.failure_code IS DISTINCT FROM OLD.failure_code THEN
            RAISE EXCEPTION 'retrieval projection failure code is immutable' USING ERRCODE = '23514';
        END IF;
    END IF;
    RETURN NEW;
END;
$$;


--
-- Name: validate_reindex_attempt_write(); Type: FUNCTION; Schema: retrieval; Owner: -
--

CREATE FUNCTION retrieval.validate_reindex_attempt_write() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF TG_OP = 'INSERT' THEN
        IF NEW.status <> 'processing' OR NEW.ended_at IS NOT NULL THEN
            RAISE EXCEPTION 'reindex attempt must be inserted as processing' USING ERRCODE = '23514';
        END IF;
        IF NEW.lease_until <= clock_timestamp() OR NEW.heartbeat_at > clock_timestamp() THEN
            RAISE EXCEPTION 'reindex attempt requires a live database-time lease' USING ERRCODE = '23514';
        END IF;
        IF NOT EXISTS (
            SELECT 1 FROM retrieval.reindex_delivery delivery
             WHERE delivery.id = NEW.delivery_id
               AND delivery.status = 'dispatched'
               AND delivery.dispatch_no = NEW.dispatch_no
               AND delivery.attempt_no + 1 = NEW.attempt_no
        ) THEN
            RAISE EXCEPTION 'reindex attempt does not match dispatched delivery' USING ERRCODE = '23514';
        END IF;
        RETURN NEW;
    END IF;
    IF OLD.status <> 'processing' THEN
        RAISE EXCEPTION 'reindex terminal attempt is append-only' USING ERRCODE = '55000';
    END IF;
    IF NEW.status = 'lease_lost' AND NEW.ended_at < OLD.lease_until THEN
        RAISE EXCEPTION 'reindex attempt lease has not expired' USING ERRCODE = '23514';
    END IF;
    IF NEW.status <> 'lease_lost' AND (
        (NEW.status <> 'processing' AND NEW.ended_at >= OLD.lease_until)
        OR (NEW.status = 'processing' AND NEW.heartbeat_at > OLD.heartbeat_at AND NEW.heartbeat_at >= OLD.lease_until)
        OR (NEW.status = 'processing' AND NEW.heartbeat_at = OLD.heartbeat_at
            AND NEW.ingestion_attempt_id IS DISTINCT FROM OLD.ingestion_attempt_id
            AND clock_timestamp() >= OLD.lease_until)
    ) THEN
        RAISE EXCEPTION 'expired reindex attempt cannot heartbeat or publish a result' USING ERRCODE = '23514';
    END IF;
    IF NEW.id <> OLD.id OR NEW.delivery_id <> OLD.delivery_id OR NEW.attempt_no <> OLD.attempt_no
       OR NEW.dispatch_no <> OLD.dispatch_no OR NEW.river_job_id <> OLD.river_job_id
       OR NEW.river_attempt <> OLD.river_attempt OR NEW.delivery_key <> OLD.delivery_key
       OR NEW.lease_owner <> OLD.lease_owner OR NEW.started_at <> OLD.started_at
       OR NEW.heartbeat_at < OLD.heartbeat_at OR NEW.lease_until < OLD.lease_until
       OR ((NEW.heartbeat_at IS DISTINCT FROM OLD.heartbeat_at)
           <> (NEW.lease_until IS DISTINCT FROM OLD.lease_until))
       OR (OLD.ingestion_attempt_id IS NOT NULL AND NEW.ingestion_attempt_id IS DISTINCT FROM OLD.ingestion_attempt_id)
       OR (NEW.status = 'processing' AND NEW.ended_at IS NOT NULL)
       OR (NEW.status <> 'processing' AND NEW.ended_at IS NULL) THEN
        RAISE EXCEPTION 'reindex attempt immutable field or transition violation' USING ERRCODE = '23514';
    END IF;
    IF NEW.status = 'succeeded' AND NEW.ingestion_attempt_id IS NULL THEN
        RAISE EXCEPTION 'successful reindex attempt requires ingestion evidence' USING ERRCODE = '23514';
    END IF;
    IF NEW.ingestion_attempt_id IS NOT NULL
       AND NOT EXISTS (
            SELECT 1
              FROM retrieval.reindex_delivery delivery
              JOIN ingestion.attempt ingestion_attempt ON ingestion_attempt.id = NEW.ingestion_attempt_id
             WHERE delivery.id = NEW.delivery_id
               AND delivery.workspace_id = ingestion_attempt.workspace_id
               AND delivery.source_version_id = ingestion_attempt.source_version_id
               AND ingestion_attempt.parse_projection_id IS NOT NULL
               AND ingestion_attempt.status = 'chunked'
               AND ingestion_attempt.security_status = 'passed'
       ) THEN
        RAISE EXCEPTION 'reindex attempt ingestion evidence mismatch' USING ERRCODE = '23514';
    END IF;
    RETURN NEW;
END;
$$;


--
-- Name: validate_reindex_delivery_write(); Type: FUNCTION; Schema: retrieval; Owner: -
--

CREATE FUNCTION retrieval.validate_reindex_delivery_write() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF TG_OP = 'INSERT' THEN
        IF NEW.status <> 'pending' OR NEW.dispatch_no <> 0 OR NEW.attempt_no <> 0
           OR NEW.current_attempt_id IS NOT NULL OR NEW.version <> 1
           OR NEW.next_attempt_at IS NOT NULL OR NEW.completed_at IS NOT NULL
           OR NEW.source_version_id IS NOT NULL OR NEW.parse_projection_id IS NOT NULL
           OR NEW.index_version_id IS NOT NULL OR NEW.activation_id IS NOT NULL
           OR NEW.excluded_source_count IS NOT NULL OR NEW.regression_code IS NOT NULL
           OR NEW.failure_class IS NOT NULL OR NEW.manual_recovery_required THEN
            RAISE EXCEPTION 'reindex delivery must be inserted as pending version one' USING ERRCODE = '23514';
        END IF;
        RETURN NEW;
    END IF;

    IF NEW.id <> OLD.id OR NEW.consumer_name <> OLD.consumer_name
       OR NEW.outbox_event_id <> OLD.outbox_event_id OR NEW.workspace_id <> OLD.workspace_id
       OR NEW.writeback_execution_id <> OLD.writeback_execution_id OR NEW.created_at <> OLD.created_at
       OR NEW.updated_at < OLD.updated_at OR NEW.version <> OLD.version + 1 THEN
        RAISE EXCEPTION 'reindex delivery immutable field or version violation' USING ERRCODE = '23514';
    END IF;

    IF OLD.status IN ('succeeded', 'failed') THEN
        RAISE EXCEPTION 'reindex terminal delivery is immutable' USING ERRCODE = '55000';
    END IF;
    IF NOT (
        NEW.status = OLD.status
        OR (OLD.status = 'pending' AND NEW.status = 'dispatched')
        OR (OLD.status = 'dispatched' AND NEW.status = 'processing')
        OR (OLD.status = 'processing' AND NEW.status IN ('retry_wait', 'succeeded', 'failed', 'manual_recovery'))
        OR (OLD.status = 'processing' AND NEW.status = 'dispatched')
        OR (OLD.status = 'retry_wait' AND NEW.status = 'dispatched')
    ) THEN
        RAISE EXCEPTION 'reindex delivery status transition is invalid' USING ERRCODE = '23514';
    END IF;

    IF OLD.status = 'pending' AND NEW.status = 'dispatched' THEN
        IF OLD.dispatch_no <> 0 OR NEW.dispatch_no <> 1 THEN
            RAISE EXCEPTION 'first reindex dispatch must create generation one' USING ERRCODE = '23514';
        END IF;
    ELSIF OLD.status = 'retry_wait' AND NEW.status = 'dispatched' THEN
        IF NEW.dispatch_no <> OLD.dispatch_no + 1 THEN
            RAISE EXCEPTION 'reindex retry dispatch must increment generation' USING ERRCODE = '23514';
        END IF;
    ELSIF NEW.dispatch_no <> OLD.dispatch_no THEN
        RAISE EXCEPTION 'reindex dispatch generation changed outside dispatcher' USING ERRCODE = '23514';
    END IF;

    IF OLD.status = 'dispatched' AND NEW.status = 'processing' THEN
        IF NEW.attempt_no <> OLD.attempt_no + 1 OR NEW.current_attempt_id IS NULL THEN
            RAISE EXCEPTION 'reindex claim must bind the next delivery attempt' USING ERRCODE = '23514';
        END IF;
        IF NOT EXISTS (
            SELECT 1 FROM retrieval.reindex_delivery_attempt attempt
             WHERE attempt.id = NEW.current_attempt_id
               AND attempt.delivery_id = NEW.id
               AND attempt.attempt_no = NEW.attempt_no
               AND attempt.dispatch_no = NEW.dispatch_no
               AND attempt.status = 'processing'
        ) THEN
            RAISE EXCEPTION 'reindex claim attempt binding mismatch' USING ERRCODE = '23514';
        END IF;
    ELSIF NEW.attempt_no <> OLD.attempt_no OR NEW.current_attempt_id IS DISTINCT FROM OLD.current_attempt_id THEN
        RAISE EXCEPTION 'reindex attempt changed outside claim' USING ERRCODE = '23514';
    END IF;

    IF OLD.status = 'processing' AND NEW.status = 'dispatched'
       AND NOT EXISTS (
            SELECT 1 FROM retrieval.reindex_delivery_attempt attempt
             WHERE attempt.id = OLD.current_attempt_id
               AND attempt.delivery_id = NEW.id
               AND attempt.attempt_no = NEW.attempt_no
               AND attempt.dispatch_no = NEW.dispatch_no
               AND attempt.status = 'lease_lost'
       ) THEN
        RAISE EXCEPTION 'reindex transport reclaim requires a lease-lost attempt' USING ERRCODE = '23514';
    END IF;

    IF OLD.status = 'processing' AND NEW.status NOT IN ('processing', 'dispatched')
       AND NOT EXISTS (
            SELECT 1 FROM retrieval.reindex_delivery_attempt attempt
             WHERE attempt.id = OLD.current_attempt_id
               AND attempt.delivery_id = NEW.id
               AND attempt.attempt_no = NEW.attempt_no
               AND attempt.dispatch_no = NEW.dispatch_no
               AND attempt.status = NEW.status
       ) THEN
        RAISE EXCEPTION 'reindex delivery result does not match current attempt' USING ERRCODE = '23514';
    END IF;

    IF OLD.source_version_id IS NOT NULL AND NEW.source_version_id IS DISTINCT FROM OLD.source_version_id
       OR OLD.parse_projection_id IS NOT NULL AND NEW.parse_projection_id IS DISTINCT FROM OLD.parse_projection_id
       OR OLD.index_version_id IS NOT NULL AND NEW.index_version_id IS DISTINCT FROM OLD.index_version_id
       OR OLD.activation_id IS NOT NULL AND NEW.activation_id IS DISTINCT FROM OLD.activation_id
       OR OLD.excluded_source_count IS NOT NULL AND NEW.excluded_source_count IS DISTINCT FROM OLD.excluded_source_count
       OR OLD.regression_code IS NOT NULL AND (
            NEW.regression_code IS DISTINCT FROM OLD.regression_code
            OR NEW.regression_hash IS DISTINCT FROM OLD.regression_hash
            OR NEW.regression_passed_at IS DISTINCT FROM OLD.regression_passed_at
       ) THEN
        RAISE EXCEPTION 'reindex checkpoint is immutable after persistence' USING ERRCODE = '23514';
    END IF;
    IF NEW.source_version_id IS NOT NULL AND NEW.parse_projection_id IS NOT NULL
       AND NOT EXISTS (
            SELECT 1 FROM ingestion.source_version_projection
             WHERE source_version_id = NEW.source_version_id
               AND parse_projection_id = NEW.parse_projection_id
               AND workspace_id = NEW.workspace_id
       ) THEN
        RAISE EXCEPTION 'reindex source version and projection binding mismatch' USING ERRCODE = '23514';
    END IF;
    IF NEW.parse_projection_id IS NOT NULL
       AND NOT EXISTS (
            SELECT 1
              FROM retrieval.reindex_delivery_attempt delivery_attempt
              JOIN ingestion.attempt ingestion_attempt
                ON ingestion_attempt.id = delivery_attempt.ingestion_attempt_id
               AND ingestion_attempt.workspace_id = NEW.workspace_id
               AND ingestion_attempt.source_version_id = NEW.source_version_id
               AND ingestion_attempt.parse_projection_id = NEW.parse_projection_id
               AND ingestion_attempt.status = 'chunked'
               AND ingestion_attempt.security_status = 'passed'
             WHERE delivery_attempt.id = NEW.current_attempt_id
               AND delivery_attempt.delivery_id = NEW.id
       ) THEN
        RAISE EXCEPTION 'reindex ingestion checkpoint binding mismatch' USING ERRCODE = '23514';
    END IF;
    RETURN NEW;
END;
$$;


--
-- Name: verify_index_activation_commit(); Type: FUNCTION; Schema: retrieval; Owner: -
--

CREATE FUNCTION retrieval.verify_index_activation_commit() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF NOT EXISTS (
        SELECT 1
          FROM retrieval.index_version
         WHERE id = NEW.target_index_version_id
           AND workspace_id = NEW.workspace_id
           AND status = 'active'
           AND version = NEW.target_version
    ) OR (
        NEW.previous_index_version_id IS NOT NULL
        AND NOT EXISTS (
            SELECT 1
              FROM retrieval.index_version
             WHERE id = NEW.previous_index_version_id
               AND workspace_id = NEW.workspace_id
               AND status = 'retiring'
               AND version = NEW.previous_version
        )
    ) THEN
        RAISE EXCEPTION 'retrieval activation did not commit an atomic index switch' USING ERRCODE = '55000';
    END IF;
    RETURN NEW;
END;
$$;


--
-- Name: verify_reindex_completion_trigger(); Type: FUNCTION; Schema: retrieval; Owner: -
--

CREATE FUNCTION retrieval.verify_reindex_completion_trigger() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    delivery_identity uuid;
BEGIN
    IF TG_TABLE_SCHEMA = 'retrieval' AND TG_TABLE_NAME = 'reindex_delivery' THEN
        IF NEW.status <> 'succeeded' THEN
            RETURN NEW;
        END IF;
        delivery_identity := NEW.id;
    ELSIF TG_TABLE_SCHEMA = 'change_control' AND TG_TABLE_NAME = 'writeback_execution' THEN
        IF NEW.status <> 'completed' THEN
            RETURN NEW;
        END IF;
        SELECT id INTO delivery_identity
          FROM retrieval.reindex_delivery
         WHERE writeback_execution_id = NEW.id;
    ELSE
        IF NEW.status <> 'completed' THEN
            RETURN NEW;
        END IF;
        SELECT delivery.id INTO delivery_identity
          FROM retrieval.reindex_delivery delivery
          JOIN change_control.writeback_execution execution
            ON execution.id = delivery.writeback_execution_id
         WHERE execution.proposal_id = NEW.id;
    END IF;

    IF delivery_identity IS NULL THEN
        RAISE EXCEPTION 'completed writeback facts require a reindex delivery' USING ERRCODE = '55000';
    END IF;
    PERFORM retrieval.assert_reindex_completion(delivery_identity);
    RETURN NEW;
END;
$$;


--
-- Name: enforce_node_attempt_model_runtime_binding(); Type: FUNCTION; Schema: workflow; Owner: -
--

CREATE FUNCTION workflow.enforce_node_attempt_model_runtime_binding() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    active_revision bigint;
    activation_phase text;
    worker_instance_id uuid;
    worker_revision bigint;
    worker_rollout_id uuid;
    worker_phase text;
BEGIN
    IF TG_OP='UPDATE' THEN
        IF NEW.model_settings_revision IS DISTINCT FROM OLD.model_settings_revision
           OR NEW.model_runtime_instance_id IS DISTINCT FROM OLD.model_runtime_instance_id THEN
            RAISE EXCEPTION 'workflow node attempt model runtime binding is immutable' USING ERRCODE='55000';
        END IF;
        RETURN NEW;
    END IF;
    IF NEW.model_settings_revision IS NULL THEN
        RETURN NEW;
    END IF;
    IF NOT ops.model_settings_revision_exists(NEW.model_settings_revision) THEN
        RAISE EXCEPTION 'workflow node attempt references an unknown model settings revision' USING ERRCODE='23503';
    END IF;
    SELECT state.active_revision,state.phase INTO active_revision,activation_phase
      FROM ops.model_settings_state AS state WHERE singleton=true FOR SHARE;
    IF activation_phase NOT IN ('idle','failed','preparing') THEN
        RAISE EXCEPTION 'workflow node attempt claim is fenced during model activation' USING ERRCODE='55P03';
    END IF;
    SELECT runtime.instance_id,runtime.applied_revision,runtime.rollout_id,runtime.phase
      INTO worker_instance_id,worker_revision,worker_rollout_id,worker_phase
      FROM ops.model_settings_runtime AS runtime WHERE runtime.role='worker' FOR SHARE;
    IF NOT FOUND THEN
        RAISE EXCEPTION 'workflow node attempt requires an active worker model runtime' USING ERRCODE='23503';
    END IF;
    IF NEW.model_runtime_instance_id IS DISTINCT FROM worker_instance_id
       OR NEW.model_settings_revision IS DISTINCT FROM active_revision
       OR worker_revision IS DISTINCT FROM active_revision
       OR worker_rollout_id IS NOT NULL OR worker_phase<>'active' THEN
        RAISE EXCEPTION 'workflow node attempt model runtime binding does not match the serving worker runtime' USING ERRCODE='23514';
    END IF;
    RETURN NEW;
END
$$;


--
-- Name: guard_node_runtime_identity_mutation(); Type: FUNCTION; Schema: workflow; Owner: -
--

CREATE FUNCTION workflow.guard_node_runtime_identity_mutation() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF NEW.idempotency_key IS DISTINCT FROM OLD.idempotency_key
       OR NEW.input_schema_version IS DISTINCT FROM OLD.input_schema_version
       OR NEW.output_schema_version IS DISTINCT FROM OLD.output_schema_version
       OR NEW.dispatch_no IS NULL OR OLD.dispatch_no IS NULL
       OR NEW.dispatch_no < OLD.dispatch_no OR NEW.dispatch_no > OLD.dispatch_no + 1 THEN
        RAISE EXCEPTION 'workflow node runtime identity or dispatch generation is invalid' USING ERRCODE = '55000';
    END IF;
    RETURN NEW;
END;
$$;


--
-- Name: guard_outbox_runtime_identity_mutation(); Type: FUNCTION; Schema: workflow; Owner: -
--

CREATE FUNCTION workflow.guard_outbox_runtime_identity_mutation() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF NEW.event_key IS DISTINCT FROM OLD.event_key
       OR NEW.schema_version IS DISTINCT FROM OLD.schema_version
       OR NEW.event_version IS DISTINCT FROM OLD.event_version THEN
        RAISE EXCEPTION 'workflow outbox runtime identity is immutable' USING ERRCODE = '55000';
    END IF;
    RETURN NEW;
END;
$$;


--
-- Name: guard_run_runtime_identity_mutation(); Type: FUNCTION; Schema: workflow; Owner: -
--

CREATE FUNCTION workflow.guard_run_runtime_identity_mutation() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF NEW.idempotency_key IS DISTINCT FROM OLD.idempotency_key
       OR NEW.request_hash IS DISTINCT FROM OLD.request_hash THEN
        RAISE EXCEPTION 'workflow run runtime identity is immutable' USING ERRCODE = '55000';
    END IF;
    RETURN NEW;
END;
$$;


--
-- Name: guard_tool_call_mutation(); Type: FUNCTION; Schema: workflow; Owner: -
--

CREATE FUNCTION workflow.guard_tool_call_mutation() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    run_status text;
    node_status text;
    node_attempt_no integer;
    node_lease_owner text;
    node_lease_until timestamptz;
    attempt_status text;
    attempt_no integer;
    attempt_lease_owner text;
    attempt_lease_until timestamptz;
    database_now timestamptz;
BEGIN
    IF TG_OP = 'DELETE' THEN
        RAISE EXCEPTION 'workflow tool call is append-preserving' USING ERRCODE = '55000';
    END IF;

    IF TG_OP = 'INSERT' THEN
        IF NEW.version <> 1 OR NEW.status NOT IN ('STARTED', 'REFUSED') THEN
            RAISE EXCEPTION 'workflow tool call must start at version one' USING ERRCODE = '23514';
        END IF;

        SELECT r.status,n.status,n.attempt,n.lease_owner,n.lease_until,
               a.status,a.attempt_no,a.lease_owner,a.lease_until
          INTO run_status,node_status,node_attempt_no,node_lease_owner,node_lease_until,
               attempt_status,attempt_no,attempt_lease_owner,attempt_lease_until
          FROM workflow.run r
          JOIN workflow.node_run n ON n.run_id=r.id
          JOIN workflow.node_attempt a ON a.node_run_id=n.id
         WHERE a.id=NEW.node_attempt_id
         FOR SHARE OF r,n,a;

        IF NOT FOUND THEN
            -- 让后续外键以标准 23503 报告不存在的父事实。
            RETURN NEW;
        END IF;

        database_now := clock_timestamp();
        IF run_status IS DISTINCT FROM 'running'
           OR node_status IS DISTINCT FROM 'running'
           OR attempt_status IS DISTINCT FROM 'running'
           OR node_attempt_no IS DISTINCT FROM attempt_no
           OR node_lease_owner IS NULL
           OR node_lease_owner IS DISTINCT FROM btrim(node_lease_owner)
           OR node_lease_owner = ''
           OR attempt_lease_owner IS DISTINCT FROM node_lease_owner
           OR node_lease_until IS NULL
           OR attempt_lease_until IS NULL
           OR node_lease_until IS DISTINCT FROM attempt_lease_until
           OR node_lease_until <= database_now THEN
            RAISE EXCEPTION 'workflow tool call requires an active node attempt lease' USING ERRCODE = '55000';
        END IF;
        RETURN NEW;
    END IF;

    IF OLD.status <> 'STARTED'
       OR NEW.status NOT IN ('SUCCEEDED', 'FAILED', 'UNKNOWN')
       OR NEW.id IS DISTINCT FROM OLD.id
       OR NEW.workspace_id IS DISTINCT FROM OLD.workspace_id
       OR NEW.workflow_run_id IS DISTINCT FROM OLD.workflow_run_id
       OR NEW.node_run_id IS DISTINCT FROM OLD.node_run_id
       OR NEW.node_attempt_id IS DISTINCT FROM OLD.node_attempt_id
       OR NEW.call_no IS DISTINCT FROM OLD.call_no
       OR NEW.requested_tool_name IS DISTINCT FROM OLD.requested_tool_name
       OR NEW.tool_version IS DISTINCT FROM OLD.tool_version
       OR NEW.definition_hash IS DISTINCT FROM OLD.definition_hash
       OR NEW.input_schema_id IS DISTINCT FROM OLD.input_schema_id
       OR NEW.input_schema_version IS DISTINCT FROM OLD.input_schema_version
       OR NEW.output_schema_id IS DISTINCT FROM OLD.output_schema_id
       OR NEW.output_schema_version IS DISTINCT FROM OLD.output_schema_version
       OR NEW.capability IS DISTINCT FROM OLD.capability
       OR NEW.side_effect_level IS DISTINCT FROM OLD.side_effect_level
       OR NEW.invocation_policy IS DISTINCT FROM OLD.invocation_policy
       OR NEW.idempotency_key IS DISTINCT FROM OLD.idempotency_key
       OR NEW.request_hash IS DISTINCT FROM OLD.request_hash
       OR NEW.request_bytes IS DISTINCT FROM OLD.request_bytes
	       OR NEW.request_summary IS DISTINCT FROM OLD.request_summary
	       OR (
	           OLD.side_effect_type IS NOT NULL
	           AND (
	               NEW.side_effect_type IS DISTINCT FROM OLD.side_effect_type
	               OR NEW.side_effect_id IS DISTINCT FROM OLD.side_effect_id
	           )
	       )
	       OR NEW.started_at IS DISTINCT FROM OLD.started_at
       OR NEW.version <> OLD.version + 1 THEN
        RAISE EXCEPTION 'workflow tool call transition or immutable binding is invalid' USING ERRCODE = '55000';
    END IF;
    RETURN NEW;
END;
$$;


--
-- Name: guard_tool_result_receipt_failure_insert(); Type: FUNCTION; Schema: workflow; Owner: -
--

CREATE FUNCTION workflow.guard_tool_result_receipt_failure_insert() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    operation_row agent.workspace_analysis_operation%ROWTYPE;
    analysis_status_value text;
    call_row workflow.tool_call%ROWTYPE;
BEGIN
    SELECT analysis.status
      INTO analysis_status_value
      FROM agent.workspace_analysis_operation AS operation
      JOIN agent.workspace_analysis_run AS analysis
        ON analysis.id=operation.analysis_run_id
       AND analysis.workspace_id=operation.workspace_id
       AND analysis.workflow_run_id=operation.workflow_run_id
     WHERE operation.id=NEW.operation_id
       AND operation.analysis_run_id=NEW.analysis_run_id
       AND operation.tool_call_id=NEW.tool_call_id
       AND operation.workspace_id=NEW.workspace_id
       AND operation.workflow_run_id=NEW.workflow_run_id
       AND operation.node_run_id=NEW.node_run_id
       AND operation.first_node_attempt_id=NEW.node_attempt_id
     FOR UPDATE OF analysis;
    SELECT operation.*
      INTO operation_row
      FROM agent.workspace_analysis_operation AS operation
     WHERE operation.id=NEW.operation_id
       AND operation.analysis_run_id=NEW.analysis_run_id
       AND operation.tool_call_id=NEW.tool_call_id
       AND operation.workspace_id=NEW.workspace_id
       AND operation.workflow_run_id=NEW.workflow_run_id
       AND operation.node_run_id=NEW.node_run_id
       AND operation.first_node_attempt_id=NEW.node_attempt_id
     FOR UPDATE;
    SELECT * INTO call_row
      FROM workflow.tool_call
     WHERE id=NEW.tool_call_id
       AND workspace_id=NEW.workspace_id
       AND workflow_run_id=NEW.workflow_run_id
       AND node_run_id=NEW.node_run_id
       AND node_attempt_id=NEW.node_attempt_id
     FOR UPDATE;

    IF operation_row.id IS NULL
       OR operation_row.call_kind<>'TOOL'
       OR operation_row.status<>'STARTED'
       OR analysis_status_value<>'running'
       OR call_row.id IS NULL
       OR call_row.status<>'SUCCEEDED'
       OR call_row.response_hash IS NULL
       OR call_row.response_bytes IS NULL
       OR call_row.completed_at IS NULL
       OR NEW.expected_output_hash IS DISTINCT FROM call_row.response_hash
       OR NEW.checked_at<call_row.completed_at
       OR NEW.checked_at>clock_timestamp()
       OR NEW.created_at>clock_timestamp()
       OR NEW.observed_output_bytes>1048576
       OR NEW.observed_binding_bytes>65536
       OR (
            NEW.failure_code IN ('CONTRACT_INVALID','BINDING_INVALID')
            AND NEW.observed_output_bytes IS DISTINCT FROM call_row.response_bytes
       )
       OR EXISTS (
            SELECT 1 FROM workflow.tool_result_receipt
             WHERE tool_call_id=NEW.tool_call_id
       ) THEN
        RAISE EXCEPTION 'tool result receipt failure binding is invalid' USING ERRCODE='55000';
    END IF;
    RETURN NEW;
END;
$$;


--
-- Name: guard_tool_result_receipt_insert(); Type: FUNCTION; Schema: workflow; Owner: -
--

CREATE FUNCTION workflow.guard_tool_result_receipt_insert() RETURNS trigger
    LANGUAGE plpgsql
    AS $_$
DECLARE
    call_row workflow.tool_call%ROWTYPE;
    operation_row agent.workspace_analysis_operation%ROWTYPE;
    analysis_status_value text;
    output_document json;
    binding_document json;
    output_text text;
    binding_text text;
    output_json jsonb;
    binding_json jsonb;
    ordered_values text[];
    sorted_values text[];
    value_count bigint;
    distinct_value_count bigint;
BEGIN
    SELECT analysis.status
      INTO analysis_status_value
      FROM agent.workspace_analysis_operation AS operation
      JOIN agent.workspace_analysis_run AS analysis
        ON analysis.id=operation.analysis_run_id
       AND analysis.workspace_id=operation.workspace_id
       AND analysis.workflow_run_id=operation.workflow_run_id
     WHERE operation.tool_call_id=NEW.tool_call_id
       AND operation.workspace_id=NEW.workspace_id
       AND operation.workflow_run_id=NEW.workflow_run_id
       AND operation.node_run_id=NEW.node_run_id
       AND operation.first_node_attempt_id=NEW.node_attempt_id
     FOR UPDATE OF analysis;
    SELECT operation.*
      INTO operation_row
      FROM agent.workspace_analysis_operation AS operation
     WHERE operation.tool_call_id=NEW.tool_call_id
       AND operation.workspace_id=NEW.workspace_id
       AND operation.workflow_run_id=NEW.workflow_run_id
       AND operation.node_run_id=NEW.node_run_id
       AND operation.first_node_attempt_id=NEW.node_attempt_id
     FOR UPDATE;
    SELECT * INTO call_row
      FROM workflow.tool_call
     WHERE id=NEW.tool_call_id
       AND workspace_id=NEW.workspace_id
       AND workflow_run_id=NEW.workflow_run_id
       AND node_run_id=NEW.node_run_id
       AND node_attempt_id=NEW.node_attempt_id
     FOR UPDATE;

    IF operation_row.id IS NULL
       OR operation_row.call_kind<>'TOOL'
       OR operation_row.status<>'STARTED'
       OR analysis_status_value<>'running'
       OR EXISTS (
            SELECT 1 FROM workflow.tool_result_receipt_failure
             WHERE tool_call_id=NEW.tool_call_id
       )
       OR call_row.id IS NULL
       OR call_row.status<>'SUCCEEDED'
       OR call_row.requested_tool_name IS DISTINCT FROM NEW.tool_name
       OR call_row.tool_version IS DISTINCT FROM NEW.tool_version
       OR call_row.output_schema_id IS DISTINCT FROM NEW.output_schema_id
       OR call_row.output_schema_version IS DISTINCT FROM NEW.output_schema_version
       OR call_row.definition_hash IS DISTINCT FROM NEW.definition_hash
       OR call_row.capability IS DISTINCT FROM 'READ_LOCAL'
       OR call_row.side_effect_level IS DISTINCT FROM 'NONE'
       OR call_row.invocation_policy IS DISTINCT FROM 'TRUSTED_WORKFLOW_ONLY'
       OR call_row.response_hash IS DISTINCT FROM NEW.output_hash
       OR call_row.response_bytes IS DISTINCT FROM NEW.output_bytes
       OR call_row.result_ref IS NOT NULL
       OR call_row.side_effect_type IS NOT NULL
       OR call_row.side_effect_id IS NOT NULL
       OR call_row.completed_at IS NULL
       OR NEW.created_at<call_row.completed_at THEN
        RAISE EXCEPTION 'tool result receipt call binding is invalid' USING ERRCODE='55000';
    END IF;

    IF (NEW.tool_name='ReadGitStatus' AND (
            call_row.input_schema_id IS DISTINCT FROM 'tool.read_git_status.input'
            OR call_row.input_schema_version IS DISTINCT FROM 1
       )) OR (NEW.tool_name='SearchKnowledge' AND (
            call_row.input_schema_id IS DISTINCT FROM 'tool.search_knowledge.input'
            OR call_row.input_schema_version IS DISTINCT FROM 2
       )) OR (NEW.tool_name='ReadSource' AND (
            call_row.input_schema_id IS DISTINCT FROM 'tool.read_source.input'
            OR call_row.input_schema_version IS DISTINCT FROM 2
       )) OR (NEW.tool_name='ValidateCitation' AND (
            call_row.input_schema_id IS DISTINCT FROM 'tool.validate_citation.input'
            OR call_row.input_schema_version IS DISTINCT FROM 2
       )) THEN
        RAISE EXCEPTION 'tool result receipt input contract is invalid' USING ERRCODE='55000';
    END IF;

    output_text := convert_from(NEW.output_document,'UTF8');
    BEGIN
        output_document := output_text::json;
    EXCEPTION WHEN OTHERS THEN
        RAISE EXCEPTION 'tool result receipt output is not valid JSON' USING ERRCODE='23514';
    END;
    IF workflow.workspace_analysis_receipt_canonical_json(output_document)<>output_text THEN
        RAISE EXCEPTION 'tool result receipt output is not canonical JSON' USING ERRCODE='23514';
    END IF;
    output_json := output_document::jsonb;
    IF jsonb_typeof(output_json)<>'object' THEN
        RAISE EXCEPTION 'tool result receipt output is not an object' USING ERRCODE='23514';
    END IF;
    IF NEW.server_binding_document IS NOT NULL THEN
        binding_text := convert_from(NEW.server_binding_document,'UTF8');
        BEGIN
            binding_document := binding_text::json;
        EXCEPTION WHEN OTHERS THEN
            RAISE EXCEPTION 'tool result receipt binding is not valid JSON' USING ERRCODE='23514';
        END;
        IF workflow.workspace_analysis_receipt_canonical_json(binding_document)<>binding_text THEN
            RAISE EXCEPTION 'tool result receipt binding is not canonical JSON' USING ERRCODE='23514';
        END IF;
        binding_json := binding_document::jsonb;
        IF jsonb_typeof(binding_json)<>'object' THEN
            RAISE EXCEPTION 'tool result receipt binding is not an object' USING ERRCODE='23514';
        END IF;
    END IF;

    IF NEW.tool_name='ReadGitStatus' THEN
        IF NOT workflow.workspace_analysis_receipt_exact_object_keys(output_json, ARRAY[
            'branch','head','object_format','clean','staged_count','unstaged_count','untracked_count','conflict_count'
        ])
           OR jsonb_typeof(output_json->'branch')<>'string'
           OR jsonb_typeof(output_json->'head')<>'string'
           OR jsonb_typeof(output_json->'object_format')<>'string'
           OR jsonb_typeof(output_json->'clean')<>'boolean'
           OR jsonb_typeof(output_json->'staged_count')<>'number'
           OR jsonb_typeof(output_json->'unstaged_count')<>'number'
           OR jsonb_typeof(output_json->'untracked_count')<>'number'
           OR jsonb_typeof(output_json->'conflict_count')<>'number'
           OR NOT workflow.workspace_analysis_receipt_reference(output_json->>'branch', 255)
           OR (output_json->>'object_format') NOT IN ('sha1','sha256')
           OR ((output_json->>'object_format')='sha1' AND (output_json->>'head') !~ '^[0-9a-f]{40}$')
           OR ((output_json->>'object_format')='sha256' AND (output_json->>'head') !~ '^[0-9a-f]{64}$')
           OR (output_json->>'staged_count') !~ '^(0|[1-9][0-9]*)$'
           OR (output_json->>'unstaged_count') !~ '^(0|[1-9][0-9]*)$'
           OR (output_json->>'untracked_count') !~ '^(0|[1-9][0-9]*)$'
           OR (output_json->>'conflict_count') !~ '^(0|[1-9][0-9]*)$'
           OR (output_json->>'staged_count')::bigint>100000
           OR (output_json->>'unstaged_count')::bigint>100000
           OR (output_json->>'untracked_count')::bigint>100000
           OR (output_json->>'conflict_count')::bigint>100000
           OR (output_json->>'clean')::boolean<>(
                (output_json->>'staged_count')::bigint
                +(output_json->>'unstaged_count')::bigint
                +(output_json->>'untracked_count')::bigint
                +(output_json->>'conflict_count')::bigint=0
           ) THEN
            RAISE EXCEPTION 'ReadGitStatus receipt document is invalid' USING ERRCODE='23514';
        END IF;
        IF binding_json IS NOT NULL AND (
            NOT workflow.workspace_analysis_receipt_exact_object_keys(binding_json, ARRAY['workspace_root_hash','repository_identity_hash'])
            OR jsonb_typeof(binding_json->'workspace_root_hash')<>'string'
            OR jsonb_typeof(binding_json->'repository_identity_hash')<>'string'
            OR NOT workflow.workspace_analysis_receipt_hash(binding_json->>'workspace_root_hash')
            OR NOT workflow.workspace_analysis_receipt_hash(binding_json->>'repository_identity_hash')
        ) THEN
            RAISE EXCEPTION 'ReadGitStatus receipt binding is invalid' USING ERRCODE='23514';
        END IF;
    ELSIF NEW.tool_name='SearchKnowledge' THEN
        IF NOT workflow.workspace_analysis_receipt_exact_object_keys(output_json, ARRAY['effective_mode','items','degradations'])
           OR jsonb_typeof(output_json->'effective_mode')<>'string'
           OR jsonb_typeof(output_json->'items')<>'array'
           OR jsonb_typeof(output_json->'degradations')<>'array'
           OR (output_json->>'effective_mode') NOT IN ('keyword','semantic','hybrid')
           OR jsonb_array_length(output_json->'items')>5
           OR jsonb_array_length(output_json->'degradations')>16
           OR EXISTS (
                SELECT 1
                  FROM jsonb_array_elements(output_json->'items') WITH ORDINALITY AS item(document, ordinal)
                 WHERE NOT workflow.workspace_analysis_receipt_exact_object_keys(item.document, ARRAY['evidence_ref','rank','snippet'])
                    OR jsonb_typeof(item.document->'evidence_ref')<>'string'
                    OR jsonb_typeof(item.document->'rank')<>'number'
                    OR jsonb_typeof(item.document->'snippet')<>'string'
                    OR item.document->>'evidence_ref'<>'E'||item.ordinal::text
                    OR item.document->>'rank'<>item.ordinal::text
                    OR NOT workflow.workspace_analysis_receipt_text(item.document->>'snippet', 4096)
           )
           OR EXISTS (
                SELECT 1
                  FROM jsonb_array_elements(output_json->'degradations') AS degradation(value)
                 WHERE jsonb_typeof(degradation.value)<>'string'
                    OR degradation.value #>> '{}' !~ '^[A-Z][A-Z0-9_]{0,127}$'
           ) THEN
            RAISE EXCEPTION 'SearchKnowledge receipt output is invalid' USING ERRCODE='23514';
        END IF;
        SELECT array_agg(value #>> '{}' ORDER BY ordinal), array_agg(value #>> '{}' ORDER BY value #>> '{}'), count(*), count(DISTINCT value #>> '{}')
          INTO ordered_values, sorted_values, value_count, distinct_value_count
          FROM jsonb_array_elements(output_json->'degradations') WITH ORDINALITY AS degradation(value, ordinal);
        IF ordered_values IS DISTINCT FROM sorted_values OR value_count<>distinct_value_count THEN
            RAISE EXCEPTION 'SearchKnowledge receipt degradations are invalid' USING ERRCODE='23514';
        END IF;
        IF NOT workflow.workspace_analysis_receipt_exact_object_keys(binding_json, ARRAY['items','selected_refs'])
           OR jsonb_typeof(binding_json->'items')<>'array'
           OR jsonb_typeof(binding_json->'selected_refs')<>'array'
           OR jsonb_array_length(binding_json->'items')<>jsonb_array_length(output_json->'items')
           OR jsonb_array_length(binding_json->'items')>5
           OR jsonb_array_length(binding_json->'selected_refs')<>LEAST(3,jsonb_array_length(binding_json->'items'))
           OR EXISTS (
                SELECT 1 FROM jsonb_array_elements(binding_json->'items') WITH ORDINALITY AS item(document, ordinal)
                 WHERE NOT workflow.workspace_analysis_receipt_identity_valid(item.document, 5)
                    OR item.document->>'evidence_ref'<>'E'||item.ordinal::text
           )
           OR EXISTS (
                SELECT 1 FROM jsonb_array_elements(binding_json->'selected_refs') WITH ORDINALITY AS selection(value, ordinal)
                 WHERE jsonb_typeof(selection.value)<>'string'
                    OR selection.value #>> '{}' <>'E'||selection.ordinal::text
           )
           OR EXISTS (
                SELECT 1
                  FROM jsonb_array_elements(output_json->'items') WITH ORDINALITY AS output_item(document, ordinal)
                  JOIN jsonb_array_elements(binding_json->'items') WITH ORDINALITY AS binding_item(document, ordinal)
                    USING (ordinal)
                 WHERE output_item.document->>'evidence_ref'<>binding_item.document->>'evidence_ref'
           ) THEN
            RAISE EXCEPTION 'SearchKnowledge receipt binding is invalid' USING ERRCODE='23514';
        END IF;
        SELECT count(*), count(DISTINCT document->>'citation_id')
          INTO value_count, distinct_value_count
          FROM jsonb_array_elements(binding_json->'items') AS item(document);
        IF value_count<>distinct_value_count THEN
            RAISE EXCEPTION 'SearchKnowledge receipt citation identities are duplicated' USING ERRCODE='23514';
        END IF;
    ELSIF NEW.tool_name='ReadSource' THEN
        IF NOT workflow.workspace_analysis_receipt_exact_object_keys(output_json, ARRAY['evidence_ref','content_hash','truncated','excerpt'])
           OR jsonb_typeof(output_json->'evidence_ref')<>'string'
           OR jsonb_typeof(output_json->'content_hash')<>'string'
           OR jsonb_typeof(output_json->'truncated')<>'boolean'
           OR jsonb_typeof(output_json->'excerpt')<>'string'
           OR (output_json->>'evidence_ref') !~ '^E[1-3]$'
           OR NOT workflow.workspace_analysis_receipt_hash(output_json->>'content_hash')
           OR NOT workflow.workspace_analysis_receipt_text(output_json->>'excerpt', 4096) THEN
            RAISE EXCEPTION 'ReadSource receipt output is invalid' USING ERRCODE='23514';
        END IF;
        IF NOT workflow.workspace_analysis_receipt_exact_object_keys(binding_json, ARRAY[
            'search_receipt_id','search_receipt_hash','evidence_ref','citation_id','index_version_id','chunk_id','source_version_id','source_span_id','content_hash'
        ])
           OR jsonb_typeof(binding_json->'search_receipt_id')<>'string'
           OR jsonb_typeof(binding_json->'search_receipt_hash')<>'string'
           OR NOT workflow.workspace_analysis_receipt_canonical_uuid(binding_json->>'search_receipt_id')
           OR NOT workflow.workspace_analysis_receipt_hash(binding_json->>'search_receipt_hash')
           OR NOT workflow.workspace_analysis_receipt_identity_valid(binding_json-ARRAY['search_receipt_id','search_receipt_hash'], 3)
           OR output_json->>'evidence_ref'<>binding_json->>'evidence_ref'
           OR output_json->>'content_hash'<>binding_json->>'content_hash'
           OR NOT EXISTS (
                SELECT 1
                  FROM workflow.tool_result_receipt AS search_receipt
                  JOIN agent.workspace_analysis_operation AS search_operation
                    ON search_operation.result_id=search_receipt.id
                   AND search_operation.result_hash=search_receipt.output_hash
                   AND search_operation.tool_call_id=search_receipt.tool_call_id
                 WHERE search_receipt.id=(binding_json->>'search_receipt_id')::uuid
                   AND search_receipt.workspace_id=NEW.workspace_id
                   AND search_receipt.workflow_run_id=NEW.workflow_run_id
                   AND search_receipt.tool_name='SearchKnowledge'
                   AND search_receipt.tool_version=2
                   AND search_receipt.output_hash=binding_json->>'search_receipt_hash'
                   AND search_operation.analysis_run_id=operation_row.analysis_run_id
                   AND search_operation.workspace_id=NEW.workspace_id
                   AND search_operation.workflow_run_id=NEW.workflow_run_id
                   AND search_operation.operation_kind='KNOWLEDGE_SEARCH'
                   AND search_operation.ordinal=1
                   AND search_operation.call_kind='TOOL'
                   AND search_operation.status='SUCCEEDED'
                   AND search_operation.result_kind='TOOL_RESULT_RECEIPT'
           ) THEN
            RAISE EXCEPTION 'ReadSource receipt binding is invalid' USING ERRCODE='23514';
        END IF;
    ELSIF NEW.tool_name='ValidateCitation' THEN
        IF NOT workflow.workspace_analysis_receipt_exact_object_keys(output_json, ARRAY['results'])
           OR jsonb_typeof(output_json->'results')<>'array'
           OR jsonb_array_length(output_json->'results') NOT BETWEEN 1 AND 3
           OR EXISTS (
                SELECT 1 FROM jsonb_array_elements(output_json->'results') AS result(document)
                 WHERE NOT workflow.workspace_analysis_receipt_exact_object_keys(result.document, ARRAY['evidence_ref','valid','reason_code'])
                    OR jsonb_typeof(result.document->'evidence_ref')<>'string'
                    OR jsonb_typeof(result.document->'valid')<>'boolean'
                    OR jsonb_typeof(result.document->'reason_code')<>'string'
                    OR result.document->>'evidence_ref' !~ '^E[1-3]$'
                    OR result.document->>'reason_code' NOT IN ('OK','CITATION_UNRESOLVABLE','EVIDENCE_INELIGIBLE','BINDING_MISMATCH')
                    OR (result.document->>'valid')::boolean<>(result.document->>'reason_code'='OK')
           ) THEN
            RAISE EXCEPTION 'ValidateCitation receipt output is invalid' USING ERRCODE='23514';
        END IF;
        SELECT count(*), count(DISTINCT document->>'evidence_ref')
          INTO value_count, distinct_value_count
          FROM jsonb_array_elements(output_json->'results') AS result(document);
        IF value_count<>distinct_value_count THEN
            RAISE EXCEPTION 'ValidateCitation receipt output references are duplicated' USING ERRCODE='23514';
        END IF;
        IF NOT workflow.workspace_analysis_receipt_exact_object_keys(binding_json, ARRAY['candidate_id','candidate_hash','results'])
           OR jsonb_typeof(binding_json->'candidate_id')<>'string'
           OR jsonb_typeof(binding_json->'candidate_hash')<>'string'
           OR jsonb_typeof(binding_json->'results')<>'array'
           OR NOT workflow.workspace_analysis_receipt_canonical_uuid(binding_json->>'candidate_id')
           OR NOT workflow.workspace_analysis_receipt_hash(binding_json->>'candidate_hash')
           OR jsonb_array_length(binding_json->'results')<>jsonb_array_length(output_json->'results')
           OR EXISTS (
                SELECT 1 FROM jsonb_array_elements(binding_json->'results') AS result(document)
                 WHERE NOT workflow.workspace_analysis_receipt_identity_valid(result.document, 3)
           )
           OR EXISTS (
                SELECT 1
                  FROM jsonb_array_elements(output_json->'results') WITH ORDINALITY AS output_result(document, ordinal)
                  JOIN jsonb_array_elements(binding_json->'results') WITH ORDINALITY AS binding_result(document, ordinal)
                    USING (ordinal)
                 WHERE output_result.document->>'evidence_ref'<>binding_result.document->>'evidence_ref'
           )
           OR NOT EXISTS (
                SELECT 1 FROM agent.workspace_analysis_candidate AS candidate
                 WHERE candidate.id=(binding_json->>'candidate_id')::uuid
                   AND candidate.workspace_id=NEW.workspace_id
                   AND candidate.analysis_run_id=operation_row.analysis_run_id
                   AND candidate.document_hash=binding_json->>'candidate_hash'
           ) THEN
            RAISE EXCEPTION 'ValidateCitation receipt binding is invalid' USING ERRCODE='23514';
        END IF;
        SELECT count(*), count(DISTINCT document->>'evidence_ref')
          INTO value_count, distinct_value_count
          FROM jsonb_array_elements(binding_json->'results') AS result(document);
        IF value_count<>distinct_value_count THEN
            RAISE EXCEPTION 'ValidateCitation receipt binding references are duplicated' USING ERRCODE='23514';
        END IF;
    END IF;
    RETURN NEW;
END;
$_$;


--
-- Name: guard_tool_result_receipt_insert_v2(); Type: FUNCTION; Schema: workflow; Owner: -
--

CREATE FUNCTION workflow.guard_tool_result_receipt_insert_v2() RETURNS trigger
    LANGUAGE plpgsql
    AS $_$
DECLARE
    call_row workflow.tool_call%ROWTYPE;
    operation_row agent.workspace_analysis_operation%ROWTYPE;
    analysis_status_value text;
    output_document json;
    binding_document json;
    output_text text;
    binding_text text;
    output_json jsonb;
    binding_json jsonb;
    ordered_values text[];
    sorted_values text[];
    value_count bigint;
    distinct_value_count bigint;
BEGIN
    SELECT analysis.status
      INTO analysis_status_value
      FROM agent.workspace_analysis_operation AS operation
      JOIN agent.workspace_analysis_run AS analysis
        ON analysis.id=operation.analysis_run_id
       AND analysis.workspace_id=operation.workspace_id
       AND analysis.workflow_run_id=operation.workflow_run_id
       AND analysis.definition_version=2
     WHERE operation.tool_call_id=NEW.tool_call_id
       AND operation.workspace_id=NEW.workspace_id
       AND operation.workflow_run_id=NEW.workflow_run_id
       AND operation.node_run_id=NEW.node_run_id
       AND operation.first_node_attempt_id=NEW.node_attempt_id
     FOR UPDATE OF analysis;
    SELECT operation.*
      INTO operation_row
      FROM agent.workspace_analysis_operation AS operation
     WHERE operation.tool_call_id=NEW.tool_call_id
       AND operation.workspace_id=NEW.workspace_id
       AND operation.workflow_run_id=NEW.workflow_run_id
       AND operation.node_run_id=NEW.node_run_id
       AND operation.first_node_attempt_id=NEW.node_attempt_id
     FOR UPDATE;
    SELECT * INTO call_row
      FROM workflow.tool_call
     WHERE id=NEW.tool_call_id
       AND workspace_id=NEW.workspace_id
       AND workflow_run_id=NEW.workflow_run_id
       AND node_run_id=NEW.node_run_id
       AND node_attempt_id=NEW.node_attempt_id
     FOR UPDATE;

    IF operation_row.id IS NULL
       OR operation_row.call_kind<>'TOOL'
       OR operation_row.status<>'STARTED'
       OR analysis_status_value IS DISTINCT FROM 'running'
       OR EXISTS (
            SELECT 1 FROM workflow.tool_result_receipt_failure
             WHERE tool_call_id=NEW.tool_call_id
       )
       OR call_row.id IS NULL
       OR call_row.status<>'SUCCEEDED'
       OR call_row.requested_tool_name IS DISTINCT FROM NEW.tool_name
       OR call_row.tool_version IS DISTINCT FROM NEW.tool_version
       OR call_row.output_schema_id IS DISTINCT FROM NEW.output_schema_id
       OR call_row.output_schema_version IS DISTINCT FROM NEW.output_schema_version
       OR call_row.definition_hash IS DISTINCT FROM NEW.definition_hash
       OR call_row.capability IS DISTINCT FROM 'READ_LOCAL'
       OR call_row.side_effect_level IS DISTINCT FROM 'NONE'
       OR call_row.invocation_policy IS DISTINCT FROM 'TRUSTED_WORKFLOW_ONLY'
       OR call_row.response_hash IS DISTINCT FROM NEW.output_hash
       OR call_row.response_bytes IS DISTINCT FROM NEW.output_bytes
       OR call_row.result_ref IS NOT NULL
       OR call_row.side_effect_type IS NOT NULL
       OR call_row.side_effect_id IS NOT NULL
       OR call_row.completed_at IS NULL
       OR NEW.created_at<call_row.completed_at THEN
        RAISE EXCEPTION 'tool result receipt call binding is invalid' USING ERRCODE='55000';
    END IF;

    IF (NEW.tool_name='ReadGitStatus' AND (
            call_row.input_schema_id IS DISTINCT FROM 'tool.read_git_status.input'
            OR call_row.input_schema_version IS DISTINCT FROM 1
       )) OR (NEW.tool_name='SearchKnowledge' AND (
            call_row.input_schema_id IS DISTINCT FROM 'tool.search_knowledge.input'
            OR call_row.input_schema_version IS DISTINCT FROM 2
       )) OR (NEW.tool_name='ReadSource' AND (
            call_row.input_schema_id IS DISTINCT FROM 'tool.read_source.input'
            OR call_row.input_schema_version IS DISTINCT FROM 3
       )) OR (NEW.tool_name='ValidateCitation' AND (
            call_row.input_schema_id IS DISTINCT FROM 'tool.validate_citation.input'
            OR call_row.input_schema_version IS DISTINCT FROM 3
       )) THEN
        RAISE EXCEPTION 'tool result receipt input contract is invalid' USING ERRCODE='55000';
    END IF;

    output_text := convert_from(NEW.output_document,'UTF8');
    BEGIN
        output_document := output_text::json;
    EXCEPTION WHEN OTHERS THEN
        RAISE EXCEPTION 'tool result receipt output is not valid JSON' USING ERRCODE='23514';
    END;
    IF workflow.workspace_analysis_receipt_canonical_json(output_document)<>output_text THEN
        RAISE EXCEPTION 'tool result receipt output is not canonical JSON' USING ERRCODE='23514';
    END IF;
    output_json := output_document::jsonb;
    IF jsonb_typeof(output_json)<>'object' THEN
        RAISE EXCEPTION 'tool result receipt output is not an object' USING ERRCODE='23514';
    END IF;
    IF NEW.server_binding_document IS NOT NULL THEN
        binding_text := convert_from(NEW.server_binding_document,'UTF8');
        BEGIN
            binding_document := binding_text::json;
        EXCEPTION WHEN OTHERS THEN
            RAISE EXCEPTION 'tool result receipt binding is not valid JSON' USING ERRCODE='23514';
        END;
        IF workflow.workspace_analysis_receipt_canonical_json(binding_document)<>binding_text THEN
            RAISE EXCEPTION 'tool result receipt binding is not canonical JSON' USING ERRCODE='23514';
        END IF;
        binding_json := binding_document::jsonb;
        IF jsonb_typeof(binding_json)<>'object' THEN
            RAISE EXCEPTION 'tool result receipt binding is not an object' USING ERRCODE='23514';
        END IF;
    END IF;

    IF NEW.tool_name='ReadGitStatus' THEN
        IF NOT workflow.workspace_analysis_receipt_exact_object_keys(output_json, ARRAY[
            'branch','head','object_format','clean','staged_count','unstaged_count','untracked_count','conflict_count'
        ])
           OR jsonb_typeof(output_json->'branch')<>'string'
           OR jsonb_typeof(output_json->'head')<>'string'
           OR jsonb_typeof(output_json->'object_format')<>'string'
           OR jsonb_typeof(output_json->'clean')<>'boolean'
           OR jsonb_typeof(output_json->'staged_count')<>'number'
           OR jsonb_typeof(output_json->'unstaged_count')<>'number'
           OR jsonb_typeof(output_json->'untracked_count')<>'number'
           OR jsonb_typeof(output_json->'conflict_count')<>'number'
           OR NOT workflow.workspace_analysis_receipt_reference(output_json->>'branch', 255)
           OR (output_json->>'object_format') NOT IN ('sha1','sha256')
           OR ((output_json->>'object_format')='sha1' AND (output_json->>'head') !~ '^[0-9a-f]{40}$')
           OR ((output_json->>'object_format')='sha256' AND (output_json->>'head') !~ '^[0-9a-f]{64}$')
           OR (output_json->>'staged_count') !~ '^(0|[1-9][0-9]*)$'
           OR (output_json->>'unstaged_count') !~ '^(0|[1-9][0-9]*)$'
           OR (output_json->>'untracked_count') !~ '^(0|[1-9][0-9]*)$'
           OR (output_json->>'conflict_count') !~ '^(0|[1-9][0-9]*)$'
           OR (output_json->>'staged_count')::bigint>100000
           OR (output_json->>'unstaged_count')::bigint>100000
           OR (output_json->>'untracked_count')::bigint>100000
           OR (output_json->>'conflict_count')::bigint>100000
           OR (output_json->>'clean')::boolean<>(
                (output_json->>'staged_count')::bigint
                +(output_json->>'unstaged_count')::bigint
                +(output_json->>'untracked_count')::bigint
                +(output_json->>'conflict_count')::bigint=0
           ) THEN
            RAISE EXCEPTION 'ReadGitStatus receipt document is invalid' USING ERRCODE='23514';
        END IF;
        IF binding_json IS NOT NULL AND (
            NOT workflow.workspace_analysis_receipt_exact_object_keys(binding_json, ARRAY['workspace_root_hash','repository_identity_hash'])
            OR jsonb_typeof(binding_json->'workspace_root_hash')<>'string'
            OR jsonb_typeof(binding_json->'repository_identity_hash')<>'string'
            OR NOT workflow.workspace_analysis_receipt_hash(binding_json->>'workspace_root_hash')
            OR NOT workflow.workspace_analysis_receipt_hash(binding_json->>'repository_identity_hash')
        ) THEN
            RAISE EXCEPTION 'ReadGitStatus receipt binding is invalid' USING ERRCODE='23514';
        END IF;
    ELSIF NEW.tool_name='SearchKnowledge' THEN
        IF NOT workflow.workspace_analysis_receipt_exact_object_keys(output_json, ARRAY['effective_mode','items','degradations'])
           OR jsonb_typeof(output_json->'effective_mode')<>'string'
           OR jsonb_typeof(output_json->'items')<>'array'
           OR jsonb_typeof(output_json->'degradations')<>'array'
           OR (output_json->>'effective_mode') NOT IN ('keyword','semantic','hybrid')
           OR jsonb_array_length(output_json->'items')>5
           OR jsonb_array_length(output_json->'degradations')>16
           OR EXISTS (
                SELECT 1
                  FROM jsonb_array_elements(output_json->'items') WITH ORDINALITY AS item(document, ordinal)
                 WHERE NOT workflow.workspace_analysis_receipt_exact_object_keys(item.document, ARRAY['evidence_ref','rank','snippet'])
                    OR jsonb_typeof(item.document->'evidence_ref')<>'string'
                    OR jsonb_typeof(item.document->'rank')<>'number'
                    OR jsonb_typeof(item.document->'snippet')<>'string'
                    OR item.document->>'evidence_ref'<>'E'||item.ordinal::text
                    OR item.document->>'rank'<>item.ordinal::text
                    OR NOT workflow.workspace_analysis_receipt_text(item.document->>'snippet', 4096)
           )
           OR EXISTS (
                SELECT 1
                  FROM jsonb_array_elements(output_json->'degradations') AS degradation(value)
                 WHERE jsonb_typeof(degradation.value)<>'string'
                    OR degradation.value #>> '{}' !~ '^[A-Z][A-Z0-9_]{0,127}$'
           ) THEN
            RAISE EXCEPTION 'SearchKnowledge receipt output is invalid' USING ERRCODE='23514';
        END IF;
        SELECT array_agg(value #>> '{}' ORDER BY ordinal), array_agg(value #>> '{}' ORDER BY value #>> '{}'), count(*), count(DISTINCT value #>> '{}')
          INTO ordered_values, sorted_values, value_count, distinct_value_count
          FROM jsonb_array_elements(output_json->'degradations') WITH ORDINALITY AS degradation(value, ordinal);
        IF ordered_values IS DISTINCT FROM sorted_values OR value_count<>distinct_value_count THEN
            RAISE EXCEPTION 'SearchKnowledge receipt degradations are invalid' USING ERRCODE='23514';
        END IF;
        IF binding_json IS NULL OR NOT workflow.workspace_analysis_receipt_exact_object_keys(binding_json, ARRAY['items','selected_refs'])
           OR jsonb_typeof(binding_json->'items')<>'array'
           OR jsonb_typeof(binding_json->'selected_refs')<>'array'
           OR jsonb_array_length(binding_json->'items')<>jsonb_array_length(output_json->'items')
           OR jsonb_array_length(binding_json->'items')>5
           OR jsonb_array_length(binding_json->'selected_refs')<>jsonb_array_length(binding_json->'items')
           OR EXISTS (
                SELECT 1 FROM jsonb_array_elements(binding_json->'items') WITH ORDINALITY AS item(document, ordinal)
                 WHERE NOT workflow.workspace_analysis_receipt_identity_valid(item.document, 5)
                    OR NOT workflow.workspace_analysis_dynamic_source_bound(NEW.workspace_id,item.document)
                    OR item.document->>'evidence_ref'<>'E'||item.ordinal::text
           )
           OR EXISTS (
                SELECT 1 FROM jsonb_array_elements(binding_json->'selected_refs') WITH ORDINALITY AS selection(value, ordinal)
                 WHERE jsonb_typeof(selection.value)<>'string'
                    OR selection.value #>> '{}' <>'E'||selection.ordinal::text
           )
           OR EXISTS (
                SELECT 1
                  FROM jsonb_array_elements(output_json->'items') WITH ORDINALITY AS output_item(document, ordinal)
                  JOIN jsonb_array_elements(binding_json->'items') WITH ORDINALITY AS binding_item(document, ordinal)
                    USING (ordinal)
                 WHERE output_item.document->>'evidence_ref'<>binding_item.document->>'evidence_ref'
           ) THEN
            RAISE EXCEPTION 'SearchKnowledge receipt binding is invalid' USING ERRCODE='23514';
        END IF;
        SELECT count(*), count(DISTINCT document->>'citation_id')
          INTO value_count, distinct_value_count
          FROM jsonb_array_elements(binding_json->'items') AS item(document);
        IF value_count<>distinct_value_count THEN
            RAISE EXCEPTION 'SearchKnowledge receipt citation identities are duplicated' USING ERRCODE='23514';
        END IF;

        IF (SELECT count(DISTINCT item->>'index_version_id')
              FROM jsonb_array_elements(binding_json->'items') item)>1 THEN
            RAISE EXCEPTION 'dynamic Search receipt spans indexes' USING ERRCODE='23514';
        END IF;
    ELSIF NEW.tool_name='ReadSource' THEN
        IF NOT workflow.workspace_analysis_receipt_exact_object_keys(output_json,ARRAY['evidence_ref','content_hash','truncated','excerpt'])
           OR jsonb_typeof(output_json->'evidence_ref')<>'string'
           OR jsonb_typeof(output_json->'content_hash')<>'string'
           OR jsonb_typeof(output_json->'truncated')<>'boolean'
           OR jsonb_typeof(output_json->'excerpt')<>'string'
           OR output_json->>'evidence_ref' !~ '^E([1-9]|[12][0-9]|3[0-2])$'
           OR NOT workflow.workspace_analysis_receipt_hash(output_json->>'content_hash')
           OR NOT workflow.workspace_analysis_receipt_text(output_json->>'excerpt',4096) THEN
            RAISE EXCEPTION 'dynamic Read output is invalid' USING ERRCODE='23514';
        END IF;
        IF binding_json IS NULL OR NOT workflow.workspace_analysis_receipt_exact_object_keys(binding_json,ARRAY[
             'search_receipt_id','search_receipt_hash','search_evidence_ref','evidence_ref','citation_id','index_version_id','chunk_id','source_version_id','source_span_id','content_hash'])
           OR jsonb_typeof(binding_json->'search_receipt_id')<>'string'
           OR jsonb_typeof(binding_json->'search_receipt_hash')<>'string'
           OR jsonb_typeof(binding_json->'search_evidence_ref')<>'string'
           OR NOT workflow.workspace_analysis_receipt_canonical_uuid(binding_json->>'search_receipt_id')
           OR NOT workflow.workspace_analysis_receipt_hash(binding_json->>'search_receipt_hash')
           OR binding_json->>'search_evidence_ref' !~ '^E[1-5]$'
           OR NOT workflow.workspace_analysis_dynamic_identity_valid(binding_json-ARRAY['search_receipt_id','search_receipt_hash','search_evidence_ref'])
           OR output_json->>'evidence_ref'<>binding_json->>'evidence_ref'
           OR output_json->>'content_hash'<>binding_json->>'content_hash'
           OR NOT workflow.workspace_analysis_dynamic_read_bound(NEW.workspace_id,NEW.workflow_run_id,operation_row.analysis_run_id,binding_json) THEN
            RAISE EXCEPTION 'dynamic Read Search binding is invalid' USING ERRCODE='23514';
        END IF;
    ELSIF NEW.tool_name='ValidateCitation' THEN
        IF NOT workflow.workspace_analysis_receipt_exact_object_keys(output_json,ARRAY['results'])
           OR jsonb_typeof(output_json->'results')<>'array'
           OR jsonb_array_length(output_json->'results') NOT BETWEEN 1 AND 8
           OR EXISTS (
             SELECT 1 FROM jsonb_array_elements(output_json->'results') result
             WHERE NOT workflow.workspace_analysis_receipt_exact_object_keys(result,ARRAY['evidence_ref','valid','reason_code'])
                OR jsonb_typeof(result->'evidence_ref')<>'string'
                OR jsonb_typeof(result->'valid')<>'boolean'
                OR jsonb_typeof(result->'reason_code')<>'string'
                OR result->>'evidence_ref' !~ '^E([1-9]|[12][0-9]|3[0-2])$'
                OR result->>'reason_code' NOT IN ('OK','CITATION_UNRESOLVABLE','EVIDENCE_INELIGIBLE','BINDING_MISMATCH')
                OR (result->>'valid')::boolean<>(result->>'reason_code'='OK')
           ) THEN
            RAISE EXCEPTION 'dynamic Citation output is invalid' USING ERRCODE='23514';
        END IF;
        IF binding_json IS NULL OR NOT workflow.workspace_analysis_receipt_exact_object_keys(binding_json,ARRAY['candidate_id','candidate_hash','results'])
           OR jsonb_typeof(binding_json->'results')<>'array'
           OR jsonb_array_length(binding_json->'results')<>jsonb_array_length(output_json->'results') THEN
            RAISE EXCEPTION 'dynamic Citation private binding is invalid' USING ERRCODE='23514';
        END IF;
        IF operation_row.node_key='decide_next' THEN
            IF binding_json->'candidate_id'<>'null'::jsonb OR binding_json->'candidate_hash'<>'null'::jsonb THEN
                RAISE EXCEPTION 'loop Citation cannot bind a candidate' USING ERRCODE='23514';
            END IF;
        ELSIF operation_row.node_key='validate_citations' AND operation_row.ordinal=1 THEN
            IF jsonb_typeof(binding_json->'candidate_id')<>'string'
               OR jsonb_typeof(binding_json->'candidate_hash')<>'string'
               OR NOT workflow.workspace_analysis_receipt_canonical_uuid(binding_json->>'candidate_id')
               OR NOT workflow.workspace_analysis_receipt_hash(binding_json->>'candidate_hash')
               OR NOT EXISTS (
                 SELECT 1 FROM agent.workspace_analysis_candidate candidate
                 WHERE candidate.id=(binding_json->>'candidate_id')::uuid
                   AND candidate.workspace_id=NEW.workspace_id AND candidate.analysis_run_id=operation_row.analysis_run_id
                   AND candidate.schema_version=2 AND candidate.document_hash=binding_json->>'candidate_hash'
                   AND convert_from(candidate.document,'UTF8')::jsonb->'payload'->'citation_refs'=(
                     SELECT jsonb_agg(result->'evidence_ref' ORDER BY ordinal)
                     FROM jsonb_array_elements(output_json->'results') WITH ORDINALITY AS item(result,ordinal))
               ) THEN
                RAISE EXCEPTION 'final Citation candidate binding is invalid' USING ERRCODE='23514';
            END IF;
        ELSE
            RAISE EXCEPTION 'dynamic Citation operation purpose is invalid' USING ERRCODE='23514';
        END IF;
        IF EXISTS (
            SELECT 1 FROM jsonb_array_elements(binding_json->'results') WITH ORDINALITY binding(item,ordinal)
            JOIN jsonb_array_elements(output_json->'results') WITH ORDINALITY output(item,ordinal) USING (ordinal)
            WHERE NOT workflow.workspace_analysis_receipt_exact_object_keys(binding.item,ARRAY[
               'search_receipt_id','search_receipt_hash','search_evidence_ref','read_receipt_id','read_receipt_hash','evidence_ref','citation_id','index_version_id','chunk_id','source_version_id','source_span_id','content_hash'])
              OR jsonb_typeof(binding.item->'search_receipt_id')<>'string'
              OR jsonb_typeof(binding.item->'search_receipt_hash')<>'string'
              OR jsonb_typeof(binding.item->'search_evidence_ref')<>'string'
              OR jsonb_typeof(binding.item->'read_receipt_id')<>'string'
              OR jsonb_typeof(binding.item->'read_receipt_hash')<>'string'
              OR NOT workflow.workspace_analysis_receipt_canonical_uuid(binding.item->>'search_receipt_id')
              OR NOT workflow.workspace_analysis_receipt_canonical_uuid(binding.item->>'read_receipt_id')
              OR binding.item->>'read_receipt_id'=binding.item->>'search_receipt_id'
              OR NOT workflow.workspace_analysis_receipt_hash(binding.item->>'search_receipt_hash')
              OR NOT workflow.workspace_analysis_receipt_hash(binding.item->>'read_receipt_hash')
              OR binding.item->>'search_evidence_ref' !~ '^E[1-5]$'
              OR NOT workflow.workspace_analysis_dynamic_identity_valid(binding.item-ARRAY['search_receipt_id','search_receipt_hash','search_evidence_ref','read_receipt_id','read_receipt_hash'])
              OR binding.item->>'evidence_ref'<>output.item->>'evidence_ref'
              OR NOT workflow.workspace_analysis_dynamic_read_bound(NEW.workspace_id,NEW.workflow_run_id,operation_row.analysis_run_id,binding.item)
              OR NOT EXISTS (
                SELECT 1 FROM workflow.tool_result_receipt source_read
                JOIN agent.workspace_analysis_operation read_operation ON read_operation.tool_call_id=source_read.tool_call_id
                  AND read_operation.workspace_id=source_read.workspace_id AND read_operation.workflow_run_id=source_read.workflow_run_id
                  AND read_operation.analysis_run_id=operation_row.analysis_run_id
                  AND read_operation.node_key='decide_next' AND read_operation.operation_kind='SOURCE_READ'
                  AND read_operation.status='SUCCEEDED' AND read_operation.result_id=source_read.id
                  AND read_operation.result_hash=source_read.output_hash AND read_operation.result_kind='TOOL_RESULT_RECEIPT'
                WHERE source_read.id=(binding.item->>'read_receipt_id')::uuid
                  AND source_read.workspace_id=NEW.workspace_id AND source_read.workflow_run_id=NEW.workflow_run_id
                  AND source_read.tool_name='ReadSource' AND source_read.tool_version=4
                  AND source_read.output_hash=binding.item->>'read_receipt_hash'
                  AND convert_from(source_read.server_binding_document,'UTF8')::jsonb=binding.item-ARRAY['read_receipt_id','read_receipt_hash']
              )
        ) OR (SELECT count(DISTINCT item->>'evidence_ref') FROM jsonb_array_elements(output_json->'results') item)<>jsonb_array_length(output_json->'results') THEN
            RAISE EXCEPTION 'dynamic Citation exact Read/Search chain is invalid' USING ERRCODE='23514';
        END IF;
    ELSE
        RAISE EXCEPTION 'unsupported dynamic Tool receipt' USING ERRCODE='23514';
    END IF;
    RETURN NEW;
END;
$_$;


--
-- Name: guard_workspace_analysis_tool_receipt_closure(); Type: FUNCTION; Schema: workflow; Owner: -
--

CREATE FUNCTION workflow.guard_workspace_analysis_tool_receipt_closure() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    PERFORM agent.verify_workspace_analysis_tool_call_closure(NEW.tool_call_id);
    RETURN NULL;
END;
$$;


--
-- Name: reject_definition_mutation(); Type: FUNCTION; Schema: workflow; Owner: -
--

CREATE FUNCTION workflow.reject_definition_mutation() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    RAISE EXCEPTION 'workflow definition is immutable' USING ERRCODE = '55000';
END;
$$;


--
-- Name: reject_node_attempt_mutation(); Type: FUNCTION; Schema: workflow; Owner: -
--

CREATE FUNCTION workflow.reject_node_attempt_mutation() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF OLD.status <> 'running'
       OR NEW.node_run_id IS DISTINCT FROM OLD.node_run_id
       OR NEW.attempt_no IS DISTINCT FROM OLD.attempt_no
       OR NEW.dispatch_no IS DISTINCT FROM OLD.dispatch_no
       OR NEW.retry_no IS DISTINCT FROM OLD.retry_no
       OR NEW.river_job_id IS DISTINCT FROM OLD.river_job_id
       OR NEW.river_job_attempt IS DISTINCT FROM OLD.river_job_attempt
       OR NEW.delivery_id IS DISTINCT FROM OLD.delivery_id
       OR NEW.started_at IS DISTINCT FROM OLD.started_at
       OR NEW.created_at IS DISTINCT FROM OLD.created_at
    THEN
        RAISE EXCEPTION 'workflow node attempt is append-only' USING ERRCODE = '55000';
    END IF;
    IF OLD.status = 'running' AND NEW.status = 'running' THEN
        IF NEW.lease_owner IS DISTINCT FROM OLD.lease_owner
           OR NEW.river_job_id IS DISTINCT FROM OLD.river_job_id
           OR NEW.river_job_attempt IS DISTINCT FROM OLD.river_job_attempt
           OR NEW.node_run_id IS DISTINCT FROM OLD.node_run_id
           OR NEW.attempt_no IS DISTINCT FROM OLD.attempt_no
           OR NEW.dispatch_no IS DISTINCT FROM OLD.dispatch_no
           OR NEW.retry_no IS DISTINCT FROM OLD.retry_no
           OR NEW.delivery_id IS DISTINCT FROM OLD.delivery_id
           OR NEW.started_at IS DISTINCT FROM OLD.started_at
           OR NEW.output_schema_version IS DISTINCT FROM OLD.output_schema_version
           OR NEW.output_hash IS DISTINCT FROM OLD.output_hash
           OR NEW.failure_class IS DISTINCT FROM OLD.failure_class
           OR NEW.error_kind IS DISTINCT FROM OLD.error_kind
           OR NEW.error_code IS DISTINCT FROM OLD.error_code
           OR NEW.error_summary IS DISTINCT FROM OLD.error_summary
           OR NEW.next_attempt_at IS DISTINCT FROM OLD.next_attempt_at
           OR NEW.ended_at IS DISTINCT FROM OLD.ended_at
           OR NEW.created_at IS DISTINCT FROM OLD.created_at
        THEN
            RAISE EXCEPTION 'workflow running attempt identity is immutable' USING ERRCODE = '55000';
        END IF;
        RETURN NEW;
    END IF;
    IF NEW.status = 'running' OR NEW.ended_at IS NULL THEN
        RAISE EXCEPTION 'workflow node attempt may only transition running to a terminal status' USING ERRCODE = '55000';
    END IF;
    RETURN NEW;
END;
$$;


--
-- Name: river_job_state_in_bitmask(bit, workflow.river_job_state); Type: FUNCTION; Schema: workflow; Owner: -
--

CREATE FUNCTION workflow.river_job_state_in_bitmask(bitmask bit, state workflow.river_job_state) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    AS $$
    SELECT CASE state
        WHEN 'available' THEN get_bit(bitmask, 7)
        WHEN 'cancelled' THEN get_bit(bitmask, 6)
        WHEN 'completed' THEN get_bit(bitmask, 5)
        WHEN 'discarded' THEN get_bit(bitmask, 4)
        WHEN 'pending'   THEN get_bit(bitmask, 3)
        WHEN 'retryable' THEN get_bit(bitmask, 2)
        WHEN 'running'   THEN get_bit(bitmask, 1)
        WHEN 'scheduled' THEN get_bit(bitmask, 0)
        ELSE 0
    END = 1;
$$;


--
-- Name: workspace_analysis_dynamic_citation_id(uuid, jsonb); Type: FUNCTION; Schema: workflow; Owner: -
--

CREATE FUNCTION workflow.workspace_analysis_dynamic_citation_id(workspace uuid, document jsonb) RETURNS text
    LANGUAGE sql IMMUTABLE STRICT
    AS $$
 SELECT 'cite-' || encode(sha256(
   convert_to(workspace::text,'UTF8') || decode('00','hex') ||
   convert_to(document->>'index_version_id','UTF8') || decode('00','hex') ||
   convert_to(document->>'chunk_id','UTF8') || decode('00','hex') ||
   convert_to(document->>'source_version_id','UTF8') || decode('00','hex') ||
   convert_to(document->>'source_span_id','UTF8')),'hex')
$$;


--
-- Name: workspace_analysis_dynamic_identity_valid(jsonb); Type: FUNCTION; Schema: workflow; Owner: -
--

CREATE FUNCTION workflow.workspace_analysis_dynamic_identity_valid(document jsonb) RETURNS boolean
    LANGUAGE sql IMMUTABLE STRICT
    AS $_$
 SELECT COALESCE(
   jsonb_typeof(document->'evidence_ref')='string'
   AND document->>'evidence_ref' ~ '^E([1-9]|[12][0-9]|3[0-2])$'
   AND workflow.workspace_analysis_receipt_identity_valid(document || '{"evidence_ref":"E1"}'::jsonb,1),false)
$_$;


--
-- Name: workspace_analysis_dynamic_read_bound(uuid, uuid, uuid, jsonb); Type: FUNCTION; Schema: workflow; Owner: -
--

CREATE FUNCTION workflow.workspace_analysis_dynamic_read_bound(workspace uuid, run_id uuid, analysis_id uuid, document jsonb) RETURNS boolean
    LANGUAGE sql STABLE STRICT
    AS $$
 SELECT EXISTS (
   SELECT 1 FROM agent.workspace_analysis_evidence evidence
   JOIN workflow.tool_result_receipt search ON search.id=evidence.search_receipt_id
     AND search.workspace_id=evidence.workspace_id AND search.workflow_run_id=run_id
     AND search.tool_name='SearchKnowledge' AND search.tool_version=3
     AND search.output_hash=evidence.search_receipt_hash
   JOIN agent.workspace_analysis_operation operation ON operation.id=evidence.search_operation_id
     AND operation.workspace_id=evidence.workspace_id AND operation.analysis_run_id=evidence.analysis_run_id
     AND operation.workflow_run_id=run_id AND operation.node_key='decide_next'
     AND operation.operation_kind='KNOWLEDGE_SEARCH' AND operation.status='SUCCEEDED'
     AND operation.tool_call_id=search.tool_call_id AND operation.result_id=search.id
     AND operation.result_hash=search.output_hash AND operation.result_kind='TOOL_RESULT_RECEIPT'
   WHERE evidence.workspace_id=workspace AND evidence.analysis_run_id=analysis_id
     AND 'E'||evidence.reference_no::text=document->>'evidence_ref'
     AND evidence.search_receipt_id=(document->>'search_receipt_id')::uuid
     AND evidence.search_receipt_hash=document->>'search_receipt_hash'
     AND evidence.local_evidence_ref=document->>'search_evidence_ref'
     AND evidence.citation_id=document->>'citation_id'
     AND evidence.index_version_id=(document->>'index_version_id')::uuid
     AND evidence.chunk_id=(document->>'chunk_id')::uuid
     AND evidence.source_version_id=(document->>'source_version_id')::uuid
     AND evidence.source_span_id=(document->>'source_span_id')::uuid
     AND evidence.content_hash=document->>'content_hash'
     AND EXISTS (
       SELECT 1 FROM jsonb_array_elements(convert_from(search.server_binding_document,'UTF8')::jsonb->'items') item
       WHERE item=(document-ARRAY['search_receipt_id','search_receipt_hash','search_evidence_ref','read_receipt_id','read_receipt_hash'])
         || jsonb_build_object('evidence_ref',document->>'search_evidence_ref')
     )
 )
$$;


--
-- Name: workspace_analysis_dynamic_source_bound(uuid, jsonb); Type: FUNCTION; Schema: workflow; Owner: -
--

CREATE FUNCTION workflow.workspace_analysis_dynamic_source_bound(workspace uuid, document jsonb) RETURNS boolean
    LANGUAGE sql STABLE STRICT
    AS $$
 SELECT document->>'citation_id'=workflow.workspace_analysis_dynamic_citation_id(workspace,document)
 AND EXISTS (
   SELECT 1 FROM retrieval.index_manifest_chunk manifest
   JOIN ingestion.canonical_chunk chunk ON chunk.id=manifest.chunk_id
     AND chunk.workspace_id=manifest.workspace_id AND chunk.content_hash=manifest.content_hash
   JOIN retrieval.index_manifest_source source_manifest
     ON source_manifest.index_version_id=manifest.index_version_id
     AND source_manifest.workspace_id=manifest.workspace_id
     AND source_manifest.parse_projection_id=chunk.parse_projection_id
     AND source_manifest.source_version_id=(document->>'source_version_id')::uuid
     AND source_manifest.selection_status='included'
   JOIN core.source_version source_version ON source_version.id=source_manifest.source_version_id
     AND source_version.source_id=source_manifest.source_id
   JOIN core.source source ON source.id=source_version.source_id AND source.workspace_id=manifest.workspace_id
   JOIN core.content_artifact artifact ON artifact.id=source_version.content_artifact_id
     AND artifact.workspace_id=manifest.workspace_id AND artifact.content_hash=source_version.content_hash
     AND artifact.byte_size=source_version.byte_size
   JOIN ingestion.parse_projection projection ON projection.id=source_manifest.parse_projection_id
     AND projection.workspace_id=manifest.workspace_id AND projection.content_artifact_id=artifact.id
   JOIN ingestion.source_span span ON span.id=chunk.source_span_id
     AND span.workspace_id=manifest.workspace_id AND span.parse_projection_id=projection.id
     AND span.content_artifact_id=artifact.id
   WHERE manifest.workspace_id=workspace
     AND manifest.index_version_id=(document->>'index_version_id')::uuid
     AND manifest.chunk_id=(document->>'chunk_id')::uuid
     AND span.id=(document->>'source_span_id')::uuid
     AND span.excerpt_hash=document->>'content_hash'
 )
$$;


--
-- Name: workspace_analysis_receipt_canonical_json(json); Type: FUNCTION; Schema: workflow; Owner: -
--

CREATE FUNCTION workflow.workspace_analysis_receipt_canonical_json(document json) RETURNS text
    LANGUAGE plpgsql IMMUTABLE STRICT
    AS $$
DECLARE
    document_type text;
    result text;
    item record;
    previous_key text;
    has_previous boolean := false;
BEGIN
    document_type := json_typeof(document);
    IF document_type='object' THEN
        result := '{';
        FOR item IN
            SELECT entry.key,entry.value
              FROM json_each(document) AS entry(key,value)
             ORDER BY entry.key COLLATE "C"
        LOOP
            IF has_previous AND item.key=previous_key THEN
                RAISE EXCEPTION 'tool result receipt JSON contains a duplicate key' USING ERRCODE='23514';
            END IF;
            IF has_previous THEN
                result := result||',';
            END IF;
            result := result
                ||workflow.workspace_analysis_receipt_json_string(item.key)
                ||':'
                ||workflow.workspace_analysis_receipt_canonical_json(item.value);
            previous_key := item.key;
            has_previous := true;
        END LOOP;
        RETURN result||'}';
    ELSIF document_type='array' THEN
        result := '[';
        FOR item IN
            SELECT entry.value,entry.ordinal
              FROM json_array_elements(document) WITH ORDINALITY AS entry(value,ordinal)
             ORDER BY entry.ordinal
        LOOP
            IF has_previous THEN
                result := result||',';
            END IF;
            result := result||workflow.workspace_analysis_receipt_canonical_json(item.value);
            has_previous := true;
        END LOOP;
        RETURN result||']';
    ELSIF document_type='string' THEN
        RETURN workflow.workspace_analysis_receipt_json_string(document #>> '{}');
    ELSIF document_type IN ('number','boolean','null') THEN
        RETURN btrim(document::text, E' \t\n\r\f\v');
    END IF;
    RAISE EXCEPTION 'tool result receipt JSON type is invalid' USING ERRCODE='23514';
END;
$$;


--
-- Name: workspace_analysis_receipt_canonical_uuid(text); Type: FUNCTION; Schema: workflow; Owner: -
--

CREATE FUNCTION workflow.workspace_analysis_receipt_canonical_uuid(value text) RETURNS boolean
    LANGUAGE sql IMMUTABLE STRICT
    AS $_$
    SELECT value ~ '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
$_$;


--
-- Name: workspace_analysis_receipt_exact_object_keys(jsonb, text[]); Type: FUNCTION; Schema: workflow; Owner: -
--

CREATE FUNCTION workflow.workspace_analysis_receipt_exact_object_keys(document jsonb, keys text[]) RETURNS boolean
    LANGUAGE sql IMMUTABLE STRICT
    AS $$
    SELECT jsonb_typeof(document)='object'
       AND document ?& keys
       AND document-keys='{}'::jsonb
$$;


--
-- Name: workspace_analysis_receipt_hash(text); Type: FUNCTION; Schema: workflow; Owner: -
--

CREATE FUNCTION workflow.workspace_analysis_receipt_hash(value text) RETURNS boolean
    LANGUAGE sql IMMUTABLE STRICT
    AS $_$
    SELECT value ~ '^[0-9a-f]{64}$'
$_$;


--
-- Name: workspace_analysis_receipt_identity_valid(jsonb, integer); Type: FUNCTION; Schema: workflow; Owner: -
--

CREATE FUNCTION workflow.workspace_analysis_receipt_identity_valid(document jsonb, maximum_evidence_ref integer) RETURNS boolean
    LANGUAGE plpgsql IMMUTABLE STRICT
    AS $_$
DECLARE
    evidence_ref text;
BEGIN
    IF NOT workflow.workspace_analysis_receipt_exact_object_keys(document, ARRAY[
        'evidence_ref','citation_id','index_version_id','chunk_id','source_version_id','source_span_id','content_hash'
    ])
       OR jsonb_typeof(document->'evidence_ref')<>'string'
       OR jsonb_typeof(document->'citation_id')<>'string'
       OR jsonb_typeof(document->'index_version_id')<>'string'
       OR jsonb_typeof(document->'chunk_id')<>'string'
       OR jsonb_typeof(document->'source_version_id')<>'string'
       OR jsonb_typeof(document->'source_span_id')<>'string'
       OR jsonb_typeof(document->'content_hash')<>'string' THEN
        RETURN false;
    END IF;

    evidence_ref := document->>'evidence_ref';
    IF evidence_ref !~ '^E[1-9]$' OR substring(evidence_ref FROM 2)::integer>maximum_evidence_ref THEN
        RETURN false;
    END IF;
    RETURN (document->>'citation_id') ~ '^cite-[0-9a-f]{64}$'
       AND workflow.workspace_analysis_receipt_canonical_uuid(document->>'index_version_id')
       AND workflow.workspace_analysis_receipt_canonical_uuid(document->>'chunk_id')
       AND workflow.workspace_analysis_receipt_canonical_uuid(document->>'source_version_id')
       AND workflow.workspace_analysis_receipt_canonical_uuid(document->>'source_span_id')
       AND (document->>'index_version_id')<>(document->>'chunk_id')
       AND (document->>'index_version_id')<>(document->>'source_version_id')
       AND (document->>'index_version_id')<>(document->>'source_span_id')
       AND (document->>'chunk_id')<>(document->>'source_version_id')
       AND (document->>'chunk_id')<>(document->>'source_span_id')
       AND (document->>'source_version_id')<>(document->>'source_span_id')
       AND workflow.workspace_analysis_receipt_hash(document->>'content_hash');
END;
$_$;


--
-- Name: workspace_analysis_receipt_json_string(text); Type: FUNCTION; Schema: workflow; Owner: -
--

CREATE FUNCTION workflow.workspace_analysis_receipt_json_string(value text) RETURNS text
    LANGUAGE sql IMMUTABLE STRICT
    AS $$
    SELECT replace(
        replace(
            replace(
                replace(
                    replace(to_json(value)::text, '&', chr(92)||'u0026'),
                    '<', chr(92)||'u003c'
                ),
                '>', chr(92)||'u003e'
            ),
            chr(8232), chr(92)||'u2028'
        ),
        chr(8233), chr(92)||'u2029'
    )
$$;


--
-- Name: workspace_analysis_receipt_reference(text, integer); Type: FUNCTION; Schema: workflow; Owner: -
--

CREATE FUNCTION workflow.workspace_analysis_receipt_reference(value text, max_bytes integer) RETURNS boolean
    LANGUAGE sql IMMUTABLE STRICT
    AS $$
    SELECT value<>''
       AND value=btrim(value, E' \t\n\r\f\v')
       AND octet_length(value)<=max_bytes
       AND value !~ E'[\r\n]'
$$;


--
-- Name: workspace_analysis_receipt_text(text, integer); Type: FUNCTION; Schema: workflow; Owner: -
--

CREATE FUNCTION workflow.workspace_analysis_receipt_text(value text, max_bytes integer) RETURNS boolean
    LANGUAGE sql IMMUTABLE STRICT
    AS $$
    SELECT octet_length(value) BETWEEN 1 AND max_bytes
       AND value ~ '[^[:space:]]'
$$;


--
-- Name: answer; Type: TABLE; Schema: agent; Owner: -
--

CREATE TABLE agent.answer (
    id uuid NOT NULL,
    workspace_id uuid NOT NULL,
    conversation_id uuid NOT NULL,
    question_id uuid NOT NULL,
    workflow_run_id uuid NOT NULL,
    model_run_id uuid,
    publication_status text NOT NULL,
    result_type text,
    result jsonb,
    result_hash text,
    retrieval_summary jsonb,
    version bigint DEFAULT 1 NOT NULL,
    created_at timestamp with time zone NOT NULL,
    updated_at timestamp with time zone NOT NULL,
    published_at timestamp with time zone,
    CONSTRAINT agent_answer_payload_shape CHECK ((((result IS NULL) OR ((jsonb_typeof(result) = 'object'::text) AND (octet_length((result)::text) <= 262144))) AND ((retrieval_summary IS NULL) OR ((jsonb_typeof(retrieval_summary) = 'object'::text) AND (octet_length((retrieval_summary)::text) <= 16384))))),
    CONSTRAINT agent_answer_publication_bundle CHECK ((((publication_status = 'pending'::text) AND (model_run_id IS NULL) AND (result_type IS NULL) AND (result IS NULL) AND (result_hash IS NULL) AND (retrieval_summary IS NULL) AND (published_at IS NULL)) OR ((publication_status = 'completed'::text) AND (model_run_id IS NOT NULL) AND (result_type = 'rag_answer'::text) AND (result IS NOT NULL) AND (result_hash IS NOT NULL) AND (retrieval_summary IS NOT NULL) AND (published_at IS NOT NULL)) OR ((publication_status = 'refused'::text) AND (model_run_id IS NOT NULL) AND (result_type = 'refusal'::text) AND (result IS NOT NULL) AND (result_hash IS NOT NULL) AND (retrieval_summary IS NOT NULL) AND (published_at IS NOT NULL)) OR ((publication_status = 'clarification_required'::text) AND (model_run_id IS NOT NULL) AND (result_type = 'clarification'::text) AND (result IS NOT NULL) AND (result_hash IS NOT NULL) AND (retrieval_summary IS NOT NULL) AND (published_at IS NOT NULL)) OR ((publication_status = 'completed'::text) AND (model_run_id IS NOT NULL) AND (result_type = 'workspace_analysis'::text) AND (result IS NOT NULL) AND (result_hash IS NOT NULL) AND (retrieval_summary IS NULL) AND (published_at IS NOT NULL)) OR ((publication_status = 'refused'::text) AND (result_type = 'workspace_analysis_refusal'::text) AND (result IS NOT NULL) AND (result_hash IS NOT NULL) AND (retrieval_summary IS NULL) AND (published_at IS NOT NULL)) OR ((publication_status = 'clarification_required'::text) AND (model_run_id IS NOT NULL) AND (result_type = 'clarification'::text) AND (result IS NOT NULL) AND (result_hash IS NOT NULL) AND (retrieval_summary IS NULL) AND (published_at IS NOT NULL)) OR ((publication_status = ANY (ARRAY['failed'::text, 'cancelled'::text])) AND (result_type = 'workspace_analysis_termination'::text) AND (result IS NOT NULL) AND (result_hash IS NOT NULL) AND (retrieval_summary IS NULL) AND (published_at IS NOT NULL)))),
    CONSTRAINT agent_answer_publication_status_check CHECK ((publication_status = ANY (ARRAY['pending'::text, 'completed'::text, 'refused'::text, 'clarification_required'::text, 'failed'::text, 'cancelled'::text]))),
    CONSTRAINT agent_answer_result_type_check CHECK (((result_type IS NULL) OR (result_type = ANY (ARRAY['rag_answer'::text, 'refusal'::text, 'clarification'::text, 'workspace_analysis'::text, 'workspace_analysis_refusal'::text, 'workspace_analysis_termination'::text])))),
    CONSTRAINT agent_answer_time_order CHECK (((updated_at >= created_at) AND ((published_at IS NULL) OR ((published_at >= created_at) AND (published_at = updated_at))))),
    CONSTRAINT answer_result_hash_check CHECK (((result_hash IS NULL) OR (result_hash ~ '^[0-9a-f]{64}$'::text))),
    CONSTRAINT answer_version_check CHECK ((version > 0))
);


--
-- Name: answer_draft_chunk; Type: TABLE; Schema: agent; Owner: -
--

CREATE TABLE agent.answer_draft_chunk (
    session_id uuid NOT NULL,
    sequence bigint NOT NULL,
    content text NOT NULL,
    created_at timestamp with time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    CONSTRAINT answer_draft_chunk_content_check CHECK (((octet_length(content) > 0) AND (octet_length(content) <= 65536))),
    CONSTRAINT answer_draft_chunk_sequence_check CHECK ((sequence > 0))
);


--
-- Name: answer_draft_session; Type: TABLE; Schema: agent; Owner: -
--

CREATE TABLE agent.answer_draft_session (
    id uuid NOT NULL,
    workspace_id uuid NOT NULL,
    answer_id uuid NOT NULL,
    workflow_run_id uuid NOT NULL,
    node_run_id uuid NOT NULL,
    node_attempt_id uuid NOT NULL,
    attempt_no integer NOT NULL,
    lease_owner text NOT NULL,
    generation bigint NOT NULL,
    status text NOT NULL,
    next_sequence bigint DEFAULT 1 NOT NULL,
    total_bytes integer DEFAULT 0 NOT NULL,
    expires_at timestamp with time zone NOT NULL,
    created_at timestamp with time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    updated_at timestamp with time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    completed_at timestamp with time zone,
    CONSTRAINT answer_draft_session_attempt_no_check CHECK ((attempt_no > 0)),
    CONSTRAINT answer_draft_session_completed_at_valid CHECK ((((status = ANY (ARRAY['ACTIVE'::text, 'DEGRADED'::text])) AND (completed_at IS NULL)) OR ((status = ANY (ARRAY['COMPLETED'::text, 'PUBLISHED'::text, 'ABORTED'::text, 'SUPERSEDED'::text])) AND (completed_at IS NOT NULL)))),
    CONSTRAINT answer_draft_session_expiry_valid CHECK ((expires_at > created_at)),
    CONSTRAINT answer_draft_session_generation_check CHECK ((generation > 0)),
    CONSTRAINT answer_draft_session_lease_owner_check CHECK (((btrim(lease_owner) <> ''::text) AND (octet_length(lease_owner) <= 256))),
    CONSTRAINT answer_draft_session_next_sequence_check CHECK ((next_sequence > 0)),
    CONSTRAINT answer_draft_session_status_check CHECK ((status = ANY (ARRAY['ACTIVE'::text, 'COMPLETED'::text, 'DEGRADED'::text, 'PUBLISHED'::text, 'ABORTED'::text, 'SUPERSEDED'::text]))),
    CONSTRAINT answer_draft_session_total_bytes_check CHECK (((total_bytes >= 0) AND (total_bytes <= 4194304)))
);


--
-- Name: answer_feedback; Type: TABLE; Schema: agent; Owner: -
--

CREATE TABLE agent.answer_feedback (
    id uuid NOT NULL,
    workspace_id uuid NOT NULL,
    answer_id uuid NOT NULL,
    feedback_type text NOT NULL,
    citation_id text,
    comment text,
    idempotency_key text NOT NULL,
    request_hash text NOT NULL,
    created_at timestamp with time zone NOT NULL,
    CONSTRAINT answer_feedback_citation_id_check CHECK (((citation_id IS NULL) OR ((citation_id = btrim(citation_id)) AND (citation_id <> ''::text) AND (octet_length(citation_id) <= 128) AND (citation_id !~ '[\r\n]'::text)))),
    CONSTRAINT answer_feedback_comment_check CHECK (((comment IS NULL) OR ((comment = btrim(comment)) AND (btrim(comment) <> ''::text) AND (octet_length(comment) <= 2048)))),
    CONSTRAINT answer_feedback_feedback_type_check CHECK ((feedback_type = ANY (ARRAY['helpful'::text, 'incorrect'::text, 'irrelevant_citation'::text, 'broken_citation'::text, 'missing_source'::text]))),
    CONSTRAINT answer_feedback_idempotency_key_check CHECK (((idempotency_key = btrim(idempotency_key)) AND (idempotency_key <> ''::text) AND (octet_length(idempotency_key) <= 128) AND (idempotency_key !~ '[\r\n]'::text))),
    CONSTRAINT answer_feedback_request_hash_check CHECK ((request_hash ~ '^[0-9a-f]{64}$'::text))
);


--
-- Name: conversation; Type: TABLE; Schema: agent; Owner: -
--

CREATE TABLE agent.conversation (
    id uuid NOT NULL,
    workspace_id uuid NOT NULL,
    status text NOT NULL,
    title text,
    version bigint DEFAULT 1 NOT NULL,
    last_activity_at timestamp with time zone NOT NULL,
    created_at timestamp with time zone NOT NULL,
    updated_at timestamp with time zone NOT NULL,
    archived_at timestamp with time zone,
    idempotency_key text NOT NULL,
    request_hash text NOT NULL,
    CONSTRAINT agent_conversation_time_order CHECK (((updated_at >= created_at) AND (last_activity_at >= created_at) AND (((status = 'open'::text) AND (archived_at IS NULL)) OR ((status = 'archived'::text) AND (archived_at IS NOT NULL) AND (archived_at >= created_at))))),
    CONSTRAINT conversation_idempotency_key_check CHECK (((idempotency_key = btrim(idempotency_key)) AND (idempotency_key <> ''::text) AND (octet_length(idempotency_key) <= 128) AND (idempotency_key !~ '[\r\n]'::text))),
    CONSTRAINT conversation_request_hash_check CHECK ((request_hash ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT conversation_status_check CHECK ((status = ANY (ARRAY['open'::text, 'archived'::text]))),
    CONSTRAINT conversation_title_check CHECK (((title IS NULL) OR ((title = btrim(title)) AND (btrim(title) <> ''::text) AND (octet_length(title) <= 512)))),
    CONSTRAINT conversation_version_check CHECK ((version > 0))
);


--
-- Name: model_call; Type: TABLE; Schema: agent; Owner: -
--

CREATE TABLE agent.model_call (
    id uuid NOT NULL,
    model_run_id uuid NOT NULL,
    call_no smallint NOT NULL,
    phase text NOT NULL,
    adapter_name text NOT NULL,
    adapter_version text NOT NULL,
    model_id text NOT NULL,
    model_version text NOT NULL,
    profile_id text NOT NULL,
    profile_version text NOT NULL,
    prompt_template_id text NOT NULL,
    prompt_template_version text NOT NULL,
    output_schema_id text NOT NULL,
    output_schema_version text NOT NULL,
    max_output_tokens integer NOT NULL,
    request_hash text NOT NULL,
    response_hash text,
    request_bytes bigint NOT NULL,
    response_bytes bigint DEFAULT 0 NOT NULL,
    input_tokens bigint DEFAULT 0 NOT NULL,
    output_tokens bigint DEFAULT 0 NOT NULL,
    latency_ms bigint DEFAULT 0 NOT NULL,
    status text NOT NULL,
    error_code text,
    version bigint DEFAULT 1 NOT NULL,
    started_at timestamp with time zone NOT NULL,
    completed_at timestamp with time zone,
    CONSTRAINT agent_model_call_lifecycle CHECK ((((completed_at IS NULL) OR (completed_at >= started_at)) AND (((status = 'STARTED'::text) AND (completed_at IS NULL) AND (response_hash IS NULL) AND (response_bytes = 0) AND (input_tokens = 0) AND (output_tokens = 0) AND (latency_ms = 0) AND (error_code IS NULL)) OR ((status = 'SUCCEEDED'::text) AND (completed_at IS NOT NULL) AND (response_hash IS NOT NULL) AND (response_bytes > 0) AND (error_code IS NULL)) OR ((status = 'FAILED'::text) AND (completed_at IS NOT NULL) AND (error_code IS NOT NULL) AND (((response_hash IS NULL) AND (response_bytes = 0)) OR ((response_hash IS NOT NULL) AND (response_bytes > 0)))) OR ((status = 'UNKNOWN'::text) AND (completed_at IS NOT NULL) AND (response_hash IS NULL) AND (response_bytes = 0) AND (input_tokens = 0) AND (output_tokens = 0) AND (error_code IS NOT NULL))))),
    CONSTRAINT agent_model_call_phase_check CHECK ((phase = ANY (ARRAY['PLAN'::text, 'AGENT'::text, 'ANSWER'::text, 'INITIAL'::text, 'REPAIR'::text, 'REDUCED'::text, 'REVIEW'::text]))),
    CONSTRAINT agent_model_call_phase_order CHECK ((((phase = 'PLAN'::text) AND (call_no = 1)) OR ((phase = 'AGENT'::text) AND (call_no >= 1)) OR ((phase = 'ANSWER'::text) AND (call_no >= 1)) OR ((phase = 'INITIAL'::text) AND (call_no >= 1)) OR ((phase = 'REPAIR'::text) AND (call_no >= 2)) OR ((phase = 'REDUCED'::text) AND (call_no >= 3)) OR ((phase = 'REVIEW'::text) AND (call_no >= 1)))),
    CONSTRAINT model_call_adapter_name_check CHECK (((btrim(adapter_name) <> ''::text) AND (octet_length(adapter_name) <= 128))),
    CONSTRAINT model_call_adapter_version_check CHECK (((btrim(adapter_version) <> ''::text) AND (octet_length(adapter_version) <= 64))),
    CONSTRAINT model_call_call_no_check CHECK (((call_no > 0) AND (call_no <= 32))),
    CONSTRAINT model_call_error_code_check CHECK (((error_code IS NULL) OR ((btrim(error_code) <> ''::text) AND (error_code ~ '^[A-Z0-9_]+$'::text) AND (octet_length(error_code) <= 128)))),
    CONSTRAINT model_call_input_tokens_check CHECK (((input_tokens >= 0) AND (input_tokens <= 1000000))),
    CONSTRAINT model_call_latency_ms_check CHECK (((latency_ms >= 0) AND (latency_ms <= 600000))),
    CONSTRAINT model_call_max_output_tokens_check CHECK (((max_output_tokens > 0) AND (max_output_tokens <= 131072))),
    CONSTRAINT model_call_model_id_check CHECK (((btrim(model_id) <> ''::text) AND (octet_length(model_id) <= 128))),
    CONSTRAINT model_call_model_version_check CHECK (((btrim(model_version) <> ''::text) AND (octet_length(model_version) <= 64))),
    CONSTRAINT model_call_output_schema_id_check CHECK (((btrim(output_schema_id) <> ''::text) AND (octet_length(output_schema_id) <= 128))),
    CONSTRAINT model_call_output_schema_version_check CHECK (((btrim(output_schema_version) <> ''::text) AND (octet_length(output_schema_version) <= 64))),
    CONSTRAINT model_call_output_tokens_check CHECK (((output_tokens >= 0) AND (output_tokens <= 1000000))),
    CONSTRAINT model_call_profile_id_check CHECK (((btrim(profile_id) <> ''::text) AND (octet_length(profile_id) <= 128))),
    CONSTRAINT model_call_profile_version_check CHECK (((btrim(profile_version) <> ''::text) AND (octet_length(profile_version) <= 64))),
    CONSTRAINT model_call_prompt_template_id_check CHECK (((btrim(prompt_template_id) <> ''::text) AND (octet_length(prompt_template_id) <= 128))),
    CONSTRAINT model_call_prompt_template_version_check CHECK (((btrim(prompt_template_version) <> ''::text) AND (octet_length(prompt_template_version) <= 64))),
    CONSTRAINT model_call_request_bytes_check CHECK (((request_bytes > 0) AND (request_bytes <= 16777216))),
