    settled_input_tokens bigint DEFAULT 0 NOT NULL,
    settled_output_tokens bigint DEFAULT 0 NOT NULL,
    settled_cost_microunits bigint,
    created_at timestamp with time zone NOT NULL,
    settled_at timestamp with time zone,
    CONSTRAINT workspace_analysis_budget_reservat_reserved_output_tokens_check CHECK ((reserved_output_tokens >= 0)),
    CONSTRAINT workspace_analysis_budget_reservati_reserved_input_tokens_check CHECK ((reserved_input_tokens >= 0)),
    CONSTRAINT workspace_analysis_budget_reservati_reserved_source_reads_check CHECK ((reserved_source_reads >= 0)),
    CONSTRAINT workspace_analysis_budget_reservati_settled_output_tokens_check CHECK ((settled_output_tokens >= 0)),
    CONSTRAINT workspace_analysis_budget_reservatio_reserved_model_calls_check CHECK ((reserved_model_calls >= 0)),
    CONSTRAINT workspace_analysis_budget_reservatio_settled_input_tokens_check CHECK ((settled_input_tokens >= 0)),
    CONSTRAINT workspace_analysis_budget_reservatio_settled_source_reads_check CHECK ((settled_source_reads >= 0)),
    CONSTRAINT workspace_analysis_budget_reservation_call_kind_check CHECK ((call_kind = ANY (ARRAY['MODEL'::text, 'TOOL'::text]))),
    CONSTRAINT workspace_analysis_budget_reservation_reserved_tool_calls_check CHECK ((reserved_tool_calls >= 0)),
    CONSTRAINT workspace_analysis_budget_reservation_settled_model_calls_check CHECK ((settled_model_calls >= 0)),
    CONSTRAINT workspace_analysis_budget_reservation_settled_tool_calls_check CHECK ((settled_tool_calls >= 0)),
    CONSTRAINT workspace_analysis_budget_reservation_status_check CHECK ((status = ANY (ARRAY['RESERVED'::text, 'SETTLED'::text, 'UNKNOWN_CHARGED'::text]))),
    CONSTRAINT workspace_analysis_reservation_call CHECK ((((call_kind = 'MODEL'::text) AND (model_call_id IS NOT NULL) AND (tool_call_id IS NULL)) OR ((call_kind = 'TOOL'::text) AND (tool_call_id IS NOT NULL) AND (model_call_id IS NULL)))),
    CONSTRAINT workspace_analysis_reservation_settlement CHECK (((settled_model_calls <= reserved_model_calls) AND (settled_tool_calls <= reserved_tool_calls) AND (settled_source_reads <= reserved_source_reads) AND (settled_input_tokens <= reserved_input_tokens) AND (settled_output_tokens <= reserved_output_tokens) AND (((reserved_cost_microunits IS NULL) AND (settled_cost_microunits IS NULL)) OR ((reserved_cost_microunits IS NOT NULL) AND (reserved_cost_microunits >= 0) AND (settled_cost_microunits IS NOT NULL) AND ((settled_cost_microunits >= 0) AND (settled_cost_microunits <= reserved_cost_microunits)))) AND (((status = 'RESERVED'::text) AND (settled_at IS NULL) AND (settled_model_calls = 0) AND (settled_tool_calls = 0) AND (settled_source_reads = 0) AND (settled_input_tokens = 0) AND (settled_output_tokens = 0) AND ((settled_cost_microunits IS NULL) OR (settled_cost_microunits = 0))) OR ((status = 'SETTLED'::text) AND (settled_at IS NOT NULL) AND (settled_at >= created_at)) OR ((status = 'UNKNOWN_CHARGED'::text) AND (settled_at IS NOT NULL) AND (settled_at >= created_at) AND (settled_model_calls = reserved_model_calls) AND (settled_tool_calls = reserved_tool_calls) AND (settled_source_reads = reserved_source_reads) AND (settled_input_tokens = reserved_input_tokens) AND (settled_output_tokens = reserved_output_tokens) AND (NOT (settled_cost_microunits IS DISTINCT FROM reserved_cost_microunits)))))),
    CONSTRAINT workspace_analysis_reservation_shape CHECK ((((call_kind = 'MODEL'::text) AND (reserved_model_calls = 1) AND (reserved_tool_calls = 0) AND (reserved_source_reads = 0) AND (reserved_input_tokens = 65536) AND ((reserved_output_tokens >= 1) AND (reserved_output_tokens <= 4096)) AND (reserved_cost_microunits IS NULL)) OR ((call_kind = 'TOOL'::text) AND (reserved_model_calls = 0) AND (reserved_tool_calls = 1) AND (reserved_source_reads = ANY (ARRAY[0, 1])) AND (reserved_input_tokens = 0) AND (reserved_output_tokens = 0) AND (reserved_cost_microunits IS NULL))))
);


