    CONSTRAINT workspace_analysis_tool_refusal_slot CHECK ((((node_key = 'inspect_workspace'::text) AND (operation_kind = 'GIT_STATUS'::text) AND (ordinal = 1)) OR ((node_key = 'retrieve_evidence'::text) AND (operation_kind = 'KNOWLEDGE_SEARCH'::text) AND (ordinal = 1)) OR ((node_key = 'read_evidence'::text) AND (operation_kind = 'SOURCE_READ'::text) AND ((ordinal >= 1) AND (ordinal <= 3))) OR ((node_key = 'validate_citations'::text) AND (operation_kind = 'CITATION_VALIDATION'::text) AND (ordinal = 1))))
);


--
