    CONSTRAINT authoring_command_shape CHECK (((((command_type = 'CREATE'::text) AND (working_draft_id IS NOT NULL) AND (expected_version = 0) AND (result_draft_version = 1) AND (document_id IS NULL) AND (document_version IS NULL) AND (article_revision_id IS NULL) AND (revision_no IS NULL) AND (parent_revision_id IS NULL) AND (response_draft_created_at IS NOT NULL) AND (response_document_created_at IS NULL) AND (response_document_lifecycle IS NULL) AND (response_published_revision_id IS NULL) AND (response_title IS NULL) AND (response_target_path IS NULL) AND (response_content_hash IS NULL) AND (proposal_id IS NULL) AND (proposal_revision_id IS NULL)) OR ((command_type = 'UPDATE'::text) AND (working_draft_id IS NOT NULL) AND (expected_version > 0) AND (result_draft_version = (expected_version + 1)) AND (article_revision_id IS NULL) AND (revision_no IS NULL) AND (parent_revision_id IS NULL) AND (response_draft_created_at IS NOT NULL) AND (response_document_created_at IS NULL) AND (response_document_lifecycle IS NULL) AND (response_published_revision_id IS NULL) AND (response_title IS NULL) AND (response_target_path IS NULL) AND (response_content_hash IS NULL) AND (proposal_id IS NULL) AND (proposal_revision_id IS NULL)) OR ((command_type = 'FREEZE'::text) AND (working_draft_id IS NOT NULL) AND (expected_version > 0) AND (result_draft_version = (expected_version + 1)) AND (document_id IS NOT NULL) AND (document_version IS NOT NULL) AND (article_revision_id IS NOT NULL) AND (revision_no IS NOT NULL) AND ((revision_no > 1) OR (parent_revision_id IS NULL)) AND ((revision_no = 1) OR (parent_revision_id IS NOT NULL)) AND (response_draft_created_at IS NOT NULL) AND (response_document_created_at IS NOT NULL) AND (response_document_lifecycle IS NOT NULL) AND (response_title IS NOT NULL) AND (response_target_path IS NOT NULL) AND (response_content_hash IS NOT NULL) AND (proposal_id IS NULL) AND (proposal_revision_id IS NULL)) OR ((command_type = 'PUBLISH'::text) AND (working_draft_id IS NULL) AND (expected_version = 0) AND (result_draft_version IS NULL) AND (document_id IS NOT NULL) AND (document_version IS NOT NULL) AND (article_revision_id IS NOT NULL) AND (revision_no IS NOT NULL) AND (response_draft_created_at IS NULL) AND (response_document_created_at IS NOT NULL) AND (response_document_lifecycle IS NOT NULL) AND (response_title IS NOT NULL) AND (response_target_path IS NOT NULL) AND (response_content_hash IS NOT NULL) AND (proposal_id IS NOT NULL) AND (proposal_revision_id IS NOT NULL))) IS TRUE)),
    CONSTRAINT working_draft_command_command_type_check CHECK ((command_type = ANY (ARRAY['CREATE'::text, 'UPDATE'::text, 'FREEZE'::text, 'PUBLISH'::text]))),
    CONSTRAINT working_draft_command_document_version_check CHECK (((document_version IS NULL) OR (document_version > 0))),
    CONSTRAINT working_draft_command_expected_version_check CHECK ((expected_version >= 0)),
    CONSTRAINT working_draft_command_idempotency_key_check CHECK (((idempotency_key = btrim(idempotency_key)) AND (btrim(idempotency_key) <> ''::text) AND (octet_length(idempotency_key) <= 128) AND (idempotency_key !~ '[\r\n]'::text))),
    CONSTRAINT working_draft_command_request_hash_check CHECK ((request_hash ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT working_draft_command_response_content_hash_check CHECK (((response_content_hash IS NULL) OR (response_content_hash ~ '^[0-9a-f]{64}$'::text))),
    CONSTRAINT working_draft_command_response_document_lifecycle_check CHECK (((response_document_lifecycle IS NULL) OR (response_document_lifecycle = ANY (ARRAY['DRAFT'::text, 'PUBLISHED'::text, 'ARCHIVED'::text, 'DELETED'::text])))),
    CONSTRAINT working_draft_command_result_draft_version_check CHECK (((result_draft_version IS NULL) OR (result_draft_version > 0))),
    CONSTRAINT working_draft_command_revision_no_check CHECK (((revision_no IS NULL) OR (revision_no > 0)))
);


