);


--
-- Name: proposal_revision; Type: TABLE; Schema: change_control; Owner: -
--

CREATE TABLE change_control.proposal_revision (
    id uuid NOT NULL,
    proposal_id uuid NOT NULL,
    revision_no integer NOT NULL,
    target_path text,
    base_hash text,
    content text,
    evidence_summary text,
    risk text NOT NULL,
    rollback_plan text NOT NULL,
    change_hash text NOT NULL,
    created_at timestamp with time zone NOT NULL,
    target_refs jsonb,
    base_versions jsonb,
    change_set jsonb,
    evidence_refs jsonb,
    schema_version text,
    artifact_id uuid,
    artifact_revision_id uuid,
    artifact_revision_no bigint,
    artifact_version bigint,
    artifact_content_hash text,
    artifact_source_coverage jsonb,
    downstream_workspace_id uuid,
    downstream_report_id uuid,
    downstream_analysis_version text,
    downstream_report_fingerprint text,
    downstream_source_event_id uuid,
    downstream_source_event_version bigint,
    downstream_target_type text,
    downstream_target_id uuid,
    downstream_base_version bigint,
    downstream_action text,
    downstream_owner_binding jsonb,
    downstream_reason text,
    target_mode text DEFAULT 'REPLACE'::text NOT NULL,
    restore_workspace_id uuid,
    restore_document_id uuid,
    restore_target_commit text,
    restore_expected_head text,
    restore_expected_document_version bigint,
    restore_preview_hash text,
    restore_current_content_hash text,
    restore_target_content_hash text,
    CONSTRAINT ck_proposal_revision_artifact_content_hash CHECK (((artifact_content_hash IS NULL) OR (artifact_content_hash ~ '^[0-9a-f]{64}$'::text))),
    CONSTRAINT ck_proposal_revision_artifact_revision_no CHECK (((artifact_revision_no IS NULL) OR (artifact_revision_no > 0))),
    CONSTRAINT ck_proposal_revision_artifact_source_coverage CHECK (
CASE
    WHEN (artifact_source_coverage IS NULL) THEN true
    ELSE ((jsonb_typeof(artifact_source_coverage) = 'array'::text) AND (jsonb_array_length(artifact_source_coverage) > 0) AND (octet_length((artifact_source_coverage)::text) <= 65536))
END),
    CONSTRAINT ck_proposal_revision_artifact_version CHECK (((artifact_version IS NULL) OR (artifact_version > 0))),
    CONSTRAINT ck_proposal_revision_base_versions CHECK (
CASE
    WHEN (base_versions IS NULL) THEN true
    ELSE ((jsonb_typeof(base_versions) = 'array'::text) AND (jsonb_array_length(base_versions) > 0) AND (octet_length((base_versions)::text) <= 16384))
END),
    CONSTRAINT ck_proposal_revision_change_set CHECK (
CASE
    WHEN (change_set IS NULL) THEN true
    ELSE ((jsonb_typeof(change_set) = 'object'::text) AND (octet_length((change_set)::text) <= 32768))
END),
    CONSTRAINT ck_proposal_revision_downstream_base_version CHECK (((downstream_base_version IS NULL) OR (downstream_base_version > 0))),
    CONSTRAINT ck_proposal_revision_downstream_reason CHECK (((downstream_reason IS NULL) OR ((btrim(downstream_reason) <> ''::text) AND (downstream_reason = btrim(downstream_reason)) AND (octet_length(downstream_reason) <= 4096) AND (downstream_reason !~ E'[\r\n]'::text)))),
    CONSTRAINT ck_proposal_revision_downstream_report_fingerprint CHECK (((downstream_report_fingerprint IS NULL) OR (downstream_report_fingerprint ~ '^[0-9a-f]{64}$'::text))),
    CONSTRAINT ck_proposal_revision_downstream_source_version CHECK (((downstream_source_event_version IS NULL) OR (downstream_source_event_version > 0))),
    CONSTRAINT ck_proposal_revision_evidence_refs CHECK (
CASE
    WHEN (evidence_refs IS NULL) THEN true
    ELSE ((jsonb_typeof(evidence_refs) = 'array'::text) AND (jsonb_array_length(evidence_refs) > 0) AND (octet_length((evidence_refs)::text) <= 16384))
END),
    CONSTRAINT ck_proposal_revision_restore_commits CHECK ((((restore_target_commit IS NULL) AND (restore_expected_head IS NULL)) OR ((restore_target_commit ~ '^([0-9a-f]{40}|[0-9a-f]{64})$'::text) AND (restore_expected_head ~ '^([0-9a-f]{40}|[0-9a-f]{64})$'::text) AND (length(restore_target_commit) = length(restore_expected_head)) AND (restore_target_commit <> restore_expected_head)))),
    CONSTRAINT ck_proposal_revision_restore_hashes CHECK ((((restore_preview_hash IS NULL) AND (restore_current_content_hash IS NULL) AND (restore_target_content_hash IS NULL)) OR ((restore_preview_hash ~ '^[0-9a-f]{64}$'::text) AND (restore_current_content_hash ~ '^[0-9a-f]{64}$'::text) AND (restore_target_content_hash ~ '^[0-9a-f]{64}$'::text) AND (restore_current_content_hash <> restore_target_content_hash)))),
    CONSTRAINT ck_proposal_revision_restore_version CHECK (((restore_expected_document_version IS NULL) OR (restore_expected_document_version > 0))),
    CONSTRAINT ck_proposal_revision_schema_version CHECK (((schema_version IS NULL) OR ((btrim(schema_version) <> ''::text) AND (octet_length(schema_version) <= 128)))),
    CONSTRAINT ck_proposal_revision_target_refs CHECK (
CASE
    WHEN (target_refs IS NULL) THEN true
    ELSE ((jsonb_typeof(target_refs) = 'array'::text) AND (jsonb_array_length(target_refs) > 0) AND (octet_length((target_refs)::text) <= 16384))
END),
    CONSTRAINT proposal_revision_base_version_check CHECK ((((target_mode = 'REPLACE'::text) AND (base_hash ~ '^[0-9a-f]{64}$'::text)) OR ((target_mode = 'CREATE_ONLY'::text) AND (base_hash ~ '^workspace-target-absent/v1:[0-9a-f]{64}$'::text)))),
    CONSTRAINT proposal_revision_change_hash_check CHECK ((change_hash ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT proposal_revision_content_check CHECK ((btrim(content) <> ''::text)),
    CONSTRAINT proposal_revision_evidence_summary_check CHECK ((btrim(evidence_summary) <> ''::text)),
    CONSTRAINT proposal_revision_revision_no_check CHECK ((revision_no > 0)),
    CONSTRAINT proposal_revision_risk_check CHECK ((btrim(risk) <> ''::text)),
    CONSTRAINT proposal_revision_rollback_plan_check CHECK ((btrim(rollback_plan) <> ''::text)),
    CONSTRAINT proposal_revision_target_mode_check CHECK ((target_mode = ANY (ARRAY['REPLACE'::text, 'CREATE_ONLY'::text]))),
    CONSTRAINT proposal_revision_target_path_check CHECK (((btrim(target_path) <> ''::text) AND ("left"(target_path, 1) <> '/'::text) AND (target_path !~ '(^|/)\.\.(/|$)'::text) AND (POSITION(('\\'::text) IN (target_path)) = 0)))
);


