);


--
-- Name: tool_authorization; Type: TABLE; Schema: change_control; Owner: -
--

CREATE TABLE change_control.tool_authorization (
    id uuid NOT NULL,
    workspace_id uuid NOT NULL,
    workflow_run_id uuid NOT NULL,
    node_run_id uuid NOT NULL,
    proposal_id uuid NOT NULL,
    revision_id uuid NOT NULL,
    approval_id uuid NOT NULL,
    tool_name text NOT NULL,
    capability text NOT NULL,
    scope text NOT NULL,
    approved_change_hash text NOT NULL,
    target_version text NOT NULL,
    token_hash text NOT NULL,
    idempotency_key text NOT NULL,
    status text NOT NULL,
    issued_at timestamp with time zone NOT NULL,
    expires_at timestamp with time zone NOT NULL,
    revoked_at timestamp with time zone,
    consumed_at timestamp with time zone,
    version bigint DEFAULT 1 NOT NULL,
    target_mode text DEFAULT 'REPLACE'::text NOT NULL,
    CONSTRAINT tool_authorization_approved_change_hash_check CHECK ((approved_change_hash ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT tool_authorization_capability_check CHECK ((capability = ANY (ARRAY['WRITE_KNOWLEDGE'::text, 'GIT_WRITE'::text]))),
    CONSTRAINT tool_authorization_expiry CHECK (((expires_at > issued_at) AND (expires_at <= (issued_at + '00:05:00'::interval)))),
    CONSTRAINT tool_authorization_idempotency_key_check CHECK (((btrim(idempotency_key) <> ''::text) AND (char_length(idempotency_key) <= 128))),
    CONSTRAINT tool_authorization_scope_check CHECK (((btrim(scope) <> ''::text) AND (char_length(scope) <= 512))),
    CONSTRAINT tool_authorization_status_check CHECK ((status = ANY (ARRAY['issued'::text, 'consumed'::text, 'revoked'::text, 'expired'::text]))),
    CONSTRAINT tool_authorization_target_mode_check CHECK ((target_mode = ANY (ARRAY['REPLACE'::text, 'CREATE_ONLY'::text]))),
    CONSTRAINT tool_authorization_target_version_check CHECK ((btrim(target_version) <> ''::text)),
    CONSTRAINT tool_authorization_terminal_timestamps CHECK ((((status = 'consumed'::text) AND (consumed_at IS NOT NULL) AND (revoked_at IS NULL)) OR ((status = 'revoked'::text) AND (revoked_at IS NOT NULL) AND (consumed_at IS NULL)) OR ((status = 'expired'::text) AND (consumed_at IS NULL) AND (revoked_at IS NULL)) OR ((status = 'issued'::text) AND (consumed_at IS NULL) AND (revoked_at IS NULL)))),
    CONSTRAINT tool_authorization_timestamp_order CHECK ((((consumed_at IS NULL) OR ((consumed_at >= issued_at) AND (consumed_at < expires_at))) AND ((revoked_at IS NULL) OR (revoked_at >= issued_at)))),
    CONSTRAINT tool_authorization_token_hash_check CHECK ((token_hash ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT tool_authorization_tool_name_check CHECK (((btrim(tool_name) <> ''::text) AND (char_length(tool_name) <= 64))),
    CONSTRAINT tool_authorization_version_check CHECK ((version > 0))
);


--
-- Name: writeback_execution; Type: TABLE; Schema: change_control; Owner: -
--

CREATE TABLE change_control.writeback_execution (
    id uuid NOT NULL,
    workspace_id uuid NOT NULL,
    workflow_run_id uuid NOT NULL,
    node_run_id uuid NOT NULL,
    proposal_id uuid NOT NULL,
    revision_id uuid NOT NULL,
    approval_id uuid NOT NULL,
    write_authorization_id uuid NOT NULL,
    git_authorization_id uuid NOT NULL,
    target_path text NOT NULL,
    base_hash text NOT NULL,
    result_hash text NOT NULL,
    approved_change_hash text NOT NULL,
    approved_git_head text NOT NULL,
    git_commit text,
    parent_git_commit text,
    diff_hash text,
    status text NOT NULL,
    idempotency_key text NOT NULL,
    failure_code text,
    manual_recovery_required boolean DEFAULT false NOT NULL,
    temporary_ref text,
    backup_ref text,
    version bigint DEFAULT 1 NOT NULL,
    created_at timestamp with time zone NOT NULL,
    updated_at timestamp with time zone NOT NULL,
    completed_at timestamp with time zone,
    file_byte_size bigint,
    file_mode integer,
    file_lock_token text,
    file_result_lock_token text,
    file_backup_lock_token text,
    base_blob_id text,
    result_blob_id text,
    base_mode text,
    cleanup_completed_at timestamp with time zone,
    target_mode text DEFAULT 'REPLACE'::text NOT NULL,
    CONSTRAINT writeback_cleanup_status_valid CHECK (((cleanup_completed_at IS NULL) OR (status = ANY (ARRAY['verifying'::text, 'verify_failed'::text, 'rolled_back'::text, 'completed'::text])))),
    CONSTRAINT writeback_cleanup_time_valid CHECK (((cleanup_completed_at IS NULL) OR (cleanup_completed_at >= created_at))),
    CONSTRAINT writeback_execution_approved_change_hash_check CHECK ((approved_change_hash ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT writeback_execution_approved_git_head_check CHECK (((approved_git_head ~ '^[0-9a-f]{40}$'::text) OR (approved_git_head ~ '^[0-9a-f]{64}$'::text))),
    CONSTRAINT writeback_execution_backup_ref_check CHECK (((backup_ref IS NULL) OR ((btrim(backup_ref) <> ''::text) AND ("left"(backup_ref, 1) <> '/'::text) AND (backup_ref !~ '(^|/)\.\.(/|$)'::text) AND (POSITION(('\\'::text) IN (backup_ref)) = 0)))),
    CONSTRAINT writeback_execution_base_version_check CHECK ((((target_mode = 'REPLACE'::text) AND (base_hash ~ '^[0-9a-f]{64}$'::text)) OR ((target_mode = 'CREATE_ONLY'::text) AND (base_hash ~ '^workspace-target-absent/v1:[0-9a-f]{64}$'::text)))),
    CONSTRAINT writeback_execution_create_only_file_fields CHECK (((target_mode <> 'CREATE_ONLY'::text) OR (backup_ref IS NULL))),
    CONSTRAINT writeback_execution_create_only_git_intent CHECK (((target_mode <> 'CREATE_ONLY'::text) OR (base_blob_id IS NULL))),
    CONSTRAINT writeback_execution_create_only_lock_fields CHECK (((target_mode <> 'CREATE_ONLY'::text) OR (file_backup_lock_token IS NULL))),
    CONSTRAINT writeback_execution_diff_hash_check CHECK (((diff_hash IS NULL) OR (diff_hash ~ '^[0-9a-f]{64}$'::text))),
    CONSTRAINT writeback_execution_failure_code CHECK (((status <> ALL (ARRAY['needs_revision'::text, 'apply_failed'::text, 'publish_recovery_required'::text, 'manual_recovery_required'::text, 'verify_failed'::text])) OR (failure_code IS NOT NULL))),
    CONSTRAINT writeback_execution_failure_code_check CHECK (((failure_code IS NULL) OR ((btrim(failure_code) <> ''::text) AND (char_length(failure_code) <= 128)))),
    CONSTRAINT writeback_execution_git_commit_check CHECK (((git_commit IS NULL) OR (git_commit ~ '^[0-9a-f]{40}$'::text) OR (git_commit ~ '^[0-9a-f]{64}$'::text))),
    CONSTRAINT writeback_execution_git_fields CHECK ((((status = ANY (ARRAY['git_prepared'::text, 'git_committed'::text, 'verifying'::text, 'publish_recovery_required'::text, 'verify_failed'::text, 'rolled_back'::text, 'completed'::text])) AND (diff_hash IS NOT NULL)) OR ((status = ANY (ARRAY['prepared'::text, 'file_prepared'::text, 'file_applied'::text, 'needs_revision'::text, 'apply_failed'::text])) AND (diff_hash IS NULL)) OR (status = ANY (ARRAY['compensating_file'::text, 'compensated'::text, 'manual_recovery_required'::text])))),
    CONSTRAINT writeback_execution_git_result CHECK ((((status = ANY (ARRAY['git_committed'::text, 'verifying'::text, 'publish_recovery_required'::text, 'verify_failed'::text, 'rolled_back'::text, 'completed'::text])) AND (git_commit IS NOT NULL) AND (parent_git_commit IS NOT NULL)) OR ((status <> ALL (ARRAY['git_committed'::text, 'verifying'::text, 'publish_recovery_required'::text, 'verify_failed'::text, 'rolled_back'::text, 'completed'::text])) AND (git_commit IS NULL) AND (parent_git_commit IS NULL)))),
    CONSTRAINT writeback_execution_idempotency_key_check CHECK (((btrim(idempotency_key) <> ''::text) AND (char_length(idempotency_key) <= 128))),
    CONSTRAINT writeback_execution_manual_recovery CHECK ((manual_recovery_required = (status = 'manual_recovery_required'::text))),
    CONSTRAINT writeback_execution_parent_git_commit_check CHECK (((parent_git_commit IS NULL) OR (parent_git_commit ~ '^[0-9a-f]{40}$'::text) OR (parent_git_commit ~ '^[0-9a-f]{64}$'::text))),
    CONSTRAINT writeback_execution_result_hash_check CHECK ((result_hash ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT writeback_execution_status_check CHECK ((status = ANY (ARRAY['prepared'::text, 'file_prepared'::text, 'file_applied'::text, 'git_prepared'::text, 'git_committed'::text, 'verifying'::text, 'needs_revision'::text, 'apply_failed'::text, 'compensating_file'::text, 'compensated'::text, 'manual_recovery_required'::text, 'publish_recovery_required'::text, 'verify_failed'::text, 'rolled_back'::text, 'completed'::text]))),
    CONSTRAINT writeback_execution_target_mode_check CHECK ((target_mode = ANY (ARRAY['REPLACE'::text, 'CREATE_ONLY'::text]))),
    CONSTRAINT writeback_execution_target_path_check CHECK (((btrim(target_path) <> ''::text) AND ("left"(target_path, 1) <> '/'::text) AND (target_path !~ '(^|/)\.\.(/|$)'::text) AND (POSITION(('\\'::text) IN (target_path)) = 0))),
    CONSTRAINT writeback_execution_temporary_ref_check CHECK (((temporary_ref IS NULL) OR ((btrim(temporary_ref) <> ''::text) AND ("left"(temporary_ref, 1) <> '/'::text) AND (temporary_ref !~ '(^|/)\.\.(/|$)'::text) AND (POSITION(('\\'::text) IN (temporary_ref)) = 0)))),
    CONSTRAINT writeback_execution_time_order CHECK (((updated_at >= created_at) AND ((completed_at IS NULL) OR (completed_at >= created_at)))),
    CONSTRAINT writeback_execution_version_check CHECK ((version > 0)),
    CONSTRAINT writeback_file_lock_token_valid CHECK (((file_lock_token IS NULL) OR (file_lock_token ~ '^[0-9a-f]{64}$'::text))),
    CONSTRAINT writeback_file_managed_lock_tokens_valid CHECK ((((target_mode = 'REPLACE'::text) AND (((file_result_lock_token IS NULL) AND (file_backup_lock_token IS NULL)) OR ((file_lock_token IS NOT NULL) AND (file_result_lock_token IS NOT NULL) AND (file_backup_lock_token IS NOT NULL) AND (file_result_lock_token ~ '^[0-9a-f]{64}$'::text) AND (file_backup_lock_token ~ '^[0-9a-f]{64}$'::text) AND (file_result_lock_token <> file_backup_lock_token) AND (file_result_lock_token <> file_lock_token) AND (file_backup_lock_token <> file_lock_token)))) OR ((target_mode = 'CREATE_ONLY'::text) AND (((file_result_lock_token IS NULL) AND (file_backup_lock_token IS NULL)) OR ((file_lock_token IS NOT NULL) AND (file_result_lock_token IS NOT NULL) AND (file_backup_lock_token IS NULL) AND (file_result_lock_token ~ '^[0-9a-f]{64}$'::text) AND (file_result_lock_token <> file_lock_token)))))),
    CONSTRAINT writeback_file_mode_valid CHECK (((file_mode IS NULL) OR ((file_mode >= 0) AND (file_mode <= 4095)))),
    CONSTRAINT writeback_file_prepared_fields CHECK (((status <> 'file_prepared'::text) OR ((temporary_ref IS NOT NULL) AND (file_byte_size IS NOT NULL) AND (file_mode IS NOT NULL) AND (file_lock_token IS NOT NULL) AND (file_result_lock_token IS NOT NULL) AND (((target_mode = 'REPLACE'::text) AND (backup_ref IS NOT NULL) AND (file_backup_lock_token IS NOT NULL)) OR ((target_mode = 'CREATE_ONLY'::text) AND (backup_ref IS NULL) AND (file_backup_lock_token IS NULL)))))),
    CONSTRAINT writeback_file_size_valid CHECK (((file_byte_size IS NULL) OR ((file_byte_size > 0) AND (file_byte_size <= 10485760)))),
    CONSTRAINT writeback_git_intent_status_valid CHECK (((result_blob_id IS NULL) OR (status = ANY (ARRAY['git_prepared'::text, 'git_committed'::text, 'verifying'::text, 'publish_recovery_required'::text, 'compensating_file'::text, 'compensated'::text, 'manual_recovery_required'::text, 'verify_failed'::text, 'rolled_back'::text, 'completed'::text])))),
    CONSTRAINT writeback_git_object_ids_valid CHECK (((((target_mode = 'REPLACE'::text) AND ((base_blob_id IS NULL) OR (base_blob_id ~ '^[0-9a-f]{40}$'::text) OR (base_blob_id ~ '^[0-9a-f]{64}$'::text))) OR ((target_mode = 'CREATE_ONLY'::text) AND (base_blob_id IS NULL))) AND ((result_blob_id IS NULL) OR (result_blob_id ~ '^[0-9a-f]{40}$'::text) OR (result_blob_id ~ '^[0-9a-f]{64}$'::text)) AND ((base_mode IS NULL) OR (base_mode = ANY (ARRAY['100644'::text, '100755'::text]))))),
    CONSTRAINT writeback_git_prepared_fields CHECK ((((target_mode = 'REPLACE'::text) AND (((base_blob_id IS NULL) AND (result_blob_id IS NULL) AND (base_mode IS NULL)) OR ((base_blob_id IS NOT NULL) AND (result_blob_id IS NOT NULL) AND (base_mode IS NOT NULL) AND (length(base_blob_id) = length(approved_git_head)) AND (length(result_blob_id) = length(approved_git_head))))) OR ((target_mode = 'CREATE_ONLY'::text) AND (base_blob_id IS NULL) AND (((result_blob_id IS NULL) AND (base_mode IS NULL)) OR ((result_blob_id IS NOT NULL) AND (base_mode IS NOT NULL) AND (length(result_blob_id) = length(approved_git_head))))))),
    CONSTRAINT writeback_git_prepared_status_fields CHECK (((status <> 'git_prepared'::text) OR ((result_blob_id IS NOT NULL) AND (base_mode IS NOT NULL) AND (diff_hash IS NOT NULL) AND (((target_mode = 'REPLACE'::text) AND (base_blob_id IS NOT NULL)) OR ((target_mode = 'CREATE_ONLY'::text) AND (base_blob_id IS NULL))))))
);


