    updated_at timestamp with time zone NOT NULL,
    CONSTRAINT capture_display_name_check CHECK (((display_name = btrim(display_name)) AND (btrim(display_name) <> ''::text) AND (octet_length(display_name) <= 512) AND (display_name !~ '[\r\n]'::text))),
    CONSTRAINT capture_error_code_check CHECK (((octet_length(error_code) <= 128) AND (error_code !~ '[\r\n]'::text))),
    CONSTRAINT capture_failure_shape CHECK (((((failure_stage = ''::text) AND (error_code = ''::text) AND (retryable = false)) OR ((failure_stage <> ''::text) AND (error_code <> ''::text))) AND ((status <> ALL (ARRAY['FETCH_FAILED'::text, 'PROCESSING_FAILED'::text])) OR (error_code <> ''::text)))),
    CONSTRAINT capture_failure_stage_check CHECK (((octet_length(failure_stage) <= 128) AND (failure_stage !~ '[\r\n]'::text))),
    CONSTRAINT capture_fetch_status_check CHECK ((fetch_status = ANY (ARRAY['PENDING'::text, 'RUNNING'::text, 'READY'::text, 'FAILED'::text, 'CAPABILITY_UNAVAILABLE'::text, 'NOT_APPLICABLE'::text]))),
    CONSTRAINT capture_index_status_check CHECK ((index_status = ANY (ARRAY['PENDING'::text, 'RUNNING'::text, 'READY'::text, 'FAILED'::text, 'CAPABILITY_UNAVAILABLE'::text, 'NOT_APPLICABLE'::text]))),
    CONSTRAINT capture_ingestion_status_check CHECK ((ingestion_status = ANY (ARRAY['PENDING'::text, 'RUNNING'::text, 'READY'::text, 'FAILED'::text, 'CAPABILITY_UNAVAILABLE'::text, 'NOT_APPLICABLE'::text]))),
    CONSTRAINT capture_input_shape CHECK ((((kind = 'URL'::text) AND (original_url IS NOT NULL) AND (original_input_hash IS NULL)) OR ((kind <> 'URL'::text) AND (original_url IS NULL) AND (original_input_hash IS NOT NULL) AND (latest_source_version_id IS NOT NULL)))),
    CONSTRAINT capture_kind_check CHECK ((kind = ANY (ARRAY['TEXT'::text, 'URL'::text, 'FILE'::text, 'IMAGE'::text]))),
    CONSTRAINT capture_original_input_hash_check CHECK (((original_input_hash IS NULL) OR (original_input_hash ~ '^[0-9a-f]{64}$'::text))),
    CONSTRAINT capture_original_location_check CHECK (((original_location = btrim(original_location)) AND (btrim(original_location) <> ''::text) AND (octet_length(original_location) <= 4096) AND (original_location !~ '[\r\n]'::text))),
    CONSTRAINT capture_original_url_check CHECK (((original_url IS NULL) OR ((original_url = btrim(original_url)) AND (btrim(original_url) <> ''::text) AND (octet_length(original_url) <= 8192) AND (original_url !~ '[\r\n]'::text)))),
    CONSTRAINT capture_profile_status_check CHECK ((profile_status = ANY (ARRAY['PENDING'::text, 'RUNNING'::text, 'READY'::text, 'FAILED'::text, 'CAPABILITY_UNAVAILABLE'::text, 'STALE'::text, 'NOT_APPLICABLE'::text]))),
    CONSTRAINT capture_status_check CHECK ((status = ANY (ARRAY['RECEIVED'::text, 'SOURCE_SAVED'::text, 'FETCHING'::text, 'PROCESSING'::text, 'READY'::text, 'READY_DEGRADED'::text, 'FETCH_FAILED'::text, 'PROCESSING_FAILED'::text]))),
    CONSTRAINT capture_times CHECK ((updated_at >= captured_at)),
    CONSTRAINT capture_unmaterialized_state CHECK (((latest_source_version_id IS NOT NULL) OR ((kind = 'URL'::text) AND (status = ANY (ARRAY['RECEIVED'::text, 'FETCHING'::text, 'FETCH_FAILED'::text]))))),
    CONSTRAINT capture_version_check CHECK ((version > 0))
);


