    CONSTRAINT knowledge_conflict_resolution_binding CHECK ((((status = ANY (ARRAY['RESOLVED'::text, 'ACCEPTED_DIVERGENCE'::text])) AND (resolution IS NOT NULL) AND (resolution_reference IS NOT NULL) AND (resolved_at IS NOT NULL)) OR ((status <> ALL (ARRAY['RESOLVED'::text, 'ACCEPTED_DIVERGENCE'::text])) AND (resolution IS NULL) AND (resolution_reference IS NULL) AND (resolved_at IS NULL)))),
    CONSTRAINT knowledge_conflict_time_order CHECK (((updated_at >= created_at) AND ((resolved_at IS NULL) OR (resolved_at >= created_at))))
);


