--

CREATE TABLE core.relation (
    id uuid NOT NULL,
    workspace_id uuid NOT NULL,
    source_node_type text NOT NULL,
    source_node_id uuid NOT NULL,
    target_node_type text NOT NULL,
    target_node_id uuid NOT NULL,
