    confirmation_ref text,
    valid_from timestamp with time zone,
    valid_to timestamp with time zone,
    version bigint DEFAULT 1 NOT NULL,
    created_at timestamp with time zone NOT NULL,
    updated_at timestamp with time zone NOT NULL,
    CONSTRAINT knowledge_relation_confirmation_binding CHECK ((((status = ANY (ARRAY['CONFIRMED'::text, 'STALE'::text, 'DEPRECATED'::text])) AND (confirmation_method IS NOT NULL) AND (confirmation_ref IS NOT NULL) AND (evidence_fingerprint IS NOT NULL)) OR ((status = 'SUGGESTED'::text) AND (confirmation_method IS NULL) AND (confirmation_ref IS NULL)) OR (status = 'REJECTED'::text))),
    CONSTRAINT knowledge_relation_confirmation_pair CHECK ((((confirmation_method IS NULL) AND (confirmation_ref IS NULL)) OR ((confirmation_method IS NOT NULL) AND (confirmation_ref IS NOT NULL)))),
    CONSTRAINT knowledge_relation_distinct_endpoints CHECK (((source_node_type <> target_node_type) OR (source_node_id <> target_node_id))),
    CONSTRAINT knowledge_relation_symmetric_canonical CHECK (((relation_type <> ALL (ARRAY['DUPLICATES'::text, 'CONFLICTS_WITH'::text])) OR (source_node_type < target_node_type) OR ((source_node_type = target_node_type) AND ((source_node_id)::text < (target_node_id)::text)))),
    CONSTRAINT knowledge_relation_time_order CHECK ((updated_at >= created_at)),
    CONSTRAINT knowledge_relation_validity CHECK (((valid_to IS NULL) OR ((valid_from IS NOT NULL) AND (valid_to > valid_from)))),
    CONSTRAINT relation_confidence_score_check CHECK (((confidence_score IS NULL) OR ((confidence_score >= (0)::double precision) AND (confidence_score <= (1)::double precision)))),
    CONSTRAINT relation_confirmation_method_check CHECK (((confirmation_method IS NULL) OR (confirmation_method = ANY (ARRAY['USER_APPROVAL'::text, 'SOURCE_DERIVED'::text])))),
    CONSTRAINT relation_confirmation_ref_check CHECK (((confirmation_ref IS NULL) OR ((btrim(confirmation_ref) <> ''::text) AND (octet_length(confirmation_ref) <= 512)))),
    CONSTRAINT relation_evidence_fingerprint_check CHECK (((evidence_fingerprint IS NULL) OR (evidence_fingerprint ~ '^[0-9a-f]{64}$'::text))),
    CONSTRAINT relation_fingerprint_check CHECK ((fingerprint ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT relation_relation_type_check CHECK ((relation_type = ANY (ARRAY['CITES'::text, 'DERIVED_FROM'::text, 'BELONGS_TO'::text, 'SUPPORTS'::text, 'COMPLEMENTS'::text, 'DUPLICATES'::text, 'CONFLICTS_WITH'::text, 'PREREQUISITE_OF'::text, 'VERSION_OF'::text, 'IMPACTS'::text]))),
    CONSTRAINT relation_source_node_type_check CHECK ((source_node_type = ANY (ARRAY['TOPIC'::text, 'CLAIM'::text]))),
    CONSTRAINT relation_status_check CHECK ((status = ANY (ARRAY['SUGGESTED'::text, 'CONFIRMED'::text, 'REJECTED'::text, 'STALE'::text, 'DEPRECATED'::text]))),
    CONSTRAINT relation_target_node_type_check CHECK ((target_node_type = ANY (ARRAY['TOPIC'::text, 'CLAIM'::text]))),
    CONSTRAINT relation_version_check CHECK ((version > 0))
);


