--
-- Name: workspace; Type: TABLE; Schema: core; Owner: -
--

CREATE TABLE core.workspace (
    id uuid NOT NULL,
    name text NOT NULL,
    root_path text NOT NULL,
    git_repository_path text NOT NULL,
    git_branch text DEFAULT ''::text NOT NULL,
    git_head text DEFAULT ''::text NOT NULL,
    git_dirty boolean DEFAULT false NOT NULL,
    git_checked_at timestamp with time zone NOT NULL,
    status text NOT NULL,
    version bigint DEFAULT 1 NOT NULL,
    created_at timestamp with time zone NOT NULL,
    updated_at timestamp with time zone NOT NULL,
    root_fingerprint text,
    binding_version bigint DEFAULT 0 NOT NULL,
    availability text DEFAULT 'migration_required'::text NOT NULL,
    availability_reason text DEFAULT 'WORKSPACE_BINDING_LEGACY_DIRECT'::text,
    availability_checked_at timestamp with time zone DEFAULT clock_timestamp(),
    last_opened_at timestamp with time zone,
    removed_at timestamp with time zone,
    CONSTRAINT workspace_availability CHECK ((availability = ANY (ARRAY['available'::text, 'unavailable'::text, 'migration_required'::text]))),
    CONSTRAINT workspace_availability_shape CHECK (((((availability = 'available'::text) AND (availability_reason IS NULL) AND (availability_checked_at IS NOT NULL)) OR ((availability = ANY (ARRAY['unavailable'::text, 'migration_required'::text])) AND (availability_reason ~ '^[A-Z0-9_]{1,128}$'::text) AND (availability_checked_at IS NOT NULL))) IS TRUE)),
    CONSTRAINT workspace_git_repository_path_check CHECK ((btrim(git_repository_path) <> ''::text)),
    CONSTRAINT workspace_name_check CHECK ((btrim(name) <> ''::text)),
    CONSTRAINT workspace_registry_text_bounds CHECK (((octet_length(name) <= 256) AND (octet_length(root_path) <= 4096) AND (octet_length(git_repository_path) <= 4096))),
    CONSTRAINT workspace_registry_times CHECK ((((last_opened_at IS NULL) OR (last_opened_at >= created_at)) AND ((removed_at IS NULL) OR (removed_at >= created_at)))),
    CONSTRAINT workspace_removed_inactive CHECK (((removed_at IS NULL) OR (status = 'inactive'::text))),
    CONSTRAINT workspace_root_binding CHECK (((((binding_version = 0) AND (root_fingerprint IS NULL) AND (availability = 'migration_required'::text)) OR ((binding_version > 0) AND (root_fingerprint ~ '^[0-9a-f]{64}$'::text))) IS TRUE)),
    CONSTRAINT workspace_root_path_check CHECK ((btrim(root_path) <> ''::text)),
    CONSTRAINT workspace_status_lifecycle CHECK ((status = ANY (ARRAY['active'::text, 'inactive'::text]))),
    CONSTRAINT workspace_updated_after_created CHECK ((updated_at >= created_at)),
    CONSTRAINT workspace_version_check CHECK ((version > 0))
);


--
-- Name: workspace_git_capture_checkpoint; Type: TABLE; Schema: core; Owner: -
--

CREATE TABLE core.workspace_git_capture_checkpoint (
    workspace_id uuid NOT NULL,
    completed_head_oid text NOT NULL,
    inflight_run_id uuid,
    inflight_before_oid text,
    inflight_after_oid text,
    inflight_request_hash text,
    last_run_id uuid,
    last_before_oid text,
    last_after_oid text,
    last_request_hash text,
    version bigint NOT NULL,
    created_at timestamp with time zone NOT NULL,
    updated_at timestamp with time zone NOT NULL,
    CONSTRAINT git_capture_checkpoint_inflight_shape CHECK ((((inflight_run_id IS NULL) AND (inflight_before_oid IS NULL) AND (inflight_after_oid IS NULL) AND (inflight_request_hash IS NULL)) OR ((inflight_run_id IS NOT NULL) AND (inflight_before_oid ~ '^([0-9a-f]{40}|[0-9a-f]{64})$'::text) AND (inflight_after_oid ~ '^([0-9a-f]{40}|[0-9a-f]{64})$'::text) AND (inflight_before_oid <> inflight_after_oid) AND (inflight_request_hash ~ '^[0-9a-f]{64}$'::text) AND (completed_head_oid = inflight_before_oid)))),
    CONSTRAINT git_capture_checkpoint_last_shape CHECK ((((last_run_id IS NULL) AND (last_before_oid IS NULL) AND (last_after_oid IS NULL) AND (last_request_hash IS NULL)) OR ((last_run_id IS NOT NULL) AND (last_before_oid ~ '^([0-9a-f]{40}|[0-9a-f]{64})$'::text) AND (last_after_oid ~ '^([0-9a-f]{40}|[0-9a-f]{64})$'::text) AND (last_before_oid <> last_after_oid) AND (last_request_hash ~ '^[0-9a-f]{64}$'::text) AND (completed_head_oid = last_after_oid)))),
    CONSTRAINT git_capture_checkpoint_timestamps CHECK ((updated_at >= created_at)),
    CONSTRAINT workspace_git_capture_checkpoint_completed_head_oid_check CHECK ((completed_head_oid ~ '^([0-9a-f]{40}|[0-9a-f]{64})$'::text)),
    CONSTRAINT workspace_git_capture_checkpoint_version_check CHECK ((version > 0))
);


