--
-- Name: semantic_link_candidate; Type: TABLE; Schema: graph; Owner: -
--

CREATE TABLE graph.semantic_link_candidate (
    id uuid NOT NULL,
    workspace_id uuid NOT NULL,
    source_node_type text NOT NULL,
    source_node_id uuid NOT NULL,
    source_node_version bigint NOT NULL,
    target_node_type text NOT NULL,
    target_node_id uuid NOT NULL,
    target_node_version bigint NOT NULL,
    relation_type text NOT NULL,
    fingerprint_schema_version text NOT NULL,
    fingerprint text NOT NULL,
    status text NOT NULL,
    reopened_reason text,
    reopened_from_candidate_id uuid,
    current_proposal_id uuid,
    confidence_score double precision,
    reason text NOT NULL,
    source_summary text DEFAULT ''::text NOT NULL,
    source_excerpt text DEFAULT ''::text NOT NULL,
    target_summary text DEFAULT ''::text NOT NULL,
    target_excerpt text DEFAULT ''::text NOT NULL,
    discovery_methods jsonb NOT NULL,
    evidence_semantic_hashes jsonb NOT NULL,
    generation jsonb NOT NULL,
    deferred_until timestamp with time zone,
    version bigint DEFAULT 1 NOT NULL,
    created_at timestamp with time zone NOT NULL,
    updated_at timestamp with time zone NOT NULL,
    CONSTRAINT graph_semantic_link_candidate_deferred_binding CHECK (((deferred_until IS NULL) OR (status = 'DEFERRED'::text))),
    CONSTRAINT graph_semantic_link_candidate_distinct_endpoints CHECK (((source_node_type <> target_node_type) OR (source_node_id <> target_node_id))),
    CONSTRAINT graph_semantic_link_candidate_proposal_binding CHECK ((((status = 'PROPOSAL_CREATED'::text) AND (current_proposal_id IS NOT NULL)) OR (status = 'SUPERSEDED'::text) OR ((status = ANY (ARRAY['ACTIVE'::text, 'DEFERRED'::text, 'IGNORED'::text, 'FALSE_POSITIVE'::text])) AND (current_proposal_id IS NULL)))),
    CONSTRAINT graph_semantic_link_candidate_relation_compatibility CHECK ((((relation_type = ANY (ARRAY['CITES'::text, 'DERIVED_FROM'::text, 'SUPPORTS'::text, 'CONFLICTS_WITH'::text])) AND (source_node_type = 'CLAIM'::text) AND (target_node_type = 'CLAIM'::text)) OR ((relation_type = 'BELONGS_TO'::text) AND (source_node_type = 'CLAIM'::text) AND (target_node_type = 'TOPIC'::text)) OR ((relation_type = ANY (ARRAY['COMPLEMENTS'::text, 'DUPLICATES'::text, 'PREREQUISITE_OF'::text, 'VERSION_OF'::text])) AND (source_node_type = target_node_type)) OR (relation_type = 'IMPACTS'::text))),
    CONSTRAINT graph_semantic_link_candidate_reopen_binding CHECK ((((reopened_from_candidate_id IS NULL) AND (reopened_reason IS NULL)) OR ((reopened_from_candidate_id IS NOT NULL) AND (reopened_reason IS NOT NULL)))),
    CONSTRAINT graph_semantic_link_candidate_symmetric_canonical CHECK (((relation_type <> ALL (ARRAY['DUPLICATES'::text, 'CONFLICTS_WITH'::text])) OR (source_node_type < target_node_type) OR ((source_node_type = target_node_type) AND ((source_node_id)::text < (target_node_id)::text)))),
    CONSTRAINT graph_semantic_link_candidate_time_order CHECK ((updated_at >= created_at)),
    CONSTRAINT semantic_link_candidate_confidence_score_check CHECK (((confidence_score IS NULL) OR ((confidence_score >= (0)::double precision) AND (confidence_score <= (1)::double precision)))),
    CONSTRAINT semantic_link_candidate_discovery_methods_check CHECK (
CASE
    WHEN (discovery_methods IS NULL) THEN false
    ELSE ((jsonb_typeof(discovery_methods) = 'array'::text) AND (jsonb_array_length(discovery_methods) > 0) AND (octet_length((discovery_methods)::text) <= 4096))
END),
    CONSTRAINT semantic_link_candidate_evidence_semantic_hashes_check CHECK (
CASE
    WHEN (evidence_semantic_hashes IS NULL) THEN false
    ELSE ((jsonb_typeof(evidence_semantic_hashes) = 'array'::text) AND (jsonb_array_length(evidence_semantic_hashes) > 0) AND (octet_length((evidence_semantic_hashes)::text) <= 8192))
END),
    CONSTRAINT semantic_link_candidate_fingerprint_check CHECK ((fingerprint ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT semantic_link_candidate_fingerprint_schema_version_check CHECK (((btrim(fingerprint_schema_version) <> ''::text) AND (octet_length(fingerprint_schema_version) <= 128))),
    CONSTRAINT semantic_link_candidate_generation_check CHECK (
CASE
    WHEN (generation IS NULL) THEN false
    ELSE ((jsonb_typeof(generation) = 'object'::text) AND (octet_length((generation)::text) <= 16384))
END),
    CONSTRAINT semantic_link_candidate_reason_check CHECK (((btrim(reason) <> ''::text) AND (octet_length(reason) <= 4096))),
    CONSTRAINT semantic_link_candidate_relation_type_check CHECK ((relation_type = ANY (ARRAY['CITES'::text, 'DERIVED_FROM'::text, 'BELONGS_TO'::text, 'SUPPORTS'::text, 'COMPLEMENTS'::text, 'DUPLICATES'::text, 'CONFLICTS_WITH'::text, 'PREREQUISITE_OF'::text, 'VERSION_OF'::text, 'IMPACTS'::text]))),
    CONSTRAINT semantic_link_candidate_reopened_reason_check CHECK (((reopened_reason IS NULL) OR (reopened_reason = 'CONTENT_CHANGED'::text))),
    CONSTRAINT semantic_link_candidate_source_excerpt_check CHECK ((octet_length(source_excerpt) <= 4096)),
    CONSTRAINT semantic_link_candidate_source_node_type_check CHECK ((source_node_type = ANY (ARRAY['TOPIC'::text, 'CLAIM'::text]))),
    CONSTRAINT semantic_link_candidate_source_node_version_check CHECK ((source_node_version > 0)),
    CONSTRAINT semantic_link_candidate_source_summary_check CHECK ((octet_length(source_summary) <= 4096)),
    CONSTRAINT semantic_link_candidate_status_check CHECK ((status = ANY (ARRAY['ACTIVE'::text, 'DEFERRED'::text, 'IGNORED'::text, 'FALSE_POSITIVE'::text, 'PROPOSAL_CREATED'::text, 'SUPERSEDED'::text]))),
    CONSTRAINT semantic_link_candidate_target_excerpt_check CHECK ((octet_length(target_excerpt) <= 4096)),
    CONSTRAINT semantic_link_candidate_target_node_type_check CHECK ((target_node_type = ANY (ARRAY['TOPIC'::text, 'CLAIM'::text]))),
    CONSTRAINT semantic_link_candidate_target_node_version_check CHECK ((target_node_version > 0)),
    CONSTRAINT semantic_link_candidate_target_summary_check CHECK ((octet_length(target_summary) <= 4096)),
    CONSTRAINT semantic_link_candidate_version_check CHECK ((version > 0))
);


--
-- Name: semantic_link_candidate_decision; Type: TABLE; Schema: graph; Owner: -
--

CREATE TABLE graph.semantic_link_candidate_decision (
    id uuid NOT NULL,
    workspace_id uuid NOT NULL,
    candidate_id uuid NOT NULL,
    candidate_version bigint NOT NULL,
    proposal_id uuid,
    idempotency_key text NOT NULL,
    request_hash text NOT NULL,
    action text NOT NULL,
    relation_type text,
    reason text,
    defer_until timestamp with time zone,
    created_at timestamp with time zone NOT NULL,
    CONSTRAINT graph_semantic_link_candidate_decision_action_payload CHECK ((((action = 'CONFIRM'::text) AND (proposal_id IS NOT NULL) AND (relation_type IS NULL) AND (reason IS NULL)) OR ((action = 'CONFIRM_WITH_RELATION_TYPE'::text) AND (proposal_id IS NOT NULL) AND (relation_type IS NOT NULL) AND (reason IS NULL)) OR ((action = ANY (ARRAY['IGNORE'::text, 'FALSE_POSITIVE'::text])) AND (proposal_id IS NULL) AND (relation_type IS NULL) AND (reason IS NOT NULL)) OR ((action = 'DEFER'::text) AND (proposal_id IS NULL) AND (relation_type IS NULL)) OR ((action = 'RESUME'::text) AND (proposal_id IS NULL) AND (relation_type IS NULL) AND (reason IS NULL) AND (defer_until IS NULL)))),
    CONSTRAINT semantic_link_candidate_decision_action_check CHECK ((action = ANY (ARRAY['CONFIRM'::text, 'CONFIRM_WITH_RELATION_TYPE'::text, 'IGNORE'::text, 'FALSE_POSITIVE'::text, 'DEFER'::text, 'RESUME'::text]))),
    CONSTRAINT semantic_link_candidate_decision_candidate_version_check CHECK ((candidate_version > 0)),
    CONSTRAINT semantic_link_candidate_decision_idempotency_key_check CHECK (((btrim(idempotency_key) <> ''::text) AND (octet_length(idempotency_key) <= 128) AND (idempotency_key !~ '[\r\n]'::text))),
    CONSTRAINT semantic_link_candidate_decision_reason_check CHECK (((reason IS NULL) OR ((btrim(reason) <> ''::text) AND (octet_length(reason) <= 4096)))),
    CONSTRAINT semantic_link_candidate_decision_relation_type_check CHECK (((relation_type IS NULL) OR (relation_type = ANY (ARRAY['CITES'::text, 'DERIVED_FROM'::text, 'BELONGS_TO'::text, 'SUPPORTS'::text, 'COMPLEMENTS'::text, 'DUPLICATES'::text, 'CONFLICTS_WITH'::text, 'PREREQUISITE_OF'::text, 'VERSION_OF'::text, 'IMPACTS'::text])))),
    CONSTRAINT semantic_link_candidate_decision_request_hash_check CHECK ((request_hash ~ '^[0-9a-f]{64}$'::text))
);


--
-- Name: semantic_link_candidate_evidence; Type: TABLE; Schema: graph; Owner: -
--

CREATE TABLE graph.semantic_link_candidate_evidence (
    id uuid NOT NULL,
    workspace_id uuid NOT NULL,
    candidate_id uuid NOT NULL,
    source_version_id uuid NOT NULL,
    source_span_id uuid NOT NULL,
    evidence_no integer NOT NULL,
    semantic_hash text NOT NULL,
    summary text NOT NULL,
    excerpt text DEFAULT ''::text NOT NULL,
    created_at timestamp with time zone NOT NULL,
    CONSTRAINT semantic_link_candidate_evidence_evidence_no_check CHECK ((evidence_no > 0)),
    CONSTRAINT semantic_link_candidate_evidence_excerpt_check CHECK ((octet_length(excerpt) <= 4096)),
    CONSTRAINT semantic_link_candidate_evidence_semantic_hash_check CHECK ((semantic_hash ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT semantic_link_candidate_evidence_summary_check CHECK (((btrim(summary) <> ''::text) AND (octet_length(summary) <= 4096)))
);


--
-- Name: semantic_link_scan; Type: TABLE; Schema: graph; Owner: -
--

CREATE TABLE graph.semantic_link_scan (
    id uuid NOT NULL,
    workspace_id uuid NOT NULL,
    scope_type text NOT NULL,
    scope_ref text NOT NULL,
    scope_version bigint NOT NULL,
    scope_schema_version text NOT NULL,
    fingerprint text NOT NULL,
    idempotency_key text NOT NULL,
    request_hash text NOT NULL,
    workflow_run_id uuid NOT NULL,
    status text NOT NULL,
    total_nodes bigint DEFAULT 0 NOT NULL,
    processed_nodes bigint DEFAULT 0 NOT NULL,
    candidate_count bigint DEFAULT 0 NOT NULL,
    suppressed_count bigint DEFAULT 0 NOT NULL,
    reopened_count bigint DEFAULT 0 NOT NULL,
    failed_count bigint DEFAULT 0 NOT NULL,
    checkpoint jsonb DEFAULT '{}'::jsonb NOT NULL,
    last_error jsonb,
    version bigint DEFAULT 1 NOT NULL,
    created_at timestamp with time zone NOT NULL,
    updated_at timestamp with time zone NOT NULL,
    completed_at timestamp with time zone,
    scope_hash text,
    read_model_revision text,
    CONSTRAINT graph_semantic_link_scan_completion CHECK ((((status = ANY (ARRAY['SUCCEEDED'::text, 'FAILED'::text, 'CANCELLED'::text])) AND (completed_at IS NOT NULL)) OR ((status = ANY (ARRAY['PENDING'::text, 'RUNNING'::text])) AND (completed_at IS NULL)))),
    CONSTRAINT graph_semantic_link_scan_error CHECK ((((status = 'FAILED'::text) AND (last_error IS NOT NULL)) OR ((status <> 'FAILED'::text) AND (last_error IS NULL)))),
    CONSTRAINT graph_semantic_link_scan_progress CHECK (((processed_nodes <= total_nodes) OR (total_nodes = 0))),
    CONSTRAINT graph_semantic_link_scan_smart_collection_binding CHECK ((((scope_type = 'SMART_COLLECTION'::text) AND (scope_hash IS NOT NULL) AND (scope_hash ~ '^[0-9a-f]{64}$'::text) AND (read_model_revision IS NOT NULL) AND (read_model_revision ~ '^[0-9a-f]{64}$'::text)) OR ((scope_type <> 'SMART_COLLECTION'::text) AND (scope_hash IS NULL) AND (read_model_revision IS NULL)))),
    CONSTRAINT graph_semantic_link_scan_time_order CHECK (((updated_at >= created_at) AND ((completed_at IS NULL) OR (completed_at >= created_at)))),
    CONSTRAINT semantic_link_scan_candidate_count_check CHECK ((candidate_count >= 0)),
    CONSTRAINT semantic_link_scan_checkpoint_check CHECK (((jsonb_typeof(checkpoint) = 'object'::text) AND (octet_length((checkpoint)::text) <= 16384))),
    CONSTRAINT semantic_link_scan_failed_count_check CHECK ((failed_count >= 0)),
    CONSTRAINT semantic_link_scan_fingerprint_check CHECK ((fingerprint ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT semantic_link_scan_idempotency_key_check CHECK (((btrim(idempotency_key) <> ''::text) AND (octet_length(idempotency_key) <= 128) AND (idempotency_key !~ '[\r\n]'::text))),
    CONSTRAINT semantic_link_scan_last_error_check CHECK (
CASE
    WHEN (last_error IS NULL) THEN true
    ELSE ((jsonb_typeof(last_error) = 'object'::text) AND (octet_length((last_error)::text) <= 4096))
END),
    CONSTRAINT semantic_link_scan_processed_nodes_check CHECK ((processed_nodes >= 0)),
    CONSTRAINT semantic_link_scan_reopened_count_check CHECK ((reopened_count >= 0)),
    CONSTRAINT semantic_link_scan_request_hash_check CHECK ((request_hash ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT semantic_link_scan_scope_ref_check CHECK (((btrim(scope_ref) <> ''::text) AND (octet_length(scope_ref) <= 512) AND (scope_ref !~ '[\r\n]'::text))),
    CONSTRAINT semantic_link_scan_scope_schema_version_check CHECK (((btrim(scope_schema_version) <> ''::text) AND (octet_length(scope_schema_version) <= 128))),
    CONSTRAINT semantic_link_scan_scope_type_check CHECK ((scope_type = ANY (ARRAY['NODE'::text, 'TOPIC'::text, 'DIRECTORY'::text, 'SMART_COLLECTION'::text]))),
    CONSTRAINT semantic_link_scan_scope_version_check CHECK ((scope_version > 0)),
    CONSTRAINT semantic_link_scan_status_check CHECK ((status = ANY (ARRAY['PENDING'::text, 'RUNNING'::text, 'SUCCEEDED'::text, 'FAILED'::text, 'CANCELLED'::text]))),
    CONSTRAINT semantic_link_scan_suppressed_count_check CHECK ((suppressed_count >= 0)),
    CONSTRAINT semantic_link_scan_total_nodes_check CHECK ((total_nodes >= 0)),
    CONSTRAINT semantic_link_scan_version_check CHECK ((version > 0))
);


