    completed_at timestamp with time zone,
    version bigint DEFAULT 1 NOT NULL,
    CONSTRAINT attempt_attempt_number_check CHECK ((attempt_number > 0)),
    CONSTRAINT attempt_chunk_strategy_version_check CHECK ((btrim(chunk_strategy_version) <> ''::text)),
    CONSTRAINT attempt_idempotency_key_check CHECK ((btrim(idempotency_key) <> ''::text)),
    CONSTRAINT attempt_parser_config_hash_check CHECK ((parser_config_hash ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT attempt_parser_id_check CHECK ((btrim(parser_id) <> ''::text)),
    CONSTRAINT attempt_parser_version_check CHECK ((btrim(parser_version) <> ''::text)),
    CONSTRAINT attempt_schema_version_check CHECK ((btrim(schema_version) <> ''::text)),
    CONSTRAINT attempt_security_status_check CHECK ((security_status = ANY (ARRAY['pending'::text, 'passed'::text, 'quarantined'::text]))),
    CONSTRAINT attempt_status_check CHECK ((status = ANY (ARRAY['validating'::text, 'parsing'::text, 'parsed'::text, 'chunking'::text, 'chunked'::text, 'parse_failed'::text, 'cancelled'::text]))),
    CONSTRAINT attempt_version_check CHECK ((version > 0)),
    CONSTRAINT attempt_warnings_check CHECK ((jsonb_typeof(warnings) = 'array'::text)),
    CONSTRAINT ingestion_attempt_completion CHECK (((((status = ANY (ARRAY['chunked'::text, 'parse_failed'::text, 'cancelled'::text])) OR ((status = 'validating'::text) AND (security_status = 'quarantined'::text))) AND (completed_at IS NOT NULL)) OR ((status <> ALL (ARRAY['chunked'::text, 'parse_failed'::text, 'cancelled'::text])) AND (NOT ((status = 'validating'::text) AND (security_status = 'quarantined'::text))) AND (completed_at IS NULL)))),
    CONSTRAINT ingestion_attempt_processing_security CHECK (((status <> ALL (ARRAY['parsing'::text, 'parsed'::text, 'chunking'::text, 'chunked'::text])) OR (security_status = 'passed'::text))),
    CONSTRAINT ingestion_attempt_projection_state CHECK (((status <> ALL (ARRAY['parsed'::text, 'chunking'::text, 'chunked'::text])) OR (parse_projection_id IS NOT NULL))),
    CONSTRAINT ingestion_attempt_quarantine_state CHECK (((security_status <> 'quarantined'::text) OR (status = 'validating'::text))),
    CONSTRAINT ingestion_attempt_validating_security CHECK (((status <> 'validating'::text) OR (security_status <> 'passed'::text)))
);


