    CONSTRAINT learning_artifact_visibility_hold_active_digest_check CHECK (((disposition <> 'ACTIVE'::text) OR (attempt_digest IS NOT NULL))),
    CONSTRAINT learning_artifact_visibility_hold_digest_check CHECK (((attempt_digest IS NULL) OR (attempt_digest ~ '^[0-9a-f]{64}$'::text))),
    CONSTRAINT learning_artifact_visibility_hold_disposition_check CHECK ((disposition = ANY (ARRAY['ACTIVE'::text, 'ORPHANED'::text]))),
    CONSTRAINT learning_artifact_visibility_hold_owner_shape_check CHECK ((((owner_type = 'INTERVIEW_COMPLETE'::text) AND (owner_id = interview_session_id) AND (interview_session_id IS NOT NULL) AND (review_answer_id IS NULL) AND (owner_role = ANY (ARRAY['REPORT'::text, 'PATH'::text]))) OR ((owner_type = 'LEARNING_PATH_CREATE'::text) AND (owner_id = review_answer_id) AND (interview_session_id IS NULL) AND (review_answer_id IS NOT NULL) AND (owner_role = 'PATH'::text)))),
    CONSTRAINT learning_artifact_visibility_hold_owner_type_check CHECK ((owner_type = ANY (ARRAY['INTERVIEW_COMPLETE'::text, 'LEARNING_PATH_CREATE'::text])))
);


