-- Name: document_knowledge_profile; Type: TABLE; Schema: learning; Owner: -
--

CREATE TABLE learning.document_knowledge_profile (
    id uuid NOT NULL,
    workspace_id uuid NOT NULL,
    capture_id uuid NOT NULL,
    source_version_id uuid NOT NULL,
    current_revision_id uuid,
    status text NOT NULL,
    error_code text DEFAULT ''::text NOT NULL,
    retryable boolean DEFAULT false NOT NULL,
    version bigint DEFAULT 1 NOT NULL,
    created_at timestamp with time zone NOT NULL,
    updated_at timestamp with time zone NOT NULL,
    CONSTRAINT document_knowledge_profile_error_code_check CHECK (((octet_length(error_code) <= 128) AND (error_code !~ '[\r\n]'::text))),
    CONSTRAINT document_knowledge_profile_status_check CHECK ((status = ANY (ARRAY['PENDING'::text, 'RUNNING'::text, 'READY'::text, 'FAILED'::text, 'CAPABILITY_UNAVAILABLE'::text, 'STALE'::text]))),
    CONSTRAINT document_knowledge_profile_version_check CHECK ((version > 0)),
    CONSTRAINT document_profile_state_shape CHECK ((((status = 'READY'::text) AND (current_revision_id IS NOT NULL) AND (error_code = ''::text) AND (retryable = false)) OR ((status = ANY (ARRAY['PENDING'::text, 'RUNNING'::text])) AND (error_code = ''::text) AND (retryable = false)) OR ((status = 'STALE'::text) AND (current_revision_id IS NOT NULL) AND (error_code = ''::text) AND (retryable = false)) OR ((status = 'FAILED'::text) AND (error_code <> ''::text)) OR ((status = 'CAPABILITY_UNAVAILABLE'::text) AND (error_code <> ''::text) AND (retryable = false)))),
    CONSTRAINT document_profile_times CHECK ((updated_at >= created_at))
);


--
