    retryable boolean DEFAULT false NOT NULL,
    started_at timestamp with time zone NOT NULL,
    completed_at timestamp with time zone,
    version bigint DEFAULT 1 NOT NULL,
    CONSTRAINT document_knowledge_profile_attempt_attempt_number_check CHECK ((attempt_number > 0)),
    CONSTRAINT document_knowledge_profile_attempt_error_code_check CHECK (((octet_length(error_code) <= 128) AND (error_code !~ '[\r\n]'::text))),
    CONSTRAINT document_knowledge_profile_attempt_prompt_version_check CHECK (((btrim(prompt_version) <> ''::text) AND (octet_length(prompt_version) <= 128))),
    CONSTRAINT document_knowledge_profile_attempt_schema_version_check CHECK ((schema_version = 'document-knowledge-profile/v1'::text)),
    CONSTRAINT document_knowledge_profile_attempt_status_check CHECK ((status = ANY (ARRAY['RUNNING'::text, 'SUCCEEDED'::text, 'FAILED'::text, 'CAPABILITY_UNAVAILABLE'::text, 'CANCELLED'::text]))),
    CONSTRAINT document_knowledge_profile_attempt_version_check CHECK ((version > 0)),
    CONSTRAINT document_profile_attempt_completion CHECK ((((status = 'RUNNING'::text) AND (completed_at IS NULL) AND (error_code = ''::text) AND (retryable = false)) OR ((status = 'SUCCEEDED'::text) AND (completed_at IS NOT NULL) AND (error_code = ''::text) AND (retryable = false) AND (model_run_id IS NOT NULL)) OR ((status = 'CAPABILITY_UNAVAILABLE'::text) AND (completed_at IS NOT NULL) AND (error_code <> ''::text) AND (retryable = false) AND (model_run_id IS NULL)) OR ((status = ANY (ARRAY['FAILED'::text, 'CANCELLED'::text])) AND (completed_at IS NOT NULL) AND (error_code <> ''::text))))
);


