--

CREATE TABLE learning.interview_completion_reservation (
    workspace_id uuid NOT NULL,
    session_id uuid NOT NULL,
    idempotency_key text NOT NULL,
    request_hash text NOT NULL,
    manual_end boolean NOT NULL,
    snapshot_version bigint NOT NULL,
    artifact_digest text,
    report_id uuid,
    report_artifact_id uuid,
    report_artifact_revision_id uuid,
    report_artifact_version bigint,
    path_id uuid,
    path_artifact_id uuid,
    path_artifact_revision_id uuid,
    path_artifact_version bigint,
    status text NOT NULL,
    created_at timestamp with time zone NOT NULL,
    prepared_at timestamp with time zone,
    completed_at timestamp with time zone,
    abandoned_at timestamp with time zone,
    updated_at timestamp with time zone NOT NULL,
    CONSTRAINT interview_completion_reservation_artifact_digest_check CHECK (((artifact_digest IS NULL) OR (artifact_digest ~ '^[0-9a-f]{64}$'::text))),
    CONSTRAINT interview_completion_reservation_request_hash_check CHECK ((request_hash ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT interview_completion_reservation_snapshot_version_check CHECK ((snapshot_version > 0)),
    CONSTRAINT interview_completion_reservation_status_check CHECK ((status = ANY (ARRAY['PENDING'::text, 'COMPLETED'::text, 'ABANDONED'::text]))),
    CONSTRAINT learning_interview_completion_binding_shape_check CHECK ((((report_id IS NULL) AND (report_artifact_id IS NULL) AND (report_artifact_revision_id IS NULL) AND (report_artifact_version IS NULL) AND (path_id IS NULL) AND (path_artifact_id IS NULL) AND (path_artifact_revision_id IS NULL) AND (path_artifact_version IS NULL)) OR ((report_id IS NOT NULL) AND (report_artifact_id IS NOT NULL) AND (report_artifact_revision_id IS NOT NULL) AND (report_artifact_version > 0) AND (path_id IS NOT NULL) AND (path_artifact_id IS NOT NULL) AND (path_artifact_revision_id IS NOT NULL) AND (path_artifact_version > 0) AND (report_artifact_id <> path_artifact_id)))),
    CONSTRAINT learning_interview_completion_digest_time_check CHECK ((((artifact_digest IS NULL) AND (prepared_at IS NULL)) OR ((artifact_digest IS NOT NULL) AND (prepared_at IS NOT NULL)))),
    CONSTRAINT learning_interview_completion_key_check CHECK (((btrim(idempotency_key) <> ''::text) AND (octet_length(idempotency_key) <= 128))),
    CONSTRAINT learning_interview_completion_status_shape_check CHECK ((((status = 'PENDING'::text) AND (completed_at IS NULL) AND (abandoned_at IS NULL) AND (report_id IS NULL)) OR ((status = 'ABANDONED'::text) AND (completed_at IS NULL) AND (abandoned_at IS NOT NULL) AND (report_id IS NULL)) OR ((status = 'COMPLETED'::text) AND (artifact_digest IS NOT NULL) AND (completed_at IS NOT NULL) AND (abandoned_at IS NULL) AND (report_id IS NOT NULL)))),
    CONSTRAINT learning_interview_completion_time_order_check CHECK (((updated_at >= created_at) AND ((prepared_at IS NULL) OR ((prepared_at >= created_at) AND (updated_at >= prepared_at))) AND ((completed_at IS NULL) OR ((completed_at >= created_at) AND (updated_at >= completed_at))) AND ((abandoned_at IS NULL) OR ((abandoned_at >= created_at) AND (updated_at >= abandoned_at)))))
);


