    CONSTRAINT capture_outbox_schema_version_check CHECK ((schema_version = 'capture-process-event/v1'::text)),
    CONSTRAINT capture_outbox_terminal_shape CHECK (((NOT ((published_at IS NOT NULL) AND (poisoned_at IS NOT NULL))) AND ((NOT manual_recovery_required) OR (poisoned_at IS NOT NULL)) AND ((published_at IS NULL) OR (published_at >= created_at)) AND ((poisoned_at IS NULL) OR (poisoned_at >= created_at)) AND (updated_at >= created_at))),
