--
-- Name: export_job; Type: TABLE; Schema: ops; Owner: -
--

CREATE TABLE ops.export_job (
    id uuid NOT NULL,
    workspace_id uuid NOT NULL,
    kind text NOT NULL,
    schema_version text NOT NULL,
    query_definition jsonb DEFAULT '{}'::jsonb NOT NULL,
    fields jsonb DEFAULT '[]'::jsonb NOT NULL,
    status text NOT NULL,
    file_path text,
    file_hash text,
    error_code text,
    idempotency_key text NOT NULL,
    expires_at timestamp with time zone NOT NULL,
    created_at timestamp with time zone NOT NULL,
    updated_at timestamp with time zone NOT NULL,
    completed_at timestamp with time zone,
    collection_id uuid,
    collection_version bigint,
    query_hash text,
    redaction_policy text DEFAULT 'MASKED'::text NOT NULL,
    include_sensitive boolean DEFAULT false NOT NULL,
    permission_scope text DEFAULT 'READ_LOCAL'::text NOT NULL,
    requested_by text DEFAULT 'system'::text NOT NULL,
    request_hash text NOT NULL,
    request_ttl_seconds bigint NOT NULL,
    version bigint NOT NULL,
    read_model_revision text,
    exact_count bigint,
    prepared_at timestamp with time zone,
    prepared_staging_path text,
    file_size bigint DEFAULT 0 NOT NULL,
    error_message text,
    attempt_count integer DEFAULT 0 NOT NULL,
    lease_owner text,
    lease_expires_at timestamp with time zone,
    started_at timestamp with time zone,
    download_count integer DEFAULT 0 NOT NULL,
    last_downloaded_at timestamp with time zone,
    cleanup_status text DEFAULT 'NOT_REQUIRED'::text NOT NULL,
    cleanup_attempt_count integer DEFAULT 0 NOT NULL,
    cleanup_error text,
    cleanup_updated_at timestamp with time zone,
    file_deleted_at timestamp with time zone,
    scope_kind text DEFAULT 'COLLECTION'::text NOT NULL,
    attachment_root_contract_version text,
    manifest_sha256 text,
    entry_count bigint,
    total_uncompressed_bytes bigint,
    CONSTRAINT export_job_fields_check CHECK ((jsonb_typeof(fields) = 'array'::text)),
    CONSTRAINT export_job_file_hash_check CHECK (((file_hash IS NULL) OR (file_hash ~ '^[0-9a-f]{64}$'::text))),
    CONSTRAINT export_job_query_definition_check CHECK ((jsonb_typeof(query_definition) = 'object'::text)),
    CONSTRAINT export_job_schema_version_check CHECK ((btrim(schema_version) <> ''::text)),
    CONSTRAINT export_job_status_check CHECK ((status = ANY (ARRAY['PENDING'::text, 'RUNNING'::text, 'SUCCEEDED'::text, 'FAILED'::text, 'EXPIRED'::text, 'CANCELLED'::text]))),
    CONSTRAINT ops_export_job_cleanup_binding CHECK ((((status = 'EXPIRED'::text) = (cleanup_status <> 'NOT_REQUIRED'::text)) AND
CASE cleanup_status
    WHEN 'NOT_REQUIRED'::text THEN ((cleanup_attempt_count = 0) AND (cleanup_error IS NULL) AND (cleanup_updated_at IS NULL) AND (file_deleted_at IS NULL))
    WHEN 'PENDING'::text THEN ((cleanup_attempt_count = 0) AND (cleanup_error IS NULL) AND (cleanup_updated_at IS NULL) AND (file_deleted_at IS NULL))
    WHEN 'FAILED'::text THEN ((cleanup_attempt_count > 0) AND (cleanup_error IS NOT NULL) AND (cleanup_updated_at IS NOT NULL) AND (file_deleted_at IS NULL))
    WHEN 'SUCCEEDED'::text THEN ((cleanup_attempt_count > 0) AND (cleanup_error IS NULL) AND (cleanup_updated_at IS NOT NULL) AND (file_deleted_at IS NOT NULL) AND (file_deleted_at = cleanup_updated_at))
    ELSE false
END)),
    CONSTRAINT ops_export_job_counters CHECK (((file_size >= 0) AND (attempt_count >= 0) AND (download_count >= 0) AND (cleanup_attempt_count >= 0) AND ((exact_count IS NULL) OR ((exact_count >= 0) AND (exact_count <= 10000))) AND ((entry_count IS NULL) OR ((entry_count >= 0) AND (entry_count <= 10000))) AND ((total_uncompressed_bytes IS NULL) OR ((total_uncompressed_bytes >= 0) AND (total_uncompressed_bytes <= 1073741824))) AND ((scope_kind <> 'WORKSPACE_ATTACHMENTS'::text) OR (file_size <= 1073741824)))),
    CONSTRAINT ops_export_job_download_binding CHECK ((((download_count = 0) AND (last_downloaded_at IS NULL)) OR ((download_count > 0) AND (last_downloaded_at IS NOT NULL) AND (status = ANY (ARRAY['SUCCEEDED'::text, 'EXPIRED'::text]))))),
    CONSTRAINT ops_export_job_lifecycle_binding CHECK (
CASE status
    WHEN 'PENDING'::text THEN ((prepared_at IS NULL) AND (completed_at IS NULL) AND (lease_owner IS NULL) AND (lease_expires_at IS NULL) AND (error_code IS NULL) AND (error_message IS NULL))
    WHEN 'RUNNING'::text THEN ((started_at IS NOT NULL) AND (completed_at IS NULL) AND (lease_owner IS NOT NULL) AND (lease_expires_at IS NOT NULL) AND (error_code IS NULL) AND (error_message IS NULL))
    WHEN 'SUCCEEDED'::text THEN ((prepared_at IS NOT NULL) AND (started_at IS NOT NULL) AND (completed_at IS NOT NULL) AND (lease_owner IS NULL) AND (lease_expires_at IS NULL) AND (error_code IS NULL) AND (error_message IS NULL))
    WHEN 'FAILED'::text THEN ((started_at IS NOT NULL) AND (completed_at IS NOT NULL) AND (lease_owner IS NULL) AND (lease_expires_at IS NULL) AND (error_code IS NOT NULL) AND (error_message IS NOT NULL))
    WHEN 'EXPIRED'::text THEN ((completed_at IS NOT NULL) AND (lease_owner IS NULL) AND (lease_expires_at IS NULL) AND (error_code IS NULL) AND (error_message IS NULL))
    WHEN 'CANCELLED'::text THEN ((prepared_at IS NULL) AND (lease_owner IS NULL) AND (lease_expires_at IS NULL) AND (error_code IS NULL) AND (error_message IS NULL))
    ELSE false
END),
    CONSTRAINT ops_export_job_prepared_binding CHECK (((((prepared_at IS NULL) AND (read_model_revision IS NULL) AND (exact_count IS NULL) AND (manifest_sha256 IS NULL) AND (entry_count IS NULL) AND (total_uncompressed_bytes IS NULL) AND (prepared_staging_path IS NULL) AND (file_path IS NULL) AND (file_hash IS NULL) AND (file_size = 0)) OR ((prepared_at IS NOT NULL) AND (prepared_staging_path IS NOT NULL) AND (file_path IS NOT NULL) AND (file_hash IS NOT NULL) AND (file_hash ~ '^[0-9a-f]{64}$'::text) AND (file_size >= 0) AND (((scope_kind = 'COLLECTION'::text) AND (read_model_revision IS NOT NULL) AND (read_model_revision ~ '^[0-9a-f]{64}$'::text) AND (exact_count IS NOT NULL) AND ((exact_count >= 0) AND (exact_count <= 10000)) AND (manifest_sha256 IS NULL) AND (entry_count IS NULL) AND (total_uncompressed_bytes IS NULL)) OR ((scope_kind = 'WORKSPACE_ATTACHMENTS'::text) AND (read_model_revision IS NULL) AND (exact_count IS NULL) AND (manifest_sha256 IS NOT NULL) AND (manifest_sha256 ~ '^[0-9a-f]{64}$'::text) AND (entry_count IS NOT NULL) AND ((entry_count >= 0) AND (entry_count <= 10000)) AND (total_uncompressed_bytes IS NOT NULL) AND ((total_uncompressed_bytes >= 0) AND (total_uncompressed_bytes <= 1073741824)))))) IS TRUE)),
    CONSTRAINT ops_export_job_prepared_path_binding CHECK ((((prepared_at IS NULL) OR ((kind = 'MARKDOWN'::text) AND (file_path = (('.knowledge/exports/'::text || (id)::text) || '.md'::text)) AND (prepared_staging_path ~ (('^\.knowledge/exports/\.staging/'::text || (id)::text) || '-[0-9a-f]{32}\.md\.stage$'::text))) OR ((kind = 'METADATA_JSON'::text) AND (file_path = (('.knowledge/exports/'::text || (id)::text) || '.json'::text)) AND (prepared_staging_path ~ (('^\.knowledge/exports/\.staging/'::text || (id)::text) || '-[0-9a-f]{32}\.json\.stage$'::text))) OR ((kind = 'ATTACHMENTS_ZIP'::text) AND (file_path = (('.knowledge/exports/'::text || (id)::text) || '.zip'::text)) AND (prepared_staging_path ~ (('^\.knowledge/exports/\.staging/'::text || (id)::text) || '-[0-9a-f]{32}\.zip\.stage$'::text)))) IS TRUE)),
    CONSTRAINT ops_export_job_redaction_policy CHECK ((redaction_policy = ANY (ARRAY['MASKED'::text, 'FULL'::text, 'RAW_USER_OWNED'::text]))),
    CONSTRAINT ops_export_job_request_hash CHECK ((request_hash ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT ops_export_job_request_ttl CHECK ((((request_ttl_seconds >= 1) AND (request_ttl_seconds <= 604800)) AND (expires_at = (created_at + make_interval(secs => (request_ttl_seconds)::double precision))))),
    CONSTRAINT ops_export_job_scope_binding CHECK (((((scope_kind = 'COLLECTION'::text) AND (kind = ANY (ARRAY['MARKDOWN'::text, 'METADATA_JSON'::text])) AND (schema_version = 'export/v1'::text) AND (collection_id IS NOT NULL) AND (collection_version IS NOT NULL) AND (collection_version > 0) AND (query_hash IS NOT NULL) AND (query_hash ~ '^[0-9a-f]{64}$'::text) AND (attachment_root_contract_version IS NULL) AND (jsonb_array_length(fields) > 0)) OR ((scope_kind = 'WORKSPACE_ATTACHMENTS'::text) AND (kind = 'ATTACHMENTS_ZIP'::text) AND (schema_version = 'attachment-export/v1'::text) AND (collection_id IS NULL) AND (collection_version IS NULL) AND (query_hash IS NULL) AND (attachment_root_contract_version IS NOT NULL) AND (attachment_root_contract_version = 'workspace-attachments/v1'::text) AND (fields = '[]'::jsonb))) IS TRUE)),
    CONSTRAINT ops_export_job_sensitive_policy CHECK ((((scope_kind = 'COLLECTION'::text) AND ((redaction_policy = 'FULL'::text) = include_sensitive)) OR ((scope_kind = 'WORKSPACE_ATTACHMENTS'::text) AND (redaction_policy = 'RAW_USER_OWNED'::text) AND (NOT include_sensitive)))),
    CONSTRAINT ops_export_job_supported_kind CHECK ((kind = ANY (ARRAY['MARKDOWN'::text, 'METADATA_JSON'::text, 'ATTACHMENTS_ZIP'::text]))),
    CONSTRAINT ops_export_job_text_bounds CHECK (((btrim(idempotency_key) <> ''::text) AND (octet_length(idempotency_key) <= 128) AND (btrim(permission_scope) <> ''::text) AND (octet_length(permission_scope) <= 128) AND (btrim(requested_by) <> ''::text) AND (octet_length(requested_by) <= 256) AND ((attachment_root_contract_version IS NULL) OR (octet_length(attachment_root_contract_version) <= 64)) AND ((error_code IS NULL) OR ((btrim(error_code) <> ''::text) AND (octet_length(error_code) <= 128))) AND ((error_message IS NULL) OR ((btrim(error_message) <> ''::text) AND (octet_length(error_message) <= 512))) AND ((lease_owner IS NULL) OR ((btrim(lease_owner) <> ''::text) AND (octet_length(lease_owner) <= 128))) AND ((cleanup_error IS NULL) OR ((btrim(cleanup_error) <> ''::text) AND (octet_length(cleanup_error) <= 128))))),
    CONSTRAINT ops_export_job_time_order CHECK (((updated_at >= created_at) AND (expires_at > created_at) AND ((started_at IS NULL) OR ((started_at >= created_at) AND (started_at <= updated_at))) AND ((prepared_at IS NULL) OR ((prepared_at >= created_at) AND (prepared_at <= updated_at))) AND ((completed_at IS NULL) OR ((completed_at >= created_at) AND (completed_at <= updated_at))) AND ((last_downloaded_at IS NULL) OR ((last_downloaded_at >= created_at) AND (last_downloaded_at <= updated_at))) AND ((lease_expires_at IS NULL) OR (lease_expires_at > updated_at)) AND ((cleanup_updated_at IS NULL) OR ((cleanup_updated_at >= created_at) AND (cleanup_updated_at <= updated_at))) AND ((file_deleted_at IS NULL) OR ((file_deleted_at >= created_at) AND (file_deleted_at <= updated_at))))),
    CONSTRAINT ops_export_job_version CHECK ((version > 0))
);


