    CONSTRAINT git_sync_attempt_shape CHECK ((((status = 'RUNNING'::text) AND (completed_at IS NULL) AND (error_code = ''::text) AND (NOT retryable) AND (lease_owner IS NOT NULL) AND (lease_expires_at IS NOT NULL)) OR ((status = 'SUCCEEDED'::text) AND (completed_at IS NOT NULL) AND (error_code = ''::text) AND (NOT retryable) AND (lease_owner IS NULL) AND (lease_expires_at IS NULL)) OR ((status = 'FAILED'::text) AND (completed_at IS NOT NULL) AND (error_code <> ''::text) AND (lease_owner IS NULL) AND (lease_expires_at IS NULL)))),
    CONSTRAINT git_sync_attempt_status_check CHECK ((status = ANY (ARRAY['RUNNING'::text, 'SUCCEEDED'::text, 'FAILED'::text]))),
    CONSTRAINT git_sync_attempt_version_check CHECK ((version > 0))
);


