    trigger text NOT NULL,
    retry_of_run_id uuid,
    idempotency_key text NOT NULL,
    request_hash text NOT NULL,
    status text NOT NULL,
    direction text NOT NULL,
    failure_class text NOT NULL,
    error_code text DEFAULT ''::text NOT NULL,
    retryable boolean DEFAULT false NOT NULL,
    expected_head_oid text,
    expected_remote_oid text,
    verified_head_oid text,
    verified_remote_oid text,
    changed_files jsonb DEFAULT '[]'::jsonb NOT NULL,
    index_status text NOT NULL,
    index_error_code text DEFAULT ''::text NOT NULL,
    index_retryable boolean DEFAULT false NOT NULL,
    index_version_id uuid,
    attempt_count integer DEFAULT 0 NOT NULL,
    version bigint NOT NULL,
    created_at timestamp with time zone NOT NULL,
    updated_at timestamp with time zone NOT NULL,
    completed_at timestamp with time zone,
    CONSTRAINT git_sync_run_attempt_count_check CHECK (((attempt_count >= 0) AND (attempt_count <= 1000))),
    CONSTRAINT git_sync_run_branch_check CHECK (((branch = btrim(branch)) AND (branch <> ''::text) AND (octet_length(branch) <= 255) AND (branch !~ '[\x00-\x20\x7f]'::text))),
    CONSTRAINT git_sync_run_changed_files_check CHECK (ops.valid_git_sync_changed_files(changed_files)),
    CONSTRAINT git_sync_run_config_revision_check CHECK ((config_revision > 0)),
    CONSTRAINT git_sync_run_direction_check CHECK ((direction = ANY (ARRAY['UNKNOWN'::text, 'NONE'::text, 'PULL'::text, 'PUSH'::text]))),
    CONSTRAINT git_sync_run_error_code_check CHECK (((octet_length(error_code) <= 128) AND (error_code !~ '[\r\n]'::text))),
    CONSTRAINT git_sync_run_expected_head_oid_check CHECK (((expected_head_oid IS NULL) OR (expected_head_oid ~ '^([0-9a-f]{40}|[0-9a-f]{64})$'::text))),
    CONSTRAINT git_sync_run_expected_remote_oid_check CHECK (((expected_remote_oid IS NULL) OR (expected_remote_oid ~ '^([0-9a-f]{40}|[0-9a-f]{64})$'::text))),
    CONSTRAINT git_sync_run_failure_class_check CHECK ((failure_class = ANY (ARRAY['NONE'::text, 'DIRTY'::text, 'DETACHED'::text, 'DIVERGED'::text, 'AUTHENTICATION'::text, 'OFFLINE'::text, 'REF_DRIFT'::text, 'NON_FAST_FORWARD'::text, 'STALE_CONFIG'::text, 'RESULT_UNKNOWN'::text, 'DEPENDENCY'::text, 'INTERNAL'::text]))),
    CONSTRAINT git_sync_run_idempotency_key_check CHECK (((idempotency_key = btrim(idempotency_key)) AND (idempotency_key <> ''::text) AND (octet_length(idempotency_key) <= 128) AND (idempotency_key !~ '[\r\n]'::text))),
    CONSTRAINT git_sync_run_index_direction CHECK ((((status = 'SUCCEEDED'::text) AND (direction = 'PULL'::text) AND (index_status = ANY (ARRAY['PENDING'::text, 'RUNNING'::text, 'SUCCEEDED'::text, 'FAILED'::text]))) OR ((NOT ((status = 'SUCCEEDED'::text) AND (direction = 'PULL'::text))) AND (index_status = 'NOT_REQUIRED'::text)))),
    CONSTRAINT git_sync_run_index_error_code_check CHECK (((octet_length(index_error_code) <= 128) AND (index_error_code !~ '[\r\n]'::text))),
    CONSTRAINT git_sync_run_index_shape CHECK ((((index_status = ANY (ARRAY['NOT_REQUIRED'::text, 'PENDING'::text, 'RUNNING'::text])) AND (index_error_code = ''::text) AND (NOT index_retryable) AND (index_version_id IS NULL)) OR ((index_status = 'SUCCEEDED'::text) AND (index_error_code = ''::text) AND (NOT index_retryable)) OR ((index_status = 'FAILED'::text) AND (index_error_code <> ''::text) AND (index_version_id IS NULL)))),
    CONSTRAINT git_sync_run_index_status_check CHECK ((index_status = ANY (ARRAY['NOT_REQUIRED'::text, 'PENDING'::text, 'RUNNING'::text, 'SUCCEEDED'::text, 'FAILED'::text]))),
    CONSTRAINT git_sync_run_ref_lengths CHECK ((((expected_head_oid IS NULL) OR (expected_remote_oid IS NULL) OR (length(expected_head_oid) = length(expected_remote_oid))) AND ((verified_head_oid IS NULL) OR (verified_remote_oid IS NULL) OR (length(verified_head_oid) = length(verified_remote_oid))))),
    CONSTRAINT git_sync_run_remote_url_check CHECK (((remote_url ~ '^https://[^/?#@]+[^?#]*$'::text) AND (POSITION(('@'::text) IN (remote_url)) = 0) AND (remote_url !~ '[\x00-\x20\x7f]'::text) AND (octet_length(remote_url) <= 2048))),
    CONSTRAINT git_sync_run_request_hash_check CHECK ((request_hash ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT git_sync_run_retry_shape CHECK ((((trigger = 'RETRY'::text) AND (retry_of_run_id IS NOT NULL)) OR ((trigger <> 'RETRY'::text) AND (retry_of_run_id IS NULL)))),
    CONSTRAINT git_sync_run_status_check CHECK ((status = ANY (ARRAY['PENDING'::text, 'FETCHING'::text, 'COMPARING'::text, 'FAST_FORWARDING'::text, 'PUSHING'::text, 'VERIFYING'::text, 'SUCCEEDED'::text, 'CONFLICT'::text, 'FAILED'::text, 'STALE'::text, 'MANUAL_RECOVERY_REQUIRED'::text]))),
    CONSTRAINT git_sync_run_terminal_shape CHECK ((((status = ANY (ARRAY['PENDING'::text, 'FETCHING'::text, 'COMPARING'::text, 'FAST_FORWARDING'::text, 'PUSHING'::text, 'VERIFYING'::text])) AND (completed_at IS NULL) AND (failure_class = 'NONE'::text) AND (error_code = ''::text) AND (NOT retryable)) OR ((status = 'SUCCEEDED'::text) AND (completed_at IS NOT NULL) AND (failure_class = 'NONE'::text) AND (error_code = ''::text) AND (NOT retryable) AND (verified_head_oid IS NOT NULL) AND (verified_remote_oid IS NOT NULL) AND (verified_head_oid = verified_remote_oid)) OR ((status = ANY (ARRAY['CONFLICT'::text, 'FAILED'::text, 'STALE'::text, 'MANUAL_RECOVERY_REQUIRED'::text])) AND (completed_at IS NOT NULL) AND (failure_class <> 'NONE'::text) AND (error_code <> ''::text)))),
    CONSTRAINT git_sync_run_timestamps CHECK (((updated_at >= created_at) AND ((completed_at IS NULL) OR (completed_at >= created_at)))),
    CONSTRAINT git_sync_run_trigger_check CHECK ((trigger = ANY (ARRAY['MANUAL'::text, 'AUTOMATIC'::text, 'RETRY'::text]))),
    CONSTRAINT git_sync_run_verified_head_oid_check CHECK (((verified_head_oid IS NULL) OR (verified_head_oid ~ '^([0-9a-f]{40}|[0-9a-f]{64})$'::text))),
    CONSTRAINT git_sync_run_verified_remote_oid_check CHECK (((verified_remote_oid IS NULL) OR (verified_remote_oid ~ '^([0-9a-f]{40}|[0-9a-f]{64})$'::text))),
    CONSTRAINT git_sync_run_version_check CHECK ((version > 0))
);


