    CONSTRAINT health_affected_change_outbox_version_check CHECK ((version > 0)),
    CONSTRAINT ops_health_affected_change_lifecycle CHECK ((((published_at IS NULL) AND (poisoned_at IS NULL) AND (NOT manual_recovery_required) AND (bound_scan_id IS NULL) AND (bound_workflow_run_id IS NULL)) OR ((published_at IS NOT NULL) AND (poisoned_at IS NULL) AND (NOT manual_recovery_required) AND (bound_scan_id IS NOT NULL) AND (bound_workflow_run_id IS NOT NULL) AND (last_error_code IS NULL)) OR ((published_at IS NULL) AND (poisoned_at IS NOT NULL) AND manual_recovery_required AND (bound_scan_id IS NULL) AND (bound_workflow_run_id IS NULL) AND (last_error_code IS NOT NULL)))),
    CONSTRAINT ops_health_affected_change_source_binding CHECK ((((source_kind = 'KNOWLEDGE_COMMAND_RECEIPT'::text) AND (event_type = 'health.affected.knowledge_changed'::text) AND (aggregate_type = ANY (ARRAY['TOPIC'::text, 'CLAIM'::text, 'RELATION'::text, 'CONFLICT'::text])) AND (aggregate_sub_id IS NULL) AND (source_hash IS NOT NULL) AND (change_code IS NULL) AND (((change_status = 'topic.create'::text) AND (aggregate_type = 'TOPIC'::text)) OR ((change_status = ANY (ARRAY['claim.suggest'::text, 'claim.confirm'::text, 'claim.transition'::text])) AND (aggregate_type = 'CLAIM'::text)) OR ((change_status = ANY (ARRAY['relation.suggest'::text, 'relation.confirm'::text, 'relation.transition'::text])) AND (aggregate_type = 'RELATION'::text)) OR ((change_status = ANY (ARRAY['conflict.open'::text, 'conflict.transition'::text])) AND (aggregate_type = 'CONFLICT'::text)))) OR ((source_kind = 'INDEX_VERSION'::text) AND (event_type = 'health.affected.index_failed'::text) AND (aggregate_type = 'INDEX_VERSION'::text) AND (aggregate_sub_id IS NULL) AND (source_key = (aggregate_id)::text) AND (source_hash IS NULL) AND (change_status = 'failed'::text) AND (change_code IS NOT NULL)) OR ((source_kind = 'CHUNK_PROJECTION'::text) AND (event_type = ANY (ARRAY['health.affected.vector_degraded'::text, 'health.affected.lexical_degraded'::text])) AND (aggregate_type = 'CHUNK_PROJECTION'::text) AND (aggregate_sub_id IS NOT NULL) AND (source_key = (((aggregate_id)::text || ':'::text) || (aggregate_sub_id)::text)) AND (source_hash IS NULL) AND (((event_type = 'health.affected.vector_degraded'::text) AND (change_status = ANY (ARRAY['failed'::text, 'skipped_oversized'::text]))) OR ((event_type = 'health.affected.lexical_degraded'::text) AND (change_status = 'failed'::text))) AND (change_code IS NOT NULL)))),
    CONSTRAINT ops_health_affected_change_time_order CHECK (((available_at >= occurred_at) AND (updated_at >= created_at) AND ((published_at IS NULL) OR (published_at >= occurred_at)) AND ((poisoned_at IS NULL) OR (poisoned_at >= occurred_at))))
);


