    CONSTRAINT health_issue_fingerprint_schema_version_check CHECK (((btrim(fingerprint_schema_version) <> ''::text) AND (octet_length(fingerprint_schema_version) <= 128))),
    CONSTRAINT health_issue_identity_hash_check CHECK ((identity_hash ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT health_issue_severity_check CHECK ((severity = ANY (ARRAY['CRITICAL'::text, 'HIGH'::text, 'MEDIUM'::text, 'LOW'::text]))),
