    CONSTRAINT health_issue_version_check CHECK ((version > 0)),
    CONSTRAINT ops_health_issue_resolution_binding CHECK ((((status = 'RESOLVED'::text) AND (resolved_at IS NOT NULL)) OR ((status <> 'RESOLVED'::text) AND (resolved_at IS NULL)))),
    CONSTRAINT ops_health_issue_status_binding CHECK ((((status = ANY (ARRAY['IGNORED'::text, 'FALSE_POSITIVE'::text])) AND (status_reason IS NOT NULL) AND (btrim(status_reason) <> ''::text) AND (octet_length(status_reason) <= 4096) AND (deferred_until IS NULL) AND (repair_proposal_id IS NULL) AND (repair_option_code IS NULL) AND (repair_binding_fingerprint IS NULL) AND (repair_binding_object_versions IS NULL) AND (repair_proposal_created_at IS NULL)) OR ((status = 'DEFERRED'::text) AND (status_reason IS NOT NULL) AND (btrim(status_reason) <> ''::text) AND (octet_length(status_reason) <= 4096) AND (deferred_until IS NOT NULL) AND (repair_proposal_id IS NULL) AND (repair_option_code IS NULL) AND (repair_binding_fingerprint IS NULL) AND (repair_binding_object_versions IS NULL) AND (repair_proposal_created_at IS NULL)) OR ((status = 'PROPOSAL_CREATED'::text) AND (status_reason IS NULL) AND (deferred_until IS NULL) AND (repair_proposal_id IS NOT NULL) AND (repair_option_code IS NOT NULL) AND (btrim(repair_option_code) <> ''::text) AND (octet_length(repair_option_code) <= 128) AND (repair_binding_fingerprint IS NOT NULL) AND (repair_binding_fingerprint ~ '^[0-9a-f]{64}$'::text) AND (repair_binding_object_versions IS NOT NULL) AND (jsonb_typeof(repair_binding_object_versions) = 'array'::text) AND (jsonb_array_length(repair_binding_object_versions) > 0) AND (octet_length((repair_binding_object_versions)::text) <= 16384) AND (repair_proposal_created_at IS NOT NULL)) OR ((status = ANY (ARRAY['OPEN'::text, 'ACKNOWLEDGED'::text, 'RESOLVED'::text, 'REOPENED'::text])) AND (status_reason IS NULL) AND (deferred_until IS NULL) AND (repair_proposal_id IS NULL) AND (repair_option_code IS NULL) AND (repair_binding_fingerprint IS NULL) AND (repair_binding_object_versions IS NULL) AND (repair_proposal_created_at IS NULL)))),
    CONSTRAINT ops_health_issue_time_order CHECK (((last_detected_at >= first_detected_at) AND (last_verified_at >= first_detected_at) AND (updated_at >= created_at) AND ((resolved_at IS NULL) OR (resolved_at >= first_detected_at)))),
    CONSTRAINT ops_health_issue_type_check CHECK ((type = ANY (ARRAY['ORPHAN'::text, 'DUPLICATE'::text, 'CONFLICT'::text, 'STALE'::text, 'MISSING_SOURCE'::text, 'LOW_CONFIDENCE'::text, 'BROKEN_REFERENCE'::text, 'INDEX_ERROR'::text, 'SUPERSEDED_USAGE'::text, 'REVIEW_INVALIDATED'::text])))
);


