    CONSTRAINT health_scan_last_error_check CHECK (((last_error IS NULL) OR ((jsonb_typeof(last_error) = 'object'::text) AND (octet_length((last_error)::text) <= 4096)))),
    CONSTRAINT health_scan_max_items_check CHECK (((max_items >= 1) AND (max_items <= 50000))),
    CONSTRAINT health_scan_processed_count_check CHECK ((processed_count >= 0)),
    CONSTRAINT health_scan_reopened_count_check CHECK ((reopened_count >= 0)),
    CONSTRAINT health_scan_request_hash_check CHECK ((request_hash ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT health_scan_resolved_count_check CHECK ((resolved_count >= 0)),
    CONSTRAINT health_scan_scope_exact_count_check CHECK (((scope_exact_count IS NULL) OR (scope_exact_count >= 0))),
    CONSTRAINT health_scan_scope_hash_check CHECK (((scope_hash IS NULL) OR (scope_hash ~ '^[0-9a-f]{64}$'::text))),
    CONSTRAINT health_scan_scope_read_model_revision_check CHECK (((scope_read_model_revision IS NULL) OR (scope_read_model_revision ~ '^[0-9a-f]{64}$'::text))),
    CONSTRAINT health_scan_scope_schema_version_check CHECK (((btrim(scope_schema_version) <> ''::text) AND (octet_length(scope_schema_version) <= 128))),
    CONSTRAINT health_scan_scope_type_check CHECK ((scope_type = ANY (ARRAY['WORKSPACE'::text, 'TOPIC'::text, 'SMART_COLLECTION'::text]))),
    CONSTRAINT health_scan_scope_version_check CHECK ((scope_version > 0)),
    CONSTRAINT health_scan_status_check CHECK ((status = ANY (ARRAY['PENDING'::text, 'RUNNING'::text, 'SUCCEEDED'::text, 'PARTIAL'::text, 'FAILED'::text, 'CANCELLED'::text]))),
    CONSTRAINT health_scan_unchanged_count_check CHECK ((unchanged_count >= 0)),
    CONSTRAINT health_scan_version_check CHECK ((version > 0)),
    CONSTRAINT ops_health_scan_completion CHECK ((((status = ANY (ARRAY['SUCCEEDED'::text, 'PARTIAL'::text, 'FAILED'::text, 'CANCELLED'::text])) AND (completed_at IS NOT NULL)) OR ((status = ANY (ARRAY['PENDING'::text, 'RUNNING'::text])) AND (completed_at IS NULL)))),
    CONSTRAINT ops_health_scan_error_binding CHECK ((((status = 'FAILED'::text) AND (last_error IS NOT NULL)) OR (status = 'PARTIAL'::text) OR ((status <> ALL (ARRAY['FAILED'::text, 'PARTIAL'::text])) AND (last_error IS NULL)))),
    CONSTRAINT ops_health_scan_scope_binding CHECK ((((scope_type = 'SMART_COLLECTION'::text) AND (scope_hash IS NOT NULL) AND (scope_hash ~ '^[0-9a-f]{64}$'::text) AND (scope_read_model_revision IS NOT NULL) AND (scope_read_model_revision ~ '^[0-9a-f]{64}$'::text) AND (scope_exact_count IS NOT NULL) AND (scope_exact_count >= 0)) OR ((scope_type <> 'SMART_COLLECTION'::text) AND (scope_hash IS NULL) AND (scope_read_model_revision IS NULL) AND (scope_exact_count IS NULL)))),
    CONSTRAINT ops_health_scan_time_order CHECK (((updated_at >= created_at) AND ((completed_at IS NULL) OR (completed_at >= created_at))))
);


