    CONSTRAINT ops_health_scan_detector_failure_binding CHECK ((((status = 'FAILED'::text) AND (failure_summary IS NOT NULL) AND (unavailable_reason IS NULL)) OR ((status = 'PARTIAL'::text) AND (failure_summary IS NOT NULL) AND (unavailable_reason IS NULL)) OR ((status = 'UNAVAILABLE'::text) AND (failure_summary IS NULL) AND (unavailable_reason IS NOT NULL)) OR ((status <> ALL (ARRAY['FAILED'::text, 'PARTIAL'::text, 'UNAVAILABLE'::text])) AND (failure_summary IS NULL) AND (unavailable_reason IS NULL))))
);


