    pending_due_at timestamp with time zone,
    dispatch_lease_until timestamp with time zone,
    CONSTRAINT health_schedule_cadence_check CHECK ((cadence = ANY (ARRAY['DISABLED'::text, 'DAILY'::text, 'WEEKLY'::text, 'CRON'::text]))),
    CONSTRAINT health_schedule_max_items_check CHECK (((max_items >= 1) AND (max_items <= 50000))),
    CONSTRAINT health_schedule_scope_hash_check CHECK (((scope_hash IS NULL) OR (scope_hash ~ '^[0-9a-f]{64}$'::text))),
    CONSTRAINT health_schedule_scope_schema_version_check CHECK (((btrim(scope_schema_version) <> ''::text) AND (octet_length(scope_schema_version) <= 128))),
    CONSTRAINT health_schedule_scope_type_check CHECK ((scope_type = ANY (ARRAY['WORKSPACE'::text, 'TOPIC'::text, 'SMART_COLLECTION'::text]))),
    CONSTRAINT health_schedule_scope_version_check CHECK ((scope_version > 0)),
    CONSTRAINT health_schedule_timezone_check CHECK (((btrim(timezone) <> ''::text) AND (octet_length(timezone) <= 128))),
    CONSTRAINT health_schedule_version_check CHECK ((version > 0)),
    CONSTRAINT ops_health_schedule_cadence_binding CHECK ((((cadence = 'DISABLED'::text) AND (cron_expression IS NULL) AND (next_run_at IS NULL)) OR ((cadence = ANY (ARRAY['DAILY'::text, 'WEEKLY'::text])) AND (cron_expression IS NULL) AND (next_run_at IS NOT NULL)) OR ((cadence = 'CRON'::text) AND (cron_expression IS NOT NULL) AND (btrim(cron_expression) <> ''::text) AND (octet_length(cron_expression) <= 128) AND (next_run_at IS NOT NULL)))),
    CONSTRAINT ops_health_schedule_dispatch_binding CHECK ((((pending_due_at IS NULL) AND (dispatch_lease_until IS NULL)) OR ((cadence <> 'DISABLED'::text) AND (pending_due_at IS NOT NULL) AND (dispatch_lease_until IS NOT NULL) AND (dispatch_lease_until >= pending_due_at)))),
    CONSTRAINT ops_health_schedule_scope_binding CHECK ((((scope_type = 'SMART_COLLECTION'::text) AND (scope_hash IS NOT NULL)) OR ((scope_type <> 'SMART_COLLECTION'::text) AND (scope_hash IS NULL)))),
    CONSTRAINT ops_health_schedule_time_order CHECK (((updated_at >= created_at) AND ((next_run_at IS NULL) OR (last_run_at IS NULL) OR (next_run_at >= last_run_at))))
);


