    CONSTRAINT ops_model_settings_chat_target CHECK (((((chat_provider = 'disabled'::text) AND (chat_base_url = ''::text) AND (chat_model = ''::text) AND (chat_model_version = ''::text)) OR ((chat_provider = ANY (ARRAY['openai-compatible'::text, 'ollama'::text])) AND (btrim(chat_base_url) <> ''::text) AND (btrim(chat_model) <> ''::text) AND (btrim(chat_model_version) <> ''::text))) IS TRUE)),
    CONSTRAINT ops_model_settings_disabled_secret CHECK ((((chat_provider <> ALL (ARRAY['disabled'::text, 'ollama'::text])) OR (chat_secret_key_id IS NULL)) AND ((embedding_provider <> ALL (ARRAY['disabled'::text, 'ollama'::text])) OR (embedding_secret_key_id IS NULL)))),
    CONSTRAINT ops_model_settings_embedding_contract CHECK (((embedding_normalization = ANY (ARRAY['none'::text, 'l2'::text])) AND (embedding_distance_metric = ANY (ARRAY['cosine'::text, 'inner_product'::text, 'euclidean'::text])))),
