    CONSTRAINT ops_model_settings_embedding_secret_envelope CHECK (((((embedding_secret_key_id IS NULL) AND (embedding_secret_nonce IS NULL) AND (embedding_secret_ciphertext IS NULL)) OR ((embedding_secret_key_id ~ '^[0-9a-f]{64}$'::text) AND (octet_length(embedding_secret_nonce) = 12) AND ((octet_length(embedding_secret_ciphertext) >= 17) AND (octet_length(embedding_secret_ciphertext) <= 20480)))) IS TRUE)),
    CONSTRAINT ops_model_settings_embedding_target CHECK (((((embedding_provider = 'disabled'::text) AND (embedding_base_url = ''::text) AND (embedding_model = ''::text) AND (embedding_dimensions = 0)) OR ((embedding_provider = ANY (ARRAY['openai-compatible'::text, 'ollama'::text])) AND (btrim(embedding_base_url) <> ''::text) AND (btrim(embedding_model) <> ''::text) AND ((embedding_dimensions >= 1) AND (embedding_dimensions <= 16000)))) IS TRUE)),
    CONSTRAINT ops_model_settings_limits CHECK ((((chat_timeout_microseconds >= 1) AND (chat_timeout_microseconds <= 300000000)) AND ((chat_max_request_bytes >= 1) AND (chat_max_request_bytes <= 16777216)) AND ((chat_max_response_bytes >= 1) AND (chat_max_response_bytes <= 16777216)) AND ((embedding_max_batch_size >= 1) AND (embedding_max_batch_size <= 1000)) AND ((embedding_max_input_bytes >= 1) AND (embedding_max_input_bytes <= 10485760)) AND ((embedding_max_batch_input_bytes >= embedding_max_input_bytes) AND (embedding_max_batch_input_bytes <= 67108864)) AND ((embedding_timeout_microseconds >= 1) AND (embedding_timeout_microseconds <= 300000000)) AND ((embedding_max_response_bytes >= 1) AND (embedding_max_response_bytes <= 134217728)))),
    CONSTRAINT ops_model_settings_revision_positive CHECK ((revision > 0)),
    CONSTRAINT ops_model_settings_text_bounds CHECK (((octet_length(chat_base_url) <= 2048) AND (octet_length(chat_model) <= 128) AND (octet_length(chat_model_version) <= 64) AND (btrim(chat_adapter_version) <> ''::text) AND (octet_length(chat_adapter_version) <= 64) AND (octet_length(embedding_base_url) <= 2048) AND (octet_length(embedding_model) <= 128) AND (btrim(created_by) <> ''::text) AND (octet_length(created_by) <= 256) AND (chat_base_url = btrim(chat_base_url)) AND (chat_model = btrim(chat_model)) AND (chat_model_version = btrim(chat_model_version)) AND (chat_adapter_version = btrim(chat_adapter_version)) AND (embedding_base_url = btrim(embedding_base_url)) AND (embedding_model = btrim(embedding_model)) AND (created_by = btrim(created_by))))
);


--
-- Name: managed_ollama_revision_requirements; Type: VIEW; Schema: ops; Owner: -
--

CREATE VIEW ops.managed_ollama_revision_requirements WITH (security_barrier='true') AS
 SELECT revision,
        CASE
            WHEN ((chat_provider = 'ollama'::text) OR ((chat_provider = 'openai-compatible'::text) AND (chat_base_url = 'http://127.0.0.1:11434'::text))) THEN chat_model
            ELSE NULL::text
        END AS local_chat_model,
        CASE
            WHEN (embedding_provider = 'ollama'::text) THEN embedding_model
            ELSE NULL::text
        END AS local_embedding_model
   FROM ops.model_settings_revisions;


