    completed_at timestamp with time zone,
    CONSTRAINT workspace_switch_binding CHECK (((target_root_fingerprint ~ '^[0-9a-f]{64}$'::text) AND (target_binding_version > 0) AND (grant_generation > 0) AND (recovery_generation > grant_generation) AND (expected_state_version > 0))),
    CONSTRAINT workspace_switch_phase CHECK ((phase = ANY (ARRAY['validating'::text, 'quiescing'::text, 'revoking'::text, 'applying_grant'::text, 'preparing'::text, 'verifying'::text, 'committing'::text, 'activating'::text, 'rolling_back'::text, 'recovering'::text]))),
    CONSTRAINT workspace_switch_request CHECK ((((octet_length(idempotency_key) >= 1) AND (octet_length(idempotency_key) <= 256)) AND (request_hash ~ '^[0-9a-f]{64}$'::text))),
    CONSTRAINT workspace_switch_result CHECK (((result IS NULL) OR (result = ANY (ARRAY['succeeded'::text, 'rejected'::text, 'cancelled'::text, 'rolled_back'::text, 'failed'::text])))),
    CONSTRAINT workspace_switch_terminal_shape CHECK (((((result IS NULL) AND (lease_owner_id IS NOT NULL) AND (lease_expires_at IS NOT NULL) AND (completed_at IS NULL) AND (error_code IS NULL)) OR ((result = ANY (ARRAY['succeeded'::text, 'cancelled'::text])) AND (lease_owner_id IS NULL) AND (lease_expires_at IS NULL) AND (completed_at IS NOT NULL) AND (error_code IS NULL)) OR ((result = ANY (ARRAY['rejected'::text, 'rolled_back'::text, 'failed'::text])) AND (lease_owner_id IS NULL) AND (lease_expires_at IS NULL) AND (completed_at IS NOT NULL) AND (error_code ~ '^[A-Z0-9_]{1,128}$'::text))) IS TRUE)),
    CONSTRAINT workspace_switch_times CHECK (((heartbeat_at >= created_at) AND (deadline_at > created_at) AND (updated_at >= created_at) AND ((lease_expires_at IS NULL) OR (lease_expires_at > heartbeat_at)) AND ((completed_at IS NULL) OR (completed_at >= created_at)))),
    CONSTRAINT workspace_switch_version CHECK ((version > 0))
);


--
-- Name: command_receipt; Type: TABLE; Schema: organizing; Owner: -
--

CREATE TABLE organizing.command_receipt (
    workspace_id uuid NOT NULL,
    idempotency_key text NOT NULL,
    request_hash text NOT NULL,
    command_type text NOT NULL,
    aggregate_id uuid NOT NULL,
    expected_version bigint NOT NULL,
    draft_id uuid,
    result_draft_version bigint,
    snapshot_id uuid,
    outbox_id uuid,
    template_id uuid,
    result_template_version bigint,
    template_revision_id uuid,
    created_at timestamp with time zone NOT NULL,
    CONSTRAINT command_receipt_command_type_check CHECK ((command_type = ANY (ARRAY['CREATE_DRAFT'::text, 'UPDATE_DRAFT'::text, 'ADD_MATERIAL'::text, 'REMOVE_MATERIAL'::text, 'SET_MATERIAL_SELECTION'::text, 'REPLACE_SUGGESTIONS'::text, 'CONFIRM_DRAFT'::text, 'CREATE_TEMPLATE'::text, 'CLONE_TEMPLATE'::text, 'REVISE_TEMPLATE'::text]))),
    CONSTRAINT command_receipt_expected_version_check CHECK ((expected_version >= 0)),
    CONSTRAINT command_receipt_idempotency_key_check CHECK (((idempotency_key = btrim(idempotency_key)) AND (idempotency_key <> ''::text) AND (octet_length(idempotency_key) <= 128) AND (idempotency_key !~ '[\r\n]'::text))),
    CONSTRAINT command_receipt_request_hash_check CHECK ((request_hash ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT organizing_receipt_required_result CHECK ((((command_type = ANY (ARRAY['CREATE_DRAFT'::text, 'UPDATE_DRAFT'::text, 'ADD_MATERIAL'::text, 'REMOVE_MATERIAL'::text, 'SET_MATERIAL_SELECTION'::text, 'REPLACE_SUGGESTIONS'::text, 'CONFIRM_DRAFT'::text])) AND (draft_id IS NOT NULL) AND (result_draft_version IS NOT NULL)) OR ((command_type = ANY (ARRAY['CREATE_TEMPLATE'::text, 'CLONE_TEMPLATE'::text, 'REVISE_TEMPLATE'::text])) AND (template_id IS NOT NULL) AND (result_template_version IS NOT NULL) AND (template_revision_id IS NOT NULL)))),
    CONSTRAINT organizing_receipt_shape CHECK (
CASE command_type
    WHEN 'CREATE_DRAFT'::text THEN ((expected_version = 0) AND (aggregate_id = draft_id) AND (result_draft_version = 1) AND (snapshot_id IS NULL) AND (outbox_id IS NULL) AND (template_id IS NULL) AND (result_template_version IS NULL) AND (template_revision_id IS NULL))
    WHEN 'UPDATE_DRAFT'::text THEN ((expected_version > 0) AND (aggregate_id = draft_id) AND (result_draft_version = (expected_version + 1)) AND (snapshot_id IS NULL) AND (outbox_id IS NULL) AND (template_id IS NULL) AND (result_template_version IS NULL) AND (template_revision_id IS NULL))
    WHEN 'ADD_MATERIAL'::text THEN ((expected_version > 0) AND (aggregate_id = draft_id) AND (result_draft_version = (expected_version + 1)) AND (snapshot_id IS NULL) AND (outbox_id IS NULL) AND (template_id IS NULL) AND (result_template_version IS NULL) AND (template_revision_id IS NULL))
    WHEN 'REMOVE_MATERIAL'::text THEN ((expected_version > 0) AND (aggregate_id = draft_id) AND (result_draft_version = (expected_version + 1)) AND (snapshot_id IS NULL) AND (outbox_id IS NULL) AND (template_id IS NULL) AND (result_template_version IS NULL) AND (template_revision_id IS NULL))
    WHEN 'SET_MATERIAL_SELECTION'::text THEN ((expected_version > 0) AND (aggregate_id = draft_id) AND (result_draft_version = (expected_version + 1)) AND (snapshot_id IS NULL) AND (outbox_id IS NULL) AND (template_id IS NULL) AND (result_template_version IS NULL) AND (template_revision_id IS NULL))
    WHEN 'REPLACE_SUGGESTIONS'::text THEN ((expected_version > 0) AND (aggregate_id = draft_id) AND (result_draft_version = (expected_version + 1)) AND (snapshot_id IS NULL) AND (outbox_id IS NULL) AND (template_id IS NULL) AND (result_template_version IS NULL) AND (template_revision_id IS NULL))
    WHEN 'CONFIRM_DRAFT'::text THEN ((expected_version > 0) AND (aggregate_id = draft_id) AND (result_draft_version = (expected_version + 1)) AND (snapshot_id IS NOT NULL) AND (outbox_id IS NOT NULL) AND (template_id IS NULL) AND (result_template_version IS NULL) AND (template_revision_id IS NULL))
    WHEN 'CREATE_TEMPLATE'::text THEN ((expected_version = 0) AND (aggregate_id = template_id) AND (result_template_version = 1) AND (template_revision_id IS NOT NULL) AND (draft_id IS NULL) AND (result_draft_version IS NULL) AND (snapshot_id IS NULL) AND (outbox_id IS NULL))
    WHEN 'CLONE_TEMPLATE'::text THEN ((expected_version = 0) AND (aggregate_id = template_id) AND (result_template_version = 1) AND (template_revision_id IS NOT NULL) AND (draft_id IS NULL) AND (result_draft_version IS NULL) AND (snapshot_id IS NULL) AND (outbox_id IS NULL))
    WHEN 'REVISE_TEMPLATE'::text THEN ((expected_version > 0) AND (aggregate_id = template_id) AND (result_template_version = (expected_version + 1)) AND (template_revision_id IS NOT NULL) AND (draft_id IS NULL) AND (result_draft_version IS NULL) AND (snapshot_id IS NULL) AND (outbox_id IS NULL))
    ELSE false
END)
);


