    CONSTRAINT generation_error_code_check CHECK (((error_code IS NULL) OR ((error_code = btrim(error_code)) AND (error_code <> ''::text) AND (error_code ~ '^[A-Z0-9_]{1,128}$'::text)))),
    CONSTRAINT generation_generation_kind_check CHECK ((generation_kind = ANY (ARRAY['OUTLINE'::text, 'DOCUMENT'::text]))),
    CONSTRAINT generation_model_settings_revision_check CHECK (((model_settings_revision IS NULL) OR (model_settings_revision >= 0))),
