    CONSTRAINT generation_request_hash_check CHECK ((request_hash ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT generation_status_check CHECK ((status = ANY (ARRAY['RUNNING'::text, 'READY'::text, 'FAILED'::text, 'RECOVERY_REQUIRED'::text]))),
    CONSTRAINT generation_version_check CHECK ((version > 0)),
    CONSTRAINT organizing_generation_state_shape CHECK (
CASE status
    WHEN 'RUNNING'::text THEN ((completed_at IS NULL) AND (output_document IS NULL) AND (output_hash IS NULL) AND (error_code IS NULL) AND (retryable = false))
    WHEN 'READY'::text THEN ((model_run_id IS NOT NULL) AND (completed_at IS NOT NULL) AND (output_document IS NOT NULL) AND (octet_length(output_document) > 0) AND (octet_length(output_document) <= 524288) AND (output_hash IS NOT NULL) AND (error_code IS NULL) AND (retryable = false))
    WHEN 'FAILED'::text THEN ((model_run_id IS NOT NULL) AND (completed_at IS NOT NULL) AND (output_document IS NULL) AND (output_hash IS NULL) AND (error_code IS NOT NULL))
    WHEN 'RECOVERY_REQUIRED'::text THEN ((model_run_id IS NOT NULL) AND (completed_at IS NOT NULL) AND (output_document IS NULL) AND (output_hash IS NULL) AND (error_code IS NOT NULL) AND (retryable = false))
    ELSE false
END),
    CONSTRAINT organizing_generation_time_order CHECK (((updated_at >= created_at) AND ((completed_at IS NULL) OR (completed_at = updated_at))))
);


