--
-- Name: workflow_input_material; Type: TABLE; Schema: organizing; Owner: -
--

CREATE TABLE organizing.workflow_input_material (
    id uuid NOT NULL,
    workspace_id uuid NOT NULL,
    snapshot_id uuid NOT NULL,
    "position" integer NOT NULL,
    kind text NOT NULL,
    source_version_id uuid,
    document_id uuid,
    article_revision_id uuid,
    claim_id uuid,
    collection_id uuid,
    origin_collection_id uuid,
    profile_revision_id uuid,
    material_version bigint NOT NULL,
    content_hash text,
    query_hash text,
    read_model_revision text,
    evidence jsonb NOT NULL,
    identity_key text GENERATED ALWAYS AS (
CASE kind
    WHEN 'SOURCE_VERSION'::text THEN ((kind || ':'::text) || (source_version_id)::text)
    WHEN 'DOCUMENT_REVISION'::text THEN ((((kind || ':'::text) || (document_id)::text) || ':'::text) || (article_revision_id)::text)
    WHEN 'CLAIM'::text THEN ((kind || ':'::text) || (claim_id)::text)
    WHEN 'SMART_COLLECTION'::text THEN ((kind || ':'::text) || (collection_id)::text)
    ELSE NULL::text
END) STORED,
    created_at timestamp with time zone NOT NULL,
    CONSTRAINT organizing_snapshot_material_shape CHECK (organizing.valid_material_shape(kind, source_version_id, document_id, article_revision_id, claim_id, collection_id, origin_collection_id, profile_revision_id, material_version, content_hash, query_hash, read_model_revision, evidence, true)),
    CONSTRAINT workflow_input_material_material_version_check CHECK ((material_version >= 0)),
    CONSTRAINT workflow_input_material_position_check CHECK ((("position" >= 0) AND ("position" < 500)))
);


