    CONSTRAINT organizing_start_outbox_state_shape CHECK (((updated_at >= created_at) AND (((status = 'PENDING'::text) AND (run_binding_id IS NULL) AND (started_at IS NULL) AND (poisoned_at IS NULL)) OR ((status = 'STARTED'::text) AND (run_binding_id IS NOT NULL) AND (started_at IS NOT NULL) AND (poisoned_at IS NULL) AND (lease_owner IS NULL) AND (lease_until IS NULL)) OR ((status = 'POISONED'::text) AND (run_binding_id IS NULL) AND (started_at IS NULL) AND (poisoned_at IS NOT NULL) AND (last_error_code IS NOT NULL) AND (lease_owner IS NULL) AND (lease_until IS NULL))))),
    CONSTRAINT workflow_start_outbox_attempt_count_check CHECK (((attempt_count >= 0) AND (attempt_count <= 1000))),
    CONSTRAINT workflow_start_outbox_last_error_code_check CHECK (((last_error_code IS NULL) OR ((last_error_code = btrim(last_error_code)) AND (last_error_code <> ''::text) AND (last_error_code ~ '^[A-Z][A-Z0-9_]{0,127}$'::text)))),
    CONSTRAINT workflow_start_outbox_lease_owner_check CHECK (((lease_owner IS NULL) OR ((lease_owner = btrim(lease_owner)) AND (lease_owner <> ''::text) AND (octet_length(lease_owner) <= 256) AND (lease_owner !~ '[\r\n]'::text)))),
    CONSTRAINT workflow_start_outbox_status_check CHECK ((status = ANY (ARRAY['PENDING'::text, 'STARTED'::text, 'POISONED'::text]))),
    CONSTRAINT workflow_start_outbox_template_kind_check CHECK ((template_kind = ANY (ARRAY['TOPIC_ARTICLE'::text, 'MERGE_DOCUMENTS'::text, 'KNOWLEDGE_REPORT'::text, 'INTERVIEW_REVIEW'::text]))),
