--
-- Name: river_queue; Type: TABLE; Schema: workflow; Owner: -
--

CREATE TABLE workflow.river_queue (
    name text NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    metadata jsonb DEFAULT '{}'::jsonb NOT NULL,
    paused_at timestamp with time zone,
    updated_at timestamp with time zone DEFAULT CURRENT_TIMESTAMP NOT NULL
);


--
-- Name: run; Type: TABLE; Schema: workflow; Owner: -
--

CREATE TABLE workflow.run (
    id uuid NOT NULL,
    workspace_id uuid NOT NULL,
    definition_id uuid NOT NULL,
    status text NOT NULL,
    input jsonb DEFAULT '{}'::jsonb NOT NULL,
    output jsonb,
    version bigint DEFAULT 1 NOT NULL,
    created_at timestamp with time zone NOT NULL,
    updated_at timestamp with time zone NOT NULL,
    completed_at timestamp with time zone,
    idempotency_key text,
    request_hash text,
    pause_requested_at timestamp with time zone,
    cancel_requested_at timestamp with time zone,
    CONSTRAINT run_version_check CHECK ((version > 0)),
    CONSTRAINT workflow_run_completion_consistent CHECK ((((status = ANY (ARRAY['succeeded'::text, 'failed'::text, 'cancelled'::text])) AND (completed_at IS NOT NULL)) OR ((status <> ALL (ARRAY['succeeded'::text, 'failed'::text, 'cancelled'::text])) AND (completed_at IS NULL)))),
    CONSTRAINT workflow_run_control_requests_consistent CHECK (((NOT ((status = ANY (ARRAY['succeeded'::text, 'failed'::text])) AND ((pause_requested_at IS NOT NULL) OR (cancel_requested_at IS NOT NULL)))) AND (NOT ((status = 'cancelled'::text) AND (pause_requested_at IS NOT NULL))))),
    CONSTRAINT workflow_run_runtime_identity_pair CHECK ((((idempotency_key IS NULL) AND (request_hash IS NULL)) OR ((idempotency_key IS NOT NULL) AND (btrim(idempotency_key) <> ''::text) AND (char_length(idempotency_key) <= 128) AND (request_hash IS NOT NULL) AND (request_hash ~ '^[0-9a-f]{64}$'::text)))),
    CONSTRAINT workflow_run_status_check CHECK ((status = ANY (ARRAY['pending'::text, 'running'::text, 'waiting_for_human'::text, 'retry_wait'::text, 'paused'::text, 'succeeded'::text, 'failed'::text, 'cancelled'::text]))),
    CONSTRAINT workflow_run_updated_after_created CHECK ((updated_at >= created_at))
);


--
-- Name: tool_call; Type: TABLE; Schema: workflow; Owner: -
--

CREATE TABLE workflow.tool_call (
    id uuid NOT NULL,
    workspace_id uuid NOT NULL,
    workflow_run_id uuid NOT NULL,
    node_run_id uuid NOT NULL,
    node_attempt_id uuid NOT NULL,
    call_no smallint NOT NULL,
    requested_tool_name text NOT NULL,
    tool_version bigint,
    definition_hash text,
    input_schema_id text,
    input_schema_version bigint,
    output_schema_id text,
    output_schema_version bigint,
    capability text,
    side_effect_level text,
    invocation_policy text,
    idempotency_key text,
    request_hash text NOT NULL,
    request_bytes bigint NOT NULL,
    request_summary jsonb NOT NULL,
    response_hash text,
    response_bytes bigint DEFAULT 0 NOT NULL,
    response_summary jsonb,
    result_ref text,
    side_effect_type text,
    side_effect_id text,
    status text NOT NULL,
    error_code text,
    retryable boolean DEFAULT false NOT NULL,
    started_at timestamp with time zone NOT NULL,
    completed_at timestamp with time zone,
    duration_ms bigint DEFAULT 0 NOT NULL,
    version bigint DEFAULT 1 NOT NULL,
    CONSTRAINT tool_call_call_no_check CHECK ((call_no > 0)),
    CONSTRAINT tool_call_capability_check CHECK (((capability IS NULL) OR (capability = ANY (ARRAY['READ_LOCAL'::text, 'READ_EXTERNAL'::text, 'WRITE_PROPOSAL'::text, 'WRITE_KNOWLEDGE'::text, 'GIT_WRITE'::text, 'INDEX_MAINTENANCE'::text, 'EVALUATION_RUN'::text])))),
    CONSTRAINT tool_call_check CHECK (((side_effect_id IS NULL) OR ((side_effect_id = btrim(side_effect_id)) AND (((side_effect_type = 'web_fetch'::text) AND (side_effect_id ~ '^[0-9a-f]{64}$'::text)) OR ((side_effect_type <> 'web_fetch'::text) AND (side_effect_id ~ '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'::text)))))),
    CONSTRAINT tool_call_definition_hash_check CHECK (((definition_hash IS NULL) OR (definition_hash ~ '^[0-9a-f]{64}$'::text))),
    CONSTRAINT tool_call_duration_ms_check CHECK ((duration_ms >= 0)),
    CONSTRAINT tool_call_error_code_check CHECK (((error_code IS NULL) OR (error_code ~ '^[A-Z][A-Z0-9_]{0,127}$'::text))),
    CONSTRAINT tool_call_idempotency_key_check CHECK (((idempotency_key IS NULL) OR ((idempotency_key = btrim(idempotency_key)) AND (idempotency_key <> ''::text) AND (octet_length(idempotency_key) <= 128) AND (idempotency_key !~ '[\r\n]'::text)))),
    CONSTRAINT tool_call_input_schema_id_check CHECK (((input_schema_id IS NULL) OR (input_schema_id ~ '^[a-z][a-z0-9_.-]{0,127}$'::text))),
    CONSTRAINT tool_call_input_schema_version_check CHECK (((input_schema_version IS NULL) OR (input_schema_version > 0))),
    CONSTRAINT tool_call_invocation_policy_check CHECK (((invocation_policy IS NULL) OR (invocation_policy = ANY (ARRAY['MODEL_REQUESTABLE'::text, 'TRUSTED_WORKFLOW_ONLY'::text])))),
    CONSTRAINT tool_call_output_schema_id_check CHECK (((output_schema_id IS NULL) OR (output_schema_id ~ '^[a-z][a-z0-9_.-]{0,127}$'::text))),
    CONSTRAINT tool_call_output_schema_version_check CHECK (((output_schema_version IS NULL) OR (output_schema_version > 0))),
    CONSTRAINT tool_call_request_bytes_check CHECK (((request_bytes > 0) AND (request_bytes <= 16777216))),
    CONSTRAINT tool_call_request_hash_check CHECK ((request_hash ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT tool_call_request_summary_check CHECK (((jsonb_typeof(request_summary) = 'object'::text) AND (octet_length((request_summary)::text) <= 16384))),
    CONSTRAINT tool_call_requested_tool_name_check CHECK ((requested_tool_name ~ '^[A-Z][A-Za-z0-9]{0,63}$'::text)),
    CONSTRAINT tool_call_response_bytes_check CHECK (((response_bytes >= 0) AND (response_bytes <= 16777216))),
    CONSTRAINT tool_call_response_hash_check CHECK (((response_hash IS NULL) OR (response_hash ~ '^[0-9a-f]{64}$'::text))),
    CONSTRAINT tool_call_response_summary_check CHECK (((response_summary IS NULL) OR ((jsonb_typeof(response_summary) = 'object'::text) AND (octet_length((response_summary)::text) <= 16384)))),
    CONSTRAINT tool_call_result_ref_check CHECK (((result_ref IS NULL) OR ((result_ref = btrim(result_ref)) AND (result_ref <> ''::text) AND (octet_length(result_ref) <= 512) AND (result_ref !~ '[\r\n]'::text) AND ((result_ref ~ '^(index-version|source-span|writeback-execution|reindex-delivery|evaluation-run):[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'::text) OR (result_ref ~ '^(citation-batch|web-content):[0-9a-f]{64}$'::text) OR (result_ref ~ '^git-head:([0-9a-f]{40}|[0-9a-f]{64})$'::text) OR (result_ref ~ '^diff:[0-9a-f]{64}:[0-9a-f]{64}$'::text))))),
    CONSTRAINT tool_call_side_effect_level_check CHECK (((side_effect_level IS NULL) OR (side_effect_level = ANY (ARRAY['NONE'::text, 'EXTERNAL_READ'::text, 'DOMAIN_WRITE'::text, 'IRREVERSIBLE_OR_UNKNOWN'::text])))),
    CONSTRAINT tool_call_side_effect_type_check CHECK (((side_effect_type IS NULL) OR (side_effect_type = ANY (ARRAY['writeback_execution'::text, 'reindex_delivery'::text, 'evaluation_run'::text, 'web_fetch'::text])))),
    CONSTRAINT tool_call_status_check CHECK ((status = ANY (ARRAY['STARTED'::text, 'SUCCEEDED'::text, 'FAILED'::text, 'REFUSED'::text, 'UNKNOWN'::text]))),
    CONSTRAINT tool_call_tool_version_check CHECK (((tool_version IS NULL) OR (tool_version > 0))),
    CONSTRAINT tool_call_version_check CHECK ((version > 0)),
    CONSTRAINT workflow_tool_call_contract_complete CHECK ((((tool_version IS NULL) AND (definition_hash IS NULL) AND (input_schema_id IS NULL) AND (input_schema_version IS NULL) AND (output_schema_id IS NULL) AND (output_schema_version IS NULL) AND (capability IS NULL) AND (side_effect_level IS NULL) AND (invocation_policy IS NULL) AND (status = 'REFUSED'::text)) OR ((tool_version IS NOT NULL) AND (definition_hash IS NOT NULL) AND (input_schema_id IS NOT NULL) AND (input_schema_version IS NOT NULL) AND (output_schema_id IS NOT NULL) AND (output_schema_version IS NOT NULL) AND (side_effect_level IS NOT NULL) AND (invocation_policy IS NOT NULL) AND ((capability IS NOT NULL) OR ((requested_tool_name = 'CalculateDiff'::text) AND (side_effect_level = 'NONE'::text)))))),
    CONSTRAINT workflow_tool_call_idempotency_required CHECK (((status = 'REFUSED'::text) OR (side_effect_level <> ALL (ARRAY['DOMAIN_WRITE'::text, 'IRREVERSIBLE_OR_UNKNOWN'::text])) OR (idempotency_key IS NOT NULL))),
    CONSTRAINT workflow_tool_call_invocation_safety CHECK (((invocation_policy IS NULL) OR (invocation_policy <> 'MODEL_REQUESTABLE'::text) OR (side_effect_level <> ALL (ARRAY['DOMAIN_WRITE'::text, 'IRREVERSIBLE_OR_UNKNOWN'::text])))),
    CONSTRAINT workflow_tool_call_lifecycle CHECK ((((completed_at IS NULL) OR (completed_at >= started_at)) AND (((status = 'STARTED'::text) AND (completed_at IS NULL) AND (duration_ms = 0) AND (error_code IS NULL) AND (NOT retryable) AND (response_hash IS NULL) AND (response_bytes = 0) AND (response_summary IS NULL) AND (result_ref IS NULL) AND ((side_effect_type IS NULL) OR ((invocation_policy = 'TRUSTED_WORKFLOW_ONLY'::text) AND (side_effect_level = 'DOMAIN_WRITE'::text) AND (side_effect_type = 'writeback_execution'::text)))) OR ((status = 'SUCCEEDED'::text) AND (completed_at IS NOT NULL) AND (error_code IS NULL) AND (NOT retryable) AND (((response_hash IS NOT NULL) AND (response_bytes > 0) AND (response_summary IS NOT NULL)) OR (result_ref IS NOT NULL))) OR ((status = 'FAILED'::text) AND (completed_at IS NOT NULL) AND (error_code IS NOT NULL) AND (response_hash IS NULL) AND (response_bytes = 0) AND (response_summary IS NULL) AND (result_ref IS NULL)) OR ((status = 'REFUSED'::text) AND (completed_at IS NOT NULL) AND (error_code IS NOT NULL) AND (NOT retryable) AND (response_hash IS NULL) AND (response_bytes = 0) AND (response_summary IS NULL) AND (result_ref IS NULL) AND (side_effect_type IS NULL)) OR ((status = 'UNKNOWN'::text) AND (completed_at IS NOT NULL) AND (error_code IS NOT NULL) AND (NOT retryable) AND (response_hash IS NULL) AND (response_bytes = 0) AND (response_summary IS NULL) AND (result_ref IS NULL))))),
    CONSTRAINT workflow_tool_call_response_bundle CHECK ((((response_hash IS NULL) AND (response_bytes = 0) AND (response_summary IS NULL)) OR ((response_hash IS NOT NULL) AND (response_bytes > 0) AND (response_summary IS NOT NULL)))),
    CONSTRAINT workflow_tool_call_side_effect_pair CHECK (((side_effect_type IS NULL) = (side_effect_id IS NULL)))
);


--
-- Name: tool_result_receipt; Type: TABLE; Schema: workflow; Owner: -
--

CREATE TABLE workflow.tool_result_receipt (
    id uuid NOT NULL,
    tool_call_id uuid NOT NULL,
    workspace_id uuid NOT NULL,
    workflow_run_id uuid NOT NULL,
    node_run_id uuid NOT NULL,
    node_attempt_id uuid NOT NULL,
    tool_name text NOT NULL,
    tool_version bigint NOT NULL,
    output_schema_id text NOT NULL,
    output_schema_version bigint NOT NULL,
    definition_hash text NOT NULL,
    persistence_policy text NOT NULL,
    max_output_bytes bigint NOT NULL,
    max_private_binding_bytes bigint NOT NULL,
    output_document bytea NOT NULL,
    output_hash text NOT NULL,
    output_bytes bigint NOT NULL,
    server_binding_schema_id text,
    server_binding_schema_version bigint,
    server_binding_document bytea,
    server_binding_hash text,
    server_binding_bytes bigint,
    created_at timestamp with time zone NOT NULL,
    CONSTRAINT tool_result_receipt_binding_integrity CHECK ((((server_binding_schema_id IS NULL) AND (server_binding_schema_version IS NULL) AND (server_binding_document IS NULL) AND (server_binding_hash IS NULL) AND (server_binding_bytes IS NULL)) OR ((server_binding_schema_id IS NOT NULL) AND (server_binding_schema_version IS NOT NULL) AND (server_binding_document IS NOT NULL) AND (server_binding_hash IS NOT NULL) AND (server_binding_bytes IS NOT NULL) AND (server_binding_bytes = octet_length(server_binding_document)) AND ((server_binding_bytes >= 1) AND (server_binding_bytes <= max_private_binding_bytes)) AND (server_binding_hash = encode(sha256(server_binding_document), 'hex'::text))))),
    CONSTRAINT tool_result_receipt_definition_hash_check CHECK ((definition_hash ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT tool_result_receipt_exact_contract CHECK ((((tool_name = 'ReadGitStatus'::text) AND (tool_version = 2) AND (definition_hash = 'b5dd1fcca72d5bb41fd9ad3f74006d3706e4184ad39e2a3409b565d1ff896bbd'::text) AND (output_schema_id = 'tool.read_git_status.output'::text) AND (output_schema_version = 1) AND (max_output_bytes = 4096) AND (max_private_binding_bytes = 1024) AND ((server_binding_schema_id IS NULL) OR ((server_binding_schema_id = 'tool.read_git_status.private_binding'::text) AND (server_binding_schema_version = 1)))) OR ((tool_name = 'SearchKnowledge'::text) AND (tool_version = 2) AND (definition_hash = 'db7180086adb06a18a4be8d1eb80a208fa6385c70f1a71d6d67c4f263fbd1807'::text) AND (output_schema_id = 'tool.search_knowledge.output'::text) AND (output_schema_version = 2) AND (max_output_bytes = 32768) AND (max_private_binding_bytes = 16384) AND (server_binding_schema_id = 'tool.search_knowledge.private_binding'::text) AND (server_binding_schema_version = 1)) OR ((tool_name = 'ReadSource'::text) AND (tool_version = 3) AND (definition_hash = 'd41dabac535261b885e453b64e11fe5bb779838e31a255aea4798e27ead54d32'::text) AND (output_schema_id = 'tool.read_source.output'::text) AND (output_schema_version = 2) AND (max_output_bytes = 8192) AND (max_private_binding_bytes = 4096) AND (server_binding_schema_id = 'tool.read_source.private_binding'::text) AND (server_binding_schema_version = 1)) OR ((tool_name = 'ValidateCitation'::text) AND (tool_version = 3) AND (definition_hash = 'bf5e643c47d57478b46d258eca250dc30e810ee7a0693569f44edaab19037d54'::text) AND (output_schema_id = 'tool.validate_citation.output'::text) AND (output_schema_version = 2) AND (max_output_bytes = 16384) AND (max_private_binding_bytes = 16384) AND (server_binding_schema_id = 'tool.validate_citation.private_binding'::text) AND (server_binding_schema_version = 1)) OR ((tool_name = 'ReadGitStatus'::text) AND (tool_version = 3) AND (definition_hash = '2aa8ae138367486c4f59e1459a47c9a86f3adca78a0d5c3305849fe7f68a6e19'::text) AND (output_schema_id = 'tool.read_git_status.output'::text) AND (output_schema_version = 1) AND (max_output_bytes = 4096) AND (max_private_binding_bytes = 1024) AND ((server_binding_schema_id IS NULL) OR ((server_binding_schema_id = 'tool.read_git_status.private_binding'::text) AND (server_binding_schema_version = 1)))) OR ((tool_name = 'SearchKnowledge'::text) AND (tool_version = 3) AND (definition_hash = 'cb3f96130645ebafc8500d6a54685a073f6b75d622f1348f194c8e88f871d832'::text) AND (output_schema_id = 'tool.search_knowledge.output'::text) AND (output_schema_version = 3) AND (max_output_bytes = 32768) AND (max_private_binding_bytes = 16384) AND ((server_binding_schema_id = 'tool.search_knowledge.private_binding'::text) AND (server_binding_schema_version = 2))) OR ((tool_name = 'ReadSource'::text) AND (tool_version = 4) AND (definition_hash = 'c6d5ffdc62d1837c3ca728a862bfc1968fc553cfe0493827e51d942abab8182c'::text) AND (output_schema_id = 'tool.read_source.output'::text) AND (output_schema_version = 3) AND (max_output_bytes = 8192) AND (max_private_binding_bytes = 4096) AND ((server_binding_schema_id = 'tool.read_source.private_binding'::text) AND (server_binding_schema_version = 2))) OR ((tool_name = 'ValidateCitation'::text) AND (tool_version = 4) AND (definition_hash = '037f389043481ef4b5f8344d4ff35b4a032b1646adc03e7afff98418ac6f3333'::text) AND (output_schema_id = 'tool.validate_citation.output'::text) AND (output_schema_version = 3) AND (max_output_bytes = 16384) AND (max_private_binding_bytes = 16384) AND ((server_binding_schema_id = 'tool.validate_citation.private_binding'::text) AND (server_binding_schema_version = 2))))),
    CONSTRAINT tool_result_receipt_output_hash_check CHECK ((output_hash ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT tool_result_receipt_output_integrity CHECK (((output_bytes = octet_length(output_document)) AND ((output_bytes >= 1) AND (output_bytes <= max_output_bytes)) AND (output_hash = encode(sha256(output_document), 'hex'::text)))),
    CONSTRAINT tool_result_receipt_persistence_policy_check CHECK ((persistence_policy = 'PERSIST_CANONICAL'::text)),
    CONSTRAINT tool_result_receipt_server_binding_hash_check CHECK (((server_binding_hash IS NULL) OR (server_binding_hash ~ '^[0-9a-f]{64}$'::text)))
);


--
-- Name: tool_result_receipt_failure; Type: TABLE; Schema: workflow; Owner: -
--

CREATE TABLE workflow.tool_result_receipt_failure (
    id uuid NOT NULL,
    tool_call_id uuid NOT NULL,
    operation_id uuid NOT NULL,
    analysis_run_id uuid NOT NULL,
    workspace_id uuid NOT NULL,
    workflow_run_id uuid NOT NULL,
    node_run_id uuid NOT NULL,
    node_attempt_id uuid NOT NULL,
    failure_code text NOT NULL,
    expected_output_hash text NOT NULL,
    observed_output_hash text,
    observed_output_bytes bigint,
    observed_binding_hash text,
    observed_binding_bytes bigint,
    validator_version bigint NOT NULL,
    checked_at timestamp with time zone NOT NULL,
    created_at timestamp with time zone NOT NULL,
    CONSTRAINT tool_result_receipt_failure_check CHECK ((created_at >= checked_at)),
    CONSTRAINT tool_result_receipt_failure_expected_output_hash_check CHECK ((expected_output_hash ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT tool_result_receipt_failure_failure_code_check CHECK ((failure_code = ANY (ARRAY['MISSING'::text, 'HASH_MISMATCH'::text, 'CONTRACT_INVALID'::text, 'BINDING_INVALID'::text]))),
    CONSTRAINT tool_result_receipt_failure_observed_binding_bytes_check CHECK (((observed_binding_bytes IS NULL) OR (observed_binding_bytes >= 0))),
    CONSTRAINT tool_result_receipt_failure_observed_binding_hash_check CHECK (((observed_binding_hash IS NULL) OR (observed_binding_hash ~ '^[0-9a-f]{64}$'::text))),
    CONSTRAINT tool_result_receipt_failure_observed_output_bytes_check CHECK (((observed_output_bytes IS NULL) OR (observed_output_bytes >= 0))),
    CONSTRAINT tool_result_receipt_failure_observed_output_hash_check CHECK (((observed_output_hash IS NULL) OR (observed_output_hash ~ '^[0-9a-f]{64}$'::text))),
    CONSTRAINT tool_result_receipt_failure_shape CHECK ((((failure_code = 'MISSING'::text) AND (observed_output_hash IS NULL) AND (observed_output_bytes IS NULL) AND (observed_binding_hash IS NULL) AND (observed_binding_bytes IS NULL)) OR ((failure_code = 'HASH_MISMATCH'::text) AND (observed_output_hash IS NOT NULL) AND (observed_output_hash <> expected_output_hash) AND (observed_output_bytes IS NOT NULL) AND (observed_binding_hash IS NULL) AND (observed_binding_bytes IS NULL)) OR ((failure_code = 'CONTRACT_INVALID'::text) AND (observed_output_hash = expected_output_hash) AND (observed_output_bytes IS NOT NULL) AND (observed_binding_hash IS NULL) AND (observed_binding_bytes IS NULL)) OR ((failure_code = 'BINDING_INVALID'::text) AND (observed_output_hash = expected_output_hash) AND (observed_output_bytes IS NOT NULL) AND (observed_binding_hash IS NOT NULL) AND (observed_binding_bytes IS NOT NULL)))),
    CONSTRAINT tool_result_receipt_failure_validator_version_check CHECK ((validator_version = 1))
);


